DARK_QSS = _build_base_qss()


import re

_STEP_HEADER_RE = re.compile(
    r'^\s*(?P<star>\u2605|\*)?\s*\[(?P<idx>[^\]]+)\]\s+(?P<title>.+?)'
    r'(?:\s{2,}\((?P<angles>alpha=[^)]*)\))?\s*$'
)
# Star marker accepts BOTH the Unicode star (used by the live HTML render)
# and a literal "*" (used by format_recipe_text's plain-text output, which
# is what PDF export actually parses) -- confirmed these differ by
# checking format_recipe_text directly; the Tk original's regex only
# handled its own text widget's "\u2605 " marker and would have silently
# failed to detect starred steps here.


def _parse_recipe_display_text(text: str):
    """Returns a list of (kind, payload) blocks:
      ("preamble", [line, ...])                                   -- title/metadata lines before step 1
      ("step", {"starred", "index", "title", "angles", "detail_lines"})
      ("warnings", [warning_text, ...])
      ("hand_edits", [hand_edit_text, ...])
    Ported from the Tk version verbatim (same block structure), just with
    the star-marker regex fix above, plus the hand-edits tally section
    (appended by _build_recipe_html after "WARNINGS", recognized here the
    same way so PDF export can render it too)."""
    lines = text.split("\n")
    blocks = []
    preamble, i, n = [], 0, len(lines)

    while i < n:
        line = lines[i]
        upper = line.strip().upper()
        if upper.startswith("WARNINGS") or upper.startswith("HAND-EDITED VALUES"):
            break
        m = _STEP_HEADER_RE.match(line)
        if m and line.lstrip().startswith(("[", "\u2605", "*")):
            break
        preamble.append(line)
        i += 1
    blocks.append(("preamble", [l for l in preamble if l.strip()]))

    current_step = None
    in_warnings = in_hand_edits = False
    warnings, hand_edits = [], []
    while i < n:
        line = lines[i]
        stripped = line.strip()
        upper = stripped.upper()
        if upper.startswith("WARNINGS"):
            if current_step:
                blocks.append(("step", current_step))
                current_step = None
            in_warnings, in_hand_edits = True, False
            i += 1
            continue
        if upper.startswith("HAND-EDITED VALUES"):
            if current_step:
                blocks.append(("step", current_step))
                current_step = None
            in_warnings, in_hand_edits = False, True
            i += 1
            continue
        if stripped and set(stripped) == {"-"}:
            # separator rule ("---...") -- not real content in any section
            i += 1
            continue
        m = None if (in_warnings or in_hand_edits) else _STEP_HEADER_RE.match(line)
        if m and line.lstrip().startswith(("[", "\u2605", "*")):
            if current_step:
                blocks.append(("step", current_step))
            current_step = {
                "starred": bool(m.group("star")),
                "index": m.group("idx"),
                "title": m.group("title").strip(),
                "angles": m.group("angles"),
                "detail_lines": [],
            }
        elif in_hand_edits:
            if stripped:
                hand_edits.append(stripped.lstrip("-\u2022").strip())
        elif in_warnings:
            if stripped:
                warnings.append(stripped.lstrip("-\u2022").strip())
        elif current_step is not None and stripped:
            current_step["detail_lines"].append(stripped)
        i += 1

    if current_step:
        blocks.append(("step", current_step))
    if warnings:
        blocks.append(("warnings", warnings))
    if hand_edits:
        blocks.append(("hand_edits", hand_edits))
    return blocks


# ----------------------------------------------------------------------
# Recipe hand-edit field registry -- lets
# a user hand-edit specific process values directly on an already-
# generated recipe step (deterministic or AI-adopted), with a visible
# highlight + tally. RecipeStep.detail is a single opaque pre-formatted
# string (recipe_generator.py's detail-builder functions bake DesignParameters
# fields into it as plain f-strings with no field-boundary markers left
# behind), so rather than re-deriving detail text from scratch -- which
# would need every call-site-specific argument (mill group index,
# whether a deposition sub-step owns the e-gun ramp, its target
# thickness) reconstructed from context -- each entry below finds and
# replaces its OWN already-formatted numeral directly inside the
# ALREADY-GENERATED text via a regex anchored to that exact formatting.
# This only ever touches the ONE step being edited, so two mill steps
# that happen to share a global DesignParameters value (e.g. the same
# beam voltage for every mill group) are NOT forced to stay in lockstep
# -- consistent with genuinely independent per-step values, matching the
# "Hand Edited: <field> for step <N>" phrasing (one step per
# edit, not "every step that logically shares this parameter").
def _hand_edit_is_mill_step(step) -> bool:
    return step.category == "mill"


def _hand_edit_is_oxidation_step(step) -> bool:
    return step.category != "mill" and "oxidation" in (step.detail or "").lower()


def _hand_edit_is_ti_gather_step(step) -> bool:
    # Fixes a bug: a Ti-gather step's real category is "prep" (see
    # generate_recipe_steps in recipe_generator.py), not "deposition" -- an
    # earlier version of this check required category == "deposition"
    # and so could never actually match a Ti-gather step. Detail-text
    # keyword matching alone is what actually distinguishes it.
    detail_lower = (step.detail or "").lower()
    return "titanium" in detail_lower or "\\ti " in detail_lower


def _hand_edit_is_metal_deposition_step(step) -> bool:
    return step.category == "deposition" and not _hand_edit_is_ti_gather_step(step)


# (field_name, human label, unit, applies_fn, regex-with-one-capture-group, format_fn)
# field_name matches the DesignParameters attribute Settings > Process
# Parameters already edits, so the Settings tree and this per-step panel
# describe the same underlying process vocabulary.
_HAND_EDIT_FIELD_SPECS = [
    ("mill_beam_voltage_v", "Beam voltage", "V", _hand_edit_is_mill_step,
     re.compile(r"Ion Beam V=([\d.]+)V"), lambda v: f"{v:g}"),
    ("mill_beam_current_ma", "Beam current", "mA", _hand_edit_is_mill_step,
     re.compile(r"I=([\d.]+)mA"), lambda v: f"{v:.1f}"),
    ("mill_accel_voltage_v", "Accel voltage", "V", _hand_edit_is_mill_step,
     re.compile(r"Vacc=([\d.]+)V"), lambda v: f"{v:g}"),
    ("mill_ar_gas_sccm", "Ar gas flow", "sccm", _hand_edit_is_mill_step,
     re.compile(r"Ar Ion Gun Gas ([\d.]+)sccm"), lambda v: f"{v:g}"),
    ("mill_duration_min", "Mill duration", "min", _hand_edit_is_mill_step,
     re.compile(r"mill for ([\d.]+) min"), lambda v: f"{v:g}"),
    ("oxidation_pressure_mbar", "Oxidation pressure", "mBar", _hand_edit_is_oxidation_step,
     re.compile(r"Static Oxidation ([\d.]+) mBar, Static O2(?!\s*\()"), lambda v: f"{v:.2f}"),
    ("oxidation_time_min", "Oxidation time", "min", _hand_edit_is_oxidation_step,
     re.compile(r"Param wait ([\d.]+) min"), lambda v: f"{v:g}"),
    ("al_dep_rate_nmps", "Deposition rate", "nm/s", _hand_edit_is_metal_deposition_step,
     re.compile(r"Rate Control ([\d.]+)nm/s"), lambda v: f"{v:g}"),
    ("ti_gather_rate_nmps", "Ti gather rate", "nm/s", _hand_edit_is_ti_gather_step,
     re.compile(r"Rate Control ([\d.]+)nm/s"), lambda v: f"{v:g}"),
    ("ti_gather_duration_min", "Ti gather duration", "min", _hand_edit_is_ti_gather_step,
     re.compile(r"hold ([\d.]+):00"), lambda v: f"{v:g}"),
    # Total deposition thickness is one of
    # the parameters most likely to be changed by hand, since a process log
    # often tracks it per step. Unlike every field above, this one's number
    # echoes TWICE inside a deposition step's own .detail ("Target
    # thickness: X nm." from generate_recipe_steps itself, and "...cuts
    # shutter at X nm" from _deposition_ramp_detail) -- the shared regex
    # below matches both phrasings via alternation on one capture group,
    # and _apply_hand_edit_to_step/_highlight_field_in_detail/
    # _editable_detail_html were all generalized to find/replace/wrap
    # EVERY match a field's pattern finds in .detail, not just the first,
    # specifically so this field's two echoes never go out of sync. A
    # THIRD echo lives in step.title itself (recipe_generator.py's own
    # " -- Xnm" suffix, e.g. "Deposition #2 -- 50nm") -- that's a
    # different RecipeStep field entirely, so _apply_hand_edit_to_step
    # has its own dedicated title-rewrite for this one field name.
    ("target_thickness_nm", "Target thickness", "nm", _hand_edit_is_metal_deposition_step,
     re.compile(r"(?:Target thickness: |cuts shutter at )([\d.]+) nm"), lambda v: f"{v:g}"),
]

# A deposition step's TITLE (RecipeStep.title,
# a field entirely separate from .detail) carries its own independent
# " -- Xnm" thickness echo -- see generate_recipe_steps in recipe_generator.py.
# _apply_hand_edit_to_step uses this to keep the title in sync whenever
# "target_thickness_nm" is hand-edited, so the title never goes stale
# after only .detail is updated.
_TITLE_THICKNESS_RE = re.compile(r"( -- )([\d.]+)nm$")

# Sentinel pair wrapped around a hand-edited value's NEW formatted text,
# embedded directly in RecipeStep.detail -- survives both the HTML build
# (_build_recipe_html) and the plain-text build (format_recipe_text,
# which just echoes .detail verbatim) unchanged, since these are
# non-printable control characters no real recipe text ever contains.
# Each consumer (screen HTML, PDF, .txt) does its own final substitution
# of these two characters into whatever highlight markup it needs.
_HAND_EDIT_MARK_START = "\x01"
_HAND_EDIT_MARK_END = "\x02"

# Replaces the earlier "Hand-Edit Process
# Values" card, which is now gone: every hand-editable process value is
# a double-click target directly inside the rendered recipe text itself.
# Double-clicking one opens a small inline popup right where you clicked,
# pre-filled with the current value and fully selected, so backspacing
# and retyping it feels exactly like editing any other selected text --
# see _RecipeTextBrowser.mouseDoubleClickEvent and
# _on_recipe_hand_edit_anchor_double_clicked. These three sentinels mark
# where in a step's raw .detail text an editable value's clickable anchor
# needs to wrap around, encoding the field_name so the click handler
# knows which field was hit -- same non-printable-survives-html-escape
# trick _HAND_EDIT_MARK_START/_END already use, just two more control
# characters so a field name can ride along with its value.
_HAND_EDIT_LINK_START = "\x03"
_HAND_EDIT_LINK_SEP = "\x04"
_HAND_EDIT_LINK_END = "\x05"
_HAND_EDIT_LINK_RE = re.compile(
    _HAND_EDIT_LINK_START + r"(.*?)" + _HAND_EDIT_LINK_SEP + r"(.*?)" + _HAND_EDIT_LINK_END)

# Both _mill_detail's and the deposition sub-step's own detail text open
# with "alpha=X deg, theta=Y deg" (recipe_generator.py) -- see
# _apply_hand_edit_to_step's alpha/theta branch for why this needs its
# own regex separate from _HAND_EDIT_FIELD_SPECS.
_ALPHA_THETA_DETAIL_RE = re.compile(r"alpha=(-?[\d.]+) deg, theta=(-?[\d.]+) deg")


class _InlineHandEditPopup(QLineEdit):
    """A tiny borderless popup that opens right where the user double-
    clicked a hand-editable value in the rendered recipe text, so that
    value can be backspaced and retyped directly.
    A QTextBrowser is read-only by design (letting the whole
    rendered document be freely typed into would make it just as easy to
    mangle a label or a warning line as the one number that's actually
    supposed to change), so this opens a small real QLineEdit exactly at
    the click point instead -- pre-filled with the current value and
    fully selected, so the very next keystroke (Backspace, or just typing
    over the selection) replaces it, functionally identical to editing
    the text in place. Enter (or clicking/tabbing away) commits; Escape
    cancels with no change. An unparseable value flashes the border red
    and stays open for correction rather than silently discarding a
    genuine edit attempt."""
    def __init__(self, current_text: str, on_commit, parent=None):
        super().__init__(parent)
        self._on_commit = on_commit
        self._done = False
        self.setWindowFlags(Qt.Popup | Qt.FramelessWindowHint)
        self.setAttribute(Qt.WA_DeleteOnClose)
        self.setText(current_text)
        self.selectAll()
        self.setMinimumWidth(max(70, self.fontMetrics().horizontalAdvance(current_text) + 40))
        self._normal_style = (
            "QLineEdit { background-color: #2a2c38; color: #ffffff; "
            "border: 1px solid #7fb8ff; border-radius: 3px; padding: 3px 6px; "
            "font-family: monospace; font-size: 10pt; }")
        self._error_style = self._normal_style.replace("#7fb8ff", "#ff5c5c")
        self.setStyleSheet(self._normal_style)
        self.returnPressed.connect(self._on_return_pressed)

    def _finish(self, apply: bool):
        if self._done:
            return
        self._done = True
        if apply:
            self._on_commit(self.text())
        self.close()

    def _on_return_pressed(self):
        text = self.text().strip()
        try:
            float(text)
        except ValueError:
            self.setStyleSheet(self._error_style)
            self.selectAll()
            return  # keep the popup open so the user can correct it
        self._finish(True)

    def focusOutEvent(self, event):
        # Clicking/tabbing away commits a valid value (matches ordinary
        # inline-edit UX -- a spreadsheet cell, a rename field) but can't
        # keep an unfocused popup open for correction, so an invalid one
        # is just discarded rather than applied.
        text = self.text().strip()
        try:
            float(text)
            self._finish(True)
        except ValueError:
            self._finish(False)
        super().focusOutEvent(event)

    def keyPressEvent(self, event):
        if event.key() == Qt.Key_Escape:
            self._finish(False)
            return
        super().keyPressEvent(event)


class _HotkeyCaptureButton(QPushButton):
    """A push-button that, once clicked, listens for the very next real
    key press (with modifiers) and reports it back as a Qt PortableText
    key-sequence string (e.g. "Ctrl+Shift+D") instead of performing an
    ordinary click action -- the actual click-to-record
    hotkey-assignment mechanic used by Settings > Hotkeys
    (MainWindow._build_settings_hotkeys_section / hotkey_registry.py).

    Escape while listening, or the button losing focus, cancels the
    capture and restores whatever text was showing before -- nothing is
    applied unless a real (non-modifier-only) key is actually pressed
    while listening. This Escape-to-cancel is this widget's own local
    input convention (the same as any "record a shortcut" control),
    independent of whatever the app's own Deselect hotkey happens to be
    bound to."""
    key_captured = Signal(str)

    # Only these four are treated as "a modifier button was actually held" --
    # Qt also sets KeypadModifier for any key that came from a numeric
    # keypad and GroupSwitchModifier while AltGr is producing an accented
    # character on non-US keyboard layouts. Neither is a button the user
    # meant to bind; stripping them keeps a captured binding independent of
    # keyboard layout/hardware (a laptop with no numpad, a European
    # keyboard, etc.) -- see build_key_combo_text's docstring for the rest
    # of this fix.
    _REAL_MODIFIER_MASK = (
        Qt.ControlModifier | Qt.ShiftModifier | Qt.AltModifier | Qt.MetaModifier
    )

    def __init__(self, text: str = "", parent=None):
        super().__init__(text, parent)
        self._listening = False
        self._pre_listen_text = text
        self.setFocusPolicy(Qt.StrongFocus)
        self.setCursor(Qt.PointingHandCursor)
        self.clicked.connect(self._start_listening)

    def _start_listening(self):
        self._listening = True
        self._pre_listen_text = self.text()
        self.setText("Press a key…")
        self.setFocus(Qt.OtherFocusReason)

    def set_key_text(self, text: str):
        """Programmatic update (Clear/Reset elsewhere, or a redraw after
        another row's change) -- never emits key_captured, only an
        actual keypress capture does."""
        self._pre_listen_text = text
        if not self._listening:
            self.setText(text if text else "— none —")

    def event(self, ev):
        """Without this, pressing a combo that's currently bound to ANY
        live QAction in the app (Ctrl+D, Ctrl+S, Ctrl+Z, Del, ... -- most
        of the table, since reassigning a row to its own current key, or
        to a key some other row still holds, are both completely normal
        things to try) never reaches keyPressEvent at all: Qt's shortcut
        map intercepts a matching key combination at the ShortcutOverride
        stage, BEFORE normal key delivery, and fires that QAction instead
        -- regardless of which widget has focus. Accepting the
        ShortcutOverride event while listening tells Qt "this focused
        widget wants to handle the key itself," which is exactly how
        QLineEdit/QKeySequenceEdit already protect their own StandardKey
        bindings from being stolen the same way (see this class's and
        build_key_combo_text's docstrings) -- same mechanism, applied
        here so capture works no matter what the key is currently bound
        to."""
        if self._listening and ev.type() == QEvent.ShortcutOverride:
            ev.accept()
            return True
        return super().event(ev)

    def keyPressEvent(self, event):
        if not self._listening:
            super().keyPressEvent(event)
            return
        key = event.key()
        if key in (Qt.Key_Control, Qt.Key_Shift, Qt.Key_Alt, Qt.Key_Meta, Qt.Key_AltGr):
            return  # a bare modifier isn't a complete binding yet -- keep listening
        mods = event.modifiers() & self._REAL_MODIFIER_MASK
        if key == Qt.Key_Escape and mods == Qt.NoModifier:
            self._listening = False
            self.setText(self._pre_listen_text)
            return
        # Any number of Ctrl/Shift/Alt/Meta held together with `key` is
        # captured as one binding (e.g. Ctrl+Shift+Alt+A) -- see
        # hotkey_registry.build_key_combo_text for why this can't just be
        # `key | int(mods)` on PySide6/Qt6.
        text = hotkey_registry.build_key_combo_text(key, mods)
        self._listening = False
        self.setText(text if text else "— none —")
        self.key_captured.emit(text)

    def focusOutEvent(self, event):
        if self._listening:
            self._listening = False
            self.setText(self._pre_listen_text)
        super().focusOutEvent(event)


class _RecipeTextBrowser(QTextBrowser):
    """QTextBrowser subclass that turns a double-click on a hand-editable
    value's anchor (an `hedit:{step_index}:{field_name}` href -- see
    _build_recipe_html's _editable_detail_html) into an inline edit popup
    instead of the default double-click-selects-the-word behavior.
    Anything that ISN'T one of those anchors keeps completely normal
    QTextBrowser double-click behavior. Deliberately separate from the
    existing single-click `angle:` links (unaffected, still handled by
    anchorClicked/_on_recipe_angle_clicked) so a double-click's first
    click doesn't also trigger any single-click behavior on the same
    text."""
    hand_edit_anchor_double_clicked = Signal(str)  # emits the raw 'hedit:...' href

    def mouseDoubleClickEvent(self, event):
        href = self.anchorAt(event.pos())
        if href.startswith("hedit:"):
            self.hand_edit_anchor_double_clicked.emit(href)
            event.accept()
            return
        super().mouseDoubleClickEvent(event)


class _RecipeTreeWidget(QTreeWidget):
    """QTreeWidget subclass adding drag-and-drop MOVING of a Recipe
    Builder folder/recipe onto a different folder, so a recipe created in
    the wrong folder can be relocated directly instead of being
    reconstructed step-by-step in the correct one. A plain QTreeWidget's own built-in
    InternalMove drag mode only reparents the on-screen QTreeWidgetItem
    -- it has no idea the tree is also backed by a real
    recipe_builder_model.PlassysRecipeNode tree, so it would silently
    desync the visual tree from the actual saved data. Instead, this
    intercepts the drop, reports (dragged item, drop-target item) to
    `item_moved_callback` (wired to MainWindow._on_recipe_builder_tree_
    item_dropped, which performs the real move via
    recipe_builder_model.move_child and then fully rebuilds this widget
    from the model, the same way every other tree mutation already
    does) and never lets Qt's own default drop handling run, so there's
    only ever one path (the model) that decides what the tree actually
    looks like."""
    item_moved_callback = None  # set by MainWindow right after construction

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setDragEnabled(True)
        self.setAcceptDrops(True)
        self.setDropIndicatorShown(True)
        self.setDragDropMode(QAbstractItemView.InternalMove)

    def dropEvent(self, event):
        dragged_item = self.currentItem()
        pos = event.position().toPoint() if hasattr(event, "position") else event.pos()
        target_item = self.itemAt(pos)
        event.accept()  # always accept -- an invalid drop is reported to the callback as a
                          # no-op/warning, never left as a half-applied Qt-internal move
        if dragged_item is not None and self.item_moved_callback is not None:
            self.item_moved_callback(dragged_item, target_item)
        # Deliberately NOT calling super().dropEvent(event) -- Qt's own
        # InternalMove would reparent the QTreeWidgetItem on screen
        # without touching the underlying PlassysRecipeNode tree at all.
        # The callback above is the only thing that actually moves
        # anything; _recipe_builder_refresh_tree_widget() (called from
        # it) rebuilds this whole widget from the model afterward, which
        # is also what makes a REJECTED drop visually a no-op -- nothing
        # to undo since nothing was ever moved on screen in the first place.


class _AIWorkerSignals(QObject):
    """Thread-safe bridge for the background Ollama call: the actual
    network request runs in a plain threading.Thread (matching the Tk
    version's pattern, and avoiding pulling in QThread machinery for what
    is otherwise a simple call-and-return), and reports back through Qt
    signals -- PySide6 automatically queues a cross-thread signal
    emission onto the receiving (main) thread's event loop, so slots
    connected to these never touch widgets from the worker thread."""
    phase = Signal(str)
    progress = Signal(int)
    image_count = Signal(int)
    done = Signal(object, object)  # (result, error_str_or_None)
    answer_stream = Signal(str)    # Ask AI only: the full accumulated response text so far,
                                      # so the panel can show the model actually typing in real
                                      # time instead of just a "N chars written" status line


class _MeasurementVoiceSignals(QObject):
    """Thread-safe bridge for the background mic-listening loop (Measure
    Resistance) -- same pattern as _AIWorkerSignals above:
    SilenceSegmenter.listen() blocks, so it runs in a plain
    threading.Thread, and reports each transcribed utterance back
    through a Qt signal so the slot that updates the table only ever
    runs on the main thread."""
    utterance_ready = Signal(str)
    engine_error = Signal(str)


class _ResizeNotifyingWidget(QWidget):
    """A plain QWidget that also invokes an optional callback right
    after every resize -- used by the Create/Import tab to
    reposition its floating Design Warnings banner, which is a free-
    floating overlay child rather than a normal layout item (see
    _build_create_import_tab's own comment for why: a layout item's
    show/hide/resize used to reflow the whole tab, changing the preview
    canvas's own pixel geometry mid-drag and throwing off scale/rotate
    precision).
    Qt's own layout system repositions every LAYOUT-MANAGED child before
    dispatching resizeEvent to the parent, so by the time on_resize runs
    here, self.create_import_canvas.geometry() already reflects the new
    size -- exactly what the overlay needs to re-anchor itself against."""

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.on_resize = None

    def resizeEvent(self, event):
        super().resizeEvent(event)
        if self.on_resize is not None:
            self.on_resize()


class _ChamberPreviewWidget(QWidget):
    """Compact, reusable chamber-orientation view: the exact same
    wafer_orientation.compute_orientation + chamber_plotting.draw_top_down/
    draw_side_view functions the retired Live Angle Tester uses, wrapped
    behind one widget with a single update_orientation() call. Simulate Design
    (a live preview next to the angle controls) and Deposition Slideshow (the
    Deposition Slideshow, one instance per step) both use this instead
    of each re-wiring their own Figure/axes/canvas -- the retired tab that hosted it
    is left exactly as it is; this is a new, independent consumer of
    the same underlying chamber_plotting functions, not a refactor of it."""

    # Class-level registry so MainWindow._apply_theme() can retheme every
    # LIVE instance of this widget (there can be several at once --
    # Simulate Design's inline preview, one per Deposition Slideshow
    # step, and the Settings > Chamber Reference Model page) without each call site
    # having to separately track the ones it created. Entries for
    # instances that get destroyed are just skipped (RuntimeError) rather
    # than pruned -- this widget class is only ever created a handful of
    # times per session, so the unbounded list is not a real leak risk.
    _live_instances = []

    def __init__(self, figsize=(5.0, 2.1), show_readout=True, show_controls=True, compact=True, parent=None):
        super().__init__(parent)
        self._compact = compact  # False for the Settings > Chamber Reference Model page --
                                    # full Old-Tab-2-style detail (title, full labels, legend
                                    # captions) at a much larger figsize; True (default) for
                                    # every other embedded use, which needs the decluttered view
        self._themed_widgets = []       # this instance's own (widget, style_fn) pairs
        # A nice-looking but non-distracting
        # animation: a slow, continuously-looping idle animation (a
        # breathing glow + a traveling pulse dot, both drawn in chamber_plotting.py
        # off this phase value -- see draw_top_down/draw_side_view's own
        # `pulse_phase` docs) -- gated to only run while this widget is
        # actually visible (see showEvent/hideEvent below), so switching
        # away from whichever tab hosts it stops the redraws rather than
        # ticking a hidden canvas forever.
        self._pulse_phase = 0.0
        self._pulse_timer = QTimer(self)
        self._pulse_timer.setInterval(115)  # ~8.7 fps -- smooth enough for a slow, gentle motion,
                                              # cheap enough for up to 3 simultaneous small previews
        self._pulse_timer.timeout.connect(self._advance_pulse)
        # A mini version of the imported
        # junction, scaled small enough to fit on the wafer shape --
        # set via set_junction_overlay() (MainWindow pushes the current
        # design's own scaled-down polygons here on every _update_preview,
        # see _compute_mini_junction_overlay/_broadcast_chamber_junction_
        # overlay), then drawn on top of the wafer in draw_top_down using
        # the SAME o.rotation_matrix the wafer's own outline/ticks use --
        # never a separately-tracked orientation of its own.
        self._junction_overlay = None
        self._last_orientation_args = None  # (alpha_display, theta_display, reference) from the
                                               # most recent update_orientation() call, so retheme()
                                               # can force a redraw with the SAME data (never loses
                                               # or guesses at the currently-shown orientation)
        _ChamberPreviewWidget._live_instances.append(self)
        layout = QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(4)
        self.fig = Figure(figsize=figsize, dpi=100, facecolor=BG_COLOR)
        self.ax_top = self.fig.add_subplot(1, 2, 1)
        self.ax_side = self.fig.add_subplot(1, 2, 2)
        # Fixes a bug where the chamber model card was left visibly cut
        # off: right=0.98 left only a 2% figure margin past each
        # subplot's plotted area, which the "Mill"/"Ion Mill" label (drawn
        # in chamber_plotting.py just past the mill wedge, intentionally
        # overhanging the axes' own xlim -- see draw_top_down/
        # draw_side_view) barely fit inside at the widget's original
        # oversized figsize, and visibly clipped ("Mill" -> "M") once this
        # widget was correctly sized to actually fit its container (see
        # sim_chamber_preview below). More right margin gives that
        # overhanging label room to render in full at any figsize.
        self.fig.subplots_adjust(left=0.02, right=0.90, top=0.98, bottom=0.03, wspace=0.12)
        self.canvas = FigureCanvasQTAgg(self.fig)
        self.canvas.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
        layout.addWidget(self.canvas, stretch=1)
        # Deliberately NOT wired for scroll/pinch zoom -- the chamber
        # model is meant to stay a fixed, stagnant view.

        # Self-contained alpha/theta/reference controls, same free-typing
        # behavior as the retired Live Angle Tester -- a user can pull
        # the tilt away from whatever value seeded this widget (Active
        # alpha, a recipe step's committed alpha) to see what a DIFFERENT
        # tilt would look like, exactly like the retired Live Angle Tester always allowed.
        self.alpha_edit = None
        self.theta_edit = None
        self.reference_combo = None
        if show_controls:
            controls = QHBoxLayout()
            controls.setSpacing(4)
            for text in ("alpha:",):
                lbl = QLabel(text)
                self._themed(lbl, lambda: f"color: {DIM_COLOR}; font-size: 7.5pt;")
                controls.addWidget(lbl)
            self.alpha_edit = QLineEdit("30")
            self.alpha_edit.setFixedWidth(46)
            self.alpha_edit.textChanged.connect(self._on_controls_changed)
            controls.addWidget(self.alpha_edit)
            theta_lbl = QLabel("theta:")
            self._themed(theta_lbl, lambda: f"color: {DIM_COLOR}; font-size: 7.5pt;")
            controls.addWidget(theta_lbl)
            self.theta_edit = QLineEdit("0")
            self.theta_edit.setFixedWidth(46)
            self.theta_edit.textChanged.connect(self._on_controls_changed)
            controls.addWidget(self.theta_edit)
            self.reference_combo = QComboBox()
            self.reference_combo.addItem("Load ref", userData="load")
            self.reference_combo.addItem("Mill ref", userData="mill")
            self.reference_combo.addItem("Deposition ref", userData="deposition")
            self.reference_combo.setStyleSheet("font-size: 7.5pt;")
            self.reference_combo.currentIndexChanged.connect(self._on_controls_changed)
            controls.addWidget(self.reference_combo, stretch=1)
            layout.addLayout(controls)

        self.readout_label = None
        if show_readout:
            self.readout_label = QLabel("")
            # Fixes a bug where Simulate Design's chamber
            # model card was cut off: this single-line readout
            # (e.g. "alpha=-30.5 (deposition)  theta=-270.5  [load-eq
            # alpha=-30.5]") has no word-wrap, so its one-line sizeHint
            # was the ACTUAL element forcing the whole narrow sidebar
            # card wider than its panel -- not the figure canvas, which
            # was the first (necessary but insufficient) fix. Word-wrap
            # lets it drop to a second line instead of demanding width.
            self.readout_label.setWordWrap(True)
            self._themed(self.readout_label, lambda: f"color: {DIM_COLOR}; font-family: monospace; font-size: 7.5pt;")
            layout.addWidget(self.readout_label)

        if show_controls:
            self._redraw()
        else:
            self.show_placeholder("No orientation set yet.")

    def _on_controls_changed(self, *_args):
        self._redraw()

    def _themed(self, widget, style_fn):
        """Same non-destructive pattern as MainWindow._themed (see that
        method's docstring) -- applies style_fn() now and remembers it so
        retheme() can reapply it later without rebuilding this widget."""
        widget.setStyleSheet(style_fn())
        self._themed_widgets.append((widget, style_fn))
        return widget

    def retheme(self):
        """Called by MainWindow._apply_theme() for every live instance.
        Reapplies this widget's own themed label stylesheets, then forces
        a redraw using the last-known orientation (if any) so the
        matplotlib background/text colors pick up the new theme too --
        without inventing or losing any orientation data."""
        for widget, style_fn in self._themed_widgets:
            try:
                widget.setStyleSheet(style_fn())
            except RuntimeError:
                pass  # underlying Qt object already destroyed
        if self._last_orientation_args is not None:
            self.update_orientation(*self._last_orientation_args)
        else:
            self.fig.set_facecolor(BG_COLOR)
            for ax in (self.ax_top, self.ax_side):
                ax.set_facecolor(BG_COLOR)
            self.canvas.draw_idle()

    def showEvent(self, event):
        """Starts the idle-animation timer only while this widget is
        actually on screen -- there can be up to 3 of these alive at
        once (Simulate Design, Deposition Slideshow, Settings > Chamber
        Reference Model), and only one tab is ever visible at a time, so
        this keeps the other two from redrawing a hidden canvas for no
        reason. Also forces one redraw on reveal, in case
        set_junction_overlay() updated this instance's own data while it
        was hidden (that call itself skips redrawing while hidden -- see
        its own docstring)."""
        super().showEvent(event)
        if not self._pulse_timer.isActive():
            self._pulse_timer.start()
        if self._last_orientation_args is not None:
            self.update_orientation(*self._last_orientation_args)

    def hideEvent(self, event):
        self._pulse_timer.stop()
        super().hideEvent(event)

    def _advance_pulse(self):
        if not self.isVisible():  # belt-and-suspenders -- showEvent/hideEvent already gate the
            return                  # timer itself, this just avoids a wasted redraw in any edge
                                     # case where the timer outlives a hide (e.g. mid-teardown)
        self._pulse_phase = (self._pulse_phase + (2 * math.pi) * (self._pulse_timer.interval() / 1000.0)
                              / chamber_plotting.PULSE_CYCLE_SECONDS) % (2 * math.pi)
        if self._last_orientation_args is not None:
            self.update_orientation(*self._last_orientation_args)

    def set_junction_overlay(self, overlay):
        """Pushes the current design's own mini polygons (see
        MainWindow._compute_mini_junction_overlay) into this instance --
        called for every live _ChamberPreviewWidget from MainWindow.
        _broadcast_chamber_junction_overlay, itself called once per
        _update_preview cycle, so every chamber view always reflects
        whichever design is actually active, same as every other
        Simulate-tab element. `overlay` is None (nothing to draw -- an
        empty design) or a list of {"points": [...], "color": "#hex"}
        dicts, already normalized/centered by the caller. Skips the
        actual redraw while hidden (an inactive tab's chamber view would
        otherwise redraw on every single edit even though nobody can see
        it); showEvent above catches it up the moment it's revealed."""
        self._junction_overlay = overlay
        if self.isVisible() and self._last_orientation_args is not None:
            self.update_orientation(*self._last_orientation_args)

    def _redraw(self):
        """Reads this widget's own alpha/theta/reference controls and
        draws them -- the only path used when show_controls=True, so
        typing directly into the widget always wins once seeded."""
        if self.alpha_edit is None:
            return
        try:
            alpha = float(self.alpha_edit.text())
            theta = float(self.theta_edit.text())
        except ValueError:
            self.show_placeholder("Enter numeric alpha/theta to preview.")
            return
        reference = self.reference_combo.currentData() or "load"
        self.update_orientation(alpha, theta, reference=reference)

    def update_orientation(self, alpha_display: float, theta_display: float, reference: str = "load"):
        """Low-level draw -- computes and renders, does NOT touch this
        widget's own controls (use set_orientation for that). reference
        defaults to 'load', the same default the retired Live Angle
        Tester started on."""
        self._last_orientation_args = (alpha_display, theta_display, reference)
        orientation = compute_orientation(alpha_display, theta_display, reference=reference)
        self.fig.set_facecolor(BG_COLOR)  # re-reads the CURRENT theme color every draw, so a
                                             # light/dark toggle recolors this figure too, not just
                                             # whatever BG_COLOR was in effect at construction time
        draw_top_down(self.ax_top, orientation, compact=self._compact,
                      pulse_phase=self._pulse_phase, mini_junction=self._junction_overlay)
        draw_side_view(self.ax_side, orientation, compact=self._compact, pulse_phase=self._pulse_phase)
        self.canvas.draw_idle()
        if self.readout_label is not None:
            alpha_load = alpha_internal_to_display(orientation.alpha_internal, "load")
            self.readout_label.setText(
                f"alpha={alpha_display:g} ({reference})  theta={orientation.theta:g}  "
                f"[load-eq alpha={alpha_load:.1f}]"
            )
        return orientation

    def set_orientation(self, alpha_display: float, theta_display: float, reference: str = "load"):
        """Re-seeds this widget's own alpha/theta/reference controls to
        a new starting point (e.g. the Deposition Slideshow calling this
        on every step change) while leaving them fully editable
        afterward -- same as the retired Live Angle Tester's Jump to Load/Mill presets:
        they set the fields, the fields stay free-typed from there."""
        if self.alpha_edit is not None:
            for w in (self.alpha_edit, self.theta_edit, self.reference_combo):
                w.blockSignals(True)
            self.alpha_edit.setText(f"{alpha_display:g}")
            self.theta_edit.setText(f"{theta_display:g}")
            idx = self.reference_combo.findData(reference)
            if idx >= 0:
                self.reference_combo.setCurrentIndex(idx)
            for w in (self.alpha_edit, self.theta_edit, self.reference_combo):
                w.blockSignals(False)
        return self.update_orientation(alpha_display, theta_display, reference=reference)

    def set_alpha(self, alpha_display: float):
        """Updates only alpha (e.g. Simulate Design's Active alpha field
        changing) -- leaves whatever theta/reference the user has
        typed into this widget's own controls untouched."""
        if self.alpha_edit is not None:
            self.alpha_edit.blockSignals(True)
            self.alpha_edit.setText(f"{alpha_display:g}")
            self.alpha_edit.blockSignals(False)
            self._redraw()

    def show_placeholder(self, message: str):
        # Guards against a bug found while adding the idle-animation timer
        # above: _advance_pulse redraws off self._last_orientation_args
        # every tick, so leaving a stale value here would have the
        # animation quietly redraw the PREVIOUS orientation right back
        # over this placeholder ~9 times a second -- cleared so the
        # timer has nothing to redraw until a real orientation is set
        # again (via update_orientation/set_orientation).
        self._last_orientation_args = None
        for ax in (self.ax_top, self.ax_side):
            ax.clear()
            ax.set_facecolor(BG_COLOR)
            ax.axis("off")
        self.ax_top.text(0.5, 0.5, message, color=DIM_COLOR, fontsize=8, ha="center", va="center",
                         wrap=True, transform=self.ax_top.transAxes)
        self.canvas.draw_idle()
        if self.readout_label is not None:
            self.readout_label.setText("")


class _FrontPageBackdrop(QWidget):
    """Renders an SVG built fresh by svg_fn() (see _build_appicon_svg /
    _build_circuit_backdrop_svg) in "cover" mode: it always fills this
    widget's own rect exactly, cropping overflow rather than
    letterboxing, so a wide backdrop or a square icon both stay full-
    bleed at any widget size. Used for both the Front Page's icon mark
    and its hero backdrop -- same class, different svg_fn/size.

    Same non-destructive theming pattern as _ChamberPreviewWidget: a
    class-level registry of live instances so MainWindow._apply_theme()
    can call retheme() on each one (regenerate the SVG from the CURRENT
    color constants, repaint) without rebuilding any widget.

    An earlier version of this class scattered
    ~14 independent pulsing circles all over the hero as resonator waves
    throughout the background, which read as too busy for a calm, elegant
    look. Replaced with ONE calmer, more deliberate motif instead of
    many small ones:

    1. A single squiggly line -- meant to evoke a resonator's own
       meander trace -- follows the hero's perimeter a short margin in
       from the edges (like a quiet picture-frame), a gentle sine ripple
       riding along an otherwise rounded-rectangle path
       (_squiggle_points). Drawn once as a static, very dim trace
       regardless of animation state, so it still reads as "framing" even
       on the very first paint before any motion has happened.
    2. Two small glowing pulses continuously travel around that same
       perimeter path in opposite directions of the loop from one
       another (half a loop apart), each with a short fading trail --
       "a pulse trailing along the squiggle" -- rather than many
       independent flashing sources.
    3. A single, very faint diagonal sheen sweeps slowly across the
       whole backdrop on a long loop -- the same "verrrry
       slight" convention every other sheen in this file already uses
       (QuantumToggleButton/QuantumCard/QuantumAppIcon's own badge
       glaze), just at hero scale.

    The static circuit-trace SVG texture itself (_build_circuit_backdrop_svg)
    is completely unchanged underneath all of this."""

    _live_instances = []

    PERIMETER_MARGIN = 26.0
    SQUIGGLE_AMPLITUDE = 7.0
    SQUIGGLE_WAVELENGTH = 130.0
    SQUIGGLE_STEP = 5.0          # sample spacing along the perimeter, in px
    PULSE_SPEED = 70.0           # px/second traveled along the perimeter
    PULSE_TRAIL_LEN = 16
    PULSE_TRAIL_STEP = 2         # sample-index spacing between trail dots
    SHEEN_PERIOD = 9.0

    def __init__(self, svg_fn, parent=None):
        super().__init__(parent)
        self._svg_fn = svg_fn
        self._renderer = QSvgRenderer()
        self._time = 0.0
        self._timer = QTimer(self)
        self._timer.setInterval(50)  # ~20fps -- ambient/background, doesn't need full 30fps smoothness
        self._timer.timeout.connect(self._advance)
        self._squiggle_cache_size = None
        self._squiggle_points = []
        self._squiggle_length = 0.0
        _FrontPageBackdrop._live_instances.append(self)
        self.retheme()

    def retheme(self):
        self._renderer.load(QByteArray(self._svg_fn()))
        self.update()

    def showEvent(self, event):
        self._timer.start()
        super().showEvent(event)

    def hideEvent(self, event):
        self._timer.stop()
        super().hideEvent(event)

    def _advance(self):
        self._time += self._timer.interval() / 1000.0
        self.update()

    def _ensure_squiggle(self, w, h):
        """(Re)computes the perimeter squiggle polyline only when this
        widget's size has actually changed (a resize), not on every
        paint -- the point list stays valid across every frame in
        between since nothing else about the path depends on self._time."""
        if self._squiggle_cache_size == (w, h) and self._squiggle_points:
            return
        self._squiggle_cache_size = (w, h)
        margin = self.PERIMETER_MARGIN
        left, top, right, bottom = margin, margin, w - margin, h - margin
        if right <= left or bottom <= top:
            self._squiggle_points, self._squiggle_length = [], 0.0
            return
        edges = [
            ((left, top), (right, top), (0.0, -1.0)),
            ((right, top), (right, bottom), (1.0, 0.0)),
            ((right, bottom), (left, bottom), (0.0, 1.0)),
            ((left, bottom), (left, top), (-1.0, 0.0)),
        ]
        points = []
        s = 0.0
        for (x0, y0), (x1, y1), (nx, ny) in edges:
            seg_len = math.hypot(x1 - x0, y1 - y0)
            n_steps = max(2, int(seg_len / self.SQUIGGLE_STEP))
            for i in range(n_steps):
                t = i / n_steps
                bx, by = x0 + (x1 - x0) * t, y0 + (y1 - y0) * t
                offset = self.SQUIGGLE_AMPLITUDE * math.sin(2 * math.pi * s / self.SQUIGGLE_WAVELENGTH)
                points.append((bx + nx * offset, by + ny * offset))
                s += seg_len / n_steps
        self._squiggle_points = points
        self._squiggle_length = s

    def _draw_squiggle(self, painter):
        points = self._squiggle_points
        n = len(points)
        if n < 3 or self._squiggle_length <= 0:
            return

        base_color = QColor(BORDER_COLOR)
        base_color.setAlphaF(0.6)
        painter.setPen(QPen(base_color, 1.3))
        poly_path = QPainterPath()
        poly_path.moveTo(*points[0])
        for x, y in points[1:]:
            poly_path.lineTo(x, y)
        poly_path.closeSubpath()
        painter.setBrush(Qt.NoBrush)
        painter.drawPath(poly_path)

        # two pulses chasing each other around the loop, half a lap apart
        for pulse_offset in (0.0, self._squiggle_length / 2.0):
            head_s = (self._time * self.PULSE_SPEED + pulse_offset) % self._squiggle_length
            head_idx = int(round(head_s / self._squiggle_length * n)) % n
            for trail_i in range(self.PULSE_TRAIL_LEN):
                idx = (head_idx - trail_i * self.PULSE_TRAIL_STEP) % n
                fade = 1.0 - trail_i / self.PULSE_TRAIL_LEN
                color = QColor(ACCENT_COLOR)
                color.setAlphaF(0.75 * fade * fade)
                radius = 3.2 * fade + 0.6
                painter.setPen(Qt.NoPen)
                painter.setBrush(QBrush(color))
                painter.drawEllipse(QPointF(*points[idx]), radius, radius)

    def _draw_sheen(self, painter, w, h):
        if w <= 0 or h <= 0:
            return
        diag = math.hypot(w, h)
        frac = (self._time % self.SHEEN_PERIOD) / self.SHEEN_PERIOD
        band = diag * 0.16
        travel = diag + 2 * band
        pos = -band + frac * travel
        painter.save()
        painter.translate(w / 2.0, h / 2.0)
        painter.rotate(24)
        gradient = QLinearGradient(pos - travel / 2.0 - band / 2.0, 0, pos - travel / 2.0 + band / 2.0, 0)
        c_edge = QColor(ACCENT_COLOR)
        c_edge.setAlphaF(0.0)
        c_mid = QColor(ACCENT_COLOR)
        c_mid.setAlphaF(0.05)
        gradient.setColorAt(0.0, c_edge)
        gradient.setColorAt(0.5, c_mid)
        gradient.setColorAt(1.0, c_edge)
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(gradient))
        big = diag * 1.5
        painter.drawRect(QRectF(-big / 2.0, -big / 2.0, big, big))
        painter.restore()

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing)
        vb = self._renderer.viewBoxF()
        if vb.width() > 0 and vb.height() > 0 and self.width() > 0 and self.height() > 0:
            scale = max(self.width() / vb.width(), self.height() / vb.height())
            tw, th = vb.width() * scale, vb.height() * scale
            target = QRectF((self.width() - tw) / 2, (self.height() - th) / 2, tw, th)
        else:
            target = QRectF(self.rect())
        painter.setClipRect(self.rect())
        self._renderer.render(painter, target)
        self._ensure_squiggle(self.width(), self.height())
        self._draw_squiggle(painter)
        self._draw_sheen(painter, self.width(), self.height())
        painter.end()


class QuantumToggleButton(QPushButton):
    """A small, fully custom-painted checkable pill button in the app's
    own 'quantum blue' language -- built for the Create/Import tab's
    'Measurements: On/Off' toggle, whose stock QSS QPushButton read as
    a bland square to click on and off.
    Drop-in compatible with plain QPushButton for every call site this
    app already uses (setCheckable/setChecked/setCursor/setToolTip/
    setText/isChecked/the toggled signal) -- only the paint job and the
    hover/pulse animation are new, so swapping the construction call is
    the only change needed anywhere this is used.

    Four ingredients:
    1. A soft vertical body gradient plus a *very* faint diagonal sheen
       band (low, constant alpha -- "verrrry slight", not a glossy
       plastic highlight).
    2. A gentle hover expand/retract: the whole pill scales up to ~4.5%
       about its own center on enter, eases back on leave (QPropertyAnimation
       over a real Qt `hoverProgress` property, not a hard snap).
    3. Instead of a ruler glyph: a small live "resonance" waveform drawn
       to the left of the text -- flat and dim when idle, a gently
       oscillating pulse (driven by `_pulse_phase`) when hovered or
       checked, reading as "a live signal is being read" rather than a
       measuring tool sitting still.
    4. Two tiny Manhattan-routed circuit-trace stubs (line -> via dot ->
       terminal pad) extending a few px past each rounded end -- the
       EXACT SAME trace/via/pad visual vocabulary _build_circuit_backdrop_svg
       already uses for the Front Page hero, reused here instead of
       inventing a second decorative language, so this reads as "the
       same app". Each stub carries its own small traveling glow (a
       "trailing resonator" pulse) that ping-pongs out from the pill and
       fades, only animating while hovered or checked -- the QTimer
       driving it is started/stopped on demand, not left running idle.

    Off + idle: calm, dim, no traces, timer stopped (zero idle CPU cost).
    Off + hover: traces extend out and the pill brightens/grows slightly
    -- a "waking up" preview. On (checked): a persistent gentle pulse
    continues even without hover (measurements ARE live), dimmer than
    full hover. On + hover: full glow, full-length traces, brightest
    pulse.
    """

    TRACE_MARGIN = 13  # px of dead space reserved on each side of the pill for the trace stub

    def __init__(self, text="", parent=None):
        super().__init__(text, parent)
        self.setCheckable(True)
        self.setCursor(Qt.PointingHandCursor)
        self.setMouseTracking(True)
        self.setFlat(True)
        self.setAttribute(Qt.WA_Hover, True)
        self._hover_progress = 0.0   # 0..1, animated on enter/leave
        self._pulse_phase = 0.0      # radians, advanced by _pulse_timer while active
        self._hover_anim = QPropertyAnimation(self, b"hoverProgress", self)
        self._hover_anim.setDuration(170)
        self._hover_anim.setEasingCurve(QEasingCurve.OutCubic)
        self._pulse_timer = QTimer(self)
        self._pulse_timer.setInterval(33)  # ~30fps
        self._pulse_timer.timeout.connect(self._advance_pulse)
        self.toggled.connect(self._on_toggled_sync)
        self.setMinimumHeight(26)

    def _get_hover_progress(self):
        return self._hover_progress

    def _set_hover_progress(self, value):
        self._hover_progress = value
        self.update()

    hoverProgress = Property(float, _get_hover_progress, _set_hover_progress)

    def _on_toggled_sync(self, _checked):
        self._sync_pulse_timer()
        self.update()

    def _sync_pulse_timer(self):
        active = self.isChecked() or self.underMouse()
        if active and not self._pulse_timer.isActive():
            self._pulse_timer.start()
        elif not active and self._pulse_timer.isActive():
            self._pulse_timer.stop()

    def _advance_pulse(self):
        self._pulse_phase = (self._pulse_phase + 0.11) % (2 * math.pi)
        self.update()

    def enterEvent(self, event):
        self._hover_anim.stop()
        self._hover_anim.setStartValue(self._hover_progress)
        self._hover_anim.setEndValue(1.0)
        self._hover_anim.start()
        self._sync_pulse_timer()
        super().enterEvent(event)

    def leaveEvent(self, event):
        self._hover_anim.stop()
        self._hover_anim.setStartValue(self._hover_progress)
        self._hover_anim.setEndValue(0.0)
        self._hover_anim.start()
        self._sync_pulse_timer()
        super().leaveEvent(event)

    def sizeHint(self):
        base = super().sizeHint()
        # +2*TRACE_MARGIN for the trace stubs, +34 for the icon glyph/gap
        # and enough right-side clearance that text never clips against
        # the pill's own rounded cap (confirmed against a real render --
        # the original +20 left "Off"/"On" clipped to "Of"/"O").
        return QSize(base.width() + 2 * self.TRACE_MARGIN + 34, max(base.height(), 26))

    def _draw_trace_stub(self, painter, anchor, direction, length, phase, glow_color, dim_color, active):
        """One Manhattan-routed stub (line -> via -> pad), matching
        _build_circuit_backdrop_svg's own motif, extending `length` px
        from `anchor` in `direction` (+1 right, -1 left). A small bright
        dot travels out along it and fades -- the "trailing resonator"."""
        if length <= 0.5:
            return
        end_x = anchor.x() + direction * length
        y = anchor.y()
        line_color = QColor(glow_color if active else dim_color)
        line_color.setAlpha(190 if active else 90)
        painter.setPen(QPen(line_color, 1.3))
        painter.drawLine(QPointF(anchor.x(), y), QPointF(end_x, y))
        # via dot, partway out
        via_x = anchor.x() + direction * length * 0.55
        via_color = QColor(glow_color if active else dim_color)
        via_color.setAlpha(150 if active else 70)
        painter.setBrush(QBrush(via_color))
        painter.setPen(Qt.NoPen)
        painter.drawEllipse(QRectF(via_x - 1.1, y - 1.1, 2.2, 2.2))
        # terminal pad
        pad_color = QColor(glow_color if active else dim_color)
        pad_color.setAlpha(170 if active else 80)
        painter.setBrush(QBrush(pad_color))
        pad_size = 2.6
        painter.drawRect(QRectF(end_x - (0 if direction > 0 else pad_size), y - pad_size / 2, pad_size, pad_size))
        if not active:
            return
        # traveling pulse: fades in/out over one phase cycle, ping-ponging
        # outward from the pill toward the pad
        t = phase / (2 * math.pi)
        envelope = math.sin(math.pi * t)  # 0 at t=0/1, 1 at t=0.5
        if envelope <= 0.02:
            return
        pulse_x = anchor.x() + direction * length * t
        pulse_color = QColor(glow_color)
        pulse_color.setAlpha(int(210 * envelope))
        painter.setBrush(QBrush(pulse_color))
        r = 1.7 * envelope + 0.6
        painter.drawEllipse(QRectF(pulse_x - r, y - r, 2 * r, 2 * r))

    def _draw_pulse_glyph(self, painter, rect, active, checked, phase):
        """A small live-resonance waveform in place of a ruler icon --
        flat and dim at rest, gently oscillating while active. Reads as
        "a signal is being read", which is what this toggle actually
        controls."""
        cy = rect.center().y()
        color = QColor(ACCENT_COLOR if checked else DIM_COLOR)
        color.setAlpha(230 if active else 130)
        painter.setPen(QPen(color, 1.4))
        path = QPainterPath()
        n = 20
        amp = (2.6 if active else 0.5) * (1.0 if checked else 0.7)
        for i in range(n + 1):
            frac = i / n
            x = rect.left() + frac * rect.width()
            y = cy - amp * math.sin(frac * 2 * math.pi * 1.5 + phase)
            if i == 0:
                path.moveTo(x, y)
            else:
                path.lineTo(x, y)
        painter.drawPath(path)

    def paintEvent(self, event):
        checked = self.isChecked()
        hp = self._hover_progress
        active = checked or hp > 0.01

        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing)

        full = QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5)
        pill = full.adjusted(self.TRACE_MARGIN, 2, -self.TRACE_MARGIN, -2)
        if pill.width() < 10 or pill.height() < 10:
            painter.end()
            return
        radius = pill.height() / 2.0

        # --- trace stubs drawn first, UNDER the pill, in unscaled space
        # so they read as wires the pill sits on top of ---
        trace_len = (4.0 + 7.0 * hp) if not checked else (6.0 + 5.0 * hp)
        glow = QColor(ACCENT_COLOR)
        mid_y = pill.center().y()
        self._draw_trace_stub(painter, QPointF(pill.left(), mid_y),
                               -1, trace_len, self._pulse_phase, glow, BORDER_COLOR, active)
        self._draw_trace_stub(painter, QPointF(pill.right(), mid_y),
                               1, trace_len, self._pulse_phase + math.pi, glow, BORDER_COLOR, active)

        # --- hover expand/retract: scale the pill (and its contents)
        # about its own center by a few percent ---
        scale = 1.0 + 0.045 * hp
        painter.save()
        center = pill.center()
        painter.translate(center)
        painter.scale(scale, scale)
        painter.translate(-center)

        path = QPainterPath()
        path.addRoundedRect(pill, radius, radius)

        grad = QLinearGradient(pill.topLeft(), pill.bottomLeft())
        if checked:
            grad.setColorAt(0.0, QColor(39, 71, 102))
            grad.setColorAt(1.0, QColor(21, 34, 51))
        else:
            base = QColor(HOVER_COLOR).lighter(103 + int(6 * hp))
            grad.setColorAt(0.0, base)
            grad.setColorAt(1.0, QColor(PANEL_COLOR))
        painter.fillPath(path, QBrush(grad))

        # glow ring -- NoBrush is essential here: drawPath() fills with
        # whatever brush the painter currently holds, which by this point
        # is still the terminal-pad brush the trace stubs left behind
        # above; without this the ring stroke silently re-fills the whole
        # pill with that leftover opaque color, drowning out the gradient
        # fill just painted.
        ring = QColor(ACCENT_COLOR)
        ring_alpha = (95 if checked else 40) + int(110 * hp)
        ring.setAlpha(min(ring_alpha, 235))
        painter.setPen(QPen(ring, 1.3))
        painter.setBrush(Qt.NoBrush)
        painter.drawPath(path)

        # very slight sheen -- a soft diagonal highlight band, low constant alpha
        painter.save()
        painter.setClipPath(path)
        sheen = QLinearGradient(pill.topLeft(), pill.bottomRight())
        sheen_alpha = 14 + int(8 * hp)
        sheen.setColorAt(0.0, QColor(255, 255, 255, sheen_alpha))
        sheen.setColorAt(0.30, QColor(255, 255, 255, 0))
        sheen.setColorAt(1.0, QColor(255, 255, 255, 0))
        painter.fillPath(path, QBrush(sheen))
        painter.restore()

        # icon glyph + text
        icon_w = 20
        icon_rect = QRectF(pill.left() + 9, pill.top(), icon_w, pill.height())
        self._draw_pulse_glyph(painter, icon_rect, active, checked, self._pulse_phase)

        text_color = QColor(TEXT_COLOR if checked else DIM_COLOR)
        painter.setPen(text_color)
        f = QFont(self.font())
        painter.setFont(f)
        text_rect = QRectF(icon_rect.right() + 4, pill.top(), pill.right() - icon_rect.right() - 16, pill.height())
        painter.drawText(text_rect, Qt.AlignVCenter | Qt.AlignLeft, self.text())

        painter.restore()
        painter.end()


class QuantumToolButton(QToolButton):
    """Small icon-only 'quantum blue' toolbar button -- the icon-button
    counterpart to QuantumToggleButton above (same hover-expand, faint
    sheen, and circuit-trace-pulse language; see that class's own
    docstring for the full rationale). Built for the rest of the main
    toolbar: Undo/Redo, Select/Pan, the shape tools, the ruler, zoom in/
    out/fit, Clear Rulers, the five Mark As role tools, and the junction
    snapshot button -- added as a follow-up once the
    Measurements toggle above landed, to give the rest of the toolbar a
    matching custom style.

    Deliberately NOT a from-scratch reimplementation of each tool's
    click/checked/enabled/exclusivity logic -- that logic already lives
    entirely in a real QAction (undo/redo's enabled state tracking the
    undo/redo stacks, the big exclusive QActionGroup every Select/Pan/
    shape/role tool already shares so only one is ever active, tooltips,
    keyboard behavior). This button binds to that SAME QAction via Qt's
    own QToolButton.setDefaultAction(), which keeps checked/enabled state
    synced automatically in both directions -- so every existing action
    site (self.action_undo.setEnabled(...), self.action_select.
    setChecked(True), tool_group's exclusivity, etc.) keeps working
    completely unchanged. ONLY the paint job is new here.

    Unlike the wider Measurements pill, this is a small chip packed edge
    to edge with its neighbors in a dense icon toolbar -- so its circuit
    trace is kept fully SELF-CONTAINED along its own bottom inner edge
    (no stubs poking past its own footprint into a neighboring button),
    and the whole chip (fill/glow/sheen/trace) only appears once hovered
    or checked -- an idle, untouched toolbar looks exactly as calm and
    scannable as it does today; only touching or activating a tool wakes
    its own chip up.

    Icon color is regenerated directly from `icon_name` (not read off the
    bound action's own baked-in icon) so this button has precise control
    over idle/hover/checked/disabled tinting; three variants are cached
    at construction/retheme() time rather than rebuilt every paint."""

    _live_instances = []  # class-level registry so _apply_theme() can retheme every live one

    def __init__(self, icon_name, action=None, parent=None):
        super().__init__(parent)
        self._icon_name = icon_name
        self.setAutoRaise(True)
        self.setCursor(Qt.PointingHandCursor)
        self.setMouseTracking(True)
        self.setAttribute(Qt.WA_Hover, True)
        self.setIconSize(QSize(15, 15))
        self.setMinimumSize(30, 28)
        self._hover_progress = 0.0
        self._pulse_phase = 0.0
        self._hover_anim = QPropertyAnimation(self, b"hoverProgress", self)
        self._hover_anim.setDuration(150)
        self._hover_anim.setEasingCurve(QEasingCurve.OutCubic)
        self._pulse_timer = QTimer(self)
        self._pulse_timer.setInterval(33)
        self._pulse_timer.timeout.connect(self._advance_pulse)
        self.toggled.connect(lambda _checked: (self._sync_pulse_timer(), self.update()))
        self._build_icons()
        QuantumToolButton._live_instances.append(self)
        if action is not None:
            self.setDefaultAction(action)

    def _get_hover_progress(self):
        return self._hover_progress

    def _set_hover_progress(self, value):
        self._hover_progress = value
        self.update()

    hoverProgress = Property(float, _get_hover_progress, _set_hover_progress)

    def _build_icons(self):
        # idle and checked intentionally use the SAME glyph color
        # (TEXT_COLOR, near-white) -- checked reads fine against the
        # solid accent-blue chip fill behind it (matches this app's
        # existing convention, e.g. the Select tool). See the "hover
        # never re-tints the glyph" note in paintEvent for why there is
        # no separate hover variant here.
        self._icon_idle = qta.icon(self._icon_name, color=TEXT_COLOR)
        self._icon_checked = qta.icon(self._icon_name, color=TEXT_COLOR)
        self._icon_disabled = qta.icon(self._icon_name, color=DIM_COLOR)
        # paintEvent below draws these variants directly and never calls
        # super().paintEvent(), so this has zero visual effect -- it's
        # purely so external code that reasonably introspects a
        # QToolButton's own .icon() (existing tests among them) still
        # gets a real, non-null icon back instead of the Qt default.
        self.setIcon(self._icon_idle)

    def retheme(self):
        self._build_icons()
        self.update()

    def _sync_pulse_timer(self):
        active = (self.isChecked() or self.underMouse()) and self.isEnabled()
        if active and not self._pulse_timer.isActive():
            self._pulse_timer.start()
        elif not active and self._pulse_timer.isActive():
            self._pulse_timer.stop()

    def _advance_pulse(self):
        self._pulse_phase = (self._pulse_phase + 0.11) % (2 * math.pi)
        self.update()

    def enterEvent(self, event):
        if self.isEnabled():
            self._hover_anim.stop()
            self._hover_anim.setStartValue(self._hover_progress)
            self._hover_anim.setEndValue(1.0)
            self._hover_anim.start()
        self._sync_pulse_timer()
        super().enterEvent(event)

    def leaveEvent(self, event):
        self._hover_anim.stop()
        self._hover_anim.setStartValue(self._hover_progress)
        self._hover_anim.setEndValue(0.0)
        self._hover_anim.start()
        self._sync_pulse_timer()
        super().leaveEvent(event)

    def sizeHint(self):
        return QSize(32, 30)

    def paintEvent(self, event):
        checked = self.isChecked()
        enabled = self.isEnabled()
        hp = self._hover_progress if enabled else 0.0
        active = enabled and (checked or hp > 0.01)

        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing)

        full = QRectF(self.rect()).adjusted(1.5, 1.5, -1.5, -1.5)
        if full.width() < 8 or full.height() < 8:
            painter.end()
            return
        radius = 6.5

        scale = 1.0 + 0.07 * hp
        painter.save()
        center = full.center()
        painter.translate(center)
        painter.scale(scale, scale)
        painter.translate(-center)

        path = QPainterPath()
        path.addRoundedRect(full, radius, radius)

        if active:
            grad = QLinearGradient(full.topLeft(), full.bottomLeft())
            if checked:
                grad.setColorAt(0.0, QColor(ACCENT_COLOR).lighter(108))
                grad.setColorAt(1.0, QColor(ACCENT_COLOR).darker(112))
            else:
                grad.setColorAt(0.0, QColor(HOVER_COLOR).lighter(106 + int(6 * hp)))
                grad.setColorAt(1.0, QColor(PANEL_COLOR))
            painter.fillPath(path, QBrush(grad))

            ring = QColor("#ffffff" if checked else ACCENT_COLOR)
            ring_alpha = (140 if checked else 0) + int(130 * hp)
            ring.setAlpha(min(ring_alpha, 230))
            painter.setPen(QPen(ring, 1.2))
            painter.setBrush(Qt.NoBrush)
            painter.drawPath(path)

            # very slight sheen, same low constant alpha as the Measurements pill
            painter.save()
            painter.setClipPath(path)
            sheen = QLinearGradient(full.topLeft(), full.bottomRight())
            a = 12 + int(9 * hp)
            sheen.setColorAt(0.0, QColor(255, 255, 255, a))
            sheen.setColorAt(0.4, QColor(255, 255, 255, 0))
            painter.fillPath(path, QBrush(sheen))
            painter.restore()

            # self-contained circuit trace along the bottom inner edge --
            # never extends past this chip's own footprint, unlike the
            # wider Measurements pill's outward stubs, since these chips
            # sit packed edge to edge with no spare room to spill into
            painter.setBrush(Qt.NoBrush)
            self._draw_footer_trace(painter, full, checked, hp)

        # icon glyph, drawn last so it sits on top of everything else.
        # Fixes a bug caught in a real render: several of these
        # glyphs (fa5s.square, fa5s.circle, fa5s.square-full, ...) are
        # solid FILLED shapes, not outlines -- tinting the glyph itself
        # ACCENT_COLOR on hover made those specific buttons look
        # indistinguishable from the solid-accent CHECKED chip fill (a
        # hovered-but-not-selected Rectangle tool read as if it were
        # already selected). Hover is communicated entirely by the chip
        # background/glow/sheen/trace above now; the icon glyph itself
        # only ever changes color for checked vs. idle/hover/disabled, so
        # "hovering" and "selected" can never look the same.
        icon = (self._icon_disabled if not enabled else
                self._icon_checked if checked else self._icon_idle)
        isz = self.iconSize()
        icon_rect = QRectF(0, 0, isz.width(), isz.height())
        icon_rect.moveCenter(full.center())
        painter.setOpacity(1.0 if enabled else 0.4)
        icon.paint(painter, icon_rect.toRect())
        painter.setOpacity(1.0)

        painter.restore()
        painter.end()

    def _draw_footer_trace(self, painter, full, checked, hp):
        """A small line -> via -> line motif hugging the chip's own
        bottom inner edge, with a traveling glow pulse when active --
        the same trace/via visual vocabulary as the Measurements pill
        and _build_circuit_backdrop_svg, just contained to this chip's
        own width instead of extending past it."""
        y = full.bottom() - 3.5
        span = full.width() * 0.5
        x0 = full.center().x() - span / 2
        x1 = full.center().x() + span / 2
        color = QColor("#ffffff" if checked else ACCENT_COLOR)
        color.setAlpha(90 + int(70 * hp) if not checked else 150)
        painter.setPen(QPen(color, 1.1))
        painter.drawLine(QPointF(x0, y), QPointF(x1, y))
        via_color = QColor(color)
        via_color.setAlpha(min(via_color.alpha() + 40, 255))
        painter.setBrush(QBrush(via_color))
        painter.setPen(Qt.NoPen)
        painter.drawEllipse(QPointF(full.center().x(), y), 1.1, 1.1)
        # traveling pulse
        t = self._pulse_phase / (2 * math.pi)
        envelope = math.sin(math.pi * t)
        if envelope > 0.02:
            pulse_x = x0 + (x1 - x0) * t
            pulse_color = QColor("#ffffff" if checked else ACCENT_COLOR)
            pulse_color.setAlpha(int(220 * envelope))
            painter.setBrush(QBrush(pulse_color))
            r = 1.3 * envelope + 0.4
            painter.drawEllipse(QPointF(pulse_x, y), r, r)


class QuantumAppIcon(QWidget):
    """Animated version of the Front Page app mark -- added
    as a follow-up once the toolbar's Quantum buttons landed, to make
    the app logo dynamic and animated. Reproduces _build_appicon_svg's
    geometry (the comb-cross arms, the faint second-pass echo, the
    fiducial, the chip-package badge with its corner bond pads) with
    QPainter instead of a generated SVG, specifically so it can carry a
    live QTimer-driven phase: the echo arms slowly drift/breathe (a
    second shadow-evaporation pass settling in), the top-left "pin 1"
    bond pad glows, and a small accent pulse runs out along each of the
    4 primary arms in turn, a quarter-cycle apart -- reading as one pulse
    circulating the whole mark. Same trailing-pulse visual language as
    QuantumToolButton/QuantumToggleButton, just applied to the one mark
    that's on screen for as long as the Front Page is.

    The static SVG (_build_appicon_svg) is untouched and still used for
    the real window/taskbar icon (_build_window_icon, needs a QIcon, not
    a live widget) -- this class only replaces the Front Page hero's own
    icon_widget.

    Zero idle cost off-screen: the Front Page is one page of
    self.main_stack, and Qt delivers hide/show events to a widget's
    children when a QStackedWidget switches pages, so the timer starts
    in showEvent and stops in hideEvent -- navigating to any other tab
    stops this animation exactly like every other hover-gated Quantum*
    widget stops its own timer when untouched."""

    _live_instances = []

    ARM_ANGLES = (45, 135, 225, 315)
    ECHO_BASE_ANGLES = (50, 140, 230, 320)

    def __init__(self, parent=None):
        super().__init__(parent)
        self._phase = 0.0        # drives the per-arm traveling pulse
        self._drift_phase = 0.0  # slower phase: echo-arm drift + pin-1 breathing
        self._timer = QTimer(self)
        self._timer.setInterval(33)  # ~30fps
        self._timer.timeout.connect(self._advance)
        QuantumAppIcon._live_instances.append(self)

    def retheme(self):
        # every color this paints is read live from the module-level
        # theme constants at paint time (same convention as
        # QuantumToolButton/QuantumToggleButton's own paintEvent) --
        # nothing is cached, so a repaint is the whole job.
        self.update()

    def showEvent(self, event):
        self._timer.start()
        super().showEvent(event)

    def hideEvent(self, event):
        self._timer.stop()
        super().hideEvent(event)

    def _advance(self):
        self._phase = (self._phase + 0.045) % (2 * math.pi)
        self._drift_phase = (self._drift_phase + 0.012) % (2 * math.pi)
        self.update()

    def sizeHint(self):
        return QSize(132, 132)

    def _draw_arm(self, painter, color):
        """One arm unit along +x -- line, pad, 4-tooth comb, short
        trailing 5th tooth -- matching _build_appicon_svg's own `arm`
        string in the same 200x200 logical coordinate space."""
        painter.setPen(QPen(color, 3))
        painter.drawLine(QPointF(0, 0), QPointF(56, 0))
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(color))
        painter.drawRect(QRectF(50, -5, 10, 10))
        painter.setPen(QPen(color, 3))
        for x in (63, 70, 77, 84):
            painter.drawLine(QPointF(x, -9), QPointF(x, 9))
        painter.setPen(QPen(color, 2.5))
        painter.drawLine(QPointF(92, -6), QPointF(92, 6))

    def _draw_fiducial(self, painter, color):
        painter.setPen(QPen(color, 2))
        painter.setBrush(Qt.NoBrush)
        painter.drawRect(QRectF(-5, -5, 10, 10))
        painter.setPen(QPen(color, 1.5))
        for x1, y1, x2, y2 in (
            (-5, -13, -5, -8), (-13, -5, -8, -5),
            (5, -13, 5, -8), (13, -5, 8, -5),
            (-5, 13, -5, 8), (-13, 5, -8, 5),
            (5, 13, 5, 8), (13, 5, 8, 5),
        ):
            painter.drawLine(QPointF(x1, y1), QPointF(x2, y2))

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing)
        side = min(self.width(), self.height())
        if side <= 0:
            painter.end()
            return
        scale = side / 200.0
        painter.translate((self.width() - side) / 2.0, (self.height() - side) / 2.0)
        painter.scale(scale, scale)

        # --- chip-package badge ---
        badge = QRectF(3, 3, 194, 194)
        painter.setPen(QPen(QColor(BORDER_COLOR), 2))
        painter.setBrush(QBrush(QColor(PANEL_COLOR)))
        painter.drawRoundedRect(badge, 34, 34)
        inner_border = QColor(BORDER_COLOR)
        inner_border.setAlphaF(0.5)
        painter.setPen(QPen(inner_border, 1))
        painter.setBrush(Qt.NoBrush)
        painter.drawRoundedRect(QRectF(13, 13, 174, 174), 25, 25)

        # corner bond pads -- the top-left "pin 1" pad breathes gently in
        # the accent color instead of sitting static, the other three
        # stay a quiet BORDER_COLOR exactly as in the static SVG
        breathe = 0.5 + 0.5 * math.sin(self._drift_phase)
        pin1 = QColor(ACCENT_COLOR)
        pin1.setAlphaF(0.62 + 0.38 * breathe)
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(pin1))
        painter.drawRoundedRect(QRectF(9, 9, 7, 7), 1.5, 1.5)
        painter.setBrush(QBrush(QColor(BORDER_COLOR)))
        for x, y in ((184, 9), (9, 184), (184, 184)):
            painter.drawRoundedRect(QRectF(x, y, 7, 7), 1.5, 1.5)

        painter.translate(100, 100)

        # --- echo arms: faint, slowly drifting second-pass ghost ---
        echo_color = QColor(DIM_COLOR)
        echo_color.setAlphaF(0.32 + 0.18 * (0.5 + 0.5 * math.sin(self._drift_phase)))
        drift_deg = 2.0 * math.sin(self._drift_phase * 0.7)
        for base_angle in self.ECHO_BASE_ANGLES:
            painter.save()
            painter.rotate(base_angle + drift_deg)
            self._draw_arm(painter, echo_color)
            painter.restore()

        # --- primary arms: crisp, stable mark; each carries its own
        # traveling pulse a quarter-cycle out of phase with its
        # neighbors, reading as one pulse circulating the whole mark ---
        text_color = QColor(TEXT_COLOR)
        for i, base_angle in enumerate(self.ARM_ANGLES):
            painter.save()
            painter.rotate(base_angle)
            self._draw_arm(painter, text_color)
            arm_phase = (self._phase + i * (math.pi / 2)) % (2 * math.pi)
            t = arm_phase / (2 * math.pi)
            envelope = math.sin(math.pi * t)
            if envelope > 0.03:
                pulse_x = 4 + t * 88  # travels from near-center out past the comb tip
                pulse_color = QColor(ACCENT_COLOR)
                pulse_color.setAlphaF(0.85 * envelope)
                painter.setPen(Qt.NoPen)
                painter.setBrush(QBrush(pulse_color))
                r = 2.6 * envelope + 0.8
                painter.drawEllipse(QPointF(pulse_x, 0), r, r)
            painter.restore()

        self._draw_fiducial(painter, text_color)

        # a very faint diagonal sheen glazing the whole badge, matching the
        # "verrrry slight, not glossy
        # plastic" convention QuantumToggleButton/QuantumCard's own sheen
        # already establishes, just riding this icon's existing slow
        # _drift_phase instead of a new timer. Clipped to the badge's own
        # rounded-rect shape so it reads as a glaze on the chip, not a
        # stray bar crossing the whole widget.
        painter.save()
        painter.translate(-100, -100)  # undo the translate(100,100) above -- back to badge-local coords
        clip_path = QPainterPath()
        clip_path.addRoundedRect(badge, 34, 34)
        painter.setClipPath(clip_path)
        sheen_frac = (self._drift_phase % (2 * math.pi)) / (2 * math.pi)
        band = 90.0
        travel = 194.0 + 2 * band
        pos = -band + sheen_frac * travel
        gradient = QLinearGradient(pos - band / 2, 0, pos + band / 2, 194)
        c_edge = QColor(ACCENT_COLOR)
        c_edge.setAlphaF(0.0)
        c_mid = QColor(ACCENT_COLOR)
        c_mid.setAlphaF(0.10)
        gradient.setColorAt(0.0, c_edge)
        gradient.setColorAt(0.5, c_mid)
        gradient.setColorAt(1.0, c_edge)
        painter.setPen(Qt.NoPen)
        painter.setBrush(QBrush(gradient))
        painter.drawRect(badge)
        painter.restore()

        painter.end()


class QuantumCard(QFrame):
    """Larger 'quantum blue' shortcut card for the Front Page's per-tab
    jump cards and the Design Library card -- added as a
    follow-up to the toolbar's Quantum buttons, to do more with these
    larger cards. Same core language as QuantumToolButton (hover
    expand, faint sheen, circuit-trace pulse), scaled up with more of
    it now that there's real canvas to use: a small icon badge (top-
    left) that switches from dim to accent-lit on hover, all 4 corner
    bond pads echoing the app mark's own badge (one -- top-left, where
    the icon sits -- picked out as "pin 1" even at rest), a gentle
    lift-and-scale on hover instead of a hard highlight, and a pulse
    that travels the FULL top edge corner-to-corner rather than a
    short stub (there's room for the whole trip now).

    Drop-in replacement for _ClickableCard at this app's two call sites
    (the per-tab shortcuts and the Design Library card): same clicked
    signal, same left-click behavior. Builds its own title/description
    labels internally (icon_name/title/description passed in) instead
    of the caller assembling them, so retheme() has one place to keep
    every non-QSS bit of this card in sync with the current theme --
    the same _live_instances-registry pattern as every other custom-
    painted Quantum*/_FrontPageBackdrop widget in this file."""

    _live_instances = []
    clicked = Signal()

    def __init__(self, icon_name, title, description, parent=None):
        super().__init__(parent)
        self._icon_name = icon_name
        self.setCursor(Qt.PointingHandCursor)
        self.setMouseTracking(True)
        self.setAttribute(Qt.WA_Hover, True)
        self.setFrameShape(QFrame.NoFrame)
        self._hover_progress = 0.0
        self._pulse_phase = 0.0
        self._hover_anim = QPropertyAnimation(self, b"hoverProgress", self)
        self._hover_anim.setDuration(180)
        self._hover_anim.setEasingCurve(QEasingCurve.OutCubic)
        self._pulse_timer = QTimer(self)
        self._pulse_timer.setInterval(33)
        self._pulse_timer.timeout.connect(self._advance_pulse)

        layout = QVBoxLayout(self)
        # top margin clears the icon badge painted in paintEvent (see
        # icon_rect there); left margin clears the top-left corner pad
        layout.setContentsMargins(18, 46, 16, 14)
        layout.setSpacing(4)
        layout.addStretch(1)
        self._title_label = QLabel(title)
        self._desc_label = QLabel(description)
        self._desc_label.setWordWrap(True)
        layout.addWidget(self._title_label)
        layout.addWidget(self._desc_label)

        self._icon_idle = None
        self._icon_active = None
        QuantumCard._live_instances.append(self)
        self.retheme()

    def _get_hover_progress(self):
        return self._hover_progress

    def _set_hover_progress(self, value):
        self._hover_progress = value
        self.update()

    hoverProgress = Property(float, _get_hover_progress, _set_hover_progress)

    def retheme(self):
        self._icon_idle = qta.icon(self._icon_name, color=DIM_COLOR)
        self._icon_active = qta.icon(self._icon_name, color=ACCENT_COLOR)
        self._title_label.setStyleSheet(
            f"background: transparent; color: {TEXT_COLOR}; font-weight: bold; font-size: 10.5pt;"
        )
        self._desc_label.setStyleSheet(
            f"background: transparent; color: {DIM_COLOR}; font-size: 8.5pt;"
        )
        self.update()

    def _sync_pulse_timer(self):
        active = self.underMouse()
        if active and not self._pulse_timer.isActive():
            self._pulse_timer.start()
        elif not active and self._pulse_timer.isActive():
            self._pulse_timer.stop()

    def _advance_pulse(self):
        self._pulse_phase = (self._pulse_phase + 0.07) % (2 * math.pi)
        self.update()

    def enterEvent(self, event):
        self._hover_anim.stop()
        self._hover_anim.setStartValue(self._hover_progress)
        self._hover_anim.setEndValue(1.0)
        self._hover_anim.start()
        self._sync_pulse_timer()
        super().enterEvent(event)

    def leaveEvent(self, event):
        self._hover_anim.stop()
        self._hover_anim.setStartValue(self._hover_progress)
        self._hover_anim.setEndValue(0.0)
        self._hover_anim.start()
        self._sync_pulse_timer()
        super().leaveEvent(event)

    def mousePressEvent(self, event):
        if event.button() == Qt.LeftButton:
            self.clicked.emit()
        super().mousePressEvent(event)

    def sizeHint(self):
        base = super().sizeHint()
        return QSize(max(base.width(), 220), max(base.height(), 108))

    def paintEvent(self, event):
        hp = self._hover_progress
        active = hp > 0.01

        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing)

        full = QRectF(self.rect()).adjusted(1.0, 1.0, -1.0, -1.0)
        if full.width() < 12 or full.height() < 12:
            painter.end()
            return
        radius = 8.0

        # very slight lift + scale on hover, about the card's own center
        painter.save()
        center = full.center()
        painter.translate(center)
        painter.translate(0, -2.0 * hp)
        painter.scale(1.0 + 0.012 * hp, 1.0 + 0.012 * hp)
        painter.translate(-center)

        path = QPainterPath()
        path.addRoundedRect(full, radius, radius)

        grad = QLinearGradient(full.topLeft(), full.bottomLeft())
        grad.setColorAt(0.0, QColor(PANEL_COLOR).lighter(100 + int(10 * hp)))
        grad.setColorAt(1.0, QColor(PANEL_COLOR).darker(100 + int(4 * hp)))
        painter.fillPath(path, QBrush(grad))

        border = QColor(ACCENT_COLOR if active else BORDER_COLOR)
        if active:
            border.setAlpha(140 + int(100 * hp))
        painter.setPen(QPen(border, 1.2))
        painter.setBrush(Qt.NoBrush)
        painter.drawPath(path)

        # very slight sheen, same low constant alpha as the Measurements
        # pill and the toolbar chips, just a bit brighter on hover
        painter.save()
        painter.setClipPath(path)
        sheen = QLinearGradient(full.topLeft(), full.bottomRight())
        a = 8 + int(10 * hp)
        sheen.setColorAt(0.0, QColor(255, 255, 255, a))
        sheen.setColorAt(0.35, QColor(255, 255, 255, 0))
        painter.fillPath(path, QBrush(sheen))
        painter.restore()

        # corner bond pads -- same badge language as the app mark; the
        # top-left "pin 1" pad stays lit even at rest (this card's own
        # quiet identity marker), the other three only light up on hover
        pad = 5.0
        corners = [
            (full.left() + 7, full.top() + 7, True),
            (full.right() - 7 - pad, full.top() + 7, False),
            (full.left() + 7, full.bottom() - 7 - pad, False),
            (full.right() - 7 - pad, full.bottom() - 7 - pad, False),
        ]
        painter.setPen(Qt.NoPen)
        for x, y, is_pin1 in corners:
            c = QColor(ACCENT_COLOR if (is_pin1 or active) else BORDER_COLOR)
            if is_pin1:
                c.setAlpha(150 + int(105 * hp))
            elif active:
                c.setAlpha(80 + int(110 * hp))
            painter.setBrush(QBrush(c))
            painter.drawRoundedRect(QRectF(x, y, pad, pad), 1.2, 1.2)

        # icon badge, top-left
        icon_rect = QRectF(full.left() + 14, full.top() + 12, 24, 24)
        badge_path = QPainterPath()
        badge_path.addRoundedRect(icon_rect.adjusted(-5, -5, 5, 5), 7, 7)
        painter.setBrush(QBrush(QColor(HOVER_COLOR if active else BG_COLOR)))
        badge_border = QColor(ACCENT_COLOR if active else BORDER_COLOR)
        badge_border.setAlpha(220 if active else 160)
        painter.setPen(QPen(badge_border, 1.0))
        painter.drawPath(badge_path)
        icon = self._icon_active if active else self._icon_idle
        if icon is not None:
            icon.paint(painter, icon_rect.toRect())

        # top-edge traveling pulse, corner to corner -- only while hovered
        if active:
            y = full.top() + 6.5
            x0, x1 = full.left() + 16, full.right() - 16
            line_color = QColor(ACCENT_COLOR)
            line_color.setAlpha(60 + int(70 * hp))
            painter.setPen(QPen(line_color, 1.0))
            painter.drawLine(QPointF(x0, y), QPointF(x1, y))
            t = self._pulse_phase / (2 * math.pi)
            envelope = math.sin(math.pi * t)
            if envelope > 0.02:
                pulse_x = x0 + (x1 - x0) * t
                pulse_color = QColor(ACCENT_COLOR)
                pulse_color.setAlpha(int(230 * envelope))
                painter.setPen(Qt.NoPen)
                painter.setBrush(QBrush(pulse_color))
                r = 2.0 * envelope + 0.7
                painter.drawEllipse(QPointF(pulse_x, y), r, r)

        painter.restore()
        painter.end()


def _lerp_qcolor(c1, c2, t):
    """Linear-interpolates two colors (hex string or QColor) between
    0..1 -- shared by every Quantum* widget below that eases a checked/
    selected-state color transition in instead of hard-snapping it.
    Reaches c2's own full opaque RGB at t=1 -- correct for a border or
    text pen that's MEANT to become the solid accent color once
    checked, but wrong for a background FILL that has to stay legible
    behind text drawn in that same accent color; see _composite_tint
    for that case."""
    c1, c2 = QColor(c1), QColor(c2)
    t = max(0.0, min(1.0, t))
    return QColor(
        int(c1.red() + (c2.red() - c1.red()) * t),
        int(c1.green() + (c2.green() - c1.green()) * t),
        int(c1.blue() + (c2.blue() - c1.blue()) * t),
    )


def _composite_tint(base, tint, tint_alpha, t):
    """Alpha-composites `tint` OVER `base` at a fixed target opacity
    (0..1), itself scaled by progress `t` (0..1), and returns an
    OPAQUE QColor -- unlike _lerp_qcolor, this stays close to `base`
    even at t=1 as long as `tint_alpha` is low, instead of drifting all
    the way to `tint`'s own full RGB.

    Fixes a bug caught in a real render: QuantumPillButton and
    QuantumSegmentButton originally built their checked-state fill with
    `_lerp_qcolor(base_fill, accent_with_alpha_46, cp)` -- but
    QColor.red()/.green()/.blue() (all _lerp_qcolor ever reads) ignore
    alpha entirely, so that `.setAlpha(46)` was a silent no-op and the
    fill actually blended all the way to the FULL SOLID accent color at
    cp=1 -- which is exactly the same color the checked-state TEXT/icon
    is drawn in, making the label unreadable on every checked pill/
    segment once its check-in animation settled (Show Angle
    Diagnostics, Angle Setup, Warnings & Risk Check all start checked
    by default, so this hit on first render, not just after a click).
    This helper does real alpha compositing instead, restoring the
    originally-intended subtle background wash while the border/text/
    icon/underline keep carrying the actual "this one is ON" signal."""
    base, tint = QColor(base), QColor(tint)
    a = max(0.0, min(1.0, tint_alpha)) * max(0.0, min(1.0, t))
    return QColor(
        int(base.red() * (1 - a) + tint.red() * a),
        int(base.green() * (1 - a) + tint.green() * a),
        int(base.blue() * (1 - a) + tint.blue() * a),
    )


def _rounded_corners_path(rect, tl, tr, br, bl):
    """A QPainterPath for `rect` with an independently-radiused corner --
    used by QuantumSegmentButton so a row of segments packed edge-to-
    edge still reads as one continuous rounded rail/pill (only the
    group's own outer corners rounded, the seams between segments
    square), without the old per-instance QSS corner-radius patches."""
    path = QPainterPath()
    path.moveTo(rect.left() + tl, rect.top())
    path.lineTo(rect.right() - tr, rect.top())
    if tr:
        path.arcTo(rect.right() - 2 * tr, rect.top(), 2 * tr, 2 * tr, 90, -90)
    path.lineTo(rect.right(), rect.bottom() - br)
    if br:
        path.arcTo(rect.right() - 2 * br, rect.bottom() - 2 * br, 2 * br, 2 * br, 0, -90)
    path.lineTo(rect.left() + bl, rect.bottom())
    if bl:
        path.arcTo(rect.left(), rect.bottom() - 2 * bl, 2 * bl, 2 * bl, -90, -90)
    path.lineTo(rect.left(), rect.top() + tl)
    if tl:
        path.arcTo(rect.left(), rect.top(), 2 * tl, 2 * tl, 180, -90)
    path.closeSubpath()
    return path


class QuantumPillButton(QPushButton):
    """Shared 'quantum blue' secondary-action pill -- the single reusable
    button behind most of the Simulate Design toolbar (Clear Rulers,
    Ruler, Show Angle Diagnostics, Angle Setup, Warnings & Risk Check)
    and the Deposition Slideshow toolbar (Reload Recipe, Prev Step,
    Next Step), replacing a dozen+ hand-rolled, copy-pasted, theme-
    frozen inline QPushButton stylesheets. Added as a
    follow-up once the toolbar icons/cards/side-panel cards landed, so
    every button is visually distinct and clearly shows on/off state.

    Drop-in QPushButton (checkable or momentary, same .clicked/
    .toggled/.isChecked()/.setChecked()/.setEnabled() every call site
    already uses) -- only the paint job and hover/checked-transition
    animation are new. Deliberately lighter-weight than
    QuantumToggleButton/QuantumActionButton (no circuit-trace stubs, no
    continuously-running pulse) since a couple dozen of these sit
    packed into two toolbars -- instead, a one-shot QPropertyAnimation
    on hover (expand/settle) and another one-shot QPropertyAnimation on
    check-state change (an eased fade into the accent fill rather than
    a hard snap), each stopping itself the moment it finishes, so an
    untouched toolbar costs nothing at all."""

    _live_instances = []

    def __init__(self, text="", accent=None, icon_name=None, checkable=False, parent=None):
        super().__init__(text, parent)
        self._accent = accent or ACCENT_COLOR
        self._icon_name = icon_name
        self.setCheckable(checkable)
        self.setCursor(Qt.PointingHandCursor)
        self.setMouseTracking(True)
        self.setFlat(True)
        self.setAttribute(Qt.WA_Hover, True)
        self._hover_progress = 0.0
        self._checked_progress = 1.0 if self.isChecked() else 0.0
        self._hover_anim = QPropertyAnimation(self, b"hoverProgress", self)
        self._hover_anim.setDuration(150)
        self._hover_anim.setEasingCurve(QEasingCurve.OutCubic)
        self._checked_anim = QPropertyAnimation(self, b"checkedProgress", self)
        self._checked_anim.setDuration(180)
        self._checked_anim.setEasingCurve(QEasingCurve.OutCubic)
        self.toggled.connect(self._on_toggled)
        self._icon_idle = None
        self._icon_checked = None
        if icon_name:
            self._build_icons()
        QuantumPillButton._live_instances.append(self)
        self.setMinimumHeight(26)

    def _get_hover_progress(self):
        return self._hover_progress

    def _set_hover_progress(self, value):
        self._hover_progress = value
        self.update()

    hoverProgress = Property(float, _get_hover_progress, _set_hover_progress)

    def _get_checked_progress(self):
        return self._checked_progress

    def _set_checked_progress(self, value):
        self._checked_progress = value
        self.update()

    checkedProgress = Property(float, _get_checked_progress, _set_checked_progress)

    def _build_icons(self):
        self._icon_idle = qta.icon(self._icon_name, color=DIM_COLOR)
        self._icon_checked = qta.icon(self._icon_name, color=self._accent)

    def retheme(self):
        if self._icon_name:
            self._build_icons()
        self.update()

    def _on_toggled(self, checked):
        self._checked_anim.stop()
        self._checked_anim.setStartValue(self._checked_progress)
        self._checked_anim.setEndValue(1.0 if checked else 0.0)
        self._checked_anim.start()

    def enterEvent(self, event):
        if self.isEnabled():
            self._hover_anim.stop()
            self._hover_anim.setStartValue(self._hover_progress)
            self._hover_anim.setEndValue(1.0)
            self._hover_anim.start()
        super().enterEvent(event)

    def leaveEvent(self, event):
        self._hover_anim.stop()
        self._hover_anim.setStartValue(self._hover_progress)
        self._hover_anim.setEndValue(0.0)
        self._hover_anim.start()
        super().leaveEvent(event)

    def sizeHint(self):
        base = super().sizeHint()
        extra = 24 if self._icon_name else 12
        return QSize(base.width() + extra, max(base.height(), 26))

    def paintEvent(self, event):
        enabled = self.isEnabled()
        hp = self._hover_progress if enabled else 0.0
        cp = self._checked_progress

        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing)
        full = QRectF(self.rect()).adjusted(1.0, 1.0, -1.0, -1.0)
        if full.width() < 8 or full.height() < 8:
            painter.end()
            return
        radius = full.height() / 2.0

        scale = 1.0 + 0.03 * hp
        painter.save()
        center = full.center()
        painter.translate(center)
        painter.scale(scale, scale)
        painter.translate(-center)

        path = QPainterPath()
        path.addRoundedRect(full, radius, radius)

        base_fill = QColor(HOVER_COLOR if enabled else PANEL_COLOR)
        fill = _composite_tint(base_fill, self._accent, 42 / 255.0, cp)
        if hp > 0.01 and enabled:
            fill = fill.lighter(100 + int(8 * hp))
        painter.fillPath(path, QBrush(fill))

        border = _lerp_qcolor(BORDER_COLOR, self._accent, cp)
        if hp > 0.01 and enabled:
            border = _lerp_qcolor(border, QColor(self._accent), 0.55 * hp)
        painter.setPen(QPen(border, 1.1))
        painter.setBrush(Qt.NoBrush)
        painter.drawPath(path)

        text_color = _lerp_qcolor(DIM_COLOR if enabled else DIM_COLOR, self._accent, cp)
        if enabled and cp < 0.5 and hp > 0.01:
            text_color = _lerp_qcolor(text_color, QColor(TEXT_COLOR), 0.5 * hp)
        painter.setPen(QPen(text_color))
        left_pad = 24 if self._icon_name else 10
        text_rect = full.adjusted(left_pad, 0, -10, 0)
        painter.drawText(text_rect, Qt.AlignCenter, self.text())

        if self._icon_name and (self._icon_idle is not None):
            icon = self._icon_checked if cp > 0.5 else self._icon_idle
            isz = 12
            icon_rect = QRectF(full.left() + 8, full.center().y() - isz / 2, isz, isz)
            icon.paint(painter, icon_rect.toRect())

        painter.restore()
        painter.end()


class QuantumSegmentButton(QPushButton):
    """One segment of a 'quantum blue' exclusive segmented-choice group
    -- Simulate Design's VIEW trio (Optimal/Simulated/Post-Shadow), the
    Recipe tab's mode pair (Auto-Generated/Recipe Builder), and the
    Deposition Slideshow's view pair (Post Deposition/Shadow Sim).
    Part of stylizing the remaining buttons app-wide, with
    each option's ON/OFF state unmistakable at a glance.

    A full drop-in QPushButton -- checkable, same .clicked/.toggled/
    .isChecked()/.setChecked()/.setText()/.setEnabled() every existing
    call site already uses (these three groups are read and driven by
    name in dozens of places across the file) -- only the paint job and
    the selected-state transition are new.

    `position` ("left"/"mid"/"right"/"solo") controls which outer
    corners round, so a row of these packed edge-to-edge (spacing 0, in
    a thin wrapper container) still reads as one continuous rail/pill,
    the way this app's hand-rolled segmented groups already did -- just
    genuinely theme-reactive and animated now instead of frozen dark-
    mode hex glued together with per-instance corner-radius QSS.

    Selecting a segment doesn't hard-snap its accent fill in -- a one-
    shot QPropertyAnimation eases it in/out (checkedProgress), and a
    thin accent underline grows in under the selected segment, a clear
    "which one is ON" signal distinct from the plain-pill DISPLAY-group
    buttons in the same toolbar. No continuous timer -- the transition
    animation stops itself once it finishes."""

    _live_instances = []

    def __init__(self, text, accent, position="solo", parent=None):
        super().__init__(text, parent)
        self._accent = accent
        self._position = position
        self.setCheckable(True)
        self.setCursor(Qt.PointingHandCursor)
        self.setMouseTracking(True)
        self.setFlat(True)
        self.setAttribute(Qt.WA_Hover, True)
        self._hover_progress = 0.0
        self._checked_progress = 0.0
        self._hover_anim = QPropertyAnimation(self, b"hoverProgress", self)
        self._hover_anim.setDuration(150)
        self._hover_anim.setEasingCurve(QEasingCurve.OutCubic)
        self._checked_anim = QPropertyAnimation(self, b"checkedProgress", self)
        self._checked_anim.setDuration(200)
        self._checked_anim.setEasingCurve(QEasingCurve.OutCubic)
        self.toggled.connect(self._on_toggled)
        QuantumSegmentButton._live_instances.append(self)
        self.setMinimumHeight(26)

    def _get_hover_progress(self):
        return self._hover_progress

    def _set_hover_progress(self, value):
        self._hover_progress = value
        self.update()

    hoverProgress = Property(float, _get_hover_progress, _set_hover_progress)

    def _get_checked_progress(self):
        return self._checked_progress

    def _set_checked_progress(self, value):
        self._checked_progress = value
        self.update()

    checkedProgress = Property(float, _get_checked_progress, _set_checked_progress)

    def retheme(self):
        self.update()

    def _on_toggled(self, checked):
        self._checked_anim.stop()
        self._checked_anim.setStartValue(self._checked_progress)
        self._checked_anim.setEndValue(1.0 if checked else 0.0)
        self._checked_anim.start()

    def enterEvent(self, event):
        if self.isEnabled():
            self._hover_anim.stop()
            self._hover_anim.setStartValue(self._hover_progress)
            self._hover_anim.setEndValue(1.0)
            self._hover_anim.start()
        super().enterEvent(event)

    def leaveEvent(self, event):
        self._hover_anim.stop()
        self._hover_anim.setStartValue(self._hover_progress)
        self._hover_anim.setEndValue(0.0)
        self._hover_anim.start()
        super().leaveEvent(event)

    def sizeHint(self):
        base = super().sizeHint()
        return QSize(base.width() + 14, max(base.height(), 26))

    def paintEvent(self, event):
        enabled = self.isEnabled()
        hp = self._hover_progress if enabled else 0.0
        cp = self._checked_progress

        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing)
        full = QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5)
        if full.width() < 8 or full.height() < 8:
            painter.end()
            return
        radius = full.height() / 2.0
        tl = radius if self._position in ("left", "solo") else 0.0
        bl = tl
        tr = radius if self._position in ("right", "solo") else 0.0
        br = tr
        path = _rounded_corners_path(full, tl, tr, br, bl)

        base_fill = QColor(HOVER_COLOR if enabled else PANEL_COLOR)
        fill = _composite_tint(base_fill, self._accent, 46 / 255.0, cp)
        if hp > 0.01 and enabled:
            fill = fill.lighter(100 + int(7 * hp))
        painter.fillPath(path, QBrush(fill))

        border = _lerp_qcolor(BORDER_COLOR, self._accent, cp)
        if hp > 0.01 and enabled:
            border = _lerp_qcolor(border, QColor(self._accent), 0.5 * hp)
        painter.setPen(QPen(border, 1.1))
        painter.setBrush(Qt.NoBrush)
        if self._position in ("mid", "right"):
            # the previous segment's own right edge already draws this
            # shared seam -- clip away this segment's left edge so it
            # isn't double-drawn (a hair thicker than the outer border)
            painter.save()
            painter.setClipRect(full.adjusted(1.3, -1, 1, 1))
            painter.drawPath(path)
            painter.restore()
        else:
            painter.drawPath(path)

        text_color = _lerp_qcolor(DIM_COLOR, self._accent, cp)
        if hp > 0.01 and enabled and cp < 0.5:
            text_color = _lerp_qcolor(text_color, QColor(TEXT_COLOR), 0.5 * hp)
        painter.setPen(QPen(text_color))
        painter.drawText(full.adjusted(4, 0, -4, -4 * cp), Qt.AlignCenter, self.text())

        # growing accent underline -- the clear "this one is ON" signal
        if cp > 0.01:
            bar_w = full.width() * 0.42 * cp
            bar_y = full.bottom() - 3.5
            bar_color = QColor(self._accent)
            bar_color.setAlpha(int(230 * cp))
            painter.setPen(Qt.NoPen)
            painter.setBrush(QBrush(bar_color))
            painter.drawRoundedRect(QRectF(full.center().x() - bar_w / 2, bar_y, bar_w, 2.0), 1.0, 1.0)

        painter.end()


class QuantumActionButton(QPushButton):
    """The 'quantum blue' primary-action CTA pill -- Simulate Design's
    two most important buttons, Run Angle Diagnostic and Run Shadow
    Simulation, get the same full-effort animated treatment as the
    Measurements On/Off toggle (QuantumToggleButton): hover expand,
    faint sheen, and the same Manhattan-routed circuit-trace stubs with
    a traveling glow, matching the same level of polish given to the
    Measurements button since these two are similarly crucial. A little
    bolder/larger than QuantumToggleButton (this is a primary CTA, not
    a small inline toggle), with a soft outward glow while hovered
    instead of a live pulse glyph -- these aren't a live-readout
    toggle, they're a "press me to act" button.

    A full drop-in QPushButton (not checkable) -- same .clicked/
    .setEnabled()/.setText() every call site already uses. Run Shadow
    Simulation's existing disabled-until-diagnostic-has-run behavior is
    preserved via the normal .setEnabled(False)/.setEnabled(True) calls
    already in place -- the disabled paint is fully dimmed with no
    glow, sheen, or trace at all, same intent as the old QSS's
    :disabled rule."""

    TRACE_MARGIN = 15
    _live_instances = []

    def __init__(self, text="", accent=None, parent=None):
        super().__init__(text, parent)
        self._accent = accent or ACCENT_COLOR
        self.setCursor(Qt.PointingHandCursor)
        self.setMouseTracking(True)
        self.setFlat(True)
        self.setAttribute(Qt.WA_Hover, True)
        self._hover_progress = 0.0
        self._pulse_phase = 0.0
        QuantumActionButton._live_instances.append(self)
        self._hover_anim = QPropertyAnimation(self, b"hoverProgress", self)
        self._hover_anim.setDuration(180)
        self._hover_anim.setEasingCurve(QEasingCurve.OutCubic)
        self._pulse_timer = QTimer(self)
        self._pulse_timer.setInterval(33)
        self._pulse_timer.timeout.connect(self._advance_pulse)
        self.setMinimumHeight(30)

    def _get_hover_progress(self):
        return self._hover_progress

    def _set_hover_progress(self, value):
        self._hover_progress = value
        self.update()

    hoverProgress = Property(float, _get_hover_progress, _set_hover_progress)

    def retheme(self):
        self.update()

    def _sync_pulse_timer(self):
        active = self.isEnabled() and self.underMouse()
        if active and not self._pulse_timer.isActive():
            self._pulse_timer.start()
        elif not active and self._pulse_timer.isActive():
            self._pulse_timer.stop()

    def _advance_pulse(self):
        self._pulse_phase = (self._pulse_phase + 0.11) % (2 * math.pi)
        self.update()

    def enterEvent(self, event):
        if self.isEnabled():
            self._hover_anim.stop()
            self._hover_anim.setStartValue(self._hover_progress)
            self._hover_anim.setEndValue(1.0)
            self._hover_anim.start()
        self._sync_pulse_timer()
        super().enterEvent(event)

    def leaveEvent(self, event):
        self._hover_anim.stop()
        self._hover_anim.setStartValue(self._hover_progress)
        self._hover_anim.setEndValue(0.0)
        self._hover_anim.start()
        self._sync_pulse_timer()
        super().leaveEvent(event)

    def sizeHint(self):
        base = super().sizeHint()
        return QSize(base.width() + 2 * self.TRACE_MARGIN + 10, max(base.height(), 30))

    def _draw_trace_stub(self, painter, anchor, direction, length, phase, glow_color, dim_color, active):
        """Same trace/via/pad motif as QuantumToggleButton._draw_trace_stub."""
        if length <= 0.5:
            return
        end_x = anchor.x() + direction * length
        y = anchor.y()
        line_color = QColor(glow_color if active else dim_color)
        line_color.setAlpha(190 if active else 90)
        painter.setPen(QPen(line_color, 1.3))
        painter.drawLine(QPointF(anchor.x(), y), QPointF(end_x, y))
        via_x = anchor.x() + direction * length * 0.55
        via_color = QColor(glow_color if active else dim_color)
        via_color.setAlpha(150 if active else 70)
        painter.setBrush(QBrush(via_color))
        painter.setPen(Qt.NoPen)
        painter.drawEllipse(QRectF(via_x - 1.1, y - 1.1, 2.2, 2.2))
        pad_color = QColor(glow_color if active else dim_color)
        pad_color.setAlpha(170 if active else 80)
        painter.setBrush(QBrush(pad_color))
        pad_size = 2.6
        painter.drawRect(QRectF(end_x - (0 if direction > 0 else pad_size), y - pad_size / 2, pad_size, pad_size))
        if not active:
            return
        t = phase / (2 * math.pi)
        envelope = math.sin(math.pi * t)
        if envelope <= 0.02:
            return
        pulse_x = anchor.x() + direction * length * t
        pulse_color = QColor(glow_color)
        pulse_color.setAlpha(int(210 * envelope))
        painter.setBrush(QBrush(pulse_color))
        r = 1.9 * envelope + 0.7
        painter.drawEllipse(QRectF(pulse_x - r, y - r, 2 * r, 2 * r))

    def paintEvent(self, event):
        enabled = self.isEnabled()
        hp = self._hover_progress if enabled else 0.0
        active = enabled and hp > 0.01

        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing)

        full = QRectF(self.rect()).adjusted(self.TRACE_MARGIN, 1.5, -self.TRACE_MARGIN, -1.5)
        if full.width() < 8 or full.height() < 8:
            painter.end()
            return
        radius = full.height() / 2.0

        scale = 1.0 + 0.045 * hp
        painter.save()
        center = full.center()
        painter.translate(center)
        painter.scale(scale, scale)
        painter.translate(-center)

        path = QPainterPath()
        path.addRoundedRect(full, radius, radius)

        accent = QColor(self._accent)
        if enabled:
            grad = QLinearGradient(full.topLeft(), full.bottomLeft())
            base = QColor(accent)
            base.setAlpha(34 + int(28 * hp))
            deep = QColor(accent)
            deep.setAlpha(16 + int(20 * hp))
            grad.setColorAt(0.0, base)
            grad.setColorAt(1.0, deep)
            painter.fillPath(path, QBrush(grad))

            if hp > 0.01:
                painter.save()
                glow = QColor(accent)
                glow.setAlpha(int(70 * hp))
                painter.setPen(QPen(glow, 4 + 3 * hp))
                painter.setBrush(Qt.NoBrush)
                painter.drawPath(path)
                painter.restore()

            border = QColor(accent)
            border.setAlpha(160 + int(90 * hp))
            painter.setPen(QPen(border, 1.3))
            painter.setBrush(Qt.NoBrush)
            painter.drawPath(path)

            painter.save()
            painter.setClipPath(path)
            sheen = QLinearGradient(full.topLeft(), full.bottomRight())
            a = 14 + int(12 * hp)
            sheen.setColorAt(0.0, QColor(255, 255, 255, a))
            sheen.setColorAt(0.4, QColor(255, 255, 255, 0))
            painter.fillPath(path, QBrush(sheen))
            painter.restore()
        else:
            painter.fillPath(path, QBrush(QColor(PANEL_COLOR)))
            painter.setPen(QPen(QColor(BORDER_COLOR), 1.1))
            painter.setBrush(Qt.NoBrush)
            painter.drawPath(path)

        text_color = QColor(accent if enabled else DIM_COLOR)
        painter.setPen(QPen(text_color))
        f = painter.font()
        f.setBold(True)
        painter.setFont(f)
        painter.drawText(full, Qt.AlignCenter, self.text())

        painter.restore()

        if enabled:
            left_anchor = QPointF(full.left(), full.center().y())
            right_anchor = QPointF(full.right(), full.center().y())
            length = self.TRACE_MARGIN - 3
            self._draw_trace_stub(painter, left_anchor, -1, length, self._pulse_phase,
                                   self._accent, BORDER_COLOR, active)
            self._draw_trace_stub(painter, right_anchor, 1, length, self._pulse_phase,
                                   self._accent, BORDER_COLOR, active)

        painter.end()


class _ClickableCard(QFrame):
    """A bordered panel that emits clicked() on a left click -- used for
    the Front Page's per-tab shortcut cards (title + description,
    doubling as both a shortcut and the Get Started guide's own text,
    both read from MainWindow._tab_definitions so they can never drift
    out of sync with the real tab list)."""

    clicked = Signal()

    def mousePressEvent(self, event):
        if event.button() == Qt.LeftButton:
            self.clicked.emit()
        super().mousePressEvent(event)


class DesignLibraryDialog(QDialog):
    """Catalog browser for design_library.py's locally-saved designs --
    reachable from File > Open Design Library... and the Front Page's
    Design Library card. Lists every saved design (name, source,
    saved/updated time, a short detail string) with Load/Rename/Delete,
    plus a direct "Save Current Design..." shortcut so saving and
    browsing live in one place. Delegates the actual save/load work to
    MainWindow._save_current_design/_load_design_from_library -- this
    dialog only owns the list UI, not the design-restoration logic."""

    def __init__(self, main_window):
        super().__init__(main_window)
        self.main_window = main_window
        self.setWindowTitle("Design Library")
        self.resize(580, 440)
        layout = QVBoxLayout(self)

        info = QLabel("Double-click a design, or select it and click Load, to restore it as active.")
        info.setWordWrap(True)
        layout.addWidget(info)

        self.list_widget = QListWidget()
        self.list_widget.itemDoubleClicked.connect(self._on_load_clicked)
        self.list_widget.currentItemChanged.connect(self._on_selection_changed)
        layout.addWidget(self.list_widget, 1)

        self.detail_label = QLabel("")
        self.detail_label.setWordWrap(True)
        self.detail_label.setStyleSheet("color: #888;")
        layout.addWidget(self.detail_label)

        btn_row = QHBoxLayout()
        save_btn = QPushButton("Save Current Design...")
        save_btn.setToolTip("Save whatever design is currently active in the app as a NEW entry here.")
        save_btn.clicked.connect(self._on_save_current)
        load_btn = QPushButton("Load")
        rename_btn = QPushButton("Rename...")
        delete_btn = QPushButton("Delete")
        load_btn.clicked.connect(self._on_load_clicked)
        rename_btn.clicked.connect(self._on_rename_clicked)
        delete_btn.clicked.connect(self._on_delete_clicked)
        btn_row.addWidget(save_btn)
        btn_row.addStretch()
        btn_row.addWidget(load_btn)
        btn_row.addWidget(rename_btn)
        btn_row.addWidget(delete_btn)
        layout.addLayout(btn_row)

        close_box = QDialogButtonBox(QDialogButtonBox.Close)
        close_box.rejected.connect(self.reject)
        layout.addWidget(close_box)

        self._designs = []
        self._refresh()

    def _refresh(self):
        self.list_widget.clear()
        try:
            self._designs = dl.list_designs()
        except Exception as e:
            QMessageBox.warning(self, "Design Library", f"Could not read the design library: {e}")
            self._designs = []
        for d in self._designs:
            source_txt = "Created" if d["source"] == "created" else "Imported"
            item = QListWidgetItem(f"{d['name']}  —  {source_txt}, saved {d['updated_at']}")
            item.setData(Qt.UserRole, d["id"])
            self.list_widget.addItem(item)
        if not self._designs:
            self.detail_label.setText("No saved designs yet -- use \"Save Current Design...\" above "
                                      "(or File > Save Design... in the main window) to save the "
                                      "design you're currently working on.")
        else:
            self.detail_label.setText("")

    def _selected_summary(self) -> Optional[dict]:
        item = self.list_widget.currentItem()
        if item is None:
            return None
        design_id = item.data(Qt.UserRole)
        return next((d for d in self._designs if d["id"] == design_id), None)

    def _on_selection_changed(self, current, previous):
        d = self._selected_summary()
        if d is None:
            self.detail_label.setText("")
            return
        self.detail_label.setText(
            f"{d['finger_count']} finger(s), {d['shape_count']} other shape(s) -- {d['detail']}\n"
            f"Notes: {d['notes'] or '(none)'}")

    def _on_save_current(self):
        self.main_window._save_current_design()
        self._refresh()

    def _on_load_clicked(self):
        d = self._selected_summary()
        if d is None:
            QMessageBox.information(self, "Nothing selected", "Select a design first.")
            return
        if self.main_window._load_design_from_library(d["id"]):
            self.accept()

    def _on_rename_clicked(self):
        d = self._selected_summary()
        if d is None:
            QMessageBox.information(self, "Nothing selected", "Select a design first.")
            return
        new_name, ok = QInputDialog.getText(self, "Rename Design", "New name:", QLineEdit.Normal, d["name"])
        if not ok or not new_name.strip():
            return
        try:
            dl.rename_design(d["id"], new_name)
        except Exception as e:
            QMessageBox.warning(self, "Rename failed", f"Could not rename: {e}")
            return
        self._refresh()

    def _on_delete_clicked(self):
        d = self._selected_summary()
        if d is None:
            QMessageBox.information(self, "Nothing selected", "Select a design first.")
            return
        reply = QMessageBox.question(self, "Delete Design", f"Permanently delete “{d['name']}”?\n\n"
                                      "This cannot be undone.",
                                      QMessageBox.Yes | QMessageBox.No, QMessageBox.No)
        if reply != QMessageBox.Yes:
            return
        try:
            dl.delete_design(d["id"])
        except Exception as e:
            QMessageBox.warning(self, "Delete failed", f"Could not delete: {e}")
            return
        self._refresh()


class _AICtx:
    """Bundles the 'Ask AI' panel's widgets plus its own in-flight-call
    state (busy flag, watchdog timer, call sequence number, reference
    images, Q&A history). Used by exactly one panel (self._ask_ai_ctx --
    see _build_ask_ai_widget) now that the earlier per-tab AI Draft/
    Review panels (each with their own _AICtx) have been removed
    entirely; kept as its own class rather than folded into MainWindow
    directly so the watchdog/threading methods below (_ai_tick,
    _ai_set_busy, etc.) stay generic and easy to reuse if another AI
    panel is ever added."""
    def __init__(self, main_window, *, host_edit, model_edit, image_list, notes_edit,
                 status_label, output_browser):
        self.host_edit = host_edit
        self.model_edit = model_edit
        self.image_list = image_list
        self.notes_edit = notes_edit          # doubles as the question box
        self.status_label = status_label
        self.output_browser = output_browser  # renders ask_history (see _render_ask_ai_history)

        self.reference_images = []        # manually added photo paths
        self.ask_history = []             # [(question, answer_text_or_None, error_or_None)]
        self.pending_question = None      # set while a call is in flight, for live-typing display
        self.pending_stream_text = ""
        self.busy = False
        self.call_seq = 0   # incremented on every new call AND on timeout, so a late-arriving
                              # worker result from a call we've already given up on gets silently
                              # discarded instead of confusing whatever the user's doing by then
        self.phase = ""
        self.progress_chars = 0
        self.start_time = 0.0
        self.last_activity_time = 0.0
        self.timeout_call_id = -1
        self.idle_timeout_dynamic = 0.0   # real value is set at the start of every busy call
        self.call_signals = None          # kept alive for the duration of an in-flight call

        self.timer = QTimer(main_window)
        self.timer.setInterval(1000)
        self.timer.timeout.connect(lambda: main_window._ai_tick(self))


# The running app's version is shown in the window title (see
# MainWindow.__init__ below), so it's always possible to confirm at a
# glance which build is actually executing -- useful when reporting an
# issue or comparing behavior across machines. Bump this string with each
# release.
APP_VERSION = "v1.0.0"

# A lightweight, always-on diagnostic trace: a short, timestamped log of
# key recipe-editing decision points, written next to this script as
# `plassys_debug.log`. Deliberately cheap (a handful of one-line file
# appends per click, never per-frame/per-redraw) and fails silently if the
# file can't be written, so it can never itself cause a problem. Capped
# and self-rotating (see _DEBUG_LOG_MAX_BYTES below) so it can never grow
# into a disk-space issue no matter how long the app runs. If you run
# into a bug that's hard to reproduce, this log is the first place to
# look -- it captures what the app actually did, not just what it should
# have done.
_DEBUG_LOG_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "plassys_debug.log")

# Capped and self-rotating so this can never grow into a real disk-space
# problem on a long-running install: once plassys_debug.log reaches
# _DEBUG_LOG_MAX_BYTES, it's renamed to plassys_debug.log.1 (overwriting
# whatever was there before) and a fresh, empty log starts -- so at most
# one full log plus one partial one (2x the cap, worst case) ever exists
# on disk, no matter how long the app has been running or how many
# sessions it's seen. Uses Python's own standard-library rotation
# (logging.handlers.RotatingFileHandler) rather than hand-rolled
# truncation, so the rollover itself is already well-tested elsewhere.
_DEBUG_LOG_MAX_BYTES = 2_000_000  # ~2 MB per file, ~4 MB worst case on disk
_DEBUG_LOG_BACKUP_COUNT = 1


def _make_debug_logger():
    import logging
    from logging.handlers import RotatingFileHandler
    logger = logging.getLogger("plassys_debug")
    logger.setLevel(logging.DEBUG)
    logger.propagate = False  # never echo onto the root logger/console
    if not logger.handlers:
        try:
            handler = RotatingFileHandler(
                _DEBUG_LOG_PATH, maxBytes=_DEBUG_LOG_MAX_BYTES,
                backupCount=_DEBUG_LOG_BACKUP_COUNT, encoding="utf-8")
            handler.setFormatter(logging.Formatter("%(message)s"))
            logger.addHandler(handler)
        except Exception:
            pass  # e.g. an unwritable directory -- _debug_log() below stays a safe no-op
    return logger


_debug_logger = _make_debug_logger()


def _debug_log(msg):
    try:
        _debug_logger.debug(f"[{datetime.datetime.now().isoformat(timespec='seconds')}] {msg}")
    except Exception:
        pass


# Guards against a whole class of hard crashes. By default,
# PySide6/Qt has NO protection against an unhandled Python exception
# raised inside a slot -- one that escapes a button's clicked handler, a
# tab-change callback, a timer tick, or any other Qt callback propagates
# straight through Qt's C++ event-loop call boundary, and the entire
# application terminates immediately with no error dialog and (unless
# a terminal happens to be visible) no visible explanation at
# all -- it just vanishes. Rapid clicking, quickly flipping through tabs,
# making many changes to the predicted recipe steps, or clicking the
# wrong area all just increase the odds of hitting SOME
# unhandled exception path (a stale row index after a rebuild, a
# focus-out edit racing a delete on the very same row, an unexpected
# None) -- and this file, at 1.7MB+ with hundreds of interconnected
# dynamic-rebuild handlers, cannot realistically have every such path
# already found and eliminated by inspection alone. The one blanket fix
# that actually closes this whole CLASS of bug, rather than chasing
# individual instances of it forever, is a global crash guard: installed
# BEFORE QApplication even exists (sys.excepthook must be set before
# app.exec() starts pumping events), it catches literally ANY unhandled
# exception from ANY slot/signal/paint/timer callback anywhere in the
# app, logs its full traceback to plassys_debug.log (see _debug_log
# above -- so a recurring crash leaves real, inspectable evidence for a
# future fix), shows a small non-blocking error dialog so the user knows
# something went wrong, and then returns NORMALLY so Qt's event loop
# keeps running -- instead of the process aborting. This turns an
# unexplained vanished app with all unsaved work lost into
# a dialog reporting that something broke, with the app still open and
# the design/
# simulation/measurements still on screen: not a
# promise that no exception can ever occur again, but a guarantee that
# one hitting ANY UI action can no longer take the whole application
# down with it.
def _install_crash_guard():
    def _excepthook(exc_type, exc_value, exc_tb):
        if issubclass(exc_type, KeyboardInterrupt):
            sys.__excepthook__(exc_type, exc_value, exc_tb)
            return
        tb_text = "".join(traceback.format_exception(exc_type, exc_value, exc_tb))
        _debug_log(f"UNHANDLED EXCEPTION -- crash guard caught this, app kept running:\n{tb_text}")
        try:
            sys.stderr.write(tb_text)
        except Exception:
            pass
        try:
            QMessageBox.critical(
                None, "Something went wrong",
                "An unexpected error occurred, but the app is staying open so you don't lose your work.\n\n"
                f"{exc_type.__name__}: {exc_value}\n\n"
                "Details were written to plassys_debug.log next to this program. If this keeps happening "
                "on the same action, please note exactly what you clicked/typed right before it and send "
                "that file along.")
        except Exception:
            pass  # showing the dialog itself must never be what defeats the crash guard
    sys.excepthook = _excepthook


class MainWindow(QMainWindow):
    # A fixed wall-clock cutoff doesn't work for the AI call: local VL
    # models can legitimately sit "silent" for a minute+ doing image
    # encoding/prefill before the first token streams, and once streaming
    # starts a long multi-step recipe can take several more minutes to
    # finish -- neither of those is "stuck", they're just slow. So instead
    # of one absolute limit, use an IDLE timeout (give up only if nothing
    # has happened -- no phase change, no new streamed characters -- for
    # this long, which is what "stuck" actually looks like) plus a much
    # larger absolute ceiling purely as a safety net against a genuinely
    # runaway call. Ported from the Tk version's exact constants/logic --
    # confirmed via direct testing there that a flat 240s budget was
    # enough at 0 images but broke down around 16, which is why the
    # per-image scaling term exists.
    AI_IDLE_TIMEOUT_SECONDS = 240    # give up if NO progress at all for this long (baseline, 0 images)
    AI_IDLE_TIMEOUT_PER_IMAGE_SECONDS = 60  # extra idle allowance per attached image (VL prefill scales with image count)
    AI_ABSOLUTE_MAX_SECONDS = 1800   # hard ceiling regardless of progress (30 min)


    # CRASH FIX -- bounded depth cap for the live-auto-recompute reentrancy
    # guard in _recommit_sim_run (see the comment there for the full trace
    # of the recursive chain this bounds). Measured directly: an ordinary
    # single-field hand-edit (e.g. the Active-alpha field) typically
    # settles within 2-3 bounces (each bounce re-derives recipe features
    # from the just-updated layer state, which can itself shift another
    # field's fallback-derived value once more before everything agrees).
    # This cap is set well above that observed normal range so it never
    # engages for real, converging usage, and only ever engages for a
    # genuinely pathological, non-converging edit sequence -- at which
    # point it hard-stops rather than recursing without bound. Each lap is
    # only a handful of stacked function calls, so even this cap is a tiny
    # fraction of Python's default recursion limit.
    _SIM_RECOMPUTE_DEPTH_CAP = 8

    def __init__(self):
        super().__init__()
        self.setWindowTitle(f"Plassys Shadow Simulator {APP_VERSION}")
        self.resize(1600, 1000)
        # Fixes a bug where the window would stretch when
        # switching tabs, stay stretched until re-toggling fullscreen,
        # and leave mouse clicks landing offset: without an
        # explicit minimum size, Qt computes the window's minimum from
        # whichever tab's own layout tree happens to be visible. If a
        # tab with a wider minimum content demand (e.g. Simulate Design's
        # multi-button control row) becomes active while the window is
        # in native fullscreen, Qt can grow the window slightly PAST the
        # screen's own bounds to satisfy that minimum -- and switching
        # back to a narrower tab does not shrink it back down (Qt never
        # auto-shrinks a window just because the current page needs
        # less space). The OS still thinks the window exactly fills the
        # screen, so its mouse-to-window coordinate mapping goes stale
        # until something forces a full relayout (toggling fullscreen).
        # Fixing this at the source, in EVERY tab's own minimum-width
        # demand, isn't tractable long-term as more tabs get added --
        # pinning the window's own minimum size to a small, fixed value
        # overrides Qt's per-tab dynamic computation entirely, so no
        # single tab's content can ever force the window to grow.
        self.setMinimumSize(900, 600)

        # --- Theme state (Settings > Light/Dark Mode) ---
        # Non-destructive "themed widget/icon registry" pattern: toggling
        # theme never rebuilds or replaces any widget (that would risk
        # silently losing live user data -- typed field values, spoken/
        # typed measurement readings, etc. that don't all have a shadow
        # copy in self state). Instead, every widget whose stylesheet
        # depends on a theme color registers itself + a small lambda that
        # regenerates that stylesheet from the CURRENT color constants;
        # _apply_theme() just re-runs those lambdas and re-applies the
        # results to the SAME existing widget objects. See _themed() and
        # _apply_theme() below.
        self._theme_mode = "dark"
        self._themed_widgets = []   # list of (widget, style_fn) -- style_fn() -> qss string
        self._themed_icons = []     # list of (setter_fn, icon_name_or_factory) -- see _themed_icon()

        # --- Live state (Phase 2) ---
        self.electrode_scene = ShapeScene()
        self._pending_shape_kind = None
        self._pending_role_kind = None
        self._pending_polygon_points = []
        self._ruler_pending_start = None   # (x,y) of the first click, or None
        self._sim_rulers = []                # Simulate Design's OWN separate ruler state -- not
                                                # shared with Create / Import's, since Simulate Design
                                                # can show shifted geometry (Post-Shadow Result) with different
                                                # coordinates than the nominal design those measure
        self._sim_ruler_pending_start = None
        self._rulers = []                    # list of {"start":(x,y), "end":(x,y), "distance_um":float}
                                                # -- persist across redraws until explicitly cleared
        self._create_import_cached_junction = None  # so zoom/toggle can redraw just the overlay
        self._create_import_cached_report = None    # without recomputing the whole design
        self._sim_cached_junction = None
        self._sim_cached_report = None
        self._sim_cached_fingerprint = None  # see _design_fingerprint -- a content-based signature
                                                # of the active design's actual geometry, kept ALONGSIDE
                                                # _sim_cached_junction's plain object identity so a design
                                                # edit that MUTATES the existing junction/finger/shape
                                                # objects in place (every Create/Import edit path does
                                                # this -- apply_finger_edit/apply_shape_edit/
                                                # recompute_derived_fields etc. all mutate their given
                                                # object rather than returning a new one) is still
                                                # detected as a real design change, not just a swap to a
                                                # brand-new junction object
        self._sim_view_mode = "optimal"    # "optimal" (recommended angles, no shadow bands) or
                                              # "simulated" (active override angles, with shadow bands)
        self._sim_has_run = False           # True once "Run Simulation" has been clicked at least once
        self._sim_angle_diagnostic_run = False  # True once "Run Angle Diagnostic" has been clicked --
                                                   # gates BOTH the recommendations/warnings/verdict
                                                   # panels AND whether "Run Shadow Simulation" is enabled
        self._sim_last_run = None           # dict of {alpha, theta_a, theta_b} committed at last Run click
        # Simulate Design's simulation results should reset or live-update
        # whenever a parameter changes; otherwise
        # stale
        # results persist and mislead a user into thinking the
        # simulation matches their latest edits when it doesn't. Angle/
        # layer/thickness overrides deliberately do NOT auto-redraw (Run
        # Shadow Simulation must stay an
        # explicit, deliberate click, not fire on every keystroke), but
        # until now nothing told the user their currently-shown Simulated
        # Design / Post-Shadow Result view no longer matches what's typed
        # -- only an easy-to-miss "•" appended to the Run button's own
        # text, and only for the Active-alpha field specifically (editing
        # a per-layer angle/thickness in the tree, or changing which
        # finger deposits first, updated nothing at all). This flag plus
        # _refresh_sim_stale_banner below make that staleness impossible
        # to miss, from every input that can cause it.
        self._sim_stale = False

        # --- Recipe (Recipe) state ---
        self._recipe_sim_result = None      # last junction_import.SimulationResult generated
        self._recipe_features = []          # editable copy of its .features -- reorder/delete lives here
        self._recipe_generated_fingerprint = None  # fingerprint baked in at generation time, for staleness
        self._recipe_custom_steps = []      # the literal custom_steps built from _recipe_features
        self._recipe_last_steps = []        # the literal RecipeStep list from the last (re)build
        self._recipe_last_warnings = []
        self._recipe_last_params = None     # the DesignParameters used for the last (re)build --
                                               # needed to re-render after a hand-edit without
                                               # regenerating (see _refresh_recipe_display_after_edit)
        self._recipe_last_source_label = None
        self._recipe_last_browser = None    # QTextBrowser that last rendered the recipe -- lets a
                                               # hand-edit redraw in place whichever pane showed it
                                               # (Recipe's own, or wherever an AI draft was adopted)
        self._recipe_hand_edits = []        # List[RecipeHandEdit] --
                                               # user edits to an already-generated recipe's process
                                               # values, tracked independently of RecipeStep itself.
                                               # Reset on every fresh generation/AI-adopt (matching the
                                               # same reset-on-regenerate idiom SimulationFeature.
                                               # manual_override already uses), read by
                                               # _build_recipe_html, _on_ai_export_pdf, _on_ai_save_recipe,
                                               # and design_library.py's save/load.

        # Transitions the format of the
        # user-generated recipe to match the format of the Plassys/by-hand
        # recipe, for editability and duplicate-and-patch behavior (see
        # generated_recipe_export.py). kind_key -> current real recipe-tree
        # path / kind_key -> the exact fresh-generated (pre-hand-edit)
        # PlassysStepRow list that produced that link -- the "baseline"
        # resolve_and_write diffs the NEXT generation against, so a real
        # parameter change duplicates+patches (keeping hand-edits) while
        # an unchanged regeneration reuses the same node untouched.
        # Persisted per-design via design_library.py's recipe_builder_links/
        # recipe_builder_baselines (replacing the older single-string
        # self._current_design_recipe_link, still read for backward compat
        # -- see _save_current_design/_load_design_from_library below).
        self._current_design_recipe_links = {}      # kind_key -> tree path
        self._current_design_recipe_baselines = {}  # kind_key -> List[PlassysStepRow]

        # Addresses a bug plus a related feature request: when
        # exporting the junction simulation as a PDF diagnostic or an HTML
        # repository, it needs to know which recipe to attach. If a
        # user has already created a recipe from one junction and then
        # switches to a junction of the same project, that design should
        # also be assigned the same recipe even if a recipe hasn't been
        # explicitly created for that specific junction yet. But
        # creating a repository for one project junction and then
        # loading a new junction from a different project should NOT reuse
        # the first design's repository -- an earlier version of this code did
        # exactly that. Root cause: none of _current_design_recipe_links/
        # _current_design_recipe_link/_recipe_builder_current_path/
        # _active_design_id were ever reset (or intentionally carried
        # over) when a genuinely different PROJECT became active --
        # only File > New Junction ever cleared any of them (and even
        # that missed _current_design_recipe_link/_recipe_builder_
        # current_path -- see _new_junction below), so the Final
        # Diagnostic PDF/HTML export's recipe section could silently
        # keep showing whatever an earlier, completely unrelated
        # project's recipe was.
        #
        # _batch_recipe_links caches each project's own last-known recipe-
        # link state (keyed by _import_project_key -- see _maybe_reset_
        # for_new_project's own established "project" identity: the same
        # GDS/script FILE, regardless of which cell/junction --
        # e.g. one row/column combination vs. another --
        # is currently selected from it) so that switching between two cells of the
        # SAME project automatically shares one recipe (the requested
        # feature), while switching to a genuinely different project
        # restores THAT project's own last-known state instead (empty/
        # None the first time it's ever seen) rather than inheriting the
        # old one (the bug fix). _recipe_link_active_project_key tracks
        # which project key the state CURRENTLY sitting in the four
        # fields above actually belongs to right now, so the switch only
        # ever fires when that identity genuinely changes -- see
        # _switch_active_project_recipe_links, and its call sites in
        # _run_import_analysis (a real Import & Analyze click -- not
        # merely browsing/picking a file) and _set_display_source
        # (toggling Created <-> Imported, already this app's own
        # established "a genuinely different design became active"
        # choke point).
        self._batch_recipe_links = {}                # project_key -> {"links", "link", "recipe_builder_path"}
        self._recipe_link_active_project_key = None

        self._sim_finger_layers = {}        # finger_index -> list of active deposition theta floats;
                                               # a feature can have MULTIPLE depositions (e.g. adhesion
                                               # passes with no oxidation between) or ZERO (meaning that
                                               # shape is never deposited at all) -- persists across tree
                                               # rebuilds directly, not reconstructed from widget text
        self._sim_patch_layers = None       # list of active deposition theta floats for ALL patches
                                               # (patches share one physical layer, so one global list,
                                               # not per-finger) -- None means "not yet initialized for
                                               # this design", distinct from [] (zero active layers,
                                               # a deliberate user choice)
        self._sim_finger_thicknesses = {}   # finger_index -> list of target-thickness floats, PARALLEL
                                               # to _sim_finger_layers[idx] (same length, same pass order).
                                               # Gives the user a direct place to set
                                               # the thickness of each deposition
                                               # step, rather than having it auto-placed into the
                                               # generated recipe -- each pass row in the Deposition
                                               # Angles tree gets its own thickness field, seeded with the
                                               # computed default the moment it's added (see
                                               # junction_import.default_finger_pass_thickness), then
                                               # always a real, directly editable number from then on.
        self._sim_patch_thicknesses = None  # list of target-thickness floats for ALL patches, parallel
                                               # to _sim_patch_layers -- same None/[] distinction
        # Per-pass alpha (planetary tilt), PARALLEL to
        # _sim_finger_layers/_sim_patch_layers exactly like _sim_finger_thicknesses/
        # _sim_patch_thicknesses already are -- fixes a bug where
        # a per-step alpha edit in the Predicted Recipe Sequence panel had
        # ZERO effect on the shadow simulation, because the shadow math only ever
        # read ONE global alpha (the Active-alpha field), never any per-pass
        # value. None here means "no explicit per-pass alpha set" -- a missing or
        # short entry falls back to the single Active-alpha field's value (kept
        # as the seed/fallback default, never removed), so a design that never
        # touches per-pass alpha behaves bit-for-bit as before.
        self._sim_finger_alphas = {}        # finger_index -> list of per-pass alpha floats, parallel to
                                               # _sim_finger_layers[idx] -- a None entry (or a missing/short
                                               # list) falls back to the shared Active-alpha field
        self._sim_patch_alphas = None       # list of per-pass alpha floats for ALL patches, parallel to
                                               # _sim_patch_layers -- same None/[] distinction and fallback
        self._dragging = False
        self._drag_offset = (0.0, 0.0)  # (click_x - shp.cx, click_y - shp.cy) at grab time -- see
                                          # _on_canvas_press/_on_canvas_motion's docstrings for the
                                          # crash this fixes: without it, a drag snaps the shape's
                                          # CENTER straight to the cursor on the very first motion
                                          # event, regardless of where within the shape you clicked.
        self._create_import_force_fit = True  # True = the next Create/Import redraw re-fits the
                                          # view to the design's current bounding box (auto-fit);
                                          # False = it preserves whatever view is already on screen.
                                          # Starts True so the very first draw gets a real fit. See
                                          # _update_create_import_preview's docstring for why this
                                          # exists -- auto-fitting on EVERY redraw (the old behavior)
                                          # creates a divergent view-rescale feedback loop the moment
                                          # a shape being dragged is itself part of what's being fit.
        self._shape_props_last_identity = None  # (role, source, stable_id/id(obj)) as of the last
                                          # _sync_shape_properties_panel() that actually populated
                                          # the card's fields -- see that method's own docstring for
                                          # the stuck-focus-guard bug this exists to fix.
        # Handles dragging a JUNCTION-native finger/patch/plate (as
        # opposed to a custom electrode_scene shape, which _dragging/
        # _drag_offset above already cover). Unlike a custom shape's
        # cx/cy-based move, a junction member is a raw point list, so
        # this tracks the last mouse position and applies each motion
        # event's own INCREMENTAL delta via _translate_junction_member
        # (no per-frame undo push -- see _on_canvas_press's own comment)
        # rather than holding one fixed offset-from-center.
        self._dragging_junction_id = None
        self._drag_junction_last_xy = (0.0, 0.0)
        # If the entire junction is
        # selected, the whole junction should move; if only the
        # patches are selected, all of them should be dragged. When a
        # Layer is highlighted (self._layer_highlight) and the shape the
        # mouse actually grabbed belongs to it, a canvas drag now moves
        # every shape classified into that layer together, as one rigid
        # group -- same incremental-delta-per-motion-event style as
        # _dragging_junction_id above (see _translate_layer_members),
        # just applied to a whole category at once instead of one
        # stable_id. Mutually exclusive with _dragging/_dragging_
        # junction_id for a given gesture -- _on_canvas_press picks
        # exactly one of the three.
        self._dragging_layer_category = None
        self._drag_layer_last_xy = (0.0, 0.0)
        # When a layer is selected, it can also be batch-rotated: a node
        # can be dragged that rotates the whole junction, recalculating
        # the angle of every shape individually. A
        # rotation ring appears whenever a Layer is highlighted (see
        # _layer_rotation_ring_geometry), rotating
        # every shape classified into it together as one rigid group
        # about a single shared pivot -- same "snapshot everything at
        # drag-start, always measure the swept delta from THAT snapshot"
        # pattern _apply_shape_rotation_drag's own polygon branch uses,
        # generalized from one shape to a whole group (see
        # _apply_layer_rotation_drag's own docstring for exactly why a
        # snapshot, not a per-frame incremental delta, is required here).
        self._rotating_layer_category = None         # the highlighted layer category being rotated, or None
        self._rotating_layer_origin = None           # (ox, oy) -- the shared pivot for this gesture
        self._rotating_layer_start_mouse_angle = 0.0  # degrees, mouse angle around the pivot at drag-start
        self._rotating_layer_start_fingers = {}       # stable_id -> (base_stub, base_patch_end, base_width_um, base_length_um)
        self._rotating_layer_start_shapes = {}        # stable_id -> [base_points...] (real junction patch/plate)
        self._rotating_layer_start_scene_shapes = {}  # scene shape id -> {"cx","cy","angle_deg","points","base_points"} snapshot
        # Click-drag shape creation (rect/circle "click one corner, drag
        # to the opposite corner" -- see _on_canvas_press's own comment
        # for why this replaces the old "pop in at a fixed default
        # size" behavior): while resizing, this holds the NEW shape's
        # own id and the anchor (fixed, opposite) corner's world
        # position captured once at press time.
        self._creating_shape_id = None
        self._creating_shape_anchor = (0.0, 0.0)
        # Per-node/vertex editing of a selected custom electrode_scene
        # shape: dragging one of its own corner/vertex handles reshapes
        # it in place instead of moving the whole shape. For "rect"/
        # "circle"/"oval", node_index is 0-3 (a bounding-box corner) and
        # node_anchor_world is that corner's OPPOSITE corner, captured
        # once at drag-start and held fixed while w/h/cx/cy are re-
        # derived from it every motion event (see _apply_node_drag's own
        # docstring for the exact rotation-aware math). For "polygon",
        # node_index is a literal index into shp.points and no anchor is
        # needed (that one vertex simply follows the cursor).
        self._dragging_node_shape_id = None
        self._dragging_node_index = None
        self._dragging_node_anchor_world = (0.0, 0.0)
        # A line with a tiny circle that
        # lets a shape be rotated just by dragging the little
        # rotation node attached to the shape, working for
        # any shape and any polygon a user creates: a small
        # rotation handle beside a selected shape's own boundary,
        # dragged instead of a corner/vertex node to change ANGLE
        # instead of size. Two separate id trackers since a custom
        # electrode_scene shape and a real junction-native finger
        # rotate through entirely different code paths (EditableShape.
        # angle_deg / raw point rotation vs. ji.apply_finger_edit's own
        # theta_toward_patch_deg pivot) -- see _apply_shape_rotation_
        # drag/_apply_finger_rotation_drag's own docstrings. A polygon
        # has no stored angle_deg (see EditableShape.to_world_polygon's
        # own docstring -- its points are always literal, already-in-
        # world-coordinates), so rotating one needs an incremental
        # delta from a captured drag-start snapshot instead of a direct
        # absolute assignment; these three fields hold that snapshot.
        self._rotating_shape_id = None            # a custom electrode_scene shape's own id
        self._rotating_shape_start_points = None  # polygon only: point snapshot at drag-start
        self._rotating_shape_start_mouse_angle = 0.0  # polygon only: degrees, at drag-start
        self._rotating_shape_start_angle_deg = 0.0  # polygon only: shp.angle_deg's own display
                                                       # value at drag-start (see _apply_shape_
                                                       # rotation_drag's own docstring for why this
                                                       # is tracked as a plain running total instead
                                                       # of re-derived from geometry every frame)
        self._rotating_finger_id = None           # a real junction finger's own stable_id
        self._panning = False
        self._pan_last_xdata = None
        self._pan_last_ydata = None
        self._undo_stack = []   # full design-state snapshot dicts (see _capture_undo_snapshot --
                                  # electrode_scene.shapes, _imported_junction, _param_shape_offsets/
                                  # _edits, _junction_scale_base, _role_overrides), taken BEFORE each
                                  # mutating action
        self._redo_stack = []
        self._drag_undo_pushed = False  # ensures a drag pushes exactly one snapshot, at
                                          # press time, not once per motion event
        self._scale_drag_undo_pushed = False  # Same convention, for the Scale
                                                 # slider's own live-apply-while-dragging gesture
                                                 # (see _on_scale_slider_moved's own docstring)
        self._deposit_first_index = 0  # 0 = "Finger A", 1 = "Finger B"
        self._selected_junction_id = None   # stable_id of a selected finger/patch/plate (not a custom shape)
        self._role_overrides = {}           # stable_id -> role, persisted across redraws
        self._layer_highlight = None        # "finger" | "patch" | "plate" | "electrode" | "__jj_all__" | None
        self._junction_scale_base = {}      # group_key -> {"origin": (x,y), "fingers": {stable_id:
                                               # (base_stub_end, base_patch_end, base_width_um)},
                                               # "shapes": {stable_id: [base_points...]}} for imported
                                               # junction fingers/patches/plates -- same "1.00 = original"
                                               # reference the electrode_scene shapes keep on themselves
                                               # (EditableShape.base_w/h), captured lazily and re-captured
                                               # on every DIRECT edit (see _on_junction_property_edit),
                                               # so a later Scale always measures from the shape's last
                                               # deliberately-set size/position, never a compounding one.
                                               # group_key is either a single shape's own stable_id (a
                                               # single-shape Scale) or a Layer category string like
                                               # "patch" (a whole-feature Scale) -- see
                                               # _apply_junction_group_scale, the ONE function behind
                                               # every Scale operation in this tab.
        # A click-drag rubber-band/marquee
        # multi-select tool, a common feature in shape
        # designer programs: click and drag a
        # dotted-line box over a region and every discernable feature
        # within that region gets selected, whether the full shape is
        # inside or even just a fraction of it. Reuses the exact same click-drag mechanics the
        # rect/circle placement tools already use (_creating_shape_id/
        # _creating_shape_anchor above), just drawing a preview rectangle
        # and selecting instead of creating one -- see _on_canvas_press/
        # _on_canvas_motion/_on_canvas_release and _finish_marquee_drag.
        # Deliberately stores STABLE IDS, never live Finger/Shape/
        # ElectrodeShape object references: a parametric design's
        # junction is fully thrown away and rebuilt from scratch on
        # every single _update_preview() call (see _param_shape_offsets'
        # own comment just below), which would silently orphan a stored
        # object reference the instant any redraw ran -- _marquee_live_
        # members() re-resolves these ids into whatever's actually live
        # right now, every time, exactly like _layer_scene_shapes/
        # _layer_junction_members already re-resolve a Layer category
        # fresh on every use instead of caching objects.
        self._marquee_drag_start = None     # (x, y) anchor in data coords while a fresh drag is in
                                               # progress; None whenever not actively dragging
        self._marquee_rect_artist = None    # the live dashed-rectangle matplotlib patch shown DURING
                                               # the drag only -- removed the instant the drag ends
        self._marquee_selection = None      # None, or {"scene_shape_ids": [...], "finger_ids": [...],
                                               # "shape_ids": [...]} -- the committed ad hoc batch a
                                               # completed drag leaves behind, acted on by Nudge/Scale/
                                               # Move (_current_edit_target's "marquee" kind) until the
                                               # user clicks away, starts a new drag, or presses Escape.
                                               # Explicitly NOT a target for per-type parameter editing
                                               # (Shape Properties / Batch Edit Layer), since a mixed batch
                                               # makes per-type parameters or calculations meaningless.
        self._dragging_marquee = False      # True while a canvas drag is moving the WHOLE committed
                                               # batch together (grabbed one of its own members) --
                                               # the "Move" operation, mirroring _dragging_layer_category
        self._drag_marquee_last_xy = (0.0, 0.0)
        self._param_shape_offsets = {}      # stable_id -> (dx_um, dy_um) accumulated Nudge offset
                                               # for a PARAMETRIC design's finger/patch/plate -- that
                                               # junction is thrown away and rebuilt fresh from Design
                                               # Parameters on every _update_preview() call, so (unlike
                                               # an imported junction's direct, persistent geometry
                                               # mutation) there's nothing to mutate in place; this is
                                               # re-applied to the freshly-rebuilt junction every time
                                               # instead. Same index-based stable_id caveat as
                                               # _role_overrides/_junction_scale_base above: changing
                                               # finger/patch/plate COUNTS reassigns indices, which can
                                               # silently point an old offset at the wrong shape -- an
                                               # existing landmine in this app, not a new one.
        self._param_shape_edits = {}         # stable_id -> dict of ABSOLUTE target values (length/
                                               # width/angle/overlap for a finger; near/far overhang/
                                               # width/margin for a patch; length/width for a plate)
                                               # for a bare PARAMETRIC finger/patch/plate edited via
                                               # the Shape Properties card (_on_shape_finger_edit/
                                               # _on_shape_patch_edit/_on_shape_plate_edit) -- same
                                               # "rebuilt from scratch every redraw" problem
                                               # _param_shape_offsets exists for (see its own comment
                                               # above), just for apply_finger_edit/
                                               # apply_patch_extension_edit/apply_shape_edit instead of
                                               # a translation. Storing ABSOLUTE targets (not deltas)
                                               # keeps re-application idempotent across repeated
                                               # rebuilds -- see _apply_param_shape_edits.
        self._param_shape_deletions = set()  # stable_ids of PARAMETRIC fingers/patches/plates the user
                                               # has deleted (see _delete_selected_shape) -- excluded
                                               # from the freshly-rebuilt junction every
                                               # _update_preview() call, same "can't mutate a
                                               # thrown-away object, so persist the edit and re-apply
                                               # it" strategy as _param_shape_offsets/_param_shape_edits
                                               # above, and the same index-based stable_id caveat
                                               # applies (changing patch_count reassigns indices -- a
                                               # pre-existing landmine this app already has).
                                               # Supports an arbitrary number of
                                               # junction fingers as
                                               # long as they go in the same direction/angle, since the
                                               # shadow sim should be able to treat a trench like any
                                               # trench: fingers are no longer refused here -- the
                                               # old "exactly 2 fingers" assumption in the shadow/recipe
                                               # engine degrades gracefully rather than crashing for
                                               # N != 2 (junction_import.py's own
                                               # compute_measurements already emits a warning, not an
                                               # error, for this), so deletion/duplication is unblocked
                                               # now (see _delete_selected_shape/_duplicate_selected_
                                               # shape) while the deeper "give every extra finger its
                                               # own fully-independent shadow treatment" engine work is
                                               # tracked separately -- see shadowing_design_rules.md.
        self._param_shape_duplicates = {}    # new synthetic stable_id -> {"source_stable_id", "dx",
                                               # "dy", "kind"} for a PARAMETRIC finger/patch/plate the
                                               # user duplicated -- re-derived from its (possibly also
                                               # freshly-rebuilt) source object every _update_preview()
                                               # call, same pattern as the two dicts above. "kind" is
                                               # "finger" or "shape", set once at creation time
                                               # so _materialize_param_shape_duplicates knows which
                                               # of junction.fingers/.other_shapes to search and append
                                               # to. If the source no longer exists after a rebuild
                                               # (deleted, or patch_count shrank under it), the
                                               # duplicate is silently skipped that round rather than
                                               # raising -- see _materialize_param_shape_duplicates.
        self._interp_tc_user_edited = False  # True once the user hand-edits Interpret Results'
                                               # T_c field -- after that, _refresh_interp_tc_default
                                               # stops seeding it from TC_KELVIN_BY_METAL[metal_type]
                                               # so a manually-entered/measured T_c is never clobbered

        self._build_menu_bar()
        self._build_settings_gear()
        self._build_toolbar()
        self._init_hotkey_system()  # must run after _build_menu_bar/_build_toolbar (both just
                                       # ran -- every QAction the Settings > Hotkeys database
                                       # drives has to exist first; see this method's docstring)
                                       # and BEFORE _build_main_tabs below, since building the
                                       # Settings tab's own Hotkeys section reads self._hotkey_entries
        self._build_navigation_rail()
        self._build_docks()
        self._build_main_tabs()
        self._refresh_interp_tc_default()  # seed Interpret Results' T_c from the startup deposition
                                              # metal now that self.interp_tc_edit exists (the Recipe
                                              # tab's recipe_panel_metal_combo is built earlier, inside
                                              # _build_main_tabs' Recipe tab, but this function still
                                              # needs BOTH widgets to exist before it can do anything) --
                                              # see _refresh_interp_tc_default's docstring
        self.setWindowIcon(self._make_app_qicon())  # the one place the Front Page's brand mark
                                                        # spreads beyond the Front Page itself --
                                                        # window/taskbar icon, set once at startup
                                                        # (not re-set on theme toggle: an OS-level
                                                        # window icon changing live under a running
                                                        # app reads as a glitch, not a feature)
        self._build_status_bar()  # must run BEFORE _on_nav_changed(0) below -- that call now
                                     # reaches into self.status_back_btn/status_forward_btn
                                     # (see _build_status_bar), which this creates
        self._on_nav_changed(0)  # Fixes a gap: setCurrentRow(0) inside
                                    # _build_navigation_rail never actually fires
                                    # currentRowChanged (no prior selection to change FROM, and
                                    # the connect happens after anyway), so dock/toolbar
                                    # visibility was never explicitly synchronized to the real
                                    # startup state -- previously harmless because every dock's
                                    # Qt-default (visible) happened to match the Front Page's
                                    # needs, but create_import_bottom_dock needs to START hidden,
                                    # which is what exposed this.
        self._update_preview()  # first real draw, now that docks (property fields) exist too
        self._hover_timer = QTimer(self)
        self._hover_timer.timeout.connect(self._check_hover_reveal)
        self._hover_timer.start(120)  # ~8x/sec -- cheap, and responsive enough to feel immediate
        self._update_undo_redo_enabled()  # both start disabled -- nothing to undo/redo yet
        # The per-tab AI review/draft/adopt panel (Recipe's own _AICtx,
        # _ai_ctx_new3) was removed along with the AI Draft/Review feature
        # itself: across real use, the
        # deterministic recipe generator already produces the recipe
        # correctly, while the LLM did consistently better in a purely
        # explanatory role. The single app-wide "Ask AI" assistant (see
        # _build_ask_ai_widget, self._ask_ai_ctx) is now the only AI
        # surface in the app, and it never generates or edits a recipe.

    # ------------------------------------------------------------------
    def _build_menu_bar(self):
        menu_bar = self.menuBar()
        # Fixes a bug where the gear icon was invisible when the app was
        # actually run, despite appearing fine in any headless/screenshot
        # render: by default Qt hands
        # a QMainWindow's menu bar off to the OS's own native/global menu
        # bar wherever the platform has one (always on macOS; optionally
        # on Linux desktops with "global menu" integration, e.g. old
        # Ubuntu Unity/appmenu-qt) -- and QMenuBar.setCornerWidget() is
        # documented to silently do nothing once that's happened, since
        # there's no in-window bar left for the corner widget to attach
        # to. The offscreen Qt platform used for headless testing/
        # screenshots has no native menu bar at all, so the corner widget
        # rendered perfectly there regardless of this bug -- it could
        # never have been caught that way, only running the real GUI app on a
        # real desktop could catch it. Forcing an in-window (non-native) menu bar
        # here fixes it everywhere, at the cost of the File/Edit/View
        # menus no longer living in the macOS system menu bar strip --
        # a deliberate tradeoff, since a custom pinned icon like the
        # Settings gear can only exist inside the actual window in the
        # first place, native menu bar or not.
        menu_bar.setNativeMenuBar(False)
        file_menu = menu_bar.addMenu("&File")
        # NOTE: none of the QAction()s below get a .setShortcut(...) call
        # here anymore -- every keyboard shortcut in the app (including
        # these five pre-existing ones) is now assigned centrally by
        # _init_hotkey_system, from the Settings > Hotkeys database
        # (hotkey_registry.py), which runs once __init__ has finished
        # building every action/toolbar this file references. Keeping
        # shortcut assignment in exactly one place is what makes the
        # Hotkeys table's reassignment/reset actually take effect live,
        # instead of two places silently drifting out of sync. Each
        # action that the registry drives is stashed on self (a
        # self._hk_action_* attribute) so _init_hotkey_system can find it.
        new_junction_action = QAction("New Junction", self)
        new_junction_action.triggered.connect(self._new_junction)
        file_menu.addAction(new_junction_action)
        self._hk_action_new_junction = new_junction_action
        file_menu.addAction("Import GDS...", lambda: self._menu_import(0))
        file_menu.addAction("Import KLayout Script...", lambda: self._menu_import(1))
        file_menu.addSeparator()
        file_menu.addAction("Save Recipe...", self._on_ai_save_recipe)
        file_menu.addAction("Save Junction Snapshot...", self._on_save_snapshot)
        file_menu.addSeparator()
        save_design_action = QAction("Save Design...", self)
        save_design_action.setToolTip("Save to the design library, overwriting the loaded design if any.")
        save_design_action.triggered.connect(lambda: self._save_current_design(
            design_id=getattr(self, "_active_design_id", None)))
        file_menu.addAction(save_design_action)
        self._hk_action_save_design = save_design_action
        save_design_as_action = QAction("Save Design As New...", self)
        save_design_as_action.triggered.connect(lambda: self._save_current_design(design_id=None))
        file_menu.addAction(save_design_as_action)
        open_library_action = QAction("Open Design Library...", self)
        open_library_action.setToolTip("Browse, load, rename, or delete every design saved locally "
                                        "on this machine.")
        open_library_action.triggered.connect(self._open_design_library)
        file_menu.addAction(open_library_action)
        self._hk_action_open_design_library = open_library_action
        file_menu.addSeparator()
        export_final_diagnostic_action = QAction("Export Final Diagnostic Report...", self)
        export_final_diagnostic_action.setToolTip(
            "One combined PDF: design, simulation, recipe, and measurement/analysis results.")
        export_final_diagnostic_action.triggered.connect(self._on_export_final_diagnostic)
        file_menu.addAction(export_final_diagnostic_action)
        export_final_diagnostic_html_action = QAction("Export Final Diagnostic Repository (HTML)...", self)
        export_final_diagnostic_html_action.setToolTip(
            "Same design/simulation/recipe/measurement content as the PDF, as a single self-contained, "
            "clickable HTML file you can open and organize your own design repository around.")
        export_final_diagnostic_html_action.triggered.connect(self._on_export_final_diagnostic_html)
        file_menu.addAction(export_final_diagnostic_html_action)
        file_menu.addSeparator()
        file_menu.addAction("Exit", self.close)

        edit_menu = menu_bar.addMenu("&Edit")
        undo_action = QAction("Undo", self)
        undo_action.triggered.connect(self._undo)
        edit_menu.addAction(undo_action)
        self._hk_action_undo_menu = undo_action
        redo_action = QAction("Redo", self)
        redo_action.triggered.connect(self._redo)
        edit_menu.addAction(redo_action)
        self._hk_action_redo_menu = redo_action
        edit_menu.addSeparator()
        delete_action = QAction("Delete Selected Shape", self)
        delete_action.setToolTip("Deletes the selected shape in Create/Import. Undoable.")
        delete_action.triggered.connect(self._delete_selected_shape)
        edit_menu.addAction(delete_action)
        self._hk_action_delete_selected = delete_action
        duplicate_action = QAction("Duplicate Selected Shape", self)
        duplicate_action.setToolTip("Clones the selected shape a short offset away. Undoable.")
        duplicate_action.triggered.connect(self._duplicate_selected_shape)
        edit_menu.addAction(duplicate_action)
        self._hk_action_duplicate_selected = duplicate_action

        view_menu = menu_bar.addMenu("&View")
        zoom_fit_action = QAction("Zoom to Fit", self)
        zoom_fit_action.setToolTip("Fit the design to the view.")
        zoom_fit_action.triggered.connect(self._on_zoom_to_fit_clicked)
        view_menu.addAction(zoom_fit_action)
        self._hk_action_zoom_fit = zoom_fit_action
        reset_view_action = QAction("Reset View", self)
        reset_view_action.setToolTip("Fit the view and clear rulers and any selection highlight.")
        reset_view_action.triggered.connect(self._on_menu_reset_view)
        view_menu.addAction(reset_view_action)
        self._hk_action_reset_view = reset_view_action

    def _new_junction(self):
        """File > New Junction (Ctrl+N): clears the current custom-shape
        design and switches back to the parametric (non-imported) view,
        so you can start a fresh junction from scratch. Confirms first
        since this touches real design state -- though it can still be
        undone afterward with Ctrl+Z, since it goes through the same
        _push_undo_snapshot the rest of the shape editor already uses,
        rather than bypassing undo history."""
        if self.electrode_scene.shapes or self._imported_junction is not None:
            reply = QMessageBox.question(
                self, "New Junction",
                "Clear the current design and start a new junction?\n\n"
                "This can be undone afterward with Ctrl+Z.",
                QMessageBox.Yes | QMessageBox.No, QMessageBox.No)
            if reply != QMessageBox.Yes:
                return
        self._push_undo_snapshot()
        self.electrode_scene.shapes = []
        self.electrode_scene.selected_id = None
        self._imported_junction = None
        self._imported_report = None
        self._display_source = "parametric"
        # A fresh design has no generation history of its own yet -- clear
        # these (and the design-library link/_recipe_builder_
        # current_path too -- see self._batch_recipe_links' own
        # declaration for the full rationale) so a later "Generate
        # Recipe" click's duplicate-and-patch logic (generated_recipe_export.
        # resolve_and_write), or a Final Diagnostic export, never
        # mistakes the PREVIOUS design's own recipe links for this new
        # one's. new_key=None (a parametric design has no project-file
        # identity) also sets self._active_design_id = None itself --
        # New Junction starts a genuinely fresh design, so an immediate
        # File > Save Design... afterward shouldn't silently overwrite
        # whatever was loaded/saved before.
        self._switch_active_project_recipe_links(
            getattr(self, "_recipe_link_active_project_key", None), None)
        self._create_import_cached_junction = None
        self._create_import_cached_report = None
        self._rulers = []
        self._ruler_pending_start = None
        self._selected_junction_id = None
        self._layer_highlight = None
        self._marquee_selection = None  # a brand-new design has no shapes in common with
                                           # whatever ad hoc batch (if any) was selected before
        self._create_import_force_fit = True  # a brand-new design has nothing in common with
                                                  # whatever the view was fit/panned/zoomed to before
        self._update_preview()

    def _menu_import(self, source_idx: int):
        """File > Import GDS.../Import KLayout Script...: reuses the
        Create / Import tab's own 'Import a Design' card instead of
        duplicating its GDS-layer-picking/cell-picking UI in a separate
        flow. Jumps to that tab first if it isn't already active, selects
        the right source radio, then opens the exact same file-browse
        dialog the card's own 'Browse...' button uses."""
        if self.main_stack.currentIndex() != 1:  # Create / Import's row index
            self.nav_list.setCurrentRow(1)
        button = self.import_source_group.button(source_idx)
        if button is not None and not button.isChecked():
            button.setChecked(True)
            self._on_import_source_changed(source_idx)
        self._on_import_browse()

    def _on_menu_reset_view(self):
        """View > Reset View -- broader than Zoom to Fit (above it in
        the menu): also clears ruler measurements and any shape/layer
        selection highlight, so the canvas goes back to a clean,
        nothing-selected, fit-to-content look. Zoom to Fit only resets
        pan/zoom and leaves selection/rulers alone -- these are
        deliberately different actions, not duplicates of each other.

        Fixes a bug where this used to do nothing at
        all for the Recipe tab's own layout (a splitter pane or table
        column resized far past reasonable, see _reset_recipe_tab_layout's
        own docstring for the two real causes). Reset View is the one
        View-menu action that already means "get this tab back to a
        sane, predictable state" app-wide, so it now also restores the
        Recipe tab's splitter/column layout -- harmless to call
        regardless of which tab is currently active."""
        self._rulers = []
        self._ruler_pending_start = None
        self.electrode_scene.selected_id = None
        self._selected_junction_id = None
        self._layer_highlight = None
        self._marquee_selection = None  # Reset View clears every selection state,
                                           # this ad hoc batch included
        self._create_import_force_fit = True  # see _create_import_view_kwargs's docstring --
                                                  # ordinary redraws now PRESERVE the current view,
                                                  # so Reset View needs to explicitly ask for a fresh
                                                  # fit rather than getting one automatically
        self._update_preview()
        self._reset_recipe_tab_layout()

    def _on_zoom_to_fit_clicked(self):
        """View > Zoom to Fit / the toolbar's Zoom to Fit button: unlike
        Reset View, this only re-fits the Create/Import view, leaving
        selection/rulers/layer-highlight untouched. Used to just be
        self._update_preview directly, back when every redraw auto-fit
        the view anyway (see _create_import_view_kwargs's docstring for
        why that changed -- ordinary redraws now preserve pan/zoom, so
        this action needs to explicitly ask for a fresh fit instead)."""
        self._create_import_force_fit = True
        self._update_preview()

    # ------------------------------------------------------------------
    # Settings (gear icon, top-right corner of every tab) -- theme
    # toggle, Chamber Reference Model, and a couple of small recovery
    # actions. See _apply_theme()'s docstring for the non-destructive
    # theming mechanism this all builds on.
    # ------------------------------------------------------------------
    def _themed(self, widget, style_fn):
        """Applies style_fn() to widget right now (identical to the old
        widget.setStyleSheet(style_fn()) this replaced everywhere), and
        remembers the (widget, style_fn) pair so a later theme toggle can
        re-run style_fn() (which reads the CURRENT color constants) and
        reapply it to this SAME widget -- no widget is ever rebuilt or
        replaced, so nothing it holds (typed text, selection state, etc)
        can be lost by a theme switch. See _apply_theme()."""
        widget.setStyleSheet(style_fn())
        self._themed_widgets.append((widget, style_fn))
        return widget

    def _prune_themed_widgets(self, roots=()):
        """Fixes a crash that occurred most often when clicking 'Run angle
        diagnostic' or 'Run Simulation' after loading and running
        the simulation for several junctions in a row -- typically by the
        third or fourth design load. Root
        cause, found via gc.get_objects() widget-type histogramming
        (QLabel/QPushButton/QLineEdit/QFrame/QMenu/QToolButton counts
        climbing by dozens on every single call and never coming back
        down, even after app.processEvents() + gc.collect()):
        self._themed_widgets (see _themed's own docstring) is APPEND-
        ONLY -- every themed label/button/frame ever created anywhere
        in the app's lifetime is remembered forever so retheme() can
        restyle it later, but nothing ever pruned an entry once its
        widget was torn down by a later rebuild. Both
        _populate_sim_feature_sequence and _rebuild_sim_angles_tree
        fire repeatedly during ordinary use (Run Angle Diagnostic, Run
        Simulation, and loading a new design each trigger several),
        theming dozens of brand-new widgets on every call while
        deleteLater()-ing the previous batch -- so _themed_widgets grew
        by dozens of now-dead (widget, style_fn) tuples on every single
        rebuild, unboundedly, for the app's whole lifetime. That list
        holding a live Python reference to every one of them is exactly
        what kept a dead-C++-side widget's Python wrapper (and its
        style_fn closure -- itself capable of capturing yet more
        objects) reachable and un-collectible; after enough rebuilds
        (each design load fires several), the accumulated dead-widget
        list is large enough to actually exhaust memory -- matching the
        observed pattern of a crash appearing only after
        loading roughly the third or fourth design in a row.

        Call this right before deleteLater()-ing a batch of widgets
        about to be replaced, passing that batch's own top-level
        widgets as `roots` (e.g. the per-feature `block`/insert-step
        `row` widgets in _populate_sim_feature_sequence, or the tree's
        prior top-level items' widgets in _rebuild_sim_angles_tree).
        Strips out every _themed_widgets entry whose widget IS one of
        `roots`, is a descendant of one of them (checked via
        QWidget.isAncestorOf -- still valid here since the real
        deletion hasn't happened yet, deleteLater() only schedules it),
        or whose underlying Qt object is already gone (a defensive
        catch-all for any stale entry that slipped in some other way,
        e.g. left over from before this fix) -- keeping the list
        bounded by "widgets currently on screen" instead of "every
        widget ever created"."""
        if not self._themed_widgets:
            return
        live_roots = []
        for r in roots:
            try:
                r.objectName()  # cheap liveness probe; raises RuntimeError if already destroyed
            except RuntimeError:
                continue
            live_roots.append(r)

        def _should_drop(widget):
            try:
                widget.objectName()
            except RuntimeError:
                return True  # already-dead widget -- drop it
            for r in live_roots:
                try:
                    if widget is r or r.isAncestorOf(widget):
                        return True
                except RuntimeError:
                    return True
            return False

        self._themed_widgets = [(w, fn) for (w, fn) in self._themed_widgets if not _should_drop(w)]

    def _collect_layout_widgets(self, layout):
        """Recursively collects every QWidget contained anywhere inside
        `layout`, including ones nested inside a CHILD layout added via
        addLayout() rather than wrapped in its own container widget --
        see _rebuild_recipe_panel_dynamic_fields's docstring for why
        this matters: for a QLayoutItem that wraps a child layout (as
        opposed to a widget), item.widget() is always None -- the item
        IS the layout, not a widget -- so a naive `[layout.itemAt(i).
        widget() for i in range(layout.count())]` scan silently misses
        every widget added to a plain `row = QHBoxLayout(); ...;
        layout.addLayout(row)` pattern (this file's own established way
        of building a one-line label+field row without a dedicated
        QFrame/QWidget container for it)."""
        found = []
        def _walk(lay):
            for i in range(lay.count()):
                item = lay.itemAt(i)
                w = item.widget()
                if w is not None:
                    found.append(w)
                    continue
                child_layout = item.layout()
                if child_layout is not None:
                    _walk(child_layout)
        _walk(layout)
        return found

    def _build_settings_gear(self):
        """A small gear icon pinned to the MENU BAR's own top-right
        corner (QMenuBar.setCornerWidget) -- the menu bar is shared
        app-wide and is never hidden or rebuilt per tab (unlike the
        toolbars, which _on_nav_changed shows/hides per section), so this
        stays glued to the exact same spot regardless of which real tab --
        or the hidden Settings/Chamber Reference Model page -- is
        currently showing."""
        # Quantum-styled to match the rest of the chrome -- same
        # hover-glow/pulse chip language as every other QuantumToolButton
        # on the main toolbar. No bound QAction here (it's a menu button,
        # not a tool), so its own .setToolTip/.setMenu/.setPopupMode calls
        # below are unchanged; only the widget class + icon handling
        # changed (QuantumToolButton manages/retints its own icon on
        # retheme(), so the old manual self._themed_icons registration is
        # removed -- keeping both would double-tint on theme toggle).
        self.settings_button = QuantumToolButton("fa5s.cog", parent=self)
        self.settings_button.setToolTip("Settings")

        menu = QMenu(self.settings_button)
        self._themed(menu, lambda: (
            f"QMenu {{ background-color: {PANEL_COLOR}; color: {TEXT_COLOR}; "
            f"border: 1px solid {BORDER_COLOR}; border-radius: 10px; padding: 6px; }} "
            f"QMenu::item {{ padding: 6px 22px 6px 14px; border-radius: 6px; margin: 1px 2px; }} "
            f"QMenu::item:selected {{ background-color: {ACCENT_COLOR}; color: {PANEL_COLOR}; }}"
        ))

        self.theme_toggle_action = QAction("Switch to Light Mode", self)
        self.theme_toggle_action.triggered.connect(self._toggle_theme)
        menu.addAction(self.theme_toggle_action)
        menu.addSeparator()

        # Process/instrument configuration
        # (resist stack, the alpha/linewidth calculator, and eventually
        # process parameters) consolidates into one Settings page rather
        # than living scattered across tabs -- see _build_settings_tab.
        # Chamber Reference Model is now a section inside it; kept as its
        # own quick-access menu entry too since it's used mid-workflow
        # (Test Angle, recipe angle links) far more often than the
        # configuration sections are.
        settings_action = QAction("Settings...", self)
        settings_action.setToolTip("Resist stack, the linewidth/alpha calculator, and other "
                                    "process configuration that other tabs read from.")
        settings_action.triggered.connect(lambda: self._show_settings_tab("Resist Stack & Calculator"))
        menu.addAction(settings_action)

        chamber_ref_action = QAction("Chamber Reference Model", self)
        chamber_ref_action.setToolTip("Standalone chamber view for testing alpha/theta/reference positions.")
        chamber_ref_action.triggered.connect(self._show_chamber_reference_tab)
        menu.addAction(chamber_ref_action)
        menu.addSeparator()

        reset_layout_action = QAction("Reset Window Layout", self)
        reset_layout_action.setToolTip("Restore hidden panels and docks for the current tab.")
        reset_layout_action.triggered.connect(self._reset_window_layout)
        menu.addAction(reset_layout_action)

        menu.aboutToShow.connect(self._refresh_settings_menu)
        self.settings_button.setMenu(menu)
        self.settings_button.setPopupMode(QToolButton.InstantPopup)
        self.settings_menu = menu

        self.menuBar().setCornerWidget(self.settings_button, Qt.TopRightCorner)

    def _refresh_settings_menu(self):
        """Runs right before the Settings menu opens (aboutToShow) so its
        theme-toggle label always reflects the CURRENT mode, however it
        was last changed."""
        self.theme_toggle_action.setText(
            "Switch to Light Mode" if self._theme_mode == "dark" else "Switch to Dark Mode"
        )

    def _toggle_theme(self):
        self._apply_theme("light" if self._theme_mode == "dark" else "dark")

    def _reset_window_layout(self):
        """Recovery action: re-shows the Contents nav dock (its own 'X'
        button only hides it, same as any QDockWidget) and re-runs the
        current tab's own toolbar/dock visibility logic, in case anything
        ended up stuck hidden. Leaves window size/position untouched --
        this is about visibility, not geometry."""
        self.nav_dock.setVisible(True)
        self._on_nav_changed(self.main_stack.currentIndex())

    def _apply_theme(self, mode: str):
        """Switches the whole app between "dark" and "light" WITHOUT
        rebuilding or replacing a single widget -- see the comment on
        self._themed_widgets in __init__ for why: a full rebuild risks
        silently wiping live user data (typed fields, spoken/typed
        measurement readings) that doesn't all have a shadow copy in
        self state.

        Three independent mechanisms get refreshed here, matching the
        three ways a color constant gets "baked" into something static:
          1. QSS strings (app-level AND the ~110 individual widgets
             registered via self._themed()) -- both are just regenerated
             from the NEW constant values and reapplied to the same
             widgets/QApplication.
          2. qtawesome QIcon objects (self._themed_icons) -- rebuilt and
             re-set onto the same QAction/QToolButton objects.
          3. matplotlib figures -- these are the ONE mechanism that's
             already reactive by default (draw functions read the color
             constants as plain module globals at draw time -- see
             chamber_plotting.py/parametric_junction_view.py), so mutating the constants
             below is sufficient on its own EXCEPT for each Figure's own
             .set_facecolor(), which is baked once at construction and
             needs an explicit redraw to pick up the change. That's what
             the per-tab redraw calls below are for -- each one is a
             pre-existing, already-safe-to-call-anytime method (verified
             individually: none of them reset user-facing state like the
             Deposition Slideshow's current step).
        """
        if mode == self._theme_mode:
            return
        values = _LIGHT_VALUES if mode == "light" else _DARK_VALUES
        globals().update(values)
        self._theme_mode = mode

        # 1a. Other modules' own color constants (each owns and mutates
        # its own copies -- see chamber_plotting.apply_theme / parametric_junction_view.
        # apply_theme / imported_junction_view.apply_theme's docstrings
        # for why a shared import can't be used here).
        chamber_plotting.apply_theme(mode)
        imported_junction_view.apply_theme(mode)

        # 1b. App-level QSS (covers every widget WITHOUT its own inline
        # stylesheet -- Qt re-polishes them all automatically) + every
        # individually-registered widget's own inline stylesheet.
        QApplication.instance().setStyleSheet(_build_base_qss())
        for widget, style_fn in list(self._themed_widgets):
            try:
                widget.setStyleSheet(style_fn())
            except RuntimeError:
                pass  # underlying Qt object already destroyed

        # 2. Icons.
        for target, icon_name, active in list(self._themed_icons):
            try:
                icon = (qta.icon(icon_name, color=TEXT_COLOR, color_active=ACCENT_COLOR) if active
                        else qta.icon(icon_name, color=TEXT_COLOR))
                target.setIcon(icon)
            except RuntimeError:
                pass

        # 2b. QuantumToolButton's own cached idle/hover/checked/disabled
        # icon variants (built once from icon_name at construction time --
        # see its own _build_icons/retheme -- so, unlike a plain QAction's
        # single icon just above, these need their own explicit rebuild
        # or they'd keep showing the OLD theme's colors indefinitely).
        for btn in list(QuantumToolButton._live_instances):
            try:
                btn.retheme()
            except RuntimeError:
                pass  # underlying Qt object already destroyed

        # 3. matplotlib figures this window owns directly, plus every
        # live _ChamberPreviewWidget instance (Simulate Design's inline
        # preview, one per Slideshow step, and the Chamber Reference
        # Model page all share that one class -- see its own retheme()).
        self._update_preview()

        # Fixes a bug where switching to light mode left
        # a graph still showing dark mode until the view was reset. Every
        # canvas below used .draw_idle() -- correct for a hot/frequent
        # redraw path (coalesces bursts of redraws into one, deferred to
        # the next Qt event-loop tick), but a theme toggle is a rare,
        # deliberate action where that deferral is pure downside: it
        # leaves a window where the OLD (wrong-theme) pixels are still
        # what's on screen, until whatever next nudges the event loop --
        # which is why Reset View's
        # own _update_preview() call happened to fix it, since it's exactly such a nudge.
        # .draw() forces the redraw to happen synchronously, right here,
        # so every canvas's pixels are already correct the instant this
        # method returns -- a few extra milliseconds of blocking work is
        # invisible for a manual, infrequent action like this one.
        if hasattr(self, "create_import_fig"):
            self.create_import_fig.set_facecolor(BG_COLOR)
            self.create_import_ax.set_facecolor(BG_COLOR)
            self.create_import_canvas.draw()
            self._redraw_create_import_overlay()  # no-op if nothing imported yet -- already guarded

        if hasattr(self, "sim_fig"):
            self.sim_fig.set_facecolor(BG_COLOR)
            self.sim_ax.set_facecolor(BG_COLOR)
            self.sim_canvas.draw()
            if self._sim_cached_junction is not None:
                self._update_simulate_preview(self._sim_cached_junction, self._sim_cached_report)

        if hasattr(self, "slideshow_fig"):
            self.slideshow_fig.set_facecolor(BG_COLOR)
            self.slideshow_ax.set_facecolor(BG_COLOR)
            self.slideshow_canvas.draw()
            self._slideshow_draw_reference()
            if hasattr(self, "_slideshow_steps"):
                self._slideshow_render_step()  # preserves the current step index, unlike
                                                  # _on_slideshow_refresh (which reloads from
                                                  # scratch and would jump back to step 0)
            self.slideshow_canvas.draw()

        if hasattr(self, "interp_fig"):
            self.interp_fig.set_facecolor(BG_COLOR)
            self.interp_ax.set_facecolor(BG_COLOR)
            if self._interp_last_result is not None:
                self._interp_draw_main_plot(self._interp_last_dataset, self._interp_last_result)
            else:
                self._interp_draw_placeholder(self.interp_ax)
            self.interp_canvas.draw()

        if hasattr(self, "interp_compare_fig"):
            self.interp_compare_fig.set_facecolor(BG_COLOR)
            self.interp_compare_ax.set_facecolor(BG_COLOR)
            if self._interp_last_compare_results:
                self._on_interp_compare_plot()
            else:
                self._interp_draw_placeholder(self.interp_compare_ax)
            self.interp_compare_canvas.draw()

        for w in list(_ChamberPreviewWidget._live_instances):
            try:
                w.retheme()
            except RuntimeError:
                pass  # underlying Qt object already destroyed

        # Front Page hero: circuit backdrop + app icon (both generated
        # SVG, not static assets -- see _FrontPageBackdrop).
        for w in list(_FrontPageBackdrop._live_instances):
            try:
                w.retheme()
            except RuntimeError:
                pass  # underlying Qt object already destroyed

        # The Front Page's app-mark logo and shortcut cards each cache/
        # derive their own non-QSS state the same way QuantumToolButton
        # does, so a theme change needs to re-apply to every live
        # instance of each, not just newly created ones.
        for w in list(QuantumAppIcon._live_instances):
            try:
                w.retheme()
            except RuntimeError:
                pass  # underlying Qt object already destroyed

        for c in list(QuantumCard._live_instances):
            try:
                c.retheme()
            except RuntimeError:
                pass  # underlying Qt object already destroyed

        # The remaining-buttons pass: secondary pills, segmented-choice
        # groups, and the two hero action buttons all paint straight
        # from the live color globals already (no cached QIcon/QSS to
        # rebuild), so retheme() here is just "repaint" -- but they
        # still need the call, or they'd keep showing stale pixels
        # until something else happens to repaint them.
        for w in list(QuantumPillButton._live_instances):
            try:
                w.retheme()
            except RuntimeError:
                pass  # underlying Qt object already destroyed

        for w in list(QuantumSegmentButton._live_instances):
            try:
                w.retheme()
            except RuntimeError:
                pass  # underlying Qt object already destroyed

        for w in list(QuantumActionButton._live_instances):
            try:
                w.retheme()
            except RuntimeError:
                pass  # underlying Qt object already destroyed

        if hasattr(self, "settings_menu"):
            self._refresh_settings_menu()

    # ------------------------------------------------------------------
    def _build_toolbar(self):
        """Icon-only toolbar, Inkscape-style -- the icon itself is the
        button (no text label alongside it); hovering shows a tooltip
        with what it does. qtawesome gives Font-Awesome-style icons for
        free, no hand-drawn assets needed."""
        toolbar = QToolBar("Tools")
        toolbar.setMovable(False)
        toolbar.setIconSize(toolbar.iconSize() * 1.3)
        self.addToolBar(toolbar)
        self.main_toolbar = toolbar  # stored so it can be hidden when a
                                       # tab that doesn't use it is active
                                       # (e.g. Live Angle & Step Creator)

        # Selection/navigation tools -- mutually exclusive (one active at a time)
        self.tool_group = QActionGroup(self)
        self.tool_group.setExclusive(True)

        def _tool_action(icon_name, tooltip, checked=False):
            action = QAction(qta.icon(icon_name, color=TEXT_COLOR, color_active=ACCENT_COLOR), "", self)
            action.setToolTip(tooltip)
            action.setCheckable(True)
            action.setChecked(checked)
            self.tool_group.addAction(action)
            # Gives the remaining toolbar buttons a matching custom style:
            # QuantumToolButton binds to this SAME action via Qt's own
            # setDefaultAction() (see its own docstring) -- every existing
            # exclusivity/checked/enabled/tooltip wire-up above is
            # completely untouched; only the visual presentation changes
            # from toolbar.addAction's plain auto-QToolButton to this
            # custom-painted one.
            btn = QuantumToolButton(icon_name, action, toolbar)
            toolbar.addWidget(btn)
            self._themed_icons.append((action, icon_name, True))
            return action

        # Undo/Redo as primary, always-visible toolbar buttons -- not part
        # of the exclusive tool_group above (they're one-off actions, not
        # a mode to switch into, so not checkable). Enabled state tracks
        # whether the stacks actually have anything in them.
        self.action_undo = QAction(qta.icon("fa5s.undo", color=TEXT_COLOR), "", self)
        self.action_undo.setToolTip("Undo (Ctrl+Z)")
        self.action_undo.triggered.connect(self._undo)
        toolbar.addWidget(QuantumToolButton("fa5s.undo", self.action_undo, toolbar))
        self._themed_icons.append((self.action_undo, "fa5s.undo", False))
        self.action_redo = QAction(qta.icon("fa5s.redo", color=TEXT_COLOR), "", self)
        self.action_redo.setToolTip("Redo (Ctrl+Shift+Z)")
        self.action_redo.triggered.connect(self._redo)
        toolbar.addWidget(QuantumToolButton("fa5s.redo", self.action_redo, toolbar))
        self._themed_icons.append((self.action_redo, "fa5s.redo", False))
        toolbar.addSeparator()

        # The rubber-band select tool is a feature that comes with the
        # 'Select' button itself, rather than its own separate button --
        # select is meant to select either single shapes or rubber-band
        # whatever amount of shapes wanted, while pan/move stays a
        # separate button. This reverses an earlier separate
        # action_marquee toolbar button -- Select now does both jobs by
        # itself: click a shape to select just it (unchanged), or click-
        # drag starting from EMPTY canvas to rubber-band a batch (see
        # _on_canvas_press's own empty-click branch). Pan stays its own
        # separate tool.
        self.action_select = _tool_action("fa5s.mouse-pointer", "Select (click a shape, or click-drag "
                                           "an empty area to rubber-band select a batch)", checked=True)
        self.action_pan = _tool_action("fa5s.hand-paper", "Pan")
        self.action_pan.toggled.connect(lambda checked: checked and self._cancel_marquee_drag_if_active())
        toolbar.addSeparator()

        # Shape tools -- wired to shape_editor.ShapeScene, same model the
        # Tk version's "+ Rectangle" button used, just as real exclusive
        # toolbar tools now: select the tool, then click the canvas to
        # place a shape of that kind.
        self.action_rect = _tool_action("fa5s.square", "Rectangle")
        self.action_circle = _tool_action("fa5s.circle", "Circle / Oval")
        self.action_polygon = _tool_action("fa5s.draw-polygon", "Polygon (click each vertex, double-click to finish)")
        self.action_ruler = _tool_action("fa5s.ruler", "Ruler (click one point, then another, to measure the distance)")
        self.action_select.toggled.connect(lambda checked: checked and self._set_pending_shape_kind(None))
        self.action_rect.toggled.connect(lambda checked: checked and self._set_pending_shape_kind("rect"))
        self.action_circle.toggled.connect(lambda checked: checked and self._set_pending_shape_kind("circle"))
        self.action_polygon.toggled.connect(lambda checked: checked and self._set_pending_shape_kind("polygon"))
        self.action_ruler.toggled.connect(self._on_ruler_toggled)
        toolbar.addSeparator()

        # Zoom controls -- not part of the exclusive tool group, these are
        # one-shot actions, not modes
        zoom_in = QAction(qta.icon("fa5s.search-plus", color=TEXT_COLOR), "", self)
        zoom_in.setToolTip("Zoom In")
        zoom_in.triggered.connect(lambda: self._zoom_step(0.85))
        toolbar.addWidget(QuantumToolButton("fa5s.search-plus", zoom_in, toolbar))
        self._themed_icons.append((zoom_in, "fa5s.search-plus", False))

        zoom_out = QAction(qta.icon("fa5s.search-minus", color=TEXT_COLOR), "", self)
        zoom_out.setToolTip("Zoom Out")
        zoom_out.triggered.connect(lambda: self._zoom_step(1.0 / 0.85))
        toolbar.addWidget(QuantumToolButton("fa5s.search-minus", zoom_out, toolbar))
        self._themed_icons.append((zoom_out, "fa5s.search-minus", False))

        zoom_fit = QAction(qta.icon("fa5s.expand", color=TEXT_COLOR), "", self)
        zoom_fit.setToolTip("Zoom to Fit")
        zoom_fit.triggered.connect(self._on_zoom_to_fit_clicked)
        toolbar.addWidget(QuantumToolButton("fa5s.expand", zoom_fit, toolbar))
        self._themed_icons.append((zoom_fit, "fa5s.expand", False))
        toolbar.addSeparator()

        # These two used to live in
        # Create / Import's own "ACTIVE DESIGN" strip above the preview
        # canvas, which otherwise had nothing left to justify its own row
        # once the preview itself was widened to fill that space (see
        # draw_imported_junction_preview's aspect-fill fix). They were moved
        # here to keep them accessible once that strip was no longer needed.
        # Both only apply to Create / Import's own
        # canvas (create_import_ax) -- see _on_show_measurements_toggled/
        # _redraw_create_import_overlay/_clear_rulers -- so unlike the rest of
        # this shared toolbar they only show while that tab is active:
        # self.create_import_toolbar_widgets is toggled by _on_nav_changed
        # alongside the toolbar's own overall visibility.
        # Replaces the plain QSS
        # QPushButton with QuantumToggleButton -- a fully custom-painted,
        # animated 'quantum'-styled toggle: a fully custom-painted
        # pill (hover expand/retract, a faint sheen, a live-resonance
        # waveform glyph instead of a ruler, and two tiny Manhattan-routed
        # circuit-trace stubs with a traveling glow pulse, reusing the
        # exact same trace/via/pad motif _build_circuit_backdrop_svg
        # already uses for the Front Page hero). Drop-in compatible with
        # every call this app already makes on it (setCheckable/
        # setChecked/setCursor/setToolTip/the toggled signal/setText in
        # _on_show_measurements_toggled/isChecked) -- see its own
        # docstring for the full design writeup.
        self.show_measurements_toggle = QuantumToggleButton("Measurements: Off")
        self.show_measurements_toggle.setChecked(False)
        self.show_measurements_toggle.setToolTip("Toggle the automatic dimension-measurement overlay.")
        self.show_measurements_toggle.toggled.connect(self._on_show_measurements_toggled)
        measurements_toggle_action = toolbar.addWidget(self.show_measurements_toggle)
        # Part of the same "remaining
        # buttons in that bar" pass as QuantumToolButton itself: converted
        # from a plain text QPushButton to an icon-only QAction + button,
        # matching every other tool in this "icon is the button" toolbar
        # (see _build_toolbar's own docstring) instead of being the one
        # lingering text label next to the pill-shaped Measurements toggle.
        self.action_clear_rulers = QAction(qta.icon("fa5s.eraser", color=TEXT_COLOR), "", self)
        self.action_clear_rulers.setToolTip("Clear every ruler drawn on the preview.")
        self.action_clear_rulers.triggered.connect(self._clear_rulers)
        clear_rulers_btn = QuantumToolButton("fa5s.eraser", self.action_clear_rulers, toolbar)
        clear_rulers_action = toolbar.addWidget(clear_rulers_btn)
        self._themed_icons.append((self.action_clear_rulers, "fa5s.eraser", False))
        create_import_toolbar_sep = toolbar.addSeparator()
        self.create_import_toolbar_widgets = [measurements_toggle_action, clear_rulers_action, create_import_toolbar_sep]

        # Role-assignment tools: click the tool, then click a shape on the
        # canvas to (re)classify it.
        #
        # These were briefly reverted to
        # electrode-only (see the removed comment this replaces), then
        # restored for every feature type, since a shape can be
        # misidentified by the program as one thing when it's actually
        # another. That's a narrower, safer
        # use than the original "hand-design any junction feature from
        # scratch" framing this project tried and stepped back from --
        # this is explicitly a CORRECTION tool (fixing a misclassified
        # shape), not a design-freedom tool, but the toolbar mechanism
        # underneath is the same either way, so it's simply restored.
        role_finger = _tool_action("fa5s.grip-lines", "Mark as Finger (click a shape)")
        role_patch = _tool_action("fa5s.stamp", "Mark as Patch (click a shape)")
        role_plate = _tool_action("fa5s.layer-group", "Mark as Adhesion Plate (click a shape)")
        role_electrode = _tool_action("fa5s.bolt", "Mark as Electrode (click a shape)")
        role_substrate = _tool_action("fa5s.square-full", "Mark as Substrate (click a shape)")
        role_finger.toggled.connect(lambda checked: checked and self._set_pending_role("finger"))
        role_patch.toggled.connect(lambda checked: checked and self._set_pending_role("patch"))
        role_plate.toggled.connect(lambda checked: checked and self._set_pending_role("plate"))
        role_electrode.toggled.connect(lambda checked: checked and self._set_pending_role("electrode"))
        role_substrate.toggled.connect(lambda checked: checked and self._set_pending_role("substrate"))
        toolbar.addSeparator()

        save_snapshot_action = QAction(qta.icon("fa5s.camera", color=TEXT_COLOR), "", self)
        save_snapshot_action.setToolTip("Save Junction Snapshot (image + parameters)")
        save_snapshot_action.triggered.connect(self._on_save_snapshot)
        toolbar.addWidget(QuantumToolButton("fa5s.camera", save_snapshot_action, toolbar))
        self._themed_icons.append((save_snapshot_action, "fa5s.camera", False))

    # ------------------------------------------------------------------
    def _f(self, edit: QLineEdit, default: float) -> float:
        """Parses a QLineEdit as float, tolerating mid-typing states
        (empty, just '-', etc) by falling back to a default instead of
        raising -- keeps the live preview from crashing on every
        keystroke while you're still typing a number."""
        try:
            return float(edit.text())
        except ValueError:
            return default

    def _f_opt(self, edit: QLineEdit) -> Optional[float]:
        """Like _f, but for a genuinely OPTIONAL field (None means "not
        set -- auto-compute", the same convention horizontal_electrode_
        angle_deg/x_um/y_um already use): a blank or unparseable field
        returns None instead of a hardcoded fallback number."""
        try:
            return float(edit.text())
        except ValueError:
            return None

    def _minutes_opt(self, edit: QLineEdit) -> Optional[float]:
        """Like _f_opt, but for an OPTIONAL duration field that must
        accept the same "M:SS" format the generated recipe itself
        displays that duration in (e.g. the Complete Process table's
        "Time (mm:ss)" column, or a real "Wait" step's own param1) --
        fixes a bug where typing "1:30" into the
        Recipe Parameters panel's "Mill ... duration (min)" field (to
        mean 1 minute 30 seconds, exactly matching how that same
        duration is shown everywhere else in this app) silently did
        nothing -- the generated recipe kept showing the old duration
        unchanged. Root cause: that field's override was read with
        plain _f_opt (`float(edit.text())`), and `float("1:30")` raises
        ValueError, so the override was treated as an intentionally
        blank field ("leave as-is") rather than a typo -- the
        typed value was silently discarded with no error shown at all.
        A value containing ":" is now parsed the same way recipe_tree_
        export._mmss_to_seconds already parses a real "Wait" row's
        param1 (mm:ss, or h:mm:ss) and converted from seconds to
        minutes; anything else falls back to the original plain-decimal-
        minutes parsing (e.g. "1.5"), so both forms this app uses for a
        duration anywhere in its own UI are now accepted here too."""
        text = (edit.text() or "").strip()
        if not text:
            return None
        if ":" in text:
            try:
                pieces = [float(p) for p in text.split(":")]
            except ValueError:
                return None
            total_seconds = 0.0
            for piece in pieces:
                total_seconds = total_seconds * 60.0 + piece
            return total_seconds / 60.0
        try:
            return float(text)
        except ValueError:
            return None

    def _oxidation_time_min_or_default(self) -> float:
        """Reads the Recipe Parameters panel's "Oxidation time" field --
        blank or unparseable falls back to DesignParameters' own
        oxidation_time_min dataclass default (25.0), so a blank field
        defaults to 25 minutes.
        Read directly by _current_params() (not just overlaid
        at Generate-Recipe time) so a design's oxidation-time choice is
        actually captured by a saved DesignParameters snapshot -- see
        _apply_settings_to_ui, which restores it back into this same
        field."""
        default = DesignParameters().oxidation_time_min
        if not hasattr(self, "recipe_panel_oxidation_time_edit"):
            return default
        text = self.recipe_panel_oxidation_time_edit.text().strip()
        if not text:
            return default
        try:
            return float(text)
        except ValueError:
            return default

    def _alpha_mill_or_default(self) -> float:
        """Reads the Recipe Parameters panel's "Mill angle" field -- blank
        or unparseable falls back to DesignParameters' own alpha_mill
        dataclass default (50.0). Same pattern as
        _oxidation_time_min_or_default: read directly by _current_params()
        (not just overlaid at Generate-Recipe time) so a design's own mill
        angle choice actually round-trips through Design Library save/load
        -- see _apply_settings_to_ui, which restores it back into this same
        field. Mill angle is a user-alterable option under Recipe
        Parameters, defaulting to 50 degrees."""
        default = DesignParameters().alpha_mill
        if not hasattr(self, "recipe_panel_mill_angle_edit"):
            return default
        text = self.recipe_panel_mill_angle_edit.text().strip()
        if not text:
            return default
        try:
            return float(text)
        except ValueError:
            return default

    def _current_params(self) -> DesignParameters:
        """Builds a DesignParameters from all the wired Parameters panels."""
        return DesignParameters(
            electrode_shapes=list(self.electrode_scene.shapes),
            electrode_gap_um=self._f(self.electrode_gap_edit, -1.5),
            # Width/length/angle for the default (non-custom-shape)
            # electrode -- see _build_electrode_designer_panel. Shared
            # across both
            # fingers' electrodes, same as electrode_gap_um above.
            horizontal_electrode_w_um=(self._f(self.electrode_width_edit, 4.0)
                                        if hasattr(self, "electrode_width_edit") else 4.0),
            horizontal_electrode_h_um=(self._f(self.electrode_length_edit, 1.5)
                                        if hasattr(self, "electrode_length_edit") else 1.5),
            horizontal_electrode_angle_deg=(self._f_opt(self.electrode_angle_edit)
                                             if hasattr(self, "electrode_angle_edit") else None),
            vertical_electrode_w_um=(self._f(self.electrode_width_edit, 4.0)
                                      if hasattr(self, "electrode_width_edit") else 4.0),
            vertical_electrode_h_um=(self._f(self.electrode_length_edit, 1.5)
                                      if hasattr(self, "electrode_length_edit") else 1.5),
            vertical_electrode_angle_deg=(self._f_opt(self.electrode_angle_edit)
                                           if hasattr(self, "electrode_angle_edit") else None),
            deposit_first="horizontal" if self._deposit_first_index == 0 else "vertical",
            horizontal_finger_angle=self._f(self.h_angle_edit, 0.0),
            vertical_finger_angle=self._f(self.v_angle_edit, 270.0),
            horizontal_lw_nm=self._f(self.h_lw_edit, 200.0),
            vertical_lw_nm=self._f(self.v_lw_edit, 220.0),
            horizontal_length_um=self._f(self.h_len_edit, 5.0),
            vertical_length_um=self._f(self.v_len_edit, 5.0),
            overlap_target_um=self._f(self.overlap_edit, 1.5),
            has_adhesion_pads=self.adhesion_check.isChecked(),
            adhesion_plate_width_um=self._f(self.plate_w_edit, 1.0),
            adhesion_plate_height_um=self._f(self.plate_h_edit, 1.0),
            patch_integrated=self.patch_check.isChecked(),
            patch_count=int(self._f(self.patch_count_edit, 3)),
            patch_spacing_um=self._f(self.patch_spacing_edit, 1.0),
            patch_width_um=self._f(self.patch_w_edit, 0.5),
            patch_long_extension_um=self._f(self.patch_long_edit, 6.0),
            patch_short_extension_um=self._f(self.patch_short_edit, 1.8),
            patch_tip_margin_um=self._f(self.patch_tip_margin_edit, 2.0),
            patch_angle=self._f(self.patch_angle_edit, 45.0),
            # Metal/electrode metal/project name used to come from a
            # separate Settings page, with the Recipe tab's own panel only
            # overriding them for a single generation if non-blank.
            # Settings has since been removed -- the Recipe Parameters
            # panel's own widgets ARE the live value everywhere, not just
            # at Generate-Recipe time (this is also what feeds Interpret
            # Results' T_c default and the mill-duration-by-metal note).
            metal_type=(self.recipe_panel_metal_combo.currentText()
                        if hasattr(self, "recipe_panel_metal_combo") else "Al"),
            electrode_metal_type=(self.recipe_panel_electrode_metal_combo.currentText()
                                   if hasattr(self, "recipe_panel_electrode_metal_combo") else "Nb"),
            # For the alpha tilt, the generated recipe's angle comments are
            # wired to the actual angles chosen in the Predicted steps on
            # the Simulate Design tab. Reads Simulate Design's own live
            # "Active alpha" field (the value
            # that already drives the real shadow-casting geometry the
            # user is looking at) instead of the old, disconnected
            # Settings alpha_dep_edit -- so the generated recipe's tilt
            # comments always match the angle actually used to compute
            # the shadows the user approved. alpha_mill has no live
            # simulation counterpart (it's a fixed sidewall-mill
            # convention, deliberately independent of deposition alpha --
            # see DesignParameters.alpha_mill's own comment); it's a
            # user-alterable Recipe Parameters field of its own now (see
            # _alpha_mill_or_default), separate from Active alpha.
            alpha_deposition=(self._f(self.sim_alpha_override_edit, 30.0)
                               if hasattr(self, "sim_alpha_override_edit") else 30.0),
            # Mill angle is a user-alterable option under Recipe
            # Parameters, defaulting to 50 degrees. Read directly here (like
            # oxidation_time_min above) so it round-trips through Design
            # Library save/load, not just a per-generation override.
            alpha_mill=self._alpha_mill_or_default(),
            project_name=(self.recipe_panel_project_name_edit.text().strip()
                          if hasattr(self, "recipe_panel_project_name_edit") else ""),
            # Defaults to 25 minutes when no value is entered -- read
            # directly here (like project_name/metal above), not just overlaid at
            # Generate-Recipe time, so a design's own oxidation-time
            # choice is actually captured by _current_params() and
            # therefore really saved/restored with that design (see
            # _apply_settings_to_ui) rather than silently lost.
            oxidation_time_min=self._oxidation_time_min_or_default(),
            # These five fields used to never reach DesignParameters at
            # all -- editing pmma_edit/pmgi_edit on the Simulate Design tab
            # only redrew that tab's own live shadow preview, and there was
            # no margin/name field feeding this constructor at all, so
            # recipe generation (and anything sent to the LLM, which treats
            # this deterministic skeleton as ground truth) always silently
            # used the dataclass defaults. Wired here to fix that. Thickness/name come
            # from the LIVE Simulate Design tab fields (the actual current
            # design state); margin/names have no other live widget, so
            # Settings' own fields are the sole source.
            top_resist_name=(self.settings_top_name_edit.text().strip()
                              if hasattr(self, "settings_top_name_edit") and self.settings_top_name_edit.text().strip()
                              else DEFAULT_TOP_RESIST_NAME),
            pmma_thickness_nm=(self._f(self.pmma_edit, DEFAULT_TOP_RESIST_THICKNESS_NM)
                                if hasattr(self, "pmma_edit") else DEFAULT_TOP_RESIST_THICKNESS_NM),
            bottom_resist_name=(self.settings_bottom_name_edit.text().strip()
                                 if hasattr(self, "settings_bottom_name_edit") and self.settings_bottom_name_edit.text().strip()
                                 else DEFAULT_BOTTOM_RESIST_NAME),
            pmgi_thickness_nm=(self._f(self.pmgi_edit, DEFAULT_BOTTOM_RESIST_THICKNESS_NM)
                                if hasattr(self, "pmgi_edit") else DEFAULT_BOTTOM_RESIST_THICKNESS_NM),
            safety_margin_nm=(self._f(self.settings_margin_edit, DEFAULT_RESIST_SAFETY_MARGIN_NM)
                               if hasattr(self, "settings_margin_edit") else DEFAULT_RESIST_SAFETY_MARGIN_NM),
            # Deposition rate, oxidation pressure/time, Ti-gather
            # rate/duration, ion mill beam gas/voltage/current/accel/
            # duration, and the four per-pass deposition thickness
            # defaults are all now pure DesignParameters dataclass
            # defaults, since these process parameters are fixed
            # machine-configured values that don't require per-design
            # logic. Deliberately NOT passed here at all, so the dataclass's own
            # field default (recipe_generator.DesignParameters) is what
            # applies -- oxidation_time_min (25.0) and mill_duration_min
            # (1.0) still have real live overrides, just one level up:
            # oxidation_time_min via the Recipe Parameters panel's new
            # "Oxidation time" field (_current_recipe_panel_params), and
            # mill_duration_min per-pass via recipe_panel_mill_duration_
            # edits (_recipe_features_with_panel_overrides) -- both
            # already fall back to exactly these same dataclass defaults
            # when left blank. A user who wants a different deposition
            # rate/Ti-gather rate/mill beam setting for a real run now
            # hand-edits that value directly in the generated recipe's
            # own step cells, which is what persists across a fresh
            # regeneration (generated_recipe_export.py's duplicate-and-patch),
            # not a Settings-level default that silently applied to every
            # future design.
        )

    def _apply_settings_to_ui(self, params: DesignParameters):
        """If the user adjusts the settings for a design and saves the
        design, those specific settings are also saved: the SETTINGS-only
        subset of _apply_params_to_ui below -- metal types, deposition
        alpha, resist stack, and oxidation time -- factored out so it can
        be applied on its OWN, independent of the geometry fields
        (electrode_shapes, finger angles/lengths/linewidths, adhesion
        pads, patch layout). That split matters because an Imported
        (GDS) design has no use for the geometry fields at all (its
        geometry lives in the ImportedJunction, not DesignParameters)
        but these settings are exactly as real and exactly as worth
        saving/restoring as a Created design's -- see _save_current_design
        and _load_design_from_library, which now attach/restore a params
        snapshot for BOTH design sources, applying only this settings
        subset for an Imported one so its own geometry is left alone.

        Metal/electrode metal/project name/alpha/oxidation time now live
        on the Recipe Parameters panel and Simulate Design's Active alpha
        field instead of a separate Settings page, so this restores into
        THOSE widgets. Every other former Process Parameters field
        (deposition rate, Ti-gather rate/duration, mill beam gas/voltage/
        current/accel/duration, the four per-pass thickness defaults) no
        longer has any UI to restore into at all -- these are pure
        hardcoded DesignParameters defaults now (see _current_params'
        own comment) -- so a saved design's own values for those specific
        fields are simply not restored anywhere anymore; any real
        customization for those lives as a hand-edit on the generated
        recipe's own step cells instead, which persists on its own via
        generated_recipe_export.py's duplicate-and-patch regeneration."""
        if hasattr(self, "recipe_panel_metal_combo"):
            idx = self.recipe_panel_metal_combo.findText(params.metal_type)
            if idx >= 0:
                self.recipe_panel_metal_combo.setCurrentIndex(idx)
            else:
                self.recipe_panel_metal_combo.setCurrentText(params.metal_type)
        if hasattr(self, "recipe_panel_electrode_metal_combo"):
            electrode_metal = getattr(params, "electrode_metal_type", "Nb")
            idx = self.recipe_panel_electrode_metal_combo.findText(electrode_metal)
            if idx >= 0:
                self.recipe_panel_electrode_metal_combo.setCurrentIndex(idx)
            else:
                self.recipe_panel_electrode_metal_combo.setCurrentText(electrode_metal)
        if hasattr(self, "sim_alpha_override_edit"):
            self.sim_alpha_override_edit.setText(f"{params.alpha_deposition:g}")
        if hasattr(self, "recipe_panel_project_name_edit"):
            self.recipe_panel_project_name_edit.setText(params.project_name)
        if hasattr(self, "recipe_panel_oxidation_time_edit"):
            # Only shown as an explicit override if it actually differs
            # from the dataclass default -- a design that never touched
            # oxidation time should come back with the field blank (its
            # "25 (default)" placeholder doing the talking), not a
            # redundant explicit "25" that LOOKS hand-set but isn't.
            default_oxid = DesignParameters().oxidation_time_min
            oxid = getattr(params, "oxidation_time_min", default_oxid)
            if oxid is not None and abs(oxid - default_oxid) > 1e-9:
                self.recipe_panel_oxidation_time_edit.setText(f"{oxid:g}")
            else:
                self.recipe_panel_oxidation_time_edit.setText("")
        if hasattr(self, "recipe_panel_mill_angle_edit"):
            # Same "blank when at the default" convention as oxidation time
            # above -- a design that never touched mill angle restores as a
            # blank field, letting the "50 (default)" placeholder do the
            # talking instead of a misleadingly-explicit "50".
            default_mill = DesignParameters().alpha_mill
            mill = getattr(params, "alpha_mill", default_mill)
            if mill is not None and abs(mill - default_mill) > 1e-9:
                self.recipe_panel_mill_angle_edit.setText(f"{mill:g}")
            else:
                self.recipe_panel_mill_angle_edit.setText("")
        # Mirror of the new resist-stack fields _current_params() now
        # reads -- restores the exact stack a saved design was built
        # with, not whatever's currently sitting in the Simulate Design
        # tab from an unrelated design.
        if hasattr(self, "pmma_edit") and params.pmma_thickness_nm is not None:
            self.pmma_edit.setText(f"{params.pmma_thickness_nm:g}")
        if hasattr(self, "pmgi_edit") and params.pmgi_thickness_nm is not None:
            self.pmgi_edit.setText(f"{params.pmgi_thickness_nm:g}")
        if hasattr(self, "settings_margin_edit"):
            self.settings_margin_edit.setText(f"{params.safety_margin_nm:g}")
        if hasattr(self, "settings_top_name_edit") and params.top_resist_name:
            self.settings_top_name_edit.setText(params.top_resist_name)
        if hasattr(self, "settings_bottom_name_edit") and params.bottom_resist_name:
            self.settings_bottom_name_edit.setText(params.bottom_resist_name)

    def _apply_params_to_ui(self, params: DesignParameters):
        """The reverse of _current_params(): pushes a DesignParameters
        (e.g. one just loaded from the design library) back into every
        wired Parameters widget, plus the electrode canvas's own shape
        list -- so "Load Design" for a Created design restores a fully
        live, still-editable state, not just a static picture. Each
        widget's own textChanged/toggled wiring (see _tree_input_row and
        the individual connect() calls in the tab-1 builders) fires
        _update_preview as these are set, same as if the user had typed
        them; _set_display_source("parametric") at the end guarantees one
        final refresh even if a value happens to match its current text
        (no-op textChanged) and switches off of Imported display."""
        self.electrode_scene.shapes = copy.deepcopy(params.electrode_shapes)
        self.electrode_scene.selected_id = None
        self.electrode_gap_edit.setText(f"{params.electrode_gap_um:g}")
        # Restores the default electrode's width/length/angle the same
        # way the standoff gap already is -- reads back off the
        # horizontal_* fields (the two are kept in
        # sync by _current_params() writing both from these same shared
        # widgets, so either would do).
        if hasattr(self, "electrode_width_edit"):
            self.electrode_width_edit.setText(f"{params.horizontal_electrode_w_um:g}")
        if hasattr(self, "electrode_length_edit"):
            self.electrode_length_edit.setText(f"{params.horizontal_electrode_h_um:g}")
        if hasattr(self, "electrode_angle_edit"):
            self.electrode_angle_edit.setText(
                f"{params.horizontal_electrode_angle_deg:g}" if params.horizontal_electrode_angle_deg is not None else "")
        self._set_deposit_first_index(0 if params.deposit_first == "horizontal" else 1)
        self.h_angle_edit.setText(f"{params.horizontal_finger_angle:g}")
        self.v_angle_edit.setText(f"{params.vertical_finger_angle:g}")
        self.h_lw_edit.setText(f"{params.horizontal_lw_nm:g}" if params.horizontal_lw_nm is not None else "")
        self.v_lw_edit.setText(f"{params.vertical_lw_nm:g}" if params.vertical_lw_nm is not None else "")
        self.h_len_edit.setText(f"{params.horizontal_length_um:g}")
        self.v_len_edit.setText(f"{params.vertical_length_um:g}")
        self.overlap_edit.setText(f"{params.overlap_target_um:g}")
        self.adhesion_check.setChecked(params.has_adhesion_pads)
        self.plate_w_edit.setText(f"{params.adhesion_plate_width_um:g}")
        self.plate_h_edit.setText(f"{params.adhesion_plate_height_um:g}")
        self.patch_check.setChecked(params.patch_integrated)
        self.patch_count_edit.setText(str(params.patch_count))
        self.patch_spacing_edit.setText(f"{params.patch_spacing_um:g}")
        self.patch_w_edit.setText(f"{params.patch_width_um:g}")
        self.patch_long_edit.setText(f"{params.patch_long_extension_um:g}")
        self.patch_short_edit.setText(f"{params.patch_short_extension_um:g}")
        self.patch_tip_margin_edit.setText(f"{params.patch_tip_margin_um:g}")
        self.patch_angle_edit.setText(f"{params.patch_angle:g}")
        self._apply_settings_to_ui(params)
        self._set_display_source("parametric")

    def _update_preview(self):
        params = self._current_params()
        # NOTE: the old inline "fingers should be perpendicular" check
        # that used to live here (comparing only the two PARAMETRIC
        # design fields, so a real GDS import never got it at all) has
        # moved into _check_design_stage_warnings / the Design Warnings
        # banner below (the warning for junction fingers that aren't
        # perfectly orthogonal to each other belongs there instead), and
        # generalized there to work from each finger's own real geometry
        # so it now also fires for imports, not just parametric designs.

        if getattr(self, "_display_source", "parametric") == "imported" and self._imported_junction is not None:
            junction = self._imported_junction
            ji.apply_deposit_order(junction, self._deposit_first_index)  # Fixed
                                                                           # here: this was only
                                                                           # ever applied once, at
                                                                           # import time -- changing
                                                                           # Deposition Order
                                                                           # afterward silently left
                                                                           # Warning #2 stale until
                                                                           # the next re-import
            report = ji.compute_measurements(junction)
            self._imported_report = report
            self._shape_measurements = ji.measurements_by_stable_id(junction, report)
        else:
            junction = ji.from_design_parameters(params, include_fingers=True)
            ji.apply_deposit_order(junction, self._deposit_first_index)  # was only wired for
                                                                           # imports -- this is
                                                                           # why Warning #2 never
                                                                           # showed for the live
                                                                           # parametric design
            if self._param_shape_offsets:
                # Re-apply whatever
                # Nudge offsets were accumulated for this (index-keyed)
                # stable_id onto the freshly-rebuilt parametric junction,
                # BEFORE measurements are computed below -- a parametric
                # design has no persistent geometry of its own (it's
                # rebuilt from Design Parameters every call), so this is
                # the only place a Nudge on it can actually stick. See
                # _nudge_single_junction_member / _on_layer_nudge and
                # self._param_shape_offsets' own comment above.
                for f in junction.fingers:
                    off = self._param_shape_offsets.get(f.stable_id)
                    if off:
                        ji.translate_finger(f, off[0], off[1])
                for s in junction.other_shapes:
                    off = self._param_shape_offsets.get(s.stable_id)
                    if off:
                        ji.translate_shape(s, off[0], off[1])
                ji.recompute_derived_fields(junction)
            if self._param_shape_edits:
                self._apply_param_shape_edits(junction)
            if self._param_shape_deletions or self._param_shape_duplicates:
                # Delete and duplicate work on either a created junction or
                # an imported junction, generalized to also cover fingers
                # (previously patches/plates only -- see
                # _apply_param_shape_deletions/_materialize_param_shape_
                # duplicates' own docstrings): same "rebuilt from scratch
                # every call, so persist the EDIT and re-apply it"
                # strategy as the two blocks just above.
                self._apply_param_shape_deletions(junction)
                self._materialize_param_shape_duplicates(junction)
                # Caught by an end-to-end mouse-drag test
                # (claude/test_shape_editor_interactions.py) covering the
                # "duplicate a shape then drag it wherever you want" case: a
                # duplicate is created fresh, right here, on EVERY
                # rebuild -- so it never existed yet during the
                # _param_shape_offsets/_param_shape_edits passes above,
                # meaning any offset accumulated by dragging/nudging the
                # DUPLICATE itself (after it was created) was silently
                # recorded but never actually applied -- the duplicate
                # would snap back to its just-materialized position every
                # single redraw. Re-running the offset/edit application,
                # scoped to ONLY the newly-materialized duplicate
                # stable_ids, fixes this without double-applying either
                # pass's effect to the ORIGINAL fingers/shapes (which
                # already received theirs above, before any duplicate
                # existed).
                new_ids = set(self._param_shape_duplicates.keys())
                if self._param_shape_offsets and new_ids:
                    for f in junction.fingers:
                        if f.stable_id in new_ids:
                            off = self._param_shape_offsets.get(f.stable_id)
                            if off:
                                ji.translate_finger(f, off[0], off[1])
                    for s in junction.other_shapes:
                        if s.stable_id in new_ids:
                            off = self._param_shape_offsets.get(s.stable_id)
                            if off:
                                ji.translate_shape(s, off[0], off[1])
                if self._param_shape_edits and new_ids:
                    self._apply_param_shape_edits(junction, only_ids=new_ids)
                ji.recompute_derived_fields(junction)
            report = ji.compute_measurements(junction)
            self._junction = junction
            self._report = report
            self._shape_measurements = ji.measurements_by_stable_id(junction, report)

        for f in junction.fingers:
            # Only apply an explicit user override (from the role tools);
            # otherwise leave whatever role_override construction already
            # set (e.g. a custom shape placed AS a finger already carries
            # role_override="finger" from from_design_parameters -- don't
            # blindly erase that just because the user hasn't separately
            # used a role tool on this specific stable_id).
            if f.stable_id in self._role_overrides:
                f.role_override = self._role_overrides[f.stable_id]
        for s in junction.other_shapes:
            if s.stable_id in self._role_overrides:
                s.role_override = self._role_overrides[s.stable_id]

        self._update_warnings_panel(junction)
        self._update_design_warnings_panel(junction, report)
        self._update_create_import_preview(junction, report)  # Create / Import's own canvas draws
                                                            # this same computed state independently
        self._update_simulate_preview(junction, report)
        self._broadcast_chamber_junction_overlay(junction)  # Draws a
                                    # mini version of the design on the wafer view --
                                    # one shared push point (like every other _update_preview
                                    # consumer above) so every live chamber view (Simulate Design,
                                    # Deposition Slideshow, Settings > Chamber Reference Model)
                                    # always reflects whichever design is currently active.
        self._sync_property_fields()
        self._sync_shape_properties_panel()
        self._sync_nudge_scale_panel()
        self._sync_context_edit_stack()  # Keeps the unified Properties panel's
                                          # single-shape-vs-batch-layer editor in sync too
        self._rebuild_deposit_order_panel(junction)  # Keeps the Deposition Order
                                    # panel's button groups in sync with the CURRENT design's
                                    # fingers -- see _build_deposition_order_panel's own docstring.

    def _compute_mini_junction_overlay(self, junction):
        """Builds the small, wafer-local-frame polygon list _ChamberPreview
        Widget.set_junction_overlay/draw_top_down draw ON the wafer: a
        miniature version of the imported junction, scaled small enough
        to fit on the wafer shape, so the user can see what the actual
        junction design looks like in all three reference points, as
        well as the chosen angles. That last part
        is exactly why this function does NOT rotate anything itself: it
        only scales the design's own real (x, y) points down and centers
        them on the design's own bounding-box center, in the SAME local
        (x, y) frame theta already rotates everywhere else in this app
        (finger axis angles, theta_toward_patch_deg, the shadow math's
        own theta convention) -- draw_top_down then lifts these through
        THIS face's vis_z and the wafer's own real o.rotation_matrix,
        the exact transform it already applies to its own local axis
        ticks, so the mini pattern rotates/flips in lockstep with the
        wafer for every alpha/theta/reference combination for free,
        rather than needing a second, separately-tracked orientation
        that could drift out of sync with the real one.

        Uses each shape's OWN nominal (as-designed, pre-shadow) points --
        a small reference thumbnail, not a post-shadow render -- colored
        with the exact same SHADOW_KIND_BASE_COLOR finger/patch/plate
        hues Post-Shadow Result and every other shadow view already use,
        so the same design reads as the same colors everywhere in the
        app. Returns None for an empty/pointless design (nothing drawn,
        same as before this feature existed)."""
        polys = []
        pts_all = []
        for f in getattr(junction, "fingers", None) or []:
            pts = list(f.points)
            if len(pts) >= 3:
                polys.append((pts, SHADOW_KIND_BASE_COLOR.get("finger", "#bfe0ff")))
                pts_all.extend(pts)
        for s in getattr(junction, "other_shapes", None) or []:
            pts = list(s.points)
            if len(pts) >= 3:
                polys.append((pts, SHADOW_KIND_BASE_COLOR.get(s.kind, "#c9ccd6")))
                pts_all.extend(pts)
        if not polys or len(pts_all) < 3:
            return None
        xs = [p[0] for p in pts_all]
        ys = [p[1] for p in pts_all]
        cx, cy = (min(xs) + max(xs)) / 2.0, (min(ys) + max(ys)) / 2.0
        half_extent = max(max(xs) - min(xs), max(ys) - min(ys)) / 2.0
        if half_extent < 1e-9:
            return None
        # Kept deliberately small: the pattern's own larger half-dimension maps to
        # under a third of the wafer's radius, so it always sits as a
        # small, clearly-miniature pattern near the wafer's center,
        # regardless of the real design's actual size in microns.
        scale = (chamber_plotting.WAFER_RADIUS * 0.32) / half_extent
        return [{"points": [((px - cx) * scale, (py - cy) * scale) for (px, py) in pts], "color": color}
                for pts, color in polys]

    def _broadcast_chamber_junction_overlay(self, junction):
        """Pushes _compute_mini_junction_overlay's result to every LIVE
        _ChamberPreviewWidget instance -- same broadcast pattern
        MainWindow._apply_theme already uses for retheme(), so this
        needs no per-widget bookkeeping of its own and automatically
        covers any future consumer of this widget class too."""
        overlay = self._compute_mini_junction_overlay(junction)
        for w in list(_ChamberPreviewWidget._live_instances):
            try:
                w.set_junction_overlay(overlay)
            except RuntimeError:
                pass  # underlying Qt object already destroyed

    def _update_warnings_panel(self, junction):
        """Populates Simulate Design's always-visible Warnings panel with
        every finger's (and, for patch-integrated designs, every patch
        group's) explanation, so the user doesn't
        have to click each badge one at a time to see what it means."""
        if not junction.fingers:
            text = "No junction drawn yet."
        else:
            lines = []
            for i, f in enumerate(junction.fingers):
                label = ji.finger_display_label(i)
                verdict = {"none": "\u2713 Safe", "unknown": "? Unchecked"}.get(f.warning_source, "\u26a0 Caution")
                lines.append(f"Finger {label}: {verdict}")
                lines.append(ji.explain_finger_angle_choice(f))
                lines.append("")
            text = "\n".join(lines).strip()
        if hasattr(self, "sim_warnings_label"):
            self.sim_warnings_label.setText(text)

    def _on_save_snapshot(self):
        """Saves the current junction preview as an image, plus a
        companion text file with exactly what was used to create it --
        the import source for an imported junction, or every parametric
        field (including custom electrode shapes) for a designed one --
        so a saved snapshot is actually reproducible later, not just a
        picture."""
        path, _ = QFileDialog.getSaveFileName(self, "Save Junction Snapshot", "", "PNG image (*.png)")
        if not path:
            return
        if not path.lower().endswith(".png"):
            path += ".png"
        self.create_import_fig.savefig(path, facecolor=BG_COLOR, dpi=150)

        lines = []
        if self._display_source == "imported" and self._imported_junction is not None:
            lines.append("Source: Imported junction")
            lines.append(f"  {self._imported_junction.source_label}")
            report = self._imported_report
        else:
            lines.append("Source: Parametric design")
            params = self._current_params()
            for f in dataclasses.fields(params):
                value = getattr(params, f.name)
                if f.name == "electrode_shapes":
                    lines.append(f"  electrode_shapes: {len(value)} custom shape(s)")
                    for shp in value:
                        lines.append(f"    - {shp.kind} role={shp.role} cx={shp.cx:.3f} cy={shp.cy:.3f} "
                                     f"w={shp.w:.3f} h={shp.h:.3f} angle={shp.angle_deg:.1f}")
                else:
                    lines.append(f"  {f.name}: {value}")
            report = self._report
        if report is not None:
            lines.append("")
            lines.append("Measurements:")
            lines.append(build_measurement_caption(report))

        params_path = path[:-4] + "_parameters.txt"
        with open(params_path, "w") as fobj:
            fobj.write("\n".join(lines))

        QMessageBox.information(self, "Snapshot Saved",
                                f"Saved image to:\n{path}\n\nSaved parameters to:\n{params_path}")

    def _on_export_measurements_txt(self):
        """A standalone way to get the
        full measurement diagnostic -- every dimension, overlap, and
        spacing Create / Import's Measurements tree shows, plus the finer
        per-side/per-patch detail build_detailed_measurement_caption adds
        on top of that -- into a plain text file, for printing or filing
        alongside the recipe. Works for whichever design is currently
        active (imported or parametric), mirroring _on_ai_save_recipe's
        own QFileDialog + plain-write pattern rather than introducing a
        new one."""
        report = self._imported_report if self._display_source == "imported" else self._report
        if report is None:
            QMessageBox.information(self, "Nothing to export", "No junction measurements to export yet -- "
                                    "design or import a junction first.")
            return
        path, _ = QFileDialog.getSaveFileName(self, "Export Measurement Diagnostic", "junction_measurements.txt",
                                              "Text files (*.txt)")
        if not path:
            return
        if not path.lower().endswith(".txt"):
            path += ".txt"
        lines = [
            "Plassys Junction Measurement Diagnostic",
            f"Generated: {time.strftime('%Y-%m-%d %H:%M:%S')}",
            "",
            build_detailed_measurement_caption(report),
        ]
        with open(path, "w") as fobj:
            fobj.write("\n".join(lines))
        QMessageBox.information(self, "Exported", f"Saved detailed measurement diagnostic to:\n{path}")

    # NOTE: Recommended Deposition Angles are populated for Simulate
    # Design's own panel by _populate_sim_recommendations_tree, gated on
    # self._sim_angle_diagnostic_run (Run Angle Diagnostic) -- see that
    # method. There is no separate manual "recommendations panel" outside
    # Simulate Design any more.

    def _effective_shape_class(self, shape) -> str:
        """A shape's class for the Layers panel: its role_override if the
        user has reclassified it via the role-assignment tools, else its
        intrinsic kind ("finger" for an ImportedFinger, "patch"/"plate"
        for an ImportedShape by its .kind). This is why marking a finger
        as a patch via the toolbar also moves it under "Patches" in the
        layer tree -- one classification, not two separate systems."""
        if getattr(shape, "role_override", None):
            return shape.role_override
        if hasattr(shape, "axis_angle_deg"):  # ImportedFinger has no .kind field
            return "finger"
        return shape.kind  # ImportedShape: "patch" or "plate"

    def _on_layer_select(self, current, _previous):
        if current is None:
            return
        category = current.data(0, Qt.UserRole)
        self._set_layer_highlight(category)

    def _set_layer_highlight(self, category):
        self._layer_highlight = category
        self._update_preview()
        self._update_layer_batch_status()

    # Human-readable label for each layer category, used in the Batch
    # Edit status line -- kept in one place so it can't drift out of
    # sync with the tree item text in _build_docks.
    _LAYER_CATEGORY_LABELS = {
        "electrode": "Electrode",
        "finger": "Junction Fingers",
        "patch": "Patches",
        "plate": "Adhesion Plates",
        "__jj_all__": "Physical JJ (fingers + patches + plates)",
    }

    def _layer_scene_shapes(self, category):
        """electrode_scene shapes (custom rect/circle/polygon, placed
        with the toolbar) currently classified into the given layer --
        by their own .role, which the role-assignment toolbar can set to
        electrode/finger/patch/plate regardless of which placement tool
        originally created the shape."""
        if not category:
            return []
        wanted = ("finger", "patch", "plate") if category == "__jj_all__" else (category,)
        return [s for s in self.electrode_scene.shapes if s.role in wanted]

    def _layer_junction_members(self, category):
        """(fingers, shapes) from the currently-active junction (imported
        or parametric) classified into the given layer, by
        _effective_shape_class -- the SAME classification the canvas
        highlight/fade already uses, so "what's outlined on the canvas"
        and "what a layer-wide edit touches" always agree."""
        if not category:
            return [], []
        junction = self._imported_junction if self._display_source == "imported" else self._junction
        if junction is None:
            return [], []
        wanted = ("finger", "patch", "plate") if category == "__jj_all__" else (category,)
        fingers = [f for f in junction.fingers if self._effective_shape_class(f) in wanted]
        shapes = [s for s in junction.other_shapes if self._effective_shape_class(s) in wanted]
        return fingers, shapes

    # Which Batch Edit Layer page (see _build_docks) each layer category
    # maps to -- kept alongside _LAYER_CATEGORY_LABELS so the two can't
    # drift apart.
    _BATCH_EDIT_PAGE_BY_CATEGORY = {"finger": 1, "patch": 2, "plate": 3}

    def _update_layer_batch_status(self):
        """Refreshes the Layers dock's "Batch Edit Layer" card -- what's
        classified into the highlighted layer (status line) and which
        set of batch-editable fields apply (the stacked page). Unlike
        the old relative Scale factor (which
        only ever worked for an imported design's junction shapes), this
        absolute set-to-exact-value batch edit works identically for a
        created (parametric) design's fingers/patches/plates too, since
        it reuses the exact same per-shape write-back functions the
        single-shape Shape Properties card already uses for both design
        sources. Also resets every batch-edit field to blank -- a value
        typed for the PREVIOUS layer selection must never silently apply
        to a newly-selected, different layer."""
        if not hasattr(self, "batch_edit_status"):
            return
        category = self._layer_highlight
        page = self._BATCH_EDIT_PAGE_BY_CATEGORY.get(category, 0)
        self.batch_edit_stack.setCurrentIndex(page)
        for field in (self.batch_finger_lw_nm, self.batch_finger_length,
                      self.batch_finger_overlap, self.batch_patch_long_ext, self.batch_patch_short_ext,
                      self.batch_patch_lw, self.batch_patch_margin, self.batch_plate_length,
                      self.batch_plate_width):
            field.clear()
        if hasattr(self, "batch_patch_aggregate_label"):
            self.batch_patch_aggregate_label.setText("")
        if not category:
            self.batch_edit_status.setText("Select a layer above to batch-edit its shapes.")
            self.batch_edit_apply_btn.setEnabled(False)
            return
        label = self._LAYER_CATEGORY_LABELS.get(category, category)
        scene_shapes = self._layer_scene_shapes(category)
        fingers, shapes = self._layer_junction_members(category)
        n_junction = len(fingers) + len(shapes)
        n = len(scene_shapes) + n_junction
        if n == 0:
            self.batch_edit_status.setText(f"{label}: nothing in this layer yet.")
            self.batch_edit_apply_btn.setEnabled(False)
            return
        status_text = (f"{label}: {n} shape(s). Type exact values below and Apply "
                       f"to set every one of them to the same value.")
        if self._layer_has_rotatable_members(category):
            # A draggable rotation handle
            # appears on the canvas for whichever Layer is
            # highlighted, batch-rotating every shape in it together
            # (fingers stay orthogonal to each other -- see
            # _apply_layer_rotation_drag's own docstring).
            status_text += " Drag the dashed rotation ring around it on the canvas to batch-rotate this whole layer."
        self.batch_edit_status.setText(status_text)
        self.batch_edit_apply_btn.setEnabled(page != 0)
        if category == "patch" and hasattr(self, "batch_patch_aggregate_label"):
            self.batch_patch_aggregate_label.setText(self._patch_layer_aggregate_text(shapes))

    def _sync_context_edit_stack(self):
        """When a single shape is selected, its own toolbar for editing
        that shape is shown automatically; when a layer is selected at
        the top instead, the view switches automatically to batch-edit
        layer properties. Switches the unified
        Properties panel's context_edit_stack (built in _build_docks,
        right below the always-visible Layers tree) to whichever of the
        three pages is appropriate right now -- page 1 (the single-shape
        Shape Properties card) when a shape is individually selected,
        page 2 (the Batch Edit Layer card) when a Layer is highlighted
        instead, or page 0 (a plain placeholder note) when neither is
        true. Mirrors _current_edit_target()'s own priority exactly (a
        single selected shape always wins over a highlighted Layer), so
        whichever editor is showing here always agrees with what the
        Nudge && Scale card right below it is about to act on -- the two
        cards can never show controls for two DIFFERENT targets at once.

        Called at the tail of _update_preview, alongside
        _sync_property_fields/_sync_shape_properties_panel/
        _update_layer_batch_status, so it always reflects the very
        latest selection/highlight state -- exactly the same refresh
        point those three already use, just one more consumer of the
        same state."""
        if not hasattr(self, "context_edit_stack"):
            return
        single_selected = (self.electrode_scene.selected() is not None
                            or self._selected_junction_id is not None)
        if single_selected:
            self.context_edit_stack.setCurrentIndex(1)
        elif self._layer_highlight:
            self.context_edit_stack.setCurrentIndex(2)
        else:
            self.context_edit_stack.setCurrentIndex(0)

    def _patch_layer_aggregate_text(self, shapes):
        """Aggregate, read-only measurements that only make sense with
        the WHOLE Patches layer selected at once: edge-to-edge spacing
        between patches needs them all selected together to be
        meaningful, and likewise for the angle of patches (all the
        patches should run along the same two axial angles).

        Edge-to-edge spacing reuses the exact same, already-computed
        PatchGroupMeasurement.edge_to_edge_spacings_um the bottom
        Measurements dock already shows per finger (junction_import.
        compute_measurements) -- no new geometry, just surfaced here
        where a whole-layer view actually makes it meaningful, grouped
        by which finger each spacing belongs to. Angle-of-patches lists
        every DISTINCT patch axis angle (mod 180, since a line's
        direction is only defined up to 180 deg) found among the
        currently selected patches -- a real Manhattan design's patches
        should collapse to at most two such values (one per finger's own
        patch direction); more than two usually means a stray or
        misclassified shape got included."""
        if not shapes:
            return ""
        report = self._imported_report if self._display_source == "imported" else self._report
        junction = self._imported_junction if self._display_source == "imported" else self._junction
        stable_ids = {s.stable_id for s in shapes if getattr(s, "stable_id", None)}
        lines = []
        if report is not None and junction is not None:
            groups = ji._assign_shapes_to_fingers(junction)
            for pg in report.patch_groups:
                group_shapes = groups.get(pg.finger_index, [])
                if not any(s.stable_id in stable_ids for s in group_shapes):
                    continue  # this finger's patch group isn't part of the current selection
                fname = ji.finger_display_label(pg.finger_index)
                if pg.edge_to_edge_spacings_um:
                    spacings = ", ".join(f"{s_:.3f}" for s_ in pg.edge_to_edge_spacings_um)
                    lines.append(f"Finger {fname} edge-to-edge spacing: [{spacings}] µm")
                else:
                    lines.append(f"Finger {fname}: only 1 patch -- no edge-to-edge spacing to measure")
        try:
            angles = sorted(set(round(ji._polygon_axis_and_ends(s.points)[0] % 180.0, 1) for s in shapes))
        except Exception:
            angles = []
        if angles:
            angle_txt = ", ".join(f"{a:g}°" for a in angles)
            if len(angles) <= 2:
                lines.append(f"Patch axis angle(s): {angle_txt} (consistent)")
            else:
                lines.append(f"⚠ Patch axis angles: {angle_txt} -- more than 2 distinct angles found "
                             f"among the selected patches, expected all of them to run along the same "
                             f"two axial directions")
        return "\n".join(lines)

    def _layer_has_members(self, category) -> bool:
        """True if at least one shape (custom electrode_scene shape or
        real junction finger/patch/plate) is currently classified into
        `category` -- the "is there anything to move" guard shared by
        _on_layer_nudge and the canvas layer-drag path, checked BEFORE
        pushing an undo snapshot so nudging/dragging an empty layer
        never adds a needless no-op undo entry."""
        if not category:
            return False
        scene_shapes = self._layer_scene_shapes(category)
        fingers, shapes = self._layer_junction_members(category)
        return bool(scene_shapes or fingers or shapes)

    def _shape_in_highlighted_layer(self, *, scene_shape=None, stable_id=None) -> bool:
        """True if the given shape -- a custom electrode_scene shape
        (pass scene_shape=) or a real junction finger/patch/plate (pass
        stable_id=) -- is classified into whichever Layer is currently
        highlighted (self._layer_highlight). This is the canvas-drag
        entry point's own test for whether grabbing this one shape should
        drag the WHOLE layer together,
        checked once at _on_canvas_press time -- False whenever nothing
        is highlighted, so an ordinary single-shape drag is completely
        unaffected unless the user has actually picked a Layer (or the
        whole "Physical JJ") in the Layers dock first."""
        category = self._layer_highlight
        if not category:
            return False
        wanted = ("finger", "patch", "plate") if category == "__jj_all__" else (category,)
        if scene_shape is not None:
            return scene_shape.role in wanted
        if stable_id:
            finger, shape = self._find_active_junction_shape(stable_id)
            obj = finger if finger is not None else shape
            if obj is None:
                return False
            return self._effective_shape_class(obj) in wanted
        return False

    def _translate_layer_members(self, category, dx: float, dy: float):
        """The no-undo-push mutation core behind BOTH _on_layer_nudge
        (which pushes exactly one snapshot per button click) and the
        canvas layer-drag path (_on_canvas_press/_on_canvas_motion --
        pushes exactly one snapshot at drag-start, then
        calls this once per motion event with that frame's own
        incremental delta, same convention as _translate_junction_member
        for a single shape). Moves every shape currently classified into
        `category` -- custom electrode_scene shapes AND real junction
        fingers/patches/plates, imported or parametric -- together by
        the SAME (dx, dy), so the whole group's relative arrangement
        (spacing, overlap, everything) is preserved exactly: the junction
        should look identical after dragging from one place to another.
        Works for a PARAMETRIC design too (accumulated
        into self._param_shape_offsets, re-applied by _update_preview
        after every rebuild), same as a single-member drag."""
        scene_shapes = self._layer_scene_shapes(category)
        fingers, shapes = self._layer_junction_members(category)
        for shp in scene_shapes:
            shp.cx += dx
            shp.cy += dy
            if shp.kind == "polygon" and shp.points:
                shp.points = [(px + dx, py + dy) for px, py in shp.points]
            if shp.base_points:  # keep the scale reference co-moving, not left behind
                shp.base_points = [(px + dx, py + dy) for px, py in shp.base_points]
        if fingers or shapes:
            if self._display_source == "imported":
                for f in fingers:
                    ji.translate_finger(f, dx, dy)
                for s in shapes:
                    ji.translate_shape(s, dx, dy)
                ji.recompute_derived_fields(self._imported_junction)
            else:
                for f in fingers:
                    dx0, dy0 = self._param_shape_offsets.get(f.stable_id, (0.0, 0.0))
                    self._param_shape_offsets[f.stable_id] = (dx0 + dx, dy0 + dy)
                for s in shapes:
                    dx0, dy0 = self._param_shape_offsets.get(s.stable_id, (0.0, 0.0))
                    self._param_shape_offsets[s.stable_id] = (dx0 + dx, dy0 + dy)

    # ------------------------------------------------------------------
    # Rubber-band/marquee multi-select: drag a dashed box
    # over the canvas (reusing the Rectangle tool's own click-drag
    # mechanics -- see _on_canvas_press/_on_canvas_motion; this is now
    # a built-in ability of the Select tool itself -- starting a
    # drag from an empty click -- rather than its own separate toolbar
    # button, see _on_canvas_press's own empty-click branch),
    # and every finger/patch/plate/custom shape with ANY overlap with that
    # box (even the slimmest sliver, not just fully-contained or centroid-
    # inside) joins one ad hoc batch selection: only the parts of the
    # junction that fall within the region are selected, and that whole
    # shape gets selected as soon as any part of it overlaps. The only
    # features usable on this batch selection are nudge, scale, and move,
    # giving the user the freedom to batch-select whatever
    # amount of shapes or features they want.
    # ------------------------------------------------------------------
    def _safe_polygon(self, points):
        """sg.Polygon(points), repaired with .buffer(0) if the raw point
        list happens to be self-intersecting/invalid -- the same defensive
        pattern already used everywhere else in this file before an
        .intersects()/.intersection() test (e.g. _ghost_junction_slivers
        and dozens of shadow-geometry call sites)."""
        poly = sg.Polygon(points)
        if not poly.is_valid:
            poly = poly.buffer(0)
        return poly

    def _shapes_overlapping_region(self, region) -> dict:
        """Every shape with ANY overlap with `region` (a shapely geometry
        in the same world/data coordinates the canvas itself uses) --
        custom electrode_scene shapes AND real junction fingers/patches/
        plates from whichever design is currently active (imported or
        parametric). Uses .intersects (a plain boolean touch/overlap
        test), deliberately never centroid-inside or fully-contained --
        whether the full shape is inside or even just a sliver of it
        overlaps, that whole shape gets
        selected. Returns id-based (never object-based -- see this
        section's own header comment) {"scene_shape_ids", "finger_ids",
        "shape_ids"}, ready to store as self._marquee_selection."""
        scene_shape_ids = [s.id for s in self.electrode_scene.shapes
                           if self._safe_polygon(s.to_world_polygon()).intersects(region)]
        junction = self._imported_junction if self._display_source == "imported" else self._junction
        finger_ids, shape_ids = [], []
        if junction is not None:
            finger_ids = [f.stable_id for f in junction.fingers
                          if self._safe_polygon(f.points).intersects(region)]
            shape_ids = [s.stable_id for s in junction.other_shapes
                        if self._safe_polygon(s.points).intersects(region)]
        return {"scene_shape_ids": scene_shape_ids, "finger_ids": finger_ids, "shape_ids": shape_ids}

    def _marquee_live_members(self):
        """Re-resolves the current marquee batch's stored ids into LIVE
        objects from whichever design is active RIGHT NOW -- never caches
        the objects themselves (see this section's own header comment for
        why: a parametric junction is fully rebuilt from scratch on every
        _update_preview() call). Mirrors _layer_scene_shapes/_layer_
        junction_members's own fresh-every-call resolution, just against
        an explicit stored id list instead of a role/class filter.
        Returns (scene_shapes, fingers, shapes); a stored id that no
        longer resolves (e.g. that shape was deleted since the drag) is
        silently dropped rather than raising."""
        sel = self._marquee_selection
        if not sel:
            return [], [], []
        scene_shapes = [self.electrode_scene.get(i) for i in sel["scene_shape_ids"]]
        scene_shapes = [s for s in scene_shapes if s is not None]
        fingers, shapes = [], []
        for fid in sel["finger_ids"]:
            f, _s = self._find_active_junction_shape(fid)
            if f is not None:
                fingers.append(f)
        for sid in sel["shape_ids"]:
            _f, s = self._find_active_junction_shape(sid)
            if s is not None:
                shapes.append(s)
        return scene_shapes, fingers, shapes

    def _marquee_batch_count(self) -> int:
        sel = self._marquee_selection
        if not sel:
            return 0
        return len(sel["scene_shape_ids"]) + len(sel["finger_ids"]) + len(sel["shape_ids"])

    def _shape_in_marquee_selection(self, *, scene_shape=None, stable_id=None) -> bool:
        """True if the given shape -- a custom electrode_scene shape
        (scene_shape=) or a real junction finger/patch/plate (stable_id=)
        -- is part of the currently-committed marquee batch. Mirrors
        _shape_in_highlighted_layer's own signature/role exactly: this is
        the canvas-drag entry point's test for whether grabbing this ONE
        shape should move the WHOLE batch together (the batch's own Move
        operation), checked with priority over the ordinary single-shape/
        Layer drag paths so a batch member is never accidentally pulled
        out and dragged alone."""
        sel = self._marquee_selection
        if not sel:
            return False
        if scene_shape is not None:
            return scene_shape.id in sel["scene_shape_ids"]
        if stable_id:
            return stable_id in sel["finger_ids"] or stable_id in sel["shape_ids"]
        return False

    def _translate_marquee_selection(self, dx: float, dy: float):
        """The no-undo-push mutation core behind the marquee batch's own
        Move (canvas drag) and Nudge -- identical in structure to
        _translate_layer_members, just driven by _marquee_live_members()
        instead of a category filter."""
        scene_shapes, fingers, shapes = self._marquee_live_members()
        for shp in scene_shapes:
            shp.cx += dx
            shp.cy += dy
            if shp.kind == "polygon" and shp.points:
                shp.points = [(px + dx, py + dy) for px, py in shp.points]
            if shp.base_points:
                shp.base_points = [(px + dx, py + dy) for px, py in shp.base_points]
        if fingers or shapes:
            if self._display_source == "imported":
                for f in fingers:
                    ji.translate_finger(f, dx, dy)
                for s in shapes:
                    ji.translate_shape(s, dx, dy)
                ji.recompute_derived_fields(self._imported_junction)
            else:
                for f in fingers:
                    dx0, dy0 = self._param_shape_offsets.get(f.stable_id, (0.0, 0.0))
                    self._param_shape_offsets[f.stable_id] = (dx0 + dx, dy0 + dy)
                for s in shapes:
                    dx0, dy0 = self._param_shape_offsets.get(s.stable_id, (0.0, 0.0))
                    self._param_shape_offsets[s.stable_id] = (dx0 + dx, dy0 + dy)

    def _on_marquee_nudge(self, dx: float, dy: float):
        """The marquee batch's own Nudge branch of the unified Nudge &
        Scale card (see _current_edit_target/_on_nudge) -- one push-undo-
        then-move, exactly like _on_layer_nudge."""
        scene_shapes, fingers, shapes = self._marquee_live_members()
        if not scene_shapes and not fingers and not shapes:
            return
        self._push_undo_snapshot()
        self._translate_marquee_selection(dx, dy)
        self._update_preview()

    def _on_marquee_scale_apply(self, factor: float, push_undo: bool = True):
        """The marquee batch's own Scale branch (see _current_edit_target/
        _on_scale_apply) -- structurally identical to _on_layer_scale_
        apply: custom electrode_scene shapes keep their own independent
        per-shape EditableShape.apply_scale; real junction fingers/
        patches/plates are handed to _apply_junction_group_scale, the ONE
        function behind every junction-shape Scale in this tab, using a
        dedicated "__marquee__" group_key so this ad hoc batch gets its
        own origin/baseline, entirely separate from any Layer's or single
        shape's own cached scale reference. That baseline is explicitly
        reset (see _finish_marquee_drag) every time a NEW drag commits a
        different batch, since -- unlike a Layer's stable category-based
        membership -- a marquee batch's membership is arbitrary and
        different every time, so re-using a stale "__marquee__" baseline
        across two unrelated batches would silently scale the new one
        from the wrong reference geometry."""
        if factor <= 0:
            return
        scene_shapes, fingers, shapes = self._marquee_live_members()
        if not scene_shapes and not fingers and not shapes:
            return
        if push_undo:
            self._push_undo_snapshot()
        if scene_shapes:
            for shp in scene_shapes:
                shp.apply_scale(factor)
        if self._display_source == "imported" and (fingers or shapes):
            self._apply_junction_group_scale(fingers, shapes, factor, group_key="__marquee__", push_undo=False)
        self._update_preview()

    def _update_marquee_drag_rect(self, x, y):
        """Cheap, _update_preview()-free live redraw of the dashed
        marquee-drag preview rectangle -- modeled on _on_canvas_motion's
        OWN panning branch (self._active_canvas.draw() directly, no full
        design rebuild), deliberately NOT routed through _update_preview():
        re-running the full design recompute on every single mouse-motion
        frame of a plain rectangle drag, when nothing about the design
        itself has changed yet, would be pure waste -- exactly the class
        of avoidable per-frame cost the Design Warnings animation
        crash fix was also found sitting behind."""
        from matplotlib.patches import Rectangle as MplRect
        x0, y0 = self._marquee_drag_start
        ax = self._active_ax
        if self._marquee_rect_artist is not None:
            try:
                self._marquee_rect_artist.remove()
            except Exception:
                pass
            self._marquee_rect_artist = None
        rect = MplRect((min(x0, x), min(y0, y)), abs(x - x0), abs(y - y0),
                       fill=False, edgecolor=ACCENT_COLOR, linewidth=1.3,
                       linestyle=(0, (4, 3)), zorder=50)
        ax.add_patch(rect)
        self._marquee_rect_artist = rect
        self._active_canvas.draw_idle()

    def _finish_marquee_drag(self, event):
        """Finalizes a completed marquee drag: removes the preview
        rectangle, hit-tests every shape against the dragged region (ANY
        overlap, per _shapes_overlapping_region), and commits the result
        as the new self._marquee_selection -- replacing whatever batch (if
        any) was committed before. A degenerate drag (no real movement --
        a plain click with the marquee tool active) or a drag that landed
        on nothing selects nothing, matching a real click-drag rubber-band
        select in any shape-editor program. Always returns to the Select
        tool afterward, same KLayout/Inkscape "placing/selecting reverts
        to Select" convention every other one-shot tool in this toolbar
        already follows (action_rect/action_circle/action_polygon)."""
        x0, y0 = self._marquee_drag_start
        self._marquee_drag_start = None
        if self._marquee_rect_artist is not None:
            try:
                self._marquee_rect_artist.remove()
            except Exception:
                pass
            self._marquee_rect_artist = None
        if event.xdata is None or event.ydata is None:
            self.action_select.setChecked(True)
            self._update_preview()
            return
        x1, y1 = event.xdata, event.ydata
        min_drag = 1e-6
        if abs(x1 - x0) < min_drag and abs(y1 - y0) < min_drag:
            self.action_select.setChecked(True)
            self._update_preview()
            return
        region = sg.box(min(x0, x1), min(y0, y1), max(x0, x1), max(y0, y1))
        selection = self._shapes_overlapping_region(region)
        n = len(selection["scene_shape_ids"]) + len(selection["finger_ids"]) + len(selection["shape_ids"])
        self._marquee_selection = selection if n else None
        self._junction_scale_base.pop("__marquee__", None)  # a genuinely NEW/different batch always
                                                               # starts its own fresh Scale baseline --
                                                               # see _on_marquee_scale_apply's own docstring
        # Clear any single-shape selection so the marquee batch is
        # unambiguously the one thing Nudge & Scale acts on next
        # (_current_edit_target checks "marquee" with top priority).
        self.electrode_scene.selected_id = None
        self._selected_junction_id = None
        self.action_select.setChecked(True)
        self._update_preview()

    # ------------------------------------------------------------------
    # Batch-rotate-by-layer: a draggable rotation handle for
    # whichever Layer is highlighted, rotating every shape classified
    # into it together as one rigid group about a single shared pivot.
    # When a layer is selected -- including the entire junction -- a
    # node can be dragged to rotate the whole selection, recalculating
    # the angle of every shape individually, so clicking off the group
    # highlight to select just one shape shows that shape's angle
    # matching what the batch rotation produced. Rotating just the
    # patches or just the fingers is also possible; the fingers remain
    # orthogonal to each other because the batch rotation node applies
    # a rotation difference to the orthogonal fingers rather than an
    # independent rotation to each.
    # ------------------------------------------------------------------

    def _group_rotation_origin(self, fingers, shapes, scene_shapes) -> Tuple[float, float]:
        """The shared pivot a batch layer-rotate turns every included
        member around -- SAME physically-meaningful choice
        _apply_junction_group_scale already uses for its own group
        origin (two or more fingers -> the real JJ crossing point of
        the first two; otherwise the centroid of every included
        member's own anchor point), extended here to also fold in
        custom electrode_scene shapes' own centers, since (unlike
        Scale, where a scene shape always scales around its OWN center
        independently) a rotate needs ONE shared pivot across every
        kind of member at once so the whole junction looks
        identical, just rotated. Computed FRESH at the start
        of every rotate gesture (not cached across separate gestures
        the way _junction_scale_base is) -- there is no persistent
        "cumulative rotation" number this needs to stay consistent
        with, so simply re-deriving it from whatever is currently on
        screen is both simpler and more intuitive (the pivot tracks
        wherever the group actually is right now, including after an
        earlier drag/nudge)."""
        anchor_pts = [self._finger_polygon_stub_patch(f)[0] for f in fingers]
        for s in shapes:
            _angle, end_a, end_b, _w = ji._polygon_axis_and_ends(s.points)
            anchor_pts.append(((end_a[0] + end_b[0]) / 2.0, (end_a[1] + end_b[1]) / 2.0))
        for shp in scene_shapes:
            if shp.kind == "polygon" and shp.points:
                cx = sum(p[0] for p in shp.points) / len(shp.points)
                cy = sum(p[1] for p in shp.points) / len(shp.points)
                anchor_pts.append((cx, cy))
            else:
                anchor_pts.append((shp.cx, shp.cy))
        if len(fingers) >= 2:
            origin = ji.finger_crossing_point(fingers[0], fingers[1])
            if origin is not None:
                return origin
        if anchor_pts:
            return (sum(p[0] for p in anchor_pts) / len(anchor_pts),
                    sum(p[1] for p in anchor_pts) / len(anchor_pts))
        return (0.0, 0.0)

    def _layer_has_rotatable_members(self, category) -> bool:
        """True if dragging this layer's rotation handle would actually
        move something. A custom electrode_scene shape always qualifies
        (EditableShape rotation is independent of _display_source
        entirely). A real junction finger/patch/plate only qualifies on
        an IMPORTED design -- same "no independent geometry to act on"
        restriction _apply_junction_group_scale already applies to
        Scale, EXCEPT fingers also qualify on a PARAMETRIC design, via
        the same absolute-theta-override mechanism
        _apply_finger_rotation_drag's own parametric branch already
        uses for a single finger (see _apply_layer_rotation_drag's own
        docstring for why patches/plates can't follow suit there)."""
        if not category:
            return False
        if self._layer_scene_shapes(category):
            return True
        fingers, shapes = self._layer_junction_members(category)
        if not fingers and not shapes:
            return False
        if self._display_source == "imported":
            return True
        return bool(fingers)

    _ROTATE_RING_BAND_MULT = 1.5  # how wide the ring's own click band is, in multiples of
                                    # _hit_test_tolerance() -- generous, since the ring's WHOLE
                                    # circumference is the grab target, not one point.
    _ROTATE_RING_MARGIN_MULT = 2.0  # how far outside the group's own silhouette the ring sits,
                                       # in multiples of _hit_test_tolerance() -- just enough
                                       # clearance that the ring never touches a real shape.

    def _layer_rotation_ring_geometry(self, category) -> Tuple[Tuple[float, float], float]:
        """(pivot, radius) for the highlighted layer's own batch-rotate
        ring, in world coordinates. The original design put a single
        small handle on a stick far outside the pivot (offset by the
        group's own bounding radius PLUS an extra fixed gap) -- for a
        spread-out design that stick could land well outside the
        visible viewport entirely, and even when visible it was a
        single small point to aim for. A full
        ring hugging just outside the group's own silhouette fixes
        both: its entire circumference is a valid grab target (see
        _hit_test_layer_rotation_ring), and it never sits further from
        the content than a small, constant clearance -- a rotation
        circle around the junction that the user can click on anywhere
        along its edge.

        pivot is the same _group_rotation_origin every rotate already
        turns around; radius is the same "every included member's own
        farthest point from pivot" bounding-radius computation the
        handle already used, plus a small constant margin so the
        ring doesn't touch the shapes it's about to rotate."""
        scene_shapes = self._layer_scene_shapes(category)
        fingers, shapes = self._layer_junction_members(category)
        pivot = self._group_rotation_origin(fingers, shapes, scene_shapes)
        ox, oy = pivot
        tol = self._hit_test_tolerance()
        radius = tol
        for f in fingers:
            stub, patch_end = self._finger_polygon_stub_patch(f)
            radius = max(radius, math.hypot(stub[0] - ox, stub[1] - oy),
                         math.hypot(patch_end[0] - ox, patch_end[1] - oy))
        for s in shapes:
            for pt in s.points:
                radius = max(radius, math.hypot(pt[0] - ox, pt[1] - oy))
        for shp in scene_shapes:
            for pt in self._shape_node_handles(shp):
                radius = max(radius, math.hypot(pt[0] - ox, pt[1] - oy))
        radius += self._ROTATE_RING_MARGIN_MULT * tol
        return pivot, radius

    def _hit_test_layer_rotation_ring(self, category, x: float, y: float) -> bool:
        """True if (x, y) lands within the highlighted layer's own
        batch-rotate ring band -- ANY point along the ring's
        circumference at roughly the right distance from the pivot,
        not just one small spot -- False immediately (no geometry work
        at all) whenever nothing is highlighted or the highlighted
        layer has nothing rotatable in it, mirroring
        _shape_in_highlighted_layer's own "no-op unless the user has
        actually picked a Layer" guard."""
        if not category or not self._layer_has_rotatable_members(category):
            return False
        (ox, oy), radius = self._layer_rotation_ring_geometry(category)
        tol = self._hit_test_tolerance()
        dist = math.hypot(x - ox, y - oy)
        return abs(dist - radius) <= self._ROTATE_RING_BAND_MULT * tol

    def _start_layer_rotation_drag(self, category, mouse_x: float, mouse_y: float):
        """Snapshots everything the upcoming rotate gesture will need --
        the shared pivot and every included member's CURRENT geometry
        and the starting mouse angle around that pivot -- exactly once,
        at drag-start. _apply_layer_rotation_drag always measures the
        total angle swept since THIS snapshot, never the previous
        frame's already-rotated result, so a long/jittery drag can never
        compound rounding error frame over frame (the same reason
        _apply_shape_rotation_drag's own polygon branch snapshots
        points once at drag-start instead of rotating incrementally)."""
        scene_shapes = self._layer_scene_shapes(category)
        fingers, shapes = self._layer_junction_members(category)
        origin = self._group_rotation_origin(fingers, shapes, scene_shapes)
        self._rotating_layer_category = category
        self._rotating_layer_origin = origin
        ox, oy = origin
        self._rotating_layer_start_mouse_angle = math.degrees(math.atan2(mouse_y - oy, mouse_x - ox))
        self._rotating_layer_start_fingers = {}
        for f in fingers:
            if not f.stable_id:
                continue
            stub, patch_end = self._finger_polygon_stub_patch(f)
            self._rotating_layer_start_fingers[f.stable_id] = (stub, patch_end, f.width_um, f.length_um)
        self._rotating_layer_start_shapes = {
            s.stable_id: [tuple(pt) for pt in s.points] for s in shapes if s.stable_id
        }
        self._rotating_layer_start_scene_shapes = {}
        for shp in scene_shapes:
            self._rotating_layer_start_scene_shapes[shp.id] = dict(
                cx=shp.cx, cy=shp.cy, angle_deg=shp.angle_deg,
                points=[tuple(pt) for pt in shp.points] if (shp.kind == "polygon" and shp.points) else None,
                base_points=[tuple(pt) for pt in shp.base_points] if shp.base_points else None,
            )

    def _apply_layer_rotation_drag(self, mouse_x: float, mouse_y: float):
        """Rotates every shape snapshotted by _start_layer_rotation_drag
        by the SAME delta (the total angle swept since drag-start,
        measured around the shared pivot) -- a true rigid-body rotation
        of the whole group: new = pivot + R(delta) * (old - pivot) for
        every included point, which by definition preserves every
        pairwise angle and distance within the group. This is exactly
        why two orthogonal fingers STAY orthogonal (each finger's own
        theta_toward_patch_deg shifts by the identical delta, so their
        difference -- the thing that actually defines "orthogonal" --
        never changes), and why a patch/plate/custom shape's own
        angle_deg updates in lockstep: selecting it individually right
        after this gesture reads back the exact same angle the batch
        rotate just applied, since both paths write into the SAME
        fields (finger.theta_toward_patch_deg, EditableShape.angle_deg)
        a single-shape edit would.

        Custom electrode_scene shapes rotate here regardless of
        _display_source (EditableShape geometry is independent of the
        junction entirely). Real junction fingers/patches/plates only
        rotate for an IMPORTED design, mirroring _apply_junction_group_
        scale's own imported-only restriction -- EXCEPT fingers, which
        also get an absolute-theta override on a PARAMETRIC design via
        self._param_shape_edits, the exact same mechanism
        _apply_finger_rotation_drag's own parametric branch already
        uses for a single finger. Patches/plates on a PARAMETRIC design
        have no equivalent: apply_patch_extension_edit only ever
        repositions a patch relative to its OWN finger's CURRENT
        crossing point and the patch's OWN current axis angle, with no
        absolute "rotate to a new world angle" input at all -- and this
        is a pre-existing gap, not a new one: a plain single-finger
        rotation drag on a parametric design ALREADY leaves that
        finger's own patches/plates visually behind (rotating one
        parametric finger's theta and calling
        recompute_derived_fields moves zero patch/plate points).
        _layer_has_rotatable_members/_draw_create_import_layer_rotation_
        handle already keep the handle itself from appearing at all for
        a Patches/Plates-only layer on a parametric design (nothing
        rotatable in it, by this same reasoning), so this silently-
        skips-patches-on-parametric branch is only ever reached via a
        mixed layer or "__jj_all__", where at least the fingers still
        rotate."""
        category = self._rotating_layer_category
        if not category or self._rotating_layer_origin is None:
            return
        ox, oy = self._rotating_layer_origin
        mouse_angle = math.degrees(math.atan2(mouse_y - oy, mouse_x - ox))
        delta = mouse_angle - self._rotating_layer_start_mouse_angle
        rad = math.radians(delta)
        cos_d, sin_d = math.cos(rad), math.sin(rad)

        def rot_pt(pt):
            dx, dy = pt[0] - ox, pt[1] - oy
            return (ox + dx * cos_d - dy * sin_d, oy + dx * sin_d + dy * cos_d)

        for shp_id, start in self._rotating_layer_start_scene_shapes.items():
            shp = self.electrode_scene.get(shp_id)
            if shp is None:
                continue
            shp.cx, shp.cy = rot_pt((start["cx"], start["cy"]))
            shp.angle_deg = (start["angle_deg"] + delta) % 360.0
            if start["points"] is not None:
                shp.points = [rot_pt(pt) for pt in start["points"]]
            if start["base_points"] is not None:
                shp.base_points = [rot_pt(pt) for pt in start["base_points"]]  # keep the scale
                                    # reference co-moving, not left behind -- same convention
                                    # _translate_layer_members's own scene-shape branch uses

        if self._display_source == "imported":
            fingers, shapes = self._layer_junction_members(category)
            fingers_by_id = {f.stable_id: f for f in fingers if f.stable_id}
            for stable_id, (base_stub, base_patch_end, base_width, _base_length) in self._rotating_layer_start_fingers.items():
                f = fingers_by_id.get(stable_id)
                if f is None:
                    continue
                new_stub = rot_pt(base_stub)
                new_patch_end = rot_pt(base_patch_end)
                new_theta = math.degrees(math.atan2(new_patch_end[1] - new_stub[1],
                                                     new_patch_end[0] - new_stub[0])) % 360.0
                new_length = math.hypot(new_patch_end[0] - new_stub[0], new_patch_end[1] - new_stub[1])
                ji.apply_finger_edit(f, length_um=new_length, width_um=base_width,
                                     theta_toward_patch_deg=new_theta, overlap_um=0.0, crossing_point=new_stub)
            shapes_by_id = {s.stable_id: s for s in shapes if s.stable_id}
            for stable_id, base_points in self._rotating_layer_start_shapes.items():
                s = shapes_by_id.get(stable_id)
                if s is None:
                    continue
                s.points = [rot_pt(pt) for pt in base_points]
                _angle, end_a, end_b, width = ji._polygon_axis_and_ends(s.points)
                s.length_um = math.hypot(end_b[0] - end_a[0], end_b[1] - end_a[1])
                s.width_um = width
            if fingers or shapes:
                ji.recompute_derived_fields(self._imported_junction)
                # Fixes a crash where clicking the node to rotate the whole
                # junction caused the view to jitter wildly, traced to the
                # code that keeps the junction always in view.
                # this used to set self._create_import_force_fit = True here,
                # exactly like _apply_junction_group_scale's own one-shot Apply
                # does. But THIS function runs on every single motion event of
                # a live, continuous mouse-driven drag (see _on_canvas_motion's
                # own rotate branch) -- forcing a fresh re-fit-to-content on
                # EVERY frame changes the view's center/zoom, which changes
                # how the NEXT frame's event.xdata/ydata (already-transformed
                # screen->data coordinates) are interpreted for the SAME
                # physical mouse position, feeding a new, larger swing back
                # into this same function -- a classic view-rescale feedback
                # loop, the exact same class of bug _on_canvas_motion's own
                # docstring already documents and fixes for a plain shape
                # drag. The fix is the same one: a continuous mouse-driven
                # gesture must NEVER force a re-fit mid-drag -- matching
                # _translate_junction_member/_translate_layer_members, which
                # already never touch this flag at all. If a rotate carries
                # the design well outside the current view, the user can
                # still hit Zoom to Fit/Reset View afterward, same as a big
                # ordinary drag already requires today.
        else:
            for stable_id, (base_stub, base_patch_end, base_width, base_length) in self._rotating_layer_start_fingers.items():
                new_stub = rot_pt(base_stub)
                new_patch_end = rot_pt(base_patch_end)
                new_theta = math.degrees(math.atan2(new_patch_end[1] - new_stub[1],
                                                     new_patch_end[0] - new_stub[0])) % 360.0
                prior_overlap = self._param_shape_edits.get(stable_id, {}).get("overlap_um")
                self._param_shape_edits[stable_id] = dict(
                    kind="finger", length_um=base_length, width_um=base_width,
                    theta_toward_patch_deg=new_theta, overlap_um=prior_overlap,
                )

    def _on_layer_nudge(self, dx: float, dy: float):
        """Nudges (and, applied repeatedly, effectively MOVES) every
        shape currently classified into the selected layer, together, by
        a fixed (dx, dy) -- the layer-wide branch of the single unified
        Nudge & Scale card (see _current_edit_target/_on_nudge), used
        whenever nothing is individually selected. dx/dy (not a sign +
        an internal step lookup) so the ONE step field in that card
        (self.nudge_step_edit) is the only source of the step size --
        the old separate self.layer_nudge_step_edit field is gone.
        Fixes a bug where nudging an entire
        junction did nothing: junction fingers/patches/
        plates now move for a PARAMETRIC design too, not just imported --
        see self._param_shape_offsets and _update_preview's parametric
        branch, which is what actually makes a parametric nudge stick
        (that junction is rebuilt from Design Parameters on every
        redraw, so there's nothing to mutate in place directly).

        The actual movement now lives in the shared
        _translate_layer_members (see its own docstring) -- this
        function is just that plus the one-push-per-click undo
        bookkeeping."""
        category = self._layer_highlight
        if not self._layer_has_members(category):
            return
        self._push_undo_snapshot()
        self._translate_layer_members(category, dx, dy)
        self._update_preview()

    def _on_layer_scale_apply(self, factor: float, push_undo: bool = True):
        """Scales every shape currently classified into the selected
        layer -- the "select just a specific feature under Layers"
        entry point: if just the patches are selected, they can be
        scaled using this same feature. Custom electrode_scene
        shapes keep their own existing, already-correct per-shape scale
        (EditableShape.apply_scale, always measured from THAT shape's
        own base_w/h -- unrelated to this round's bug). Real junction
        fingers/patches/plates are handed to _apply_junction_group_scale
        -- the ONE function behind every junction-shape Scale in this
        tab, single shape or whole layer alike (see its own docstring
        for why this used to leave every shape's POSITION untouched,
        and for the separate, now-fixed "briefly scales, then reverts"
        bug in how this control's own displayed factor used to be
        computed). Junction fingers/patches/plates only scale for an
        IMPORTED design -- a parametric junction is fully derived from
        Design Parameters on every rebuild, with no independent
        geometry to scale against.

        push_undo=False lets the Scale slider's live-drag
        handler apply every tick without flooding the undo stack (one
        snapshot pushed at the gesture's first tick, none after).
        push_undo=True (the default, used by the typed-field/Apply-
        button path) pushes exactly ONE snapshot for the whole layer
        here -- fixes a bug where a layer containing BOTH
        custom electrode_scene shapes and real junction members used to
        push two separate undo snapshots for a single Apply click (one
        here, one more inside _apply_junction_group_scale), so a single
        Undo only reverted half of what that one Apply had just done.
        The scene-shape branch and the junction-shape branch below now
        share this one push instead."""
        category = self._layer_highlight
        if not category or factor <= 0:
            return
        scene_shapes = self._layer_scene_shapes(category)
        fingers, shapes = self._layer_junction_members(category)
        if not scene_shapes and not fingers and not shapes:
            return
        if push_undo:
            self._push_undo_snapshot()
        if scene_shapes:
            for shp in scene_shapes:
                shp.apply_scale(factor)
            self._update_preview()
        if self._display_source == "imported" and (fingers or shapes):
            self._apply_junction_group_scale(fingers, shapes, factor, group_key=category, push_undo=False)
        self._update_layer_batch_status()

    def _on_batch_layer_edit_apply(self):
        """Batch Edit Layer's Apply button: sets EVERY shape currently
        classified into the highlighted layer to the SAME exact typed
        value(s) -- an ABSOLUTE overwrite, not the relative Scale factor
        above. Patches may show a slightly
        different decimal value of a length or linewidth per shape once
        batch-selected; this lets the user type in the
        exact parameters they want them all to be, and they all
        change at once. Works for junction fingers, patches, and
        adhesion plates, on BOTH a created (parametric) and an imported
        design -- unlike the relative Scale factor, which only ever
        worked for imported junction shapes, this reuses the exact same
        write-back primitives (apply_finger_edit/apply_patch_extension_edit/
        apply_shape_edit, or _param_shape_edits for a parametric design)
        the single-shape Shape Properties card already uses for both
        sources, just looped across every shape in the layer instead of
        one. A blank field leaves that one parameter alone on every
        shape (same blank-means-unchanged convention as the single-shape
        editors), so typing only Linewidth, say, is safe."""
        category = self._layer_highlight
        if category not in ("finger", "patch", "plate"):
            return
        scene_shapes = self._layer_scene_shapes(category)
        fingers, shapes = self._layer_junction_members(category)
        if not scene_shapes and not fingers and not shapes:
            return

        def _read(field):
            text = field.text().strip()
            if not text:
                return None
            try:
                return float(text)
            except ValueError:
                return None

        is_imported = self._display_source == "imported"
        junction = self._imported_junction if is_imported else self._junction
        self._push_undo_snapshot()

        if category == "finger":
            # NOTE: Angle is deliberately NOT batch-editable here -- see
            # the comment beside batch_finger_page's
            # construction. Every finger keeps its OWN current angle
            # (eff_angle = f.theta_toward_patch_deg, never overridden)
            # through this whole batch-edit path.
            new_lw_nm = _read(self.batch_finger_lw_nm)
            new_length = _read(self.batch_finger_length)
            new_overlap = _read(self.batch_finger_overlap)
            new_width_um = new_lw_nm / 1000.0 if new_lw_nm is not None else None
            for f in fingers:
                other = next((g for g in junction.fingers if g is not f), None) if junction else None
                eff_length = new_length if new_length is not None else f.length_um
                eff_width_um = new_width_um if new_width_um is not None else f.width_um
                eff_angle = f.theta_toward_patch_deg
                if is_imported:
                    crossing_point = (ji.finger_overlap_start_point(f, other)
                                      if (new_overlap is not None and other is not None) else None)
                    ji.apply_finger_edit(f, length_um=eff_length, width_um=eff_width_um,
                                         theta_toward_patch_deg=eff_angle,
                                         overlap_um=new_overlap, crossing_point=crossing_point)
                    if f.stable_id:
                        self._rebase_single_shape_scale_base(f.stable_id, finger=f)
                else:
                    if f.stable_id:
                        self._param_shape_edits[f.stable_id] = dict(
                            kind="finger", length_um=eff_length, width_um=eff_width_um,
                            theta_toward_patch_deg=eff_angle, overlap_um=new_overlap,
                        )
            for shp in scene_shapes:
                resolved, other = self._resolve_custom_finger_pair(shp)
                if resolved is None:
                    continue  # not yet resolved into the junction -- nothing to batch-edit yet
                eff_length = new_length if new_length is not None else resolved.length_um
                eff_width_um = new_width_um if new_width_um is not None else resolved.width_um
                eff_angle = resolved.theta_toward_patch_deg  # Angle is never batch-edited -- see above
                theta_rad = math.radians(eff_angle)
                axis_hat = (math.cos(theta_rad), math.sin(theta_rad))
                new_stub = None
                if new_overlap is not None and other is not None:
                    crossing = ji.finger_overlap_start_point(resolved, other)
                    if crossing is not None:
                        new_stub = (crossing[0] - axis_hat[0] * new_overlap, crossing[1] - axis_hat[1] * new_overlap)
                if new_stub is None:
                    new_patch_end = resolved.patch_end
                    new_stub = (new_patch_end[0] - axis_hat[0] * eff_length, new_patch_end[1] - axis_hat[1] * eff_length)
                new_center = (new_stub[0] + axis_hat[0] * eff_length / 2.0, new_stub[1] + axis_hat[1] * eff_length / 2.0)
                shp.cx, shp.cy = new_center
                shp.w = eff_length
                shp.h = eff_width_um
                shp.angle_deg = eff_angle
                shp.capture_scale_base()
            if is_imported and junction is not None:
                ji.recompute_derived_fields(junction)

        elif category == "patch":
            new_far = _read(self.batch_patch_long_ext)
            new_near = _read(self.batch_patch_short_ext)
            new_lw = _read(self.batch_patch_lw)
            new_margin = _read(self.batch_patch_margin)
            all_patch_shapes = list(shapes)
            for shp in scene_shapes:
                resolved = self._resolve_custom_junction_shape(shp, "patch")
                if resolved is not None:
                    all_patch_shapes.append(resolved)
            margin_applied_for_finger = set()  # finger stable_ids already shifted this pass --
                                                  # margin is a per-GROUP quantity, applied once,
                                                  # not once per patch in that group
            for shape in all_patch_shapes:
                m = getattr(self, "_shape_measurements", {}).get(shape.stable_id, {})
                finger = next((f for f in junction.fingers if f.stable_id == m.get("finger_stable_id")), None) \
                    if junction else None
                if finger is None:
                    continue
                if is_imported:
                    patch_angle_deg, _end_a, _end_b, _cur_w = ji._polygon_axis_and_ends(shape.points)
                    ji.apply_patch_extension_edit(shape, finger, patch_angle_deg,
                                                  near_overhang_um=new_near, far_overhang_um=new_far,
                                                  width_um=new_lw,
                                                  connector_union=ji.finger_connector_union(junction, finger))
                    if new_margin is not None and finger.stable_id not in margin_applied_for_finger:
                        m_fresh = ji.measurements_by_stable_id(junction, ji.compute_measurements(junction)).get(shape.stable_id, {})
                        group_margin = m_fresh.get("group_tip_past_last_patch_um")
                        if group_margin is not None:
                            delta = new_margin - group_margin[2]
                            if abs(delta) > 1e-9:
                                groups = ji._assign_shapes_to_fingers(junction)
                                group_shapes = groups.get(junction.fingers.index(finger), [])
                                ji.apply_patch_group_margin_edit(group_shapes, finger, delta)
                        margin_applied_for_finger.add(finger.stable_id)
                else:
                    if shape.stable_id:
                        self._param_shape_edits[shape.stable_id] = dict(
                            kind="patch", finger_stable_id=finger.stable_id,
                            near_overhang_um=new_near, far_overhang_um=new_far,
                            width_um=new_lw, margin_um=new_margin,
                        )
            if is_imported and junction is not None:
                ji.recompute_derived_fields(junction)

        elif category == "plate":
            new_length = _read(self.batch_plate_length)
            new_width = _read(self.batch_plate_width)
            all_plate_shapes = list(shapes)
            for shp in scene_shapes:
                resolved = self._resolve_custom_junction_shape(shp, "plate")
                if resolved is not None:
                    all_plate_shapes.append(resolved)
            for shape in all_plate_shapes:
                eff_length = new_length if new_length is not None else shape.length_um
                eff_width = new_width if new_width is not None else shape.width_um
                if is_imported:
                    ji.apply_shape_edit(shape, length_um=eff_length, width_um=eff_width)
                    if shape.stable_id:
                        self._rebase_single_shape_scale_base(shape.stable_id, shape=shape)
                else:
                    if shape.stable_id:
                        self._param_shape_edits[shape.stable_id] = dict(
                            kind="plate", length_um=eff_length, width_um=eff_width)
            if is_imported and junction is not None:
                ji.recompute_derived_fields(junction)

        self._create_import_force_fit = True  # a batch edit across many shapes at once can move the
                                                  # design's overall extent by a lot -- see the matching
                                                  # comment in _on_shape_finger_edit for why re-fitting
                                                  # here is safe (a discrete, one-shot commit)
        self._update_preview()
        self._update_layer_batch_status()

    def _set_pending_shape_kind(self, kind):
        self._pending_shape_kind = kind
        self._pending_role_kind = None  # mutually exclusive with role-assignment tools
        if kind != "polygon" and self._pending_polygon_points:
            self._pending_polygon_points = []  # switching tools mid-polygon cancels it
            self._update_preview()
        # Switching to ANY other tool (this fires on every
        # select/rect/circle/polygon toggle-on) defensively cancels an
        # IN-PROGRESS marquee drag if one happened to be live -- e.g. the
        # user started a rubber-band drag with Select, then clicked a
        # different toolbar button without releasing the mouse. See
        # _cancel_marquee_drag_if_active's own docstring; it does NOT
        # touch an already-COMMITTED batch (self._marquee_selection),
        # only a drag still mid-flight.
        self._cancel_marquee_drag_if_active()

    def _on_ruler_toggled(self, checked):
        if not checked:
            self._ruler_pending_start = None
        self._cancel_marquee_drag_if_active()

    def _cancel_marquee_drag_if_active(self):
        """Defensive cleanup: if a rubber-band/marquee drag is currently
        mid-flight (self._marquee_drag_start is not None) when the active
        tool changes out from under it -- Pan, Ruler, or any shape-
        placement tool clicked mid-drag without releasing the mouse first
        -- cancel it and remove its preview rectangle artist, so a stray
        dashed rectangle can never linger on the canvas after nothing is
        left tracking it. Does NOT touch an already-committed batch
        (self._marquee_selection); that's a separate, persisted selection
        state cleared only by starting a new drag, clicking away, or
        Escape (see _on_canvas_press/keyPressEvent)."""
        if self._marquee_drag_start is None:
            return
        self._marquee_drag_start = None
        if self._marquee_rect_artist is not None:
            try:
                self._marquee_rect_artist.remove()
            except Exception:
                pass
            self._marquee_rect_artist = None
        if hasattr(self, "_active_canvas") and self._active_canvas is not None:
            self._active_canvas.draw_idle()

    def _on_ruler_click(self, x, y):
        """Deliberately does NOT auto-revert to Select after a
        measurement, unlike the shape-placement tools -- a ruler is a
        repeated measuring action, not a one-shot placement, so staying
        active for several measurements in a row is the more useful
        default here."""
        if self._ruler_pending_start is None:
            self._ruler_pending_start = (x, y)
            self._update_preview()
            return
        start = self._ruler_pending_start
        end = (x, y)
        distance = math.hypot(end[0] - start[0], end[1] - start[1])
        self._rulers.append({"start": start, "end": end, "distance_um": distance})
        self._ruler_pending_start = None
        self._update_preview()

    def _clear_rulers(self):
        self._rulers = []
        self._ruler_pending_start = None
        self._update_preview()

    def _draw_rulers(self, ax):
        """Draws every persisted ruler measurement plus the in-progress
        first-click marker, if any -- called AFTER the main junction
        redraw for whichever ax this is, since that redraw clears the
        axes and would otherwise wipe these out."""
        for r in self._rulers:
            sx, sy = r["start"]
            ex, ey = r["end"]
            ax.plot([sx, ex], [sy, ey], color="#ffd166", linewidth=1.2, linestyle="--", zorder=15)
            ax.plot([sx, ex], [sy, ey], color="#ffd166", marker="o", markersize=4, linestyle="none", zorder=15)
            mx, my = (sx + ex) / 2.0, (sy + ey) / 2.0
            ax.text(mx, my, f" {r['distance_um']:.3f} \u00b5m", color="#ffd166", fontsize=8,
                   fontweight="bold", zorder=16,
                   bbox=dict(boxstyle="round,pad=0.2", facecolor="#2a2410", edgecolor="#ffd166", linewidth=0.8))
        if self._ruler_pending_start is not None:
            sx, sy = self._ruler_pending_start
            ax.plot([sx], [sy], color="#ffd166", marker="x", markersize=8, zorder=15)

    def _draw_pending_polygon(self, ax):
        """Draws the polygon tool's in-progress vertices (multi-click
        placement -- not yet a real shape until the finishing double-
        click) as connected markers on whichever ax this is.

        Fixed a bug where this used to be drawn inline only
        inside _update_preview, with no equivalent call in
        _update_create_import_preview -- so a vertex placed while looking at
        Create / Import (which shares the exact same
        _pending_polygon_points state and toolbar) was silently invisible
        there the whole time you were clicking, only appearing once the
        double-click turned it into a real committed shape (which then
        draws through the normal electrode-shape path instead). Reusing
        _draw_rulers's shared-helper-called-from-both-canvases pattern
        fixes it the same way that function already handles rulers
        correctly on both canvases. markersize bumped from 4 to 6, since
        it was hard to see and visibility here is the
        whole point of this method existing."""
        if not self._pending_polygon_points:
            return
        pts = self._pending_polygon_points
        xs = [p[0] for p in pts]
        ys = [p[1] for p in pts]
        ax.plot(xs, ys, "o--", color=OUTLINE_COLOR, linewidth=1.4, markersize=6, zorder=8)

    def _on_sim_canvas_press(self, event):
        """Simulate Design's own mouse handler -- only the ruler tool,
        not the full shape-editing set Create / Import has, since
        Simulate Design is purely a simulation viewer. Kept separate
        from _on_canvas_press because that one checks the SHARED
        toolbar's action_ruler, which isn't even visible on this tab."""
        if event.xdata is None or event.ydata is None:
            return
        if getattr(self, "sim_ruler_toggle", None) is not None and self.sim_ruler_toggle.isChecked():
            self._on_sim_ruler_click(event.xdata, event.ydata)

    def _on_sim_ruler_click(self, x, y):
        if self._sim_ruler_pending_start is None:
            self._sim_ruler_pending_start = (x, y)
            self._draw_sim_rulers(self.sim_ax)
            self.sim_canvas.draw()
            return
        start = self._sim_ruler_pending_start
        end = (x, y)
        distance = math.hypot(end[0] - start[0], end[1] - start[1])
        self._sim_rulers.append({"start": start, "end": end, "distance_um": distance})
        self._sim_ruler_pending_start = None
        self._draw_sim_rulers(self.sim_ax)
        self.sim_canvas.draw()

    def _clear_sim_rulers(self):
        self._sim_rulers = []
        self._sim_ruler_pending_start = None
        if self._sim_cached_junction is not None:
            self._update_simulate_preview(self._sim_cached_junction, self._sim_cached_report)

    def _draw_sim_rulers(self, ax):
        """Same drawing logic as _draw_rulers, using Simulate Design's own
        separate ruler list -- called after every redraw of sim_ax,
        since that redraw clears the axes."""
        for r in self._sim_rulers:
            sx, sy = r["start"]
            ex, ey = r["end"]
            ax.plot([sx, ex], [sy, ey], color="#ffd166", linewidth=1.2, linestyle="--", zorder=15)
            ax.plot([sx, ex], [sy, ey], color="#ffd166", marker="o", markersize=4, linestyle="none", zorder=15)
            mx, my = (sx + ex) / 2.0, (sy + ey) / 2.0
            ax.text(mx, my, f" {r['distance_um']:.3f} \u00b5m", color="#ffd166", fontsize=8,
                   fontweight="bold", zorder=16,
                   bbox=dict(boxstyle="round,pad=0.2", facecolor="#2a2410", edgecolor="#ffd166", linewidth=0.8))
        if self._sim_ruler_pending_start is not None:
            sx, sy = self._sim_ruler_pending_start
            ax.plot([sx], [sy], color="#ffd166", marker="x", markersize=8, zorder=15)

    def _set_pending_role(self, role):
        self._pending_role_kind = role
        self._pending_shape_kind = None  # mutually exclusive with shape-placement tools

    # Fixes a crash where zooming in and out of the
    # preview was far too sensitive: a single finger-roll on a trackpad
    # could zoom out so far that the junction
    # left the page entirely, after which it got laggy and continued to
    # zoom out well beyond the physical scroll motion, sometimes
    # crashing outright. Root-caused by direct
    # reproduction: a single trackpad "roll" gesture delivers a BURST of
    # many discrete Qt wheel events (not one), and _on_canvas_scroll/
    # _zoom_step applied its fixed 0.85-or-1/0.85 factor per event with
    # NO ceiling on the resulting view span -- so a burst of, say, 40
    # events compounds to (1/0.85)**40 =~ 700x zoomed out in the time it
    # takes to process the queued backlog (which is also why it kept
    # visibly zooming out well after the physical scroll motion stopped:
    # Qt had already queued the whole burst before the first one was
    # even handled). At an extreme-enough span, imported_junction_view's
    # grid-line spacing (_draw_grid, driven by refresh_grid_and_scale's
    # xlim_changed callback -- see its own docstring) is capped at a
    # MAXIMUM step of 100 um, with no matching cap on the number of
    # lines that get drawn at that step -- so once the runaway view span
    # reaches the hundreds-of-thousands-of-microns range, that callback
    # tries to create tens or hundreds of thousands of Line2D grid
    # artists on a single redraw, which is the actual freeze/crash.
    # These two constants put a hard floor/ceiling on how far a SINGLE
    # _zoom_step call can push either axis's span, in data microns --
    # 20,000 um (2 cm) is already a wildly generous zoomed-out bound for
    # a chip-scale JJ design (fingers/patches here are routinely under
    # 10 um), so normal zooming is completely unaffected; it just makes
    # the span mathematically incapable of ever reaching grid-line-count
    # territory that could hang the app, no matter how many burst events
    # queue up. 0.02 um floors zooming IN for the same reason (protects
    # against a degenerate near-zero span elsewhere, e.g. _hit_test_
    # tolerance's own division).
    _MIN_ZOOM_SPAN_UM = 0.02
    _MAX_ZOOM_SPAN_UM = 20000.0

    def _zoom_step(self, factor, center=None, ax=None, canvas=None):
        """center=(x,y) in data coords -- if given, that point stays
        fixed on screen while the view scales around it (so the cursor
        position stays put, matching trackpad-pinch expectations). Falls
        back to the current view's own geometric center when not given
        (the toolbar zoom in/out buttons, which have no cursor position
        to work with).

        ax/canvas default to self._active_ax/_active_canvas (every
        single-subplot canvas in the app just uses that pair) -- pass
        them explicitly for a canvas that holds MULTIPLE independent
        subplots at once (the retired Live Angle Tester's chamber view: top-down + side by
        side on one canvas), where there is no single "the active axes"
        and the caller instead knows exactly which subplot the cursor
        was over (event.inaxes).

        The crash fix (see the class constants just above): factor
        is clamped, BEFORE it's applied to either axis, so that neither
        axis's resulting span can ever leave [_MIN_ZOOM_SPAN_UM,
        _MAX_ZOOM_SPAN_UM] -- clamping the single shared factor (rather
        than clamping each axis's final xlim/ylim independently
        afterward) is what keeps X and Y scaling by the exact same
        amount, so the view never gets stretched/distorted at the
        boundary. This is a genuine ceiling/floor, not just a per-call
        rate limit: it holds regardless of how many _zoom_step calls
        arrive back-to-back (an entire queued burst of scroll events),
        so a runaway burst can overshoot the bound on its way in but can
        never end up past it, and once AT a bound, further calls in the
        same direction become clean no-ops (factor clamps to ~1.0)
        instead of continuing to drift."""
        ax = ax if ax is not None else self._active_ax
        canvas = canvas if canvas is not None else self._active_canvas
        cur_xlim = ax.get_xlim()
        cur_ylim = ax.get_ylim()
        cur_x_span = cur_xlim[1] - cur_xlim[0]
        cur_y_span = cur_ylim[1] - cur_ylim[0]
        if not (math.isfinite(cur_x_span) and math.isfinite(cur_y_span)
                and cur_x_span > 0 and cur_y_span > 0):
            return  # already-degenerate view -- nothing sane to scale from
        min_factor = max(self._MIN_ZOOM_SPAN_UM / cur_x_span, self._MIN_ZOOM_SPAN_UM / cur_y_span)
        max_factor = min(self._MAX_ZOOM_SPAN_UM / cur_x_span, self._MAX_ZOOM_SPAN_UM / cur_y_span)
        if min_factor <= max_factor:
            factor = max(min_factor, min(factor, max_factor))
        if center is not None:
            px, py = center
        else:
            px = (cur_xlim[0] + cur_xlim[1]) / 2.0
            py = (cur_ylim[0] + cur_ylim[1]) / 2.0
        new_x0 = px - (px - cur_xlim[0]) * factor
        new_x1 = px + (cur_xlim[1] - px) * factor
        new_y0 = py - (py - cur_ylim[0]) * factor
        new_y1 = py + (cur_ylim[1] - py) * factor
        ax.set_xlim(new_x0, new_x1)
        ax.set_ylim(new_y0, new_y1)
        # draw_idle() (schedules one repaint, coalescing any
        # further draw_idle() calls that arrive before Qt actually gets
        # to paint) instead of draw() (an immediate, synchronous full
        # repaint EVERY call): the other half of the laggy, continues-
        # well-beyond-the-scrolling-motion fix -- a burst of queued
        # scroll events used to force one full synchronous redraw per
        # event, so the visible view kept changing, one full repaint at
        # a time, for as long as it took to drain the whole backlog.
        # With draw_idle(), that same backlog still updates the
        # (now-bounded) xlim/ylim state instantly for every event, but
        # only actually repaints once Qt's event loop is free -- so the
        # screen catches up to the final state in one repaint instead of
        # visibly crawling through every intermediate one.
        canvas.draw_idle()

    def _on_canvas_scroll(self, event):
        if event.xdata is None:
            return
        self._zoom_step(0.85 if event.button == "up" else 1.0 / 0.85, center=(event.xdata, event.ydata))

    def _on_canvas_press(self, event):
        if event.xdata is None or event.ydata is None:
            return
        if self.action_ruler.isChecked():
            self._on_ruler_click(event.xdata, event.ydata)
            return
        if self.action_pan.isChecked():
            # Screen-pixel-invariant panning: the reference point is set
            # ONCE here and deliberately never updated during the drag --
            # since event.xdata/ydata are recomputed against whatever the
            # CURRENT (possibly already-shifted) view is, the same
            # dx = event.xdata - reference formula self-corrects on every
            # subsequent motion event without needing to track the shift
            # separately. Verified this holds across multiple consecutive
            # shifts before relying on it.
            self._panning = True
            self._pan_last_xdata = event.xdata
            self._pan_last_ydata = event.ydata
            return
        if self._pending_shape_kind == "polygon":
            self._on_polygon_click(event)
            return
        if self._pending_shape_kind in ("rect", "circle"):
            # Instead of a shape appearing at a default dimension,
            # clicking the rectangle shape button lets the user click to
            # set the first node and then drag to whatever
            # coordinate or dimension sets the length and
            # width of the rectangle (same for a circle or oval). The
            # new shape is created immediately at a near-zero size
            # anchored at the click point, then genuinely resized live on
            # every motion event (see _on_canvas_motion) via the exact
            # same w/h/cx/cy fields the Shape Properties card and a
            # regular drag already use -- no separate "preview-only"
            # rendering path, so it looks and behaves exactly like any
            # other shape throughout the drag. plate_stamp keeps its old
            # one-click placement (a fixed-size stamp is the whole point
            # of that tool) and polygon keeps its own click-per-vertex
            # flow above -- neither was part of this request.
            self._push_undo_snapshot()
            eps = 1e-3
            new_id = self.electrode_scene.add(kind=self._pending_shape_kind, cx=event.xdata, cy=event.ydata,
                                               w=eps, h=eps, angle_deg=0.0, role="electrode")
            self._creating_shape_id = new_id
            self._creating_shape_anchor = (event.xdata, event.ydata)
            if not self.custom_electrode_check.isChecked():
                self.custom_electrode_check.setChecked(True)  # drawing a shape implies opting
                                                                # into custom placement
            self._update_preview()
            return
        if self._pending_shape_kind is not None:
            # plate_stamp -- unchanged, still a single fixed-size click-to-place.
            w, h = 1.0, 1.0
            self._push_undo_snapshot()
            self.electrode_scene.add(kind="rect", cx=event.xdata, cy=event.ydata,
                                     w=w, h=h, angle_deg=0.0, role="plate")
            self.action_select.setChecked(True)  # KLayout/Inkscape convention: placing one
                                                   # shape returns you to the select tool
            if not self.custom_electrode_check.isChecked():
                self.custom_electrode_check.setChecked(True)  # drawing a shape implies opting
                                                                # into custom placement
            self._update_preview()
            return
        if self._pending_role_kind is not None:
            self._assign_role_at(event.xdata, event.ydata, self._pending_role_kind)
            return
        # The batch-rotate-by-layer ring takes priority
        # over EVERYTHING below, checked first and independent of
        # whatever shape (if any) happens to already be selected --
        # highlighting a Layer in the Layers dock is itself already a
        # deliberate "act on this whole group" choice, exactly like the
        # whole-layer canvas DRAG below already takes priority the
        # moment a grabbed shape turns out to belong to the highlighted
        # layer. _hit_test_layer_rotation_ring is a cheap,
        # early-out False whenever nothing is highlighted, so this adds
        # no real cost to an ordinary click when no Layer is selected.
        if self._layer_highlight and self._hit_test_layer_rotation_ring(
                self._layer_highlight, event.xdata, event.ydata):
            self._push_undo_snapshot()
            self._start_layer_rotation_drag(self._layer_highlight, event.xdata, event.ydata)
            self._update_preview()
            return
        # Per-node editing takes priority over a plain
        # whole-shape select/move, but ONLY against the shape that's
        # ALREADY selected: the user can re-select the shape and drag
        # one of its nodes to redefine its shape -- an unrelated shape's node
        # handles are never shown or hit-tested while it isn't the
        # current selection, so this can't be confused with an ordinary
        # click landing near some other shape's corner.
        already_selected = self.electrode_scene.selected()
        if already_selected is not None:
            # Same "re-select-then-drag" priority as the
            # node-editing block right below, checked FIRST since the
            # rotation handle sits further out from the shape than any
            # corner/vertex node and should never be shadowed by one.
            if self._hit_test_shape_rotation_handle(already_selected, event.xdata, event.ydata):
                self._push_undo_snapshot()
                self._rotating_shape_id = already_selected.id
                if already_selected.kind == "polygon" and already_selected.points:
                    pts = already_selected.points
                    cx = sum(p[0] for p in pts) / len(pts)
                    cy = sum(p[1] for p in pts) / len(pts)
                    self._rotating_shape_start_points = list(pts)
                    self._rotating_shape_start_mouse_angle = math.degrees(
                        math.atan2(event.ydata - cy, event.xdata - cx))
                    self._rotating_shape_start_angle_deg = already_selected.angle_deg
                self._update_preview()
                return
            node_idx = self._hit_test_shape_node(already_selected, event.xdata, event.ydata)
            if node_idx is not None:
                self._push_undo_snapshot()
                self._dragging_node_shape_id = already_selected.id
                self._dragging_node_index = node_idx
                if already_selected.kind != "polygon":
                    opposite_idx = (node_idx + 2) % 4
                    self._dragging_node_anchor_world = self._shape_node_handles(already_selected)[opposite_idx]
                self._update_preview()
                return
        elif self._selected_junction_id is not None:
            # The same re-select-then-drag-the-handle
            # priority, generalized to a real junction finger's own
            # "Angle (deg):" field (see _apply_finger_rotation_drag's
            # own docstring). Only fingers get a rotation handle --
            # patches/plates have no independent angle property in
            # Shape Properties at all today (their orientation is
            # always locked to their owning finger's axis), so there's
            # nothing for a drag gesture to change for those.
            finger, _shape = self._find_active_junction_shape(self._selected_junction_id)
            if finger is not None and self._hit_test_finger_rotation_handle(finger, event.xdata, event.ydata):
                self._push_undo_snapshot()
                self._rotating_finger_id = finger.stable_id
                self._update_preview()
                return
        hit_id = self.electrode_scene.hit_test(event.xdata, event.ydata)
        if hit_id is not None and self._shape_in_marquee_selection(scene_shape=self.electrode_scene.get(hit_id)):
            # Grabbing ANY shape that's part of the current
            # marquee/rubber-band batch moves the WHOLE batch together
            # (the batch's own "Move" operation), exactly like grabbing
            # any one member of a
            # highlighted Layer already drags that whole layer just below
            # (_shape_in_highlighted_layer) -- same mechanism,
            # just against an explicit drag-selected id list instead of a
            # role/class filter. Checked BEFORE the ordinary single-shape
            # select path so a batch member is never pulled out and
            # dragged alone.
            self._push_undo_snapshot()
            self.electrode_scene.selected_id = None
            self._selected_junction_id = None
            self._dragging_marquee = True
            self._drag_marquee_last_xy = (event.xdata, event.ydata)
            self._update_preview()
            return
        self.electrode_scene.selected_id = hit_id
        self._dragging = False
        if hit_id is not None:
            self._push_undo_snapshot()  # before the drag moves anything
            self._selected_junction_id = None  # custom electrode shape takes priority
            self._marquee_selection = None  # A plain click on a DIFFERENT single
                                              # shape ends any previously-committed batch, same
                                              # Inkscape/KLayout convention as the empty-canvas
                                              # branch below (no-op if there wasn't one)
            shp = self.electrode_scene.get(hit_id)
            if self._shape_in_highlighted_layer(scene_shape=shp):
                # If the entire junction
                # is selected, the whole junction should move; if only
                # the patches are selected, all of them should be
                # dragged. Grabbing any ONE shape that's classified into
                # the currently highlighted Layer drags the WHOLE layer
                # together as one rigid group instead of just this shape
                # -- same incremental-delta-per-motion-event style as the
                # junction-member drag below, just for a whole category
                # at once (see _translate_layer_members).
                self._dragging_layer_category = self._layer_highlight
                self._drag_layer_last_xy = (event.xdata, event.ydata)
            else:
                self._dragging = True
                # Fixes a crash where the shape couldn't be grabbed
                # reliably, and when it was, dragging was too sensitive
                # and could move it thousands of
                # microns away quickly: remember WHERE within the shape
                # this click landed, relative to its own center, so
                # _on_canvas_motion can hold that same offset throughout
                # the drag instead of snapping the shape's center
                # straight to the cursor on the very first motion event
                # -- see _on_canvas_motion's own docstring for the second
                # half of this fix (a view-rescale feedback loop that
                # turned that initial snap into a runaway).
                self._drag_offset = (event.xdata - shp.cx, event.ydata - shp.cy)
        else:
            self._selected_junction_id = self._hit_test_junction_shape(event.xdata, event.ydata)
            if (self._selected_junction_id is not None
                    and self._shape_in_marquee_selection(stable_id=self._selected_junction_id)):
                # Same batch-move priority as the scene-shape
                # branch above, entered via a real junction finger/patch/
                # plate instead of a custom shape.
                self._push_undo_snapshot()
                self._selected_junction_id = None  # keep this a BATCH drag, not a single-shape one
                self._dragging_marquee = True
                self._drag_marquee_last_xy = (event.xdata, event.ydata)
                self._update_preview()
                return
            self._marquee_selection = None  # A plain click that lands on a
                                              # DIFFERENT single junction shape, or on empty
                                              # canvas (_selected_junction_id stays None), ends
                                              # any previously-committed batch (no-op if none)
            if self._selected_junction_id is None and self._layer_highlight:
                # Clicking far away or off the junction entirely clears
                # the highlight automatically. Reaching this point means the click hit
                # NOTHING at all (not a custom scene shape -- hit_id was
                # None, checked above -- and not a real junction finger/
                # patch/plate either, just confirmed by the
                # _hit_test_junction_shape call above returning None) --
                # exactly "off the junction entirely." A Layer highlight
                # (set via the Layers dock) previously only ever cleared
                # through that dock's own "Clear Highlight" button, Escape,
                # or Reset View -- an ordinary click elsewhere on the
                # canvas left it highlighted indefinitely, unlike the
                # single-shape/marquee-batch selection just above, which
                # already deselects this same way. This mirrors that exact
                # convention for the Layer highlight too, via the same
                # _set_layer_highlight(None) the dock's own button already
                # calls. Deliberately scoped to a genuinely EMPTY click --
                # clicking a specific shape that merely isn't part of the
                # highlighted layer takes its own, already-defined path
                # (ordinary single-shape select) and is left alone here.
                self._set_layer_highlight(None)
            # Once a shape is duplicated, it can be dragged to wherever
            # the user wants -- generalized here to every junction-native
            # finger/patch/plate, not just a freshly-duplicated one, since there
            # was no reason a real click-drag should work for a custom
            # shape but not one of these): a junction member has no
            # single cx/cy to snap-and-offset the way a custom shape's
            # drag does, so this instead just remembers the current mouse
            # position and _on_canvas_motion applies each frame's own
            # incremental delta via _translate_junction_member -- exactly
            # one undo snapshot for the whole drag (pushed here, once),
            # not one per motion event.
            if self._selected_junction_id is not None:
                self._push_undo_snapshot()
                if self._shape_in_highlighted_layer(stable_id=self._selected_junction_id):
                    # Same whole-layer drag as the custom-
                    # shape branch above, just entered via a real
                    # finger/patch/plate instead of a custom shape.
                    self._dragging_layer_category = self._layer_highlight
                    self._drag_layer_last_xy = (event.xdata, event.ydata)
                else:
                    self._dragging_junction_id = self._selected_junction_id
                    self._drag_junction_last_xy = (event.xdata, event.ydata)
            elif self.action_select.isChecked():
                # The rubber-band select tool is a feature that comes
                # with the Select button itself, rather than its own
                # separate button: the purpose of Select is to select
                # either single shapes or rubber-band whatever amount of
                # shapes are wanted. Reaching this branch means the click hit
                # NOTHING at all -- not a custom scene shape (hit_id was
                # None), not a real junction finger/patch/plate
                # (_selected_junction_id is None too) -- so a genuinely
                # empty click with Select active starts a rubber-band/
                # marquee drag instead of doing nothing. A plain click with
                # no real drag afterward still just deselects (matching
                # the old empty-click behavior exactly): _finish_marquee_
                # drag's own degenerate-drag guard commits no batch at all
                # in that case. The isChecked() guard here is belt-and-
                # suspenders -- every other tool (Pan/Ruler/Rect/Circle/
                # Polygon/role-assignment) already returned earlier in
                # this function, so Select is the only tool that can ever
                # reach this point, but this keeps that invariant explicit
                # rather than implicit. (self._marquee_selection was
                # already cleared just above, so a fresh drag always
                # starts clean, replacing whatever batch -- if any -- was
                # committed by an earlier one.)
                self._marquee_drag_start = (event.xdata, event.ydata)
        self._update_preview()

    def _on_polygon_click(self, event):
        """Multi-click polygon placement: each click (that isn't a
        double-click) adds a vertex; a double-click finishes the polygon
        using whatever vertices were already collected -- the second
        click of the double-click itself isn't added, avoiding a
        near-duplicate vertex on top of the one the first click of that
        same double-click already placed."""
        if event.dblclick:
            if len(self._pending_polygon_points) >= 3:
                self._push_undo_snapshot()
                # Freehand polygon drawing has too much freedom on its
                # own -- it's easy to end up with a crazy or misshapen
                # polygon when the intent was just a long rectangle.
                # Before committing the freshly-drawn vertex
                # list verbatim, run it through shape_editor's
                # regularize_drawn_polygon(), which snaps a shape that is
                # ALREADY fairly close to rectilinear (a wobbly rectangle,
                # triangle, trapezoid, or other near-clean polygon) into
                # an exact, evenly-dimensioned version -- rounded lengths,
                # a clean angle -- while leaving a genuinely irregular/
                # organic shape completely untouched (see that function's
                # own module-level docstring for the full algorithm). A
                # near-rectangle becomes a real kind="rect" shape (not a
                # 4-point polygon), so it plugs directly into every other
                # tool (Nudge & Scale, the Shape Properties card, role
                # classification/axis detection) exactly like one drawn
                # with the rectangle tool.
                result = regularize_drawn_polygon(self._pending_polygon_points)
                if result["kind"] == "rect":
                    self.electrode_scene.add(kind="rect", cx=result["cx"], cy=result["cy"],
                                             w=result["w"], h=result["h"],
                                             angle_deg=result["angle_deg"], role="electrode")
                else:
                    self.electrode_scene.add(kind="polygon", cx=0.0, cy=0.0, angle_deg=0.0,
                                             points=result["points"], role="electrode")
                if not self.custom_electrode_check.isChecked():
                    self.custom_electrode_check.setChecked(True)
                self.action_select.setChecked(True)  # this also clears _pending_polygon_points
                                                       # via _set_pending_shape_kind's cancel logic
                if hasattr(self, "import_status_label"):
                    if result["changed"]:
                        self.import_status_label.setText(f"Polygon auto-corrected: {result['note']}.")
                    else:
                        self.import_status_label.setText(
                            "Polygon kept exactly as drawn -- too irregular to confidently clean up.")
            # else: double-clicked with fewer than 3 points -- not enough
            # for a polygon yet, ignore and stay in polygon mode
            self._update_preview()
            return
        self._pending_polygon_points.append((event.xdata, event.ydata))
        self._update_preview()

    def _hit_test_tolerance(self) -> float:
        """A click-precision buffer in data coordinates (~1.5% of the
        current view width), so thin fingers/patches (often well under
        1um wide) don't require a pixel-perfect click to select --
        fingers are commonly 0.2-0.3um wide
        against a multi-um view, easy to miss with a real mouse."""
        x0, x1 = self._active_ax.get_xlim()
        return max(abs(x1 - x0) * 0.015, 0.05)

    def _hit_test_junction_shape(self, x, y):
        """Hit-test against the currently-drawn fingers/patches/plates
        (from the live parametric or imported junction) -- separate from
        electrode_scene.hit_test, which only covers custom-placed
        electrode shapes. Returns a stable_id or None. Topmost/last-drawn
        wins on overlap, matching ShapeScene's own convention."""
        junction = self._imported_junction if self._display_source == "imported" else self._junction
        if junction is None:
            return None
        pt = sg.Point(x, y)
        tol = self._hit_test_tolerance()
        for f in reversed(junction.fingers):
            if sg.Polygon(f.points).buffer(tol).contains(pt):
                return f.stable_id
        for s in reversed(junction.other_shapes):
            if sg.Polygon(s.points).buffer(tol).contains(pt):
                return s.stable_id
        return None

    # ------------------------------------------------------------------
    # Per-node/vertex editing + click-drag shape creation
    # ------------------------------------------------------------------
    def _shape_node_handles(self, shp) -> List[Tuple[float, float]]:
        """The draggable "node" points for a custom electrode_scene
        shape, in world coordinates: for "rect"/"circle"/"oval", the 4
        corners of its own (possibly rotated) bounding box -- the same
        box a rect literally is, and the box an ellipse's w/h are
        measured against -- in the SAME order to_world_polygon()'s own
        rect branch builds them ((-hw,-hh),(hw,-hh),(hw,hh),(-hw,hh))
        before rotation/translation, so index i's diagonally-OPPOSITE
        handle is always index (i+2)%4. For "polygon", every real vertex
        in shp.points is its own handle, dragged independently with no
        coupling to any other vertex."""
        if shp.kind == "polygon" and shp.points:
            return list(shp.points)
        hw, hh = shp.w / 2.0, shp.h / 2.0
        local = [(-hw, -hh), (hw, -hh), (hw, hh), (-hw, hh)]
        rad = math.radians(shp.angle_deg)
        cos_a, sin_a = math.cos(rad), math.sin(rad)
        return [(shp.cx + lx * cos_a - ly * sin_a, shp.cy + lx * sin_a + ly * cos_a) for lx, ly in local]

    def _hit_test_shape_node(self, shp, x: float, y: float) -> Optional[int]:
        """Index of shp's own node handle nearest (x, y), if within
        click tolerance -- else None. Only ever checked against the
        ALREADY-SELECTED shape (see _on_canvas_press), so a plain click
        elsewhere always falls through to ordinary whole-shape
        select/move instead of accidentally grabbing a node handle that
        merely happens to be nearby."""
        tol = self._hit_test_tolerance()
        best_idx, best_dist = None, tol
        for i, (hx, hy) in enumerate(self._shape_node_handles(shp)):
            d = math.hypot(x - hx, y - hy)
            if d <= best_dist:
                best_idx, best_dist = i, d
        return best_idx

    def _apply_node_drag(self, shp, node_index: int, anchor_world: Tuple[float, float],
                          mouse_x: float, mouse_y: float):
        """Reshapes shp so its OWN node `node_index` follows the cursor.

        For "polygon": trivial -- that one vertex simply becomes
        (mouse_x, mouse_y); every other vertex is untouched.

        For "rect"/"circle"/"oval": rotation-aware corner-handle resize,
        exactly matching how any ordinary vector editor's bounding-box
        handles behave -- the DIAGONALLY OPPOSITE corner (anchor_world,
        captured once when the drag started, at _on_canvas_press, and
        held fixed for the whole drag) stays exactly where it was in
        world space; angle_deg never changes; only w, h, and the center
        move. Derivation: work in the shape's own unrotated local frame
        with the anchor corner as its origin -- the vector from the
        anchor to the dragged corner is then exactly (+-w, +-h) (a full
        w/h, not a half, since the anchor is a full diagonal away, not
        the center) -- so inverse-rotating (mouse - anchor) by
        -angle_deg directly gives the new w/h magnitudes, and the new
        center is the midpoint of that same local vector, rotated back
        to world and added to the anchor."""
        if shp.kind == "polygon" and shp.points:
            pts = list(shp.points)
            if 0 <= node_index < len(pts):
                pts[node_index] = (mouse_x, mouse_y)
                shp.points = pts
            return
        ax, ay = anchor_world
        wx, wy = mouse_x - ax, mouse_y - ay
        rad = math.radians(shp.angle_deg)
        cos_a, sin_a = math.cos(rad), math.sin(rad)
        # inverse-rotate the world delta into the shape's own local frame
        local_dx = wx * cos_a + wy * sin_a
        local_dy = -wx * sin_a + wy * cos_a
        min_size = 0.02  # um -- never collapse to a literally zero/negative size mid-drag
        new_w = max(abs(local_dx), min_size)
        new_h = max(abs(local_dy), min_size)
        # re-sign the local delta to the ENFORCED (possibly floored) magnitude,
        # preserving whichever side of the anchor the cursor is currently on
        signed_dx = math.copysign(new_w, local_dx) if local_dx != 0 else new_w
        signed_dy = math.copysign(new_h, local_dy) if local_dy != 0 else new_h
        local_center_x, local_center_y = signed_dx / 2.0, signed_dy / 2.0
        # rotate that local center vector back to world and add the anchor
        world_center_dx = local_center_x * cos_a - local_center_y * sin_a
        world_center_dy = local_center_x * sin_a + local_center_y * cos_a
        shp.cx, shp.cy = ax + world_center_dx, ay + world_center_dy
        shp.w, shp.h = new_w, new_h

    # ------------------------------------------------------------------
    # Rotation-handle drag (custom electrode_scene shapes
    # and real junction fingers)
    # ------------------------------------------------------------------
    _ROTATE_HANDLE_OFFSET_TOL_MULT = 3.0  # how far the little circle sits beyond the shape's own
                                            # edge, in multiples of _hit_test_tolerance() -- deliberately
                                            # VIEW-RELATIVE, not shape-size-relative, so it stays a small,
                                            # constant, easy-to-grab distance from the shape at any zoom
                                            # level instead of growing huge on a large electrode or
                                            # vanishing on a tiny patch, and stays a small handle that
                                            # doesn't extend too far away from the shape.

    def _shape_rotation_handle_points(self, shp) -> Tuple[Tuple[float, float], Tuple[float, float], Tuple[float, float]]:
        """(pivot, line_start, handle) for shp's rotation handle, in
        world coordinates -- pivot is the point rotation actually
        happens around (shp's own center for "rect"/"circle"/"oval",
        since angle_deg is defined relative to (cx, cy); a "polygon"
        has no such point, so its own centroid is used instead, the
        same convenient, always-well-defined stand-in
        regularize_drawn_polygon's own rectangle-detection already
        uses for "the shape's own middle"). line_start is a point ON
        the shape's own boundary the connecting line is drawn FROM (so
        the handle reads as rigidly attached to the shape and visibly
        rotates along with it, never floating free); handle is the
        small draggable circle itself, _ROTATE_HANDLE_OFFSET_TOL_MULT
        view-relative hit-test-tolerances further out along the exact
        same direction.

        For "rect"/"circle"/"oval": line_start is the top-edge
        midpoint of the shape's own (possibly already-rotated)
        bounding box, in the exact same local-frame-then-rotate-then-
        translate convention _shape_node_handles' own corner math
        already uses, so the handle sweeps around the shape in lockstep
        with every other node as angle_deg changes.

        For "polygon": there is no fixed "top edge" (see
        EditableShape.to_world_polygon's own docstring: a polygon's
        points are always literal, already-in-world-coordinates, with
        no independent angle_deg applied on top) -- so this instead
        uses the polygon's own dominant axis (_min_rotated_rect_angle_deg,
        the same "which way is this shape mostly pointing" heuristic
        regularize_drawn_polygon already relies on) to pick a
        consistent "outward, perpendicular to the long axis" direction
        from the centroid, sized to the polygon's own actual half-
        extent along that direction so the handle sits just outside
        the shape's real silhouette rather than at an arbitrary fixed
        offset that might land INSIDE a large or oddly-shaped polygon."""
        tol = self._hit_test_tolerance()
        offset = self._ROTATE_HANDLE_OFFSET_TOL_MULT * tol
        if shp.kind == "polygon" and shp.points:
            pts = shp.points
            cx = sum(p[0] for p in pts) / len(pts)
            cy = sum(p[1] for p in pts) / len(pts)
            axis_deg = _min_rotated_rect_angle_deg(pts)
            up_rad = math.radians(axis_deg + 90.0)
            up_hat = (math.cos(up_rad), math.sin(up_rad))
            half_extent = max(abs((px - cx) * up_hat[0] + (py - cy) * up_hat[1]) for px, py in pts)
            if half_extent < 1e-9:
                half_extent = tol
            pivot = (cx, cy)
            line_start = (cx + up_hat[0] * half_extent, cy + up_hat[1] * half_extent)
            handle = (line_start[0] + up_hat[0] * offset, line_start[1] + up_hat[1] * offset)
            return pivot, line_start, handle
        hw, hh = shp.w / 2.0, shp.h / 2.0
        rad = math.radians(shp.angle_deg)
        cos_a, sin_a = math.cos(rad), math.sin(rad)

        def _to_world(lx, ly):
            return (shp.cx + lx * cos_a - ly * sin_a, shp.cy + lx * sin_a + ly * cos_a)

        pivot = (shp.cx, shp.cy)
        line_start = _to_world(0.0, hh)
        handle = _to_world(0.0, hh + offset)
        return pivot, line_start, handle

    def _hit_test_shape_rotation_handle(self, shp, x: float, y: float) -> bool:
        """True if (x, y) is within click tolerance of shp's own
        rotation handle -- only ever checked against the ALREADY-
        SELECTED shape (see _on_canvas_press), exactly like
        _hit_test_shape_node, so this can't be confused with a plain
        click merely landing near some other shape's handle."""
        tol = self._hit_test_tolerance()
        _pivot, _line_start, handle = self._shape_rotation_handle_points(shp)
        return math.hypot(x - handle[0], y - handle[1]) <= tol

    def _apply_shape_rotation_drag(self, shp, mouse_x: float, mouse_y: float) -> float:
        """Rotates shp so its own rotation-handle direction points at
        (mouse_x, mouse_y), and returns the new display angle (degrees)
        for the live Shape Properties readout.

        For "rect"/"circle"/"oval": angle_deg is a direct, absolute
        property (see EditableShape.to_world_polygon), so this is a
        one-line assignment every motion event -- the handle sits at
        local angle +90 degrees from the shape's own local +x axis (see
        _shape_rotation_handle_points), so world angle_deg is always
        exactly (mouse_angle_from_center - 90), independent of whatever
        angle_deg was a moment ago. cx/cy never move; matches typing a
        value directly into the Angle field (_on_property_edit).

        For "polygon": angle_deg has no live geometric effect (see
        EditableShape.to_world_polygon's own docstring), so
        this applies an INCREMENTAL rotation to the actual points --
        the total angle swept since the drag started (this frame's
        mouse angle around the centroid, minus the angle captured at
        drag-start in _on_canvas_press) -- to a SNAPSHOT of the
        polygon's points captured once at drag-start, never to
        whatever the previous motion event already left behind. This
        is the same "always measure from a fixed drag-start reference,
        not the previous frame's result" pattern _apply_node_drag's own
        rect-resize branch already uses (its anchor_world), which is
        what keeps a long, jittery drag numerically exact instead of
        silently accumulating rounding error frame over frame.
        angle_deg is kept in lockstep with this same swept delta purely
        as a continuous, jump-free display value (added onto whatever
        it was at drag-start, self._rotating_shape_start_angle_deg) --
        deliberately NOT re-derived from the polygon's own geometry
        (e.g. via _min_rotated_rect_angle_deg) on every frame, since
        that heuristic is only continuous modulo the bounding
        rectangle's own symmetry and can jump unpredictably as a shape
        rotates smoothly through certain angles."""
        if shp.kind == "polygon" and shp.points and self._rotating_shape_start_points is not None:
            start_pts = self._rotating_shape_start_points
            cx = sum(p[0] for p in start_pts) / len(start_pts)
            cy = sum(p[1] for p in start_pts) / len(start_pts)
            mouse_angle = math.degrees(math.atan2(mouse_y - cy, mouse_x - cx))
            delta = mouse_angle - self._rotating_shape_start_mouse_angle
            rad = math.radians(delta)
            cos_d, sin_d = math.cos(rad), math.sin(rad)
            new_points = []
            for px, py in start_pts:
                dx, dy = px - cx, py - cy
                new_points.append((cx + dx * cos_d - dy * sin_d, cy + dx * sin_d + dy * cos_d))
            shp.points = new_points
            shp.angle_deg = (self._rotating_shape_start_angle_deg + delta) % 360.0
            return shp.angle_deg
        mouse_angle = math.degrees(math.atan2(mouse_y - shp.cy, mouse_x - shp.cx))
        shp.angle_deg = (mouse_angle - 90.0) % 360.0
        return shp.angle_deg

    def _finger_rotation_handle_points(self, finger) -> Tuple[Tuple[float, float], Tuple[float, float]]:
        """(line_start, handle) for a real junction finger's rotation
        handle, in world coordinates -- the pivot is always finger.
        stub_end (see _apply_finger_rotation_drag's own docstring for
        why), so it isn't returned here; line_start sits at patch_end
        (the far end from the pivot -- the end that actually MOVES
        when the angle changes, exactly like the handle for a rect/
        circle/oval sits at the far, non-anchor side), and handle is
        _ROTATE_HANDLE_OFFSET_TOL_MULT view-relative hit-test-
        tolerances further out along the same axis."""
        tol = self._hit_test_tolerance()
        offset = self._ROTATE_HANDLE_OFFSET_TOL_MULT * tol
        patch_end = finger.patch_end
        theta_rad = math.radians(finger.theta_toward_patch_deg)
        axis_hat = (math.cos(theta_rad), math.sin(theta_rad))
        handle = (patch_end[0] + axis_hat[0] * offset, patch_end[1] + axis_hat[1] * offset)
        return patch_end, handle

    def _hit_test_finger_rotation_handle(self, finger, x: float, y: float) -> bool:
        tol = self._hit_test_tolerance()
        _line_start, handle = self._finger_rotation_handle_points(finger)
        return math.hypot(x - handle[0], y - handle[1]) <= tol

    def _apply_finger_rotation_drag(self, finger, mouse_x: float, mouse_y: float) -> float:
        """Rotates `finger` (a real ImportedFinger, imported or
        parametric) so its own axis points at (mouse_x, mouse_y),
        pivoting around its stub_end (held fixed) -- exactly matching
        apply_finger_edit's own default pivot when only theta_toward_
        patch_deg is edited (e.g. typing a value directly into the
        Shape Properties "Angle (deg):" field, _on_shape_finger_edit's
        source == "junction" branch), so dragging and typing always
        produce IDENTICAL geometry for the same angle -- never a second,
        subtly different rotation convention just because the input was
        a drag instead of a keystroke. Returns the new angle (0-360) for
        the live properties-panel readout.

        Imported designs mutate the real, persistent ImportedFinger in
        place every motion event (same as _translate_junction_member's
        own imported branch). A parametric design's junction is thrown
        away and rebuilt fresh from Design Parameters on every
        _update_preview() call, so this instead records the new angle
        as an absolute target in self._param_shape_edits (same
        mechanism _on_shape_finger_edit's own parametric branch uses),
        re-applied to each freshly-rebuilt junction by
        _apply_param_shape_edits -- length_um/width_um are read
        straight from the CURRENT finger object (already reflecting
        whatever was reapplied on the last rebuild) so a rotation drag
        alone can never silently reset either of them back to their
        un-edited design default."""
        stub_x, stub_y = finger.stub_end
        new_theta = math.degrees(math.atan2(mouse_y - stub_y, mouse_x - stub_x)) % 360.0
        if self._display_source == "imported":
            ji.apply_finger_edit(finger, theta_toward_patch_deg=new_theta)
            if self._imported_junction is not None:
                ji.recompute_derived_fields(self._imported_junction)
        elif finger.stable_id:
            prior_overlap = self._param_shape_edits.get(finger.stable_id, {}).get("overlap_um")
            self._param_shape_edits[finger.stable_id] = dict(
                kind="finger", length_um=finger.length_um, width_um=finger.width_um,
                theta_toward_patch_deg=new_theta, overlap_um=prior_overlap,
            )
        return new_theta

    def _translate_junction_member(self, stable_id, dx: float, dy: float):
        """The no-undo-push mutation core of _nudge_single_junction_member
        (which pushes exactly ONE undo snapshot before calling this) --
        factored out so a continuous mouse drag (see _on_canvas_motion)
        can apply many small per-frame deltas against the SAME single
        undo snapshot pushed once at drag-start (_on_canvas_press),
        instead of flooding the undo stack with one entry per motion
        event. Works for both imported (direct, persistent mutation) and
        parametric designs (accumulated into self._param_shape_offsets,
        re-applied by _update_preview after every rebuild), exactly like
        _nudge_single_junction_member's own docstring describes."""
        finger, shape = self._find_active_junction_shape(stable_id)
        if finger is None and shape is None:
            return
        if self._display_source == "imported":
            if finger is not None:
                ji.translate_finger(finger, dx, dy)
            else:
                ji.translate_shape(shape, dx, dy)
            ji.recompute_derived_fields(self._imported_junction)
        else:
            off = self._param_shape_offsets.get(stable_id, (0.0, 0.0))
            self._param_shape_offsets[stable_id] = (off[0] + dx, off[1] + dy)

    def _assign_role_at(self, x: float, y: float, role: str):
        """Click-a-tool-then-click-a-shape flow (same pattern as
        Rectangle/Circle): hit-tests whatever's under (x, y) -- a custom
        electrode shape first, then a finger/patch/plate -- and assigns
        the role directly, no separate select step required. Reverts to
        the Select tool only once a shape is actually hit (unlike
        Rectangle/Circle, a click can miss here, so staying in the tool
        lets the user just try again instead of having to re-click the
        toolbar icon)."""
        custom_id = self.electrode_scene.hit_test(x, y)
        if custom_id is not None:
            shp = self.electrode_scene.get(custom_id)
            shp.role = role
            self.electrode_scene.selected_id = custom_id
            self._selected_junction_id = None
            self.action_select.setChecked(True)
            self._update_preview()
            return
        junction_id = self._hit_test_junction_shape(x, y)
        if junction_id is not None:
            if self._display_source == "imported" and self._imported_junction is not None:
                self._reclassify_imported_shape(junction_id, role)
            else:
                self._role_overrides[junction_id] = role
            self._selected_junction_id = junction_id
            self.electrode_scene.selected_id = None
            self.action_select.setChecked(True)
            self._update_preview()
            return
        if hasattr(self, "import_status_label"):
            self.import_status_label.setText(
                f"No shape under that click -- try again (still in 'mark as {role}' mode).")

    def _reclassify_imported_shape(self, stable_id: str, role: str):
        """Real reclassification (not just cosmetic recoloring) for a
        junction member on an IMPORTED design. Found on a real GDS
        import: classify_fingers()
        misidentified a patch-integrated design's patches as fingers and
        the real fingers as patches, and using
        Mark-as-Finger/Mark-as-Patch to correct this didn't work -- the
        shape repainted, but the underlying junction.fingers/other_shapes
        split (and therefore every downstream consumer: the A/B labels,
        JJ crossing area, warning classification, deposition-angle
        recommendations, and the new Batch Edit Layer card) still used
        the ORIGINAL wrong split, since role_override was always
        deliberately cosmetic-only (see ImportedFinger/ImportedShape's
        own docstrings, predating this fix). Now, marking a real junction
        member as "Finger"/"Patch"/"Adhesion Plate" on an imported design
        actually converts and moves the object between
        junction.fingers/other_shapes (junction_import.
        promote_shape_to_finger/demote_finger_to_shape), preserving its
        stable_id, then recomputes everything from the corrected lists.

        "Electrode"/"Substrate" on a real junction member has no
        structural home in fingers/other_shapes (those come from
        electrode_polygons/electrode_material entirely separately, drawn
        independently of the finger/patch/plate lists) -- there's nothing
        to misclassify there, so those two stay cosmetic-only, exactly as
        every role always was before this fix.

        Only applies to an IMPORTED design (self._display_source ==
        "imported") -- a Created/parametric junction's fingers/patches
        are built directly from Design Parameters, never geometrically
        guessed, so there's no possible misclassification to correct
        there; marking one of ITS real junction members stays the
        original cosmetic-only behavior (matching its pre-existing,
        correct-by-construction status)."""
        junction = self._imported_junction
        finger = next((f for f in junction.fingers if f.stable_id == stable_id), None)
        shape = next((s for s in junction.other_shapes if s.stable_id == stable_id), None)
        if role == "finger":
            if shape is not None:
                ji.promote_shape_to_finger(junction, shape)
            # else: already a real finger -- nothing to convert.
        elif role in ("patch", "plate"):
            if finger is not None:
                ji.demote_finger_to_shape(junction, finger, role)
            elif shape is not None and shape.kind != role:
                shape.kind = role  # patch <-> plate: same structure, just relabel .kind
        else:
            # "electrode"/"substrate" -- no structural conversion exists
            # for these on a real junction member; kept cosmetic-only.
            self._role_overrides[stable_id] = role
            return
        ji.recompute_derived_fields(junction)
        # The object's REAL kind now matches what was asked for, so a
        # leftover cosmetic override under this same stable_id would only
        # cause confusion (or, worse, silently mask a FUTURE genuine
        # misclassification of whatever new shape ends up with this id).
        self._role_overrides.pop(stable_id, None)

    def _on_canvas_motion(self, event):
        if self._panning:
            if event.xdata is None or event.ydata is None:
                return
            dx = event.xdata - self._pan_last_xdata
            dy = event.ydata - self._pan_last_ydata
            xlim = self._active_ax.get_xlim()
            ylim = self._active_ax.get_ylim()
            self._active_ax.set_xlim(xlim[0] - dx, xlim[1] - dx)
            self._active_ax.set_ylim(ylim[0] - dy, ylim[1] - dy)
            self._active_canvas.draw()
            return  # deliberately NOT updating _pan_last_xdata/ydata -- see _on_canvas_press
        if event.xdata is None or event.ydata is None:
            return
        if self._marquee_drag_start is not None:
            # Deliberately NOT routed through _update_preview():
            # see _update_marquee_drag_rect's own docstring for why a plain
            # rectangle drag must never trigger the full design rebuild on
            # every motion-event frame.
            self._update_marquee_drag_rect(event.xdata, event.ydata)
            return
        if self._dragging_marquee:
            # The committed batch's own "Move" operation:
            # same incremental-per-frame-delta style as the whole-layer
            # canvas drag just below (_dragging_layer_category), just
            # against an explicit drag-selected id list instead of a
            # category filter.
            last_x, last_y = self._drag_marquee_last_xy
            dx, dy = event.xdata - last_x, event.ydata - last_y
            self._translate_marquee_selection(dx, dy)
            self._drag_marquee_last_xy = (event.xdata, event.ydata)
            self._update_preview()
            return
        if self._creating_shape_id is not None:
            # Click-drag shape creation: resize the shape
            # created at press-time so its anchor corner (the click
            # point) stays fixed and the opposite corner follows the
            # cursor -- i.e. the exact same rotation-aware corner-drag
            # math as a node-edit (_apply_node_drag), just with
            # angle_deg pinned at 0 (a freshly-placed shape is always
            # axis-aligned) and node_index=2 (the "far" corner in
            # to_world_polygon()'s own (-hw,-hh),(hw,-hh),(hw,hh),(-hw,hh)
            # ordering, diagonally opposite the (-hw,-hh) corner that
            # sits at the anchor).
            shp = self.electrode_scene.get(self._creating_shape_id)
            if shp is not None:
                self._apply_node_drag(shp, 2, self._creating_shape_anchor, event.xdata, event.ydata)
                self._update_preview()
            return
        if self._dragging_node_shape_id is not None:
            shp = self.electrode_scene.get(self._dragging_node_shape_id)
            if shp is not None:
                self._apply_node_drag(shp, self._dragging_node_index, self._dragging_node_anchor_world,
                                       event.xdata, event.ydata)
                self._update_preview()
            return
        if self._rotating_shape_id is not None:
            shp = self.electrode_scene.get(self._rotating_shape_id)
            if shp is not None:
                self._apply_shape_rotation_drag(shp, event.xdata, event.ydata)
                self._update_preview()
            return
        if self._rotating_finger_id is not None:
            finger, _shape = self._find_active_junction_shape(self._rotating_finger_id)
            if finger is not None:
                self._apply_finger_rotation_drag(finger, event.xdata, event.ydata)
                self._update_preview()
            return
        if self._rotating_layer_category is not None:
            # See _on_canvas_press's own comment: batch-
            # rotate the whole highlighted layer together, measured from
            # the fixed drag-start snapshot every frame (see
            # _apply_layer_rotation_drag's own docstring for why this is
            # a snapshot-based total delta, not a per-frame incremental
            # one like the layer DRAG case just below).
            self._apply_layer_rotation_drag(event.xdata, event.ydata)
            self._update_preview()
            return
        if self._dragging_layer_category is not None:
            # See _on_canvas_press's own comment: same
            # incremental-per-frame-delta style as the single-junction-
            # member drag below, just moving every shape classified into
            # the whole highlighted layer together (_translate_layer_
            # members) instead of one stable_id.
            last_x, last_y = self._drag_layer_last_xy
            dx, dy = event.xdata - last_x, event.ydata - last_y
            self._translate_layer_members(self._dragging_layer_category, dx, dy)
            self._drag_layer_last_xy = (event.xdata, event.ydata)
            self._update_preview()
            return
        if self._dragging_junction_id is not None:
            # See _on_canvas_press's own comment: apply just
            # THIS frame's incremental delta (not an absolute offset-from-
            # center like the custom-shape drag below), since a junction
            # member has no single cx/cy to snap against.
            last_x, last_y = self._drag_junction_last_xy
            dx, dy = event.xdata - last_x, event.ydata - last_y
            self._translate_junction_member(self._dragging_junction_id, dx, dy)
            self._drag_junction_last_xy = (event.xdata, event.ydata)
            self._update_preview()
            return
        if not self._dragging:
            return
        # See _on_canvas_press's own comment for the
        # full diagnosis: hold the same click-to-center offset recorded at
        # grab time throughout the drag, so the shape tracks the cursor
        # (matching every other drawing/CAD tool's convention) instead of
        # its center snapping straight onto the cursor on every motion
        # event. This alone fixes "couldn't grab it, then it flew away the
        # instant I did" -- the OTHER half of that report (view rescaling
        # mid-drag into a runaway feedback loop) is fixed separately, by
        # _update_create_import_preview preserving the current view during
        # ordinary redraws instead of re-fitting to content on every call.
        dx, dy = self._drag_offset
        self.electrode_scene.move_selected_to(event.xdata - dx, event.ydata - dy)
        self._update_preview()

    def _on_canvas_release(self, event):
        self._dragging = False
        self._panning = False
        if self._marquee_drag_start is not None:
            self._finish_marquee_drag(event)
            return
        if self._dragging_marquee:
            self._dragging_marquee = False
            self._drag_marquee_last_xy = None
        if self._creating_shape_id is not None:
            # Finalize the click-drag-created shape: a plain
            # click with no real drag leaves it at the near-zero epsilon
            # size _on_canvas_press seeded it with, which would be
            # invisible and unusable, so floor both dimensions to a small
            # but real, editable default instead of leaving a sliver.
            shp = self.electrode_scene.get(self._creating_shape_id)
            if shp is not None:
                min_visible = 0.2
                if shp.w < min_visible and shp.h < min_visible:
                    shp.w = shp.h = min_visible
                shp.capture_scale_base()  # this drawn size becomes the new "1.00" scale reference
                self.electrode_scene.selected_id = shp.id
            self._creating_shape_id = None
            self.action_select.setChecked(True)  # KLayout/Inkscape convention: placing one
                                                   # shape returns you to the select tool
            self._update_preview()
        if self._dragging_node_shape_id is not None:
            shp = self.electrode_scene.get(self._dragging_node_shape_id)
            if shp is not None:
                shp.capture_scale_base()  # the reshaped size/points become the new "1.00" reference
            self._dragging_node_shape_id = None
            self._dragging_node_index = None
        if self._rotating_shape_id is not None:
            shp = self.electrode_scene.get(self._rotating_shape_id)
            if shp is not None:
                shp.capture_scale_base()  # the rotated points/angle become the new "1.00" reference --
                                            # same convention a resize-drag's own release already follows
            self._rotating_shape_id = None
            self._rotating_shape_start_points = None
        if self._rotating_finger_id is not None:
            if self._display_source == "imported":
                finger, _shape = self._find_active_junction_shape(self._rotating_finger_id)
                if finger is not None and finger.stable_id:
                    # Same "a direct, deliberate edit re-baselines the Scale
                    # reference" convention _on_shape_finger_edit's own
                    # imported branch already follows after a typed Angle
                    # edit -- a rotation drag is just that same edit applied
                    # continuously instead of in one typed shot.
                    self._rebase_single_shape_scale_base(finger.stable_id, finger=finger)
            self._rotating_finger_id = None
        if self._rotating_layer_category is not None:
            # Same "a deliberate edit re-baselines the
            # Scale reference" convention the single-finger/shape
            # rotate release just above already follows, looped across
            # every member the just-finished batch rotate touched, so a
            # LATER individual Scale on any one of them measures from
            # its real, current (rotated) geometry -- never a stale
            # pre-rotate one.
            if self._display_source == "imported":
                for stable_id in self._rotating_layer_start_fingers:
                    finger, _shape = self._find_active_junction_shape(stable_id)
                    if finger is not None:
                        self._rebase_single_shape_scale_base(stable_id, finger=finger)
                for stable_id in self._rotating_layer_start_shapes:
                    _finger, shape = self._find_active_junction_shape(stable_id)
                    if shape is not None:
                        self._rebase_single_shape_scale_base(stable_id, shape=shape)
            for shp_id in self._rotating_layer_start_scene_shapes:
                shp = self.electrode_scene.get(shp_id)
                if shp is not None:
                    shp.capture_scale_base()
            self._rotating_layer_category = None
            self._rotating_layer_origin = None
            self._rotating_layer_start_fingers = {}
            self._rotating_layer_start_shapes = {}
            self._rotating_layer_start_scene_shapes = {}
        self._dragging_junction_id = None
        self._dragging_layer_category = None  # Whole-layer canvas drag, if one was active

    def _sync_property_fields(self):
        shp = self.electrode_scene.selected()
        for field in (self.prop_x, self.prop_y, self.prop_w, self.prop_h, self.prop_angle):
            field.blockSignals(True)
            field.setText("")
            field.blockSignals(False)
        if shp is not None:
            self.prop_x.setText(f"{shp.cx:g}")
            self.prop_y.setText(f"{shp.cy:g}")
            self.prop_w.setText(f"{shp.w:g}")
            self.prop_h.setText(f"{shp.h:g}")
            # The angle of the shape updates as it's being dragged and
            # rotated, shown to the nearest hundredth: 2 decimal places
            # instead
            # of the old bare :g, matching the finger Angle field's own
            # existing precision (shape_finger_angle). angle_deg is now
            # meaningful and exact for EVERY kind, "polygon" included --
            # see EditableShape.angle_deg's own field comment and
            # to_world_polygon's docstring for why a polygon tracks a
            # plain running total here instead of re-deriving "the
            # current angle" from its own geometry on every redraw.
            self.prop_angle.setText(f"{shp.angle_deg % 360.0:.2f}")
            self.shape_prop_status.setText(f"Selected: {shp.kind} ({shp.role})")
            if hasattr(self, "scale_edit"):
                self.scale_edit.blockSignals(True)
                self.scale_edit.setText(f"{shp.scale_factor:g}")  # reflects the factor
                                                                     # ACTUALLY applied right now,
                                                                     # relative to shp.base_w/h --
                                                                     # not reset to a fixed "1.00"
                self.scale_edit.blockSignals(False)
        else:
            self.shape_prop_status.setText("Select a shape to edit its properties.")
            if hasattr(self, "scale_edit"):
                self.scale_edit.blockSignals(True)
                self.scale_edit.setText("1.00")
                self.scale_edit.blockSignals(False)

    def _on_property_edit(self):
        shp = self.electrode_scene.selected()
        if shp is None:
            return
        try:
            new_cx = float(self.prop_x.text())
            new_cy = float(self.prop_y.text())
            new_w = float(self.prop_w.text())
            new_h = float(self.prop_h.text())
            new_angle = float(self.prop_angle.text())
        except ValueError:
            return
        self._push_undo_snapshot()
        if shp.kind == "polygon" and shp.points:
            # Typing directly into the
            # angle property gives precise control for the shape's angle:
            # angle_deg has no live GEOMETRIC effect for polygon kind
            # (see EditableShape.angle_deg's own field comment and
            # to_world_polygon's docstring), so a typed angle instead
            # directly rotates the real points around the shape's own
            # centroid by the delta from its CURRENT tracked angle_deg
            # (never re-derived from geometry -- see that same
            # docstring for why) -- the exact same operation the
            # rotation-handle drag performs (_apply_shape_rotation_
            # drag), so typing and dragging are two equivalent ways to
            # reach the same result, and angle_deg is kept in the same
            # continuous, jump-free lockstep either way. cx/cy/w/h are
            # deliberately left untouched here for polygon kind --
            # out of scope for this fix.
            cx = sum(p[0] for p in shp.points) / len(shp.points)
            cy = sum(p[1] for p in shp.points) / len(shp.points)
            rad = math.radians(new_angle - shp.angle_deg)
            cos_d, sin_d = math.cos(rad), math.sin(rad)
            shp.points = [(cx + (px - cx) * cos_d - (py - cy) * sin_d,
                           cy + (px - cx) * sin_d + (py - cy) * cos_d) for px, py in shp.points]
            shp.angle_deg = new_angle % 360.0
        else:
            shp.cx, shp.cy, shp.w, shp.h, shp.angle_deg = new_cx, new_cy, new_w, new_h, new_angle
        # A direct W/H edit is a deliberate resize, not a relative scale --
        # it becomes the new "1.00" reference for the Scale field below,
        # exactly like typing a fresh length/width does for an imported
        # shape (see _on_junction_property_edit). Without this, applying
        # a scale factor after a manual resize would measure against
        # whatever size the shape had BEFORE this edit, not the one just
        # typed in.
        shp.capture_scale_base()
        self._update_preview()

    def _apply_param_shape_edits(self, junction, only_ids=None):
        """Re-applies any pending Shape Properties edits (see
        _on_shape_finger_edit/_on_shape_patch_edit/_on_shape_plate_edit)
        onto a freshly-rebuilt PARAMETRIC junction -- same reason
        self._param_shape_offsets exists (see its own comment): that
        junction is thrown away and rebuilt from Design Parameters on
        every _update_preview() call, so there's nothing persistent to
        mutate in place the way an imported design's own junction
        allows. Each stored edit holds ABSOLUTE target values (not
        deltas), and "current" baselines apply_patch_extension_edit/
        apply_patch_group_margin_edit need are re-measured fresh here
        against the just-rebuilt (un-edited) geometry every time, rather
        than cached from edit time -- both together are what make this
        idempotent across repeated rebuilds instead of drifting.

        `only_ids`, when given, restricts this pass to just
        those stable_ids -- used to re-apply a pending edit onto a
        just-materialized PARAMETRIC duplicate (see
        _materialize_param_shape_duplicates, called right after this
        function normally runs its full, unrestricted pass over the
        junction as it existed BEFORE any duplicate existed) without
        re-running the full pass a second time over every original
        finger/patch/plate too (harmless in principle, since edits are
        idempotent absolute targets, but wasteful and an unnecessary
        second recompute_measurements() call for every patch edit)."""
        fingers_by_id = {f.stable_id: f for f in junction.fingers}
        shapes_by_id = {s.stable_id: s for s in junction.other_shapes}

        for stable_id, edit in list(self._param_shape_edits.items()):
            if only_ids is not None and stable_id not in only_ids:
                continue
            kind = edit.get("kind")
            if kind == "finger":
                finger = fingers_by_id.get(stable_id)
                if finger is None:
                    continue
                other = next((f for f in junction.fingers if f is not finger), None)
                overlap_um = edit.get("overlap_um")
                crossing_point = ji.finger_overlap_start_point(finger, other) if (overlap_um is not None and other is not None) else None
                ji.apply_finger_edit(finger, length_um=edit.get("length_um"), width_um=edit.get("width_um"),
                                     theta_toward_patch_deg=edit.get("theta_toward_patch_deg"),
                                     overlap_um=overlap_um, crossing_point=crossing_point)
            elif kind == "plate":
                shape = shapes_by_id.get(stable_id)
                if shape is None:
                    continue
                ji.apply_shape_edit(shape, length_um=edit.get("length_um"), width_um=edit.get("width_um"))
            elif kind == "patch":
                shape = shapes_by_id.get(stable_id)
                finger = fingers_by_id.get(edit.get("finger_stable_id"))
                if shape is None or finger is None:
                    continue
                report = ji.compute_measurements(junction)
                m = ji.measurements_by_stable_id(junction, report).get(stable_id, {})
                patch_angle_deg, _a, _b, _w = ji._polygon_axis_and_ends(shape.points)
                ji.apply_patch_extension_edit(shape, finger, patch_angle_deg,
                                              near_overhang_um=edit.get("near_overhang_um"),
                                              far_overhang_um=edit.get("far_overhang_um"),
                                              width_um=edit.get("width_um"),
                                              connector_union=ji.finger_connector_union(junction, finger))
                margin_target = edit.get("margin_um")
                group_margin = m.get("group_tip_past_last_patch_um")
                if margin_target is not None and group_margin is not None:
                    delta = margin_target - group_margin[2]
                    if abs(delta) > 1e-9:
                        groups = ji._assign_shapes_to_fingers(junction)
                        idx = junction.fingers.index(finger)
                        ji.apply_patch_group_margin_edit(groups.get(idx, []), finger, delta)
        ji.recompute_derived_fields(junction)

    def _apply_param_shape_deletions(self, junction):
        """Excludes any PARAMETRIC finger/patch/plate the user has
        deleted (see _delete_selected_shape) from a freshly-rebuilt
        junction -- same 'nothing persists across a rebuild, so persist
        the EDIT instead and re-apply it' strategy
        _param_shape_offsets/_param_shape_edits already use above.

        This used to filter only junction.other_shapes
        (patches/plates), refusing fingers outright -- see
        _param_shape_deletions' own declaration comment for the
        (now-superseded) reasoning. Fingers are structurally rebuilt from
        Design Parameters the same way patches are, and already carry
        stable_ids consistent across rebuilds (the pre-existing Nudge
        feature already relies on this, a few lines above this
        function), so the identical stable_id-filter strategy applies to
        junction.fingers with no new plumbing needed."""
        if not self._param_shape_deletions:
            return
        junction.fingers = [
            f for f in junction.fingers if f.stable_id not in self._param_shape_deletions
        ]
        junction.other_shapes = [
            s for s in junction.other_shapes if s.stable_id not in self._param_shape_deletions
        ]

    def _materialize_param_shape_duplicates(self, junction):
        """Re-derives every pending PARAMETRIC finger/patch/plate
        duplicate (see _duplicate_selected_shape) from its own source
        object on the freshly-rebuilt junction, every _update_preview()
        call -- same pattern as _apply_param_shape_edits just above, and
        called right after _apply_param_shape_deletions so a duplicate's
        clone always reflects the current (post-offset, post-edit,
        post-deletion) state of its source rather than a stale snapshot
        from whenever it was first duplicated. A duplicate whose source
        no longer exists this round (deleted since, or patch_count
        shrank under it) is silently skipped rather than raising -- it
        simply doesn't render until/unless its source reappears, the
        same quiet-skip behavior _apply_param_shape_edits already uses
        for a stale stable_id.

        (Renamed from _materialize_param_patch_duplicates,
        which only ever handled other_shapes): each pending entry now
        carries its own "kind" ("finger" or "shape", set at creation in
        _duplicate_selected_shape) so this function knows which of
        junction.fingers/.other_shapes to search for its source and
        append the clone to -- a plain dict.get("kind", "shape") default
        keeps any pre-existing entry from before this field existed
        (there shouldn't be any live ones, since this state doesn't
        survive a session restart, but it costs nothing to be safe)
        resolving exactly as it always did."""
        if not self._param_shape_duplicates:
            return
        fingers_by_id = {f.stable_id: f for f in junction.fingers}
        shapes_by_id = {s.stable_id: s for s in junction.other_shapes}
        for new_id, info in self._param_shape_duplicates.items():
            if info.get("kind") == "finger":
                source = fingers_by_id.get(info["source_stable_id"])
                if source is None:
                    continue
                clone = copy.deepcopy(source)
                clone.stable_id = new_id
                ji.translate_finger(clone, info["dx"], info["dy"])
                junction.fingers.append(clone)
            else:
                source = shapes_by_id.get(info["source_stable_id"])
                if source is None:
                    continue
                clone = copy.deepcopy(source)
                clone.stable_id = new_id
                ji.translate_shape(clone, info["dx"], info["dy"])
                junction.other_shapes.append(clone)

    def _current_shape_role_and_object(self):
        """Resolves what the consolidated Shape Properties card should
        show right now: (role, source, obj).
          role   -- "finger" | "patch" | "plate" | "none" (unclassified,
                    or explicitly electrode/substrate -- no specialized
                    fields exist for those, just the basic X/Y/W/H/Angle
                    form)
          source -- "custom" (an electrode_scene.EditableShape) or
                    "junction" (a real ImportedFinger/ImportedShape from
                    whichever junction is currently active -- imported OR
                    the auto-generated parametric one, via
                    _find_active_junction_shape, which is source-
                    agnostic -- this is what makes the old
                    display_source == "imported" gate unnecessary, see B1)
          obj    -- the EditableShape/ImportedFinger/ImportedShape
                    itself, or None if nothing is selected.
        A selected custom electrode_scene shape takes priority over a
        selected junction shape, matching _current_edit_target's own
        priority order."""
        shp = self.electrode_scene.selected()
        if shp is not None:
            role = shp.role if shp.role in ("finger", "patch", "plate") else "none"
            return role, "custom", shp
        if self._selected_junction_id is not None:
            finger, jshape = self._find_active_junction_shape(self._selected_junction_id)
            if finger is not None:
                return "finger", "junction", finger
            if jshape is not None:
                role = self._effective_shape_class(jshape)
                role = role if role in ("patch", "plate") else "none"
                return role, "junction", jshape
        return "none", None, None

    def _resolve_custom_finger_pair(self, shp):
        """For a custom, 'finger'-role electrode_scene shape, finds (this
        shape's resolved ImportedFinger, the OTHER finger) in whichever
        junction is currently active -- both already built by
        from_design_parameters's override resolution (see A2/A4), so
        this is a lookup, not a re-derivation. Matched by nearest
        centroid, the same heuristic from_design_parameters itself uses
        to decide which side a custom finger shape replaces. Returns
        (None, None) if no active junction exists yet, or nothing in it
        is a custom finger override."""
        junction = self._imported_junction if self._display_source == "imported" else self._junction
        if junction is None:
            return None, None
        candidates = [f for f in junction.fingers if f.role_override == "finger"]
        if not candidates:
            return None, None
        try:
            shp_centroid = sg.Polygon(shp.to_world_polygon()).centroid
            resolved = min(candidates, key=lambda f: sg.Polygon(f.points).distance(shp_centroid))
        except Exception:
            resolved = candidates[0]
        other = next((f for f in junction.fingers if f is not resolved), None)
        return resolved, other

    def _resolve_custom_junction_shape(self, shp, kind):
        """The patch/plate analog of _resolve_custom_finger_pair: for a
        custom electrode_scene shape marked role='patch' or role='plate',
        finds its resolved real ImportedShape in whichever junction is
        currently active. from_design_parameters turns every non-finger-
        role custom shape into a real other_shapes entry tagged
        role_override=<that role> (the 'Custom-placed shapes... become
        real ImportedShape entries here for every role EXCEPT finger'
        block, junction_import.py) -- this is a lookup against that
        result, not a re-derivation, matched by nearest centroid exactly
        like the finger case. Returns None if no active junction exists
        yet, or nothing in it is a matching custom override (e.g. the
        instant after drawing/marking, before the following
        _update_preview() has run once)."""
        junction = self._imported_junction if self._display_source == "imported" else self._junction
        if junction is None:
            return None
        candidates = [s for s in junction.other_shapes if s.kind == kind and s.role_override == kind]
        if not candidates:
            return None
        try:
            shp_centroid = sg.Polygon(shp.to_world_polygon()).centroid
            return min(candidates, key=lambda s: sg.Polygon(s.points).distance(shp_centroid))
        except Exception:
            return candidates[0]

    def _set_shape_patch_margin_field(self, group_margin):
        """"Margin before finger's
        end" is a single value shared by the WHOLE patch group (matching
        the parametric design's one shared tip-margin field,
        DesignParameters.patch_tip_margin_um) and is only ever MEASURED
        against the group's outermost patch -- every other patch in the
        group showed this exact same field, blank but still fully
        EDITABLE, which silently did nothing if typed into
        (group_tip_past_last_patch_um is None for a non-outermost patch,
        so _on_shape_patch_edit's own guard already skipped applying it)
        with nothing on screen explaining why. Typing
        the same target value repeatedly into what LOOKED like a working
        field (while actually selecting the last/outermost patch, where
        it genuinely does apply) produced runaway drift instead -- a
        SEPARATE bug in the underlying axis-direction math, fixed in
        _long_short_edge_indices, but this compounds the confusion: nothing
        here previously helped tell "it's not applying" apart from "it's
        applying but doing something wrong."

        Now the field is flatly DISABLED (not just blank) whenever the
        selected patch isn't the group's outermost one, with placeholder
        text pointing at the one patch where it does apply -- rather
        than leaving an editable-looking box that quietly no-ops."""
        if group_margin is not None:
            self.shape_patch_margin.setEnabled(True)
            self.shape_patch_margin.setPlaceholderText("")
            self.shape_patch_margin.setText(f"{group_margin[2]:.4f}")
        else:
            self.shape_patch_margin.setEnabled(False)
            self.shape_patch_margin.setText("")
            self.shape_patch_margin.setPlaceholderText("(edit on the outermost patch instead)")

    def _sync_shape_properties_panel(self):
        """Refreshes the consolidated Shape Properties card: which page
        is shown (basic/finger/patch/plate) and what's in its fields, for
        whatever _current_shape_role_and_object() resolves to right now.
        Mirrors the old per-card blockSignals + focus-guard pattern,
        generalized across all four pages at once so an in-progress
        redraw -- which runs on every canvas interaction, not just after
        an edit -- never clobbers a field the user is mid-typing in any
        of them. Pre-fills finger/patch/plate fields from
        self._shape_measurements (see junction_import.measurements_by_stable_id,
        populated fresh in _update_preview) -- the SAME real,
        already-computed numbers already shown when 'Measurements: On' is
        toggled, per the plan's Part B.

        Fixes a bug where after clicking and
        modifying one finger, then clicking on the other finger, the
        adhesion plates, the patches, etc., the card didn't change to
        the properties/measurements of those at all. Root cause: the
        focus-guard above (added so an in-progress redraw never clobbers
        a field you're mid-typing) checked ONLY "does any field have
        focus right now" -- with no check that the focus still belongs
        to the SAME shape this sync is about to run for. Committing an
        edit with Enter does not blur the QLineEdit (editingFinished
        fires, but focus stays right there), and clicking on the
        matplotlib canvas afterward does not reliably steal keyboard
        focus away from it either -- so after editing exactly one
        field once, that field could stay "focused" for the rest of the
        session, and the guard above then silently discarded every
        subsequent sync forever, for every shape clicked afterward, no
        matter which one. Fixed by keying the guard to the SELECTED
        shape's own identity: the guard only applies when the focused
        field's stale state belongs to the shape ALREADY on screen
        (nothing has changed, still genuinely mid-typing that one) --
        the instant a DIFFERENT shape becomes selected, the sync runs
        regardless of what still reports having focus, since a stale
        focus left over from the previous shape's field can never be
        "mid-typing" a value for a shape that wasn't even selected yet."""
        role, source, obj = self._current_shape_role_and_object()

        all_fields = (self.shape_finger_angle, self.shape_finger_lw_nm, self.shape_finger_length, self.shape_finger_overlap,
                      self.shape_patch_long_ext, self.shape_patch_short_ext, self.shape_patch_lw, self.shape_patch_margin,
                      self.shape_plate_length, self.shape_plate_width)
        stable_id = getattr(obj, "stable_id", None) if obj is not None else None
        identity = (role, source, stable_id if stable_id is not None else id(obj) if obj is not None else None)
        same_shape_as_last_sync = identity == getattr(self, "_shape_props_last_identity", None)
        self._shape_props_last_identity = identity
        if same_shape_as_last_sync and any(f.hasFocus() for f in all_fields):
            return

        self.shape_prop_stack.setCurrentIndex({"none": 0, "finger": 1, "patch": 2, "plate": 3}.get(role, 0))
        # Fingers and plates now genuinely
        # support delete/duplicate for a real junction-native object too
        # (source == "junction"), same as patches already did -- see
        # _delete_selected_shape/_duplicate_selected_shape's own
        # comments. Every one of these six buttons now shows for BOTH
        # "custom" (hand-drawn) and "junction" (real finger/patch/plate,
        # imported or parametric) sources.
        if hasattr(self, "shape_finger_delete_btn"):
            self.shape_finger_delete_btn.setVisible(source in ("custom", "junction"))
        if hasattr(self, "shape_finger_duplicate_btn"):
            self.shape_finger_duplicate_btn.setVisible(source in ("custom", "junction"))
        if hasattr(self, "shape_patch_delete_btn"):
            self.shape_patch_delete_btn.setVisible(source in ("custom", "junction"))
        if hasattr(self, "shape_patch_duplicate_btn"):
            self.shape_patch_duplicate_btn.setVisible(source in ("custom", "junction"))
        if hasattr(self, "shape_plate_delete_btn"):
            self.shape_plate_delete_btn.setVisible(source in ("custom", "junction"))
        if hasattr(self, "shape_plate_duplicate_btn"):
            self.shape_plate_duplicate_btn.setVisible(source in ("custom", "junction"))

        for f in all_fields:
            f.blockSignals(True)

        measurements = getattr(self, "_shape_measurements", {}) or {}

        if role == "none" or obj is None:
            if source is None:
                self.shape_prop_status.setText("Select a shape to edit its properties.")
            # basic page's own status/fields are handled by _sync_property_fields()

        elif role == "finger":
            if source == "custom":
                # A hand-drawn "finger"-role shape -- pull the REAL
                # resolved geometry (A2's electrode-distance stub/patch
                # classification, world angle) from the matching finger
                # in the currently-active junction, not the raw shape's
                # own ambiguous angle_deg (which could point either way
                # along the finger's axis until classified).
                resolved, other = self._resolve_custom_finger_pair(obj)
                if resolved is not None:
                    self.shape_prop_status.setText(
                        f"Selected: hand-drawn finger (stable_id={resolved.stable_id})")
                    self.shape_finger_angle.setText(f"{resolved.theta_toward_patch_deg:.2f}")
                    self.shape_finger_lw_nm.setText(f"{resolved.width_um * 1000.0:.2f}")
                    self.shape_finger_length.setText(f"{resolved.length_um:.4f}")
                    overlap = ji.finger_overlap_um(resolved, other) if other is not None else None
                    self.shape_finger_overlap.setText(f"{overlap:.4f}" if overlap is not None else "")
                else:
                    self.shape_prop_status.setText(
                        "Selected: hand-drawn finger shape (not yet resolved into the junction).")
                    self.shape_finger_angle.setText(f"{obj.angle_deg:.2f}")
                    self.shape_finger_lw_nm.setText(f"{obj.h * 1000.0:g}")
                    self.shape_finger_length.setText(f"{obj.w:g}")
                    self.shape_finger_overlap.setText("")
            else:
                m = measurements.get(obj.stable_id, {})
                self.shape_prop_status.setText(f"Selected: Finger ({obj.stable_id}), warning={obj.warning_source}")
                self.shape_finger_angle.setText(f"{obj.theta_toward_patch_deg:.2f}")
                self.shape_finger_lw_nm.setText(f"{obj.width_um * 1000.0:.2f}")
                self.shape_finger_length.setText(f"{obj.length_um:.4f}")
                overlap = m.get("overlap_um")
                self.shape_finger_overlap.setText(f"{overlap:.4f}" if overlap is not None else "")
            lw = getattr(self, "_last_suggested_linewidth_nm", None)
            self.shape_finger_suggested_lw.setText(f"(suggested: {lw:.1f} nm)" if lw is not None else "")

        elif role == "patch":
            if source == "custom":
                # A hand-drawn "patch"-role shape -- same pull-the-real-
                # resolved-object pattern as the finger/custom branch
                # above, since from_design_parameters turns this into a
                # real other_shapes entry too (just not one that mutates
                # the raw EditableShape's own w/h/stable_id fields --
                # those don't exist on it at all).
                resolved = self._resolve_custom_junction_shape(obj, "patch")
                if resolved is not None:
                    m = measurements.get(resolved.stable_id, {})
                    far = m.get("far_overhang_um")
                    near = m.get("near_overhang_um")
                    self.shape_patch_long_ext.setText(f"{far:.4f}" if far is not None else "")
                    self.shape_patch_short_ext.setText(f"{near:.4f}" if near is not None else "")
                    self.shape_patch_lw.setText(f"{resolved.width_um:.4f}")
                    group_margin = m.get("group_tip_past_last_patch_um")
                    self._set_shape_patch_margin_field(group_margin)
                    self.shape_prop_status.setText(
                        f"Selected: hand-drawn patch (stable_id={resolved.stable_id})"
                        + ("" if group_margin is not None else " -- not the outermost patch in its group"))
                else:
                    self.shape_prop_status.setText(
                        "Selected: hand-drawn patch shape (not yet resolved into the junction).")
                    self.shape_patch_long_ext.setText("")
                    self.shape_patch_short_ext.setText("")
                    self.shape_patch_lw.setText(f"{obj.w:g}")
                    self._set_shape_patch_margin_field(None)
            else:
                m = measurements.get(obj.stable_id, {})
                far = m.get("far_overhang_um")
                near = m.get("near_overhang_um")
                self.shape_patch_long_ext.setText(f"{far:.4f}" if far is not None else "")
                self.shape_patch_short_ext.setText(f"{near:.4f}" if near is not None else "")
                self.shape_patch_lw.setText(f"{obj.width_um:.4f}")
                group_margin = m.get("group_tip_past_last_patch_um")
                self._set_shape_patch_margin_field(group_margin)
                self.shape_prop_status.setText(
                    f"Selected: Patch ({obj.stable_id})"
                    + ("" if group_margin is not None else " -- not the outermost patch in its group"))

        elif role == "plate":
            if source == "custom":
                resolved = self._resolve_custom_junction_shape(obj, "plate")
                if resolved is not None:
                    self.shape_prop_status.setText(f"Selected: hand-drawn adhesion plate (stable_id={resolved.stable_id})")
                    self.shape_plate_length.setText(f"{resolved.length_um:.4f}")
                    self.shape_plate_width.setText(f"{resolved.width_um:.4f}")
                    m = measurements.get(resolved.stable_id, {})
                    finger_id = m.get("finger_stable_id")
                    self.shape_plate_attached_label.setText(f"Finger {finger_id}" if finger_id else "—")
                else:
                    self.shape_prop_status.setText(
                        "Selected: hand-drawn adhesion plate shape (not yet resolved into the junction).")
                    self.shape_plate_length.setText(f"{obj.h:g}")
                    self.shape_plate_width.setText(f"{obj.w:g}")
                    self.shape_plate_attached_label.setText("—")
            else:
                self.shape_prop_status.setText(f"Selected: Adhesion Plate ({obj.stable_id})")
                self.shape_plate_length.setText(f"{obj.length_um:.4f}")
                self.shape_plate_width.setText(f"{obj.width_um:.4f}")
                m = measurements.get(obj.stable_id, {})
                finger_id = m.get("finger_stable_id")
                self.shape_plate_attached_label.setText(f"Finger {finger_id}" if finger_id else "—")

        for f in all_fields:
            f.blockSignals(False)

    def _on_shape_finger_edit(self):
        """Applies edited Angle/Linewidth/Length/Overlap onto the
        currently-selected finger -- a real one (source="junction",
        straight through junction_import.apply_finger_edit, the same
        mechanism the old imported-only card used, now also working for
        the auto-generated parametric junction per B1) or a hand-drawn
        "finger"-role custom shape (source="custom" -- recomputes the
        EditableShape's own cx/cy/w/h/angle_deg so the NEXT redraw's
        from_design_parameters/A2 resolution reproduces the intended
        geometry: Angle rotates about the shape's own center; Length
        holds patch_end fixed (that's the end plates/patches attach to,
        so a plain resize shouldn't disturb them) unless Overlap is also
        typed, in which case the crossing-point formula from A3 places
        stub_end directly and patch_end follows from Length)."""
        role, source, obj = self._current_shape_role_and_object()
        if role != "finger" or obj is None:
            return

        def _read(field, current):
            text = field.text().strip()
            if not text:
                return current
            try:
                return float(text)
            except ValueError:
                return current

        if source == "junction":
            self._push_undo_snapshot()
            finger = obj
            is_imported = self._display_source == "imported"
            junction = self._imported_junction if is_imported else self._junction
            other = next((f for f in junction.fingers if f is not finger), None) if junction else None
            new_length = _read(self.shape_finger_length, finger.length_um)
            new_width_um = _read(self.shape_finger_lw_nm, finger.width_um * 1000.0) / 1000.0
            new_angle = _read(self.shape_finger_angle, finger.theta_toward_patch_deg)
            overlap_text = self.shape_finger_overlap.text().strip()
            overlap_um = None
            if overlap_text:
                try:
                    overlap_um = float(overlap_text)
                except ValueError:
                    pass

            if is_imported:
                crossing_point = ji.finger_overlap_start_point(finger, other) if (overlap_um is not None and other is not None) else None
                ji.apply_finger_edit(finger, length_um=new_length, width_um=new_width_um,
                                     theta_toward_patch_deg=new_angle,
                                     overlap_um=overlap_um, crossing_point=crossing_point)
                if finger.stable_id:
                    self._rebase_single_shape_scale_base(finger.stable_id, finger=finger)
                if junction is not None:
                    ji.recompute_derived_fields(junction)
            else:
                # A bare parametric finger is rebuilt from scratch on
                # every _update_preview() call -- store the ABSOLUTE
                # target values and let _apply_param_shape_edits()
                # re-apply them to each fresh rebuild, instead of
                # mutating a throwaway object directly (which
                # _update_preview()'s own rebuild would immediately
                # discard).
                if finger.stable_id:
                    self._param_shape_edits[finger.stable_id] = dict(
                        kind="finger", length_um=new_length, width_um=new_width_um,
                        theta_toward_patch_deg=new_angle, overlap_um=overlap_um,
                    )
            # Fixes a bug reported on a real GDS import, where the
            # electrode disappeared briefly and reshaped
            # strangely, requiring repeated adjustment until it came back.
            # A committed edit here (Enter/focus-loss on a property
            # field) can move a finger by a large, discrete amount in
            # one shot -- unlike a drag, which moves it by tiny amounts
            # across many motion events. The drag-stability fix in
            # _on_canvas_motion deliberately makes ordinary redraws
            # PRESERVE the current view (re-fitting on every redraw is
            # what caused that crash), but that same preserved, now-STALE
            # view is wrong the instant a one-shot edit moves the finger
            # somewhere the old crop doesn't cover -- the finger (and
            # anything measured relative to it) can end up partly or
            # entirely outside the fixed crop window, which reads as
            # things going missing or looking wrong until the view
            # happens to catch up. Safe to force a fresh fit here
            # specifically because this is a single, discrete, one-shot
            # redraw triggered by a committed field edit -- never a
            # per-pixel motion-event stream -- so it cannot reintroduce
            # the view-rescale feedback loop that fix was about.
            self._create_import_force_fit = True
            self._update_preview()
        else:
            shp = obj
            resolved, other = self._resolve_custom_finger_pair(shp)
            if resolved is None:
                # Not yet resolved into a real finger (e.g. first click
                # right after drawing, before a redraw has run) -- fall
                # back to the shape's own raw fields so Delete/basic
                # editing still works via the basic page instead.
                return
            new_length = _read(self.shape_finger_length, resolved.length_um)
            new_width_um = _read(self.shape_finger_lw_nm, resolved.width_um * 1000.0) / 1000.0
            new_theta = _read(self.shape_finger_angle, resolved.theta_toward_patch_deg)
            overlap_text = self.shape_finger_overlap.text().strip()

            theta_rad = math.radians(new_theta)
            axis_hat = (math.cos(theta_rad), math.sin(theta_rad))
            new_stub = None
            if overlap_text and other is not None:
                try:
                    overlap_um = float(overlap_text)
                    crossing = ji.finger_overlap_start_point(resolved, other)
                except ValueError:
                    crossing = None
                if crossing is not None:
                    new_stub = (crossing[0] - axis_hat[0] * overlap_um, crossing[1] - axis_hat[1] * overlap_um)
            if new_stub is None:
                # Anchor on patch_end (the end plates/patches attach to)
                # instead of stub_end, so a plain Length/Angle/Linewidth
                # edit never disturbs attachment -- the opposite anchor
                # from apply_finger_edit's own convention, deliberately,
                # since THIS end is the one other geometry depends on.
                new_patch_end = resolved.patch_end
                new_stub = (new_patch_end[0] - axis_hat[0] * new_length, new_patch_end[1] - axis_hat[1] * new_length)
            new_center = (new_stub[0] + axis_hat[0] * new_length / 2.0, new_stub[1] + axis_hat[1] * new_length / 2.0)

            self._push_undo_snapshot()
            shp.cx, shp.cy = new_center
            shp.w = new_length
            shp.h = new_width_um
            shp.angle_deg = new_theta
            shp.capture_scale_base()
            self._create_import_force_fit = True  # see the matching comment in the source=="junction"
                                                      # branch above -- same one-shot-edit re-fit fix
            self._update_preview()

    def _on_shape_patch_edit(self):
        """Applies edited long/short-side extension, linewidth, and group
        margin onto the currently-selected real patch --
        junction_import.apply_patch_extension_edit/apply_patch_group_margin_edit,
        reusing the exact u=lw/2/|sin(delta)| derivation build_side_patches
        itself uses. Works for source="junction" (a real patch on the
        active design) AND source="custom" (a hand-drawn shape marked
        'patch' -- resolved into its real ImportedShape counterpart via
        _resolve_custom_junction_shape, the same way _on_shape_finger_edit
        resolves a custom finger; from_design_parameters turns every
        role='patch' custom shape into a real other_shapes entry, it just
        isn't the SAME object as the raw EditableShape, which has no
        stable_id/width_um/length_um fields at all)."""
        role, source, obj = self._current_shape_role_and_object()
        if role != "patch" or obj is None:
            return
        is_imported = self._display_source == "imported"
        junction = self._imported_junction if is_imported else self._junction
        if junction is None:
            return
        if source == "custom":
            resolved = self._resolve_custom_junction_shape(obj, "patch")
            if resolved is None:
                return  # not yet resolved into the junction -- nothing to edit yet
            shape = resolved
        else:
            shape = obj
        m = getattr(self, "_shape_measurements", {}).get(shape.stable_id, {})
        finger = next((f for f in junction.fingers if f.stable_id == m.get("finger_stable_id")), None)
        if finger is None:
            return

        def _read(field):
            text = field.text().strip()
            if not text:
                return None
            try:
                return float(text)
            except ValueError:
                return None

        new_far = _read(self.shape_patch_long_ext)
        new_near = _read(self.shape_patch_short_ext)
        new_lw = _read(self.shape_patch_lw)
        new_margin = _read(self.shape_patch_margin)

        self._push_undo_snapshot()
        if is_imported:
            # The patch's OWN current axis angle -- an exact value
            # straight from its geometry (not an approximation via the
            # finger's own angle), matching what apply_patch_extension_edit
            # itself expects.
            patch_angle_deg, _end_a, _end_b, _cur_w = ji._polygon_axis_and_ends(shape.points)
            ji.apply_patch_extension_edit(shape, finger, patch_angle_deg,
                                          near_overhang_um=new_near, far_overhang_um=new_far,
                                          width_um=new_lw,
                                          connector_union=ji.finger_connector_union(junction, finger))
            group_margin = m.get("group_tip_past_last_patch_um")
            if new_margin is not None and group_margin is not None:
                delta = new_margin - group_margin[2]
                if abs(delta) > 1e-9:
                    groups = ji._assign_shapes_to_fingers(junction)
                    group_shapes = groups.get(junction.fingers.index(finger), [])
                    ji.apply_patch_group_margin_edit(group_shapes, finger, delta)
            ji.recompute_derived_fields(junction)
        else:
            # A bare parametric patch is rebuilt from scratch on every
            # _update_preview() call, exactly like a bare parametric
            # finger -- store ABSOLUTE targets and let
            # _apply_param_shape_edits() re-apply them (re-measuring
            # "current" near/far/margin fresh against each rebuild, so
            # this stays idempotent instead of drifting).
            if shape.stable_id:
                self._param_shape_edits[shape.stable_id] = dict(
                    kind="patch", finger_stable_id=finger.stable_id,
                    near_overhang_um=new_near, far_overhang_um=new_far,
                    width_um=new_lw, margin_um=new_margin,
                )
        self._create_import_force_fit = True  # see _on_shape_finger_edit's matching comment --
                                                  # same one-shot-edit re-fit fix, applies here too
        self._update_preview()

    def _on_shape_plate_edit(self):
        """Applies an edited Length/Width onto the currently-selected
        real adhesion plate -- junction_import.apply_shape_edit,
        unchanged (a plate resizes about its own center). Persisted via
        _param_shape_edits for a bare parametric plate, exactly like the
        finger/patch cases above, since it too is rebuilt from scratch
        on every _update_preview() call. Works for source="junction" and
        source="custom" (a hand-drawn shape marked 'plate' -- resolved
        via _resolve_custom_junction_shape, mirroring the patch case
        above)."""
        role, source, obj = self._current_shape_role_and_object()
        if role != "plate" or obj is None:
            return
        is_imported = self._display_source == "imported"
        junction = self._imported_junction if is_imported else self._junction
        if junction is None:
            return
        if source == "custom":
            resolved = self._resolve_custom_junction_shape(obj, "plate")
            if resolved is None:
                return
            shape = resolved
        else:
            shape = obj
        try:
            new_length = float(self.shape_plate_length.text())
            new_width = float(self.shape_plate_width.text())
        except ValueError:
            return
        self._push_undo_snapshot()
        if is_imported:
            ji.apply_shape_edit(shape, length_um=new_length, width_um=new_width)
            if shape.stable_id:
                self._rebase_single_shape_scale_base(shape.stable_id, shape=shape)
            ji.recompute_derived_fields(junction)
        else:
            if shape.stable_id:
                self._param_shape_edits[shape.stable_id] = dict(kind="plate", length_um=new_length, width_um=new_width)
        self._create_import_force_fit = True  # see _on_shape_finger_edit's matching comment --
                                                  # same one-shot-edit re-fit fix, applies here too
        self._update_preview()

    def _init_hotkey_system(self):
        """Builds self._hotkey_entries -- the live, per-window list of
        hotkey_registry.HotkeyEntry, defaults merged with anything saved
        in ~/.plassys_shadow_sim/hotkeys.json (hotkey_registry.
        load_overrides) -- and applies every entry's current_key to
        whatever it actually drives: its real QAction(s) for
        kind="action" entries, or self._hotkey_keyevent_combos (the
        lookup table MainWindow.keyPressEvent reads) for kind="keyevent"
        entries. Called once at the end of __init__, after every QAction
        this table references has actually been constructed -- in
        particular self.action_undo/self.action_redo (the TOOLBAR undo/
        redo buttons, built in _build_toolbar) are a second, independent
        QAction pair from the Edit-menu's own undo_action/redo_action
        (self._hk_action_undo_menu/_hk_action_redo_menu, built earlier
        in _build_menu_bar) -- both call self._undo/self._redo, so both
        need the SAME shortcut applied or they'd silently drift apart
        the moment either one is reassigned.

        Also called again (for just the changed entry) from the Settings
        > Hotkeys table every time a key is captured/cleared/reset, so a
        change takes effect immediately -- no restart needed."""
        self._hotkey_entries = hotkey_registry.merge_defaults_with_overrides()
        self._hotkey_action_refs = {
            "new_junction": [self._hk_action_new_junction],
            "save_design": [self._hk_action_save_design],
            "open_design_library": [self._hk_action_open_design_library],
            "undo": [self._hk_action_undo_menu, self.action_undo],
            "redo": [self._hk_action_redo_menu, self.action_redo],
            "delete_selected": [self._hk_action_delete_selected],
            "duplicate_selected": [self._hk_action_duplicate_selected],
            "zoom_to_fit": [self._hk_action_zoom_fit],
            "reset_view": [self._hk_action_reset_view],
        }
        self._hotkey_keyevent_combos = {}
        for entry in self._hotkey_entries:
            self._apply_hotkey_entry(entry)

    def _apply_hotkey_entry(self, entry):
        """Pushes one HotkeyEntry's current_key live: onto its real
        QAction(s) for kind="action" (Qt's shortcut map takes it from
        there), or into self._hotkey_keyevent_combos for kind="keyevent"
        (MainWindow.keyPressEvent's own _matches() reads it from there).
        An empty current_key ("no hotkey assigned") clears the QAction's
        shortcut / removes the keyevent entry entirely rather than
        leaving a stale binding active.

        For kind="action", this applies current_key PLUS
        every alias hotkey_registry.ALIAS_KEYS lists for this entry (via
        QAction.setShortcuts -- plural -- instead of setShortcut), so
        e.g. duplicate_selected always answers to both its own
        (possibly user-customized) primary key AND Ctrl+C/Cmd+D, and
        delete_selected always also answers to Backspace -- see
        ALIAS_KEYS' own module-level comment in hotkey_registry.py: the
        Mac delete key sends Backspace, not Del, and Ctrl+C is
        the more common duplicate convention. An
        empty current_key still clears the shortcut list entirely
        (aliases included) -- "no hotkey assigned" means none, not
        just the alias."""
        if entry.kind == "action":
            seqs = []
            if entry.current_key:
                seqs.append(QKeySequence(entry.current_key))
                for alias in hotkey_registry.ALIAS_KEYS.get(entry.id, []):
                    seqs.append(QKeySequence(alias))
            for action in self._hotkey_action_refs.get(entry.id, []):
                action.setShortcuts(seqs)
        else:
            self._hotkey_keyevent_combos[entry.id] = hotkey_registry.parse_key_combo(entry.current_key)

    def _set_hotkey(self, hotkey_id: str, new_key: str):
        """Settings > Hotkeys' actual write path: updates the one entry
        matching hotkey_id, applies it live (_apply_hotkey_entry), and
        persists every entry that differs from its own default (a
        sparse save -- hotkey_registry.entries_to_overrides -- so
        hotkeys.json only ever records real customizations, not the
        whole table). new_key == "" clears the assignment entirely
        (kind="action" -> QAction gets an empty QKeySequence; kind=
        "keyevent" -> the id is simply absent from
        self._hotkey_keyevent_combos, so _matches() never fires for it).
        Returns the updated HotkeyEntry, or None if hotkey_id isn't a
        real entry (shouldn't happen from the UI, but safe either way)."""
        for i, entry in enumerate(self._hotkey_entries):
            if entry.id == hotkey_id:
                updated = dataclasses.replace(entry, current_key=new_key)
                self._hotkey_entries[i] = updated
                self._apply_hotkey_entry(updated)
                hotkey_registry.save_overrides(hotkey_registry.entries_to_overrides(self._hotkey_entries))
                return updated
        return None

    def _push_undo_snapshot(self):
        """Call BEFORE any mutation to the live design state -- drag,
        delete, nudge, scale, placement, role change, or a real
        finger/patch/plate property edit.

        Fixes a bug where, in Create/Import, the undo and redo buttons
        appeared broken and had no effect. Root cause: this
        snapshot used to capture ONLY electrode_scene.shapes -- the
        hand-drawn custom shapes. But most real edits in this tab don't
        touch electrode_scene.shapes at all: a real imported junction's
        finger/patch/plate geometry is mutated directly on
        self._imported_junction, a bare parametric shape's edits are
        absolute-target dicts in self._param_shape_edits/
        _param_shape_offsets (that junction is rebuilt from scratch on
        every redraw, so THOSE dicts are the real persistent state, not
        the throwaway rebuilt object), and role reclassification / a
        shape's own scale baseline live in self._role_overrides/
        _junction_scale_base. Undo/redo silently had no effect on any of
        that -- exactly the broken symptom reported -- both because
        several mutating call sites never called this method at all
        (now fixed: see _on_shape_finger_edit's source=="junction"
        branch, _on_shape_patch_edit, _on_shape_plate_edit, and the
        role-override-clearing branch of _delete_selected_shape) and
        because even where it WAS called, the snapshot itself was
        missing everything but electrode_scene.shapes. Now captures/
        restores all six pieces of state together as one combined
        undo-stack entry, via _capture_undo_snapshot/_restore_undo_snapshot.
        Deep-copies are cheap here (a JJ design has at most a handful of
        fingers/patches/plates/custom shapes)."""
        self._undo_stack.append(self._capture_undo_snapshot())
        self._redo_stack.clear()
        if len(self._undo_stack) > 100:
            self._undo_stack.pop(0)
        self._update_undo_redo_enabled()

    def _capture_undo_snapshot(self):
        return dict(
            shapes=copy.deepcopy(self.electrode_scene.shapes),
            imported_junction=copy.deepcopy(self._imported_junction),
            param_shape_offsets=copy.deepcopy(self._param_shape_offsets),
            param_shape_edits=copy.deepcopy(self._param_shape_edits),
            param_shape_deletions=copy.deepcopy(self._param_shape_deletions),
            param_shape_duplicates=copy.deepcopy(self._param_shape_duplicates),
            junction_scale_base=copy.deepcopy(self._junction_scale_base),
            role_overrides=copy.deepcopy(self._role_overrides),
        )

    def _restore_undo_snapshot(self, snap):
        self.electrode_scene.shapes = snap["shapes"]
        self._imported_junction = snap["imported_junction"]
        self._param_shape_offsets = snap["param_shape_offsets"]
        self._param_shape_edits = snap["param_shape_edits"]
        self._param_shape_deletions = snap["param_shape_deletions"]
        self._param_shape_duplicates = snap["param_shape_duplicates"]
        self._junction_scale_base = snap["junction_scale_base"]
        self._role_overrides = snap["role_overrides"]

    def _update_undo_redo_enabled(self):
        if hasattr(self, "action_undo"):
            self.action_undo.setEnabled(bool(self._undo_stack))
            self.action_redo.setEnabled(bool(self._redo_stack))

    def _undo(self):
        if not self._undo_stack:
            return
        self._redo_stack.append(self._capture_undo_snapshot())
        self._restore_undo_snapshot(self._undo_stack.pop())
        self.electrode_scene.selected_id = None  # may no longer exist in the restored state
        self._selected_junction_id = None  # ditto for a restored junction finger/patch/plate
        self._marquee_selection = None  # ditto for an ad hoc batch's own member ids
        self._update_undo_redo_enabled()
        self._update_preview()

    def _redo(self):
        if not self._redo_stack:
            return
        self._undo_stack.append(self._capture_undo_snapshot())
        self._restore_undo_snapshot(self._redo_stack.pop())
        self.electrode_scene.selected_id = None
        self._selected_junction_id = None
        self._marquee_selection = None
        self._update_undo_redo_enabled()
        self._update_preview()

    def _delete_selected_shape(self):
        """Edit > Delete Selected Shape (hotkey-configurable, default
        Del/Backspace). Fixes a bug where the delete button did nothing:
        this feature now
        works on either a created junction or an imported junction. Root
        cause: a selected JUNCTION-native finger/patch/plate gets the
        exact same thick white selection outline as a selected CUSTOM
        electrode_scene shape (see imported_junction_view.py's
        selected_stable_id highlight vs.
        _draw_create_import_selected_custom_shape), so there was no
        visual way to tell them apart -- but this function only ever did
        anything for a custom shape, or for clearing a role override; any
        other junction-native selection was a silent, unexplained no-op
        that looked exactly like a broken button.

        Deleting or duplicating junction fingers or adhesion pads is
        supported, since a researcher may want to create a
        series of Manhattan junctions stacked on top of each other.
        A FINGER can now be deleted
        too, not just a patch/plate -- previously refused here because
        the shadow-simulation engine assumed exactly two (see this app's
        many `len(junction.fingers) == 2`/`fingers[0]`/`fingers[1]`
        call sites); the shadow sim should be able to treat a trench
        like any trench, regardless of how many junction fingers exist,
        so that assumption is being generalized away
        (see shadowing_design_rules.md's own dedicated section on this
        for exactly what already works today and what's still a
        disclosed, scoped follow-up) -- this Create/Import-side deletion
        is the first, self-contained piece of that: a junction can now
        genuinely go up, down, or to any finger/patch/plate COUNT the
        user wants, immediately, with full undo/redo. A plate, living in
        the identical other_shapes list a patch already does (just
        `kind="plate"` instead of `"patch"`), needed no new mechanism at
        all -- only the role check below ever refused it."""
        shp = self.electrode_scene.selected()
        if shp is not None:
            self._push_undo_snapshot()
            self.electrode_scene.remove(shp.id)
            self._update_preview()
            return

        role, source, obj = self._current_shape_role_and_object()
        if source == "junction" and role in ("patch", "plate"):
            stable_id = obj.stable_id
            self._push_undo_snapshot()
            if self._display_source == "imported" and self._imported_junction is not None:
                self._imported_junction.other_shapes = [
                    s for s in self._imported_junction.other_shapes if s.stable_id != stable_id
                ]
                ji.recompute_derived_fields(self._imported_junction)
            else:
                self._param_shape_deletions.add(stable_id)
            self._forget_junction_shape_id(stable_id)
            self._selected_junction_id = None
            self._update_preview()
            return

        if source == "junction" and role == "finger":
            stable_id = obj.stable_id
            self._push_undo_snapshot()
            if self._display_source == "imported" and self._imported_junction is not None:
                self._imported_junction.fingers = [
                    f for f in self._imported_junction.fingers if f.stable_id != stable_id
                ]
                ji.recompute_derived_fields(self._imported_junction)
            else:
                # A bare PARAMETRIC finger is normally derived fresh from
                # Design Parameters on every rebuild, same "nothing
                # persists across a rebuild" problem _param_shape_offsets/
                # _param_shape_edits already solve for -- reuse the SAME
                # deletion set patches/plates already use (it's just a
                # set of stable_ids; _apply_param_shape_deletions below
                # now filters BOTH junction.fingers and .other_shapes
                # against it, so one mechanism covers every shape kind).
                self._param_shape_deletions.add(stable_id)
            self._forget_junction_shape_id(stable_id)
            self._selected_junction_id = None
            self._update_preview()
            return

        # A role override IS a standalone thing the user added (not
        # derived from DesignParameters), so "delete" on a selected
        # shape that's been cosmetically marked as electrode/substrate
        # (role resolves to "none") clears it back to the default
        # classification -- unchanged from before this fix.
        if self._selected_junction_id is not None and self._selected_junction_id in self._role_overrides:
            self._push_undo_snapshot()
            del self._role_overrides[self._selected_junction_id]
            self._update_preview()
            return

    def _clone_imported_patch(self, junction, shape):
        """Deep-copies a real, persistent (imported-junction) patch/plate
        a short offset away and appends it directly to the junction --
        the ImportedJunction/ImportedShape equivalent of
        ShapeScene.duplicate (shape_editor.py), for a junction whose
        other_shapes list is real mutable state rather than something
        rebuilt from scratch every redraw. Returns the clone's new
        stable_id."""
        clone = copy.deepcopy(shape)
        clone.stable_id = uuid.uuid4().hex[:8]
        dx = max(shape.width_um, 0.2) * 0.2
        dy = max(shape.length_um, 0.2) * 0.2
        ji.translate_shape(clone, dx, dy)
        junction.other_shapes.append(clone)
        return clone.stable_id

    def _clone_imported_finger(self, junction, finger):
        """The finger equivalent of _clone_imported_patch,
        for a real (imported) junction's own persistent junction.fingers
        list: deep-copies the finger, gives it a fresh stable_id, and
        rigidly translates every one of its geometric fields (points,
        stub_end, patch_end -- ji.translate_finger already carries all
        three together, unlike translate_shape's plain points-only
        move) a short offset away so the clone doesn't land exactly on
        top of its source. Returns the clone's new stable_id."""
        clone = copy.deepcopy(finger)
        clone.stable_id = uuid.uuid4().hex[:8]
        dx = max(finger.width_um, 0.2) * 0.2
        dy = max(finger.width_um, 0.2) * 0.2
        ji.translate_finger(clone, dx, dy)
        junction.fingers.append(clone)
        return clone.stable_id

    def _forget_junction_shape_id(self, stable_id):
        """Cleans up every piece of per-shape state this app keeps keyed
        by stable_id once that shape is genuinely gone (deleted, or was
        itself a duplicate that's being deleted) -- avoids orphaned
        entries silently accumulating in _role_overrides/
        _param_shape_offsets/_param_shape_edits/_param_shape_duplicates
        forever. Also cascades: if the deleted shape was the SOURCE of
        any pending duplicate(s), those duplicates are dropped too rather
        than left to be silently skipped every future rebuild (see
        _materialize_param_shape_duplicates)."""
        self._role_overrides.pop(stable_id, None)
        self._param_shape_offsets.pop(stable_id, None)
        self._param_shape_edits.pop(stable_id, None)
        self._param_shape_duplicates.pop(stable_id, None)
        for dup_id in [k for k, v in self._param_shape_duplicates.items() if v.get("source_stable_id") == stable_id]:
            del self._param_shape_duplicates[dup_id]

    def _duplicate_selected_shape(self):
        """Edit > Duplicate Selected Shape (hotkey-configurable, default
        Ctrl+D -- also always answers to Ctrl+C/Cmd+C, see
        hotkey_registry.ALIAS_KEYS): clones the selected shape a short
        offset away and selects the clone -- undoable, the same
        _push_undo_snapshot()-before-mutation pattern every other edit in
        this file follows.

        Fixes a bug alongside the delete bug
        above (same root cause: a selected junction-native patch looks
        exactly like a selected custom shape, but this used to be an
        unconditional no-op for anything that wasn't a custom
        electrode_scene shape). Now genuinely duplicates a selected
        patch/plate from either kind of junction.

        (See _delete_selected_shape's own
        docstring for background): a FINGER can now be duplicated
        too, via _clone_imported_finger (imported designs) or the same
        _param_shape_duplicates mechanism patches/plates already use
        (parametric designs -- see _materialize_param_shape_duplicates,
        which now looks up a duplicate's source in EITHER
        junction.fingers or .other_shapes and appends the clone to
        whichever list its source came from)."""
        shp = self.electrode_scene.selected()
        if shp is not None:
            self._push_undo_snapshot()
            self.electrode_scene.duplicate(shp.id)
            self._update_preview()
            return

        role, source, obj = self._current_shape_role_and_object()
        if source == "junction" and role in ("patch", "plate"):
            stable_id = obj.stable_id
            self._push_undo_snapshot()
            if self._display_source == "imported" and self._imported_junction is not None:
                new_id = self._clone_imported_patch(self._imported_junction, obj)
            else:
                new_id = uuid.uuid4().hex[:8]
                dx = max(obj.width_um, 0.2) * 0.2
                dy = max(obj.length_um, 0.2) * 0.2
                self._param_shape_duplicates[new_id] = {
                    "source_stable_id": stable_id, "dx": dx, "dy": dy, "kind": "shape",
                }
            self._selected_junction_id = new_id
            self._update_preview()
            return

        if source == "junction" and role == "finger":
            stable_id = obj.stable_id
            self._push_undo_snapshot()
            if self._display_source == "imported" and self._imported_junction is not None:
                new_id = self._clone_imported_finger(self._imported_junction, obj)
                ji.recompute_derived_fields(self._imported_junction)
            else:
                new_id = uuid.uuid4().hex[:8]
                dx = max(obj.width_um, 0.2) * 0.2
                dy = max(obj.width_um, 0.2) * 0.2
                self._param_shape_duplicates[new_id] = {
                    "source_stable_id": stable_id, "dx": dx, "dy": dy, "kind": "finger",
                }
            self._selected_junction_id = new_id
            self._update_preview()
            return

    def _find_active_junction_shape(self, stable_id):
        """Like _find_imported_shape, but resolves against whichever
        junction is actually active right now (imported OR parametric) --
        lets the unified Nudge & Scale card act on a single selected
        finger/patch/plate regardless of design source, not just
        imported ones."""
        junction = self._imported_junction if self._display_source == "imported" else self._junction
        if junction is None or not stable_id:
            return None, None
        finger = next((f for f in junction.fingers if f.stable_id == stable_id), None)
        if finger is not None:
            return finger, None
        shape = next((s for s in junction.other_shapes if s.stable_id == stable_id), None)
        return None, shape

    def _current_edit_target(self):
        """Resolves what the unified Nudge & Scale card acts on right
        now. 'Batch Edit Selected Layer'
        and 'Nudge and Scale (Selected Shape)' are now ONE control -- a
        single selected shape (custom electrode shape, or a clicked
        junction finger/patch/plate) takes priority; with nothing
        individually selected, it falls back to whichever Layer is
        highlighted in the Layers dock, acting on every shape in it at
        once. Returns (kind, target):
          ("marquee", <selection dict>)      -- an ad hoc
                                                  drag-selected batch (see
                                                  _finish_marquee_drag) --
                                                  Nudge/Scale/Move only,
                                                  no per-type parameter
                                                  editing surface
          ("scene_shape", <ElectrodeShape>)  -- a custom placed shape
          ("junction_shape", stable_id)      -- one selected finger/patch/plate
          ("layer", category)                -- every shape in a Layer
          (None, None)                       -- nothing to act on

        A committed marquee batch is checked FIRST, ahead of a
        single-shape selection -- in practice this never actually
        competes with one, since committing a batch (_finish_marquee_
        drag) and grabbing a DIFFERENT single shape (_on_canvas_press)
        each explicitly clear the other's selection state as part of the
        same click; this ordering is just the belt-and-suspenders
        priority that matches how deliberately-explicit the batch is."""
        if self._marquee_selection is not None:
            return "marquee", self._marquee_selection
        shp = self.electrode_scene.selected()
        if shp is not None:
            return "scene_shape", shp
        if self._selected_junction_id is not None:
            return "junction_shape", self._selected_junction_id
        if self._layer_highlight:
            return "layer", self._layer_highlight
        return None, None

    def _group_scale_current_factor(self, group_key, fingers, shapes):
        """The REAL current cumulative Scale factor for a scale group
        (a single shape -- a group of one -- or a whole highlighted
        Layer), i.e. how big its members actually are right now versus
        their TRUE original ("1.00") geometry, per _apply_junction_group_
        scale's own cached base. Returns 1.0 if this group has never
        been scaled yet (nothing cached), or if it contains no members.

        Fixes a bug where a scale briefly applied but then reverted as
        soon as focus moved elsewhere, only coming back after pressing
        undo. The OLD Layer-scale branch of this same status refresh
        unconditionally hardcoded the Scale field back to "1.00" after
        every single apply, no matter what factor had actually just been
        set -- so if the field was touched again for ANY reason
        (pressing Enter again, clicking Apply again, or simply losing
        focus, which re-fires this same handler), it read that
        wrongly-reset "1.00" as the new ABSOLUTE target and silently
        reset the WHOLE layer back to its unscaled original size. This
        computes and shows the real, honest number instead, exactly the
        way the single-shape branch already correctly did -- so the
        field can never again lie about what's actually on screen, and
        re-touching it can never revert anything by accident."""
        group = self._junction_scale_base.get(group_key)
        if not group:
            return 1.0
        finger_bases = group.get("fingers", {})
        shape_bases = group.get("shapes", {})
        for f in fingers:
            fb = finger_bases.get(f.stable_id)
            if fb is None:
                continue
            base_stub, base_patch_end, _base_width = fb
            base_length = math.hypot(base_patch_end[0] - base_stub[0], base_patch_end[1] - base_stub[1])
            return (f.length_um / base_length) if base_length else 1.0
        for s in shapes:
            base_points = shape_bases.get(s.stable_id)
            if base_points is None:
                continue
            _angle, end_a, end_b, _w = ji._polygon_axis_and_ends(base_points)
            base_length = math.hypot(end_b[0] - end_a[0], end_b[1] - end_a[1])
            return (s.length_um / base_length) if base_length else 1.0
        return 1.0

    def _on_scale_slider_moved(self, value: int):
        """Fires on every tick while the user drags the Scale slider (or
        nudges it with arrow keys): updates the Scale text field so it
        always shows the exact number the slider currently represents,
        AND live-applies that factor to the actual geometry: as the
        slider is dragged, the measurements and the visuals of the
        junction or the selected layer update, so the scaling applies
        immediately, instead of the old behavior where
        dragging only moved a live numeric readout and the real Scale
        didn't apply until the slider was released.

        Still pushes exactly ONE undo snapshot per gesture, not one per
        motion event (matching _drag_undo_pushed's existing convention
        elsewhere in this file, e.g. the rotation-handle drag): the
        FIRST tick of a fresh mouse drag (self.scale_slider.isSliderDown()
        just became True) pushes the snapshot and sets self._scale_drag_
        undo_pushed; every subsequent tick of that same drag applies
        with push_undo=False. _on_scale_slider_released resets the flag
        so the next drag gets its own fresh snapshot. A keyboard arrow-
        key nudge has no press/release pair at all (isSliderDown() is
        never True for it) -- each keypress is its own atomic step, so
        it always pushes its own snapshot, same as clicking a Nudge
        button once.

        Repeatedly re-applying mid-drag is safe/idempotent: apply_scale
        and _apply_junction_group_scale both measure from a cached
        "1.00" base captured once at the start of a scale gesture (see
        their own docstrings), never from the last-applied size, so
        replaying this with a different factor every tick can never
        compound or drift.

        A purely programmatic value change (from _sync_scale_slider,
        e.g. after selecting a different shape/layer) never reaches
        here since that call always wraps setValue in blockSignals."""
        factor = 10 ** (value / 1000.0)
        self.scale_edit.blockSignals(True)
        self.scale_edit.setText(f"{factor:.3g}")
        self.scale_edit.blockSignals(False)
        dragging = self.scale_slider.isSliderDown()
        if dragging and self._scale_drag_undo_pushed:
            self._on_scale_apply(factor=factor, push_undo=False)
        else:
            self._on_scale_apply(factor=factor, push_undo=True)
            if dragging:
                self._scale_drag_undo_pushed = True

    def _on_scale_slider_released(self):
        """Resets the Scale slider's own per-gesture undo-push flag --
        the drag itself already applied live, tick by tick, in
        _on_scale_slider_moved, so there is nothing left to re-apply
        here; this just prepares self._scale_drag_undo_pushed for the
        NEXT drag gesture."""
        self._scale_drag_undo_pushed = False

    def _sync_scale_slider(self, cur_factor: float):
        """Positions the Scale slider to match cur_factor (the real
        cumulative factor _sync_nudge_scale_panel just computed for
        whatever is currently selected), via the same log10 mapping
        _on_scale_slider_moved uses in reverse. Always wrapped in
        blockSignals so re-displaying the current state can never itself
        trigger an apply."""
        if not hasattr(self, "scale_slider"):
            return
        safe_factor = cur_factor if cur_factor and cur_factor > 0 else 1.0
        safe_factor = max(0.1, min(10.0, safe_factor))
        value = int(round(1000.0 * math.log10(safe_factor)))
        value = max(-1000, min(1000, value))
        self.scale_slider.blockSignals(True)
        self.scale_slider.setValue(value)
        self.scale_slider.blockSignals(False)

    def _sync_nudge_scale_panel(self):
        """Refreshes the unified Nudge & Scale card's status line + Scale
        field/slider to reflect whatever _current_edit_target() resolves
        to right now -- called every time _update_preview() runs (see
        its tail), so it always agrees with the canvas selection/
        highlight state."""
        if not hasattr(self, "nudge_scale_status"):
            return
        kind, target = self._current_edit_target()
        cur_factor = 1.0
        if kind == "marquee":
            scene_shapes, fingers, shapes = self._marquee_live_members()
            n = len(scene_shapes) + len(fingers) + len(shapes)
            suffix = ("" if self._display_source == "imported" else
                      " -- Scale only applies to custom-placed shapes in this batch for a created "
                      "design (Nudge/Move still moves everything)")
            self.nudge_scale_status.setText(
                f"Acting on: dragged selection ({n} shape(s)) -- Nudge, Scale, and Move only; "
                f"exact per-type parameters aren't available for a mixed batch.{suffix}")
            cur_factor = (self._group_scale_current_factor("__marquee__", fingers, shapes)
                          if self._display_source == "imported" else 1.0)
            self.scale_edit.blockSignals(True)
            self.scale_edit.setText(f"{cur_factor:g}")
            self.scale_edit.blockSignals(False)
        elif kind == "scene_shape":
            self.nudge_scale_status.setText(f"Acting on: selected {target.kind} ({target.role})")
            cur_factor = target.scale_factor
            self.scale_edit.blockSignals(True)
            self.scale_edit.setText(f"{cur_factor:g}")
            self.scale_edit.blockSignals(False)
        elif kind == "junction_shape":
            finger, shape = self._find_active_junction_shape(target)
            label = None
            if finger is not None:
                label = f"Finger ({finger.stable_id})"
                cur_factor = self._group_scale_current_factor(target, [finger], [])
            elif shape is not None:
                kind_label = "Patch" if shape.kind == "patch" else "Adhesion Plate"
                label = f"{kind_label} ({shape.stable_id})"
                cur_factor = self._group_scale_current_factor(target, [], [shape])
            if label:
                suffix = ("" if self._display_source == "imported" else
                          " -- Scale not available for a created design's junction shapes "
                          "(use the Parameters panel instead); Nudge still works.")
                self.nudge_scale_status.setText(f"Acting on: selected {label}{suffix}")
                if self._display_source != "imported":
                    cur_factor = 1.0
                self.scale_edit.blockSignals(True)
                self.scale_edit.setText(f"{cur_factor:g}")
                self.scale_edit.blockSignals(False)
            else:
                self.nudge_scale_status.setText("Select a shape (click it), or a Layer in the "
                                                 "Layers tree above, to Nudge/Scale it.")
        elif kind == "layer":
            label = self._LAYER_CATEGORY_LABELS.get(target, target)
            scene_shapes = self._layer_scene_shapes(target)
            fingers, shapes = self._layer_junction_members(target)
            n = len(scene_shapes) + len(fingers) + len(shapes)
            suffix = ("" if self._display_source == "imported" else
                      " -- layer Scale not available for a created design (Nudge still works)")
            self.nudge_scale_status.setText(f"Acting on: Layer “{label}” ({n} shape(s)){suffix}")
            cur_factor = (self._group_scale_current_factor(target, fingers, shapes)
                          if self._display_source == "imported" else 1.0)
            self.scale_edit.blockSignals(True)
            self.scale_edit.setText(f"{cur_factor:g}")
            self.scale_edit.blockSignals(False)
        else:
            self.nudge_scale_status.setText("Select a shape (click it), or a Layer in the "
                                             "Layers tree above, to Nudge/Scale it.")
        self._sync_scale_slider(cur_factor)

    def _nudge_single_junction_member(self, stable_id, dx, dy):
        """Nudges ONE selected finger/patch/plate -- works for both
        imported (direct, persistent mutation) and parametric designs
        (recorded into self._param_shape_offsets, re-applied by
        _update_preview after every rebuild -- see that dict's own
        comment). Single-shape Nudge
        previously only ever worked on a custom electrode_scene shape; a
        selected junction finger/patch/plate had no individual nudge at
        all before (only the layer-wide batch edit touched junction
        geometry, and even that was broken for parametric designs --
        see _on_layer_nudge)."""
        finger, shape = self._find_active_junction_shape(stable_id)
        if finger is None and shape is None:
            return
        self._push_undo_snapshot()
        self._translate_junction_member(stable_id, dx, dy)
        self._update_preview()

    def _rebase_single_shape_scale_base(self, stable_id, finger=None, shape=None):
        """(Re-)establishes stable_id's OWN single-shape Scale baseline
        at its CURRENT geometry -- called right after a direct, absolute
        edit (Shape Properties, Batch Edit Layer) that deliberately
        redefines what "1.00" should mean going forward, e.g. the user
        just typed an exact new length. Writes the SAME per-group cache
        entry shape _apply_junction_group_scale itself would establish
        the first time this stable_id is individually Scaled, so the two
        mechanisms never disagree about this shape's own single-shape
        scale group -- a direct edit followed by a Scale of 1.00 means
        exactly the just-edited size, with position tracked alongside
        size."""
        if finger is not None:
            self._junction_scale_base[stable_id] = {
                "origin": tuple(finger.stub_end),
                "fingers": {stable_id: (tuple(finger.stub_end), tuple(finger.patch_end), finger.width_um)},
                "shapes": {},
            }
        elif shape is not None:
            _angle, end_a, end_b, _w = ji._polygon_axis_and_ends(shape.points)
            center = ((end_a[0] + end_b[0]) / 2.0, (end_a[1] + end_b[1]) / 2.0)
            self._junction_scale_base[stable_id] = {
                "origin": center,
                "fingers": {},
                "shapes": {stable_id: [tuple(pt) for pt in shape.points]},
            }

    def _scale_single_junction_member(self, stable_id, factor, push_undo: bool = True):
        """Scale ONE selected finger/patch/plate -- IMPORTED designs
        only, same reasoning as _apply_junction_group_scale's docstring:
        a parametric junction's shapes have no independent size to scale
        against (fully derived from Design Parameters every rebuild).
        Thin wrapper: a single shape is just a group of one, so this
        delegates to the SAME unified group-scale function a whole
        Layer uses -- one feature functional for all scaling needs,
        rather than duplicating it."""
        if self._display_source != "imported":
            return
        finger, shape = self._find_active_junction_shape(stable_id)
        if finger is None and shape is None:
            return
        fingers = [finger] if finger is not None else []
        shapes = [shape] if shape is not None else []
        self._apply_junction_group_scale(fingers, shapes, factor, group_key=stable_id, push_undo=push_undo)

    def _finger_polygon_stub_patch(self, f):
        """Returns (stub_end, patch_end) derived from the finger's OWN
        current polygon corners (ji._polygon_axis_and_ends), NOT from its
        separate finger.stub_end/finger.patch_end bookkeeping fields.

        Found while verifying the Scale-position fix
        against a real parametric-converted design: those two bookkeeping
        fields can silently disagree with the polygon actually on screen
        (finger.patch_end reported a point past the polygon's own real
        short edge in one reproduced case, while finger.stub_end matched
        it exactly) -- likely a from_design_parameters/JunctionLayout
        conversion quirk unrelated to the scaling work. Scaling
        must always measure the shape that's actually drawn, never a
        cached field that might quietly disagree with it -- otherwise
        the very first Scale Apply on such a finger (even at factor=1.0)
        would silently stretch it to match the stale field instead of
        leaving it exactly as drawn. theta_toward_patch_deg (confirmed
        correct/authoritative already, used everywhere else in this file)
        disambiguates which of the polygon's two short-edge midpoints is
        the patch side vs the stub side."""
        _angle, end_a, end_b, _w = ji._polygon_axis_and_ends(f.points)
        theta_rad = math.radians(f.theta_toward_patch_deg)
        ux, uy = math.cos(theta_rad), math.sin(theta_rad)
        proj_a = end_a[0] * ux + end_a[1] * uy
        proj_b = end_b[0] * ux + end_b[1] * uy
        return (end_a, end_b) if proj_a <= proj_b else (end_b, end_a)

    def _apply_junction_group_scale(self, fingers, shapes, factor, group_key, push_undo: bool = True):
        """The ONE function behind every real junction-shape Scale
        operation in Create/Import -- a single selected finger/patch/
        plate (group_key = that shape's own stable_id, a "group" of
        one) or an entire highlighted Layer (group_key = the category
        string, e.g. "patch" -- if just the patches are selected, they
        can be scaled using this same feature). IMPORTED
        designs only -- a parametric junction is fully re-derived from
        Design Parameters on every redraw, with no independent geometry
        to scale against.

        Fixes a bug where scaling did not scale the
        position of the shapes properly: the spacing between each
        patch should scale up proportionally, along with the junction
        overlap, the location of the patches, etc. -- all measurements
        should scale, so the junction appears identical to its original
        unscaled version, just bigger or smaller. The OLD code (still
        used for a single shape's own resize-in-place elsewhere) just
        called apply_finger_edit/apply_shape_edit with a new length/
        width, which deliberately keeps a finger's stub_end (or a patch/
        plate's own center) FIXED -- correct for editing ONE shape by
        itself, but wrong for a GROUP: every shape kept its own
        independent anchor, so sizes grew/shrank but nothing's POSITION
        moved relative to anything else -- the patch spacing, the
        finger-to-finger overlap, and every patch's distance from its
        finger's tip all stayed exactly as they were.

        This instead scales the WHOLE GROUP as one rigid similarity
        transform about a single shared origin: every included point
        maps as new = origin + (old - origin) * factor. Two points that
        were, say, 2 um apart before the transform are exactly
        2*factor um apart after it, NO MATTER which single origin is
        used -- so picking one shared origin for the whole group is
        both necessary and sufficient to make every spacing/overlap/
        position scale together, so the junction appears
        identical to its original unscaled version, just bigger or
        smaller. The origin itself is chosen for physical relevance,
        not because the math needs it to be any particular point:
          - Two or more fingers in the group (a whole-JJ or Fingers-
            layer scale): the real JJ crossing point of the first two
            fingers (finger_crossing_point) -- the single most
            physically meaningful point in the whole design, so it's
            the one that stays fixed in space while everything else
            grows/shrinks around it.
          - Otherwise (a single shape, or a patches/plates-only layer
            with no finger in the group): the centroid of every
            included shape's own reference point (a finger's stub_end,
            or a patch/plate's own center) -- for a single shape this
            is just that shape's own anchor, so its position never
            moves (matching the old, still-correct single-shape
            behavior); for a patches-only layer this keeps the patch
            group roughly in place while their MUTUAL spacing and size
            scale correctly around it.

        Every group's own origin + every member's own pre-scale ("1.00")
        geometry is captured ONCE, the first time that group_key is ever
        scaled, and reused for every later Scale on the same group_key --
        the same "always measure from the TRUE original, never the last-
        applied size" principle _junction_scale_base already used for
        length/width alone (see _sync_nudge_scale_panel/
        _rebase_single_shape_scale_base for the other half of this: a
        direct Shape Properties/Batch Edit Layer edit re-baselines this
        the same way it always has).

        push_undo=False lets a caller that already pushed
        its own snapshot for this whole gesture -- the Scale slider's
        live-drag handler, or _on_layer_scale_apply when it already
        pushed one for this same Apply covering scene shapes too -- skip
        pushing a second one here."""
        if self._display_source != "imported" or factor <= 0:
            return
        if not fingers and not shapes:
            return
        if push_undo:
            self._push_undo_snapshot()

        group = self._junction_scale_base.setdefault(group_key, {})
        finger_bases = group.setdefault("fingers", {})
        shape_bases = group.setdefault("shapes", {})

        if "origin" not in group:
            anchor_pts = [self._finger_polygon_stub_patch(f)[0] for f in fingers]
            for s in shapes:
                _angle, end_a, end_b, _w = ji._polygon_axis_and_ends(s.points)
                anchor_pts.append(((end_a[0] + end_b[0]) / 2.0, (end_a[1] + end_b[1]) / 2.0))
            origin = None
            if len(fingers) >= 2:
                # Picks the first two fingers' own crossing -- for the
                # classic 2-finger design this IS the (only) JJ crossing;
                # for a >2-finger series chain it's a reasonable, fixed,
                # deterministic anchor (falls back to the centroid below
                # if those two happen to be parallel/non-crossing).
                origin = ji.finger_crossing_point(fingers[0], fingers[1])
            if origin is None and anchor_pts:
                origin = (sum(p[0] for p in anchor_pts) / len(anchor_pts),
                          sum(p[1] for p in anchor_pts) / len(anchor_pts))
            group["origin"] = origin or (0.0, 0.0)

        ox, oy = group["origin"]

        def scaled_point(pt):
            return (ox + (pt[0] - ox) * factor, oy + (pt[1] - oy) * factor)

        for f in fingers:
            if not f.stable_id:
                continue
            if f.stable_id not in finger_bases:
                actual_stub, actual_patch_end = self._finger_polygon_stub_patch(f)
                finger_bases[f.stable_id] = (actual_stub, actual_patch_end, f.width_um)
            base_stub, base_patch_end, base_width = finger_bases[f.stable_id]
            new_stub = scaled_point(base_stub)
            new_patch_end = scaled_point(base_patch_end)
            new_theta = math.degrees(math.atan2(new_patch_end[1] - new_stub[1],
                                                 new_patch_end[0] - new_stub[0])) % 360.0
            new_length = math.hypot(new_patch_end[0] - new_stub[0], new_patch_end[1] - new_stub[1])
            # overlap_um=0.0 + crossing_point=new_stub makes apply_finger_edit
            # place stub_end EXACTLY at new_stub (see its own docstring: sx,
            # sy = crossing_point - axis*overlap_um) -- an absolute
            # reposition, not a relative one, using the existing, already-
            # tested rectangle-rebuild math instead of duplicating it here.
            ji.apply_finger_edit(f, length_um=new_length, width_um=base_width * factor,
                                 theta_toward_patch_deg=new_theta, overlap_um=0.0, crossing_point=new_stub)

        for s in shapes:
            if not s.stable_id:
                continue
            base_points = shape_bases.setdefault(s.stable_id, [tuple(pt) for pt in s.points])
            s.points = [scaled_point(pt) for pt in base_points]
            _angle, end_a, end_b, width = ji._polygon_axis_and_ends(s.points)
            s.length_um = math.hypot(end_b[0] - end_a[0], end_b[1] - end_a[1])
            s.width_um = width

        ji.recompute_derived_fields(self._imported_junction)
        self._create_import_force_fit = True  # a group scale can move the design's overall
                                                  # extent by a lot -- see _on_shape_finger_edit's
                                                  # matching comment for why re-fitting here is safe
        self._update_preview()

    def _on_nudge(self, dx_sign: int, dy_sign: int):
        """Unified Nudge button handler -- the single entry point wired
        to the Nudge & Scale card's four arrow buttons. Dispatches to
        whichever target _current_edit_target() resolves (a single
        custom shape, a single junction finger/patch/plate, or an entire
        highlighted Layer) using the ONE step field in that card."""
        kind, target = self._current_edit_target()
        if kind is None:
            return
        try:
            step = float(self.nudge_step_edit.text())
        except ValueError:
            step = 0.5
        dx, dy = dx_sign * step, dy_sign * step
        if kind == "marquee":
            self._on_marquee_nudge(dx, dy)
        elif kind == "scene_shape":
            self._push_undo_snapshot()
            target.cx += dx
            target.cy += dy
            self._update_preview()
        elif kind == "junction_shape":
            self._nudge_single_junction_member(target, dx, dy)
        elif kind == "layer":
            self._on_layer_nudge(dx, dy)

    def _on_scale_apply(self, factor: Optional[float] = None, push_undo: bool = True):
        """Unified Scale handler -- the single entry point wired to the
        Nudge & Scale card's Scale field/Apply button (called with no
        arguments there: reads the typed factor from self.scale_edit,
        and always pushes its own undo snapshot, exactly the original
        behavior). Dispatches to whichever target _current_edit_target()
        resolves, exactly like _on_nudge.

        Also the live-apply entry point for the Scale
        slider's own drag handler (_on_scale_slider_moved), which passes
        an explicit `factor` (the slider's own current value, not
        whatever stale text happens to be in scale_edit at that instant)
        and `push_undo=False` for every tick after the gesture's first,
        so a whole drag still pushes exactly one undo snapshot instead
        of one per motion event."""
        kind, target = self._current_edit_target()
        if kind is None:
            return
        if factor is None:
            try:
                factor = float(self.scale_edit.text())
            except ValueError:
                return
        if factor <= 0:
            return
        if kind == "marquee":
            self._on_marquee_scale_apply(factor, push_undo=push_undo)
        elif kind == "scene_shape":
            if push_undo:
                self._push_undo_snapshot()
            # Fixes a bug where apply_scale()
            # always measures against shp.base_w/h/points -- the size the
            # shape had when it was created or last DIRECTLY edited --
            # never against its current (possibly already-scaled) size.
            # Typing 0.5 then 2.00 now both measure against that same
            # original: 50% of it, then 200% of it. The old code
            # multiplied shp.w/h in place and then reset this field to
            # "1.00", which silently made the just-applied size the new
            # baseline for the NEXT apply -- so 0.5 followed by 2.00
            # landed back at 100% of the original instead of 200% of it.
            target.apply_scale(factor)
            self._update_preview()
        elif kind == "junction_shape":
            self._scale_single_junction_member(target, factor, push_undo=push_undo)
        elif kind == "layer":
            self._on_layer_scale_apply(factor, push_undo=push_undo)

    def _set_deposit_first_index(self, index: int):
        """Programmatic equivalent of clicking a Deposition Order button
        (_on_deposit_first_changed) -- used by _apply_settings_to_ui /
        _apply_params_to_ui (design-library Load, a saved recipe's
        params, etc.) so a restored design's saved deposit order is
        reflected in the buttons themselves, not just the underlying
        int.

        Generalized for the dynamic, multi-finger-group panel:
        delegates to _check_deposit_first_button_for_index, which checks
        whichever button's GROUP currently contains `index`, rather than
        indexing a fixed 2-button list positionally (self._deposit_first_
        buttons no longer exists -- see self._deposit_first_group_buttons
        and _build_deposition_order_panel's own docstring)."""
        self._check_deposit_first_button_for_index(index)
        self._on_deposit_first_changed(index)

    def _on_deposit_first_changed(self, index):
        self._deposit_first_index = index
        # Fixes a significant bug where the
        # angle tree's cached self._sim_finger_layers/_sim_patch_layers
        # were NEVER invalidated when deposit order changed -- only when
        # switching to a genuinely different design. Deposit order is a
        # real input to the recommendation (which finger is "1st
        # deposited" affects the self-shadowing check and which patch
        # angle is actually safe), so toggling it and toggling back
        # left stale values from whichever order was active when the
        # angle tree was last built, silently disagreeing with what a
        # fresh diagnostic run for the CURRENT order would actually
        # recommend. Resetting here forces a genuinely fresh
        # recommendation the next time Run Angle Diagnostic is clicked,
        # matching the same reset already used for a design switch.
        self._sim_finger_layers = {}
        self._sim_patch_layers = None
        self._sim_finger_thicknesses = {}
        self._sim_patch_thicknesses = None
        self._sim_finger_alphas = {}
        self._sim_patch_alphas = None
        self._sim_angle_diagnostic_run = False
        self._sim_has_run = False
        self._sim_stale = False  # item #105 -- no committed Run left to be stale against
        if hasattr(self, "sim_run_button"):
            self.sim_run_button.setEnabled(False)
        if hasattr(self, "sim_stale_banner"):
            self._refresh_sim_stale_banner()
        self._update_preview()

    # ------------------------------------------------------------------
    def _build_docks(self):
        """Dockable, tabbable side panels -- like the "Layers and
        Objects / Fill and Stroke / Trace Bitmap" tabs in Inkscape.
        Real Qt dock widgets: draggable, tabbable, floatable, natively --
        no extra code needed for that behavior, unlike the Tk version's
        fixed-position scrollable columns.

        Layout pattern: a section tree on top, a QStackedWidget below it
        showing only the selected section's controls -- click "Electrode
        Designer", see the electrode panel; click "Patches", see that
        panel. Keeps each section's controls out of one giant scrolling
        column (the Tk version's approach), closer to a real settings/
        properties UI."""
        params_dock = QDockWidget("Parameters", self)
        params_dock.setFeatures(QDockWidget.DockWidgetMovable | QDockWidget.DockWidgetFloatable)
        params_dock.setMinimumWidth(300)  # Fixed: the new Import/Create
                                    # cards need real width to show their labels -- the dock's
                                    # previous default width truncated "Import a Design" etc.
                                    # down to a few characters, matching Simulate Design's own
                                    # left panel sizing (280-360px) instead.
        params_scroll = QScrollArea()
        params_scroll.setWidgetResizable(True)
        params_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        params_widget = QWidget()
        params_layout = QVBoxLayout(params_widget)
        params_layout.setContentsMargins(6, 6, 6, 6)
        params_scroll.setWidget(params_widget)

        # Import and Create are two
        # fundamentally different workflows (bring in a real file vs.
        # parametrically design one from scratch) that were previously
        # mixed into the same flat accordion list, with Import as just
        # one small item among six others -- easy to miss, and not
        # visually distinguished from "creating" at all. Reorganized to
        # match Simulate Design's own card style: Import gets its own
        # prominent, clearly-labeled card up top; the remaining
        # parametric-design sections are grouped under their own
        # explicitly-labeled "Create a Design" card, so the two
        # workflows read as genuinely separate choices, not six items
        # in one list.
        import_card, import_content = self._sim_card("Import a Design (GDS / KLayout)", "#7fc8e6", collapsed=False)
        import_content.addWidget(self._build_import_panel())
        params_layout.addWidget(import_card)

        create_card, create_content = self._sim_card("Create a Design Parametrically", "#8fd694", collapsed=False)
        create_label = QLabel("Set geometry parameters below to design a junction from scratch.")
        create_label.setWordWrap(True)
        self._themed(create_label, lambda: f"color: {DIM_COLOR}; font-size: 8pt;")
        create_content.addWidget(create_label)

        params_tree = QTreeWidget()
        params_tree.setHeaderHidden(True)
        params_tree.setMaximumHeight(150)
        # The junction target overlap
        # moved under finger geometry and the "Junction Overlap" tree
        # was removed. Finger Geometry now owns
        # the target-overlap input (see _build_finger_geometry_panel), so
        # this nav list/stack no longer has a separate section for it.
        section_names = ["Electrode Designer", "Finger Geometry",
                         "Adhesion / Overlap", "Patches"]
        for section in section_names:
            QTreeWidgetItem(params_tree, [section])
        create_content.addWidget(params_tree)

        self.params_stack = QStackedWidget()
        self.params_stack.addWidget(self._build_electrode_designer_panel())
        self.params_stack.addWidget(self._build_finger_geometry_panel())
        self.params_stack.addWidget(self._build_adhesion_panel())
        self.params_stack.addWidget(self._build_patches_panel())
        create_content.addWidget(self.params_stack)

        def _on_tree_selection(current, _previous):
            if current is not None:
                self.params_stack.setCurrentIndex(params_tree.indexOfTopLevelItem(current))
        params_tree.currentItemChanged.connect(_on_tree_selection)
        params_tree.setCurrentItem(params_tree.topLevelItem(0))  # "Electrode Designer" --
                                                                    # keeps the instant-parametric-
                                                                    # design first impression intact
        params_layout.addWidget(create_card)
        params_layout.addStretch()

        params_dock.setWidget(params_scroll)
        self.addDockWidget(Qt.LeftDockWidgetArea, params_dock)
        self.splitDockWidget(self.nav_dock, params_dock, Qt.Horizontal)  # guarantees nav rail
                                                                            # stays leftmost, side
                                                                            # by side (not tabbed)

        # --- Properties dock: real X/Y/W/H/Angle fields for the
        # currently-selected shape, bidirectionally synced with clicking/
        # dragging on the canvas. RENOVATED here to match the card style
        # used everywhere else in the app since Simulate Design (_sim_card --
        # rounded, accent-colored, collapsible sections) instead of the
        # original plain stacked QLabel headers, and wrapped in a
        # QScrollArea -- fixes a bug where this dock had no
        # scroll area at all, so as sections were added over time (the
        # Imported Junction Shape section, then Nudge, then Scale) its
        # natural height kept growing with nothing to contain it. On any
        # window not tall enough for the full stack, whatever fell past
        # the bottom of the screen was simply unreachable -- this is the
        # direct cause of the Layers dock (originally stacked right
        # below Properties) becoming impossible to see.
        properties_dock = QDockWidget("Properties", self)
        properties_dock.setFeatures(QDockWidget.DockWidgetMovable | QDockWidget.DockWidgetFloatable)
        properties_dock.setMinimumWidth(300)
        properties_scroll = QScrollArea()
        properties_scroll.setWidgetResizable(True)
        properties_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        properties_widget = QWidget()
        prop_layout = QVBoxLayout(properties_widget)
        prop_layout.setContentsMargins(6, 6, 6, 6)
        prop_layout.setSpacing(10)
        properties_scroll.setWidget(properties_widget)

        # --- Shape Properties: ONE consolidated card replacing the old
        # separate "Custom Electrode Shape" and "Imported Junction Shape"
        # cards, so the parameters shown depend on the shape being
        # focused on and its classification.
        # _current_shape_role_and_object() resolves
        # (role, source, obj) fresh on every selection change:
        #   role   -- "finger" | "patch" | "plate" | "none" ("none" covers
        #             a freshly-drawn/unclassified custom shape, or one
        #             explicitly marked electrode/substrate -- no
        #             specialized fields are defined for those, just the
        #             basic geometry form)
        #   source -- "custom" (an electrode_scene.EditableShape, editable
        #             via X/Y/W/H/Angle before -- or instead of --
        #             classification) or "junction" (a real ImportedFinger/
        #             ImportedShape from whichever junction is currently
        #             active, imported OR the auto-generated parametric
        #             one -- this is what drops the old
        #             display_source == "imported" gate; see B1)
        # A hand-drawn "finger"-role custom shape gets the SAME
        # specialized finger fields a real finger does (it already
        # becomes a real ImportedFinger via from_design_parameters, with
        # genuine stub/patch/overlap semantics -- see A2/A4). A custom
        # "patch"/"plate"-role shape stays on the basic form until it's
        # actually part of a built junction, since the long/short-
        # extension/margin decomposition only exists once a patch is
        # really attached to a finger via build_side_patches -- a
        # hand-drawn patch rectangle has no such derivation yet.
        shape_card, shape_content = self._toolbar_section("Shape Properties", "#7fb8ff")
        self.shape_prop_status = QLabel("Select a shape to edit its properties.")
        self.shape_prop_status.setWordWrap(True)
        self._themed(self.shape_prop_status, lambda: f"color: {DIM_COLOR}; font-size: 8pt;")
        shape_content.addWidget(self.shape_prop_status)

        self.shape_prop_stack = QStackedWidget()
        shape_content.addWidget(self.shape_prop_stack)

        # Page 0 ("none"): basic geometry -- unchanged from the old
        # "Custom Electrode Shape" form, same attribute names
        # (prop_x/y/w/h/angle, _on_property_edit, _delete_selected_shape)
        # so nothing else that reads them needs to change.
        basic_page = QWidget()
        basic_layout = QVBoxLayout(basic_page)
        basic_layout.setContentsMargins(0, 0, 0, 0)
        basic_form = QFormLayout()
        basic_form.setSpacing(4)
        self.prop_x = QLineEdit(); self.prop_y = QLineEdit()
        self.prop_w = QLineEdit(); self.prop_h = QLineEdit()
        self.prop_angle = QLineEdit()
        for field, label in [(self.prop_x, "X:"), (self.prop_y, "Y:"), (self.prop_w, "W:"),
                             (self.prop_h, "H:"), (self.prop_angle, "Angle:")]:
            field.editingFinished.connect(self._on_property_edit)
            basic_form.addRow(label, field)
        basic_layout.addLayout(basic_form)
        basic_delete_btn = QPushButton("Delete Selected")
        basic_delete_btn.clicked.connect(self._delete_selected_shape)
        basic_layout.addWidget(basic_delete_btn)
        self.shape_prop_stack.addWidget(basic_page)  # index 0

        # Page 1 ("finger"): angle, linewidth (+ dim suggested-linewidth
        # hint), length, overlap with the other finger. Works for both a
        # custom "finger"-role shape (edits recomputed onto the shape's
        # own cx/cy/w/h/angle_deg, see _on_shape_finger_edit) and a real
        # finger (edits go straight through junction_import.apply_finger_edit,
        # same mechanism the old imported-only card used).
        finger_page = QWidget()
        finger_layout = QVBoxLayout(finger_page)
        finger_layout.setContentsMargins(0, 0, 0, 0)
        finger_form = QFormLayout()
        finger_form.setSpacing(4)
        self.shape_finger_angle = QLineEdit()
        self.shape_finger_lw_nm = QLineEdit()
        self.shape_finger_suggested_lw = QLabel("—")
        self._themed(self.shape_finger_suggested_lw, lambda: f"color: {DIM_COLOR}; font-size: 7.5pt; font-style: italic;")
        self.shape_finger_length = QLineEdit()
        self.shape_finger_overlap = QLineEdit()
        for field in (self.shape_finger_angle, self.shape_finger_lw_nm,
                      self.shape_finger_length, self.shape_finger_overlap):
            field.editingFinished.connect(self._on_shape_finger_edit)
        finger_form.addRow("Angle (°):", self.shape_finger_angle)
        lw_row = QHBoxLayout()
        lw_row.addWidget(self.shape_finger_lw_nm)
        lw_row.addWidget(self.shape_finger_suggested_lw)
        finger_form.addRow("Linewidth (nm):", lw_row)
        finger_form.addRow("Length (µm):", self.shape_finger_length)
        finger_form.addRow("Overlap w/ other finger (µm):", self.shape_finger_overlap)
        finger_layout.addLayout(finger_form)
        finger_note = QLabel("The end farthest from an electrode is always the crossing/overlap end; "
                             "the end nearest an electrode is always where patches/plates attach.")
        finger_note.setWordWrap(True)
        self._themed(finger_note, lambda: f"color: {DIM_COLOR}; font-size: 7.5pt;")
        finger_layout.addWidget(finger_note)
        # A real finger (source="junction") can now genuinely be deleted
        # and duplicated, not just a hand-drawn one -- needed for designs
        # that stack multiple Manhattan junctions on top of each other,
        # where individual fingers must be added or removed after the
        # initial layout. See _delete_selected_shape/
        # _duplicate_selected_shape's own comments. Both buttons live on
        # one row, same pattern as the patch page just below, both
        # routing through the same hotkey-configurable actions (Del/
        # Backspace, Ctrl+D/Ctrl+C) the Edit menu and keyboard shortcut
        # already use.
        finger_btn_row = QHBoxLayout()
        self.shape_finger_delete_btn = QPushButton("Delete Selected")
        self.shape_finger_delete_btn.clicked.connect(self._delete_selected_shape)
        finger_btn_row.addWidget(self.shape_finger_delete_btn)
        self.shape_finger_duplicate_btn = QPushButton("Duplicate Selected")
        self.shape_finger_duplicate_btn.clicked.connect(self._duplicate_selected_shape)
        finger_btn_row.addWidget(self.shape_finger_duplicate_btn)
        finger_layout.addLayout(finger_btn_row)
        self.shape_prop_stack.addWidget(finger_page)  # index 1

        # Page 2 ("patch"): long/short-side extension, linewidth, margin
        # before the finger's own end -- junction_import.
        # apply_patch_extension_edit/apply_patch_group_margin_edit. Works
        # for a real patch (source="junction") and a hand-drawn "patch"-
        # role shape (source="custom", resolved into its real
        # ImportedShape counterpart -- see _resolve_custom_junction_shape).
        patch_page = QWidget()
        patch_layout = QVBoxLayout(patch_page)
        patch_layout.setContentsMargins(0, 0, 0, 0)
        patch_form = QFormLayout()
        patch_form.setSpacing(4)
        self.shape_patch_long_ext = QLineEdit()
        self.shape_patch_short_ext = QLineEdit()
        self.shape_patch_lw = QLineEdit()
        self.shape_patch_margin = QLineEdit()
        for field in (self.shape_patch_long_ext, self.shape_patch_short_ext,
                      self.shape_patch_lw, self.shape_patch_margin):
            field.editingFinished.connect(self._on_shape_patch_edit)
        patch_form.addRow("Long-side extension (µm):", self.shape_patch_long_ext)
        patch_form.addRow("Short-side extension (µm):", self.shape_patch_short_ext)
        patch_form.addRow("Linewidth (µm):", self.shape_patch_lw)
        patch_form.addRow("Margin before finger's end (µm):", self.shape_patch_margin)
        patch_layout.addLayout(patch_form)
        patch_note = QLabel("Margin applies to the whole patch group sharing this finger, matching the "
                            "parametric design's single shared tip-margin field -- only editable when the "
                            "group's OUTERMOST patch is selected (disabled otherwise).")
        patch_note.setWordWrap(True)
        self._themed(patch_note, lambda: f"color: {DIM_COLOR}; font-size: 7.5pt;")
        patch_layout.addWidget(patch_note)
        # A real patch belonging to either a created or imported
        # junction (source="junction") can now genuinely be deleted and
        # duplicated, not just a hand-drawn one (source="custom") -- see
        # _delete_selected_shape/_duplicate_selected_shape's own
        # comments. Both buttons live on this one row since they're both
        # patch-only, and both route through the same hotkey-
        # configurable actions (Del / Ctrl+D) that the Edit menu and
        # keyboard shortcut already use, so a click here and the hotkey
        # always agree.
        patch_btn_row = QHBoxLayout()
        self.shape_patch_delete_btn = QPushButton("Delete Selected")
        self.shape_patch_delete_btn.clicked.connect(self._delete_selected_shape)
        patch_btn_row.addWidget(self.shape_patch_delete_btn)
        self.shape_patch_duplicate_btn = QPushButton("Duplicate Selected")
        self.shape_patch_duplicate_btn.clicked.connect(self._duplicate_selected_shape)
        patch_btn_row.addWidget(self.shape_patch_duplicate_btn)
        patch_layout.addLayout(patch_btn_row)
        self.shape_prop_stack.addWidget(patch_page)  # index 2

        # Page 3 ("plate"): length, width, and a read-only "attached to"
        # label (auto-detected by nearest patch_end -- not a manual
        # reassignment control, per the plan). Works for a real plate
        # (source="junction") and a hand-drawn "plate"-role shape
        # (source="custom", resolved the same way as patch above).
        plate_page = QWidget()
        plate_layout = QVBoxLayout(plate_page)
        plate_layout.setContentsMargins(0, 0, 0, 0)
        plate_form = QFormLayout()
        plate_form.setSpacing(4)
        self.shape_plate_length = QLineEdit()
        self.shape_plate_width = QLineEdit()
        for field in (self.shape_plate_length, self.shape_plate_width):
            field.editingFinished.connect(self._on_shape_plate_edit)
        plate_form.addRow("Length (µm):", self.shape_plate_length)
        plate_form.addRow("Width (µm):", self.shape_plate_width)
        self.shape_plate_attached_label = QLabel("—")
        self.shape_plate_attached_label.setWordWrap(True)
        self._themed(self.shape_plate_attached_label, lambda: f"color: {DIM_COLOR}; font-size: 7.5pt;")
        plate_form.addRow("Attached to:", self.shape_plate_attached_label)
        plate_layout.addLayout(plate_form)
        # A real plate (source="junction") can now genuinely be deleted
        # and duplicated too -- see the finger page's own comment just
        # above (same reasoning, same button-row pattern).
        plate_btn_row = QHBoxLayout()
        self.shape_plate_delete_btn = QPushButton("Delete Selected")
        self.shape_plate_delete_btn.clicked.connect(self._delete_selected_shape)
        plate_btn_row.addWidget(self.shape_plate_delete_btn)
        self.shape_plate_duplicate_btn = QPushButton("Duplicate Selected")
        self.shape_plate_duplicate_btn.clicked.connect(self._duplicate_selected_shape)
        plate_btn_row.addWidget(self.shape_plate_duplicate_btn)
        plate_layout.addLayout(plate_btn_row)
        self.shape_prop_stack.addWidget(plate_page)  # index 3

        # The Properties section and Layers list live together in one
        # area, with no tab switch between them: shape_card becomes
        # page 1 of self.context_edit_stack (built further down, once
        # batch_card also exists), which switches automatically between
        # this single-shape editor and the Batch Edit Layer card below,
        # per _sync_context_edit_stack.

        # --- Nudge + Scale: "batch edit layer" and "nudge/scale the
        # selected shape" share one card and one pair of controls. What
        # it acts on is resolved fresh on every click by
        # _current_edit_target(): a single selected shape -- a custom
        # electrode shape OR a clicked junction finger/patch/plate --
        # takes priority; with nothing individually selected, it falls
        # back to whichever Layer is highlighted in the Layers tree and
        # acts on every shape in it at once. self.nudge_scale_status
        # (kept in sync by _sync_nudge_scale_panel, called at the end of
        # every _update_preview) always says which of those it's about
        # to do.
        adjust_card, adjust_content = self._toolbar_section("Nudge && Scale", "#8fd694")
        self.nudge_scale_status = QLabel("Select a shape (click it), or a Layer in the Layers tree "
                                          "above, to Nudge/Scale it.")
        self.nudge_scale_status.setWordWrap(True)
        self._themed(self.nudge_scale_status, lambda: f"color: {DIM_COLOR}; font-size: 7.5pt;")
        adjust_content.addWidget(self.nudge_scale_status)
        nudge_step_row = QHBoxLayout()
        nudge_step_row.addWidget(QLabel("Step (\u00b5m):"))
        self.nudge_step_edit = QLineEdit("0.5")
        self.nudge_step_edit.setFixedWidth(60)
        nudge_step_row.addWidget(self.nudge_step_edit)
        nudge_step_row.addStretch()
        adjust_content.addLayout(nudge_step_row)
        nudge_grid = QGridLayout()
        nudge_grid.setSpacing(2)
        nudge_up_btn = QPushButton("\u2191")
        nudge_up_btn.clicked.connect(lambda: self._on_nudge(0, 1))
        nudge_left_btn = QPushButton("\u2190")
        nudge_left_btn.clicked.connect(lambda: self._on_nudge(-1, 0))
        nudge_right_btn = QPushButton("\u2192")
        nudge_right_btn.clicked.connect(lambda: self._on_nudge(1, 0))
        nudge_down_btn = QPushButton("\u2193")
        nudge_down_btn.clicked.connect(lambda: self._on_nudge(0, -1))
        for _btn in (nudge_up_btn, nudge_left_btn, nudge_right_btn, nudge_down_btn):
            _btn.setFixedWidth(36)
        nudge_grid.addWidget(nudge_up_btn, 0, 1)
        nudge_grid.addWidget(nudge_left_btn, 1, 0)
        nudge_grid.addWidget(nudge_right_btn, 1, 2)
        nudge_grid.addWidget(nudge_down_btn, 2, 1)
        nudge_grid_wrap = QHBoxLayout()
        nudge_grid_wrap.addLayout(nudge_grid)
        nudge_grid_wrap.addStretch()
        adjust_content.addLayout(nudge_grid_wrap)

        scale_note = QLabel("1.00 = original size. A single shape keeps its own place; a whole "
                            "Layer scales together (spacing, overlap, and position included).")
        scale_note.setWordWrap(True)
        self._themed(scale_note, lambda: f"color: {DIM_COLOR}; font-size: 7.5pt; padding-top: 4px;")
        adjust_content.addWidget(scale_note)
        scale_row = QHBoxLayout()
        scale_row.addWidget(QLabel("Scale:"))
        self.scale_edit = QLineEdit("1.00")
        self.scale_edit.editingFinished.connect(self._on_scale_apply)
        scale_row.addWidget(self.scale_edit)
        scale_apply_btn = QPushButton("Apply")
        scale_apply_btn.clicked.connect(self._on_scale_apply)
        scale_row.addWidget(scale_apply_btn)
        adjust_content.addLayout(scale_row)

        # A scale bar lets the user set the scale either by typing an
        # exact value or by dragging across a 0.1x-10x range, with
        # 1.00x at the middle of the bar. A LOG-scaled slider (not
        # linear) is what actually puts 1.00x in the middle of a
        # 0.1x-10x range: log10(0.1)=-1, log10(10)=+1, log10(1.00)=0 --
        # a plain linear 0.1-10 slider would instead crush the whole
        # useful "roughly life-size" 0.5x-2x range into the leftmost
        # ~15% of the bar. Every tick both updates the readout and
        # live-applies the Scale to the real geometry (see
        # _on_scale_slider_moved's own docstring for the one-undo-per-
        # gesture bookkeeping), so the measurements and visuals of the
        # selected junction or layer update live as the slider moves.
        scale_slider_row = QHBoxLayout()
        self.scale_slider = QSlider(Qt.Horizontal)
        self.scale_slider.setMinimum(-1000)
        self.scale_slider.setMaximum(1000)
        self.scale_slider.setValue(0)  # 1.00x, dead center
        self.scale_slider.setFixedHeight(18)
        self.scale_slider.setToolTip("Drag to Scale, 0.1x to 10x -- 1.00x (original size) is the middle. "
                                       "Updates live as you drag.")
        self.scale_slider.valueChanged.connect(self._on_scale_slider_moved)
        self.scale_slider.sliderReleased.connect(self._on_scale_slider_released)
        scale_slider_row.addWidget(self.scale_slider)
        adjust_content.addLayout(scale_slider_row)
        scale_slider_labels_row = QHBoxLayout()
        scale_slider_labels_row.setContentsMargins(0, 0, 0, 0)
        scale_slider_labels_row.setSpacing(0)
        scale_lbl_min = QLabel("0.1x")
        scale_lbl_mid = QLabel("1.00x")
        scale_lbl_max = QLabel("10x")
        for _lbl in (scale_lbl_min, scale_lbl_mid, scale_lbl_max):
            self._themed(_lbl, lambda: f"color: {DIM_COLOR}; font-size: 6.5pt;")
        scale_slider_labels_row.addWidget(scale_lbl_min)
        scale_slider_labels_row.addStretch()
        scale_slider_labels_row.addWidget(scale_lbl_mid)
        scale_slider_labels_row.addStretch()
        scale_slider_labels_row.addWidget(scale_lbl_max)
        adjust_content.addLayout(scale_slider_labels_row)
        # adjust_card (Nudge && Scale) is added to prop_layout further
        # down, in its final position below the Layers tree and
        # context-sensitive editor, once those also exist -- see the
        # Layers/Batch-Edit section below, which finishes building
        # prop_layout's contents in top-to-bottom visual order.

        properties_dock.setWidget(properties_scroll)
        self.addDockWidget(Qt.RightDockWidgetArea, properties_dock)

        # --- Layers tree + context-sensitive editor. Clicking a layer
        # highlights everything in it (and fades the rest) on Create/
        # Import's own canvas -- see _update_create_import_preview /
        # _redraw_create_import_overlay, which pass layer_highlight/
        # selected_stable_id/shape_class_fn through to the shared
        # drawing function. With a layer selected, Batch Edit below can
        # also Nudge or Scale every shape currently classified into that
        # layer at once.
        #
        # The Layers tree is built straight into properties_dock:
        # tree_card (this Layers tree) goes at the very top of
        # prop_layout (added below, right after it's built), and
        # batch_card (Batch Edit Layer, built further down) becomes one
        # page of self.context_edit_stack, which switches automatically
        # between it and the single-shape shape_card built above, per
        # _sync_context_edit_stack -- so selecting a layer or a shape
        # brings up the right editor right there, with no tab and no
        # separate dock.
        tree_card, tree_content = self._toolbar_section("Layers", "#e0c46c")
        tree_note = QLabel("Click a layer to highlight everything in it and fade the rest.")
        tree_note.setWordWrap(True)
        self._themed(tree_note, lambda: f"color: {DIM_COLOR}; font-size: 7.5pt;")
        tree_content.addWidget(tree_note)
        self.layers_tree = QTreeWidget()
        self.layers_tree.setHeaderHidden(True)
        self.layers_tree.setMaximumHeight(115)  # Trimmed from 150 -- only ever shows 5 rows
                                                 # (Electrode, Physical JJ, and its 3 children)
                                                 # fully expanded, so the extra headroom was
                                                 # just unused vertical space.
        electrode_item = QTreeWidgetItem(self.layers_tree, ["Electrode"])
        electrode_item.setData(0, Qt.UserRole, "electrode")
        jj_item = QTreeWidgetItem(self.layers_tree, ["Physical JJ"])
        jj_item.setData(0, Qt.UserRole, "__jj_all__")  # parent -- highlights all JJ classes
                                                          # together (finger+patch+plate), fading
                                                          # only the electrode -- distinct from
                                                          # None, which means "no highlight"
        finger_item = QTreeWidgetItem(jj_item, ["Junction Fingers"])
        finger_item.setData(0, Qt.UserRole, "finger")
        patch_item = QTreeWidgetItem(jj_item, ["Patches"])
        patch_item.setData(0, Qt.UserRole, "patch")
        plate_item = QTreeWidgetItem(jj_item, ["Adhesion Plates"])
        plate_item.setData(0, Qt.UserRole, "plate")
        self.layers_tree.expandAll()
        self.layers_tree.currentItemChanged.connect(self._on_layer_select)
        tree_content.addWidget(self.layers_tree)
        clear_highlight_btn = QPushButton("Clear Highlight")
        clear_highlight_btn.clicked.connect(lambda: self._set_layer_highlight(None))
        tree_content.addWidget(clear_highlight_btn)
        # tree_card becomes the first section of the single merged
        # "Toolbar" card, built once everything else below also exists
        # (see the final assembly, right after context_edit_stack).

        # --- Batch Edit Layer: when a specific feature layer is
        # selected on the "Layers" card, the measurements that can
        # change appear and the user can mass-set the dimensions of
        # every shape in that layer to the same values. Patches in
        # particular may show slightly different decimal values for
        # length or linewidth when batch-selected, since small
        # variations accumulate across many shapes; typing an exact
        # value here overwrites all of them at once. This is
        # deliberately an ABSOLUTE set (every shape in the layer becomes
        # EXACTLY this value), not the relative Scale factor above -- the
        # two are complementary, not duplicates: Scale multiplies each
        # shape's own size by the same factor (preserving relative
        # differences), this OVERWRITES every shape to the identical
        # value (eliminating them). It reuses the exact same field sets as
        # the single-shape "Shape Properties" card above (finger: Angle/
        # Linewidth/Length/Overlap; patch: Long/Short-side extension/
        # Linewidth/Margin; plate: Length/Width) -- the same underlying
        # write-back functions, just applied to every shape currently
        # classified into the highlighted layer instead of one. A field
        # left blank leaves that parameter alone on every shape (same
        # blank-means-unchanged convention the single-shape editors already
        # use), so a partial batch edit (e.g. only Linewidth) is safe.
        batch_card, batch_content = self._toolbar_section("Batch Edit Layer", "#e08a5c")
        self.batch_edit_status = QLabel("Select a layer above to batch-edit its shapes.")
        self.batch_edit_status.setWordWrap(True)
        self._themed(self.batch_edit_status, lambda: f"color: {DIM_COLOR}; font-size: 7.5pt;")
        batch_content.addWidget(self.batch_edit_status)

        self.batch_edit_stack = QStackedWidget()
        batch_content.addWidget(self.batch_edit_stack)

        # Page 0: nothing batch-editable (no layer selected, an empty
        # layer, or Electrode/"Physical JJ" -- a mix of roles with no one
        # shared field set to batch-edit).
        batch_none_page = QWidget()
        batch_none_layout = QVBoxLayout(batch_none_page)
        batch_none_layout.setContentsMargins(0, 0, 0, 0)
        batch_none_note = QLabel("Select a single feature layer (Junction Fingers / Patches / "
                                 "Adhesion Plates) above to batch-edit its shared parameters.")
        batch_none_note.setWordWrap(True)
        self._themed(batch_none_note, lambda: f"color: {DIM_COLOR}; font-size: 7.5pt;")
        batch_none_layout.addWidget(batch_none_note)
        self.batch_edit_stack.addWidget(batch_none_page)  # index 0

        # Page 1 ("finger"): same 4 fields as the single-finger page.
        batch_finger_page = QWidget()
        batch_finger_layout = QVBoxLayout(batch_finger_page)
        batch_finger_layout.setContentsMargins(0, 0, 0, 0)
        batch_finger_form = QFormLayout()
        batch_finger_form.setSpacing(4)
        # Angle is intentionally excluded from batch edit: batch-editing
        # the junction fingers' angle to a single shared value caused
        # both fingers to become parallel to each other, which is never
        # a valid design state. Unlike Linewidth/Length/Overlap -- which
        # legitimately CAN be
        # standardized to one shared value across every finger in the
        # layer -- Angle can't: two junction fingers are supposed to run
        # at two DIFFERENT angles (roughly perpendicular), so setting
        # them all to the SAME batch value is never a valid design move,
        # only ever a way to accidentally collapse the whole junction.
        # Removed entirely (not just disabled) -- Angle stays editable
        # only on the single-shape Shape Properties card, one finger at
        # a time, where "what angle should THIS finger be" is actually a
        # meaningful question.
        self.batch_finger_lw_nm = QLineEdit()
        self.batch_finger_length = QLineEdit()
        self.batch_finger_overlap = QLineEdit()
        for field in (self.batch_finger_lw_nm, self.batch_finger_length, self.batch_finger_overlap):
            field.setPlaceholderText("(leave blank = unchanged)")
        batch_finger_form.addRow("Linewidth (nm):", self.batch_finger_lw_nm)
        batch_finger_form.addRow("Length (µm):", self.batch_finger_length)
        batch_finger_form.addRow("Overlap w/ other finger (µm):", self.batch_finger_overlap)
        batch_finger_layout.addLayout(batch_finger_form)
        batch_finger_note = QLabel("Angle isn't batch-editable here -- fingers are supposed to run at "
                                   "different angles, so one shared value would collapse them together. "
                                   "Edit a finger's angle individually on its own Shape Properties card.")
        batch_finger_note.setWordWrap(True)
        self._themed(batch_finger_note, lambda: f"color: {DIM_COLOR}; font-size: 7.5pt;")
        batch_finger_layout.addWidget(batch_finger_note)
        self.batch_edit_stack.addWidget(batch_finger_page)  # index 1

        # Page 2 ("patch"): same 4 fields as the single-patch page.
        batch_patch_page = QWidget()
        batch_patch_layout = QVBoxLayout(batch_patch_page)
        batch_patch_layout.setContentsMargins(0, 0, 0, 0)
        # Read-only aggregate measurements -- only meaningful with the
        # whole layer selected at once (edge-to-edge spacing between
        # patches, and whether every patch's own axis angle agrees) --
        # see _patch_layer_aggregate_text.
        self.batch_patch_aggregate_label = QLabel("")
        self.batch_patch_aggregate_label.setWordWrap(True)
        self._themed(self.batch_patch_aggregate_label, lambda: f"color: {TEXT_COLOR}; font-size: 7.5pt;")
        batch_patch_layout.addWidget(self.batch_patch_aggregate_label)
        batch_patch_form = QFormLayout()
        batch_patch_form.setSpacing(4)
        self.batch_patch_long_ext = QLineEdit()
        self.batch_patch_short_ext = QLineEdit()
        self.batch_patch_lw = QLineEdit()
        self.batch_patch_margin = QLineEdit()
        for field in (self.batch_patch_long_ext, self.batch_patch_short_ext,
                      self.batch_patch_lw, self.batch_patch_margin):
            field.setPlaceholderText("(leave blank = unchanged)")
        batch_patch_form.addRow("Long-side extension (µm):", self.batch_patch_long_ext)
        batch_patch_form.addRow("Short-side extension (µm):", self.batch_patch_short_ext)
        batch_patch_form.addRow("Linewidth (µm):", self.batch_patch_lw)
        batch_patch_form.addRow("Margin before finger's end (µm):", self.batch_patch_margin)
        batch_patch_layout.addLayout(batch_patch_form)
        batch_patch_note = QLabel("Margin is applied once per finger's own patch group (not per "
                                  "patch), matching the single-shape editor's own convention.")
        batch_patch_note.setWordWrap(True)
        self._themed(batch_patch_note, lambda: f"color: {DIM_COLOR}; font-size: 7.5pt;")
        batch_patch_layout.addWidget(batch_patch_note)
        self.batch_edit_stack.addWidget(batch_patch_page)  # index 2

        # Page 3 ("plate"): same 2 fields as the single-plate page.
        batch_plate_page = QWidget()
        batch_plate_layout = QVBoxLayout(batch_plate_page)
        batch_plate_layout.setContentsMargins(0, 0, 0, 0)
        batch_plate_form = QFormLayout()
        batch_plate_form.setSpacing(4)
        self.batch_plate_length = QLineEdit()
        self.batch_plate_width = QLineEdit()
        for field in (self.batch_plate_length, self.batch_plate_width):
            field.setPlaceholderText("(leave blank = unchanged)")
        batch_plate_form.addRow("Length (µm):", self.batch_plate_length)
        batch_plate_form.addRow("Width (µm):", self.batch_plate_width)
        batch_plate_layout.addLayout(batch_plate_form)
        self.batch_edit_stack.addWidget(batch_plate_page)  # index 3

        self.batch_edit_apply_btn = QPushButton("Apply to All in Layer")
        self.batch_edit_apply_btn.clicked.connect(self._on_batch_layer_edit_apply)
        batch_content.addWidget(self.batch_edit_apply_btn)

        # --- The context-sensitive editor. This QStackedWidget selects
        # a single shape and brings up the toolbar to edit that shape;
        # selecting a layer instead automatically switches it to batch
        # edit layer properties. It sits right below the Layers tree
        # (added above) and switches pages via _sync_context_edit_stack, called
        # every _update_preview alongside _sync_property_fields/
        # _sync_shape_properties_panel/_update_layer_batch_status, using
        # the exact same priority order _current_edit_target() already
        # establishes elsewhere: a single selected shape (custom or a
        # real junction finger/patch/plate) wins over a highlighted
        # Layer, which wins over showing nothing. shape_card and
        # batch_card are the SAME card widgets built above/here (nothing
        # about either one's fields, buttons, or sync functions changes)
        # -- only which one is visible at a time changes, and that's now
        # automatic instead of a manual "Layers" | "Properties" tab
        # click.
        self.context_edit_stack = QStackedWidget()
        context_none_page = QWidget()
        context_none_layout = QVBoxLayout(context_none_page)
        context_none_layout.setContentsMargins(0, 0, 0, 0)
        context_none_note = QLabel("Select a layer above, or click a shape on the canvas, "
                                    "to edit it here.")
        context_none_note.setWordWrap(True)
        self._themed(context_none_note, lambda: f"color: {DIM_COLOR}; font-size: 8pt;")
        context_none_layout.addWidget(context_none_note)
        context_none_layout.addStretch()
        self.context_edit_stack.addWidget(context_none_page)  # index 0: nothing selected
        self.context_edit_stack.addWidget(shape_card)          # index 1: single shape selected
        self.context_edit_stack.addWidget(batch_card)          # index 2: a Layer is highlighted

        # --- The four sections above (Layers, Shape Properties, Batch
        # Edit Layer, Nudge && Scale) do not sit in their own separate
        # _sim_card each: that would be 3-4 complete extra card
        # borders/gradients/title-bars' worth of padding stacked
        # vertically, forcing extra scrolling to see the whole toolbar.
        # They are instead sections (built via _toolbar_section, a much
        # thinner header with no border/collapse-chevron/dot) inside ONE
        # shared card, separated by thin _toolbar_separator() rules
        # instead of a second full card's worth of chrome -- a more
        # compact, purely-functional layout.
        toolbar_card, toolbar_content = self._sim_card("Toolbar", "#9aa8cf", collapsed=False)
        toolbar_content.addWidget(tree_card)
        toolbar_content.addWidget(self._toolbar_separator())
        toolbar_content.addWidget(self.context_edit_stack)
        toolbar_content.addWidget(self._toolbar_separator())
        toolbar_content.addWidget(adjust_card)  # Nudge && Scale -- always visible, below the
                                                 # context-sensitive editor (see its own comment
                                                 # above: it already self-adjusts to whichever of
                                                 # the two targets above is active)
        prop_layout.addWidget(toolbar_card)
        prop_layout.addStretch()

        # Stored so they can be hidden when a tab that doesn't use them is
        # active -- these docks hold Create/Import-specific shape-editing
        # content, shown only while that tab is active. The Layers tree
        # lives inside properties_dock rather than as its own dock.
        self.shared_geometry_docks = [params_dock, properties_dock]

        create_import_dock = QDockWidget("Measurements", self)
        create_import_dock.setFeatures(QDockWidget.DockWidgetMovable | QDockWidget.DockWidgetFloatable)
        create_import_widget = QWidget()
        create_import_layout = QVBoxLayout(create_import_widget)
        create_import_layout.setContentsMargins(4, 4, 4, 4)
        self.create_import_measurements_tree = QTreeWidget()
        self.create_import_measurements_tree.setHeaderLabels(["Measurement", "Value"])
        self.create_import_measurements_tree.setColumnWidth(0, 260)
        # NOT setAlternatingRowColors -- deliberately avoided here: the
        # global QSS sets QTreeWidget's background but not an
        # alternate-row color, so Qt falls back to its default palette's
        # AlternateBase (a light color), producing stark white bands
        # against this dark theme. Simplest safe fix is to just not
        # enable it, rather than touch the shared global QSS.
        create_import_layout.addWidget(self.create_import_measurements_tree)
        export_measurements_btn = QPushButton("Export Detailed Measurement Diagnostic (.txt)")
        export_measurements_btn.setToolTip("Save all measurements (including ones not shown in the tree) to a text file.")
        export_measurements_btn.clicked.connect(self._on_export_measurements_txt)
        create_import_layout.addWidget(export_measurements_btn)
        create_import_dock.setWidget(create_import_widget)
        self.addDockWidget(Qt.BottomDockWidgetArea, create_import_dock)
        self.create_import_bottom_dock = create_import_dock
        self.resizeDocks([create_import_dock], [220], Qt.Vertical)  # collapsed/compact by default --
                                                                  # the canvas gets priority for space;
                                                                  # every finger/patch group still
                                                                  # starts collapsed too (see the
                                                                  # populate function), so even 220px
                                                                  # shows the full top-level outline

    def _make_app_qicon(self) -> QIcon:
        """Rasterizes the same comb-cross app icon the Front Page uses
        (_build_appicon_svg) into a QIcon for the window/taskbar --
        multiple sizes baked in up front so it stays crisp at whatever
        size the OS actually displays it at."""
        icon = QIcon()
        renderer = QSvgRenderer(QByteArray(_build_appicon_svg()))
        for size in (16, 32, 48, 64, 128, 256):
            pixmap = QPixmap(size, size)
            pixmap.fill(Qt.transparent)
            painter = QPainter(pixmap)
            painter.setRenderHint(QPainter.Antialiasing)
            renderer.render(painter, QRectF(0, 0, size, size))
            painter.end()
            icon.addPixmap(pixmap)
        return icon

    def _build_front_page_tab(self) -> QWidget:
        """The Front Page: nav_list row 0 / main_stack index 0, and the
        page shown at startup (see nav_list.setCurrentRow(0) in
        _build_navigation_rail and _on_nav_changed(0) at the end of
        __init__, both of which point at row/index 0).

        Hero: a full-bleed, theme-aware circuit-trace backdrop
        (_build_circuit_backdrop_svg) that IS the app icon/name/tagline/
        credit's own parent widget (paints its SVG in paintEvent, then
        Qt paints those normal child widgets on top -- no separate
        layered/composited sibling, which a StackAll QStackedLayout
        version of this turned out not to composite correctly under
        this app's headless test backend). Not a static image, so it
        repaints correctly on every light/dark toggle
        (_FrontPageBackdrop.retheme(), called from _apply_theme()
        alongside every other themed surface).

        Below that: one short paragraph on the app's overall purpose,
        then a card per real tab -- title + description read straight
        from self._tab_definitions (so this can never drift out of sync
        with the actual tab list), each one a direct shortcut
        (nav_list.setCurrentRow) AND the Get Started guide's own text at
        the same time, rather than maintaining two separate lists."""
        outer = QWidget()
        outer_layout = QVBoxLayout(outer)
        outer_layout.setContentsMargins(0, 0, 0, 0)
        outer_layout.setSpacing(0)

        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setFrameShape(QFrame.NoFrame)
        self._themed(scroll, lambda: f"QScrollArea {{ background-color: {BG_COLOR}; border: none; }}")
        content = QWidget()
        self._themed(content, lambda: f"background-color: {BG_COLOR};")
        content_layout = QVBoxLayout(content)
        content_layout.setContentsMargins(0, 0, 0, 28)
        content_layout.setSpacing(0)

        # --- Hero: circuit backdrop with icon/name/tagline/credit as
        # DIRECT CHILDREN of the same widget (not a separate sibling
        # layered via QStackedLayout -- an earlier version tried that
        # and the offscreen/headless Qt backend used for this app's own
        # tests silently failed to composite the two overlapping
        # widgets, so nothing but the backdrop ever painted; a widget
        # painting its own background in paintEvent and then letting Qt
        # paint its normal children on top, as below, is the standard
        # mechanism and doesn't depend on any compositing step at all).
        hero = _FrontPageBackdrop(_build_circuit_backdrop_svg)
        hero.setMinimumHeight(300)
        hero_layout = QVBoxLayout(hero)
        hero_layout.setContentsMargins(24, 34, 24, 28)
        hero_layout.setSpacing(6)
        hero_layout.addStretch(1)

        # The app-mark logo is the hero's sole centerpiece, centered and
        # alone -- deliberately uncluttered (see QuantumAppIcon's own
        # sheen animation above).
        icon_widget = QuantumAppIcon()
        icon_widget.setFixedSize(132, 132)
        hero_layout.addWidget(icon_widget, alignment=Qt.AlignHCenter)

        name_label = QLabel("Plassys Shadow Simulator")
        self._themed(name_label, lambda: (
            f"background: transparent; color: {TEXT_COLOR}; font-weight: bold; font-size: 22pt;"
        ))
        name_label.setAlignment(Qt.AlignCenter)
        hero_layout.addWidget(name_label)

        tagline = QLabel("Simulate the shadow. Generate the recipe. Measure what actually formed.")
        self._themed(tagline, lambda: (
            f"background: transparent; color: {DIM_COLOR}; font-size: 10pt; font-style: italic;"
        ))
        tagline.setAlignment(Qt.AlignCenter)
        hero_layout.addWidget(tagline)

        credit = QLabel("By Alexander Braiman — SQMS Center, Fermilab")
        self._themed(credit, lambda: (
            f"background: transparent; color: {ACCENT_COLOR}; font-size: 9pt; padding-top: 6px;"
        ))
        credit.setAlignment(Qt.AlignCenter)
        hero_layout.addWidget(credit)

        acknowledgment = QLabel(
            "With design and shadow-evaporation guidance from Francesco Crisa, "
            "and support from Akshay Murthy"
        )
        acknowledgment.setWordWrap(True)
        self._themed(acknowledgment, lambda: (
            f"background: transparent; color: {DIM_COLOR}; font-size: 8pt; padding-top: 2px;"
        ))
        acknowledgment.setAlignment(Qt.AlignCenter)
        hero_layout.addWidget(acknowledgment)

        hero_layout.addStretch(1)
        content_layout.addWidget(hero)

        # --- Purpose blurb + "Get Started" shortcut cards ---
        body = QWidget()
        self._themed(body, lambda: f"background-color: {BG_COLOR};")
        body_layout = QVBoxLayout(body)
        body_layout.setContentsMargins(28, 22, 28, 0)
        body_layout.setSpacing(14)

        purpose = QLabel(
            "Design a junction, simulate shadow evaporation, generate a recipe, then measure and "
            "linearize the resulting resistance -- one pipeline, start to finish."
        )
        purpose.setWordWrap(True)
        self._themed(purpose, lambda: f"color: {TEXT_COLOR}; font-size: 10pt;")
        body_layout.addWidget(purpose)

        section_label = QLabel("GET STARTED  —  JUMP TO A SECTION")
        self._themed(section_label, lambda: (
            f"color: {DIM_COLOR}; font-size: 8.5pt; font-weight: bold; letter-spacing: 1px; "
            f"padding-top: 8px;"
        ))
        body_layout.addWidget(section_label)

        # One icon per real tab, purely decorative (matched by title so
        # this can never fall out of sync with self._tab_definitions
        # itself) -- a sensible glyph per section, not a generic bullet.
        _card_icons = {
            "Create / Import": "fa5s.file-import",
            "Simulate Design": "fa5s.layer-group",
            "Recipe": "fa5s.flask",
            "Deposition Slideshow": "fa5s.images",
            "Measure Resistance": "fa5s.bolt",
            "Interpret Results": "fa5s.chart-line",
        }

        cards_grid = QGridLayout()
        cards_grid.setSpacing(14)
        real_defs = self._tab_definitions[1:]  # everything except this Front Page (row 0)
        cols = 2
        for i, (title, desc) in enumerate(real_defs):
            row_target = i + 1  # nav_list row -- Front Page occupies row 0
            card = QuantumCard(_card_icons.get(title, "fa5s.arrow-circle-right"), title, desc)
            card.clicked.connect(lambda checked=False, r=row_target: self.nav_list.setCurrentRow(r))
            cards_grid.addWidget(card, i // cols, i % cols)
        for c in range(cols):
            cards_grid.setColumnStretch(c, 1)
        body_layout.addLayout(cards_grid)

        # --- Design Library shortcut card: a catalog of locally-saved
        # designs (Created and Imported alike), reachable directly from
        # the main screen rather than only via File > Open Design
        # Library. Styled identically to the per-tab cards above
        # (frontPageCard QSS) so it reads as part of the same row of
        # shortcuts, not a bolted-on afterthought.
        library_section_label = QLabel("YOUR SAVED DESIGNS")
        self._themed(library_section_label, lambda: (
            f"color: {DIM_COLOR}; font-size: 8.5pt; font-weight: bold; letter-spacing: 1px; "
            f"padding-top: 10px;"
        ))
        body_layout.addWidget(library_section_label)

        library_card = QuantumCard(
            "fa5s.book", "Design Library", "Save the current design, or load one saved earlier."
        )
        library_card.clicked.connect(self._open_design_library)
        body_layout.addWidget(library_card)

        content_layout.addWidget(body)
        scroll.setWidget(content)
        outer_layout.addWidget(scroll)
        return outer

    def _build_main_tabs(self):
        """The actual page container -- a QStackedWidget with NO visible
        tab bar of its own (a native tab bar would sit below the
        Design/Import toolbar and visibly shift position whenever that
        toolbar hides/shows while switching tabs). All switching happens
        through the fixed left-side navigation rail instead
        (_build_navigation_rail), which never moves.

        The prev/next arrows are hosted as ONE shared back/forward pair
        in the status bar (see _build_status_bar), rather than wrapped
        around each individual page's own widget: a QStatusBar always
        spans the full window width at the true bottom edge regardless
        of which side docks are visible, so the arrows sit in the exact
        same spot on every tab -- including Create / Import, where the
        Contents/Parameters/Properties/Layers docks eat into the central
        widget's width."""
        self.main_stack = QStackedWidget()
        self.main_stack.addWidget(self._build_front_page_tab())
        # Resist Stack & Calculator and Chamber Reference Model live
        # under Settings; project name/metal/electrode metal/oxidation
        # time live on the Recipe tab's Recipe Parameters panel (see
        # _build_recipe_parameters_panel), and deposition tilt is
        # Simulate Design's own Active alpha field
        # (sim_alpha_override_edit). The shape-editing canvas, docks, and
        # toolbar live entirely under the Create / Import tab below.
        self.main_stack.addWidget(self._build_create_import_tab())
        self.main_stack.addWidget(self._build_simulate_tab())
        self.main_stack.addWidget(self._build_recipe_tab())
        self.main_stack.addWidget(self._build_slideshow_tab())
        self.main_stack.addWidget(self._build_measurement_tab())
        self.main_stack.addWidget(self._build_interpretation_tab())
        # Settings -- a hidden page, deliberately NOT added to
        # self._tab_definitions / self.nav_list below, so it has no row
        # in the Contents panel and no prev/next arrows (see
        # _on_nav_changed hiding the status-bar nav widget for any index
        # outside the real tabs) -- the ONLY way in is the gear menu
        # (_show_settings_tab / _show_chamber_reference_tab), and the
        # only way out is picking any real section from the Contents
        # panel (see _show_chamber_reference_tab's docstring). Chamber
        # Reference Model is one section inside this page -- see
        # _build_settings_tab.
        self._settings_tab_index = self.main_stack.count()
        self.main_stack.addWidget(self._build_settings_tab())
        self.setCentralWidget(self.main_stack)

    def _build_settings_tab(self) -> QWidget:
        """The Settings page: a hidden, non-nav page with its own
        internal section list + stacked pages -- mirrors the app's main
        nav_list/main_stack pattern at a smaller scale. This is where
        configuration that many OTHER tabs read from lives (resist
        stack, the alpha/linewidth calculator, and eventually process
        parameters/ion-mill angle) -- set up once and rarely revisited,
        unlike the sequential Create -> Simulate -> Recipe -> Slideshow
        tabs, so it doesn't belong in that pipeline or consume a
        nav-rail slot."""
        outer = QWidget()
        layout = QVBoxLayout(outer)
        layout.setContentsMargins(16, 12, 16, 16)
        layout.setSpacing(6)

        header = QLabel("Settings")
        self._themed(header, lambda: f"color: {TEXT_COLOR}; font-weight: bold; font-size: 14pt;")
        layout.addWidget(header)

        splitter = QSplitter(Qt.Horizontal)
        layout.addWidget(splitter, stretch=1)

        self.settings_nav_list = QListWidget()
        self.settings_nav_list.setMaximumWidth(230)
        self.settings_nav_list.setMinimumWidth(170)
        self.settings_stack = QStackedWidget()

        # Settings > Process Parameters was removed -- its live fields
        # moved to the Recipe tab's Recipe Parameters panel (metal/
        # electrode metal/project name/oxidation time) and Simulate
        # Design's own Active alpha field (deposition tilt); the rest
        # are now pure hardcoded DesignParameters defaults with no UI at
        # all. See _current_params/_apply_settings_to_ui for where
        # everything ended up.
        settings_sections = [
            ("Resist Stack & Calculator", self._build_settings_resist_stack_section()),
            ("Chamber Reference Model", self._build_chamber_reference_tab()),
            ("Hotkeys", self._build_settings_hotkeys_section()),
        ]
        # Settings' "Deposition Order" section (a read-only summary +
        # jump link, added in an earlier pass) was removed as
        # unnecessary here. The real control stays exactly where it
        # already was: Simulate Design's
        # own Deposition Order card (now merged into that tab's single
        # "Process Parameters" card alongside Resist Stack & Electrode --
        # see _build_simulate_tab).
        for title, widget in settings_sections:
            self.settings_nav_list.addItem(QListWidgetItem(title))
            self.settings_stack.addWidget(widget)
        self.settings_nav_list.currentRowChanged.connect(self.settings_stack.setCurrentIndex)
        self.settings_nav_list.setCurrentRow(0)

        splitter.addWidget(self.settings_nav_list)
        splitter.addWidget(self.settings_stack)
        splitter.setStretchFactor(0, 0)
        splitter.setStretchFactor(1, 1)

        return outer

    def _show_settings_tab(self, section_title: str = None):
        """Gear menu > Settings entry point. Same hidden-page navigation
        _show_chamber_reference_tab already established (nav_list
        deselected without firing a nav change, Contents force-reopened
        as the only way back out) -- optionally also selects a specific
        section row (e.g. "Chamber Reference Model", so
        _show_chamber_reference_tab can reuse this instead of duplicating
        the navigation)."""
        self.nav_list.blockSignals(True)
        self.nav_list.setCurrentRow(-1)
        self.nav_list.blockSignals(False)
        self.nav_dock.setVisible(True)
        self._on_nav_changed(self._settings_tab_index)
        if section_title is not None and hasattr(self, "settings_nav_list"):
            for row in range(self.settings_nav_list.count()):
                if self.settings_nav_list.item(row).text() == section_title:
                    self.settings_nav_list.setCurrentRow(row)
                    break

    def _settings_resist_stack_values(self):
        """Reads (top_thickness_nm, bottom_thickness_nm, margin_nm) from
        Settings' own fields, falling back to the module defaults if a
        field isn't parseable or doesn't exist yet -- used by the
        calculator and available for any other consumer."""
        def f(edit, default):
            try:
                return float(edit.text())
            except (ValueError, AttributeError):
                return default
        top = f(getattr(self, "settings_top_thickness_edit", None), DEFAULT_TOP_RESIST_THICKNESS_NM)
        bottom = f(getattr(self, "settings_bottom_thickness_edit", None), DEFAULT_BOTTOM_RESIST_THICKNESS_NM)
        margin = f(getattr(self, "settings_margin_edit", None), DEFAULT_RESIST_SAFETY_MARGIN_NM)
        return top, bottom, margin

    def _sim_resist_label_text(self, role: str) -> str:
        """Composes the Simulate Design tab's resist-thickness row
        label from whatever name is currently configured in Settings
        (settings_top_name_edit/settings_bottom_name_edit) -- falls
        back to a generic "Top layer"/"Bottom layer" label if Settings
        hasn't been built yet (it's built after the Simulate tab -- see
        _refresh_sim_resist_labels) or its name field is blank."""
        edit = getattr(self, f"settings_{role}_name_edit", None)
        name = edit.text().strip() if edit is not None else ""
        if not name:
            name = "Top layer" if role == "top" else "Bottom layer"
        return f"{name} thickness (nm):"

    def _refresh_sim_resist_labels(self):
        """Keeps the Simulate Design tab's "Resist Stack & Electrode"
        card's row labels in sync with Settings' resist names: whatever
        resist name is listed in Settings automatically becomes what
        appears on this card. Called once right after Settings' own name fields are
        built (so the Simulate tab's initial generic labels get their
        real names -- _build_simulate_tab runs first, before
        Settings exists yet) and live thereafter via those fields'
        textChanged signal, so renaming a resist updates the card
        immediately without needing "Apply to Simulate Design tab"."""
        if hasattr(self, "sim_top_resist_label"):
            self.sim_top_resist_label.setText(self._sim_resist_label_text("top"))
        if hasattr(self, "sim_bottom_resist_label"):
            self.sim_bottom_resist_label.setText(self._sim_resist_label_text("bottom"))

    def _build_settings_resist_stack_section(self) -> QWidget:
        """Settings > Resist Stack & Calculator. A generalized bilayer +
        safety margin (not fixed to a specific resist pairing/
        thickness), plus the bidirectional linewidth <-> alpha
        calculator -- recipe_generator.compute_alpha_from_linewidth /
        compute_linewidth_from_alpha -- with no label hardcoded to a
        specific resist. "Apply to Simulate Design
        tab" pushes the stack straight into the currently open design's
        own Resist Stack & Electrode card (self.pmma_edit/pmgi_edit --
        the same widgets, since Simulate Design is one persistent tab
        for the whole session, not rebuilt per design)."""
        outer = QWidget()
        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        inner = QWidget()
        layout = QVBoxLayout(inner)
        scroll.setWidget(inner)
        outer_layout = QVBoxLayout(outer)
        outer_layout.addWidget(scroll)

        header = QLabel("Resist Stack & Calculator")
        self._themed(header, lambda: f"color: {TEXT_COLOR}; font-weight: bold; font-size: 12pt;")
        layout.addWidget(header)
        sub = QLabel("Any resist bilayer, any thickness, any safety margin.")
        sub.setWordWrap(True)
        self._themed(sub, lambda: f"color: {DIM_COLOR};")
        layout.addWidget(sub)

        stack_card, stack_content = self._sim_card("Bilayer Resist Stack", "#7fc8e6", collapsed=False)
        stack_form = QFormLayout()
        self.settings_top_name_edit = QLineEdit(DEFAULT_TOP_RESIST_NAME)
        stack_form.addRow("Top (imaging) layer name:", self.settings_top_name_edit)
        # These two thickness fields (here and on the Simulate Design
        # tab's own card) start blank rather than prefilled with
        # DEFAULT_TOP_RESIST_THICKNESS_NM/DEFAULT_BOTTOM_RESIST_THICKNESS_NM;
        # every downstream reader already tolerates a blank/unparseable
        # field by falling back to those same constants internally (see
        # _settings_resist_stack_values, _f), so this is purely about
        # not showing a specific number that looks like a real
        # recommendation before the user's actually chosen one.
        self.settings_top_thickness_edit = QLineEdit("")
        self.settings_top_thickness_edit.setPlaceholderText("nm")
        stack_form.addRow("Top layer thickness (nm):", self.settings_top_thickness_edit)
        self.settings_bottom_name_edit = QLineEdit(DEFAULT_BOTTOM_RESIST_NAME)
        stack_form.addRow("Bottom (undercut) layer name:", self.settings_bottom_name_edit)
        self.settings_bottom_thickness_edit = QLineEdit("")
        self.settings_bottom_thickness_edit.setPlaceholderText("nm")
        stack_form.addRow("Bottom layer thickness (nm):", self.settings_bottom_thickness_edit)
        self.settings_margin_edit = QLineEdit(f"{DEFAULT_RESIST_SAFETY_MARGIN_NM:g}")
        stack_form.addRow("Safety margin (nm):", self.settings_margin_edit)
        stack_content.addLayout(stack_form)

        apply_stack_btn = QPushButton("Apply to Simulate Design tab")
        apply_stack_btn.setToolTip("Pushes the top/bottom thickness above into the Simulate "
                                    "Design tab's own Resist Stack & Electrode card.")
        apply_stack_btn.clicked.connect(self._on_apply_resist_stack_to_sim)
        stack_content.addWidget(apply_stack_btn)
        layout.addWidget(stack_card)

        # Generalizes the Simulate Design tab's row labels to whatever
        # resist names are set here, immediately and live -- see
        # _refresh_sim_resist_labels.
        self.settings_top_name_edit.textChanged.connect(self._refresh_sim_resist_labels)
        self.settings_bottom_name_edit.textChanged.connect(self._refresh_sim_resist_labels)
        self._refresh_sim_resist_labels()

        calc_card, calc_content = self._sim_card("Linewidth <-> Alpha Calculator", "#c9a8e6", collapsed=False)
        calc_note = QLabel("alpha = arctan( linewidth / (top layer thickness - safety margin) ), "
                            "using the stack above.")
        calc_note.setWordWrap(True)
        self._themed(calc_note, lambda: f"color: {DIM_COLOR}; font-size: 8pt;")
        calc_content.addWidget(calc_note)

        lw_row = QHBoxLayout()
        lw_row.addWidget(QLabel("Line width (nm):"))
        self.settings_calc_lw_edit = QLineEdit()
        lw_row.addWidget(self.settings_calc_lw_edit)
        lw_to_alpha_btn = QPushButton("→ Compute alpha")
        lw_to_alpha_btn.clicked.connect(self._on_settings_compute_alpha)
        lw_row.addWidget(lw_to_alpha_btn)
        calc_content.addLayout(lw_row)

        alpha_row = QHBoxLayout()
        alpha_row.addWidget(QLabel("Alpha (deg):"))
        self.settings_calc_alpha_edit = QLineEdit()
        alpha_row.addWidget(self.settings_calc_alpha_edit)
        alpha_to_lw_btn = QPushButton("→ Compute linewidth")
        alpha_to_lw_btn.clicked.connect(self._on_settings_compute_linewidth)
        alpha_row.addWidget(alpha_to_lw_btn)
        calc_content.addLayout(alpha_row)

        commit_row = QHBoxLayout()
        use_tilt_btn = QPushButton("Use this tilt →")
        use_tilt_btn.setToolTip("Pushes the alpha above into the open design's Simulate Design "
                                 "tab (Active alpha) -- the same live value recipe generation "
                                 "reads for the deposition tilt.")
        use_tilt_btn.clicked.connect(self._on_settings_use_tilt)
        commit_row.addWidget(use_tilt_btn)
        commit_row.addStretch()
        calc_content.addLayout(commit_row)

        hint_note = QLabel("Also offered as a suggested hint on the finger linewidth fields.")
        hint_note.setWordWrap(True)
        self._themed(hint_note, lambda: f"color: {DIM_COLOR}; font-size: 8pt; font-style: italic;")
        calc_content.addWidget(hint_note)
        layout.addWidget(calc_card)

        layout.addStretch()
        return outer

    def _on_apply_resist_stack_to_sim(self):
        top, bottom, _ = self._settings_resist_stack_values()
        if hasattr(self, "pmma_edit"):
            self.pmma_edit.setText(f"{top:g}")
        if hasattr(self, "pmgi_edit"):
            self.pmgi_edit.setText(f"{bottom:g}")

    def _on_settings_compute_alpha(self):
        try:
            lw = float(self.settings_calc_lw_edit.text())
        except ValueError:
            QMessageBox.critical(self, "Cannot compute alpha", "Enter a numeric line width (nm).")
            return
        top, _, margin = self._settings_resist_stack_values()
        try:
            alpha = compute_alpha_from_linewidth(lw, top, margin)
        except ValueError as e:
            QMessageBox.critical(self, "Cannot compute alpha", str(e))
            return
        self.settings_calc_alpha_edit.setText(f"{alpha:.4f}")
        self._last_suggested_linewidth_nm = lw
        self._refresh_linewidth_hints()

    def _on_settings_compute_linewidth(self):
        try:
            alpha = float(self.settings_calc_alpha_edit.text())
        except ValueError:
            QMessageBox.critical(self, "Cannot compute linewidth", "Enter a numeric alpha (deg).")
            return
        top, _, margin = self._settings_resist_stack_values()
        lw = compute_linewidth_from_alpha(alpha, top, margin)
        self.settings_calc_lw_edit.setText(f"{lw:.4f}")
        self._last_suggested_linewidth_nm = lw
        self._refresh_linewidth_hints()

    def _on_settings_use_tilt(self):
        try:
            alpha = float(self.settings_calc_alpha_edit.text())
        except ValueError:
            QMessageBox.critical(self, "Cannot use tilt", "Compute or enter a numeric alpha (deg) first.")
            return
        # Settings > Process Parameters removal round: alpha_dep_edit is
        # gone -- Simulate Design's own "Active alpha" field is now the
        # ONE live value DesignParameters.alpha_deposition reads (see
        # _current_params), so pushing it here is the whole story; no
        # second field to keep in sync anymore.
        if hasattr(self, "sim_alpha_override_edit"):
            self.sim_alpha_override_edit.setText(f"{alpha:g}")

    def _build_settings_hotkeys_section(self) -> QWidget:
        """Settings > Hotkeys. A single hotkey database: easy to view,
        reassign, and clear each binding, clearly organized, covering
        every hotkey already implemented (including the arrow keys and
        the File/Edit/View menu shortcuts). One table, grouped by category exactly
        as hotkey_registry.DEFAULT_HOTKEYS orders them (File/Edit/View/
        Navigation/Deposition Slideshow), covering every keyboard
        shortcut in the app -- old and new -- with all of them equally
        reassignable: click a key chip to capture a new key, Clear to
        unassign, Reset to jump back to that entry's own default. See
        hotkey_registry.py's module docstring for the "action" vs
        "keyevent" split this reads from (invisible here -- the table
        treats every row identically; _set_hotkey/_apply_hotkey_entry
        is what actually dispatches based on it)."""
        outer = QWidget()
        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        inner = QWidget()
        layout = QVBoxLayout(inner)
        scroll.setWidget(inner)
        outer_layout = QVBoxLayout(outer)
        outer_layout.addWidget(scroll)

        header = QLabel("Hotkeys")
        self._themed(header, lambda: f"color: {TEXT_COLOR}; font-weight: bold; font-size: 12pt;")
        layout.addWidget(header)
        sub = QLabel("Every keyboard shortcut in the app, old and new. Click a key chip and "
                     "press a new key combination to reassign it; Clear removes a binding "
                     "entirely; Reset restores the original.")
        sub.setWordWrap(True)
        self._themed(sub, lambda: f"color: {DIM_COLOR};")
        layout.addWidget(sub)

        self._hotkey_conflict_label = QLabel("")
        self._hotkey_conflict_label.setWordWrap(True)
        self._hotkey_conflict_label.setVisible(False)
        self._themed(self._hotkey_conflict_label, lambda: (
            f"color: {WARN_COLOR}; font-weight: bold; padding: 6px 8px; "
            f"border: 1px solid {WARN_COLOR}; border-radius: 6px;"))
        layout.addWidget(self._hotkey_conflict_label)

        card, content = self._sim_card("Hotkey Database", "#7fb8ff", collapsed=False)
        table = QTableWidget(0, 5)
        table.setHorizontalHeaderLabels(["Category", "Action", "Key", "", ""])
        table.verticalHeader().setVisible(False)
        table.setEditTriggers(QAbstractItemView.NoEditTriggers)
        table.setSelectionMode(QAbstractItemView.NoSelection)
        # Category/Action share whatever width is left over; Key/Clear/
        # Reset stay fixed-width chips -- keeps the table filling the
        # card's real width instead of leaving a large blank gutter past
        # a short fixed-width last column (QTableWidget's own default).
        header = table.horizontalHeader()
        header.setStretchLastSection(False)
        header.setSectionResizeMode(0, QHeaderView.Stretch)
        header.setSectionResizeMode(1, QHeaderView.Stretch)
        for col in (2, 3, 4):
            header.setSectionResizeMode(col, QHeaderView.Fixed)
        table.setColumnWidth(2, 130)
        table.setColumnWidth(3, 70)
        table.setColumnWidth(4, 70)
        # The whole Settings page is already one big QScrollArea (outer
        # `scroll` above) -- letting the table grow to its own full
        # content height (no inner scrollbar) means the page scrolls
        # ONCE, rather than a short inner table viewport nested inside
        # an outer scroll area (confusing "which scrollbar do I use"
        # UX). _refresh_hotkeys_table sets the actual fixed height once
        # every row exists.
        table.setVerticalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        table.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        self._themed(table, lambda: f"""
            QTableWidget {{
                background-color: {PANEL_COLOR}; color: {TEXT_COLOR};
                gridline-color: {BORDER_COLOR}; border: 1px solid {BORDER_COLOR};
            }}
            QHeaderView::section {{
                background-color: {PANEL_COLOR}; color: {TEXT_COLOR};
                padding: 4px; border: 1px solid {BORDER_COLOR}; font-weight: bold;
            }}
        """)
        # Noted while testing this section's own light theme:
        # every other themed QTableWidget in this file (recipe_builder_
        # table, meas_table, interp_area_table) hardcodes its header
        # background to a fixed dark "#23242e" while its header TEXT
        # uses theme-reactive TEXT_COLOR -- fine in dark mode (TEXT_COLOR
        # is pale), but TEXT_COLOR flips to near-black ("#1c1d24") in
        # light mode, landing near-black text on that same hardcoded
        # near-black header background. This new table uses PANEL_COLOR
        # (itself theme-reactive, and already proven to contrast with
        # TEXT_COLOR everywhere else in the app) for the header instead,
        # so the header stays legible in both themes -- font-weight/
        # border alone distinguish it from the body rows now, rather
        # than a fixed-dark fill. The other three tables share this same
        # pre-existing issue but are out of scope for this change.
        content.addWidget(table)
        self._hotkey_table = table
        self._hotkey_row_widgets = {}  # hotkey_id -> (key_btn, clear_btn, reset_btn)
        self._build_hotkey_table_rows()
        self._refresh_hotkeys_table()
        layout.addWidget(card)
        layout.addStretch(1)
        return outer

    def _build_hotkey_table_rows(self):
        """Creates every row's widgets EXACTLY ONCE (Category/Action
        QTableWidgetItems, plus the Key/Clear/Reset cell widgets) and
        stashes the three per-row widgets in self._hotkey_row_widgets.

        A reassigned/conflicting row could show visibly garbled,
        overlapping button text -- root cause is a documented
        QTableWidget gotcha, not a paint-timing artifact (it persisted
        through repeated repaint()/processEvents() calls): "This
        function cannot be used to set a widget for a cell which already
        has one - in this case you must first delete the existing widget
        with removeCellWidget()." The original version of this code
        called setCellWidget(row, col, ...) with a BRAND NEW widget on
        every single refresh (including the very common case of just one
        row's key changing), which silently left the previous widget
        alive underneath the new one instead of replacing it. Building
        every row's widgets once here, and having _refresh_hotkeys_table
        only update their text/enabled/style afterward, avoids the
        setCellWidget-replacement pitfall entirely instead of working
        around it."""
        table = self._hotkey_table
        table.setRowCount(len(self._hotkey_entries))
        for row, entry in enumerate(self._hotkey_entries):
            cat_item = QTableWidgetItem(entry.category)
            cat_item.setFlags(cat_item.flags() & ~Qt.ItemIsEditable)
            table.setItem(row, 0, cat_item)

            action_item = QTableWidgetItem(entry.label)
            action_item.setFlags(action_item.flags() & ~Qt.ItemIsEditable)
            action_item.setToolTip(entry.description)
            table.setItem(row, 1, action_item)

            key_btn = _HotkeyCaptureButton("")
            key_btn.setToolTip("Click, then press a key combination to reassign.")
            key_btn.key_captured.connect(lambda text, hid=entry.id: self._on_hotkey_row_changed(hid, text))
            # Noted while testing this section's own light theme:
            # a key chip's border/background/text color were set with a
            # one-off setStyleSheet() call inside _refresh_hotkeys_table,
            # not through self._themed() -- so toggling the theme WITHOUT
            # also touching a hotkey afterward left every chip frozen in
            # whatever theme was active when it was last refreshed (dark
            # colors surviving a switch to light, or vice versa). Routing
            # it through self._themed() with a closure that recomputes
            # BOTH the live theme colors AND this row's current conflict
            # state on every call (never a value baked in once) fixes
            # that -- the same style_fn runs from _apply_theme's own
            # broadcast loop and from _refresh_hotkeys_table below.
            self._themed(key_btn, self._make_hotkey_key_style_fn(entry.id))
            table.setCellWidget(row, 2, key_btn)

            clear_btn = QPushButton("Clear")
            clear_btn.setToolTip("Unassign this hotkey.")
            clear_btn.clicked.connect(lambda _checked=False, hid=entry.id: self._on_hotkey_row_changed(hid, ""))
            table.setCellWidget(row, 3, clear_btn)

            reset_btn = QPushButton("Reset")
            reset_btn.clicked.connect(
                lambda _checked=False, hid=entry.id: self._on_hotkey_row_changed(
                    hid, next(e.default_key for e in self._hotkey_entries if e.id == hid)))
            table.setCellWidget(row, 4, reset_btn)

            self._hotkey_row_widgets[entry.id] = (key_btn, clear_btn, reset_btn)

        table.resizeRowsToContents()
        total_height = table.horizontalHeader().height() + 2
        for r in range(table.rowCount()):
            total_height += table.rowHeight(r)
        table.setFixedHeight(total_height)

    def _make_hotkey_key_style_fn(self, hotkey_id: str):
        """Returns a closure (for self._themed()) that recomputes a key
        chip's border/background/text on every call -- both the live
        theme colors (PANEL_COLOR/TEXT_COLOR/BORDER_COLOR/WARN_COLOR,
        plain module globals _apply_theme mutates) AND this row's
        CURRENT conflict state (self._hotkey_entries can change between
        calls), never a value baked in once. Registering this with
        self._themed() is what makes a plain theme toggle -- with no
        hotkey touched at all -- still repaint every key chip correctly;
        _refresh_hotkeys_table calls the exact same function after a
        real hotkey change."""
        def _style_fn():
            conflicts = hotkey_registry.find_conflicts(self._hotkey_entries)
            conflicting_ids = {hid for ids in conflicts.values() for hid in ids}
            is_conflict = hotkey_id in conflicting_ids
            return (
                f"border: 1.5px solid {WARN_COLOR}; border-radius: 5px; padding: 3px 8px;"
                if is_conflict else
                f"border: 1px solid {BORDER_COLOR}; border-radius: 5px; padding: 3px 8px; "
                f"background-color: {PANEL_COLOR}; color: {TEXT_COLOR};"
            )
        return _style_fn

    def _refresh_hotkeys_table(self):
        """Updates every row's EXISTING Key/Clear/Reset widgets (text,
        enabled state, conflict-highlight style) from self._hotkey_
        entries, and recomputes the conflict banner -- never recreates
        or replaces a cell widget (see _build_hotkey_table_rows' own
        comment for why that matters). Called once right after the rows
        are built, and again after every single-entry change
        (_on_hotkey_row_changed), since a change to one entry can affect
        whether OTHER rows are now conflicting, not just its own."""
        conflicts = hotkey_registry.find_conflicts(self._hotkey_entries)
        for entry in self._hotkey_entries:
            key_btn, clear_btn, reset_btn = self._hotkey_row_widgets[entry.id]
            key_btn.set_key_text(entry.current_key)
            key_btn.setStyleSheet(self._make_hotkey_key_style_fn(entry.id)())
            clear_btn.setEnabled(bool(entry.current_key))
            reset_btn.setEnabled(entry.is_customized)
            reset_btn.setToolTip(f"Restore the default: {entry.default_key or '(none)'}")

        if conflicts:
            lines = []
            id_to_label = {e.id: e.label for e in self._hotkey_entries}
            for key, ids in conflicts.items():
                names = ", ".join(id_to_label.get(hid, hid) for hid in ids)
                lines.append(f'"{key}" is assigned to more than one action: {names}')
            self._hotkey_conflict_label.setText("⚠ " + "  |  ".join(lines))
            self._hotkey_conflict_label.setVisible(True)
        else:
            self._hotkey_conflict_label.setVisible(False)

    def _on_hotkey_row_changed(self, hotkey_id: str, new_key: str):
        """Wired to every row's key-capture button, Clear button, and
        Reset button. Applies + persists the change (_set_hotkey) then
        refreshes every row's displayed state so conflict highlighting
        and every row's Reset-enabled state stay correct app-wide, not
        just for the one row that changed."""
        self._set_hotkey(hotkey_id, new_key)
        self._refresh_hotkeys_table()

    def _build_chamber_reference_tab(self) -> QWidget:
        """Settings > Chamber Reference Model: a much larger, standalone
        version of the retired Live Angle Tester's chamber view -- same alpha/theta/reference
        controls, same two-view (top-down + side) rendering, reusing
        _ChamberPreviewWidget (compact=False for the full detailed
        labeling/legend this needs at this size) so the actual
        chamber mechanics are byte-for-byte the same code the retired Live Angle Tester and
        every other embedded chamber preview already use -- just no
        "Commit Step to Recipe" section, since this page is a side tool
        for testing orientation, not a recipe step source; live step
        creation was removed from this page."""
        outer = QWidget()
        layout = QVBoxLayout(outer)
        layout.setContentsMargins(16, 12, 16, 16)
        layout.setSpacing(6)

        header_row = QHBoxLayout()
        header = QLabel("Chamber Reference Model")
        self._themed(header, lambda: f"color: {TEXT_COLOR}; font-weight: bold; font-size: 14pt;")
        header_row.addWidget(header)
        header_row.addStretch()
        back_hint = QLabel("← To leave, open Contents (top-left ≡) and pick any section")
        back_hint.setWordWrap(True)
        self._themed(back_hint, lambda: f"color: {DIM_COLOR}; font-size: 8pt; font-style: italic;")
        header_row.addWidget(back_hint)
        layout.addLayout(header_row)

        sub = QLabel("Adjust alpha/theta and the reference point to see how the wafer moves. Reference only -- nothing here is saved.")
        sub.setWordWrap(True)
        self._themed(sub, lambda: f"color: {DIM_COLOR};")
        layout.addWidget(sub)

        self.chamber_reference_widget = _ChamberPreviewWidget(
            figsize=(13.0, 5.6), show_readout=True, show_controls=True, compact=False)
        layout.addWidget(self.chamber_reference_widget, stretch=1)

        return outer

    def _build_navigation_rail(self):
        """A persistent left-side 'table of contents' for switching
        between the app's top-level sections -- always in the same
        screen position regardless of which section is active or what
        else is shown/hidden around it (explicitly requested: the old
        QTabWidget's own tab bar moved every time the Design/Import
        toolbar hid/showed). Two ways to bring it back once closed: the
        small always-visible toggle button at the very top-left (works
        regardless of which section is active, unlike the main toolbar),
        or hovering the far-left edge of the window (see
        _check_hover_reveal). Uses the normal Qt dock system, so showing
        it shifts/shrinks the rest of the window to fit -- not an
        overlay -- exactly like any other dock."""
        nav_toggle_toolbar = QToolBar("Show Contents")
        nav_toggle_toolbar.setMovable(False)
        toggle_action = QAction(qta.icon("fa5s.bars", color=TEXT_COLOR), "", self)
        toggle_action.setToolTip("Show/hide Contents")
        toggle_action.triggered.connect(lambda: self.nav_dock.setVisible(not self.nav_dock.isVisible()))
        # Quantum-styled to match the tab switcher button in the upper
        # left that gives access to the section list. Bound
        # to the SAME QAction via setDefaultAction() so its trigger,
        # tooltip, and enabled state all keep working unchanged -- only
        # the paint job is new; addWidget() (not addAction()) is required
        # to host a real widget in the toolbar instead of an auto-
        # generated default QToolButton. The old manual _themed_icons
        # registration is removed -- QuantumToolButton retints its own
        # icon on retheme(), so keeping both would double-tint.
        nav_toggle_button = QuantumToolButton("fa5s.bars", action=toggle_action, parent=nav_toggle_toolbar)
        nav_toggle_toolbar.addWidget(nav_toggle_button)
        self.insertToolBar(self.main_toolbar, nav_toggle_toolbar)  # explicitly leftmost,
                                                                      # regardless of build order
        self.nav_toggle_toolbar = nav_toggle_toolbar
        self.nav_toggle_action = toggle_action
        self.nav_toggle_button = nav_toggle_button

        self.nav_dock = QDockWidget("Contents", self)
        self.nav_dock.setFeatures(QDockWidget.DockWidgetClosable)
        self.nav_dock.setFixedWidth(230)

        nav_widget = QWidget()
        nav_layout = QVBoxLayout(nav_widget)
        nav_layout.setContentsMargins(4, 4, 4, 4)
        hint = QLabel("Click a section below. Reopen this panel with the \u2261 button (top-left).")
        hint.setWordWrap(True)
        self._themed(hint, lambda: f"color: {DIM_COLOR}; font-size: 8pt; padding-bottom: 4px;")
        nav_layout.addWidget(hint)

        self.nav_list = QListWidget()
        self.nav_list.setWordWrap(True)
        self._tab_definitions = [
            ("Front Page", "Overview and quick links to every section."),
            ("Create / Import", "Design or import a junction, place and classify shapes, "
                                        "and see automatic measurements."),
            ("Simulate Design", "Recommended deposition angles, warning explanations, and "
                                       "the shadowing visualization for the active design."),
            ("Recipe", "Generates a recipe from the last Simulate Design run -- each step "
                               "traces back to the finger/patch and warning that produced it."),
            ("Deposition Slideshow", "Steps through the generated recipe, showing chamber "
                               "orientation and detail text for each step alongside the finished design."),
            ("Measure Resistance", "Room-temperature resistance capture for a junction array. "
                               "Set the array size and scan pattern, read values aloud (Whisper or "
                               "Vosk) hands-free, and export to CSV."),
            ("Interpret Results", "Resistance vs. inverse junction area (Ambegaokar-Baratoff "
                               "validation). Load data, adjust geometry or apply an offset, plot, "
                               "and save/compare experiments."),
        ]
        for title, desc in self._tab_definitions:
            item = QListWidgetItem(f"{title}\n{desc}")
            item.setSizeHint(QSize(200, 70))
            self.nav_list.addItem(item)
        self.nav_list.setCurrentRow(0)
        self.nav_list.currentRowChanged.connect(self._on_nav_changed)
        # Left/right-arrow tab switching and, while on the Deposition
        # Slideshow specifically, up/down-arrow step scrolling -- see
        # MainWindow.keyPressEvent. Resolved by
        # title match (not a hardcoded index) so this keeps working
        # correctly even if _tab_definitions' own order/membership ever
        # changes again, the same way this section's own comment already
        # warns every hardcoded-index reference in this file to watch for.
        self._slideshow_nav_row = next(
            (i for i, (title, _desc) in enumerate(self._tab_definitions) if title == "Deposition Slideshow"),
            None)
        # NOTE: the initial dock/toolbar sync call is made after
        # _build_main_tabs() runs (main_stack doesn't exist yet here) --
        # see the call right after that in __init__.
        nav_layout.addWidget(self.nav_list)

        self.nav_dock.setWidget(nav_widget)
        self.addDockWidget(Qt.LeftDockWidgetArea, self.nav_dock)

    def _on_nav_changed(self, index: int):
        self.main_stack.setCurrentIndex(index)
        last_index = len(self._tab_definitions) - 1
        if hasattr(self, "status_back_btn"):
            in_real_tabs = 0 <= index <= last_index
            # Hidden pages (currently just Settings, at whatever index
            # main_stack.count() lands it at -- see self._settings_tab_index)
            # aren't part of the prev/next sequence at all -- hide the
            # whole nav widget there rather than leave it showing stale/
            # meaningless enabled state.
            self.status_nav_widget.setVisible(in_real_tabs)
            if in_real_tabs:
                self.status_back_btn.setEnabled(index > 0)
                self.status_forward_btn.setEnabled(index < last_index)
        # NOTE: every literal below is relative to the CURRENT nav_list/
        # main_stack row order (see _build_navigation_rail's
        # _tab_definitions and _build_main_tabs): Front Page (0), then
        # Create / Import, Simulate Design, Recipe, Deposition Slideshow,
        # Measure Resistance, Interpret Results (1-6). Two tabs that used
        # to sit in this pipeline (Live Angle & Step Creator and AI
        # Recipe & Verification) and a separate Shadowing & Additional
        # Info tab, plus the original Design / Import tab, have all been
        # removed once their functionality was fully absorbed into the
        # tabs above / Settings -- see _build_main_tabs' comment for where
        # Shadowing & Additional Info's fields went, and this file's
        # history for the rest.
        is_front_page = (index == 0)
        is_create_import = (index == 1)
        is_simulate_design = (index == 2)
        is_recipe = (index == 3)
        is_slideshow = (index == 4)
        is_measure_resistance = (index == 5)
        is_interpret_results = (index == 6)
        if is_interpret_results:
            self._refresh_interp_tc_default()  # safety net: re-sync T_c's suggested default in case
                                                   # the deposition metal changed while this tab wasn't visible
        self.main_toolbar.setVisible(is_create_import)  # shared shape-editing toolbar
        if hasattr(self, "create_import_toolbar_widgets"):
            # Measurements toggle / Clear Rulers / their separator only
            # apply to Create / Import's own canvas (create_import_ax).
            for _w_action in self.create_import_toolbar_widgets:
                _w_action.setVisible(is_create_import)
        if hasattr(self, "sim_toolbar"):
            self.sim_toolbar.setVisible(is_simulate_design)
        if hasattr(self, "slideshow_toolbar"):
            self.slideshow_toolbar.setVisible(is_slideshow)
        if is_slideshow and hasattr(self, "_on_slideshow_refresh"):
            self._on_slideshow_refresh()  # pull the latest recipe every time this page becomes visible
        # The preview graph must resize correctly not just for the
        # default design but also for one imported or loaded from the
        # library. draw_imported_junction_preview
        # (imported_junction_view.py) fills the canvas's
        # actual aspect ratio by reading the widget's CURRENT rendered
        # size (ax.get_position(original=True) x the figure's size in
        # inches) at the moment it draws. Importing a GDS file or loading
        # a design from the library (a modal dialog) can trigger that
        # redraw while Create / Import isn't the visible/laid-out tab yet,
        # so the fill-to-widget crop gets computed against a stale/default
        # canvas size unless something re-triggers a redraw once the tab
        # actually becomes visible with its real, final size. The
        # DEFAULT design looks fine simply because every field
        # edit that builds it already happens while Create / Import is the
        # visible tab (so its redraws always see the correct size); an
        # imported/loaded design has no such guarantee. Re-running the
        # same full preview update every time this tab becomes visible
        # (mirroring the Recipe/Deposition Slideshow refresh-on-show
        # pattern just above) guarantees the crop is always computed against the
        # tab's real, current geometry -- for ANY design, not just ones
        # that happened to already be on screen when they were built.
        if is_create_import:
            self._update_preview()
        if hasattr(self, "meas_toolbar"):
            self.meas_toolbar.setVisible(is_measure_resistance)
        for dock in self.shared_geometry_docks:
            dock.setVisible(is_create_import)
        self.create_import_bottom_dock.setVisible(is_create_import)
        if is_recipe and hasattr(self, "_on_recipe_tab_shown"):
            self._on_recipe_tab_shown()  # refresh the staleness banner every time this page becomes visible
        # Shape-editing interaction (creating/dragging/zooming/panning) is
        # hardcoded to whichever ax/canvas is currently "active" -- switched
        # here, not hardcoded to one tab's canvas -- so it works correctly
        # on whichever tab is actually visible. Simulate Design shares the
        # same mechanism: it only needs mouse-centered zoom, not the full
        # shape-editing interaction set, but sharing _active_ax/
        # _active_canvas means _zoom_step and the scroll handler work
        # identically there with no separate implementation.
        if is_create_import:
            self._active_ax, self._active_canvas = self.create_import_ax, self.create_import_canvas
        elif is_simulate_design:
            self._active_ax, self._active_canvas = self.sim_ax, self.sim_canvas
        elif is_slideshow and hasattr(self, "slideshow_ax"):
            # Scroll-to-zoom on the Deposition Slideshow's reference
            # panel, same mechanism as Simulate Design (see the
            # slideshow_canvas.mpl_connect comment above).
            self._active_ax, self._active_canvas = self.slideshow_ax, self.slideshow_canvas
        else:
            self._active_ax, self._active_canvas = self.create_import_ax, self.create_import_canvas

    def keyPressEvent(self, event):
        """Left/right arrows switch between the top-level nav-rail tabs
        (the exact same action as the status-bar prev/next-tab arrows,
        _build_status_bar); while the Deposition Slideshow is the active
        tab specifically, up/down arrows step through its recipe steps
        (the exact same action as its own Prev step/Next step toolbar
        buttons); and Escape (when nothing more specific already
        consumed it) clears the current shape/junction-member selection.
        All three -- and every other key this method checks -- resolve
        their ACTUAL key through self._hotkey_keyevent_combos, populated
        by _init_hotkey_system from Settings > Hotkeys
        (hotkey_registry.py); Left/Right/Up/Down/Esc are just each
        one's default, not hardcoded here anymore.

        Delete Selected Shape / Duplicate Selected Shape / Zoom to Fit /
        Reset View / Undo / Redo / etc. are all plain QAction shortcuts
        instead (Qt's own shortcut map dispatches those directly; they
        never reach this method) -- see hotkey_registry.py's module
        docstring for exactly why these few specifically stay on manual
        key-event handling rather than becoming QActions too.

        This override only ever SEES a key event that no more-specific
        focused child widget already claimed for its own purpose first --
        that's ordinary Qt event propagation, not anything special coded
        here: a QLineEdit/QTextEdit/QAbstractSpinBox/editable QComboBox
        consumes its own arrow keys for cursor movement or value
        stepping, a QListWidget/QTreeWidget/QTableView consumes up/down
        for its own row navigation, and the inline hand-edit popup
        (_InlineHandEditPopup) consumes its own Escape to cancel itself
        -- none of those ever reach here while focused. This is exactly
        the behavior wanted: these hotkeys add tab/step navigation and
        deselection without stealing keys away from normal text editing,
        spin-box stepping, list browsing, or popup-cancel behavior
        anywhere else in the app -- and it stays true no matter which
        key each one is reassigned to, since reassignment only changes
        which (key, modifiers) pair _matches() below compares against.

        Up/down is deliberately scoped to ONLY the Deposition Slideshow
        tab (not global) -- elsewhere, that key keeps whatever its
        ordinary meaning already is (e.g. scrolling a panel), since it's
        meant only to scroll between steps within the slideshow.
        Left/right tab-switching, by contrast, is global, mirroring the
        always-available status-bar arrows it reuses."""
        key = event.key()
        mods = event.modifiers()

        def _matches(hotkey_id):
            combo = getattr(self, "_hotkey_keyevent_combos", {}).get(hotkey_id)
            return combo is not None and combo[0] == key and combo[1] == mods

        if hasattr(self, "nav_list") and hasattr(self, "_tab_definitions") and \
                (_matches("nav_prev_tab") or _matches("nav_next_tab")):
            current = self.nav_list.currentRow()
            target = current - 1 if _matches("nav_prev_tab") else current + 1
            last_index = len(self._tab_definitions) - 1
            if 0 <= target <= last_index:
                self.nav_list.setCurrentRow(target)
            event.accept()
            return
        if getattr(self, "_slideshow_nav_row", None) is not None and \
                (_matches("slideshow_prev") or _matches("slideshow_next")):
            if hasattr(self, "nav_list") and self.nav_list.currentRow() == self._slideshow_nav_row:
                if _matches("slideshow_prev"):
                    self._on_slideshow_prev()
                else:
                    self._on_slideshow_next()
                event.accept()
                return
        if _matches("deselect"):
            # Clears whichever of the two mutually-exclusive selection
            # states (_on_canvas_press) is currently set -- the same
            # pair _delete_selected_shape/_undo/_redo already null out,
            # so a deselected state is never stale/invalid. Also clears
            # a committed marquee/rubber-band batch, the third selection
            # state this app now has.
            if (self.electrode_scene.selected_id is not None or self._selected_junction_id is not None
                    or self._marquee_selection is not None):
                self.electrode_scene.selected_id = None
                self._selected_junction_id = None
                self._marquee_selection = None
                self._update_preview()
            event.accept()
            return
        super().keyPressEvent(event)

    def _show_chamber_reference_tab(self):
        """Settings > Chamber Reference Model entry point. Chamber
        Reference Model is now one section inside the Settings page
        (see _build_settings_tab) rather than its own separate hidden
        page, so this is now a thin wrapper around _show_settings_tab
        that also selects that section's row -- every existing call
        site (Recipe's clickable alpha:theta recipe links, the gear
        menu action) keeps working unchanged, same method name, same
        zero-argument call."""
        self._show_settings_tab("Chamber Reference Model")

    def _check_hover_reveal(self):
        """Auto-CLOSE only, on a timer polling the ABSOLUTE cursor
        position -- the panel now only OPENS via the manual toggle
        button (nav_toggle_action), not by hovering near the edge. That
        reveal-on-hover behavior was removed: it was causing the whole
        window to visibly reflow/elongate as the dock's presence toggled
        in and out during ordinary mouse movement near the left edge,
        which is more disruptive than useful. Auto-close is kept, since
        that part was working as intended and is still convenient once
        the panel's been opened deliberately."""
        if not self.nav_dock.isVisible():
            return
        pos = self.mapFromGlobal(QCursor.pos())
        close_threshold = self.nav_dock.width() + 60
        if pos.x() > close_threshold or pos.y() < 0 or pos.y() > self.height():
            self.nav_dock.setVisible(False)

    def _build_create_import_tab(self) -> QWidget:
        """Create / Import -- pure geometry, no shadowing info at all.
        Reads the SAME app-wide design state every other tab shares
        (self.electrode_scene, self._current_params(), self._junction),
        drawn onto its own canvas with show_badges=False (nothing
        warning-related, not even neutral-colored), and a simple
        Measurements-only bottom panel instead of a full Warnings/
        Measurements/Recommendations split."""
        outer = _ResizeNotifyingWidget()  # Lets the floating Design Warnings
                                           # banner (built below) re-anchor itself on resize --
                                           # see _ResizeNotifyingWidget's own docstring
        layout = QVBoxLayout(outer)
        layout.setContentsMargins(4, 4, 4, 4)  # the preview canvas should use essentially the
                                                  # whole tab now -- see the slimmed active_bar below

        # --- Active Design strip: trimmed down to just the Created/
        # Imported selector (still real, load-bearing state -- this
        # choice is what Simulate Design and everything downstream will
        # use). The Measurements toggle and Clear Rulers button live in
        # the main toolbar instead (see _build_toolbar's
        # create_import_toolbar_widgets), and the preview canvas below
        # fills the rest of the tab (see draw_imported_junction_preview's
        # aspect-fill logic).
        active_bar = QWidget()
        self._themed(active_bar, lambda: f"background-color: {PANEL_COLOR}; border-radius: 6px;")
        active_row = QHBoxLayout(active_bar)
        active_row.setContentsMargins(10, 4, 10, 4)
        active_label = QLabel("ACTIVE DESIGN:")
        self._themed(active_label, lambda: f"color: {DIM_COLOR}; font-weight: bold; font-size: 9pt; letter-spacing: 1px;")
        active_row.addWidget(active_label)
        self.create_import_active_created_btn = QPushButton("Created")
        self.create_import_active_created_btn.setCheckable(True)
        self.create_import_active_created_btn.clicked.connect(lambda: self._set_display_source("parametric"))
        self.create_import_active_imported_btn = QPushButton("Imported")
        self.create_import_active_imported_btn.setCheckable(True)
        self.create_import_active_imported_btn.setEnabled(False)  # nothing imported yet -- enabled
                                                                # on the first successful import
        self.create_import_active_imported_btn.clicked.connect(lambda: self._set_display_source("imported"))
        active_row.addWidget(self.create_import_active_created_btn)
        active_row.addWidget(self.create_import_active_imported_btn)
        self.create_import_active_detail_label = QLabel("")
        self._themed(self.create_import_active_detail_label, lambda: f"color: {ACCENT_COLOR}; font-size: 9pt;")
        active_row.addWidget(self.create_import_active_detail_label)
        active_row.addStretch()
        active_bar.setMaximumHeight(34)  # slim, single-row strip -- the canvas
                                            # below gets the rest of the tab's height
        layout.addWidget(active_bar)

        # --- Design Warnings banner: a notification-style warning
        # system for this tab that surfaces design-based warnings -- see
        # _check_design_stage_warnings for exactly what it checks.
        # Always visible (not tucked inside a dock tab that might not be
        # raised) and completely hidden when the design has no warnings
        # at all, so it reads as a real notification rather than
        # permanent screen furniture.
        #
        # This banner must not participate in the tab's QVBoxLayout: if
        # it were a normal `layout.addWidget(...)` item sitting between
        # active_bar and the preview canvas, then _update_preview --
        # which reruns on every single mouse-motion frame of a live
        # drag/scale/rotate -- showing/hiding it or changing its height
        # (word-wrapped text, more/fewer warning lines) on ANY frame
        # would reflow the whole layout, changing the canvas's own pixel
        # size/position mid-gesture and corrupting event.xdata/ydata for
        # the in-progress drag, making edits imprecise. It's instead a
        # free-floating overlay -- NOT parented into `layout`, so its
        # own visibility/size can never affect anyone else's geometry;
        # it's simply painted on top of the canvas, in its top-right
        # corner, positioned/resized by _position_design_warnings_banner
        # (called after every content change, and on every resize of the
        # tab via _ResizeNotifyingWidget.on_resize -- see that class's
        # own docstring for why the canvas's geometry is already up to
        # date by then). It also animates in/out
        # (_show_design_warnings_banner/_hide_design_warnings_banner),
        # sliding in from the right and fading in over a brief,
        # sub-second transition.
        self.design_warnings_banner = QWidget(outer)
        self._themed(self.design_warnings_banner, lambda: f"background-color: {WARN_COLOR}22; "
                    f"border: 1px solid {WARN_COLOR}; border-radius: 6px;")
        design_warnings_layout = QVBoxLayout(self.design_warnings_banner)
        design_warnings_layout.setContentsMargins(10, 6, 10, 6)
        self.design_warnings_label = QLabel("")
        self.design_warnings_label.setWordWrap(True)
        self._themed(self.design_warnings_label, lambda: f"color: {WARN_COLOR}; font-size: 8.5pt;")
        design_warnings_layout.addWidget(self.design_warnings_label)
        self._design_warnings_opacity_effect = QGraphicsOpacityEffect(self.design_warnings_banner)
        self._design_warnings_opacity_effect.setOpacity(1.0)
        self.design_warnings_banner.setGraphicsEffect(self._design_warnings_opacity_effect)
        self.design_warnings_banner.setVisible(False)  # shown only once _update_design_warnings_panel
                                                          # actually has something to report
        # Deliberately NOT layout.addWidget(...) -- see the comment above.

        self.create_import_fig = Figure(figsize=(6, 6), dpi=100, facecolor=BG_COLOR)
        self.create_import_ax = self.create_import_fig.add_subplot(1, 1, 1)
        # The aspect-fill fix in draw_imported_junction_preview
        # (widening the DATA crop to match the axes BOX's aspect ratio) was
        # necessary but not sufficient -- matplotlib's default subplot
        # margins (left=0.125, right=0.9, bottom=0.11, top=0.88) leave the
        # axes box itself sitting at roughly 77% of the figure's width AND
        # height, which is close to square-shaped even inside a wide
        # landscape figure. Widening the data to fill that already-near-
        # square box does nothing visible -- the real dead space was
        # this OUTER margin around the box, not empty
        # space inside it. Matches the tight-margin pattern
        # _ChamberPreviewWidget already uses for the exact same reason
        # (see its own subplots_adjust call). top=0.90 (not tighter) is
        # deliberate -- draw_imported_junction_preview always sets a
        # title via ax.set_title(...), which needs that headroom or it
        # gets clipped against the widget's top edge. bottom=0.08 (not
        # tighter) is deliberate too: draw_imported_junction_preview
        # draws the scale-bar label a little BELOW the visible y-range on
        # purpose (see its bar_y computation) -- too tight a bottom
        # margin pushes that label off the bottom of
        # the actual canvas entirely, since it isn't clipped to the axes
        # box, it's clipped to the FIGURE itself.
        self.create_import_fig.subplots_adjust(left=0.01, right=0.99, top=0.90, bottom=0.11)
        # matplotlib's callback registry holds only a WEAK reference to
        # whatever's connected. A bound method created inline here has no
        # other strong reference anywhere, so it was being garbage
        # collected almost immediately -- the callback silently never
        # fired again after that (no error, it just does nothing once
        # the weak reference is dead). Storing the bound method as an
        # instance attribute FIRST keeps a strong reference alive for
        # as long as the window itself exists.
        self._create_import_xlim_callback = self._on_create_import_xlim_changed
        self.create_import_ax.callbacks.connect("xlim_changed", self._create_import_xlim_callback)
        self.create_import_canvas = FigureCanvasQTAgg(self.create_import_fig)
        self.create_import_canvas.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)  # Without this,
                                        # the canvas just sits at its
                                        # figsize-derived preferred size instead of actually claiming
                                        # available space, leaving a large blank area beside it
        self.create_import_canvas.mpl_connect("button_press_event", self._on_canvas_press)
        self.create_import_canvas.mpl_connect("motion_notify_event", self._on_canvas_motion)
        self.create_import_canvas.mpl_connect("button_release_event", self._on_canvas_release)
        self.create_import_canvas.mpl_connect("scroll_event", self._on_canvas_scroll)
        layout.addWidget(self.create_import_canvas, stretch=1)
        outer.on_resize = self._position_design_warnings_banner  # Keeps the
                                    # floating banner anchored to the canvas's top-right
                                    # corner whenever this tab (and so the canvas) resizes
        return outer

    def _populate_patch_group_item(self, tree, group_item, pg):
        """Builds the per-patch content shown under the bottom Measurements
        dock's per-finger patch groups (_populate_measurements_tree). Used
        to also be shared with the Patches creator panel's own "Live
        Measurements" branch, which was removed as redundant since the
        same measurements already appear under "Measurements" at the
        bottom of the screen -- keeping live measurements in two places
        at once was redundant."""
        def add_row(parent, label, value=""):
            item = QTreeWidgetItem([label, value])
            parent.addChild(item)
            return item

        for k in range(pg.patch_count):
            w_nm = pg.individual_widths_um[k] * 1000.0
            patch_item = add_row(group_item, f"patch[{k}]", f"W={w_nm:.1f} nm")
            add_row(patch_item, "Linewidth", f"{w_nm:.1f} nm")
            if k < len(pg.individual_near_overhang_um):
                add_row(patch_item, "Near overhang", f"{pg.individual_near_overhang_um[k]:.3f} \u00b5m")
            if k < len(pg.individual_far_overhang_um):
                add_row(patch_item, "Far overhang", f"{pg.individual_far_overhang_um[k]:.3f} \u00b5m")
            if k < len(pg.individual_overlap_depths_um) and pg.individual_overlap_depths_um[k] is not None:
                add_row(patch_item, "Electrode overlap", f"{pg.individual_overlap_depths_um[k]:.3f} \u00b5m")
            if k < len(pg.individual_overlap_area_um2):
                add_row(patch_item, "Contact area (finger/plate)", f"{pg.individual_overlap_area_um2[k]:.4f} \u00b5m\u00b2")
        if pg.edge_to_edge_spacings_um:
            spacings = ", ".join(f"{s:.3f}" for s in pg.edge_to_edge_spacings_um)
            add_row(group_item, "Edge-to-edge spacing(s)", f"[{spacings}] \u00b5m")
        if pg.individual_far_overhang_um:
            smallest = min(pg.individual_far_overhang_um + pg.individual_near_overhang_um)
            largest = max(pg.individual_far_overhang_um + pg.individual_near_overhang_um)
            add_row(group_item, "Smallest / largest overhang", f"{smallest:.3f} / {largest:.3f} \u00b5m")
        if pg.total_overlap_area_um2 is not None:
            add_row(group_item, "Total contact area (finger/plate)", f"{pg.total_overlap_area_um2:.4f} \u00b5m\u00b2")
        if pg.finger_tip_past_last_patch_um is not None:
            left, right, shortest = pg.finger_tip_past_last_patch_um
            add_row(group_item, "Finger tip past last patch",
                   f"left={left:.3f}, right={right:.3f} \u00b5m (shortest={shortest:.3f})")

    def _populate_measurements_tree(self, report):
        """Replaces the old flat wall-of-text caption with a proper
        hierarchical tree: collapsed by default (so even a small dock
        height shows the full outline at a glance), with every finger
        and patch group expandable on demand -- the canvas gets priority
        for space, the measurements stay one click away rather than
        permanently consuming a large vertical block."""
        tree = self.create_import_measurements_tree
        tree.clear()

        def add_row(parent, label, value=""):
            item = QTreeWidgetItem([label, value])
            (parent.addChild if parent is not None else tree.addTopLevelItem)(item)
            return item

        add_row(None, "Source", report.source_label)
        overview = add_row(None, "Overview")
        if report.jj_crossing_area_um2 is not None:
            add_row(overview, "JJ crossing area (tunnel barrier)", f"{report.jj_crossing_area_um2:.5f} \u00b5m\u00b2")
        if report.total_exposed_area_um2 is not None:
            add_row(overview, "Total write area (union)", f"{report.total_exposed_area_um2:.4f} \u00b5m\u00b2")
        overview.setExpanded(True)

        for i, (L, W) in enumerate(zip(report.finger_lengths_um, report.finger_widths_nm)):
            label = ji.finger_display_label(i)
            finger_item = add_row(None, f"Finger {label}", f"L={L:.3f} \u00b5m, W={W:.1f} nm")
            add_row(finger_item, "Length", f"{L:.3f} \u00b5m")
            add_row(finger_item, "Linewidth", f"{W:.1f} nm")
            crossing_overlap = report.finger_crossing_overlap_um[i] if i < len(report.finger_crossing_overlap_um) else None
            if crossing_overlap is not None:
                add_row(finger_item, "Junction overlap (with other finger)", f"{crossing_overlap:.3f} \u00b5m")
            overlap_depth = report.finger_electrode_overlap_depth_um[i] if i < len(report.finger_electrode_overlap_depth_um) else None
            if overlap_depth is not None:
                add_row(finger_item, "Finger-to-electrode overlap", f"{overlap_depth:.3f} \u00b5m")
            tip_shortest = report.finger_tip_shortest_overhang_um[i] if i < len(report.finger_tip_shortest_overhang_um) else None
            if tip_shortest is not None:
                add_row(finger_item, "Shortest corner overlap depth (per side)", f"{tip_shortest:.3f} \u00b5m")

        for pg in report.patch_groups:
            label = ji.finger_display_label(pg.finger_index)
            group_item = add_row(None, f"Finger {label} Patches", f"n={pg.patch_count}")
            self._populate_patch_group_item(tree, group_item, pg)

    def _on_show_measurements_toggled(self, checked):
        self.show_measurements_toggle.setText("Measurements: On" if checked else "Measurements: Off")
        self._redraw_create_import_overlay()

    def _redraw_create_import_overlay(self):
        """Redraws JUST the measurement overlay (dotted lines + labels)
        on top of whatever's already drawn, using the cached junction/
        report from the last full update -- lets zooming rescale the
        label text without re-running the full design computation each
        time, and lets the toggle flip on/off instantly."""
        if not hasattr(self, "create_import_ax") or self._create_import_cached_junction is None:
            return
        # This call passes layer_highlight/selected_stable_id/
        # shape_class_fn through, so clicking a layer (or a shape)
        # highlights it on Create / Import's own canvas too --
        # _update_preview always computes these. Both this overlay and
        # Simulate Design share the SAME design and the SAME
        # _layer_highlight/_selected_junction_id state, so both reflect
        # it.
        draw_imported_junction_preview(self.create_import_ax, self._create_import_cached_junction,
                                       self._create_import_cached_report,
                                       **self._create_import_view_kwargs(),
                                       selected_stable_id=self._selected_junction_id,
                                       layer_highlight=self._layer_highlight,
                                       shape_class_fn=self._effective_shape_class,
                                       show_badges=False, show_caption=False)
        self._draw_create_import_selected_custom_shape()
        self._draw_create_import_selected_finger_rotation_handle()
        self._draw_create_import_layer_rotation_ring()
        self._draw_create_import_marquee_selection()
        self.create_import_ax.callbacks.connect("xlim_changed", self._create_import_xlim_callback)  # draw_imported_junction_preview
                    # calls ax.clear() internally,
                    # which unconditionally wipes the ENTIRE callback registry (the real
                    # cause, not a weak-reference GC issue as first suspected).
                    # Since this redraw runs on every parameter change, the connection made once at
                    # construction was being destroyed almost immediately and never present again.
                    # Must reconnect after every redraw, not just once.
        self.create_import_ax.set_facecolor(BG_COLOR)
        for spine in self.create_import_ax.spines.values():
            spine.set_color(BORDER_COLOR)
        self._draw_pending_polygon(self.create_import_ax)  # keeps in-progress polygon vertices visible
                                    # through a zoom/pan-triggered overlay-only redraw too, not just
                                    # the full _update_create_import_preview path
        self._draw_rulers(self.create_import_ax)
        if self.show_measurements_toggle.isChecked():
            self._draw_measurement_overlay(self.create_import_ax, self._create_import_cached_junction, self._create_import_cached_report)
        self.create_import_canvas.draw()

    def _overlay_fontsize(self, ax):
        """Font scales with the CURRENT view width in data units, not a
        fixed screen-pixel size -- zooming in on the canvas makes the
        labels visually larger, same as zooming in on the drawing itself
        would. Clamped so it never becomes illegibly tiny or
        absurdly large at extreme zoom levels."""
        xlim = ax.get_xlim()
        view_width = abs(xlim[1] - xlim[0]) or 1.0
        return max(3.0, min(20.0, 26.0 / view_width))

    def _draw_measurement_overlay(self, ax, junction, report):
        """Dotted dimension lines + bare numbers (no explanatory labels --
        just the distance) for the dimensions most relevant to shadowing:
        finger length, finger linewidth, patch linewidth, and
        patch-to-patch spacing. Deliberately not every measurement in
        the tree, to avoid the exact clutter this was designed to
        avoid -- these are the ones with an obvious, unambiguous place
        to draw a line on the actual geometry.

        Uses whatever finger/patch axis angles and points are already on
        the junction objects, so this works for any angle, length, or
        width combination -- not just the current default design.

        Stores every Text artist it creates in self._create_import_overlay_texts
        so a later zoom can rescale their font size directly (see
        _on_create_import_xlim_changed) without a full redraw -- a full
        redraw would reset xlim/ylim via draw_imported_junction_preview,
        which would immediately re-trigger xlim_changed and recurse.

        The dimension numbers use GRAPH_TEXT_COLOR, a theme-reactive
        "quantum blue" text color (see its own definition/docstring next
        to _DARK_VALUES/_LIGHT_VALUES) -- darker blue on the light
        canvas, lighter blue on the dark one, read live at draw time so
        a theme toggle picks it up on the very next redraw. A hardcoded,
        theme-invariant gray ("#aaacba") reads fine on the dark canvas
        but measures only a 2.09:1 contrast ratio against the light-mode
        canvas -- WCAG AA wants >=4.5:1 for normal text, so that would
        be close to invisible in light mode, not just a stylistic
        issue. The dotted connector lines use DIM_COLOR (already
        theme-reactive, already used everywhere else for secondary/muted
        UI elements) for the same reason -- they're meant to read as a
        subtle guide, not the labels themselves, so DIM_COLOR's muted-
        but-legible contrast on both themes is the right fit."""
        fs = self._overlay_fontsize(ax)
        line_kw = dict(color=DIM_COLOR, linewidth=0.6, linestyle=(0, (2, 2)), zorder=20)
        text_kw = dict(color=GRAPH_TEXT_COLOR, fontsize=fs, ha="center", va="center", zorder=21)
        self._create_import_overlay_texts = []
        MIN_SHOWN_LENGTH = 0.02  # um -- anything at or below this (including exact 0, no gap/
                                    # no overhang, degenerate cases) is skipped entirely rather
                                    # than drawn, since a zero-length dimension is pure clutter,
                                    # not information

        def add_text(*args, **kwargs):
            t = ax.text(*args, **kwargs)
            self._create_import_overlay_texts.append(t)
            return t

        def add_dimension(p1, p2, value, **kwargs):
            """A line + centered label for a real, non-trivial distance
            -- skips drawing anything at all if the value is at or near
            zero, so a design with no gap/no overhang doesn't clutter
            the view with a meaningless zero-length marker."""
            if value <= MIN_SHOWN_LENGTH:
                return
            ax.plot([p1[0], p2[0]], [p1[1], p2[1]], **line_kw)
            mx, my = (p1[0]+p2[0])/2.0, (p1[1]+p2[1])/2.0
            add_text(mx, my, f"{value:.2f}\u00b5m", **{**text_kw, **kwargs})

        for i, f in enumerate(junction.fingers):
            ang = math.radians(f.axis_angle_deg)
            f_hat = (math.cos(ang), math.sin(ang))
            perp = (-f_hat[1], f_hat[0])
            offset = f.width_um * 1.8 + 0.15  # clear of the finger body itself

            # Length: dotted line alongside the finger, from stub to tip
            if f.length_um > MIN_SHOWN_LENGTH:
                sx, sy = f.stub_end[0] + perp[0] * offset, f.stub_end[1] + perp[1] * offset
                ex, ey = f.patch_end[0] + perp[0] * offset, f.patch_end[1] + perp[1] * offset
                ax.plot([sx, ex], [sy, ey], **line_kw)
                mx, my = (sx + ex) / 2.0, (sy + ey) / 2.0
                add_text(mx + perp[0] * 0.1, my + perp[1] * 0.1, f"{f.length_um:.2f}\u00b5m", **text_kw)

            # Linewidth: a short perpendicular tick near the midpoint
            midx, midy = (f.stub_end[0] + f.patch_end[0]) / 2.0, (f.stub_end[1] + f.patch_end[1]) / 2.0
            hw = f.width_um / 2.0
            tx0, ty0 = midx + perp[0] * hw, midy + perp[1] * hw
            tx1, ty1 = midx - perp[0] * hw, midy - perp[1] * hw
            ax.plot([tx0, tx1], [ty0, ty1], **line_kw)
            add_text(midx + f_hat[0] * 0.15, midy + f_hat[1] * 0.15, f"{f.width_um*1000:.0f}nm", **text_kw)

            # Junction overlap: dotted line ALONG the finger's own axis
            # (no perpendicular offset, so it reads as distinct from the
            # length dimension drawn beside the finger) from this
            # finger's stub end to where its axis crosses the OTHER
            # finger's axis -- exactly the segment finger_overlap_um()
            # measures, and the same number already shown per-finger in
            # the Shape Properties card and the bottom Measurements tree
            # (report.finger_crossing_overlap_um, computed once in
            # compute_measurements and reused here rather than
            # recomputed, so all three surfaces always agree). Only
            # drawn for a genuine positive overlap -- a negative value
            # means the fingers don't actually cross (a gap, not an
            # overlap), which add_dimension's own MIN_SHOWN_LENGTH-based
            # skip wouldn't otherwise filter out since it compares
            # against the raw value, not its magnitude.
            overlap_val = (report.finger_crossing_overlap_um[i]
                           if report is not None and i < len(report.finger_crossing_overlap_um) else None)
            if overlap_val is not None and overlap_val > MIN_SHOWN_LENGTH and len(junction.fingers) == 2:
                other = junction.fingers[1 - i]
                crossing = ji.finger_overlap_start_point(f, other)
                if crossing is not None:
                    add_dimension(crossing, f.stub_end, overlap_val)

        for pg in report.patch_groups if report is not None else []:
            finger = junction.fingers[pg.finger_index]
            shapes = [s for s in junction.other_shapes if s.kind == "patch"]
            # re-derive this finger's own patches in position order (same
            # sort the measurement pipeline already uses) rather than
            # re-deriving from scratch -- just enough to place labels
            fx, fy = finger.patch_end[0]-finger.stub_end[0], finger.patch_end[1]-finger.stub_end[1]
            flen = math.hypot(fx, fy) or 1.0
            fu, fv = fx/flen, fy/flen
            def pos(s):
                cx = sum(p[0] for p in s.points)/len(s.points)
                cy = sum(p[1] for p in s.points)/len(s.points)
                return (cx-finger.stub_end[0])*fu + (cy-finger.stub_end[1])*fv
            nearby = sorted(shapes, key=lambda s: sg.Polygon(s.points).distance(sg.Point(finger.patch_end)))[:pg.patch_count]
            nearby = sorted(nearby, key=pos)

            finger_poly = sg.Polygon(finger.points)
            plate = ji._find_finger_plate(junction, finger)
            connector = so.unary_union([finger_poly, sg.Polygon(plate.points)]) if plate is not None else finger_poly

            for k, s in enumerate(nearby):
                axis_angle, end_a, end_b, _w = ji._polygon_axis_and_ends(s.points)
                cx = sum(p[0] for p in s.points) / len(s.points)
                cy = sum(p[1] for p in s.points) / len(s.points)
                pang = math.radians(axis_angle)
                p_hat = (math.cos(pang), math.sin(pang))
                pperp = (-p_hat[1], p_hat[0])
                w_um = pg.individual_widths_um[k] if k < len(pg.individual_widths_um) else s.width_um
                hw = w_um / 2.0
                tx0, ty0 = cx + pperp[0]*hw, cy + pperp[1]*hw
                tx1, ty1 = cx - pperp[0]*hw, cy - pperp[1]*hw
                ax.plot([tx0, tx1], [ty0, ty1], **line_kw)
                add_text(cx + p_hat[0]*0.15, cy + p_hat[1]*0.15, f"{w_um*1000:.0f}nm", **text_kw)
                if k > 0:
                    prev_poly = sg.Polygon(nearby[k-1].points)
                    this_poly = sg.Polygon(s.points)
                    gap = prev_poly.distance(this_poly)
                    if gap > MIN_SHOWN_LENGTH:
                        p1, p2 = so.nearest_points(prev_poly, this_poly)
                        gx, gy = (p1.x+p2.x)/2.0, (p1.y+p2.y)/2.0
                        ax.plot([p1.x, p2.x], [p1.y, p2.y], **line_kw)
                        add_text(gx, gy, f"{gap:.2f}\u00b5m", **text_kw)

                # Long/short extension: draw the ACTUAL span (finger/
                # plate edge boundary -> patch's own end) on each side.
                # Previously this placed a bare
                # number near the patch's own end point with NO
                # accompanying line at all, giving no visual indication
                # of what distance it represented or where the reference
                # point was. Now calls _measure_local_width_and_overhang
                # directly (same function the measurement pipeline uses)
                # and draws the real boundary/patch points it returns.
                _lw, _no, _fo, geo = ji._measure_local_width_and_overhang(
                    finger.stub_end, finger.patch_end, connector, s.points, axis_angle, (cx, cy))
                near_val = pg.individual_near_overhang_um[k] if k < len(pg.individual_near_overhang_um) else _no
                far_val = pg.individual_far_overhang_um[k] if k < len(pg.individual_far_overhang_um) else _fo
                if near_val > MIN_SHOWN_LENGTH:
                    ax.plot([geo["near_boundary_pt"][0], geo["near_patch_pt"][0]],
                           [geo["near_boundary_pt"][1], geo["near_patch_pt"][1]], **line_kw)
                    nmx = (geo["near_boundary_pt"][0]+geo["near_patch_pt"][0])/2.0
                    nmy = (geo["near_boundary_pt"][1]+geo["near_patch_pt"][1])/2.0
                    add_text(nmx, nmy, f"{near_val:.2f}\u00b5m", **text_kw)
                if far_val > MIN_SHOWN_LENGTH:
                    ax.plot([geo["far_boundary_pt"][0], geo["far_patch_pt"][0]],
                           [geo["far_boundary_pt"][1], geo["far_patch_pt"][1]], **line_kw)
                    fmx = (geo["far_boundary_pt"][0]+geo["far_patch_pt"][0])/2.0
                    fmy = (geo["far_boundary_pt"][1]+geo["far_patch_pt"][1])/2.0
                    add_text(fmx, fmy, f"{far_val:.2f}\u00b5m", **text_kw)

            # Finger tip past last patch: draw the ACTUAL span (entry
            # point on the last patch -> finger tip corner) on each
            # side, using the exact same geometry the measurement itself
            # uses (_finger_past_last_patch_geometry), so the drawn
            # line's length is always the real distance -- not a fixed-
            # length symbol -- and it visibly connects to the patch the
            # number is measuring.
            if pg.finger_tip_past_last_patch_um is not None and nearby:
                outer_patch = nearby[-1]
                geo = ji._finger_past_last_patch_geometry(finger.stub_end, finger.patch_end, connector, outer_patch.points)
                for exit_pt, tip_pt, dist in geo:
                    if dist <= MIN_SHOWN_LENGTH:
                        continue
                    ax.plot([exit_pt[0], tip_pt[0]], [exit_pt[1], tip_pt[1]], **line_kw)
                    lx, ly = (exit_pt[0]+tip_pt[0])/2.0, (exit_pt[1]+tip_pt[1])/2.0
                    add_text(lx, ly, f"{dist:.2f}\u00b5m", **text_kw)

            # Shortest patch-electrode overlap -- particularly important
            # for shadowing. A real callout: a dot AT the actual overlap
            # boundary (centroid of the overlap region itself), a short
            # leader line, and a label -- same grey/style as every other
            # measurement here now, not a special color/box. Skipped
            # entirely if every patch in the group is FULLY inside the
            # electrode (nothing sticking out unconnected) -- in that
            # case there's no meaningful "shortest overlap" risk to flag,
            # since none of them have a partial/marginal connection at
            # all. Only the WORST (minimum) patch gets a callout when
            # this does apply, to avoid repeating it for every patch.
            valid_depths = [(k, d) for k, d in enumerate(pg.individual_overlap_depths_um) if d is not None]
            if valid_depths:
                electrode_poly = None
                if junction.electrode_polygons:
                    electrode_poly = so.unary_union([sg.Polygon(p) for p in junction.electrode_polygons if len(p) >= 3])
                all_fully_inside = electrode_poly is not None and all(
                    sg.Polygon(nearby[k].points).difference(electrode_poly).area < 1e-4
                    for k, _d in valid_depths
                )
                k_min, depth_min = min(valid_depths, key=lambda kd: kd[1])
                if depth_min > MIN_SHOWN_LENGTH and not all_fully_inside:
                    s_min = nearby[k_min]
                    patch_poly = sg.Polygon(s_min.points)
                    overlap_region = patch_poly.intersection(electrode_poly) if electrode_poly is not None else None
                    if overlap_region is not None and not overlap_region.is_empty:
                        anchor = overlap_region.centroid
                        ax.plot([anchor.x], [anchor.y], marker="o", markersize=3, color=line_kw["color"], zorder=22)
                        lax, lay = anchor.x + 0.3, anchor.y + 0.3
                        ax.plot([anchor.x, lax], [anchor.y, lay], **line_kw)
                        add_text(lax + 0.15, lay, f"{depth_min:.3f}\u00b5m overlap", **text_kw)

        for finger in junction.fingers:
            plate = ji._find_finger_plate(junction, finger)
            if plate is None:
                continue
            # Use the plate's own stored width_um/length_um and the
            # finger's own axis_angle_deg directly, rather than
            # re-deriving axis/length from the raw polygon points: for a
            # square (or near-square) plate, point-extent detection is
            # ambiguous (no single longest edge), and returned 0.707
            # instead of the true 1.0 side length on a real 1.0x1.0
            # default plate.
            # Plates are always oriented in-line with their own finger,
            # so the finger's axis is reliable or every case, not just
            # non-square ones.
            plate_length = plate.length_um
            plate_width = plate.width_um
            cx = sum(p[0] for p in plate.points) / len(plate.points)
            cy = sum(p[1] for p in plate.points) / len(plate.points)
            pang = math.radians(finger.axis_angle_deg)
            p_hat = (math.cos(pang), math.sin(pang))
            pperp = (-p_hat[1], p_hat[0])
            hl = plate_length / 2.0
            end_a = (cx - p_hat[0]*hl, cy - p_hat[1]*hl)
            end_b = (cx + p_hat[0]*hl, cy + p_hat[1]*hl)
            offset = plate_width / 2.0 + 0.1  # right next to the plate's own edge, not far off it --
                                                # simplified now that plate_width is the real
                                                # dimension (the old *0.7 factor predates that fix
                                                # and was tuned around a much larger, wrong value)
            if plate_length > MIN_SHOWN_LENGTH:
                sx, sy = end_a[0]+pperp[0]*offset, end_a[1]+pperp[1]*offset
                ex, ey = end_b[0]+pperp[0]*offset, end_b[1]+pperp[1]*offset
                ax.plot([sx, ex], [sy, ey], **line_kw)
                add_text((sx+ex)/2.0, (sy+ey)/2.0, f"{plate_length:.2f}\u00b5m", **text_kw)
            if plate_width > MIN_SHOWN_LENGTH:
                hw = plate_width/2.0
                ax.plot([cx+pperp[0]*hw, cx-pperp[0]*hw], [cy+pperp[1]*hw, cy-pperp[1]*hw], **line_kw)
                add_text(cx+p_hat[0]*0.15, cy+p_hat[1]*0.15, f"{plate_width:.2f}\u00b5m", **text_kw)

    def _on_create_import_xlim_changed(self, ax):
        """Rescales the overlay's existing Text artists directly (no
        clear/redraw of anything else), so zooming visibly grows the
        labels without recursing back through xlim_changed -- a full
        redraw would call draw_imported_junction_preview, which resets
        xlim/ylim itself and would immediately re-fire this same
        callback.

        Also keeps the grid lines and the "5 um" scale bar in sync with
        the current zoom level, rather than staying at their original
        scale -- see imported_junction_view.refresh_grid_and_scale for
        that logic; this callback is the wiring point since it already
        fires on every xlim change, same as the overlay-text rescale
        below. Must run even when there's no overlay text to rescale."""
        changed = refresh_grid_and_scale(ax)
        if getattr(self, "_create_import_overlay_texts", None):
            fs = self._overlay_fontsize(ax)
            for t in self._create_import_overlay_texts:
                t.set_fontsize(fs)
            changed = True
        if changed:
            self.create_import_canvas.draw_idle()

    def _on_sim_xlim_changed(self, ax):
        """Simulate tab's own counterpart to _on_create_import_xlim_changed
        -- the Optimal Design view draws through the same draw_imported_
        junction_preview call and is exposed to the identical grid/scale-
        bar-stuck-under-zoom bug (see refresh_grid_and_scale's docstring).
        Post-Shadow Result / Simulated Design draw no grid or scale bar at
        all, so refresh_grid_and_scale is a no-op there (it detects the
        tracked artists are detached and bails out) rather than drawing
        one in where none belongs."""
        if refresh_grid_and_scale(ax):
            self.sim_canvas.draw_idle()

    def _create_import_view_kwargs(self):
        """Returns {"zoom_half_width_um": ..., "center_override": ...} to
        splat into draw_imported_junction_preview so an ordinary
        Create/Import redraw PRESERVES whatever view is already on
        screen, instead of re-fitting to the design's current bounding
        box on every single call.

        This matters because every call to draw_imported_junction_preview
        from either Create/Import redraw path
        (_update_create_import_preview, _redraw_create_import_overlay)
        would otherwise re-fit the view to junction.bounds() on EVERY
        redraw -- including every mouse-drag motion event, since
        _on_canvas_motion calls _update_preview() on each one. When the
        shape being dragged is itself part of what junction.bounds()
        measures (any custom shape, especially a "finger"-role one whose
        position drives from_design_parameters' plate/patch attachment),
        that's a real feedback loop: the shape moves -> the view re-fits
        around the new bounding box -> the pixel<->data transform changes
        -> the SAME screen pixel the cursor sits on now maps to a
        different data coordinate -> the shape "moves" again on the very
        next motion event even with zero real mouse movement -> the view
        re-fits again, wider -> divergence. Simulating a stationary
        mouse across repeated redraws grows the view span from ~11 to
        ~30 data units in 8 iterations alone, with no floor -- a real
        drag fires many motion events per second, reaching
        non-finite/astronomic coordinates fast enough to crash the
        underlying geometry library outright.

        This is why zoom_half_width_um/center_override are instead
        computed from the axes' OWN current xlim/ylim (read before
        draw_imported_junction_preview's ax.clear() erases them) rather
        than re-derived from the design's bounding box. Only
        self._create_import_force_fit (True on the very first draw, and
        set again by anything that makes the old view meaningless --
        Zoom to Fit, Reset View, File > New Junction, or switching which
        design is active) causes a real auto-fit; this method always
        consumes that flag (sets it back to False), so exactly one
        redraw gets a fresh fit and every one after it preserves that
        fit until something re-arms the flag. This also keeps editing a
        shape's fields from silently relocating or rescaling the view
        out from under a click that follows.

        Falls back to a fresh auto-fit (returns Nones) if the CURRENT
        view is somehow non-finite, inverted, or absurdly sized -- with
        the feedback loop above avoided this should never trigger, but a
        preserved view feeds every future redraw until something re-fits,
        so silently propagating garbage here would make it permanent
        instead of self-correcting."""
        force_fit = getattr(self, "_create_import_force_fit", True)
        zoom_half_width_um = None
        center_override = None
        if not force_fit and hasattr(self, "create_import_ax"):
            cur_xlim = self.create_import_ax.get_xlim()
            cur_ylim = self.create_import_ax.get_ylim()
            x_span = cur_xlim[1] - cur_xlim[0]
            y_span = cur_ylim[1] - cur_ylim[0]
            if (all(math.isfinite(v) for v in (cur_xlim[0], cur_xlim[1], cur_ylim[0], cur_ylim[1]))
                    and 1e-6 < x_span < 1e7 and 1e-6 < y_span < 1e7):
                center_override = ((cur_xlim[0] + cur_xlim[1]) / 2.0, (cur_ylim[0] + cur_ylim[1]) / 2.0)
                zoom_half_width_um = min(x_span, y_span) / 2.0
        self._create_import_force_fit = False
        return dict(zoom_half_width_um=zoom_half_width_um, center_override=center_override)

    def _update_create_import_preview(self, junction, report):
        """Called from the SAME place _update_preview already recomputes
        junction/report, so Create / Import always reflects the current design
        without needing its own separate recompute path."""
        if not hasattr(self, "create_import_ax"):
            return
        self._create_import_cached_junction = junction
        self._create_import_cached_report = report
        # Passes layer/selection highlighting through so it's reflected
        # on Create / Import's own canvas too -- see the matching
        # comment in _redraw_create_import_overlay.
        draw_imported_junction_preview(self.create_import_ax, junction, report,
                                       **self._create_import_view_kwargs(),
                                       selected_stable_id=self._selected_junction_id,
                                       layer_highlight=self._layer_highlight,
                                       shape_class_fn=self._effective_shape_class,
                                       show_badges=False, show_caption=False)
        self._draw_create_import_selected_custom_shape()
        self._draw_create_import_selected_finger_rotation_handle()
        self._draw_create_import_layer_rotation_ring()
        self._draw_create_import_marquee_selection()
        self.create_import_ax.callbacks.connect("xlim_changed", self._create_import_xlim_callback)  # reconnect --
                    # see the matching comment in _redraw_create_import_overlay for why this is needed here too
        self.create_import_ax.set_facecolor(BG_COLOR)
        for spine in self.create_import_ax.spines.values():
            spine.set_color(BORDER_COLOR)
        self._draw_pending_polygon(self.create_import_ax)  # See that
                                    # method's own docstring: this was missing here entirely, so a
                                    # polygon vertex was invisible while clicking on Create / Import
        self._draw_rulers(self.create_import_ax)  # AFTER the main redraw -- that call clears the axes first
        if hasattr(self, "show_measurements_toggle") and self.show_measurements_toggle.isChecked():
            self._draw_measurement_overlay(self.create_import_ax, junction, report)
        self.create_import_canvas.draw()
        if report is not None and hasattr(self, "create_import_measurements_tree"):
            self._populate_measurements_tree(report)
        if hasattr(self, "create_import_active_detail_label"):
            self.create_import_active_created_btn.setChecked(self._display_source == "parametric")
            self.create_import_active_imported_btn.setChecked(self._display_source == "imported")
            self.create_import_active_detail_label.setText(getattr(junction, "source_label", "") or "")

    def _draw_create_import_selected_custom_shape(self):
        """Draws the selected-custom-electrode-shape white outline onto
        Create / Import's own canvas -- electrode_scene's selection state
        is shared app-wide, so a shape selected anywhere should look
        selected here too."""
        if not hasattr(self, "create_import_ax"):
            return
        selected_custom = self.electrode_scene.selected()
        if selected_custom is None:
            return
        from matplotlib.patches import Polygon as MplPolygon
        self.create_import_ax.add_patch(MplPolygon(selected_custom.to_world_polygon(), closed=True,
                                              facecolor="none", edgecolor=OUTLINE_COLOR, linewidth=2.6, zorder=6))
        # Every defining corner or node of the shape is alterable after
        # it's created, by re-selecting the shape and dragging one of
        # its nodes: a
        # small filled marker at each of _shape_node_handles' own points
        # -- the actual, exact hit-targets _hit_test_shape_node checks
        # against, not a decorative approximation -- so the user can see
        # exactly where to click-drag to reshape this shape. A slightly
        # larger, hollow ring under the currently-grabbed node (if any)
        # gives a clear "you're dragging THIS one" cue mid-drag.
        for i, (hx, hy) in enumerate(self._shape_node_handles(selected_custom)):
            is_active = (self._dragging_node_shape_id == selected_custom.id and self._dragging_node_index == i)
            self.create_import_ax.plot([hx], [hy], marker="s", markersize=7.5 if is_active else 6.0,
                                       markerfacecolor=WARN_COLOR if is_active else OUTLINE_COLOR,
                                       markeredgecolor=BG_COLOR, markeredgewidth=1.0, zorder=7)
        self._draw_rotation_handle(self.create_import_ax, *self._shape_rotation_handle_points(selected_custom)[1:],
                                    is_active=(self._rotating_shape_id == selected_custom.id))

    def _draw_create_import_marquee_selection(self):
        """Outlines every member of the current marquee/
        rubber-band batch (self._marquee_selection) so the user can
        actually SEE what a completed drag selected, not just infer it
        from the Nudge & Scale card's status line. Reuses the exact same
        outline color/style _draw_create_import_selected_custom_shape
        already uses for a single selected shape (a thinner line, since a
        batch can contain many overlapping/adjacent members at once and a
        thick outline on every one would read as clutter rather than a
        clean 'these are selected' cue)."""
        if not hasattr(self, "create_import_ax") or self._marquee_selection is None:
            return
        from matplotlib.patches import Polygon as MplPolygon
        scene_shapes, fingers, shapes = self._marquee_live_members()
        for shp in scene_shapes:
            self.create_import_ax.add_patch(MplPolygon(shp.to_world_polygon(), closed=True,
                                                  facecolor="none", edgecolor=OUTLINE_COLOR,
                                                  linewidth=1.6, linestyle=(0, (3, 2)), zorder=6))
        for f in fingers:
            self.create_import_ax.add_patch(MplPolygon(f.points, closed=True,
                                                  facecolor="none", edgecolor=OUTLINE_COLOR,
                                                  linewidth=1.6, linestyle=(0, (3, 2)), zorder=6))
        for s in shapes:
            self.create_import_ax.add_patch(MplPolygon(s.points, closed=True,
                                                  facecolor="none", edgecolor=OUTLINE_COLOR,
                                                  linewidth=1.6, linestyle=(0, (3, 2)), zorder=6))

    def _draw_rotation_handle(self, ax, line_start, handle, is_active: bool):
        """A small, elegant rotation handle -- a line with a tiny circle
        that lets the user rotate a shape by dragging the node attached
        to it, kept small and close to the shape rather than extending
        far away from it. Shared drawing
        code for a rotation handle, used for both a selected custom
        electrode_scene shape and a selected real junction finger --
        a short, thin connecting line from the shape's own boundary
        (line_start) out to a small, hollow circle (handle), deliberately
        smaller and visually distinct (a circle, not the square used for
        a resize node) from every other on-canvas handle so it always
        reads as "this one rotates, the square ones resize." Turns a
        warm highlight color while actively being dragged, exactly
        matching the resize-node convention right above."""
        color = WARN_COLOR if is_active else OUTLINE_COLOR
        ax.plot([line_start[0], handle[0]], [line_start[1], handle[1]],
                color=color, linewidth=1.0, zorder=7, solid_capstyle="round")
        ax.plot([handle[0]], [handle[1]], marker="o", markersize=6.5 if is_active else 5.0,
                markerfacecolor=BG_COLOR, markeredgecolor=color, markeredgewidth=1.4, zorder=8)

    def _draw_create_import_selected_finger_rotation_handle(self):
        """The junction-finger analog of _draw_create_import_selected_
        custom_shape's own rotation handle -- only a real, currently-
        selected FINGER gets one (see _hit_test_finger_rotation_handle's
        own docstring for why patches/plates don't: they have no
        independent angle property in Shape Properties for a drag
        gesture to change). Drawn from the same shared selection state
        (self._selected_junction_id) every other Create/Import
        selection highlight already reads, so it appears/disappears in
        lockstep with the rest of the app's own selection feedback."""
        if not hasattr(self, "create_import_ax") or self.electrode_scene.selected() is not None:
            return  # a selected custom shape always takes priority, matching _current_shape_role_and_object
        if not self._selected_junction_id:
            return
        finger, _shape = self._find_active_junction_shape(self._selected_junction_id)
        if finger is None:
            return
        line_start, handle = self._finger_rotation_handle_points(finger)
        self._draw_rotation_handle(self.create_import_ax, line_start, handle,
                                    is_active=(self._rotating_finger_id == finger.stable_id))

    def _draw_create_import_layer_rotation_ring(self):
        """The batch-rotate-by-layer analog of
        _draw_create_import_selected_finger_rotation_handle, drawn
        whenever a Layer is highlighted (self._layer_highlight) with at
        least one ROTATABLE member in it (see
        _layer_has_rotatable_members), regardless of what individual
        shape (if any) is currently selected -- highlighting a Layer is
        itself already the deliberate "act on this whole group" choice,
        so unlike the single-shape/finger handles above it does not
        defer to an individual selection at all (matching the existing
        whole-layer canvas drag, which already overrides a
        plain single-shape drag the moment a grabbed shape belongs to
        the highlighted layer).

        Replaces an earlier
        single far-out handle-on-a-stick (which could land outside the
        visible viewport for a spread-out design, and was a single
        small point to aim for) with a thin dashed ring hugging just
        outside the group's own silhouette, plus a tiny crosshair
        marking the pivot -- the WHOLE ring is a valid grab target
        (_hit_test_layer_rotation_ring), giving the user a full rotation
        circle around the junction to click on."""
        if not hasattr(self, "create_import_ax"):
            return
        category = self._layer_highlight
        if not category or not self._layer_has_rotatable_members(category):
            return
        (ox, oy), radius = self._layer_rotation_ring_geometry(category)
        is_active = (self._rotating_layer_category == category)
        color = WARN_COLOR if is_active else OUTLINE_COLOR
        theta = np.linspace(0.0, 2.0 * np.pi, 96)
        self.create_import_ax.plot(ox + radius * np.cos(theta), oy + radius * np.sin(theta),
                                   color=color, linewidth=1.3 if is_active else 1.0,
                                   linestyle=(0, (4, 3)), zorder=7)
        cross = self._hit_test_tolerance() * 0.6
        self.create_import_ax.plot([ox - cross, ox + cross], [oy, oy], color=color, linewidth=1.0, zorder=7)
        self.create_import_ax.plot([ox, ox], [oy - cross, oy + cross], color=color, linewidth=1.0, zorder=7)

    def _sim_card(self, title: str, accent: str, collapsed: bool = False) -> tuple:
        """One 'card' panel used across EVERY tab's side panels (Simulate
        Design, Recipe, Deposition Slideshow, Measure Resistance,
        Interpret Results, Settings -- ~25 call sites in all): a
        rounded, subtly-bordered container with an accent-colored,
        CLICKABLE title bar that collapses/expands the content, so a
        column can stay compact by default instead of every card
        permanently consuming vertical space. Returns (card_widget,
        content_layout) -- caller populates content_layout with
        whatever that card shows.

        Every card here shares a common, quiet visual treatment.
        Deliberately calmer than the Front Page's animated, hover-driven
        QuantumCard -- these cards sit on screen constantly while the
        user is actually working, not as occasional navigation
        shortcuts, so nothing here moves: no timers, no hover state.
        Three static touches, applied consistently everywhere this
        function is called:

        1. The frame's background/border are registered through
           self._themed() like every other themed widget (so all ~25 of
           these cards respect the light/dark theme toggle), with a very
           faint top-to-bottom gradient (barely perceptible -- the same
           restrained "sheen" language as the toolbar buttons, just
           static here instead of hover-driven) instead of a flat fill.
        2. The collapse arrow is a small qtawesome chevron tinted in the
           card's own accent color instead of the native OS arrow glyph
           -- consistent with every other icon in this app being a qta
           glyph. The accent itself stays a fixed per-card color (a
           deliberate rainbow code across cards, e.g. warnings are
           reds/oranges, previews are blues) rather than a theme
           constant.
        3. A small static accent-colored dot at the right end of the
           title row -- a quiet nod to the pad/via marks used throughout
           the rest of the app's "quantum" language, without animating
           anything.
        """
        card = QWidget()
        card.setObjectName("simCard")
        self._themed(card, lambda: (
            f"QWidget#simCard {{ "
            f"background: qlineargradient(x1:0, y1:0, x2:0, y2:1, "
            f"stop:0 {QColor(PANEL_COLOR).lighter(114).name()}, stop:1 {PANEL_COLOR}); "
            f"border: 1px solid {BORDER_COLOR}; border-radius: 10px; }}"
        ))
        outer = QVBoxLayout(card)
        # Compact margins: every card in the left panel pays this margin
        # on all four sides, and with 5+ cards stacked (Process
        # Parameters, Wafer Orientation Preview, Deposition Angles,
        # Mill/Oxidation Placement) a larger margin would add up to a
        # meaningful chunk of excessive scrolling before ever reaching
        # the chamber side-view.
        outer.setContentsMargins(10, 8, 10, 10)
        outer.setSpacing(6)
        title_row = QHBoxLayout()
        title_btn = QToolButton()
        icon_down = qta.icon("fa5s.chevron-down", color=accent)
        icon_right = qta.icon("fa5s.chevron-right", color=accent)
        title_btn.setIcon(icon_down if not collapsed else icon_right)
        title_btn.setIconSize(QSize(9, 9))
        title_btn.setStyleSheet("border: none; background: transparent;")
        title_btn.setCursor(Qt.PointingHandCursor)
        title_row.addWidget(title_btn)
        bar = QLabel()
        bar.setFixedWidth(4)
        bar.setStyleSheet(f"background-color: {accent}; border-radius: 2px;")
        title_row.addWidget(bar)
        title_label = QLabel(title.upper())
        title_label.setStyleSheet(f"color: {accent}; font-weight: bold; font-size: 9pt; "
                                  f"letter-spacing: 1px; padding-left: 6px;")
        # A long title (e.g. "PROCESS PARAMETERS (DEPOSITION ORDER &
        # RESIST STACK)") needs word-wrap: without it, the one-line
        # sizeHint would force the ENTIRE card -- and the whole narrow
        # sidebar panel it sits in (Simulate Design's angle_scroll,
        # min/max width 280-360px) -- wider than the panel's fixed max
        # width. Since that panel's horizontal scrollbar is disabled,
        # the overflow would be silently clipped: titles would read
        # "PROCESS PARAMETERS (D", "WAFER ORIENTATION PRE", etc.
        # Word-wrapping the title lets it wrap onto a second line
        # instead of demanding extra width.
        title_label.setWordWrap(True)
        title_row.addWidget(title_label, stretch=1)
        dot = QLabel()
        dot.setFixedSize(6, 6)
        dot.setStyleSheet(f"background-color: {accent}; border-radius: 3px;")
        title_row.addWidget(dot)
        outer.addLayout(title_row)
        content_widget = QWidget()
        content = QVBoxLayout(content_widget)
        content.setContentsMargins(0, 0, 0, 0)
        outer.addWidget(content_widget)
        content_widget.setVisible(not collapsed)

        def _toggle(checked=None):
            vis = not content_widget.isVisible()
            content_widget.setVisible(vis)
            title_btn.setIcon(icon_down if vis else icon_right)

        title_btn.clicked.connect(_toggle)
        return card, content

    def _toolbar_section(self, title: str, accent: str) -> tuple:
        """A lightweight, non-collapsible section
        divider used ONLY inside the merged Create/Import Toolbar card
        (see _build_docks) -- Layers / Shape Properties / Batch Edit
        Layer / Nudge && Scale each get one of these instead of their
        own separate _sim_card. Returns (section_widget, content_layout)
        with the exact same (widget, layout) shape _sim_card returns, so
        every pre-existing content-building call site below each one
        (xxx_content.addWidget/addLayout(...)) works completely
        unchanged -- only the chrome around it is thinner: no card
        border/background/gradient, no collapse chevron, no accent dot,
        far tighter margins. Never collapsible on purpose -- these were
        already reduced to "whichever one applies is just shown", so an
        extra collapse click would undo the whole point of merging them
        (fewer clicks to get from selecting something to editing it)."""
        section = QWidget()
        section_layout = QVBoxLayout(section)
        section_layout.setContentsMargins(0, 2, 0, 2)
        section_layout.setSpacing(4)
        header_row = QHBoxLayout()
        header_row.setContentsMargins(0, 0, 0, 0)
        header_row.setSpacing(6)
        bar = QLabel()
        bar.setFixedWidth(3)
        bar.setFixedHeight(11)
        bar.setStyleSheet(f"background-color: {accent}; border-radius: 1px;")
        header_row.addWidget(bar)
        label = QLabel(title.upper())
        label.setStyleSheet(f"color: {accent}; font-weight: bold; font-size: 8pt; letter-spacing: 1px;")
        header_row.addWidget(label)
        header_row.addStretch()
        section_layout.addLayout(header_row)
        return section, section_layout

    def _toolbar_separator(self) -> QFrame:
        """A thin horizontal rule between sections of the merged Toolbar
        card -- same QFrame.HLine pattern already used
        elsewhere in this file (e.g. the Predicted Recipe Sequence's
        insert-step row), just themed to the shared border color so it
        reads as a quiet divider, not a heavy line."""
        line = QFrame()
        line.setFrameShape(QFrame.HLine)
        self._themed(line, lambda: f"color: {BORDER_COLOR};")
        return line

    def _build_simulate_tab(self) -> QWidget:
        """Simulate Design -- reads whichever design is currently ACTIVE
        (self._display_source, set from Create / Import's prominent
        toggle -- deliberately not a second, separate selection) and
        shows its full warning/recommendation picture (compute_
        recommended_angles, explain_finger_angle_choice), given a
        dedicated, modern-styled home instead of being mixed in with
        shape-creation tools."""
        outer = QWidget()
        self._themed(outer, lambda: f"background-color: {BG_COLOR};")
        layout = QVBoxLayout(outer)
        layout.setContentsMargins(16, 16, 16, 16)
        layout.setSpacing(12)

        header_row = QHBoxLayout()
        header = QLabel("SIMULATE DESIGN")
        self._themed(header, lambda: f"color: {TEXT_COLOR}; font-weight: bold; font-size: 14pt; letter-spacing: 1px;")
        header_row.addWidget(header)
        header_row.addStretch()
        self.sim_active_label = QLabel("")
        self._themed(self.sim_active_label, lambda: f"color: {ACCENT_COLOR}; font-size: 9pt; background-color: {PANEL_COLOR}; "
            f"border-radius: 6px; padding: 6px 12px;")
        self.sim_active_label.setMaximumHeight(28)
        self.sim_active_label.setAlignment(Qt.AlignCenter)
        self.sim_active_label.setSizePolicy(QSizePolicy.Maximum, QSizePolicy.Fixed)
        self.sim_active_label.setMinimumWidth(0)  # A contributor to a window-growth
                                    # glitch: this label shows the loaded design's filename, which
                                    # can be very long (measured one real case at 317px), and even
                                    # with a "Maximum" horizontal policy, Qt still uses the label's
                                    # full-text width as its OWN minimum unless told otherwise --
                                    # meaning the severity of the growth bug depended on WHICH file
                                    # happened to be loaded. Explicit minimum width of 0 lets the
                                    # layout compress it (eliding truncates the text instead of
                                    # forcing extra window width) rather than always reserving room
                                    # for the longest filename ever seen.
        header_row.addWidget(self.sim_active_label)
        layout.addLayout(header_row, stretch=0)

        def _group_label(text):
            lbl = QLabel(text)
            self._themed(lbl, lambda: f"color: {DIM_COLOR}; font-size: 7.5pt; letter-spacing: 1px;")
            lbl.setAlignment(Qt.AlignVCenter)
            return lbl

        # Controls, grouped by PURPOSE with an inline label ahead of each
        # cluster, left-to-right in the order a user actually decides
        # them: what to show -> which view -> commit that view by
        # running -- one single row (avoids a nested-layout spacing bug
        # from an earlier version where labels visually detached from
        # their buttons with a large gap).
        # For consistency with Create / Import's own
        # style, where every tool lives in the thin toolbar strip at
        # the very top of the window, not inside the tab's own content
        # area. All the buttons below move into a dedicated QToolBar
        # for this tab (shown only while it's active), rather than
        # living in QHBoxLayouts inside the canvas area -- same
        # widgets, same names, same connections, just relocated.
        sim_toolbar = QToolBar("Simulate Design Tools")
        sim_toolbar.setMovable(False)
        self._themed(sim_toolbar, lambda: f"QToolBar {{ background-color: {PANEL_COLOR}; border: none; spacing: 6px; padding: 4px 8px; }}")
        self.addToolBar(sim_toolbar)
        self.sim_toolbar = sim_toolbar  # hidden/shown alongside main_toolbar in _on_nav_changed

        # Each toolbar control is visually distinct so it's clear at a
        # glance when it's on or off: VIEW is a QuantumSegmentButton rail
        # (one exclusive choice, one shared accent, a growing underline
        # says which is active); MEASURE/DISPLAY are QuantumPillButton
        # (each its own accent, animated and theme-reactive); the two
        # Run buttons get the full QuantumActionButton treatment,
        # matching the weight of the Measurements On/Off toggle, since
        # these are the tab's two most important buttons. Every
        # attribute name, signal connection, and enabled/disabled call
        # site below reads the same widgets as any other button here --
        # only the widget class and paint job differ.
        sim_toolbar.addWidget(_group_label("VIEW:"))
        self.sim_view_optimal_btn = QuantumSegmentButton("Optimal Design", "#7fb8ff", "left")
        self.sim_view_simulated_btn = QuantumSegmentButton("Simulated Design", "#7fb8ff", "mid")
        self.sim_view_postshadow_btn = QuantumSegmentButton("Post-Shadow Result", "#7fb8ff", "right")
        sim_view_group = QWidget()
        sim_view_group_layout = QHBoxLayout(sim_view_group)
        sim_view_group_layout.setContentsMargins(0, 0, 0, 0)
        sim_view_group_layout.setSpacing(0)
        for btn in (self.sim_view_optimal_btn, self.sim_view_simulated_btn, self.sim_view_postshadow_btn):
            sim_view_group_layout.addWidget(btn)
        self.sim_view_optimal_btn.setChecked(True)
        self.sim_view_optimal_btn.clicked.connect(lambda: self._set_sim_view_mode("optimal"))
        self.sim_view_simulated_btn.clicked.connect(lambda: self._set_sim_view_mode("simulated"))
        self.sim_view_postshadow_btn.clicked.connect(lambda: self._set_sim_view_mode("postshadow"))
        sim_toolbar.addWidget(sim_view_group)

        sim_toolbar.addSeparator()
        sim_toolbar.addWidget(_group_label("MEASURE:"))
        self.sim_ruler_toggle = QuantumPillButton("Ruler", accent="#ffd166", icon_name="fa5s.ruler", checkable=True)
        sim_toolbar.addWidget(self.sim_ruler_toggle)
        sim_clear_rulers_btn = QuantumPillButton("Clear Rulers", accent="#ff8f6b", icon_name="fa5s.eraser")
        sim_clear_rulers_btn.clicked.connect(self._clear_sim_rulers)
        sim_toolbar.addWidget(sim_clear_rulers_btn)

        sim_toolbar.addSeparator()
        sim_toolbar.addWidget(_group_label("DISPLAY:"))
        # Once shadow simulation is
        # running, the angle-diagnostic layer (Warning markers, theta
        # labels) drawn underneath the shadow bands can get visually
        # busy -- this lets the user hide that layer to focus purely on
        # the shadow result, without losing it entirely (still there
        # for Optimal Design view once the diagnostic has run).
        self.sim_show_diagnostics_toggle = QuantumPillButton(
            "Show Angle Diagnostics", accent="#7fb8ff", icon_name="fa5s.eye", checkable=True)
        self.sim_show_diagnostics_toggle.setChecked(True)
        self.sim_show_diagnostics_toggle.toggled.connect(lambda _c: self._update_preview())
        sim_toolbar.addWidget(self.sim_show_diagnostics_toggle)

        # The angle/resist-stack setup panel
        # needs to be visible ALONGSIDE the canvas, not on a different
        # tab -- switching an angle slightly while unable to see the
        # design or its shadow simulation defeats the purpose. This
        # toggle shows/hides a panel docked to the LEFT of the canvas,
        # within this same tab.
        self.sim_angle_panel_toggle = QuantumPillButton(
            "Angle Setup", accent="#ffb454", icon_name="fa5s.cog", checkable=True)
        self.sim_angle_panel_toggle.setChecked(True)  # This panel
                                    # (resist stack, active alpha, recommendations, the per-feature
                                    # angle tree) is crucial to see by default, not a "slight open
                                    # space" that has to be remembered and turned on every visit -- still
                                    # fully toggleable off via this same button once it's not needed.
        self.sim_angle_panel_toggle.toggled.connect(self._on_toggle_angle_panel)
        sim_toolbar.addWidget(self.sim_angle_panel_toggle)

        # A matching toggle for the RIGHT
        # side (Shadowing Risk Check / Angle Warnings / Shadowing
        # Warnings) -- same on-by-default, user-can-turn-it-off pattern
        # as Angle Setup above, just for the other panel.
        self.sim_right_panel_toggle = QuantumPillButton(
            "Warnings && Risk Check", accent="#ff8f6b", icon_name="fa5s.exclamation-triangle", checkable=True)
        self.sim_right_panel_toggle.setChecked(True)
        self.sim_right_panel_toggle.toggled.connect(self._on_toggle_sim_right_panel)
        sim_toolbar.addWidget(self.sim_right_panel_toggle)

        spacer = QWidget()
        spacer.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Preferred)
        sim_toolbar.addWidget(spacer)

        # Run Angle Diagnostic belongs right next to Run
        # Shadow Simulation in the toolbar, not buried in the left
        # panel -- both are the two-step workflow's primary actions and
        # should sit together where they're always visible regardless
        # of whether the angle panel itself is toggled open.
        #
        # As separate top-level toolbar items after an Expanding spacer,
        # a narrower window would force this toolbar into overflow (the
        # ">>" chevron), and Qt's own overflow menu could then show Run
        # Angle Diagnostic inline while dropping Run Shadow Simulation
        # into that popup -- or vice versa -- putting the two on opposite
        # sides of the screen from each other.
        # Wrapping them in ONE container widget (stacked vertically,
        # same pattern as sim_view_group/mode_pill_group elsewhere in
        # this file) makes the toolbar treat them as a single atomic
        # item: they now either both show inline or both drop into the
        # overflow popup together, always adjacent -- and stacking
        # instead of sitting side by side also roughly halves this
        # pair's own contribution to the toolbar's total width, making
        # the overflow case itself less likely to begin with. Matched
        # fixed widths keep the stack visually tidy instead of jagged.
        self.sim_run_diagnostic_button = QuantumActionButton("\u25b6  Run Angle Diagnostic", accent="#7fc8e6")
        self.sim_run_diagnostic_button.clicked.connect(self._on_run_angle_diagnostic_clicked)

        self.sim_run_button = QuantumActionButton("\u25b6  Run Shadow Simulation", accent="#8fd694")
        self.sim_run_button.clicked.connect(self._on_run_simulation_clicked)
        # A two-step, guided workflow --
        # angle diagnostics first (recommendations, warnings, per-
        # feature verdicts), THEN shadow simulation, not both bundled
        # into one click. Disabled until the diagnostic step has run at
        # least once.
        self.sim_run_button.setEnabled(False)

        run_buttons_group = QWidget()
        run_buttons_layout = QVBoxLayout(run_buttons_group)
        run_buttons_layout.setContentsMargins(0, 0, 0, 0)
        run_buttons_layout.setSpacing(3)
        stacked_width = max(self.sim_run_diagnostic_button.sizeHint().width(),
                             self.sim_run_button.sizeHint().width())
        self.sim_run_diagnostic_button.setFixedWidth(stacked_width)
        self.sim_run_button.setFixedWidth(stacked_width)
        run_buttons_layout.addWidget(self.sim_run_diagnostic_button)
        run_buttons_layout.addWidget(self.sim_run_button)
        sim_toolbar.addWidget(run_buttons_group)
        self.sim_run_buttons_group = run_buttons_group

        splitter = QSplitter(Qt.Horizontal)
        layout.addWidget(splitter, stretch=1)

        # Everything that feeds the
        # shadow calculation -- resist stack, electrode height, active
        # alpha, the recommendation summary, and the editable per-
        # feature angle tree with add/remove layers -- lives in a
        # panel docked to the LEFT of the canvas, toggled via the
        # "Angle Setup" button in the toolbar above. Hidden by default
        # (a "slight open space" toggled on when needed, not an
        # always-visible third column crowding the canvas).
        angle_scroll = QScrollArea()
        angle_scroll.setWidgetResizable(True)
        # This panel is 320-440px wide (still a compact side panel, not
        # a third main column) with its own content -- long card titles,
        # and especially the Wafer Orientation Preview's chamber diagram
        # (see sim_chamber_preview's figsize below) -- sized to fit
        # inside it. The horizontal scrollbar stays fixed AlwaysOff:
        # every real overflow source (unwrapped card titles, an
        # oversized chamber-preview figure, an unwrapped orientation
        # readout) is fixed at the source instead (word-wrap + a
        # column-sized figsize, see test_sim_tab_card_widths.py) rather
        # than papered over with an AsNeeded scrollbar. A regression here
        # shows as silent clipping again rather than a scrollbar
        # appearing, which is exactly why that test checks actual
        # content width against the viewport, not just the policy enum.
        angle_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        angle_panel = QWidget()
        angle_layout = QVBoxLayout(angle_panel)
        angle_layout.setSpacing(8)  # Tightened gap between stacked cards, same
                                    # "reduce density" goal as _sim_card's own
                                    # tightened margins above.
        angle_scroll.setWidget(angle_panel)
        angle_scroll.setMinimumWidth(360)
        angle_scroll.setMaximumWidth(460)
        angle_scroll.setVisible(True)  # visible by default -- see sim_angle_panel_toggle above
        self.sim_angle_panel = angle_scroll

        # Deposition Order and Resist
        # Stack & Electrode are MERGED into one "Process Parameters"
        # card -- both are process parameters the user must specify for
        # this design, so they belong together rather than as two
        # separate always-visible cards. Deposition Order itself was
        # already relocated here from Create / Import in an earlier pass (which
        # finger deposits first affects the self-shadowing check and the
        # shadow calculation generally, making it a simulation-setup
        # concern, not a geometry-creation one) -- reuses the exact same
        # self-contained panel/handler (_build_deposition_order_panel,
        # _on_deposit_first_changed), just folded into the same card as
        # the resist stack instead of its own separate one.
        # Expanded by default: everything should show up evenly and
        # fully right from the start, with all of the info, the chamber
        # model, and the predicted steps/angles visible just by using
        # the up/down scrollbar -- no card should need an extra click to
        # reveal its content, vertical scrolling alone is enough. Hiding
        # the "Deposition Angles (per feature)" card below (see its own
        # note further down) freed enough vertical room for this one to
        # stay expanded without crowding the chamber preview; still one
        # click away to collapse manually if the user wants to.
        params_card, params_content = self._sim_card("Process Parameters (Deposition Order & Resist Stack)",
                                                       "#e0a875", collapsed=False)
        order_label = QLabel("Deposition Order")
        self._themed(order_label, lambda: f"color: {TEXT_COLOR}; font-weight: bold; font-size: 9pt;")
        params_content.addWidget(order_label)
        params_content.addWidget(self._build_deposition_order_panel())

        # Generalized -- this bilayer is not fixed to any one specific
        # resist pairing or thickness. Field NAMES stay pmma_edit/
        # pmgi_edit (every shadow-simulation call site downstream reads
        # these two attribute names extensively), but the visible label
        # and the fields' initial values are generalized: see
        # _build_settings_resist_stack_section for where Settings' own
        # "Apply to Simulate Design" button can push a newly configured
        # stack in here directly.
        stack_label = QLabel("Resist Stack & Electrode")
        self._themed(stack_label, lambda: f"color: {TEXT_COLOR}; font-weight: bold; font-size: 9pt; padding-top: 10px;")
        params_content.addWidget(stack_label)
        stack_form = QFormLayout()
        # No values are prefilled for these parameters to start, so
        # nothing here looks like a real recommended number until the
        # user (or Settings' "Apply to Simulate Design tab") actually
        # sets one. The row LABELS read whatever resist name is
        # currently typed into Settings > Resist Stack & Calculator
        # (settings_top_name_edit/settings_bottom_name_edit), refreshed
        # live (see _refresh_sim_resist_labels, wired to those fields'
        # textChanged) so renaming a resist in Settings updates this
        # card immediately, matching whatever bilayer is actually in
        # use. Settings is built after this tab (see
        # _refresh_sim_resist_labels' own docstring), so the initial
        # text falls back to the generic label until that happens.
        self.pmma_edit = QLineEdit("")
        self.pmma_edit.setPlaceholderText("nm")
        self.sim_top_resist_label = QLabel(self._sim_resist_label_text("top"))
        stack_form.addRow(self.sim_top_resist_label, self.pmma_edit)
        self.pmgi_edit = QLineEdit("")
        self.pmgi_edit.setPlaceholderText("nm")
        self.sim_bottom_resist_label = QLabel(self._sim_resist_label_text("bottom"))
        stack_form.addRow(self.sim_bottom_resist_label, self.pmgi_edit)
        self.es_height_edit = QLineEdit("300")  # Nb electrode layer height, a
                                    # realistic default for a typical process (not
                                    # an arbitrary guess) -- was 200 as a generic placeholder
        stack_form.addRow("Electrode height (nm):", self.es_height_edit)
        self.sim_alpha_override_edit = QLineEdit("30")
        self.sim_alpha_override_edit.textChanged.connect(self._on_sim_override_edited)
        self.sim_alpha_override_edit.textChanged.connect(self._on_sim_active_alpha_changed)
        stack_form.addRow("Active alpha (deg):", self.sim_alpha_override_edit)
        params_content.addLayout(stack_form)
        self.es_height_edit.textChanged.connect(self._on_resist_stack_changed)
        self.pmma_edit.textChanged.connect(self._on_resist_stack_changed)
        self.pmgi_edit.textChanged.connect(self._on_resist_stack_changed)
        angle_layout.addWidget(params_card)

        # Wafer orientation preview -- see the chamber orientation for a
        # candidate alpha/theta pair before committing to it in the
        # angle tree below. This is a live-tester, not a step-committer:
        # in the New pipeline, recipe steps are auto-generated from the
        # simulation on the Recipe tab, not hand-committed the way the retired
        # Live Angle Tester worked -- so there is no "add as step" button
        # here, just a way to actually see the wafer before deciding on
        # an angle. The widget owns its own alpha/theta/reference fields
        # (freely editable, same as the retired Live Angle Tester) --
        # Active alpha above only SEEDS the widget's alpha field when it
        # changes, it doesn't lock it, so you can freely explore a
        # different tilt here without changing the actual simulation.
        orient_card, orient_content = self._sim_card("Wafer Orientation Preview", "#7fb8ff", collapsed=False)
        orient_note = QLabel("Type any alpha/theta to preview a different tilt before committing.")
        orient_note.setWordWrap(True)
        self._themed(orient_note, lambda: f"color: {DIM_COLOR}; font-size: 8pt;")
        orient_content.addWidget(orient_note)
        # The chamber model figure must fit inside this ~300-420px-wide
        # sidebar card without being clipped: a figsize of (5.0, 1.8) is
        # 500px wide @100dpi, too wide for the card since the panel's
        # horizontal scrollbar is disabled (see angle_scroll above), so
        # the figsize below is narrowed to fit the card with room to
        # spare.
        self.sim_chamber_preview = _ChamberPreviewWidget(figsize=(3.0, 1.3))
        orient_content.addWidget(self.sim_chamber_preview)
        angle_layout.addWidget(orient_card)

        # "Recommended Deposition Angles" and "Deposition Angles (per
        # feature)" are consolidated into ONE card, rather than kept as
        # two cards showing overlapping information (the same
        # finger/patch recommendation, once as prose, once as an
        # editable tree): the prose recommendation stays as a short
        # readout at the top (self.sim_recommendations_label -- name
        # kept, since _populate_sim_recommendations_tree and other call
        # sites already reference it directly), and the editable tree
        # follows immediately below it in the SAME card, so there is
        # exactly one place to look for "what angles is this design
        # using."
        tree_card, tree_content = self._sim_card("Deposition Angles (per feature)", "#8fd694", collapsed=False)
        self.sim_recommendations_label = QLabel("No junction to recommend angles for yet.")
        self.sim_recommendations_label.setWordWrap(True)
        self._themed(self.sim_recommendations_label, lambda: f"color: {TEXT_COLOR}; font-size: 9pt;")
        tree_content.addWidget(self.sim_recommendations_label)
        tree_note = QLabel("Pre-filled with the recommendation above; edit as needed.")
        tree_note.setWordWrap(True)
        self._themed(tree_note, lambda: f"color: {DIM_COLOR}; font-size: 8pt;")
        tree_content.addWidget(tree_note)
        self.sim_angles_tree = QTreeWidget()
        self.sim_angles_tree.setHeaderLabels(["Feature", "Mode / Angle / Verdict"])
        self.sim_angles_tree.setColumnWidth(0, 85)
        self.sim_angles_tree.setWordWrap(True)
        self.sim_angles_tree.header().setSectionResizeMode(0, QHeaderView.Fixed)
        self.sim_angles_tree.header().setSectionResizeMode(1, QHeaderView.Stretch)
        self.sim_angles_tree.setStyleSheet("QTreeWidget { font-size: 8pt; }")
        self.sim_angles_tree.setMinimumHeight(220)  # This card also carries the
                                    # merged recommendation readout above it, so
                                    # its minimum height keeps the card's total
                                    # height in check.
        tree_content.addWidget(self.sim_angles_tree)
        self._sim_angle_state = {}  # feature_key -> {"layer_edits"/"check"+"edit", "verdict_item", ...}
        angle_layout.addWidget(tree_card)
        # This card's tree duplicates information already shown, with
        # full context, by the "Predicted Recipe Sequence" card below:
        # every pass -- deposition, mill, and oxidation -- with its own
        # editable angle, plus the mill/oxidation rows and reordering
        # this tree lacks. It's hidden rather than removed/deleted: the
        # card stays a real child of angle_layout so Qt's parent-child
        # ownership keeps self.sim_angles_tree / self.sim_recommendations_
        # label alive, and every existing update path that still targets
        # them by attribute (_rebuild_sim_angles_tree, _update_sim_angle_
        # verdicts, _refresh_recipe_features, etc.) keeps running in the
        # background to seed self._sim_finger_layers /
        # self._sim_patch_layers / self._recipe_features -- the same
        # hide-not-delete pattern _on_toggle_angle_panel uses for
        # self.sim_angle_panel. A hidden widget takes zero space in its
        # parent layout, so no gap is left behind.
        tree_card.setVisible(False)

        # The mill/deposition/oxidation PLACEMENT prediction lives here,
        # live, alongside the deposition angle and thickness predictions
        # -- rather than only being computed once the user clicks
        # "Generate Recipe from Simulation" on the Recipe tab -- so
        # oxidation and milling step placement is predicted at the same
        # time. self._recipe_features (kept up to date by
        # _refresh_recipe_features, called from _update_sim_angle_
        # verdicts -- i.e. after every layer/patch add/remove/edit) is
        # the single source of truth the Recipe tab's "Generate Recipe"
        # just reads, already decided, rather than recomputing. With the
        # "Deposition Angles (per feature)" card above hidden (see
        # comment above), this card is the sole place that shows angles
        # and predicted steps together, hence its name "Predicted Recipe
        # Sequence" rather than "Mill / Oxidation Placement".
        seq_card, seq_content = self._sim_card("Predicted Recipe Sequence", "#ff8f6b", collapsed=False)
        seq_note = QLabel("Every deposition, mill, and oxidation pass predicted from this design, in order, "
                           "with its angle -- reorder, delete, or hand-override any pass here before generating a recipe.")
        seq_note.setWordWrap(True)
        self._themed(seq_note, lambda: f"color: {DIM_COLOR}; font-size: 8pt;")
        seq_content.addWidget(seq_note)
        self.sim_feature_sequence_container = QWidget()
        self.sim_feature_sequence_layout = QVBoxLayout(self.sim_feature_sequence_container)
        self.sim_feature_sequence_layout.setSpacing(6)
        seq_content.addWidget(self.sim_feature_sequence_container)
        angle_layout.addWidget(seq_card)
        angle_layout.addStretch()

        splitter.addWidget(angle_scroll)

        left = QWidget()
        # Without its own minimum width, the canvas pane can be squeezed
        # down to a sliver at a realistic (non-ultrawide) window size,
        # e.g. 1280x800: with the Angle Setup panel visible (its default
        # state) the two side panes (angle_scroll, floored at 360px via
        # setMinimumWidth below, and right_scroll, floored at 340px)
        # both have stretch factor 0, so Qt's splitter keeps THEM at
        # their preferred/floored width no matter what and hands 100% of
        # any space deficit to this canvas pane instead -- which can get
        # squeezed to a few hundred px wide (e.g. 214px against a
        # roughly-square ~34x34um design), rendering the junction as a
        # tiny box centered in a sea of empty canvas background. Giving
        # the canvas pane its own floor (big enough to keep the design
        # legible) and marking it non-collapsible means a tight window
        # instead takes the deficit out of the two side panels (which
        # can still shrink toward their own, smaller floors).
        left.setMinimumWidth(420)
        left_layout = QVBoxLayout(left)
        left_layout.setContentsMargins(0, 0, 0, 0)
        # A prominent, impossible-to-miss banner -- not just the Run
        # button's own "•" suffix -- shown right above the canvas
        # whenever the Simulated Design / Post-Shadow Result view no
        # longer reflects what's currently typed/set. See
        # _refresh_sim_stale_banner and _mark_sim_stale below for what
        # sets/clears it.
        self.sim_stale_banner = QLabel("")
        self.sim_stale_banner.setWordWrap(True)
        self.sim_stale_banner.setVisible(False)
        self.sim_stale_banner.setStyleSheet(
            "color: #ffb454; font-size: 8.5pt; font-weight: bold; padding: 5px 8px; "
            "background-color: #3a2f14; border: 1px solid #7a6a3a; border-radius: 5px;")
        left_layout.addWidget(self.sim_stale_banner)
        self.sim_fig = Figure(figsize=(6, 6), dpi=100, facecolor=BG_COLOR)
        self.sim_ax = self.sim_fig.add_subplot(1, 1, 1)
        self.sim_canvas = FigureCanvasQTAgg(self.sim_fig)
        self.sim_canvas.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)  # Same fix
                                    # Create / Import's canvas already got: without this,
                                    # the canvas just sits at its figsize-derived 600x600 natural
                                    # size instead of claiming available space, leaving a large
                                    # empty margin, AND (more disruptively) can make Qt's layout
                                    # system grow the WHOLE WINDOW to satisfy that fixed size hint
                                    # when this tab becomes visible -- matching the
                                    # "window stretches when switching tabs" glitch exactly.
        left_layout.addWidget(self.sim_canvas, stretch=1)
        self.sim_canvas.mpl_connect("scroll_event", self._on_canvas_scroll)  # mouse-centered zoom,
                                    # same _zoom_step/_on_canvas_scroll already used by Create / Import --
                                    # works here with no separate implementation since both read
                                    # whichever ax/canvas _on_nav_changed currently marked active.
        self.sim_canvas.mpl_connect("button_press_event", self._on_sim_canvas_press)  # ruler tool
        # Grid/scale-bar zoom-tracking fix (same bug and same fix as Create /
        # Import's own _create_import_xlim_callback -- see refresh_grid_and_
        # scale's docstring): the Optimal Design view draws its grid + scale
        # bar via the same draw_imported_junction_preview call Create/Import
        # uses, so it's exposed to the identical "stuck under pure scroll-
        # zoom" bug. Stored as a persistent bound-method attribute (not
        # passed directly to .connect()) because ax.clear() unconditionally
        # replaces the whole CallbackRegistry -- this must be reconnected
        # after every self.sim_ax.clear(), not just once here.
        self._sim_xlim_callback = self._on_sim_xlim_changed
        self.sim_ax.callbacks.connect("xlim_changed", self._sim_xlim_callback)
        splitter.addWidget(left)

        right = QWidget()
        right_layout = QVBoxLayout(right)
        right_layout.setContentsMargins(0, 0, 0, 0)
        right_scroll = QScrollArea()
        right_scroll.setWidgetResizable(True)
        # Caught while verifying the Post-Shadow Measurements
        # & Continuity card rewrite: this splitter (below, setSizes([320,
        # 1000, 430])) never gave any of its 3 widgets a stretch factor or a
        # floor width, so the matplotlib canvas's own expanding size policy
        # could win the layout fight and squeeze this whole right panel down
        # to its bare QScrollArea sizeHint (~80px, real screenshot measured)
        # at ordinary window widths -- silently clipping every card here
        # (this one and the pre-existing Angle/Shadowing Warnings cards
        # alike) to a sliver, with no visible sign anything was missing.
        # A floor width, matching angle_scroll's own existing 360-460 cap
        # just below, keeps it always legible; setStretchFactor after
        # splitter.setSizes (same pattern already used for the Settings and
        # Recipe splitters) then lets the canvas alone absorb any extra
        # width the window has beyond both panels' floors.
        right_scroll.setMinimumWidth(340)
        right_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)  # Word-wrap
                                    # and Stretch column mode alone did not stop
                                    # tree items from reporting an oversized natural width (a known
                                    # QTreeWidgetItem sizeHint limitation with wrapped text), which
                                    # dragged the whole scroll area wider and left text truncated
                                    # rather than wrapped. Forcibly disabling horizontal scroll here
                                    # means the content widget is CONSTRAINED to the viewport width
                                    # no matter what any child reports, forcing real wrapping instead.
        right_scroll.setWidget(right)
        self.sim_right_panel = right_scroll  # shown/hidden by sim_right_panel_toggle above

        # Recommended Deposition Angles and the per-feature
        # angle-override tree live on the "Angle & Shadowing Setup" tab,
        # alongside PMMA/PMGI/electrode height -- this tab focuses
        # purely on shadowing GEOMETRY (shapes, the crossing-overlap
        # calculation, warnings), not angle input. self.sim_angles_tree,
        # self.sim_recommendations_label, self.sim_alpha_override_edit,
        # self._sim_angle_state are all built in that tab's own function
        # but read by exactly the same code everywhere else.
        # This card is the Simulate-tab counterpart to the Create/Import
        # tab's own "Measurements" tree (same QTreeWidget/add_row
        # pattern, see _populate_measurements_tree), reporting every
        # feature's REAL POST-SHADOW dimensions instead of the nominal
        # as-drawn ones: total length, linewidth, adhesion-plate
        # length/width, each patch's real electrode/connector overlap
        # and near/far extension, the tip margin between the outermost
        # patch and the finger's real post-shadow tip, real ghost-line
        # and triangle-anomaly dimensions -- plus ONE final circuit-
        # continuity verdict (OPEN / SHORTED / intact) at the bottom.
        # Named "Post-Shadow Measurements & Continuity" to match.
        risk_card, risk_content = self._sim_card("Post-Shadow Measurements & Continuity", "#ff8f6b")
        risk_note = QLabel("Every feature's real post-shadow dimensions, and a final open/short circuit check.")
        risk_note.setWordWrap(True)
        self._themed(risk_note, lambda: f"color: {DIM_COLOR}; font-size: 8pt;")
        risk_content.addWidget(risk_note)

        self.sim_resist_label = QLabel("")
        self.sim_resist_label.setWordWrap(True)
        self._themed(self.sim_resist_label, lambda: f"color: {DIM_COLOR}; font-size: 8pt;")
        risk_content.addWidget(self.sim_resist_label)

        # Always-visible headline verdict -- the one thing the user
        # should be able to read at a glance without expanding anything
        # in the tree below it (same "headline above the detail tree"
        # placement as sim_resist_label above).
        self.sim_postshadow_verdict_label = QLabel("Run ▶ Run Shadow Simulation to check circuit continuity.")
        self.sim_postshadow_verdict_label.setWordWrap(True)
        self._themed(self.sim_postshadow_verdict_label, lambda: f"color: {TEXT_COLOR}; font-size: 9pt; font-weight: bold;")
        risk_content.addWidget(self.sim_postshadow_verdict_label)

        self.sim_postshadow_tree = QTreeWidget()
        self.sim_postshadow_tree.setHeaderLabels(["Feature", "Post-Shadow Value"])
        self.sim_postshadow_tree.setColumnWidth(0, 190)
        self.sim_postshadow_tree.setWordWrap(True)
        self.sim_postshadow_tree.header().setSectionResizeMode(0, QHeaderView.Fixed)
        self.sim_postshadow_tree.header().setSectionResizeMode(1, QHeaderView.Stretch)
        self.sim_postshadow_tree.setStyleSheet("QTreeWidget { font-size: 8pt; }")
        self.sim_postshadow_tree.setMaximumHeight(420)  # taller than the old 260px cap -- this tree
                                    # now carries a full measurement report (per Create/Import's own
                                    # Measurements tree, which has no cap at all -- capped here only
                                    # because this panel is a narrow side column, not a whole dock)
        risk_content.addWidget(self.sim_postshadow_tree)
        right_layout.addWidget(risk_card)

        warn_card, warn_content = self._sim_card("Angle Warnings", "#ffb454", collapsed=True)
        self.sim_warnings_label = QLabel("No junction drawn yet.")
        self.sim_warnings_label.setWordWrap(True)
        self._themed(self.sim_warnings_label, lambda: f"color: {TEXT_COLOR}; font-size: 9pt;")
        warn_content.addWidget(self.sim_warnings_label)
        right_layout.addWidget(warn_card)

        # A DEDICATED section, separate
        # from the angle warnings above, specifically for zero-
        # deposition alerts -- removing a feature's only layer means it
        # will not be deposited at all, which is a much more severe,
        # different kind of warning than an off-axis or risky angle.
        shadow_warn_card, shadow_warn_content = self._sim_card("Shadowing Warnings", "#ff6b6b", collapsed=False)
        self.sim_shadow_warnings_label = QLabel("No zero-deposition features.")
        self.sim_shadow_warnings_label.setWordWrap(True)
        self._themed(self.sim_shadow_warnings_label, lambda: f"color: {TEXT_COLOR}; font-size: 9pt;")
        shadow_warn_content.addWidget(self.sim_shadow_warnings_label)
        right_layout.addWidget(shadow_warn_card)
        right_layout.addStretch()

        splitter.addWidget(right_scroll)
        # This splitter now holds THREE
        # widgets (the angle setup panel added first, then canvas, then
        # this right panel), but setSizes was still only given two
        # values -- a leftover from before the angle panel existed.
        # Qt's own behavior when given fewer sizes than widgets left
        # this right panel starved of space whenever the angle panel
        # was toggled visible, effectively hiding the entire Shadowing
        # Risk Check / Warnings / Shadowing Warnings section with no
        # visible sign it still existed. All three now get an explicit
        # width.
        splitter.setSizes([320, 1000, 430])
        splitter.setStretchFactor(0, 0)  # angle setup panel: fixed, floored by its own min/max width
        splitter.setStretchFactor(1, 1)  # canvas: absorbs any extra window width
        splitter.setStretchFactor(2, 0)  # right panel: fixed, floored by right_scroll.setMinimumWidth above
        # See left.setMinimumWidth(420) above for
        # the full root-cause writeup. Also block the canvas pane from
        # being dragged all the way to 0 by hand -- setCollapsible defaults
        # to True for every pane, which would otherwise let a manual
        # splitter-handle drag re-introduce the exact same "squeezed to
        # nothing" state the minimum width above prevents on resize.
        splitter.setCollapsible(0, True)
        splitter.setCollapsible(1, False)
        splitter.setCollapsible(2, True)
        self._on_sim_active_alpha_changed()  # seed the preview's alpha field to match Active alpha
        return outer

    def _on_sim_active_alpha_changed(self, *_args):
        """Pushes Active alpha into the Wafer Orientation Preview
        widget's own alpha field as a convenience default -- the
        widget's alpha/theta/reference controls stay independently
        editable after that (same spirit as the retired Live Angle
        Tester's Jump to Load/Mill presets: they seed the fields, the fields stay
        free-typed). Does not touch the angle tree, the recommendation,
        or any committed state."""
        if not hasattr(self, "sim_chamber_preview"):
            return
        try:
            alpha = float(self.sim_alpha_override_edit.text())
        except ValueError:
            return
        self.sim_chamber_preview.set_alpha(alpha)

    def _populate_sim_recommendations_tree(self, junction):
        """A QTreeWidget version of this
        was tried first (matching the tree pattern used elsewhere), but
        QTreeWidgetItem's own sizeHint computation doesn't reliably
        account for wrapped text -- multiple attempts (setWordWrap,
        Stretch column mode, disabling the scrollbar) all failed to
        stop long explanation lines from reporting an oversized natural
        width and getting truncated instead of wrapping. A plain QLabel
        wraps reliably (proven throughout the rest of this app), so
        this uses one instead, kept inside the SAME collapsible card
        via _sim_card's own collapse mechanism -- same
        compute_recommended_angles call the original text version
        used."""
        if not hasattr(self, "sim_recommendations_label") or junction is None or not junction.fingers:
            return
        rec = ji.compute_recommended_angles(junction)
        if rec.get("not_set"):
            self.sim_recommendations_label.setText("Set which finger deposits first to get recommendations.")
            return
        lines = []
        for key in ("first_finger", "second_finger"):
            entry = rec.get(key)
            if entry is None:
                continue
            label = ji.finger_display_label(entry["finger_index"])
            order = "1st deposited" if key == "first_finger" else "2nd deposited"
            lines.append(f"Finger {label} ({order}):")
            lines.append("  " + entry["explanation"].replace("\n", "\n  "))
        patches = rec.get("patches")
        if patches is not None:
            lines.append("Patches:")
            lines.append("  " + patches["explanation"].replace("\n", "\n  "))
        self.sim_recommendations_label.setText("\n".join(lines))

    def _populate_sim_warnings_tree(self, junction):
        """Same reasoning as _populate_sim_recommendations_tree above --
        reverted from a tree to a reliably-wrapping QLabel."""
        if not hasattr(self, "sim_warnings_label") or junction is None:
            return
        if not junction.fingers:
            self.sim_warnings_label.setText("No junction drawn yet.")
            return
        lines = []
        for i, f in enumerate(junction.fingers):
            label = ji.finger_display_label(i)
            verdict = {"none": "\u2713 Safe", "unknown": "? Unchecked"}.get(f.warning_source, "\u26a0 Caution")
            lines.append(f"Finger {label}: {verdict}")
            lines.append(ji.explain_finger_angle_choice(f))
            lines.append("")
        self.sim_warnings_label.setText("\n".join(lines).strip())
        return

    def _design_fingerprint(self, junction):
        """A cheap, content-based signature of a junction's actual
        geometry -- used ALONGSIDE plain object identity
        (_sim_cached_junction) in _update_simulate_preview to decide
        whether the active design has genuinely changed.

        This closes a real gap: if the same design is edited WITHIN the
        Create/Import tab after already being simulated, everything
        except the resist and electrode thicknesses needs to reset again
        in the Simulate tab, since the underlying geometry has changed.
        A plain `junction is not self._sim_cached_junction` identity
        check can never see this: every real Create/Import edit path
        (apply_finger_edit, apply_shape_edit, recompute_derived_fields,
        the Nudge & Scale absolute-target-override mechanism, role
        reassignment, etc.) MUTATES the fields of the existing finger/
        shape/junction objects in place rather than building and
        swapping in a brand-new junction -- their own signatures confirm
        this (they take the object to edit, not a DesignParameters to
        rebuild from). Without this fingerprint check, editing a shape
        in Tab 1 and switching back to Simulate Design would leave every
        stale-design reset above silently skipped, because `junction`
        is still the exact same Python object it was before the edit --
        the design's actual angles/geometry could be completely
        different, but Simulate Design would keep showing (and letting
        you re-run against) the OLD committed angles as if nothing had
        changed.

        Rounds every float to 9 decimal places -- enough headroom that
        an ordinary UI-driven edit (which changes a value by many orders
        of magnitude more than 1e-9) is always caught, while floating-
        point noise from redrawing/recomputing the SAME unedited design
        through a different code path on a later redraw can never
        spuriously trigger a reset."""
        if junction is None:
            return None
        parts = []
        for f in junction.fingers:
            parts.append(("finger", tuple(round(c, 9) for p in f.points for c in p),
                          round(f.theta_toward_patch_deg, 9), round(f.theta_toward_stub_deg, 9),
                          round(f.width_um, 9)))
        for s in junction.other_shapes:
            parts.append((s.kind, tuple(round(c, 9) for p in s.points for c in p)))
        return tuple(parts)

    def _update_simulate_preview(self, junction, report):
        """Called from the SAME shared _update_preview cycle -- Simulate Design
        always reflects whichever design is currently active, with no
        separate recompute path of its own."""
        if not hasattr(self, "sim_ax"):
            return
        # A design switch (not just a redraw/Run click on what's already
        # loaded) must not leave _sim_last_run / _sim_has_run holding
        # the PREVIOUS design's committed angles -- otherwise Simulated
        # Design and Post-Shadow Result could silently apply one
        # design's angles to a completely different design's geometry
        # the moment you switch files, with no visible sign anything is
        # stale. This check also fires on a content-based fingerprint
        # mismatch, not just a changed object identity -- see
        # _design_fingerprint's own docstring for the in-place-mutation
        # gap that alone closes.
        design_fp = self._design_fingerprint(junction)
        if junction is not getattr(self, "_sim_cached_junction", None) \
                or design_fp != getattr(self, "_sim_cached_fingerprint", None):
            self._sim_last_run = None
            self._sim_has_run = False
            self._sim_stale = False  # item #105 -- a fresh design has no committed Run to be stale against
            self._sim_angle_diagnostic_run = False
            self._sim_finger_layers = {}
            self._sim_patch_layers = None
            self._sim_finger_thicknesses = {}
            self._sim_patch_thicknesses = None
            self._sim_finger_alphas = {}
            self._sim_patch_alphas = None
            # A design that had gone through simulation, been
            # hand-altered (angles or recipe order), and then had
            # another design loaded and simulated in its place must not
            # keep the hand-altered steps/angles from the previous
            # design: the predicted recipe sequence should be completely
            # reset when a new design is loaded in. This block already
            # resets every OTHER piece of per-design Simulate-tab state
            # (_sim_last_run, _sim_finger_layers, the angle diagnostic,
            # etc.) the moment a genuinely different design is detected,
            # so it must also reset
            # self._recipe_features/_recipe_sim_result/
            # _recipe_generated_fingerprint/_recipe_custom_steps -- the
            # Predicted Recipe Sequence card's own state. Leaving that
            # state stale would corrupt more than just the display: the
            # very next
            # _refresh_recipe_features() call (fired automatically once
            # the new design's angle diagnostic runs) passes this
            # left-over PREVIOUS-design feature list into
            # _reapply_manual_angle_overrides as `old_features` --
            # matched only by (kind, label), e.g. "deposition"/"Deposit
            # patches (pass 1 of 2)", a label that recurs across totally
            # unrelated designs -- so any hand-typed angle override (or
            # a fully hand-inserted custom step) from the OLD design
            # silently bleeds onto the NEW design's freshly computed
            # sequence. Clearing this state here, in the exact same
            # reset block as everything else per-design, makes
            # _reapply_manual_angle_overrides's own `if not old_features:
            # return` guard a genuine no-op for a new design: a new
            # design resets everything except the wafer-wide parameters.
            self._recipe_features = []
            self._recipe_sim_result = None
            self._recipe_generated_fingerprint = None
            self._recipe_custom_steps = []
            if hasattr(self, "sim_feature_sequence_layout"):
                self._populate_sim_feature_sequence()
            if hasattr(self, "sim_run_button"):
                self.sim_run_button.setText("\u25b6 Run Shadow Simulation")
                self.sim_run_button.setEnabled(False)
            if hasattr(self, "sim_run_diagnostic_button"):
                self.sim_run_diagnostic_button.setText("\u25b6 Run Angle Diagnostic")
            if hasattr(self, "sim_stale_banner"):
                self._refresh_sim_stale_banner()
            if self._sim_view_mode in ("simulated", "postshadow"):
                self._sim_view_mode = "optimal"
                if hasattr(self, "sim_view_optimal_btn"):
                    self.sim_view_optimal_btn.setChecked(True)
                    self.sim_view_simulated_btn.setChecked(False)
                    self.sim_view_postshadow_btn.setChecked(False)
        self.sim_ax.clear()
        if junction is not None and report is not None and self._sim_view_mode == "postshadow" and self._sim_has_run:
            # The COMPLETE final design after all depositions -- real
            # computed polygons, not the nominal design annotated with
            # dimension bands. Only available once Run Simulation has
            # committed the active angles, same as Simulated Design.
            self._draw_post_shadow_design(self.sim_ax, junction, report)
        else:
            # The Optimal Design view looks exactly like Create /
            # Import's plain design until the user explicitly runs the
            # angle diagnostic -- no Warning #1/#2 markers appear before
            # that click. Once the diagnostic has run, both show
            # together automatically, tied to the diagnostic step itself
            # rather than a separate manual on/off toggle for each.
            w1 = w2 = True
            # warning1_enabled=False/warning2_enabled=False alone does
            # NOT hide the theta labels in draw_imported_junction_preview
            # -- it only draws them in neutral color without a
            # warning/checkmark symbol (labels like "theta=0 deg" stay
            # present with both flags off). Genuinely hiding everything
            # requires show_badges=False, a separate parameter that
            # skips ALL badge drawing outright -- used here for both
            # "diagnostic hasn't run yet" and "toggle switched off",
            # rather than relying on w1/w2 to do double duty as a
            # visibility switch they were never built to be.
            show_diag = self.sim_show_diagnostics_toggle.isChecked() if hasattr(self, "sim_show_diagnostics_toggle") else True
            show_badges = self._sim_angle_diagnostic_run and show_diag
            draw_imported_junction_preview(self.sim_ax, junction, report, show_caption=False,
                                           warning1_enabled=w1, warning2_enabled=w2, show_badges=show_badges)
            # Shadow bands only ever show in Simulated Design view, and only
            # once Run Simulation has actually been clicked -- Optimal Design
            # view shows the plain warning-based layout with no shadow
            # bands at all, matching "the simulation doesn't happen until
            # the user clicks Run Simulation."
            if junction is not None and report is not None and self._sim_view_mode == "simulated" and self._sim_has_run:
                self._draw_sim_shadow_visualization(self.sim_ax, junction, report)
        # Reconnect -- see the matching comment where self._sim_xlim_callback
        # is first connected: self.sim_ax.clear() just above (and, in the
        # Optimal Design branch, draw_imported_junction_preview's own
        # internal ax.clear()) unconditionally wipes the whole callback
        # registry, so this must run after every redraw, not just once.
        self.sim_ax.callbacks.connect("xlim_changed", self._sim_xlim_callback)
        self.sim_ax.set_facecolor(BG_COLOR)
        for spine in self.sim_ax.spines.values():
            spine.set_color(BORDER_COLOR)
        self._draw_sim_rulers(self.sim_ax)  # AFTER the main redraw -- that call clears the axes first
        self.sim_canvas.draw()
        if hasattr(self, "sim_active_label"):
            source_txt = "Created" if self._display_source == "parametric" else "Imported"
            detail = getattr(junction, "source_label", "") or ""
            self.sim_active_label.setText(f"Simulating: {source_txt} \u2014 {detail}")
        self._sim_cached_junction = junction
        self._sim_cached_report = report
        self._sim_cached_fingerprint = design_fp
        if self._sim_angle_diagnostic_run:
            self._populate_sim_recommendations_tree(junction)
            self._populate_sim_warnings_tree(junction)
            rec = ji.compute_recommended_angles(junction) if (junction is not None and junction.fingers) else {"not_set": True}
            self._rebuild_sim_angles_tree(junction, rec)
        self._update_sim_shadow_risk()

    def _project_plate_onto_finger_axis(self, finger, plate_points):
        """Finding the plate's own near/far ends via
        _polygon_axis_and_ends -- which just picks whichever dimension
        of the plate's OWN rectangle is longer -- works fine for a
        long, narrow plate colinear with its finger, but a near-square
        plate has no well-defined "long axis" of its own, and picking
        the wrong one means near/far get computed against a direction
        that has nothing to do with how the finger actually approaches
        it. In one measured case, a near-square plate's own long
        dimension was horizontal, while its finger approached
        vertically -- the distance from the finger's tip to what that
        method calls the plate's "near end" was 1.118 (comfortably
        outside the 0.5 tolerance), so association would silently fail
        every time. Projecting the plate's own 4 corners onto the
        FINGER's own axis direction instead -- grouping the 2 closest
        corners as "near", the 2 farthest as "far" -- works regardless
        of the plate's own aspect ratio, and reproduces the exact same
        near/far/width as that method on long, narrow plates (near an
        exact match to the finger's own patch_end)."""
        fx = finger.patch_end[0] - finger.stub_end[0]
        fy = finger.patch_end[1] - finger.stub_end[1]
        flen = math.hypot(fx, fy) or 1.0
        axis_hat = (fx/flen, fy/flen)
        projections = [((p[0]-finger.stub_end[0])*axis_hat[0] + (p[1]-finger.stub_end[1])*axis_hat[1], p)
                       for p in plate_points]
        projections.sort(key=lambda t: t[0])
        near_pair = [p for _, p in projections[:2]]
        far_pair = [p for _, p in projections[2:]]
        near_end = (sum(p[0] for p in near_pair)/2.0, sum(p[1] for p in near_pair)/2.0)
        far_end = (sum(p[0] for p in far_pair)/2.0, sum(p[1] for p in far_pair)/2.0)
        width = math.hypot(near_pair[0][0]-near_pair[1][0], near_pair[0][1]-near_pair[1][1])
        return near_end, far_end, width

    def _find_associated_plate(self, junction, finger, tol_um=0.5):
        """Whether this finger has an adhesion/overlap plate physically
        touching or overlapping it -- checked against TWO
        genuinely different real geometries before settling on this:
        in one design a finger and plate meet edge-to-edge (patch_end essentially
        coincides with the plate's near edge), but in another the finger polygon
        extends WELL INTO its plate (patch_end sits 3 units inside a
        4-unit-tall plate, nowhere near either edge) -- a point-distance
        tolerance check that worked for the first case completely
        missed the second (distance was 3+ units, nowhere close to any
        reasonable tolerance). A genuine polygon-overlap check (do the
        finger's and plate's own drawn shapes actually touch or
        intersect at all) correctly catches both patterns, since both
        are still the same physical situation: same deposition step,
        continuous metal, whether they merely touch or substantially
        overlap. Returns (plate_shape, plate_near_end, plate_far_end)
        or None if no plate touches this finger at all."""
        try:
            finger_poly = sg.Polygon(finger.points)
        except Exception:
            return None
        for s in junction.other_shapes:
            if s.kind != "plate":
                continue
            try:
                plate_poly = sg.Polygon(s.points)
                if finger_poly.distance(plate_poly) > tol_um:
                    continue
            except Exception:
                continue
            near_end, far_end, _w = self._project_plate_onto_finger_axis(finger, s.points)
            return s, near_end, far_end
        return None

    def _find_finger_for_plate(self, junction, plate_shape):
        """Picking "whichever finger's stub_end or patch_end is closest
        to this plate's own CENTROID" is a much cruder heuristic than
        the precise proximity check _find_associated_plate already uses
        the other way around (finger -> its plate). In an orthogonal
        layout (two fingers at 90 degrees to each other, both plates
        roughly similarly far from the crossing point), centroid
        distance can easily pick the WRONG finger entirely, which would
        explain both a plate getting an unrelated theta and, if that
        wrong finger's angle happens to be perpendicular to this
        plate's own axis, appearing to get zero shadow at all. Reuses
        the SAME real touching-point check as _find_associated_plate,
        just from the plate's side, for consistency -- one true
        pairing, checked the same way everywhere. Falls back to the
        old centroid heuristic only for a plate that doesn't actually
        touch any finger's tip at all."""
        for f in junction.fingers:
            found = self._find_associated_plate(junction, f)
            if found is not None and found[0] is plate_shape:
                return f
        cx = sum(p[0] for p in plate_shape.points) / len(plate_shape.points)
        cy = sum(p[1] for p in plate_shape.points) / len(plate_shape.points)
        return min(junction.fingers, key=lambda f: min(
            math.hypot(cx - f.stub_end[0], cy - f.stub_end[1]),
            math.hypot(cx - f.patch_end[0], cy - f.patch_end[1])))

    def _shadow_alignment(self, axis_hat_toward_end, theta_deg):
        """Positive = the active deposition theta points TOWARD this
        end (that end EXTENDS, dy applies); negative = theta points
        AWAY from this end (that end SHRINKS, dx applies). Matches the
        existing, already-validated Warning #2 convention:
        self_shadow_safe_theta_deg
        (= theta_toward_stub_deg) gives positive alignment at the stub/
        crossing end, and the risky theta_toward_patch_deg gives
        negative -- matching "thinning lands on the current-carrying
        side" exactly for a real design's own computed values."""
        theta_hat = (math.cos(math.radians(theta_deg)), math.sin(math.radians(theta_deg)))
        return axis_hat_toward_end[0] * theta_hat[0] + axis_hat_toward_end[1] * theta_hat[1]

    def _scaled_shadow_depth(self, dx_um, dy_um, align):
        """Picking dy or dx by the SIGN of align alone would make any
        custom theta within +-90 deg of the recommended direction
        produce the exact same visual result as the recommendation
        itself -- so typing a custom angle would appear to do nothing.
        Scaling by |align| (the cosine of how far off-axis theta
        actually is) makes the depth vary continuously: full effect
        exactly on-axis, zero effect exactly perpendicular (align=0),
        and the sign flip at +-90 deg naturally reproduces "recommended
        +-180 flips the shadowing" without a special case. align=-1.0
        exactly at theta_toward_stub (the recommended opposite
        direction), as expected."""
        depth = (dy_um if align > 0 else dx_um) * abs(align)
        return depth, align > 0

    def _net_depth_multi(self, axis_hat, thetas, dx_um, dy_um):
        """N-way generalization of the two-pass patches cascade fix
        (metal accumulates across ALL active depositions -- the final
        boundary is simply whichever single pass reaches furthest,
        symmetric with respect to order or count). Verified against a
        synthetic case matching a real workflow
        (a vertical finger deposited at both 0 and 270 with no
        oxidation between) before using this to replace the old
        single-theta-only computation for fingers and plates. Returns
        None if thetas is empty -- meaning this feature has NO active
        deposition at all, which callers must handle by omitting the
        shape entirely, not by falling back to some default angle.

        `dx_um`/`dy_um` accept EITHER a single scalar (broadcast to
        every theta, for a caller with one shared alpha across all
        passes) OR a sequence the same length as `thetas` (each pass's
        own real dx/dy, from that pass's own real alpha). A per-step
        alpha edit (supported by the Predicted Recipe Sequence panel,
        and by the real Plassys machine, which can retilt between any
        two passes) needs a path to reach this math: a single shared
        dx/dy pair would mean raising the tilt for just one pass
        produces no change anywhere in the shadow sim/post-deposition
        view or ghost linewidths, since every pass would still be
        computed against the same alpha. The combination rule itself
        (furthest pass wins) treats each pass independently before
        combining; only the per-pass dx/dy lookup varies."""
        if not thetas:
            return None
        dx_list = dx_um if isinstance(dx_um, (list, tuple)) else [dx_um] * len(thetas)
        dy_list = dy_um if isinstance(dy_um, (list, tuple)) else [dy_um] * len(thetas)
        signed_vals = []
        for t, dx_i, dy_i in zip(thetas, dx_list, dy_list):
            align = self._shadow_alignment(axis_hat, t)
            depth, extend = self._scaled_shadow_depth(dx_i, dy_i, align)
            signed_vals.append(depth if extend else -depth)
        net = max(signed_vals)
        return abs(net), net > 0

    def _electrode_shadow_addon_um(self, align, alpha):
        """Electrode-crossing shadow (compute_electrode_shadow from Tab
        3) is a GENUINELY DIFFERENT mechanism from the resist-stack
        overlap shadow above -- the electrode's own physical height
        blocks metal near its edge, independent of PMMA/PMGI. It only
        applies on the RISKY side of a Warning #1 feature (align<0,
        theta pointing away from the safe direction) -- when theta is
        safe, the feature travels uphill onto the electrode and this
        mechanism doesn't apply at all. Scaled by |align| for the same
        reason the overlap shadow is."""
        if align >= 0:
            return 0.0
        try:
            electrode_height_nm = float(self.es_height_edit.text()) if hasattr(self, "es_height_edit") else 300.0
        except ValueError:
            electrode_height_nm = 300.0
        shadow_nm = compute_electrode_shadow(electrode_height_nm, alpha)
        return (shadow_nm / 1000.0) * abs(align)

    def _all_deposition_pass_records(self, junction, run, theta_overrides, patch_thetas=None,
                                      patch_thicknesses=None, finger_theta_lists=None,
                                      finger_alpha_lists=None, patch_alphas=None,
                                      alpha=None, dx_um=None, dy_um=None):
        """Every real deposition pass in the recipe, each tagged with the
        kind/feature-index that OFFICIALLY owns it and that ONE pass's
        own thickness -- the corrected ghost-
        junction-line model draws its 'foreign pass' pool from this,
        then EXCLUDES a target's own records before checking it (see
        _foreign_pass_records/_ghost_junction_slivers). Every deposition
        step exposes the whole open wafer (the same cross-feature
        'blanket deposition' philosophy as the Deposition Slideshow's
        Shadow Sim view), so a feature's own
        still-open resist aperture is exposed to every OTHER feature's
        deposition pass too, not just its own recipe-assigned theta(s).

        By default (finger_theta_lists=None) each finger's thetas are
        resolved off `run` the same way every other real-geometry caller
        in this file does -- for Post-Shadow Result's always-FINAL pool.
        Passing finger_theta_lists ({finger_index: [thetas so far]})
        instead lets the Deposition Slideshow's progressive view
        (_compute_post_shadow_shapes_upto) build the same kind of pool
        from a possibly-truncated "so far" history, so a ghost line
        correctly can't appear before the pass that actually causes it
        happens in the slideshow.

        Plates are deliberately NOT pooled in separately -- a plate
        always deposits in the same step as its owning finger (an
        existing convention), so its passes are already present via that
        finger's own records; a ghost check against a plate target
        excludes that owning finger's records the same way a finger
        target excludes its own (see _foreign_pass_records).

        New, all OPTIONAL/additive: when `alpha`,
        `dx_um`, and `dy_um` (this call's own already-computed shared
        fallback scalars -- exactly what every existing caller already
        has in scope) are all supplied, each emitted record ALSO carries
        its own resolved `"alpha"`/`"dx_um"`/`"dy_um"` keys, so a
        downstream cross-feature consumer (_ghost_junction_slivers,
        _foreign_blanket_footprints/_disjoint_foreign_plate_lobes via
        their own callback, _plate_thickness_bands) can use THIS pass's
        own real per-pass alpha instead of always falling back to the
        one shared scalar -- see _resolve_pass_dxdy_list for the
        resolution itself. Finger alpha hints come from
        `finger_alpha_lists` ({finger_index: [alphas so far]}, parallel
        to `finger_theta_lists`) when that's given, else from
        `run["theta_a_alphas"]`/`run["theta_b_alphas"]` (parallel to how
        theta itself is resolved just above) -- so the Post-Shadow-Result
        path gets this for free with no new argument needed, only the
        Slideshow's progressive path needs the explicit list. Patch
        alpha hints come from `patch_alphas`, which -- like
        `patch_thicknesses` already does -- the caller must resolve and
        reorder to match `patch_thetas` itself (_match_pass_thicknesses
        with default=None). Omitting `alpha`/`dx_um`/`dy_um` entirely
        (the old 6-arg call shape) skips all of this and reproduces
        today's exact records -- no dx_um/dy_um/alpha keys at all --
        fully backward compatible for every existing caller."""
        records = []
        resolve_dxdy = alpha is not None and dx_um is not None and dy_um is not None
        if resolve_dxdy:
            try:
                pmma_nm = float(self.pmma_edit.text()) if hasattr(self, "pmma_edit") else 875.0
            except ValueError:
                pmma_nm = 875.0
            try:
                pmgi_nm = float(self.pmgi_edit.text()) if hasattr(self, "pmgi_edit") else 600.0
            except ValueError:
                pmgi_nm = 600.0
        for i, f in enumerate(junction.fingers):
            alpha_hints = None
            if finger_theta_lists is not None:
                thetas = finger_theta_lists.get(i, [])
                alpha_hints = (finger_alpha_lists or {}).get(i)
            else:
                thetas = self._run_finger_thetas(run, i, f, theta_overrides)
                alpha_hints = self._run_finger_alphas(run, i)
            if not thetas:
                continue
            layers_ref = self._sim_finger_layers.get(i) or thetas
            thicknesses_ref = self._sim_finger_thicknesses.get(i, [])
            pass_thicknesses = self._match_pass_thicknesses(thetas, layers_ref, thicknesses_ref)
            if resolve_dxdy:
                dx_list, dy_list = self._resolve_pass_dxdy_list(thetas, alpha_hints, dx_um, dy_um, pmma_nm, pmgi_nm)
            for j, (t, th) in enumerate(zip(thetas, pass_thicknesses)):
                rec = {"theta": t, "kind": "finger", "feature_index": i, "thickness": th}
                if resolve_dxdy:
                    rec["dx_um"] = dx_list[j]
                    rec["dy_um"] = dy_list[j]
                    rec["alpha"] = alpha_hints[j] if alpha_hints and j < len(alpha_hints) and alpha_hints[j] is not None else alpha
                records.append(rec)
        if patch_thetas:
            if patch_thicknesses is None or len(patch_thicknesses) != len(patch_thetas):
                patch_thicknesses = [None] * len(patch_thetas)
            if resolve_dxdy:
                p_dx_list, p_dy_list = self._resolve_pass_dxdy_list(patch_thetas, patch_alphas, dx_um, dy_um, pmma_nm, pmgi_nm)
            for j, (t, th) in enumerate(zip(patch_thetas, patch_thicknesses)):
                rec = {"theta": t, "kind": "patch", "feature_index": None, "thickness": th}
                if resolve_dxdy:
                    rec["dx_um"] = p_dx_list[j]
                    rec["dy_um"] = p_dy_list[j]
                    rec["alpha"] = patch_alphas[j] if patch_alphas and j < len(patch_alphas) and patch_alphas[j] is not None else alpha
                records.append(rec)
        return records

    def _foreign_pass_records(self, all_records, exclude_kind, exclude_index):
        """Every pooled deposition-pass record EXCEPT the ones officially
        belonging to the target being checked -- a feature checking its
        own aperture against its OWN official pass(es) is not a
        'foreign' pass at all (that's just its own ordinary deposition);
        only a pass belonging to a DIFFERENT feature qualifies as a
        candidate ghost-line source. Patches are excluded as a whole
        kind when the target itself is a patch (every patch instance in
        every group shares the same recipe-wide patch_thetas, so there
        is no meaningfully 'different' patch pass to be foreign to
        another patch); a plate target passes exclude_kind="finger",
        exclude_index=<owning finger index> (a plate deposits in
        lockstep with its own finger, an existing convention, and never
        contributes its own records to the pool at all -- see
        _all_deposition_pass_records)."""
        return [r for r in all_records
                if not (r["kind"] == exclude_kind and
                        (exclude_index is None or r["feature_index"] == exclude_index))]

    def _foreign_blanket_footprints(self, foreign_records, single_pass_footprint_fn):
        """A new mechanism, verified
        against real adhesion-pad screenshots and an SEM reference
        showing an adhesion plate visibly thickened/pushed in THREE
        different directions by three DIFFERENT fingers' own deposition
        passes: adhesion pads that are wide (often wider than
        the max linewidths) are constantly being shadowed
        in every deposition step, so they accumulate
        thickness in various directions -- this models that same
        mechanism.

        Physically: every deposition step exposes the whole open wafer
        (see _all_deposition_pass_records's own docstring -- the same
        principle already used for ghost junction line slivers), so a
        feature that ALREADY holds real metal from its own official
        pass(es) is STILL exposed to every later foreign pass too. A
        foreign pass can only ever ADD more metal on top of / beside
        what a feature's own official pass(es) already deposited --
        never retroactively remove any of it -- so this is a strict
        UNION, never a shrink.

        `single_pass_footprint_fn(theta) -> footprint_or_None` is the
        SAME per-pass, fully-independently-shadowed footprint callback
        each feature kind already builds for its own official passes
        (_finger_pass_footprint / the plate equivalent) -- invoked here
        with a FOREIGN theta instead of one of the feature's own, so
        every already-validated per-pass physics this feature kind has
        (electrode-crossing subtraction, cross-axis self-shadow, the
        associated-plate patch-end gating, etc.) applies automatically
        to a foreign pass exactly the way it already does to an
        official one -- this can never independently drift from that
        per-pass math, and a foreign pass that physically points away
        from this feature correctly contributes nothing (its own solo
        footprint comes back empty/None, exactly like a self-shadowed
        official pass already does).

        Returns a list of (footprint, thickness) pairs -- the same
        shape _pass_footprint_overlay's own `pass_footprints` parameter
        expects, so a caller can append these directly onto a feature's
        own official (footprint, thickness) list and reuse that one
        shared N-way combinator unchanged -- skipping any foreign pass
        whose own solo footprint on this feature is None or empty.

        `single_pass_footprint_fn` is now called
        as `single_pass_footprint_fn(theta, alpha_override)` -- a foreign
        record carrying its own resolved `"alpha"` key (stamped on by
        _all_deposition_pass_records) passes that pass's own real alpha
        through, so a foreign pass computes its solo footprint with ITS
        OWN tilt, not whatever alpha this feature's own official passes
        happen to use. A record with no `"alpha"` key (old-style, or a
        caller that didn't opt into per-pass alpha) passes `None`,
        matching today's exact shared-alpha behavior."""
        out = []
        for rec in foreign_records:
            try:
                fp = single_pass_footprint_fn(rec["theta"], rec.get("alpha"))
            except Exception:
                fp = None
            if fp is None:
                continue
            try:
                poly = fp if hasattr(fp, "geom_type") else sg.Polygon(fp).buffer(0)
            except Exception:
                continue
            if poly.is_empty:
                continue
            out.append((fp, rec["thickness"] if rec["thickness"] is not None else 0.0))
        return out

    def _widen_with_foreign_footprints(self, official_pts, foreign_footprints):
        """Unions a feature's own official final polygon (`official_pts`)
        with every qualifying foreign pass's own footprint (from
        _foreign_blanket_footprints) -- the actual GEOMETRIC widening
        needed to incorporate the overshadow extra-deposition
        material, not just a color change. Returns (new_points_list,
        multi_geom) -- multi_geom is the full (possibly disconnected)
        shapely union, for a caller that needs every disjoint lobe
        (fingers); new_points_list is just the SINGLE LARGEST lobe's own
        exterior, for a caller that -- like every existing plate
        computation -- always reduces to one piece. Returns
        (official_pts, None) unchanged if there's nothing to widen with,
        or on any construction failure (same safety-net convention every
        other thickness/geometry helper in this file already uses).

        `official_pts=None` means there is NO real official geometry yet
        (a plate whose own owning finger hasn't deposited at this point
        in the sequence -- see the own_pass_pending branch at both call
        sites). Both call sites must pass None rather than substituting
        this plate's own FULL NOMINAL (undeposited) outline as a
        stand-in `official_pts`: the union below (`[official_poly] +
        extra`) would then union the ENTIRE unshadowed plate with a
        foreign footprint that is, by construction, always a subset of
        that same full outline -- a union can only ever grow or
        preserve area, never shrink it, so that would be a geometric
        no-op that always returns the full, uncut nominal shape no
        matter what the real shadow computation said. Passing None
        instead means: there is nothing real to anchor/preserve, so
        union ONLY the foreign footprints together and return the
        union's own largest resulting piece -- this is a plate's real,
        physically-deposited coverage so far (foreign-only), correctly
        reduced/shaped by the actual per-pass shadow math, not the
        untouched nominal aperture."""
        # `max(geoms, key=lambda g: g.area)` -- picking the LARGEST lobe
        # of the union -- assumes a plate's own official geometry and a
        # qualifying foreign footprint always end up touching/
        # overlapping (the common case this mechanism is built and
        # tested against). But a foreign pass's own solo blanket
        # footprint on this plate (_foreign_blanket_footprints) is
        # computed completely independently of the plate's own official
        # geometry, with no guarantee it actually touches it -- when it
        # doesn't (a foreign theta whose own solo footprint on this
        # plate lands entirely DISJOINT from, and happens to be LARGER
        # than, the plate's own correctly-shadowed official area),
        # `unary_union` returns two separate lobes, and "largest by
        # area" would pick the unrelated FOREIGN lobe -- silently
        # discarding the plate's own real, correctly axially-shadowed
        # geometry and replacing it with an unrelated blob positioned
        # wherever that foreign pass's own solo computation happened to
        # land. Picking the lobe that actually CONTAINS/overlaps the
        # ORIGINAL official polygon instead of the largest one means
        # this feature's own real geometry can never be replaced by a
        # disjoint foreign blob; a foreign footprint that doesn't touch
        # the official geometry at all is effectively excluded from this
        # widening (it never had a legitimate "same contiguous piece"
        # claim to begin with -- a genuinely disconnected foreign
        # contribution is exactly what the separate ghost-junction-
        # sliver mechanism exists to model instead, not this one).
        if not foreign_footprints:
            return official_pts, None
        try:
            official_poly = sg.Polygon(official_pts).buffer(0) if official_pts is not None else None
            extra = [fp if hasattr(fp, "geom_type") else sg.Polygon(fp).buffer(0) for fp, _th in foreign_footprints]
            union_input = ([official_poly] if official_poly is not None else []) + extra
            widened = so.unary_union(union_input)
            if widened.is_empty:
                return official_pts, None
            geoms = list(widened.geoms) if hasattr(widened, "geoms") else [widened]
            geoms = [g for g in geoms if hasattr(g, "exterior") and g.exterior is not None and g.area > 1e-9]
            if not geoms:
                return official_pts, None
            if official_poly is not None:
                containing = [g for g in geoms if g.intersects(official_poly)]
                chosen = max(containing, key=lambda g: g.area) if containing else official_poly
            else:
                # No real official geometry to anchor to (own_pass_pending) --
                # just pick the largest piece of the foreign-only union as
                # this plate's real foreign-deposited coverage so far.
                chosen = max(geoms, key=lambda g: g.area)
            return list(chosen.exterior.coords), widened
        except Exception:
            return official_pts, None

    def _disjoint_foreign_plate_lobes(self, widened_pts, foreign_records, single_pass_footprint_fn):
        """The companion piece to _widen_with_foreign_footprints above:
        since that function refuses to merge a genuinely disjoint
        foreign footprint into this plate's own official geometry, this
        surfaces each such
        footprint separately instead of silently dropping it -- a
        foreign pass whose own solo footprint on this plate lands
        disconnected from the plate's own real (possibly already
        widened-by-OTHER-foreign-passes) geometry is still real,
        physically-deposited metal, exactly the same physical situation
        _ghost_junction_slivers already models for fingers/patches (a
        foreign pass's metal landing disconnected from a feature's own
        real line) -- just at a plate's own much larger scale (a real,
        independently-shadowed footprint comparable in size to the
        plate itself) rather than a thin dx/dy-sized sliver, so this
        reuses each record's own full solo footprint (the SAME
        single_pass_footprint_fn callback _foreign_blanket_footprints
        itself uses) rather than the thin-sliver rectangle model.

        Checked per-record (not against the already-unioned blanket
        footprint) so a caller always knows exactly which foreign
        pass/thickness each disjoint lobe belongs to -- the same
        per-record attribution _foreign_pass_records already carries.
        Returns a list of (points, thickness) pairs, one per foreign
        record whose own solo footprint on this plate is real and
        genuinely disjoint from `widened_pts`; a record whose own
        footprint is empty, self-shadowed (None), or overlaps
        `widened_pts` at all is excluded (an overlapping one already
        contributes its thickness via the ordinary extra_passes/
        _plate_thickness_bands path, so including it here too would
        double-count it)."""
        try:
            official_poly = sg.Polygon(widened_pts).buffer(0)
        except Exception:
            return []
        out = []
        for rec in foreign_records:
            try:
                fp = single_pass_footprint_fn(rec["theta"], rec.get("alpha"))
            except Exception:
                fp = None
            if fp is None:
                continue
            try:
                poly = fp if hasattr(fp, "geom_type") else sg.Polygon(fp).buffer(0)
            except Exception:
                continue
            if poly.is_empty or poly.intersects(official_poly):
                continue
            out.append((list(poly.exterior.coords), rec["thickness"] if rec["thickness"] is not None else 0.0))
        return out

    def _cross_feature_thickness_overlay(self, shapes):
        """A new mechanism: features that overlap are scaled to
        whatever combined thickness is present after they overlap. So
        the junction ends up at the thickness of finger 1 + finger 2,
        and reads darker. Overlapping features
        have their color darker in accordance with how much thicker
        those layers now are, matching the adhesion pads and the
        patches (already partly true for the patches).

        Generalizes the EXISTING per-feature _pass_footprint_overlay
        (multiple of ONE feature's own passes decohering into thickness
        bands) to CROSS-FEATURE overlaps: two DIFFERENT features' own
        final deposited metal physically occupying the same space (two
        fingers meeting at a JJ crossing, an adhesion plate whose own
        blanket-widened footprint -- see _foreign_blanket_footprints --
        now overlaps a neighboring finger, two patches that happen to
        touch, etc.) using the exact same N-way overlay math, applied
        across `group_id` boundaries this time instead of pass indices.

        Each existing group_id already identifies one contiguous,
        already-finalized real piece of ONE feature (see
        _compute_post_shadow_shapes' own docstring) -- shapes sharing a
        group_id are already a correct non-overlapping partition of
        that ONE piece and must never be checked against each other;
        only shapes from DIFFERENT group_ids can physically overlap in
        space. For every resulting atomic region, EVERY group_id that
        covers it is re-emitted there (so each group's own union of its
        own re-emitted pieces still reconstructs its EXACT original
        silhouette -- _draw_shadow_shapes' per-group_id white outline
        stays exactly correct, unaffected by this), each carrying the
        SAME combined thickness = the sum of every covering group's own
        local thickness there. A region covered by only one group comes
        back with that group's own unchanged thickness (sum of one term
        is a no-op), so this can only ever DARKEN a genuine overlap,
        never change anything else.

        A ghost sliver (is_ghost=True) is excluded entirely, passed
        through untouched -- it is deliberately a DISJOINT, not-really-
        there fragment (see _ghost_junction_slivers' own docstring), not
        real permanently-deposited metal, so it must never darken (or be
        darkened by) a real feature's own color.

        Returns a new shapes list in the same 6-tuple shape. Degrades to
        the original `shapes` list completely unchanged on any
        construction failure or whenever fewer than 2 real (non-ghost)
        pieces exist to compare -- same safety-net convention every
        other thickness-banding function in this file already uses."""
        ghosts = [s for s in shapes if s[5]]
        real = [s for s in shapes if not s[5]]
        if len(real) < 2:
            return shapes
        try:
            group_info = {}
            layers = []  # every individual BAND, tagged with its own group_id
            for pts, kind, fi, th, gid in [(p, k, f, t, g) for p, k, f, t, g, _gh in real]:
                poly = sg.Polygon(pts).buffer(0)
                if poly.is_empty:
                    continue
                group_info.setdefault(gid, {"kind": kind, "fi": fi})
                layers.append((gid, poly, th if th is not None else 0.0))
            if len({gid for gid, _p, _t in layers}) < 2:
                return shapes

            # Successive refinement at the INDIVIDUAL-BAND granularity
            # (not one merged silhouette per group) -- caught and fixed
            # while writing this function's own
            # regression test: refining group-by-group using each
            # group's own merged silhouette, then separately summing
            # "every one of that group's own bands whose polygon touches
            # this atomic region," double- (or quadruple-) counts a
            # group that has 2+ of its own already-thickness-banded
            # sub-pieces (e.g. a plate with its own near/far/core
            # thickness split) -- a region can only ever genuinely
			# belong to ONE of that SAME group's own bands (they tile
            # disjointly, by construction), so crediting every band that
            # merely OVERLAPS the group's own merged silhouette there
            # inflated the combined thickness far past the real sum
            # (observed directly: a 40nm+55nm cross-feature overlap
            # coming out as 245nm, the group's own 4 internal sub-band
            # thicknesses [40, 55, 55, 95] all summed together instead
            # of picking the one that actually applies). Fixed by
            # tracking a per-region {gid: thickness} accumulator one
            # BAND at a time instead: a NEW band belonging to a gid
            # already present in `contrib` REPLACES that entry rather
            # than adding to it (same physical reason -- two bands of
            # the SAME group are never both really present at the same
            # point), while a genuinely DIFFERENT gid's contribution
            # still ADDS, which is the actual cross-feature effect this
            # function exists to produce.
            atomic = [(layers[0][1], {layers[0][0]: layers[0][2]})]
            for gid, poly, th in layers[1:]:
                new_atomic = []
                covered = so.unary_union([r for r, _c in atomic]) if atomic else sg.Polygon()
                for region, contrib in atomic:
                    inter = region.intersection(poly)
                    if not inter.is_empty and inter.area > 1e-9:
                        new_contrib = dict(contrib)
                        new_contrib[gid] = th  # same-group bands never overlap -- replace, don't add
                        new_atomic.append((inter, new_contrib))
                    diff = region.difference(poly)
                    if not diff.is_empty and diff.area > 1e-9:
                        new_atomic.append((diff, contrib))
                new_part = poly.difference(covered)
                if not new_part.is_empty and new_part.area > 1e-9:
                    new_atomic.append((new_part, {gid: th}))
                atomic = new_atomic
            if not atomic:
                return shapes

            result = []
            for region, contrib in atomic:
                if region.is_empty or not contrib:
                    continue
                combined = sum(contrib.values())
                geoms = list(region.geoms) if hasattr(region, "geoms") else [region]
                geoms = [g for g in geoms if hasattr(g, "exterior") and g.exterior is not None and g.area > 1e-9]
                if not geoms:
                    continue
                pts_list = [list(g.exterior.coords) for g in geoms]
                for gid in contrib:
                    info = group_info[gid]
                    for pts in pts_list:
                        result.append((pts, info["kind"], info["fi"], combined, gid, False))
            return (result + ghosts) if result else shapes
        except Exception:
            return shapes

    def _ghost_junction_slivers(self, nominal_pts, axis_hat, perp_hat, origin, foreign_records, dx_um, dy_um,
                                 junction=None, alpha_deg=None):
        """Physical model: a ghost junction line is a fragment of a
        DIFFERENT, currently-depositing feature's OWN metal landing
        inside a THIRD, not-yet-deposited feature's still fully-open
        resist aperture -- specifically in that aperture's UNDERCUT
        region, beyond its own nominal (top-of-PMMA) edge, not touching
        the eventual real feature at all (there is a visible gap between
        where the ghost line starts and where the actual deposited
        feature within that trench is). This matches real SEM evidence
        (a 520nm vertical finger sample). It is a fragment of foreign
        metal landing in an open aperture's undercut -- not a translated
        copy of the at-risk feature's own line offset by its own
        linewidth excess.

        Physical derivation: the resist aperture's near/entry wall has
        already bloomed outward with depth by the time it's developed
        (e-beam forward/backscatter), so incoming metal is shadowed by
        the wall's own FULL bilayer height for a lateral throw of
        h*tan(alpha) (h = PMMA+PMGI) -- exactly dx_um, already computed
        by _shadow_dxdy from the same pmma+pmgi/alpha used everywhere
        else in this file. Metal then lands from that point onward, out
        to the aperture's own FAR wall's undercut (extended by PMGI's
        own bloom, dy_um) -- exactly the existing _cross_axis_boundaries
        per-pass formula (dx shrinks the near edge, dy extends the far
        edge), applied HERE to the TARGET's OWN NOMINAL (undeposited)
        extents against a FOREIGN pass, instead of a feature's own
        official pass(es) against its own already-shadowed extents.

        The resulting ghost width, LW - PMMA*tan(alpha), falls straight
        out of this: (plus_extent + dy*a) - (-minus_extent + dx*a) = LW
        - (dx - dy)*a = LW - PMMA*tan(alpha)*a (dx - dy =
        PMMA*tan(alpha)/1000 exactly, by construction of
        _shadow_dxdy/compute_overlap_shadow_bounds) -- thinning to zero
        for a small enough linewidth, matching the observed physical
        behavior.

        A ghost only genuinely exists when this coated interval is
        DISJOINT from the target's own nominal span -- entirely past
        one wall, not merely touching or extending past it (touching/
        extending past it is just the ordinary, already-modeled cross-
        axis extend/shrink every real depositing feature already gets
        via _cross_axis_boundaries itself, not a defect). It spans the
        target's FULL nominal length, not clipped to the depositing
        feature's own crossing footprint: the ghost linewidth spans the
        entire length of the trench the deposited metal can enter, which
        is why it is so detrimental -- if it makes a full connection
        with the electrode on the other side, the entire junction would
        short.

        `foreign_records` is the pool of OTHER features' own deposition
        passes to check against (see _all_deposition_pass_records /
        _foreign_pass_records -- callers must exclude the target's own
        records first). Each qualifying pass's sliver carries that
        pass's OWN kind/feature_index/thickness for attribution -- there
        is deliberately no separate visual distinction for a ghost
        sliver, since its existence is the warning: it renders as the
        same color as the deposition step/feature that deposited it, so
        callers render the returned sliver exactly as a normal band of
        that kind/thickness, never a separate hue.

        Returns a list of {"pts": [4 pts], "kind", "feature_index",
        "thickness"} dicts, one per foreign pass that actually produces
        a disjoint sliver (0, 1, or more -- e.g. passes on either side of
        a two-pass finger's own theta list could each favor a different
        edge of a DIFFERENT target).

        `junction`/`alpha_deg`: a ghost sliver is real metal from a
        FOREIGN pass, so if the TARGET's own footprint (`nominal_pts`)
        crosses the electrode's topographic step -- the exact same
        crossing _compute_electrode_shadow_region already finds for a
        feature's own official pass -- that same step also blocks this
        foreign pass's metal wherever it falls on the substrate side
        beyond the crossing edge. Reuses the shared
        _electrode_shadow_strip helper (the raw, unclipped shadow-strip
        geometry _compute_electrode_shadow_region itself intersects
        against a feature's own polygon) rather than that function
        directly, since a ghost sliver lives OUTSIDE the target's own
        (narrow) nominal polygon by construction -- intersecting against
        the strip's own raw geometry and subtracting it from the
        sliver rectangle here is the correct reuse, not a parallel
        reimplementation. Both are optional and default to None so any
        caller that genuinely can't supply them degrades to the old,
        un-shadowed sliver rather than crashing.

        Each record in `foreign_records` may also carry its OWN resolved
        `"dx_um"`/`"dy_um"`/`"alpha"` keys (stamped on by
        _all_deposition_pass_records -- see that function's own
        docstring), used here via `rec.get(...)` in preference to the
        shared `dx_um`/`dy_um`/`alpha_deg` params -- this is what lets a
        per-pass alpha genuinely change WHICH ghost slivers appear and
        how wide they are, instead of every foreign pass being checked
        against one shared shadow-throw regardless of its own real
        tilt. An old-style record with no such keys (e.g. the 4 direct
        test-constructed records in test_ghost_junction_lines.py) falls
        back to the shared params exactly as before -- fully backward
        compatible."""
        if not nominal_pts or not foreign_records:
            return []
        cx, cy = origin

        def perp_proj(p):
            return (p[0] - cx) * perp_hat[0] + (p[1] - cy) * perp_hat[1]

        def axis_proj(p):
            return (p[0] - cx) * axis_hat[0] + (p[1] - cy) * axis_hat[1]

        plus_extent = max(perp_proj(p) for p in nominal_pts)
        minus_extent = -min(perp_proj(p) for p in nominal_pts)
        ax_min = min(axis_proj(p) for p in nominal_pts)
        ax_max = max(axis_proj(p) for p in nominal_pts)
        EPS = 1e-9

        def _pt(ax_v, perp_v):
            return (cx + axis_hat[0] * ax_v + perp_hat[0] * perp_v,
                    cy + axis_hat[1] * ax_v + perp_hat[1] * perp_v)

        out = []
        for rec in foreign_records:
            rec_dx = rec.get("dx_um", dx_um)
            rec_dy = rec.get("dy_um", dy_um)
            align = self._shadow_alignment(perp_hat, rec["theta"])
            a = abs(align)
            if a <= EPS:
                continue
            if align >= 0:
                b_minus = -minus_extent + rec_dx * a
                b_plus = plus_extent + rec_dy * a
                disjoint = b_minus > plus_extent + EPS
            else:
                b_plus = plus_extent - rec_dx * a
                b_minus = -minus_extent - rec_dy * a
                disjoint = b_plus < -minus_extent - EPS
            if not disjoint or b_plus - b_minus <= EPS:
                continue
            pts = [_pt(ax_min, b_minus), _pt(ax_min, b_plus), _pt(ax_max, b_plus), _pt(ax_max, b_minus)]
            sliver_pts_list = [pts]
            # See this function's own docstring (`junction`/`alpha_deg`
            # above): carve away whatever part of this foreign-pass sliver falls
            # inside the electrode's own topographic shadow at THAT
            # pass's own theta, using the target's own crossing edge.
            if junction is not None and alpha_deg is not None:
                try:
                    strip = self._electrode_shadow_strip(junction, nominal_pts, rec["theta"], rec.get("alpha", alpha_deg))
                except Exception:
                    strip = None
                if strip is not None and not strip.is_empty:
                    try:
                        remaining = sg.Polygon(pts).difference(strip.buffer(0.002, join_style=2))
                        pieces = list(remaining.geoms) if hasattr(remaining, "geoms") else [remaining]
                        sliver_pts_list = [list(piece.exterior.coords) for piece in pieces
                                           if hasattr(piece, "exterior") and piece.exterior is not None
                                           and piece.area > 1e-9]
                    except Exception:
                        pass  # fall back to the un-shadowed sliver rather than dropping it
            for sliver_pts in sliver_pts_list:
                out.append({"pts": sliver_pts, "kind": rec["kind"], "feature_index": rec["feature_index"],
                            "thickness": rec["thickness"]})
        return out

    def _triangle_anomaly_slivers(self, junction, all_records, dy_um, pmma_nm, pmgi_nm, alpha_fallback):
        """Section 7a of shadowing_design_rules.md: "triangular
        deposition artifacts" -- small triangles of FOREIGN metal landing
        in the small pocket left open right where two crossing trenches'
        own PMGI undercuts meet, whenever some OTHER pass's azimuth isn't
        aligned with either trench's own axis. Matches a real SEM
        image and, independently, a hand-marked annotation on a
        boundaries-only rendering (pixel-measured to land on this exact
        construction) -- see section 7a for the full derivation this
        reproduces. Ships using the EXISTING `dy = t_PMGI * tan(alpha)`
        placeholder (there is no per-design empirical alternative in a
        tool whose whole point is simulating a design BEFORE it's ever
        put through the Plassys).

        The two "crossing trenches" forming the pocket are not limited
        to a junction's own two (perpendicular) FINGERS -- ANY two of
        {finger, plate, patch} shapes that actually cross, at ANY angle
        short of parallel, get checked, so a patch crossing a finger, a
        patch crossing an adhesion plate, or a plate crossing a finger
        all go through the same construction. The depositing pass does
        not need to bisect the crossing at ~45deg either. Unlike
        _ghost_junction_slivers (one target feature's own aperture vs
        every OTHER feature's passes), this defect belongs to the
        CROSSING itself, so it's computed once
        per junction from the full `all_records` pool, not once per
        target inside a per-feature loop. A trench's own pass can never
        trigger an anomaly at its own crossing: its azimuth is aligned
        with its own axis, so its perpendicular projection is exactly
        zero -- in practice only a genuinely different-angle pass (almost
        always a patch) ever qualifies, matching every real report of
        this defect so far.

        RIGHT-ANGLE ASSUMPTION ELIMINATED: assuming a right triangle is
        incorrect whenever the trenches are not perpendicular to each
        other. A construction that instead fixed the triangle's
        "hypotenuse" at exactly 45deg off each trench's own axis, no
        matter what theta actually was, only coincidentally matched
        reality when a pass happened to bisect the crossing at 45deg --
        at other angles (even a 5deg change in a patch's theta) it made
        the triangle disappear entirely.
        Derived from section 7a's own 3 boundaries, with
        genuine line-line intersections in absolute (x,y) coordinates
        (never an oblique-basis shortcut, which would silently assume
        perpendicularity), for trench U (axis `u_hat`, half-width `s_u`)
        and trench V (axis `v_hat`, half-width `s_v`) crossing at
        `origin`, a pass with azimuth `theta_hat`, `perp_u`/`perp_v` each
        trench's own perpendicular, `align_u = perp_u . theta_hat`,
        `align_v = perp_v . theta_hat` (the same per-trench alignment
        factor `_ghost_junction_slivers` uses for that trench's own
        ghost-sliver check):

            boundary-1 (one leg): trench U's own edge, WIDENED by `dy`,
              i.e. the line through `origin + sign(align_u)*(s_u+dy)*
              perp_u`, running along `u_hat` -- a wet-develop (PMGI
              undercut) property, independent of any pass's tilt.
            boundary-3 (the other leg): trench V's own edge, SHRUNK by
              this pass's shadow, i.e. the line through
              `origin - sign(align_v)*(s_v - dx*|align_v|)*perp_v`,
              running along `v_hat` -- identical convention to
              `_ghost_junction_slivers`' own near-wall shrink for that
              same trench.
            boundary-2 (the THIRD side, the "hypotenuse" -- this is what
              was missing before): the line through the ADJACENT
              quadrant's TRUE NOMINAL (un-widened, un-shrunk) corner,
              running along `theta_hat` ITSELF -- not a fixed 45deg
              offset from either trench's axis. This is exactly what
              makes the triangle's third side actually rotate with the
              real deposition angle typed into that step, continuously,
              for any crossing angle between the two trenches (acute or
              obtuse) and any pass azimuth -- matching the physical
              picture: every individual patch has its own quadrants that
              form acute and obtuse angles that depend on the angles of
              the finger trench, the adhesion plate trench, and the
              patch trenches.

        The triangle's 3 vertices are simply the 3 pairwise intersections
        of these boundaries: `apex` = boundary-1 x boundary-3 (this part
        is UNCHANGED from before -- it's what test 9 already verifies
        bit-for-bit against `_ghost_junction_slivers`' own near edge, for
        any crossing angle), `far_u` = boundary-1 x boundary-2, `far_v` =
        boundary-3 x boundary-2. Verified to exactly (bit-for-bit)
        reproduce the one real, SEM/pixel-verified case (perpendicular
        fingers, an exact-45deg-bisecting pass) -- there the three
        boundaries happen to meet at exactly 45deg to each other,
        reproducing the old isoceles-right numbers exactly by construction,
        not by coincidence. Off that one special case (any other angle,
        or any oblique trench pair), the triangle is a genuine, generally
        SCALENE triangle whose shape depends on the real angle between
        the two trenches and the real pass azimuth -- there is no "right
        angle" anywhere in this construction except where the geometry
        itself happens to produce one.

        EXISTENCE CONDITION: a real V-apex/endpoint-style junction -- two
        fingers meeting AT a shared point rather than crossing THROUGH
        each other, e.g. a diagonal/"rotated" Manhattan design -- must
        still show a triangle, since the design's own resist notch that
        should catch foreign metal is plainly there. A test based on
        `align_u`/`align_v` having opposite signs looks like a clean
        geometric test but is actually just an accident of WHICH WAY
        `u_hat`/`v_hat` happen to point along their own (otherwise
        arbitrary/undirected) axis lines -- `_trench_axis`/
        `_polygon_axis_and_ends` have no obligation to agree on that
        convention from one real design to another, and flipping either
        one flips `align_u`'s or `align_v`'s sign without changing the
        real geometry at all, silently flipping this test's verdict. The
        one real, SEM/pixel-confirmed case (mid-span "+"-style crossing)
        and a real V-apex junction (fingers meeting at a shared endpoint)
        are both genuinely valid, triangle-producing configurations, but
        they need OPPOSITE `align_u`/`align_v` sign patterns for the
        exact same physical reason -- one arbitrary formula cannot cover
        both.

        Real, referentially-transparent existence test: `apex`
        (the vertex that slides as this pass's own `dx` shrinks
        boundary-3) must still sit on the SAME side of boundary-2 (the
        far, theta_hat-aligned line through `q_adj`) as the crossing
        `origin` itself -- once a big enough `dx` pushes `apex` PAST
        boundary-2, the pocket has been shadowed shut. This is built
        entirely from real positions (`apex`, `origin`, `q_adj`) and
        `theta_hat` (the pass's own real azimuth, never an arbitrary
        trench-axis labeling), so it cannot depend on which way either
        trench's own axis happens to be drawn -- flipping `u_hat` or
        `v_hat` moves `apex`/`q_adj`/`origin` not at all (all three are
        already invariant to that flip), so this test is too. Verified
        bit-for-bit against the one real, SEM/pixel-confirmed case
        (reproduces the exact same alpha=45deg leg=55.75nm number, AND the
        exact same alpha~=46deg closure point implied by that confirmed
        formula's own `leg=0` solution) and against the real V-apex
        junction (correctly shows a triangle that shrinks toward zero,
        then closes, as alpha climbs from 30 to ~46deg, matching the
        physical expectation that the triangles get significantly
        smaller as alpha increases in that range). A clean side effect,
        preserved from the previous (wrong) formula: the "onU"/"onV"
        pair still exists or vanishes TOGETHER for every case checked so
        far.

        STEEP-ALPHA "CLOSES THE POCKET": boundary-1 and boundary-2 are
        both independent of `dx` so only boundary-3 moves; a purely
        Euclidean read of the triangle-leg lengths could suggest
        increasing `dx` can only make the pocket LARGER, but that misses
        that the real, SIGNED quantity being measured (how far `apex`
        sits from crossing over boundary-2) passes through zero and goes
        negative -- so the triangle's legs appear to shrink, hit a
        minimum, and then "grow again," which is a real closure followed
        by a spurious wrong-side re-opening, not a real re-growth. The
        SIGNED test above (`side_apex`/`side_origin`) tracks the same
        physical quantity the model is meant to describe (existing only
        while leg > 0 -- a bigger tilt leaves less room for stray metal
        to land) and correctly stops at the zero crossing instead of
        continuing past it: at a fixed qualifying theta, the leg shrinks
        monotonically as alpha increases and the pocket closes for good
        beyond a specific alpha, reproduced by the fully general
        (non-isoceles) construction.

        A separate, secondary safety net remains: every trench is a real,
        FINITE edge, not an infinite line, so a vertex that would need to
        sit beyond a trench's own actual length (past its own stub/patch
        ends, or its own polygon ends for a plate/patch) still gets
        dropped (`max(length*0.5, half_width*3)` tolerance, same style as
        this function's own trench-pair crossing-point sanity check).
        This mainly catches a DIFFERENT failure mode than pocket closure:
        a pass azimuth only a few degrees off from one trench's own axis
        (`a_u`/`a_v` small but not zero) can still swing `far_u`/`far_v`
        out to an enormous, physically-meaningless distance (the
        `theta_hat`-aligned boundary-2 line becomes nearly parallel to
        that trench's own axis), and this clip is what keeps such a shard
        from being drawn. Still a reasonable modeling default, not
        independently SEM-confirmed the way the core 3-boundary
        construction is -- revisit the tolerance specifically if a real
        design's report disagrees with it.

        Returns a list of {"pts": [3 pts], "kind", "feature_index",
        "thickness", "merge_finger_index", "pair_kinds", "pass_theta"}
        dicts -- the first 4 keys are the same shape as
        _ghost_junction_slivers' own output, meant to be appended into
        the same flat `shapes` list with is_ghost=True (this is foreign
        metal, not either finger's own official footprint).
        `merge_finger_index` (NEW) names which finger's own
        ghost-sliver group this triangle should be merged into when one
        from the SAME pass touches it there -- see
        _merge_triangle_group_id, which callers use to avoid a visible
        white-outline seam between two pieces of what is, physically,
        the exact same deposited metal."""
        if junction is None or not all_records:
            return []

        # The pocket-forming mechanism below does not require the two
        # crossing apertures to be a junction's own two (perpendicular)
        # FINGERS -- any two of {finger, plate, patch} trenches that
        # actually cross, at ANY angle short of parallel, go through the
        # exact same construction (patches intersecting a junction
        # finger or an adhesion plate included: every individual patch
        # has its own quadrants forming acute and obtuse angles that
        # depend on the angles of the finger trench, the adhesion plate
        # trench, and the patch trenches). It also does not require the
        # depositing pass to bisect the crossing at ~45deg -- any pass
        # not aligned with either trench's own axis qualifies, per a
        # real-position existence test (`apex` still on the same side of
        # boundary-2 as the crossing `origin`) -- see this function's
        # own docstring for the full existence derivation (a test based
        # on `align_u`/`align_v` having opposite signs was tried and
        # replaced: it silently depended on an arbitrary
        # trench-axis-direction convention that a real V-apex/endpoint-
        # style junction does not share with the confirmed, mid-span-
        # style crossing).
        #
        # Every quantity below is built from genuine line-line
        # intersections in absolute (x,y) coordinates -- not an
        # oblique-basis (cu,cv) shortcut, which would silently assume the
        # two trenches are perpendicular. Verified to reproduce the
        # ORIGINAL, still-shipped finger-finger formula bit-for-bit at
        # the one real, SEM/pixel-confirmed case (perpendicular fingers,
        # an exact-45deg-bisecting pass) -- see
        # test_triangle_deposition_anomaly.py. The RIGHT-ANGLE isoceles
        # assumption used everywhere else is eliminated: the triangle's
        # third side genuinely runs along the pass's own azimuth
        # (`theta_hat`), continuously, for any crossing angle and any
        # pass angle -- see the docstring's "RIGHT-ANGLE ASSUMPTION
        # ELIMINATED" section for the full derivation, the real-position
        # existence test, and the "steep alpha closes the pocket" claim.
        def _trench_axis(pt_a, pt_b):
            fx, fy = pt_b[0] - pt_a[0], pt_b[1] - pt_a[1]
            flen = math.hypot(fx, fy) or 1.0
            return (fx / flen, fy / flen), math.degrees(math.atan2(fy, fx)) % 360

        trenches = []
        for i, f in enumerate(getattr(junction, "fingers", None) or []):
            axis_hat, axis_deg = _trench_axis(f.stub_end, f.patch_end)
            trenches.append({"axis_hat": axis_hat, "axis_deg": axis_deg,
                              "half_width": f.width_um / 2.0, "end_a": f.stub_end, "end_b": f.patch_end,
                              "kind": "finger", "feature_index": i})
        for s in getattr(junction, "other_shapes", None) or []:
            if getattr(s, "kind", None) not in ("plate", "patch") or not getattr(s, "points", None):
                continue
            try:
                axis_deg, end_a, end_b, width = ji._polygon_axis_and_ends(s.points)
            except Exception:
                continue
            axis_hat = (math.cos(math.radians(axis_deg)), math.sin(math.radians(axis_deg)))
            trenches.append({"axis_hat": axis_hat, "axis_deg": axis_deg,
                              "half_width": width / 2.0, "end_a": end_a, "end_b": end_b,
                              "kind": s.kind, "feature_index": None})
        if len(trenches) < 2:
            return []

        def _perp(d):
            return (-d[1], d[0])

        def _line_x(p1, d1, p2, d2):
            denom = d1[0] * d2[1] - d1[1] * d2[0]
            if abs(denom) < 1e-12:
                return None, None
            ddx, ddy = p2[0] - p1[0], p2[1] - p1[1]
            t = (ddx * d2[1] - ddy * d2[0]) / denom
            return (p1[0] + t * d1[0], p1[1] + t * d1[1]), t

        def _add(p, v, s):
            return (p[0] + v[0] * s, p[1] + v[1] * s)

        out = []
        for i in range(len(trenches)):
            for j in range(i + 1, len(trenches)):
                ta, tb = trenches[i], trenches[j]
                ua_hat, ub_hat = ta["axis_hat"], tb["axis_hat"]
                if abs(ua_hat[0] * ub_hat[0] + ua_hat[1] * ub_hat[1]) > 0.999:
                    continue  # parallel (or coincident) axes -- no real crossing
                origin = ji.axis_line_intersection(ta["end_a"], ta["axis_deg"], tb["end_a"], tb["axis_deg"])
                if origin is None:
                    continue
                # Sanity check: the two trenches' own axis LINES cross
                # somewhere, but that doesn't mean the two actual (finite)
                # shapes physically meet there -- a patch on the far side
                # of a design and an unrelated finger's own axis, extended
                # indefinitely, could "cross" too. Require the crossing
                # point to fall within (a generous margin around) BOTH
                # trenches' own real extent -- fingers always pass this by
                # construction (they physically cross), plates/patches
                # only pair up with a finger/plate/patch they actually run
                # into.
                #
                # A trench's own "axis_hat" is not guaranteed to point
                # from its own end_a toward its own end_b -- for a
                # finger it does (_trench_axis builds it that way), but
                # for a plate/patch, junction_import._polygon_axis_and_
                # ends' own axis_deg can come back ANTI-parallel to
                # (end_b - end_a) (confirmed on a synthetic 60deg plate),
                # where assuming end_b always sits at t=+len would
                # silently put every extent check on the wrong side of
                # end_a. Compute each trench's OWN signed extent range
                # (`[0, t_end_b]`, in whichever order that actually
                # falls) instead of assuming `[0, +len]`.
                def _extent_range(end_a, end_b, axis_hat):
                    t_end_b = (end_b[0] - end_a[0]) * axis_hat[0] + (end_b[1] - end_a[1]) * axis_hat[1]
                    return (min(0.0, t_end_b), max(0.0, t_end_b))

                lo_a, hi_a = _extent_range(ta["end_a"], ta["end_b"], ua_hat)
                lo_b, hi_b = _extent_range(tb["end_a"], tb["end_b"], ub_hat)
                len_a = hi_a - lo_a or 1.0
                len_b = hi_b - lo_b or 1.0
                pa = (origin[0] - ta["end_a"][0]) * ua_hat[0] + (origin[1] - ta["end_a"][1]) * ua_hat[1]
                pb = (origin[0] - tb["end_a"][0]) * ub_hat[0] + (origin[1] - tb["end_a"][1]) * ub_hat[1]
                tol_a = max(len_a * 0.5, ta["half_width"] * 3.0)
                tol_b = max(len_b * 0.5, tb["half_width"] * 3.0)
                if not (lo_a - tol_a <= pa <= hi_a + tol_a) or not (lo_b - tol_b <= pb <= hi_b + tol_b):
                    continue

                perp_a, perp_b = _perp(ua_hat), _perp(ub_hat)
                s_a, s_b = ta["half_width"], tb["half_width"]
                lohi_a_real, lohi_b_real = (lo_a, hi_a), (lo_b, hi_b)
                tol_extent_a, tol_extent_b = tol_a, tol_b

                def _one_side(u_hat, s_u, end_u_a, lohi_u, tol_u,
                               v_hat, s_v, end_v_a, lohi_v, tol_v,
                               theta_hat, rec_dx, rec_dy, merge_idx, rec):
                    """The 'onU' pocket: boundary-1 = trench U's own
                    dy-WIDENED edge (parallel to u_hat); boundary-3 =
                    trench V's own dx-SHRUNK edge (parallel to v_hat,
                    identical convention to _ghost_junction_slivers' own
                    near-wall shrink); boundary-2 = the line through the
                    ADJACENT quadrant's TRUE NOMINAL (un-widened,
                    un-shrunk) corner, running along theta_hat -- this is
                    what makes the triangle's third side actually track
                    the pass's own angle, instead of being forced
                    perpendicular to the first leg. See this function's
                    own docstring for the full re-derivation."""
                    perp_u, perp_v = _perp(u_hat), _perp(v_hat)
                    align_u = theta_hat[0] * perp_u[0] + theta_hat[1] * perp_u[1]
                    align_v = theta_hat[0] * perp_v[0] + theta_hat[1] * perp_v[1]
                    a_u, a_v = abs(align_u), abs(align_v)
                    # GRAZING-INCIDENCE EXCLUSION, widened from a bare
                    # Exact-parallel check: a deposition pass only a few
                    # degrees off a patch/plate's own axis (e.g. a few
                    # degrees away from the nominal design angle) can
                    # produce shard-like structures whose vertices fall
                    # well outside the resist border. `a_u`/`a_v` is
                    # |sin(angle between this pass and that trench's own
                    # axis)|; `far_u`/`far_v` come from intersecting
                    # boundary-1/boundary-3 with boundary-2 (the line along
                    # theta_hat), so as either angle shrinks toward 0 the
                    # intersection is between two increasingly near-
                    # parallel lines and the vertex distance grows as
                    # roughly 1/a_u (or 1/a_v) -- smoothly, without any
                    # natural bound, confirmed numerically down to tens of
                    # microns for a sub-degree offset. There is no
                    # "physical" leg-length cutoff for this (see the SHARD
                    # GUARD below for that backstop); the real problem is
                    # that near grazing incidence the whole 3-boundary
                    # construction stops approximating a localized corner
                    # pocket at all. `0.3` (~17.5deg) sits safely below
                    # every angle any confirmed/regression case has ever
                    # used (smallest: sin(20deg)=0.342, this file's own
                    # "well off the 45deg bisector" test) with real margin,
                    # while cutting off the near-degenerate patch/plate
                    # pairs that only appear once a patch pass drifts a
                    # handful of degrees from its design's own patch axis.
                    if a_u < 0.3 or a_v < 0.3:
                        return None  # pass too close to grazing along one trench's own axis -- no reliable anomaly
                    su_sign = 1.0 if align_u >= 0 else -1.0
                    sv_sign = 1.0 if align_v >= 0 else -1.0

                    edgeU_pt = _add(origin, perp_u, su_sign * (s_u + rec_dy))
                    edgeV_shrunk_pt = _add(origin, perp_v, -sv_sign * (s_v - rec_dx * a_v))
                    apex, _t = _line_x(edgeU_pt, u_hat, edgeV_shrunk_pt, v_hat)
                    if apex is None:
                        return None
                    q_adj, _t2 = _line_x(_add(origin, perp_u, -su_sign * s_u), u_hat,
                                          _add(origin, perp_v, sv_sign * s_v), v_hat)
                    if q_adj is None:
                        return None
                    far_u, _t3 = _line_x(edgeU_pt, u_hat, q_adj, theta_hat)
                    far_v, _t4 = _line_x(edgeV_shrunk_pt, v_hat, q_adj, theta_hat)
                    if far_u is None or far_v is None:
                        return None

                    # EXISTENCE, re-re-derived: a real V-apex/endpoint-style
                    # junction -- e.g. two fingers meeting AT a shared point
                    # rather than crossing THROUGH each other -- showed no
                    # triangle at all even though the resist notch that
                    # should catch foreign metal there is clearly present.
                    # The old
                    # `align_u*align_v>=0` pre-filter looked like a clean
                    # geometric test but was secretly just an artifact of
                    # WHICH WAY `u_hat`/`v_hat` happen to point along their
                    # own (otherwise arbitrary/undirected) axis lines --
                    # `_trench_axis`/`_polygon_axis_and_ends` have no
                    # obligation to agree on that convention from one real
                    # design to another, and flipping either one flips
                    # `align_u` or `align_v`'s sign without changing the
                    # real geometry at all, silently flipping this test's
                    # verdict. Real, referentially-transparent existence
                    # test instead: `apex` (the vertex that slides as this
                    # pass's own `dx` shrinks boundary-3) must still sit on
                    # the SAME side of boundary-2 (the far, theta_hat-
                    # aligned line through `q_adj`) as the crossing
                    # `origin` itself -- once a big enough `dx` pushes
                    # `apex` PAST boundary-2, the pocket has been shadowed
                    # shut. This is built entirely from real positions
                    # (`apex`, `origin`, `q_adj`) and `theta_hat` (the
                    # pass's own real azimuth, never an arbitrary trench-
                    # axis labeling), so it cannot depend on which way
                    # either trench's own axis happens to be drawn.
                    # Verified bit-for-bit against a real, SEM/pixel-
                    # measured reference case (reproduces the exact same
                    # alpha=45deg leg=55.75nm number, and the exact same
                    # alpha~=46deg closure point implied by that measured
                    # formula) AND against a real V-apex junction geometry
                    # (correctly shows a triangle that shrinks toward zero,
                    # then closes, as alpha climbs -- see "STEEP ALPHA..."
                    # below).
                    perp_theta = _perp(theta_hat)
                    side_apex = (apex[0] - q_adj[0]) * perp_theta[0] + (apex[1] - q_adj[1]) * perp_theta[1]
                    side_origin = (origin[0] - q_adj[0]) * perp_theta[0] + (origin[1] - q_adj[1]) * perp_theta[1]
                    if side_apex * side_origin <= 0.0:
                        return None

                    # SHARD GUARD: patch passes only a few degrees off a
                    # patch/plate's own axis (e.g. a few degrees away from
                    # the nominal design angle) can produce shard-like
                    # structures whose vertices make no physical sense,
                    # either falling well outside the resist border or
                    # being inconsistent and too large.
                    # Root cause: `far_u`/`far_v` are found by intersecting
                    # boundary-1/boundary-3 with boundary-2 (the line along
                    # `theta_hat`). When this pass's azimuth drifts close
                    # to being PARALLEL to one trench's own axis (a_u or
                    # a_v small but well above the `1e-6` hard-parallel
                    # exclusion above), that intersection is between two
                    # near-parallel lines and the resulting vertex shoots
                    # out to a distance that scales as roughly 1/a_u (or
                    # 1/a_v) -- continuously and without any natural
                    # cutoff, confirmed numerically (a patch pass only 5deg
                    # off its own patch's 135deg axis here already produces
                    # a >3.5um leg from a <=0.15um-half-width, <=6.9um-long
                    # patch). Critically, the resulting vertex can still
                    # land WITHIN that trench's own real finite length (as
                    # it does here), so the finite-extent clip below -- by
                    # design generous, for a different job: rejecting a
                    # crossing whose own trenches don't really meet at all
                    # -- cannot and should not be tightened to catch this.
                    # This whole construction is inherently a LOCAL, near-
                    # corner phenomenon (foreign metal landing right at a
                    # crossing), so a real triangle's own legs should stay
                    # comparable to the local physical scale actually
                    # driving its size -- the two trenches' half-widths
                    # plus this pass's own shadow throw and the uniform
                    # wet-develop dy. Reject once a leg grows well beyond
                    # that scale. Verified against every existing
                    # confirmed/regression case (largest observed ratio
                    # ~0.6x this scale, test_triangle_deposition_anomaly.py
                    # test 4) with wide margin below the cutoff, and
                    # against a real shard reproduction case (ratio
                    # already ~2.4x by 5deg off-axis, growing without
                    # bound as the pass approaches the trench's own axis).
                    local_scale = s_u + s_v + rec_dx + rec_dy
                    leg_u = math.hypot(far_u[0] - apex[0], far_u[1] - apex[1])
                    leg_v = math.hypot(far_v[0] - apex[0], far_v[1] - apex[1])
                    if max(leg_u, leg_v) > 1.0 * local_scale:
                        return None

                    # Finite-extent sanity clip: boundary-1/boundary-2's
                    # own intersection (far_u) never moves with dx/alpha
                    # at all, but the apex and far_v DO (through the
                    # dx-shrunk boundary-3) -- as alpha steepens they
                    # slide further from the crossing without bound. A
                    # trench is a real, FINITE PMGI/PMMA edge, not an
                    # infinite line, so once a vertex would sit beyond a
                    # trench's own actual length (plus a generous
                    # margin), there is no physical edge left there to
                    # bound the pocket. This -- not a leg-length formula
                    # -- is the real, principled mechanism by which a
                    # steep enough alpha eventually closes the pocket;
                    # unlike the core 3-boundary construction (SEM/pixel
                    # confirmed), this specific clip is a reasonable
                    # modeling default, not independently confirmed --
                    # revisit the tolerance if a real design disagrees.
                    def _within(pt, end_a, axis_hat, lohi, tol):
                        t = (pt[0] - end_a[0]) * axis_hat[0] + (pt[1] - end_a[1]) * axis_hat[1]
                        lo, hi = lohi
                        return lo - tol <= t <= hi + tol

                    if not (_within(apex, end_u_a, u_hat, lohi_u, tol_u)
                            and _within(far_u, end_u_a, u_hat, lohi_u, tol_u)
                            and _within(apex, end_v_a, v_hat, lohi_v, tol_v)
                            and _within(far_v, end_v_a, v_hat, lohi_v, tol_v)):
                        return None

                    return {"pts": [far_u, apex, far_v], "kind": rec["kind"],
                            "feature_index": rec["feature_index"], "thickness": rec["thickness"],
                            "merge_finger_index": merge_idx,
                            # NEW: which two TRENCHES this triangle sits between (not the
                            # depositing pass's own kind above) -- lets a caller tell a
                            # junction-centric triangle (both "finger") apart from a
                            # patch-centric one (anything involving a patch/plate), used by
                            # _check_triangle_anomaly_warnings to consolidate warnings.
                            "pair_kinds": (ta["kind"], tb["kind"]),
                            "pass_theta": rec["theta"]}

                for rec in all_records:
                    theta_hat = (math.cos(math.radians(rec["theta"])), math.sin(math.radians(rec["theta"])))
                    # dy stays the caller's own UNIFORM value (a wet-develop
                    # property, independent of any specific pass's tilt --
                    # see this function's own docstring/section 7a); dx is
                    # THIS pass's own full-stack shadow throw.
                    rec_dy = dy_um
                    rec_dx = rec.get("dx_um")
                    if rec_dx is None:
                        rec_dx, _unused = self._shadow_dxdy(pmma_nm, pmgi_nm, rec.get("alpha", alpha_fallback))

                    tri_a = _one_side(ua_hat, s_a, ta["end_a"], lohi_a_real, tol_extent_a,
                                       ub_hat, s_b, tb["end_a"], lohi_b_real, tol_extent_b,
                                       theta_hat, rec_dx, rec_dy, 1, rec)
                    if tri_a is not None:
                        out.append(tri_a)
                    tri_b = _one_side(ub_hat, s_b, tb["end_a"], lohi_b_real, tol_extent_b,
                                       ua_hat, s_a, ta["end_a"], lohi_a_real, tol_extent_a,
                                       theta_hat, rec_dx, rec_dy, 0, rec)
                    if tri_b is not None:
                        out.append(tri_b)
        return out

    def _merge_triangle_group_id(self, tri_pts, kind, thickness, finger_index, shapes, next_group_id_fn):
        """REVERTED: an earlier `allowed_group_ids` finger-scoping added
        here did not fix a triangle/ghost-line misalignment that turned
        out to be a real geometry problem, not a merge/outline-grouping
        one -- and restricting merge candidates by finger index made the
        picture actively worse: a triangle and a same-kind/thickness
        shape it genuinely overlaps would now draw as two separately-
        outlined pieces instead of one union, reintroducing a seam/
        white-line-through-the-triangle artifact for exactly the
        touching-but-different-finger case this revert removes the
        restriction for. Back to the original, simpler rule: a triangle
        merges with the first existing shape of the same (kind,
        thickness) it geometrically touches, full stop.

        Fix: a Post-Shadow Result view showing a distracting
        white line cutting straight through a triangle revealed that a
        triangular deposition anomaly and the ghost-junction-line sliver
        it sits beside are the exact same physical event -- one foreign
        pass's own metal, landing partly as a long sliver in the
        adjacent finger's aperture and partly as this triangle right at
        the corner -- so they should share ONE white outline (per
        _draw_shadow_shapes' own per-group_id union-outline mechanism),
        not two separate ones that leave a seam wherever they touch or
        overlap.

        `finger_index` (_triangle_anomaly_slivers' own
        `merge_finger_index`) names which finger this triangle sits
        beside, kept here for documentation/future use, but NOT used to
        filter `shapes` directly -- a ghost sliver's own tuple carries
        the DEPOSITING pass's kind/feature_index (matching this
        triangle's own, since both come from the same record), not the
        TARGET finger's identity, so there's no target-finger field to
        match against there. Matched instead by (kind, thickness) plus
        real geometric adjacency (shapely `intersects`, not exact vertex
        equality, since floating point and the two different
        derivations -- ghost slivers vs. this triangle's own vertex
        formulas -- can leave a hairline gap or overlap even when they
        are, physically, the same edge)."""
        try:
            tri_poly = sg.Polygon(tri_pts).buffer(0.001, join_style=2)
        except Exception:
            return next_group_id_fn()
        for pts, s_kind, _s_finger_idx, s_thickness, gid, _is_ghost in shapes:
            if s_kind != kind or s_thickness != thickness:
                continue
            try:
                if tri_poly.intersects(sg.Polygon(pts).buffer(0.001, join_style=2)):
                    return gid
            except Exception:
                continue
        return next_group_id_fn()

    def _find_electrode_crossing_line(self, junction, feature_points):
        """Where the feature's OWN edges actually cross the electrode
        boundary -- confirmed to be the right way to find the relevant
        local edge, replacing an earlier "nearest electrode edge to a
        point" approach that picked up an irrelevant, distant edge on
        real geometry. Verified with a synthetic case giving exactly the
        two expected crossing points before using this on real designs.
        Returns (p1, p2), the two points where the feature's boundary
        crosses the electrode's boundary, or None if the feature doesn't
        actually cross it at all (e.g. an adhesion plate that never
        touches the electrode -- confirmed this distinction matters on
        real designs: a plate typically gives zero crossings while its
        associated finger gives exactly two).

        Significant bug fix (matches real designs with
        distinct electrode-material and electrode-hole geometry): this
        used to build
        electrode_union from junction.electrode_material -- the
        "actual drawn Nb metal" background set kept ONLY for display
        (correctly used elsewhere, e.g. _mill_highlighted_edges' own
        ion-mill target) -- instead of junction.electrode_polygons, the
        real hole/contact region _assign_warning_sources and every
        OTHER warning-math function in this app already agree is "the
        electrode" for crossing/contact purposes. For a GDS import
        these come from two genuinely different queries (nearby_holes
        vs. nearby_material in junction_import.import_gds_cell) and are
        NOT the same shapes -- a finger correctly classified
        warning_source="finger" (it DOES cross electrode_polygons)
        could easily not cross electrode_material at all, so this
        silently returned None (no crossing found) even on a design
        where Warning #1 clearly applies. That broke BOTH consumers:
        the electrode-shadow hatch overlay in Simulated Design never
        appeared for the risky angle, and (since
        _compute_finger_shadowed_pieces / _compute_one_patch_shadowed_pieces
        feed this same function to carve real post-shadow geometry)
        Post-Shadow Result never showed the resulting gap either -- one
        fix here corrects both. (For a parametric/"Created" design
        these two fields are identical anyway, per
        from_design_parameters' own comment, so this only changes
        behavior for imports -- exactly where the two real, DIFFERENT
        electrode geometries exist to disagree.)"""
        try:
            electrode_union = sg.MultiPolygon([sg.Polygon(p) for p in junction.electrode_polygons if len(p) >= 3]).buffer(0)
        except Exception:
            return None
        boundary = electrode_union.boundary
        n = len(feature_points)
        crossing_points = []
        for i in range(n):
            p1, p2 = feature_points[i], feature_points[(i+1) % n]
            edge = sg.LineString([p1, p2])
            inter = edge.intersection(boundary)
            if inter.is_empty:
                continue
            if hasattr(inter, "geoms"):
                for g in inter.geoms:
                    if hasattr(g, "x"):
                        crossing_points.append((g.x, g.y))
            elif hasattr(inter, "x"):
                crossing_points.append((inter.x, inter.y))
        if len(crossing_points) < 2:
            return None
        best_pair, best_dist = None, -1
        for i in range(len(crossing_points)):
            for j in range(i+1, len(crossing_points)):
                d = math.hypot(crossing_points[i][0]-crossing_points[j][0],
                               crossing_points[i][1]-crossing_points[j][1])
                if d > best_dist:
                    best_dist = d
                    best_pair = (crossing_points[i], crossing_points[j])
        return best_pair

    def _electrode_shadow_strip(self, junction, feature_points, theta_deg, alpha_deg):
        """Refactor (ghost-junction-line electrode shadowing --
        see _ghost_junction_slivers' own comment for the full physical
        reasoning): extracted out of
        _compute_electrode_shadow_region so the raw shadow-strip
        geometry -- everything about WHERE the electrode's topographic
        step throws its shadow, before that's clipped down to any one
        feature's own polygon -- can be reused against something other
        than the crossing feature's own footprint. Returns the strip as
        a shapely Polygon (unclipped -- typically much larger than any
        one feature), or None if the feature doesn't cross the
        electrode at all, or the computed reach is negligible.
        _compute_electrode_shadow_region itself is now a thin wrapper:
        this strip intersected with the feature's own polygon."""
        edge = self._find_electrode_crossing_line(junction, feature_points)
        if edge is None:
            return None
        try:
            electrode_height_nm = float(self.es_height_edit.text()) if hasattr(self, "es_height_edit") else 300.0
        except ValueError:
            electrode_height_nm = 300.0
        reach_nm = compute_electrode_shadow(electrode_height_nm, alpha_deg)
        reach_um = reach_nm / 1000.0
        if reach_um <= 0.005:
            return None
        p1, p2 = edge
        edge_vec = (p2[0]-p1[0], p2[1]-p1[1])
        edge_len = math.hypot(*edge_vec) or 1.0
        eu = (edge_vec[0]/edge_len, edge_vec[1]/edge_len)
        theta_rad = math.radians(theta_deg)
        reach_vec = (reach_um*math.cos(theta_rad), reach_um*math.sin(theta_rad))
        edge_mid = ((p1[0]+p2[0])/2.0, (p1[1]+p2[1])/2.0)
        # Bug: the electrode-shadowing polygon could appear on
        # the wrong side of where it should be -- over the electrode
        # itself rather than past the electrode, on the substrate. This
        # used to flip reach_vec to point toward the
        # feature's own overall centroid -- but a feature that crosses
        # the electrode boundary has points on BOTH sides of the
        # crossing edge, so "toward the centroid" just picks whichever
        # side happens to hold more of the feature's own polygon area,
        # with no actual relationship to which side is physically the
        # lower substrate. Physically the shadow can ONLY ever fall on
        # the substrate side: the electrode is a raised step (e.g.
        # 300nm tall), so it can block the beam's line of sight to the
        # substrate immediately past its own edge, but nothing can cast
        # a shadow onto the raised electrode itself from a lower
        # surface. Fixed by testing electrode_polygons membership
        # directly at a small probe offset to each side of the crossing
        # edge, and forcing reach_vec to point away from whichever side
        # that probe finds inside the electrode -- i.e. always toward
        # the substrate side, regardless of where the bulk of the
        # feature's own polygon area happens to sit.
        try:
            electrode_union = sg.MultiPolygon(
                [sg.Polygon(p) for p in junction.electrode_polygons if len(p) >= 3]).buffer(0)
        except Exception:
            electrode_union = None
        perp = (-eu[1], eu[0])
        probe_dist = max(reach_um, 0.05) * 0.25
        probe_plus = (edge_mid[0] + perp[0]*probe_dist, edge_mid[1] + perp[1]*probe_dist)
        try:
            plus_is_electrode = electrode_union is not None and electrode_union.contains(sg.Point(probe_plus))
        except Exception:
            plus_is_electrode = False
        substrate_dir = (-perp[0], -perp[1]) if plus_is_electrode else perp
        if reach_vec[0]*substrate_dir[0] + reach_vec[1]*substrate_dir[1] < 0:
            reach_vec = (-reach_vec[0], -reach_vec[1])
        extend = edge_len * 5 + 5.0
        ext_p1 = (p1[0]-eu[0]*extend, p1[1]-eu[1]*extend)
        ext_p2 = (p2[0]+eu[0]*extend, p2[1]+eu[1]*extend)
        return sg.Polygon([
            ext_p1, ext_p2,
            (ext_p2[0]+reach_vec[0], ext_p2[1]+reach_vec[1]),
            (ext_p1[0]+reach_vec[0], ext_p1[1]+reach_vec[1]),
        ])

    def _compute_electrode_shadow_region(self, junction, feature_points, theta_deg, alpha_deg):
        """The REAL 2D shadow region cast by the electrode's own
        topology onto a crossing feature -- the actual intersection of
        the feature's polygon with a shadow strip running parallel to
        the REAL crossing line (where the feature's own edges cross the
        electrode boundary, found directly rather than assumed), offset
        by the reach vector (electrode_height * tan(alpha)) in the
        theta direction. This is a PARALLELOGRAM whenever the feature's
        own axis isn't parallel to the crossing line -- verified
        against a synthetic 45-degree case (four vertices, confirmed
        opposite sides parallel) before using it here. Only meaningful
        when theta is on the risky side of Warning #1 for this feature;
        caller is responsible for checking that. Returns a shapely
        geometry (possibly empty) or None if the feature doesn't cross
        the electrode at all."""
        strip = self._electrode_shadow_strip(junction, feature_points, theta_deg, alpha_deg)
        if strip is None:
            return None
        try:
            feature_poly = sg.Polygon(feature_points)
            if not feature_poly.is_valid:
                feature_poly = feature_poly.buffer(0)
            return feature_poly.intersection(strip)
        except Exception:
            return None

    def _draw_electrode_shadow_parallelogram(self, ax, junction, feature_points, theta_deg, alpha_deg):
        """Draws the REAL electrode-crossing shadow region -- a
        parallelogram (when the feature's own axis isn't parallel to
        the electrode's local edge) computed by actually intersecting
        the feature's polygon with the electrode's shadow strip, not
        just a length subtracted along one axis. Drawn with a red hatch
        that is visually distinct, since this is a genuinely different
        mechanism from the resist-stack overlap shadow bands (grey/blue/
        red dashed) drawn elsewhere."""
        region = self._compute_electrode_shadow_region(junction, feature_points, theta_deg, alpha_deg)
        if region is None or region.is_empty:
            return
        geoms = list(region.geoms) if hasattr(region, "geoms") else [region]
        for g in geoms:
            if not hasattr(g, "exterior") or g.exterior is None:
                continue
            pts = list(g.exterior.coords)
            if len(pts) < 3:
                continue
            poly = MplPolygon(pts, closed=True, facecolor="#ff5c5c", edgecolor=OUTLINE_COLOR,
                              linewidth=1.0, hatch="xxxx", alpha=0.55, zorder=19)
            ax.add_patch(poly)

    def _outline_extra_halfwidth(self, ax, outline_lw_points=1.0):
        """How much extra half-width (in DATA units, i.e. um) the
        shape's own white outline visually adds beyond its true
        width_um -- the rendering draws every finger/patch with a
        white edge at linewidth=1.0 (points, screen-space), which is a
        FIXED SCREEN size, not a fixed data size, so it has to be
        converted using the CURRENT zoom level rather than a constant.
        Verified the conversion arithmetic (points -> pixels via DPI,
        pixels -> data units via the axes' current window extent and
        xlim span) against a hand-computed case before using it here."""
        try:
            fig = ax.figure
            bbox = ax.get_window_extent()
            xlim = ax.get_xlim()
            px_per_data = bbox.width / abs(xlim[1] - xlim[0]) if abs(xlim[1] - xlim[0]) > 1e-9 else 1.0
            pt_to_px = fig.dpi / 72.0
            return (outline_lw_points / 2.0) * pt_to_px / px_per_data
        except Exception:
            return 0.0

    def _draw_shadow_band(self, ax, edge_center, axis_hat_toward_end, perp_hat, half_width, depth, extend_outward, label=None, masked=False):
        """A shadow band drawn to be UNMISTAKABLE, not just present:
        solid (not faint) fill, a bright dashed edge outline in a
        distinct accent color, and diagonal hatching so it reads even
        against whatever color happens to be underneath -- a single
        light-grey semi-transparent fill alone (the first version)
        turned out to blend into the design almost invisibly.
        half_width is extended by the shape's own visual outline
        thickness (see _outline_extra_halfwidth) so the band's edges
        line up with what's actually drawn on screen, not just the
        underlying data width. inward (into the design, shrinking) if
        extend_outward is False, outward (beyond the design, extending)
        if True. depth <= 0 or half_width <= 0 draws nothing, matching
        the same "don't clutter with a zero-length marker" rule used
        throughout the rest of this overlay.

        label, when given (used for patches needing two deposition
        passes), is drawn as small text at the band.

        masked=True draws an OUTLINE-ONLY "ghost" version (no fill, no
        hatch, dotted edge) instead of the normal solid band -- for a
        deposition pass whose own shadow reach is entirely behind metal
        an EARLIER pass already deposited there. This is needed because showing
        only the final NET result (one band per end) was mathematically
        correct but visually indistinguishable from a single deposition --
        the whole point is to SEE that two passes happened, including the
        one whose effect is real but doesn't change the visible boundary."""
        if depth <= 0.005 or half_width <= 0.005:
            return
        half_width = half_width + self._outline_extra_halfwidth(ax)
        sign = 1.0 if extend_outward else -1.0
        p1 = (edge_center[0] - perp_hat[0]*half_width, edge_center[1] - perp_hat[1]*half_width)
        p2 = (edge_center[0] + perp_hat[0]*half_width, edge_center[1] + perp_hat[1]*half_width)
        far = (edge_center[0] + axis_hat_toward_end[0]*depth*sign, edge_center[1] + axis_hat_toward_end[1]*depth*sign)
        p3 = (far[0] + perp_hat[0]*half_width, far[1] + perp_hat[1]*half_width)
        p4 = (far[0] - perp_hat[0]*half_width, far[1] - perp_hat[1]*half_width)
        edge_color = "#ff5c5c" if not extend_outward else "#7fd4ff"  # shrink=warning red, extend=cool blue --
                                                                        # distinct from Warning #1/#2's own
                                                                        # colors so the two systems don't blur
        if masked:
            poly = MplPolygon([p1, p2, p3, p4], closed=True, facecolor="none", edgecolor=edge_color,
                              linewidth=0.8, linestyle=(0, (1, 2)), alpha=0.55, zorder=16)
        else:
            poly = MplPolygon([p1, p2, p3, p4], closed=True, facecolor="#c9cbd6", edgecolor=edge_color,
                              linewidth=1.3, linestyle=(0, (3, 2)), hatch="////", alpha=0.62, zorder=17)
        ax.add_patch(poly)
        # The Deposition Slideshow's "Shadow Sim" view feeds every
        # already-introduced feature the WHOLE recipe's accumulated theta
        # pool (see _slideshow_draw_shadow_sim_view), so the same feature
        # can carry many more simultaneous bands than this label mechanism
        # was ever designed for, producing illegible, overlapping text
        # that cluttered the whole view. Suppressed there via
        # self._suppress_shadow_band_labels (set/cleared only around that
        # one call site); every other caller (Simulate tab's Optimal/
        # Simulated/Post-Shadow views) never sets this flag, so their own
        # angle labels are completely unaffected.
        if label and not getattr(self, "_suppress_shadow_band_labels", False):
            mid = ((edge_center[0]+far[0])/2.0, (edge_center[1]+far[1])/2.0)
            fs = self._overlay_fontsize(ax) * 0.85
            text_color = edge_color if not masked else "#6a6c7a"
            t = ax.text(mid[0] + perp_hat[0]*(half_width+0.1), mid[1] + perp_hat[1]*(half_width+0.1),
                       label, color=text_color, fontsize=fs, ha="center", va="center", zorder=18)
            if hasattr(self, "_create_import_overlay_texts"):
                self._create_import_overlay_texts.append(t)

    def _cross_axis_boundaries(self, perp_hat, plus_extent, minus_extent, thetas, dx_um, dy_um):
        """Shared core for _apply_cross_axis_shadow (the real post-shadow
        geometry) and _draw_cross_axis_shadow_bands (its own visual
        annotation). An earlier electrode-crossing
        shadow bug showed that keeping the real math and its own picture as two
        independently-maintained code paths is exactly how they silently
        drift apart. Both now call this one
        function for "where do this feature's two long edges actually
        end up," so there is one true answer, not two that happen to
        usually agree.

        Computes each ACTIVE PASS's own one-sided shift INDEPENDENTLY --
        for a single theta, whichever long edge its alignment points
        away from shrinks by dx_um*|align|, the opposite edge (theta
        points toward it) extends by dy_um*|align|, exactly mirroring
        the already-validated tip-end model (_shadow_alignment/
        _scaled_shadow_depth) but applied to perp_hat instead of the
        feature's own length axis. Bug fix: an earlier
        version of this function used _net_depth_multi (the tip model's
        OWN multi-pass rule, "whichever pass's metal reaches furthest
        wins," applied independently per edge) to combine multiple
        active passes -- but that quietly let a SHRINK from one pass be
        overridden by an EXTEND from a completely different pass at the
        SAME edge, which is only valid for the tip ends (a single edge,
        metal really does simply accumulate to whichever pass reaches
        furthest). For the two LONG edges, "furthest per edge" doesn't
        correspond to any one pass's own real shape -- verified directly
        against a real SEM-matched scenario (two passes 90deg off a
        patch's own axis): each of those two passes ALONE already
        fully occludes this patch (each pass's own shrink alone exceeds
        the entire linewidth), so the true physical result is "no metal
        from either pass" -- but combining them via the tip model's
        per-edge rule instead let pass 45's extend-credit on one edge
        paper over pass 225's shrink there (and vice versa), producing a
        surviving strip WIDER than nominal, flatly contradicting the
        real fabricated "no patches at all" result this feature was
        built to reproduce.

        FIXED: each pass's own (boundary_plus, boundary_minus) interval
        is computed fully independently; a pass whose own shrink alone
        already crosses to the far edge contributes NOTHING (metal a
        DIFFERENT pass deposits elsewhere doesn't un-occlude THIS pass's
        own failure). The final result is the union of whichever passes
        individually still bridge the linewidth at all -- taken as the
        enclosing hull of their intervals, since every pass acts on the
        SAME two edges of the SAME rectangle, so in every realistic case
        their surviving intervals touch or overlap (a pathological case
        with genuinely disjoint per-pass survivors would report the hull
        between them rather than two separate pieces -- a modeling
        simplification flagged here rather than silently assumed, kept
        for the same reason the rest of this app returns one polygon per
        feature, not an open-ended list).

        Returns (boundary_plus, boundary_minus, any_effect): the final
        signed edge positions along perp_hat (NOT clamped to the nominal
        extents -- a shrink deep enough legitimately crosses into the
        opposite edge's own territory), or (None, None, True) if EVERY
        active pass individually fails to bridge the linewidth at all
        (fully self-shadowed, no metal survives). any_effect is False
        only when every theta is close enough to exactly on-axis that
        this is a true no-op (bit-identical geometry, not floating-point
        rebuild noise).

        `dx_um`/`dy_um` accept EITHER a single scalar (broadcast to every
        theta, today's exact behavior) OR a sequence the same length as
        `thetas` (each pass's own real dx/dy) -- see `_net_depth_multi`'s
        own matching
        comment for the full root-cause writeup. The per-pass
        independence this function already relies on (each pass's own
        interval computed fully separately before the enclosing-hull
        combination) makes this a purely mechanical change: each loop
        iteration just needs to look up ITS OWN dx/dy instead of the one
        shared pair."""
        NEGLIGIBLE_UM = 1e-6
        dx_list = dx_um if isinstance(dx_um, (list, tuple)) else [dx_um] * len(thetas)
        dy_list = dy_um if isinstance(dy_um, (list, tuple)) else [dy_um] * len(thetas)
        max_abs_align = max(abs(self._shadow_alignment(perp_hat, t)) for t in thetas)
        max_dxdy = max(max(dx_i, dy_i) for dx_i, dy_i in zip(dx_list, dy_list))
        if max_abs_align * max_dxdy < NEGLIGIBLE_UM:
            return plus_extent, -minus_extent, False

        candidate_plus, candidate_minus = [], []
        for t, dx_i, dy_i in zip(thetas, dx_list, dy_list):
            align = self._shadow_alignment(perp_hat, t)
            a = abs(align)
            if align >= 0:
                b_plus = plus_extent + dy_i * a      # this pass extends the + edge
                b_minus = -minus_extent + dx_i * a   # ...and shrinks the - edge
            else:
                b_plus = plus_extent - dx_i * a      # this pass shrinks the + edge
                b_minus = -minus_extent - dy_i * a   # ...and extends the - edge
            if b_plus - b_minus > 1e-9:
                candidate_plus.append(b_plus)
                candidate_minus.append(b_minus)
        if not candidate_plus:
            return None, None, True
        return max(candidate_plus), min(candidate_minus), True

    def _draw_cross_axis_shadow_bands(self, ax, feature_points, axis_hat, thetas, dx_um, dy_um, label=None, origin=None):
        """The WIDTH-wise (cross-axis) counterpart to the tip-shrink bands
        drawn above. Gap: _apply_cross_axis_shadow (the real
        math backing Post-Shadow Result and the disconnection warnings)
        already computes a CONTINUOUS, angle-dependent shrink of a
        feature's linewidth, not an all-or-nothing flag -- the effective
        linewidth depends on the designed linewidth minus the length of
        the red-hatched shadow -- but Simulated Design never drew
        anything for it: a fully-vanished feature got only a text warning
        (no visual at all), and a partially-eaten one got nothing
        whatsoever, silently understating a real, continuous effect.

        Bug fix, found against a real design (theta
        changed from the finger's own drawn axis by only 5deg): this
        used to draw the SAME shrink (red) hatch on BOTH long edges,
        using only the MAGNITUDE of the perpendicular alignment -- so a
        single directional deposition visually looked like it was being
        shadowed from both sides at once, when a single deposition
        angle should only ever shadow one side. Fixed to draw exactly
        what the shared
        _cross_axis_boundaries now computes (the SAME function
        _apply_cross_axis_shadow itself calls, so the picture can never
        disagree with the real geometry): a red shrink hatch on whichever
        ONE edge theta points away from, and a blue extend indicator on
        the opposite edge theta points toward -- directional by
        construction, matching a single light source/ray-tracing model,
        not a symmetric occlusion. A shrink band's drawn depth is
        clamped to the feature's total width (never drawn running past
        the opposite edge) so a shadow deep enough to sweep clean across
        a thin line reads as "the whole strip," not an arrow overshooting
        it; a full self-shadow (every active pass individually fails to
        bridge the linewidth) draws both edges hatched fully across the
        whole width. _draw_shadow_band's own depth<=0.005/half_width<=
        0.005 guard makes this a safe no-op for an on-axis (already-
        correct) deposition -- nothing new is drawn when there's nothing
        to show."""
        if not thetas:
            return
        perp_hat = (-axis_hat[1], axis_hat[0])
        neg_perp_hat = (-perp_hat[0], -perp_hat[1])

        if origin is not None:
            cx, cy = origin
        else:
            cx = sum(p[0] for p in feature_points) / len(feature_points)
            cy = sum(p[1] for p in feature_points) / len(feature_points)

        def perp_proj(p):
            return (p[0] - cx) * perp_hat[0] + (p[1] - cy) * perp_hat[1]

        def axis_proj(p):
            return (p[0] - cx) * axis_hat[0] + (p[1] - cy) * axis_hat[1]

        plus_extent = max(perp_proj(p) for p in feature_points)
        minus_extent = max(-perp_proj(p) for p in feature_points)
        boundary_plus, boundary_minus, any_effect = self._cross_axis_boundaries(
            perp_hat, plus_extent, minus_extent, thetas, dx_um, dy_um)
        if not any_effect:
            return

        # Significant bug fix: the shadowing hatches
        # could extend way outside the design. This
        # used to take half_len = max(abs(axis_proj(p))) -- i.e., it
        # assumed the band should be drawn SYMMETRIC about `origin` along
        # axis_hat, which only holds when `origin` happens to be the
        # feature's own axial midpoint (true for the default no-origin
        # case, where cx/cy IS the centroid). But an earlier `origin` fix
        # deliberately anchors a finger's and its plate's cross-axis call
        # at a shared point on the finger's real axis line
        # (`f.patch_end`/`nearest_finger.patch_end`) -- an END of the
        # finger, not its center. With origin pinned to one end, every
        # one of the feature's own points projects to roughly the SAME
        # SIGN along axis_hat (e.g., all in [-flen, 0] rather than
        # [-flen/2, +flen/2]), so max(abs(axis_proj(p))) came out close
        # to the feature's FULL length rather than half of it -- and
        # since the drawn band is built symmetric about `origin` (extending
        # +-half_len along axis_hat from there), the band's far half
        # landed a full extra feature-length PAST the actual design,
        # matching the "way outside" report. Confirmed directly:
        # rebuilding with origin=f.patch_end on a real finger reproduced
        # a drawn band bounding box roughly DOUBLE the finger's own
        # length, overshooting past patch_end in the direction away from
        # the finger entirely.
        #
        # Fixed by decoupling the along-axis extent from `origin`
        # entirely: `origin` is only ever meant to pick a consistent
        # PERPENDICULAR reference plane (so a finger and its plate agree
        # on which side is "+"/"-"), never the axial center of the drawn
        # band. The band's own along-axis center/half-length are now
        # taken directly from the feature's own real bounding extent
        # along axis_hat (min/max of axis_proj, not just abs-max) --
        # bit-identical to the old behavior for the already-tested
        # default (origin=centroid) rectangle case, where axis_proj is
        # already symmetric about 0 by construction, but now correct
        # regardless of where `origin` sits.
        axis_vals = [axis_proj(p) for p in feature_points]
        axis_lo, axis_hi = min(axis_vals), max(axis_vals)
        axis_mid = (axis_lo + axis_hi) / 2.0
        half_len = (axis_hi - axis_lo) / 2.0
        total_width = plus_extent + minus_extent
        plus_center = (cx + axis_hat[0] * axis_mid + perp_hat[0] * plus_extent,
                       cy + axis_hat[1] * axis_mid + perp_hat[1] * plus_extent)
        minus_center = (cx + axis_hat[0] * axis_mid - perp_hat[0] * minus_extent,
                        cy + axis_hat[1] * axis_mid - perp_hat[1] * minus_extent)

        if boundary_plus is None:
            # Every active pass individually fails to bridge the
            # linewidth -- fully self-shadowed. Draw both edges hatched
            # fully across the whole width so the picture unambiguously
            # reads "nothing survives here," matching
            # _apply_cross_axis_shadow's own None/vanish return.
            self._draw_shadow_band(ax, plus_center, perp_hat, axis_hat, half_len, total_width, False, label=label)
            self._draw_shadow_band(ax, minus_center, neg_perp_hat, axis_hat, half_len, total_width, False, label=label)
            return

        plus_depth = boundary_plus - plus_extent            # >0 extend, <0 shrink
        minus_depth = (-boundary_minus) - minus_extent      # >0 extend, <0 shrink
        if plus_depth < 0:
            self._draw_shadow_band(ax, plus_center, perp_hat, axis_hat, half_len,
                                   min(-plus_depth, total_width), False, label=label)
        else:
            self._draw_shadow_band(ax, plus_center, perp_hat, axis_hat, half_len, plus_depth, True, label=label)
        if minus_depth < 0:
            self._draw_shadow_band(ax, minus_center, neg_perp_hat, axis_hat, half_len,
                                   min(-minus_depth, total_width), False, label=label)
        else:
            self._draw_shadow_band(ax, minus_center, neg_perp_hat, axis_hat, half_len, minus_depth, True, label=label)

    def _draw_cross_axis_shadow_bands_masked_passes(self, ax, feature_points, axis_hat, thetas, dx_um, dy_um, origin=None):
        """Visualization gap fix: found against a real
        patch group with two good deposition angles (e.g. 0 and 180deg)
        where changing one pass's angle to a much worse angle (e.g.
        45deg) still produced hatching visually identical to the
        original good-angle case, when it clearly should not.

        Root cause: _apply_cross_axis_shadow/_draw_cross_axis_shadow_bands
        already correctly implement the validated (real SEM-matched
        data) "each pass acts independently; keep whichever surviving
        pass reaches furthest" model for the FINAL/NET geometry -- and
        for this exact case that net result genuinely IS unaffected,
        because the OTHER, still-on-axis pass (180deg) alone already
        bridges this patch's full nominal width, so its own envelope
        wins outright over the 45deg pass's own, far narrower one --
        correct final physics (whichever pass's own metal reaches
        furthest is what's actually there), not a bug in the math. But
        the visualization only ever drew that ONE net picture, giving
        zero visual indication that one of the two active passes was,
        on its own, catastrophic. This is the direct cross-axis
        counterpart to the masked-
        ghost treatment the near/far TIP bands already get for a 2-pass
        end (see the patch tip-band code in _draw_sim_shadow_visualization):
        drawn as a separate pass here (rather than folded into
        _draw_cross_axis_shadow_bands itself) so it can simply COMPARE
        against that function's own real net boundary via the same
        shared _cross_axis_boundaries core, instead of duplicating its
        math -- the two can't independently drift apart.

        For each active pass, computes what its own boundary would be
        if it were the ONLY pass depositing (same _cross_axis_boundaries
        call, given a single-element theta list), and draws a masked
        (ghost, outline-only) band for whichever side that solo result
        is narrower than the real net result already drawn -- i.e.
        exactly the passes/sides masked out of the final picture,
        making them visible without changing what the net result says
        actually happens. A no-op when only one pass is active (nothing
        to mask against) or when the mechanism doesn't engage at all."""
        if len(thetas) < 2:
            return
        perp_hat = (-axis_hat[1], axis_hat[0])
        neg_perp_hat = (-perp_hat[0], -perp_hat[1])

        if origin is not None:
            cx, cy = origin
        else:
            cx = sum(p[0] for p in feature_points) / len(feature_points)
            cy = sum(p[1] for p in feature_points) / len(feature_points)

        def perp_proj(p):
            return (p[0] - cx) * perp_hat[0] + (p[1] - cy) * perp_hat[1]

        def axis_proj(p):
            return (p[0] - cx) * axis_hat[0] + (p[1] - cy) * axis_hat[1]

        plus_extent = max(perp_proj(p) for p in feature_points)
        minus_extent = max(-perp_proj(p) for p in feature_points)
        net_plus, net_minus, net_any = self._cross_axis_boundaries(
            perp_hat, plus_extent, minus_extent, thetas, dx_um, dy_um)
        if not net_any:
            return  # this pass set doesn't even engage the mechanism -- nothing to compare against

        # Same fix as _draw_cross_axis_shadow_bands's own -- see its
        # docstring's bug-fix note for the full
        # report/root-cause writeup: the along-axis extent/center must
        # come from the feature's own real bounding extent along
        # axis_hat, never assumed symmetric about `origin` (which may
        # legitimately sit at one END of the feature, e.g. a finger's
        # shared `patch_end` anchor with its plate).
        axis_vals = [axis_proj(p) for p in feature_points]
        axis_lo, axis_hi = min(axis_vals), max(axis_vals)
        axis_mid = (axis_lo + axis_hi) / 2.0
        half_len = (axis_hi - axis_lo) / 2.0
        total_width = plus_extent + minus_extent
        plus_center = (cx + axis_hat[0] * axis_mid + perp_hat[0] * plus_extent,
                       cy + axis_hat[1] * axis_mid + perp_hat[1] * plus_extent)
        minus_center = (cx + axis_hat[0] * axis_mid - perp_hat[0] * minus_extent,
                        cy + axis_hat[1] * axis_mid - perp_hat[1] * minus_extent)

        # `dx_um`/`dy_um` may now be either a
        # single scalar (broadcast to every theta, today's exact
        # behavior) or a sequence the same length as `thetas` (each
        # pass's own real dx/dy) -- same convention _net_depth_multi/
        # _cross_axis_boundaries themselves already accept. Needed here
        # (unlike the net-boundary call just above, which already
        # forwards whichever shape it's given straight through) because
        # this loop calls _cross_axis_boundaries again per SINGLE theta,
        # so it must pick out that ONE pass's own dx/dy, not the whole list.
        dx_list = dx_um if isinstance(dx_um, (list, tuple)) else [dx_um] * len(thetas)
        dy_list = dy_um if isinstance(dy_um, (list, tuple)) else [dy_um] * len(thetas)
        for t, dx_i, dy_i in zip(thetas, dx_list, dy_list):
            solo_plus, solo_minus, solo_any = self._cross_axis_boundaries(
                perp_hat, plus_extent, minus_extent, [t], dx_i, dy_i)
            if not solo_any:
                continue
            if solo_plus is None:
                # This pass ALONE fails to bridge the linewidth at all --
                # catastrophic on its own, entirely masked by whichever
                # OTHER pass(es) actually won the real net result. Only
                # worth a ghost when the net result itself survived --
                # otherwise the un-masked full-width band already drawn
                # by _draw_cross_axis_shadow_bands shows this exact
                # picture already.
                if net_plus is not None:
                    self._draw_shadow_band(ax, plus_center, perp_hat, axis_hat, half_len, total_width, False,
                                           label=f"{t:g}° (masked)", masked=True)
                    self._draw_shadow_band(ax, minus_center, neg_perp_hat, axis_hat, half_len, total_width, False,
                                           label=f"{t:g}° (masked)", masked=True)
                continue
            if net_plus is None:
                continue  # the real net result fully vanished -- already shown, unmasked
            plus_depth = solo_plus - plus_extent
            minus_depth = (-solo_minus) - minus_extent
            if solo_plus < net_plus - 1e-9:
                if plus_depth < 0:
                    self._draw_shadow_band(ax, plus_center, perp_hat, axis_hat, half_len,
                                           min(-plus_depth, total_width), False,
                                           label=f"{t:g}° (masked)", masked=True)
                else:
                    self._draw_shadow_band(ax, plus_center, perp_hat, axis_hat, half_len, plus_depth, True,
                                           label=f"{t:g}° (masked)", masked=True)
            if solo_minus > net_minus + 1e-9:
                if minus_depth < 0:
                    self._draw_shadow_band(ax, minus_center, neg_perp_hat, axis_hat, half_len,
                                           min(-minus_depth, total_width), False,
                                           label=f"{t:g}° (masked)", masked=True)
                else:
                    self._draw_shadow_band(ax, minus_center, neg_perp_hat, axis_hat, half_len, minus_depth, True,
                                           label=f"{t:g}° (masked)", masked=True)

    def _shadow_dxdy(self, pmma_nm, pmgi_nm, alpha):
        """dx/dy depend only on the resist stack and alpha -- confirmed
        directly that compute_overlap_shadow_bounds returns identical
        dx/dy for wildly different chosen_overlap_nm values, so no
        "nominal length" is needed at all to know the shift magnitude;
        it's a property of the deposition step itself, applying equally
        to any edge that step's metal crosses."""
        dx, dy, _mn, _mx, _safe = compute_overlap_shadow_bounds(pmma_nm, pmgi_nm, alpha, 1500.0)
        return dx, dy

    def _resolve_pass_dxdy_list(self, thetas, alpha_hints, fallback_dx, fallback_dy, pmma_nm, pmgi_nm):
        """The shared per-pass-alpha resolver
        every feature-geometry function below now uses, fixing
        a confirmed, reproduced bug -- raising the tilt (alpha) for just
        the patch depositions, theta unchanged, had ZERO effect anywhere
        in the shadow sim/post-deposition view. Root cause: every one of
        these functions used to receive ONE shared (dx_um, dy_um) pair,
        computed ONCE by the caller from ONE shared alpha, and reuse it
        for every theta in a feature's own thetas list -- so a per-pass
        alpha (already fully supported by the Predicted Recipe Sequence
        panel's own per-row alpha field, and by the real Plassys
        machine, which can retilt between any two passes) had no path
        to ever reach the actual shadow math.

        Builds a per-pass (dx_um, dy_um) list, one entry per theta in
        `thetas`, resolving each pass's own alpha from `alpha_hints` (a
        list aligned index-wise with `thetas`; a missing list, a
        too-short list, or a None entry at a given index all fall back
        to `fallback_dx`/`fallback_dy` VERBATIM).

        Bug fix, caught by the
        test_plate_and_tip_theta_generalization.py regression (an EARLIER
        version of this function took `fallback_alpha` (a raw angle) plus
        `pmma_nm`/`pmgi_nm` and RE-DERIVED the fallback dx/dy via a fresh
        self._shadow_dxdy(pmma_nm, pmgi_nm, fallback_alpha) call, on the
        theory that this reproduces the caller's own already-computed
        dx_um/dy_um exactly): that's only true when this function's own
        freshly-read pmma_nm/pmgi_nm (from self.pmma_edit/self.pmgi_edit,
        read independently inside each feature-geometry function, same
        convention this file already uses everywhere else) happen to
        exactly match whatever pmma_nm/pmgi_nm the CALLER originally used
        to compute the dx_um/dy_um it passed in -- true for every real
        end-to-end call path (every caller ultimately reads the same live
        self.pmma_edit/self.pmgi_edit fields at the same instant), but NOT
        guaranteed for a direct unit-test call built from an explicit,
        independent pmma/pmgi -- exactly what surfaced this: a plate
        computed via a hand-supplied pmma=900nm dx_um no longer matched
        _cross_axis_boundaries' own boundaries (computed with that same
        900nm-based dx_um directly) once the plate function's own
        self.pmma_edit read defaulted to 875nm internally, silently
        substituting a DIFFERENT dx/dy for every fallback pass. Taking the
        caller's own already-computed `fallback_dx`/`fallback_dy` directly
        (instead of re-deriving it) removes the possibility of the two
        ever disagreeing: a fallback pass now uses EXACTLY the scalar the
        caller already had, bit-for-bit, regardless of what pmma_nm/
        pmgi_nm this function itself separately resolved. `pmma_nm`/
        `pmgi_nm` are still needed here, and still read fresh by every
        caller, but only to translate a genuinely DIFFERENT per-pass
        alpha (one actually present in `alpha_hints`) into its own real
        dx/dy -- the one case with no pre-existing scalar to reuse.

        The returned lists feed directly into _net_depth_multi/
        _cross_axis_boundaries/_apply_cross_axis_shadow/
        _end_depth_ranking, all of which now accept either a scalar
        (broadcast) or a per-pass sequence -- see _net_depth_multi's own
        comment for that half of the fix. A design that never sets a
        per-pass alpha anywhere produces a list where every entry is
        `fallback_dx`/`fallback_dy` verbatim -- bit-for-bit identical to
        the old shared-scalar behavior, just expressed as a (trivial)
        per-pass list instead of one scalar."""
        cache = {}
        dx_list, dy_list = [], []
        for i, _t in enumerate(thetas):
            a = alpha_hints[i] if alpha_hints and i < len(alpha_hints) and alpha_hints[i] is not None else None
            if a is None:
                dx_list.append(fallback_dx)
                dy_list.append(fallback_dy)
                continue
            if a not in cache:
                cache[a] = self._shadow_dxdy(pmma_nm, pmgi_nm, a)
            dx_i, dy_i = cache[a]
            dx_list.append(dx_i)
            dy_list.append(dy_i)
        return dx_list, dy_list

    def _resolve_pass_alpha_list(self, thetas, alpha_hints, fallback_alpha):
        """The same index-wise "hint or
        fallback" resolution as _resolve_pass_dxdy_list, but returning
        the raw per-pass ALPHA value itself rather than a derived
        dx_um/dy_um pair -- needed by the electrode-crossing shadow
        mechanism (_compute_electrode_shadow_region/_electrode_shadow_
        strip), which computes its own reach directly from
        electrode_height_nm*tan(alpha) via compute_electrode_shadow,
        an entirely different physical calculation from the PMMA/PMGI
        resist-bilayer dx/dy this file uses everywhere else -- so it
        needs alpha itself, not a dx/dy translation of it. A missing
        list, a too-short list, or a None entry at a given index all
        fall back to `fallback_alpha` verbatim, exactly matching
        _resolve_pass_dxdy_list's own contract (and _all_deposition_
        pass_records' own per-record alpha resolution, which this
        duplicates in miniature rather than importing, since that
        function resolves a whole record dict, not a bare list)."""
        return [alpha_hints[i] if alpha_hints and i < len(alpha_hints) and alpha_hints[i] is not None else fallback_alpha
                for i in range(len(thetas))]

    def _thickness_to_color(self, kind, thickness_nm, min_nm, max_nm):
        """Maps a deposited region's own accumulated thickness to a
        shade within its kind's existing base hue (based on
        real SEM images of a fabricated junction: the thicker the
        deposition, the darker the color of the line -- the
        thinnest-deposited feature reads lightest, the thickest feature
        or part of a feature reads darkest). Interpolates HLS
        lightness/saturation
        between a near-white tint at the thinnest region present
        anywhere in THIS render and a materially darker, more saturated
        version of the SAME hue at the thickest -- so a finger always
        still reads as blue, a patch as green, a plate as gold, just
        lighter or darker within that family, the same way real liftoff
        SEM shade varies by thickness within one material rather than
        switching hue. Falls back to the mid-tone (frac=0.5) when the
        range can't be determined (e.g. every region in this render
        happens to share one thickness) so a degenerate range never
        divides by zero or looks arbitrarily dark/light.

        Tuning note: the original LIGHTEST_L=
        0.92/DARKEST_L=0.32 range (plus a +0.15 saturation boost at the
        dark end) produced a jarring jump between a single-pass region
        (near-white) and a double-pass one (much darker, closer to
        black than to the base hue). The colors read better on a gentler
        scale -- e.g. the patch color of the first deposition as a light
        green and the second deposition as a slightly darker green,
        rather than a much darker green -- distinct from each other, but
        more visually pleasing. Narrowed to a gentler L range and a
        smaller saturation delta so adjacent thickness bands read as
        close relatives of the same hue -- still clearly distinct, but
        without the harsh near-white-to-near-black swing. Applies
        uniformly to every deposited feature kind (finger, patch,
        plate) since they all share this one function."""
        base_hex = SHADOW_KIND_BASE_COLOR.get(kind, "#a8dab5")
        r, g, b = (int(base_hex[i:i + 2], 16) / 255.0 for i in (1, 3, 5))
        h, l, s = colorsys.rgb_to_hls(r, g, b)
        if thickness_nm is None or min_nm is None or max_nm is None or max_nm <= min_nm:
            frac = 0.5
        else:
            frac = (thickness_nm - min_nm) / (max_nm - min_nm)
            frac = max(0.0, min(1.0, frac))
        LIGHTEST_L, DARKEST_L = 0.84, 0.50
        new_l = LIGHTEST_L + (DARKEST_L - LIGHTEST_L) * frac
        new_s = min(1.0, s + 0.08 * frac)
        nr, ng, nb = colorsys.hls_to_rgb(h, new_l, new_s)
        return "#{:02x}{:02x}{:02x}".format(int(round(nr * 255)), int(round(ng * 255)), int(round(nb * 255)))

    def _thickness_range(self, shapes):
        """Min/max thickness_nm across a shapes list (6-tuples of
        (points, kind, finger_index, thickness_nm, group_id, is_ghost) --
        see _compute_post_shadow_shapes' own docstring for what is_ghost
        marks), ignoring any None entries -- factored out so the
        Deposition Slideshow can compute this ONCE from the COMPLETE
        design's shapes and reuse that same fixed range while drawing
        the truncated, progressively-revealed subset, so a region's
        shade never jumps as more of the design is revealed; only which
        regions are VISIBLE changes across frames, never how a given
        thickness maps to a shade. Returns (None, None) if there's
        nothing to measure."""
        values = [th for _pts, _k, _fi, th, _gid, _ghost in shapes if th is not None]
        if not values:
            return None, None
        return min(values), max(values)

    def _match_pass_thicknesses(self, thetas_ordered, layers_ref, thicknesses_ref, default=0.0):
        """thetas_ordered may be a REORDERED copy of layers_ref (e.g.
        patches' own _true_order_patch_thetas sorts a design's active
        thetas into chronological order for the shadow cascade, losing
        the original commit-order alignment with self._sim_patch_
        thicknesses) -- same float values, different order. Matches each
        theta in thetas_ordered back to its own typed thickness by
        finding the closest not-yet-consumed entry in layers_ref
        (tolerant of tiny float round-trip differences, never reusing
        the same source entry twice), pulling the parallel entry from
        thicknesses_ref. A theta with no real match at all (a genuine
        mismatch -- e.g. the tree was edited after the cached run) still
        gets `default` rather than raising, so a stale/edited state
        degrades to a visibly-off but harmless flat shade instead of
        crashing the whole post-shadow render.

        `default` is an OPTIONAL param
        (defaults to 0.0, today's exact behavior/value, byte-identical
        for every existing thickness caller) so this same generic
        "reorder this parallel array to match a reordered theta list"
        logic can be reused VERBATIM for per-pass alpha too (called with
        `default=None`, since an unmatched/missing alpha entry must fall
        back to the shared Active-alpha field downstream -- see
        _resolve_pass_dxdy_list -- never silently become a real, very
        different alpha value of 0deg the way an unmatched thickness
        correctly becomes 0nm of metal)."""
        used = [False] * len(layers_ref)
        result = []
        for theta in thetas_ordered:
            best_idx, best_diff = None, None
            for idx, cand in enumerate(layers_ref):
                if used[idx] or cand is None:
                    continue
                diff = abs(((theta - cand + 180.0) % 360.0) - 180.0)
                if best_diff is None or diff < best_diff:
                    best_idx, best_diff = idx, diff
            if best_idx is not None and best_diff < 1.0:
                used[best_idx] = True
                th = thicknesses_ref[best_idx] if best_idx < len(thicknesses_ref) else None
                result.append(th if th is not None else default)
            else:
                result.append(default)
        return result

    def _end_depth_ranking(self, axis_hat, passes, dx_um, dy_um):
        """passes: [(theta, thickness_nm), ...] for one feature's own
        committed deposition passes. Returns a list of (signed_depth,
        thickness_nm) for THIS end (axis_hat toward the end in
        question), ranked DESCENDING by signed_depth -- index 0 is the
        single pass that reaches furthest outward at this end, matching
        how the REAL final boundary here is exactly max(signed_depth)
        (_net_depth_multi). This is the general, per-pass-INDEPENDENT-
        reach model: each pass's own metal-reach at a given end is
        entirely its own, unaffected by any other pass -- true for every
        shape that uses _net_depth_multi (fingers, plates). Patches'
        shrink-then-extend COUPLING is a real, different exception,
        handled separately by _patch_end_band -- never routed through
        this function.

        `dx_um`/`dy_um` accept EITHER a
        single scalar (broadcast to every entry in `passes`, today's
        exact behavior) OR a sequence the same length as `passes` (each
        pass's own real dx/dy, from that pass's own real alpha) -- see
        `_net_depth_multi`'s own comment for the root-cause writeup this
        mirrors."""
        dx_list = dx_um if isinstance(dx_um, (list, tuple)) else [dx_um] * len(passes)
        dy_list = dy_um if isinstance(dy_um, (list, tuple)) else [dy_um] * len(passes)
        ranked = []
        for pair, dx_i, dy_i in zip(passes, dx_list, dy_list):
            # `passes` entries may be 3-tuples
            # (theta, thickness, alpha) -- unused here (this function
            # only needs dx_i/dy_i, already resolved by the caller), but
            # unpacked this way so a 3-tuple caller (the finger loops'
            # own footprint-decoherence `passes`, see _finger_pass_
            # footprint) doesn't crash a plain 2-tuple unpack; an old
            # 2-tuple caller (e.g. a direct test call) still works too.
            theta, thickness, *_rest = pair
            if theta is None:
                continue
            align = self._shadow_alignment(axis_hat, theta)
            depth, extend = self._scaled_shadow_depth(dx_i, dy_i, align)
            signed = depth if extend else -depth
            ranked.append((signed, thickness if thickness is not None else 0.0))
        ranked.sort(key=lambda pair: pair[0], reverse=True)
        return ranked

    def _pass_footprint_overlay(self, pass_footprints, clip_pts):
        """Generalized model, replacing the old "near/far axial
        banding only, with a single combined cross-axis edge bolted on"
        approximation: each deposition step should be treated as a
        separate layer -- distinct from the others, but still able to
        represent the same feature -- generalized so this model works
        with every feature that is deposited more than once.

        The physically correct model: each active deposition PASS has
        its own COMPLETE, independently-shadowed real 2D footprint
        (built by the caller from whichever axial+cross-axis physics
        actually applies to that pass, for that feature) -- metal exists
        at a given point iff at least one pass's own real footprint
        covers it, and the THICKNESS there is the sum of every pass
        whose own footprint does. This is the direct generalization of
        "each layer is deposited separately, and they decohere" to ANY
        combination of thetas (axial-only/on-axis, cross-axis-shifted,
        or both at once), not just the two special cases (tip-end-only
        shrink/extend, or a single combined cross-axis edge) previously
        handled separately.

        pass_footprints: [(footprint, thickness_nm), ...] where
        `footprint` is either a raw point list, an already-built shapely
        geometry (a single pass whose OWN computation already returned
        multiple disconnected pieces -- e.g. an electrode-crossing split
        -- can be passed in pre-unioned), or None (that pass is fully
        self-shadowed for this specific feature -- simply excluded, same
        convention _apply_cross_axis_shadow/_compute_one_patch_
        shadowed_pieces already use for "no metal here at all").

        Builds the N-way arrangement via successive refinement (O(N)
        shapely ops, each pass tested against the regions accumulated so
        far) -- correct for any N, not just 2 -- then clips every
        resulting piece against `clip_pts`, the already-validated real
        final silhouette (electrode-crossing subtraction, disconnect-
        splitting, etc. already baked into however the caller computed
        it). This can only ever refine how the interior is colored,
        never change the outer shape that's already been tested.

        Correction (found and fixed while writing
        this function's own regression test,
        test_generalized_pass_footprint_decoherence.py): an EARLIER
        version of this docstring claimed the union of every pass's own
        footprint always exactly reproduces clip_pts, on the theory that
        both _net_depth_multi (axial) and _cross_axis_boundaries
        (cross-axis) are "literally the union of each pass's own
        independent reach." That's true for the axial dimension, but
        _cross_axis_boundaries' OWN docstring already documents a real
        exception for the cross-axis one: multiple passes are combined
        as the ENCLOSING HULL of their individual intervals, not a
        literal per-pass union -- deliberately, so a feature always
        renders as ONE polygon rather than splitting into disconnected
        pieces when two passes' own intervals don't overlap. That hull
        can legitimately claim a thin strip of territory along a
        feature's FULL length that only ONE pass's own independent
        footprint would reach only over PART of that length (verified
        directly: a finger with a 20deg/180deg pass pair has its 180deg
        pass's own solo footprint stop well short of the tip the 20deg
        pass alone extends to, yet the official hull-based envelope
        credits the 20deg pass's own wider cross-axis reach across the
        ENTIRE length, including the part only the 180deg pass's axial
        reach actually covers) -- a real, already-documented modeling
        simplification in the trusted, unchanged envelope math, not a
        bug in this function. Rather than silently under-covering
        clip_pts whenever this happens (which used to make the band
        union fall short of the real silhouette), any leftover area
        clip_pts has that no single pass's own footprint actually
        reaches is now folded in as one additional FULL-thickness
        (every active pass summed) region -- the same convention this
        function already uses for a genuine multi-pass overlap core, so
        a hull-attributed sliver reads as "fully committed" rather than
        arbitrarily assigned to one pass's own thickness or, worse,
        vanishing from the drawn shape entirely.

        Degrades to a single (clip_pts, total_thickness) piece for 0 or
        1 real (non-None) footprints, or on ANY construction failure --
        same safety-net convention every other thickness-banding
        function here already uses.

        Bug fix: a patch
        pass deposited at a near-perpendicular theta that fully self-
        shadows this feature (which should completely shadow this layer
        and leave only the other deposition visible) still
        showed the WHOLE remaining single-pass region shaded as if BOTH
        passes had contributed. `total` used to be computed from the
        RAW `pass_footprints` list, before excluding the `None`/empty
        (fully self-shadowed) entries -- so a masked-out pass's own
        thickness still leaked into the fallback (len(valid)<=1) and
        leftover-fold thicknesses below, even though that pass
        deposited NO metal anywhere on this feature. A feature with one
        surviving pass and one fully-self-shadowed pass rendered as
        dark/thick as if fully double-deposited, silently hiding the
        real single-pass shading a user would need to see to notice the
        self-shadow took effect at all -- directly contributing to a
        real report that the shadow simulation and post-shadow view
        never seemed to reflect self-shadowed angles. Fixed by computing
        `total` from `valid` (the already-filtered, actually-surviving
        footprints) instead, so a masked pass is treated exactly like it
        deposited zero metal everywhere, not just wherever its own
        footprint failed to reach."""

        def _to_poly(candidate):
            if candidate is None:
                return None
            if hasattr(candidate, "geom_type"):
                return candidate
            return sg.Polygon(candidate).buffer(0)

        valid = [(_to_poly(fp), th if th is not None else 0.0) for fp, th in pass_footprints]
        valid = [(poly, th) for poly, th in valid if poly is not None and not poly.is_empty]
        total = sum(th for _poly, th in valid)
        fallback = [(clip_pts, total)]
        if len(valid) <= 1:
            return fallback
        try:
            clip_poly = sg.Polygon(clip_pts).buffer(0)
            if clip_poly.is_empty or clip_poly.area < 1e-9:
                return fallback

            bands = [(valid[0][0], {0})]
            covered = valid[0][0]
            for idx in range(1, len(valid)):
                poly_i, _th_i = valid[idx]
                new_bands = []
                for region, idxset in bands:
                    inter = region.intersection(poly_i)
                    if not inter.is_empty and inter.area > 1e-9:
                        new_bands.append((inter, idxset | {idx}))
                    diff = region.difference(poly_i)
                    if not diff.is_empty and diff.area > 1e-9:
                        new_bands.append((diff, idxset))
                new_part = poly_i.difference(covered)
                if not new_part.is_empty and new_part.area > 1e-9:
                    new_bands.append((new_part, {idx}))
                covered = covered.union(poly_i)
                bands = new_bands

            result = []
            for region, idxset in bands:
                piece = region.intersection(clip_poly)
                if piece.is_empty:
                    continue
                thickness = sum(valid[i][1] for i in idxset)
                geoms = list(piece.geoms) if hasattr(piece, "geoms") else [piece]
                for g in geoms:
                    if hasattr(g, "exterior") and g.exterior is not None and g.area > 1e-9:
                        result.append((list(g.exterior.coords), thickness))

            # Fix (see docstring above): clip_pts
            # can legitimately include a hull-attributed sliver no
            # single pass's own footprint actually reaches (a real,
            # already-documented _cross_axis_boundaries simplification,
            # not a bug) -- fold any such leftover in at full combined
            # thickness rather than letting the band union silently fall
            # short of the real, already-validated silhouette.
            leftover = clip_poly.difference(covered)
            if not leftover.is_empty and leftover.area > 1e-9:
                geoms = list(leftover.geoms) if hasattr(leftover, "geoms") else [leftover]
                for g in geoms:
                    if hasattr(g, "exterior") and g.exterior is not None and g.area > 1e-9:
                        result.append((list(g.exterior.coords), total))

            return result if result else fallback
        except Exception:
            return fallback

    def _thickness_shaded_pieces_for_ends(self, nominal_points, near_end, far_end, near_ranked, far_ranked, clip_pts,
                                           axis_toward_far=None, thetas=None, dx_um=None, dy_um=None, origin=None,
                                           passes=None, pass_footprint_fn=None):
        """Builds (points, thickness_nm) sub-region pieces that together
        exactly cover the already-computed, already-tested final polygon
        `clip_pts` -- given each end's own independent pass ranking (see
        _end_depth_ranking). The two ends' bands are each built with the
        OTHER end pinned to its own loosest (rank-0, final) position, so
        a band is confined to a thin strip near its own end (a real
        design's feature length is always many times the shadow depth
        scale, so the two ends' bands never spatially overlap) --
        NEAR_i \\ NEAR_(i+1) is reached by exactly the top-(i+1)-ranked
        passes at that end (thickness = their sum), and the innermost
        region (both ends pinned to their tightest/worst-ranked position)
        is the 'core' every committed pass reaches, at the full summed
        thickness. Degrades to a single (clip_pts, total_thickness) piece
        whenever there's nothing to split (0 or 1 total pass) or if the
        geometry construction fails for ANY reason -- the OUTER
        silhouette this draws is always clip_pts itself (or pieces that
        exactly tile it), so this can never change what's already been
        validated to draw correctly, only how it's colored inside.

        Significant bug fix, against a real patch group where
        the post-deposition view did not reflect the supposed extra
        deposition amount even where the blue-hatch overlay indicated
        one: each candidate used to
        be built from tip-only shifts of the ORIGINAL nominal points,
        never the width-wise (cross-axis) shift `clip_pts` already has
        baked in -- fixed by applying the same _apply_cross_axis_shadow
        shift to each candidate before intersecting with `clip_poly`.

        Generalized model -- see _pass_footprint_overlay's own
        docstring for the full writeup: this near/far-axial-only banding
        (further bolting on a single COMBINED cross-axis edge, as the
        fix above did) is
        itself now only the FALLBACK path, used when the caller omits
        the new `passes`/`pass_footprint_fn` parameters (an older
        call site or test). When both are supplied, this instead builds
        each real active pass's own COMPLETE 2D footprint via
        `pass_footprint_fn(theta) -> footprint_or_None` (a callback the
        caller builds from whichever per-pass computation already
        applies to this feature kind -- e.g. a finger's own
        _compute_finger_shadowed_pieces called with a synthetic single-
        theta run, reusing its already-validated per-pass physics,
        including electrode-crossing, verbatim) and overlays them via
        _pass_footprint_overlay -- correctly capturing a mis-angled
        pass's own real decoherence from its siblings in BOTH the axial
        AND cross-axis dimensions AT ONCE, for any combination of
        thetas, not just the two special cases handled below."""
        near_total = sum(t for _s, t in near_ranked)
        far_total = sum(t for _s, t in far_ranked)
        total = near_total if near_ranked else far_total
        fallback = [(clip_pts, total)]

        if pass_footprint_fn is not None and passes:
            # A `passes` entry may be a
            # 3-tuple (theta, thickness, alpha) -- this pass's own real
            # per-pass alpha, threaded through to `pass_footprint_fn` so
            # a finger/plate's own multi-pass thickness-shading gradient
            # (this function's whole reason to exist) reflects each
            # pass's own tilt, not always the shared Active-alpha field.
            # An old 2-tuple entry (no per-pass alpha available to this
            # caller) still works -- `a` is simply None, and every
            # `pass_footprint_fn` implementation already treats a None
            # alpha_override as "use the shared fallback", exactly
            # today's pre-fix behavior.
            real_passes = [(t, th, (rest[0] if rest else None)) for t, th, *rest in passes if t is not None]
            if len(real_passes) >= 2:
                footprints = [(pass_footprint_fn(t, a), th) for t, th, a in real_passes]
                return self._pass_footprint_overlay(footprints, clip_pts)

        n_near, n_far = len(near_ranked), len(far_ranked)
        if n_near <= 1 and n_far <= 1:
            return fallback
        try:
            clip_poly = sg.Polygon(clip_pts).buffer(0)
            if clip_poly.is_empty or clip_poly.area < 1e-9:
                return fallback
            near_loose = near_ranked[0][0] if near_ranked else 0.0
            far_loose = far_ranked[0][0] if far_ranked else 0.0

            def shifted(near_depth, far_depth):
                pts = self._compute_shadowed_polygon(
                    nominal_points, near_end, far_end,
                    abs(near_depth), near_depth >= 0,
                    abs(far_depth), far_depth >= 0)
                if thetas:
                    pts = self._apply_cross_axis_shadow(pts, axis_toward_far, thetas, dx_um, dy_um, origin=origin)
                    if pts is None:
                        return sg.Polygon()  # fully self-shadowed for this candidate -- no metal here
                poly = sg.Polygon(pts).buffer(0)
                return poly.intersection(clip_poly)

            pieces = []
            for i in range(n_near - 1):
                outer = shifted(near_ranked[i][0], far_loose)
                inner = shifted(near_ranked[i + 1][0], far_loose)
                thickness = sum(t for _s, t in near_ranked[:i + 1])
                pieces.append((outer.difference(inner), thickness))
            for i in range(n_far - 1):
                outer = shifted(near_loose, far_ranked[i][0])
                inner = shifted(near_loose, far_ranked[i + 1][0])
                thickness = sum(t for _s, t in far_ranked[:i + 1])
                pieces.append((outer.difference(inner), thickness))
            core_near = near_ranked[-1][0] if near_ranked else near_loose
            core_far = far_ranked[-1][0] if far_ranked else far_loose
            pieces.append((shifted(core_near, core_far), total))

            result = []
            for region, thickness in pieces:
                if region.is_empty:
                    continue
                geoms = list(region.geoms) if hasattr(region, "geoms") else [region]
                for g in geoms:
                    if hasattr(g, "exterior") and g.exterior is not None and g.area > 1e-9:
                        result.append((list(g.exterior.coords), thickness))
            return result if result else fallback
        except Exception:
            return fallback

    def _patch_pass_axial_positions(self, axis_toward, t1, t2, th1, th2, dx1_um, dy1_um, dx2_um=None, dy2_um=None):
        """Each pass's own REAL axial (tip) boundary position at ONE
        patch end, as a signed delta from the nominal edge.

        Physics fix, reverting
        the earlier "shrink-then-extend CASCADE coupling" this function
        used to implement: the resist trench is fixed, and the shadowing
        should not depend on the previous feature or deposition pass of
        a feature -- it should depend only on the shape of the trench
        itself. The resist trench (the physical opening in the bilayer resist)
        is cut once, before any deposition happens, and never changes
        shape between passes -- what each pass deposits is governed
        SOLELY by that fixed opening and that pass's own angle/tilt, so
        pass 2's own reach can never depend on where pass 1's metal
        happened to end up. The earlier cascade (pass 2's extend adding
        pass 1's shrink, i.e. `s1 + s2`, when pass 1 shrinks an end and
        pass 2 extends it) had it backwards: it made pass 2's own
        boundary artificially SHORTER than pass 2's true independent
        reach (e.g. pass 1 shrinks -0.5, pass 2 independently extends to
        +0.3 past nominal -- the old formula reported pos2 = -0.2,
        understating pass 2's real reach by 0.5). Each pass's own
        position is now simply its own independent signed depth from the
        nominal (fixed-trench) edge, EXACTLY like a finger/plate already
        computes via _net_depth_multi (same "furthest pass wins, order-
        and-count-independent" rule) -- there was never a real physical
        reason for patches to be the one feature type with coupling
        between passes, and there no longer is one. This is the single
        source of truth for a patch pass's own real axial reach, reused
        both by the thickness-banding overlay below
        (_patch_thickness_bands) and by
        _compute_one_patch_shadowed_pieces's own final-boundary
        computation, which mirrors this same independent-per-pass model
        inline for its own reasons (kept separate there to avoid a wider
        signature change).

        `dx2_um`/`dy2_um` are OPTIONAL
        trailing params for pass 2's own dx/dy -- when omitted (None,
        the default), pass 2 falls back to using `dx1_um`/`dy1_um` too,
        i.e. today's exact single-shared-dx/dy behavior, byte-identical
        for every existing caller. When given, pass 1 and pass 2 each
        get their OWN real dx/dy (from their own real, possibly
        different, alpha) -- no existing test calls this function
        directly, so this additive signature change carries no
        back-compat risk.

        Returns [(pos1, th1), (pos2, th2)] -- pos_i is pass i's own real
        signed axial position at THIS end (>0 extends outward from
        nominal, <0 shrinks inward), computed independently of the other
        pass."""
        if dx2_um is None:
            dx2_um = dx1_um
        if dy2_um is None:
            dy2_um = dy1_um
        a1 = self._shadow_alignment(axis_toward, t1)
        a2 = self._shadow_alignment(axis_toward, t2)
        d1, e1 = self._scaled_shadow_depth(dx1_um, dy1_um, a1)
        d2, e2 = self._scaled_shadow_depth(dx2_um, dy2_um, a2)
        s1 = d1 if e1 else -d1
        s2 = d2 if e2 else -d2
        pos1, pos2 = s1, s2  # each pass's own reach from the fixed nominal trench edge -- no cross-pass coupling
        return [(pos1, th1), (pos2, th2)]

    def _patch_end_band(self, axis_toward, t1, t2, th1, th2, dx1_um, dy1_um, dx2_um=None, dy2_um=None):
        """Patches' own analogue of _end_depth_ranking -- returns
        [(value, thickness, theta), ...] sorted DESCENDING by value (the
        `theta` is carried alongside so a caller can further narrow a
        single-pass-owned band by that ONE pass's own cross-axis reach --
        see _patch_thickness_bands' own "per-shell cross-axis" step,
        added after a direct report that patches showed axial (tip)
        decoherence but never any visible cross-axis (width/height)
        decoherence between two passes at genuinely different angles).
        Same shape _end_depth_ranking returns for fingers/plates (plus
        theta), so the shared _thickness_shaded_pieces_for_ends
        nested-shell algorithm can still be reused verbatim for the pure
        axial fallback path. Patches no longer have any
        cross-pass coupling (see _patch_pass_axial_positions, which this
        delegates to) -- each pass's own real boundary at an end is
        simply its own independent signed depth from the fixed nominal
        trench edge, same as a finger/plate. This just pairs each pass's
        already-independent position with its own thickness and theta
        and sorts, matching _end_depth_ranking's own contract (index 0 =
        whichever pass's own real boundary reaches furthest outward at
        this end -- the real final boundary here is exactly max(value),
        matching _compute_one_patch_shadowed_pieces's own final-boundary
        computation).

        `dx2_um`/`dy2_um` are the same
        optional, pass-2-own-dx/dy params documented on
        _patch_pass_axial_positions, which this simply forwards to."""
        positions = self._patch_pass_axial_positions(axis_toward, t1, t2, th1, th2, dx1_um, dy1_um, dx2_um, dy2_um)
        ranked = [(pos, th, theta) for (pos, th), theta in zip(positions, (t1, t2))]
        ranked.sort(key=lambda triple: triple[0], reverse=True)
        return ranked

    def _patch_thickness_bands(self, patch_shape, near_end, far_end, axis_toward_near, axis_toward_far,
                                patch_thetas, patch_thicknesses, dx1_um, dy1_um, clip_pts, dx2_um=None, dy2_um=None):
        """Patch-specific thickness banding -- patches never exceed 2
        real committed passes (compute_recommended_angles/build_
        simulation_result never produce more). Degrades to a single
        (clip_pts, total_thickness) piece for a single-pass patch, an
        empty theta/thickness list, or on ANY geometry-construction
        failure -- same safety-net convention as
        _thickness_shaded_pieces_for_ends.

        Generalized model: each deposition step should be
        treated as a layer, separate from the others, generalizing this
        model so that it works with every feature that is deposited
        more than once.

        HISTORY (all four attempts kept here so the reasoning that ruled
        each one out isn't lost -- this function has been rewritten
        multiple times this round and the failure modes are subtle):

        Attempt 1 (nested-shell, axial-only) reused the shared
        _thickness_shaded_pieces_for_ends algorithm (already correct for
        fingers/plates) with patch-specific ranked end values from
        _patch_end_band. This is real and correct for AXIAL (tip)
        banding -- a patch's two passes really do show a two-tone hatch
        along its length -- but it applies ONE combined (hull) cross-
        axis width UNIFORMLY to every band, so it can never show any
        cross-axis (width/height) decoherence at all.

        Attempt 2 (per-shell cross-axis narrowing) tried to patch that
        gap by narrowing each single-pass-owned axial shell to that
        pass's own solo cross-axis reach, keeping the nested-shell
        structure otherwise intact. Found against a real
        design with two genuinely different-angle patch passes (20deg/
        170deg): the patch decoherence did not actually show -- both
        passes still rendered at the same height as each other. Root
        cause found while
        fixing that report: the far-end shell's own construction
        (outer_f.difference(inner_f)) could degenerate when inner_f
        collapsed to empty, silently returning the FULL envelope as the
        far shell -- completely overlapping the near shell and painting
        over whatever cross-axis narrowing it had. A complement-based
        fix (far_outer = clip - near_outer - core) closed that one
        overlap, but a direct numerical check afterward (thetas=[20,170])
        turned up a SECOND, structural overlap: 'core' (meant to be the
        axial region reached by both passes) and 'near_outer' (meant to
        be reached ONLY by the near end's own winner) came out spanning
        the exact same x-range, because core's own construction pins its
        near boundary to the near end's LOSING pass's value from
        _patch_end_band -- a value ranked at the NEAR end -- while
        near_outer's inner boundary is pinned to that same value, so
        the two shells are only as disjoint as the nested-shell
        algorithm's own end-value bookkeeping, which does not hold once
        cross-axis narrowing (rather than plain axial nesting) is
        layered on top. This whole nested/narrowed hybrid was
        fundamentally the wrong shape for the problem.

        Attempt 3 (this one, ADOPTED): retire the nested-shell approach
        entirely for patches and instead reuse _pass_footprint_overlay
        verbatim -- the exact same N-way per-pass overlay combinator
        that already gives fingers and plates their real cross-axis
        decoherence (see _finger_pass_footprint/_plate_thickness_bands).
        Each pass's own COMPLETE 2D footprint is built independently:
        its own real axial position at BOTH ends via
        _patch_pass_axial_positions (already cascade-aware -- computed
        fresh per end, so a pass's credited boundary is never mixed
        across ends), intersected with that pass's own SOLO cross-axis
        reach (_apply_cross_axis_shadow with a single-element theta
        list -- confirmed safe independently of the axial cascade, since
        _cross_axis_boundaries' own docstring documents cross-axis
        passes as combined with NO coupling at all). _pass_footprint_overlay
        then handles everything else: pairwise band construction between
        the two footprints, and -- critically -- folding any leftover
        clip-area neither footprint's own honest reach covers into one
        additional region at full (both-pass) thickness, exactly the fix
        already applied there for fingers (see that function's own
        fix comment).

        This SAME footprint-overlay reuse was tried once before, early
        on, and rejected: for a patch design with two very different
        deposition angles (e.g. [20deg,180deg])
        with an aggressively large shadow throw, it dropped the computed
        band-union area to barely a fifth of the real clip area, which
        was diagnosed at the time as the axial cascade producing a
        self-crossing/inverted per-pass quadrilateral. Re-verified
        numerically here (including that same large-throw scenario)
        with today's _pass_footprint_overlay: no self-crossing,
        symmetric_difference against the real clip polygon is exactly
        0.0, and no two returned bands overlap, in every case tried. The
        real explanation: that earlier attempt PRE-DATES
        _pass_footprint_overlay's own leftover-fold fix (added later,
        for fingers, via the mis-angled-finger
        silhouette-gap report) -- without it, only the DIRECT
        intersection/difference pieces between the two per-pass
        footprints were counted, and for two solo per-pass footprints
        that barely overlap each other (the common case -- most of a
        patch's interior is only reachable via the ENCLOSING HULL's
        generosity, not by either pass's own strict solo reach), that
        direct-piece total really can be a small fraction of the real
        area. It was never a self-crossing bug; it was the same
        incomplete-coverage bug already root-caused and fixed once for
        fingers, just not yet retroactively reused here. Fixing it at
        the shared _pass_footprint_overlay level, once, now correctly
        covers patches too with no patch-specific leftover logic needed.

        Falls back to one flat (clip_pts, total) piece on any
        construction failure -- this can only ever refine internal
        coloring, never the outer silhouette (which comes from the
        separately-computed, unchanged official envelope math)."""
        total = sum(patch_thicknesses) if patch_thicknesses else 0.0
        fallback = [(clip_pts, total)]
        if len(patch_thetas) < 2 or len(patch_thicknesses) < 2:
            return fallback
        t1, t2 = patch_thetas[0], patch_thetas[1]
        th1, th2 = patch_thicknesses[0], patch_thicknesses[1]

        def _own_footprint(theta_i, pass_idx):
            """Pass `pass_idx`'s (0 or 1) own complete real 2D footprint:
            its own cascade-aware axial position at BOTH ends (each
            queried fresh from _patch_pass_axial_positions for that
            end -- never mixed with a value computed for the other
            end or the other pass), narrowed by that SAME pass's own
            solo cross-axis reach. Returns None (not a bug -- just 'this
            pass claims no independent territory of its own') if either
            the axial or the cross-axis construction collapses to
            nothing; _pass_footprint_overlay already treats a None entry
            as 'this pass contributes only via the shared envelope.'"""
            try:
                pos_near = self._patch_pass_axial_positions(
                    axis_toward_near, t1, t2, th1, th2, dx1_um, dy1_um, dx2_um, dy2_um)[pass_idx][0]
                pos_far = self._patch_pass_axial_positions(
                    axis_toward_far, t1, t2, th1, th2, dx1_um, dy1_um, dx2_um, dy2_um)[pass_idx][0]
                pts = self._compute_shadowed_polygon(
                    patch_shape.points, near_end, far_end,
                    abs(pos_near), pos_near >= 0, abs(pos_far), pos_far >= 0)
                if pts is None:
                    return None
                axial_poly = sg.Polygon(pts).buffer(0)
                if axial_poly.is_empty or axial_poly.area < 1e-9:
                    return None
                # this pass's own solo cross-axis reach uses ITS OWN
                # dx/dy (pass_idx 0 -> dx1/dy1, pass_idx 1 -> dx2/dy2 if
                # given, else falls back to dx1/dy1 -- see
                # _patch_pass_axial_positions' own docstring for the
                # same fallback contract), never the other pass's.
                own_dx = dx1_um if pass_idx == 0 else (dx2_um if dx2_um is not None else dx1_um)
                own_dy = dy1_um if pass_idx == 0 else (dy2_um if dy2_um is not None else dy1_um)
                cross_pts = self._apply_cross_axis_shadow(pts, axis_toward_far, [theta_i], own_dx, own_dy)
                if cross_pts is None:
                    return None
                cross_poly = sg.Polygon(cross_pts).buffer(0)
                if cross_poly.is_empty or cross_poly.area < 1e-9:
                    return None
                narrowed = axial_poly.intersection(cross_poly)
                return narrowed if not narrowed.is_empty else None
            except Exception:
                return None

        try:
            fp1 = _own_footprint(t1, 0)
            fp2 = _own_footprint(t2, 1)
            bands = self._pass_footprint_overlay([(fp1, th1), (fp2, th2)], clip_pts)
            return bands if bands else fallback
        except Exception:
            return fallback

    def _compute_shadowed_polygon(self, points, stub_end, patch_end, stub_depth, stub_extend, patch_depth, patch_extend):
        """Shifts a rectangle's two ends independently to produce the
        ACTUAL final shape after shadow evaporation, rather than just
        annotating the nominal drawn shape with dimension bands.
        extend=True moves that end AWAY from the other end (grows it);
        extend=False moves it TOWARD the other end (shrinks it) -- same
        convention _draw_shadow_band already uses. Each corner is
        assigned to whichever end it's geometrically closer to. Verified
        against a hand-computed case (shrink one end by dx, extend the
        other by dy) before using it here."""
        fx, fy = patch_end[0]-stub_end[0], patch_end[1]-stub_end[1]
        flen = math.hypot(fx, fy) or 1.0
        axis_hat = (fx/flen, fy/flen)
        new_points = []
        for p in points:
            proj_stub = (p[0]-stub_end[0])*axis_hat[0] + (p[1]-stub_end[1])*axis_hat[1]
            proj_patch = (p[0]-patch_end[0])*axis_hat[0] + (p[1]-patch_end[1])*axis_hat[1]
            if abs(proj_patch) < abs(proj_stub):
                sign = 1.0 if patch_extend else -1.0
                new_p = (p[0] + axis_hat[0]*patch_depth*sign, p[1] + axis_hat[1]*patch_depth*sign)
            else:
                sign = -1.0 if stub_extend else 1.0
                new_p = (p[0] + axis_hat[0]*stub_depth*sign, p[1] + axis_hat[1]*stub_depth*sign)
            new_points.append(new_p)
        return new_points

    def _apply_cross_axis_shadow(self, points, axis_hat, thetas, dx_um, dy_um, origin=None):
        """Generalizes the existing shadow model to a feature's two LONG
        edges (its own WIDTH/linewidth), not just its two short (tip)
        ends. A real failure mode, diagnosed against a real SEM
        image of a Manhattan-style patch design where the patches ran
        orthogonal to the angle originally assumed for the Plassys
        deposition: the shadowing effect covered the long side of the
        patches, which meant that nothing got deposited at all (at least
        until the linewidth was greater than the length of the shadow).
        The existing model
        (_shadow_alignment/_scaled_shadow_depth/_net_depth_multi) only
        ever applies dx/dy shrink-or-extend to a feature's two SHORT tip
        ends, scaled by |align| against the feature's own LENGTH axis --
        at exactly 90 deg off (align=0 at both tips), it reports ZERO
        effect, which is silently backwards: a deposition angle
        perpendicular to a feature's own drawn axis is the WORST case,
        not a harmless one.

        Bug fix, found against a real design (theta
        changed from the finger's own drawn axis by only 5deg): the
        FIRST version of this function (see below, "MODELING CHOICE")
        applied the SAME shrink depth (scaled by |align| only, direction
        discarded) to BOTH long edges at once -- ray-tracing a SINGLE
        directional deposition can never do that. A single deposition
        angle should only ever shadow one side; the two-shadows behavior
        would only be correct if the design had actually been deposited
        twice, at two different angles. That is exactly right, and it's
        exactly how the SHORT tip ends already work one axis over
        (_shadow_alignment's own sign says which end is "downhill"/
        shrinks and which is "uphill"/extends) -- the old cross-axis
        code just never carried that same signed logic to the LONG
        edges, discarding the sign via abs() and shrinking both.

        FIXED, delegated to the shared _cross_axis_boundaries (also used
        by this feature's own visualization, _draw_cross_axis_shadow_
        bands, so the two can never disagree) -- no new physics beyond
        what's already validated for the tip ends, just applied along
        perp_hat instead of axis_hat:
          - the edge whose OUTWARD normal points AWAY from theta
            (negative alignment) is the one metal doesn't reach for a
            given pass -- it's the ONLY edge that pass shrinks, by
            dx_um*|align|.
          - the OPPOSITE edge (theta points toward it) is unobstructed
            for that pass and gets the same small overspray the tip
            model already credits an uphill end with, dy_um*|align|.
          - the shrink is NOT clamped at the centerline: if it eats
            past the strip's own middle, the shadow has genuinely swept
            all the way across a linewidth this thin, continuing to
            erode into the far (extending) edge's own territory --
            exactly mirroring _compute_shadowed_polygon's one-sided
            "shift one end toward the other" tip logic, just applied
            perpendicular to it.
          - MULTIPLE active passes are each evaluated on their OWN,
            independently, and the surviving result is the union of
            whichever passes individually still bridge the linewidth at
            all (see _cross_axis_boundaries' own docstring for why the
            tip model's "furthest pass wins per edge" rule does NOT
            transfer here -- verified directly against a real SEM-
            matched scenario, where using that rule incorrectly
            resurrected metal for two passes that each, alone, already
            fully self-shadow this feature).

        Returns the shifted points, or None if every active pass
        individually fails to bridge the linewidth at all -- meaning
        this pass set deposits NO metal here at all.

        Significant bug fix, found against a real
        finger/adhesion-plate connection (changing the finger's
        committed deposition theta from its own drawn axis by 30deg):
        the junction finger no longer stayed centered on the adhesion
        plate. Root cause -- this used
        to RECONSTRUCT every point by SNAPPING it to one of exactly two
        flat values (`plus_new` or `-minus_new`), discarding each
        point's own original perpendicular position entirely. That's
        harmless for a finger/patch (always a plain 4-corner rectangle,
        so every point on a given side already shares one perp value --
        snapping it to the new boundary is identical to translating it).
        But a plate's own post-shadow shape, by the time this runs, is
        NOT a plain rectangle: _compute_plate_shadowed_points has
        already carved a stepped near edge (see its own Bug 6/6b/6c
        history) whose CENTER STRIP -- the part permanently, physically
        connected to the finger, deliberately excluded from that
        near-edge shadow carving so the connection can never break --
        sits at a DIFFERENT, narrower perpendicular position than the
        wider shoulders and far edge. Snapping ALL of a plate's "+"-side
        points to one flat value and all "-"-side points to another
        FLATTENS that entire stepped structure onto the plate's own
        outer envelope, silently destroying the finger-width center
        strip the shoulder mechanism spent three rounds getting right --
        confirmed directly: at a real off-axis theta, every one of a
        plate's near-edge points (center-strip AND shoulder alike)
        collapsed onto just two coordinate values instead of preserving
        the distinct step.

        Fixed by TRANSLATING each point by a per-side DELTA (how far
        that side's own boundary net-shifted) instead of snapping it to
        an absolute value. This is a strict generalization, not a
        behavior change for the already-tested rectangle case: for a
        rectangle, every point on a given side already sits at exactly
        that side's own `plus_extent`/`-minus_extent`, so translating it
        by `boundary_plus - plus_extent` lands it at exactly
        `boundary_plus` -- bit-for-bit the same result the old snap
        produced. For a plate's stepped near edge, the SAME delta now
        correctly shifts the wide shoulders AND the narrower, distinct
        center strip by the same physical amount, preserving the step
        instead of erasing it.

        The other half of the fix is `origin`: perp/axis position is
        normally measured from `points`' own centroid, which is exactly
        right for a self-contained finger/patch (always symmetric about
        its own drawn axis, so its centroid already sits ON that axis
        at perp=0). A plate's own centroid is NOT guaranteed to sit on
        its finger's axis line at all (a real, possibly off-center
        finger-to-plate connection is exactly what `finger_perp_offset`
        in _compute_plate_shadowed_points already has to account for) --
        so classifying the plate's OWN points as "+"/"-" from its own
        centroid could disagree with how the finger itself classifies
        the very same physical side, right at the seam between them.
        Passing an explicit `origin` -- any point that's actually ON the
        shared finger axis line, e.g. the finger's own patch_end -- for
        BOTH the finger's and its plate's calls removes that risk
        entirely: moving the reference point along the axis (never
        across it) can't change a perpendicular projection at all, so
        this costs nothing for the finger's own already-correct call and
        guarantees the finger and its plate agree on which side is which
        at their real physical seam. Defaults to points' own centroid
        (today's behavior) when omitted, matching every existing
        finger/patch call site exactly."""
        if not thetas:
            return points
        perp_hat = (-axis_hat[1], axis_hat[0])

        if origin is not None:
            cx, cy = origin
        else:
            cx = sum(p[0] for p in points) / len(points)
            cy = sum(p[1] for p in points) / len(points)

        def perp_proj(p):
            return (p[0] - cx) * perp_hat[0] + (p[1] - cy) * perp_hat[1]

        plus_extent = max(perp_proj(p) for p in points)
        minus_extent = max(-perp_proj(p) for p in points)
        boundary_plus, boundary_minus, any_effect = self._cross_axis_boundaries(
            perp_hat, plus_extent, minus_extent, thetas, dx_um, dy_um)
        if not any_effect:
            return points
        if boundary_plus is None:
            return None  # every active pass individually fails to bridge the linewidth -- no metal survives here

        delta_plus = boundary_plus - plus_extent            # signed: how far the "+" side net-shifted
        delta_minus = boundary_minus - (-minus_extent)      # signed: how far the "-" side net-shifted

        new_points = []
        for p in points:
            delta = delta_plus if perp_proj(p) >= 0 else delta_minus
            new_points.append((p[0] + perp_hat[0] * delta, p[1] + perp_hat[1] * delta))
        return new_points

    def _apply_finger_shoulder_patch_end_shadow(self, f, poly_pts, associated_plate, depth, extend):
        """Gap fix: the shadowing of a wider finger and
        a thinner adhesion plate needs to work similarly but opposite to
        the case where the side shoulders of a wider adhesion plate were
        shadowed while the two shapes stayed intact together -- the same
        mechanism should apply no matter which side is wider.

        _compute_plate_shadowed_points already handles a plate WIDER
        than its own finger correctly: only the plate's own exposed
        "shoulders" (the strips of ITS width sticking out past the
        finger's linewidth) get a real near-edge shadow shrink/extend;
        the center strip (matching the finger's own width) is never
        touched, so the two stay permanently connected. But
        _compute_finger_shadowed_pieces (this function's caller) used to
        collapse EVERY "this finger has an associated plate" case into a
        single hardcoded patch_depth=0.0/always-extend rule -- correct
        whenever the plate is as wide as or wider than the finger (the
        finger's entire patch-end already sits inside the plate's own
        footprint, so there genuinely is no shoulder to shadow), but
        silently wrong the moment the PLATE is narrower than the FINGER
        -- exactly the scenario a deliberately narrow adhesion plate
        (e.g. the reported 350nm plate on a 520nm finger, built
        specifically to test whether that connection creates false
        resistances) is designed to exercise. In that case the finger's
        OWN shoulders -- the strips of ITS width sticking out past the
        narrower plate's own footprint -- are the physical mirror image
        of the plate's shoulders in the already-handled case, and need
        the identical treatment: shrink/extend on the shoulders only,
        via a real 2D boolean region (never hand-picked corners, for the
        same "diagonal house-roof" reason _compute_plate_shadowed_
        points' own Bug 6 history already documents), while the CENTER
        strip -- matching the plate's own width, at the plate's own real
        (possibly off-center) perpendicular offset from the finger's
        axis -- is never given a shadow region at all, so the finger and
        its narrower plate stay permanently connected there exactly like
        the wider-plate case does.

        Returns poly_pts completely unchanged whenever the plate is as
        wide as or wider than the finger (today's exact, already-tested
        behavior -- byte-identical, since no shoulder can exist) or
        `depth` is negligible."""
        if associated_plate is None or depth <= 0.005:
            return poly_pts
        plate_near_end, _plate_far_end, plate_w = self._project_plate_onto_finger_axis(f, associated_plate.points)
        half_finger = f.width_um / 2.0
        half_plate = plate_w / 2.0
        if half_plate >= half_finger - 0.005:
            return poly_pts  # plate as wide as or wider than the finger -- no shoulder, unaffected
        fx, fy = f.patch_end[0] - f.stub_end[0], f.patch_end[1] - f.stub_end[1]
        flen = math.hypot(fx, fy) or 1.0
        axis_hat = (fx / flen, fy / flen)
        perp = (-axis_hat[1], axis_hat[0])
        plate_perp_offset = ((plate_near_end[0] - f.patch_end[0]) * perp[0]
                              + (plate_near_end[1] - f.patch_end[1]) * perp[1])
        left_edge = plate_perp_offset - half_plate
        right_edge = plate_perp_offset + half_plate

        _FINGER_SHOULDER_GRID = 1e-6

        def _snap(geom):
            return shapely.set_precision(geom, _FINGER_SHOULDER_GRID)

        try:
            poly = sg.Polygon(poly_pts)
            if not poly.is_valid:
                poly = poly.buffer(0)
        except Exception:
            return poly_pts
        poly = _snap(poly)

        extrude = axis_hat if extend else (-axis_hat[0], -axis_hat[1])

        def shoulder_region(perp_lo, perp_hi):
            p1 = (f.patch_end[0] + perp[0] * perp_lo, f.patch_end[1] + perp[1] * perp_lo)
            p2 = (f.patch_end[0] + perp[0] * perp_hi, f.patch_end[1] + perp[1] * perp_hi)
            p3 = (p2[0] + extrude[0] * depth, p2[1] + extrude[1] * depth)
            p4 = (p1[0] + extrude[0] * depth, p1[1] + extrude[1] * depth)
            return _snap(sg.Polygon([p1, p2, p3, p4]))

        regions = []
        if left_edge > -half_finger + 0.005:
            regions.append(shoulder_region(-half_finger, left_edge))
        if right_edge < half_finger - 0.005:
            regions.append(shoulder_region(right_edge, half_finger))
        if not regions:
            return poly_pts
        combined_region = _snap(so.unary_union(regions))
        poly = _snap(poly.union(combined_region)) if extend else _snap(poly.difference(combined_region))
        if poly.is_empty:
            return None
        geoms = list(poly.geoms) if hasattr(poly, "geoms") else [poly]
        largest = max(geoms, key=lambda g: g.area)
        if not hasattr(largest, "exterior") or largest.exterior is None:
            return None
        return list(largest.exterior.coords)

    def _run_finger_thetas(self, run, i, f, theta_overrides):
        """Root-cause fix, found against a real 4-finger
        series-chain (a layered Manhattan-style junction array) design:
        every one of this file's shadow-geometry/warning/recipe
        functions used to resolve a finger's own active deposition
        theta list via `run["theta_a_list"] if i == 0 else
        run["theta_b_list"]` -- i.e. ONLY finger indices 0 and 1 ever
        read their own real data; every other finger index (2, 3, ...)
        silently got finger 1's ("Finger B"'s) list instead of its own,
        which is exactly why a horizontal chain finger ("Finger 3",
        sharing Finger A's 0deg axis) was being evaluated against Finger
        B's 270deg angle and shadowed as if it were vertical.

        `_sim_finger_layers` (and therefore `run["finger_theta_lists"]`,
        populated by `_recommit_sim_run` from the SAME source) has
        always correctly stored each finger's OWN theta history by its
        real index -- this helper is the fix that finally makes every
        consumer actually read it, instead of the old 0/1-only aliasing.
        `run["theta_a_list"]`/`run["theta_b_list"]` are kept exactly as
        they were (still finger 0/1 only) for byte-identical behavior on
        a classic 2-finger design and for every small synthetic single-
        pass `run` dict built elsewhere in this file (which only ever
        set those two legacy keys) -- `run["finger_theta_lists"]` is
        preferred when present and simply supplies what those two keys
        could never reach: finger indices 2 and up."""
        extra = run.get("finger_theta_lists")
        if extra is not None and i in extra:
            thetas = extra.get(i)
        elif i == 0:
            thetas = run.get("theta_a_list")
        elif i == 1:
            thetas = run.get("theta_b_list")
        else:
            thetas = None
        if thetas is None:
            single = theta_overrides[i] if i < len(theta_overrides) and theta_overrides[i] is not None else f.theta_toward_patch_deg
            thetas = [single]
        return thetas

    def _run_finger_alphas(self, run, i):
        """Same generalization as _run_finger_thetas, for the parallel
        per-pass alpha lists (theta_a_alphas/theta_b_alphas -> finger
        indices 0/1 only, run["finger_alpha_lists"] -> any index)."""
        extra = run.get("finger_alpha_lists")
        if extra is not None and i in extra:
            return extra.get(i)
        if i == 0:
            return run.get("theta_a_alphas")
        if i == 1:
            return run.get("theta_b_alphas")
        return None

    def _single_pass_run(self, finger_idx, theta, alpha_override=None):
        """Builds the small synthetic one-pass `run` dict used to
        recurse into _compute_finger_shadowed_pieces/
        _compute_plate_shadowed_points for exactly one isolated pass
        (e.g. a foreign-footprint or thickness-band computation).
        Generalizes the old `{"theta_a_list"/"theta_b_list": [theta]}`
        literal (finger 0/1 only) to any finger index via
        run["finger_theta_lists"], which _run_finger_thetas/
        _run_finger_alphas above now read first."""
        if finger_idx is None:
            return {}
        single_run = {"finger_theta_lists": {finger_idx: [theta]}}
        if alpha_override is not None:
            single_run["finger_alpha_lists"] = {finger_idx: [alpha_override]}
        return single_run

    def _compute_finger_shadowed_pieces(self, junction, f, i, run, theta_overrides, alpha, dx_um, dy_um):
        """Extracted so the JJ Crossing Overlap check can use the exact
        SAME finger-shadow computation as the actual Post-Shadow Result
        (multi-layer cascade, associated-plate merge, electrode-
        crossing disconnect split) instead of a separate, simplified
        approximation -- confirmed this was necessary directly: the
        risk check previously used a manually-typed generic "target
        overlap" value from Recipe and only the global alpha, completely
        ignoring which theta(s) were actually active or how many
        deposition layers existed. Returns a list of point-lists
        (usually one, possibly more if the electrode-crossing
        disconnect splits the finger, empty if zero active layers).

        Resolves this finger's own per-pass alpha (from
        run["theta_a_alphas"]/["theta_b_alphas"], falling back to
        the shared `alpha` param -- see _resolve_pass_dxdy_list) instead
        of using the one shared `dx_um, dy_um` for every theta in
        `thetas`, so a hand-edited per-pass alpha (Predicted Recipe
        Sequence) actually changes this finger's own shadow geometry.
        NOTE (pre-existing, separate limitation, out of scope here): the
        electrode-crossing shadow below still only checks `thetas[0]`
        against the single scalar `alpha`, regardless of how many passes
        are active -- a second, independent gap, unchanged by this fix.

        Series-chain generalization: thetas/alpha_key
        resolution now goes through _run_finger_thetas/_run_finger_alphas
        (see their docstrings) instead of the old finger-0/1-only
        aliasing, so finger index >= 2 finally reads its own committed
        angle history instead of silently aliasing Finger B's."""
        thetas = self._run_finger_thetas(run, i, f, theta_overrides)
        if not thetas:
            return []
        pass_alpha_hints = self._run_finger_alphas(run, i)
        try:
            pmma_nm = float(self.pmma_edit.text()) if hasattr(self, "pmma_edit") else 875.0
        except ValueError:
            pmma_nm = 875.0
        try:
            pmgi_nm = float(self.pmgi_edit.text()) if hasattr(self, "pmgi_edit") else 600.0
        except ValueError:
            pmgi_nm = 600.0
        dx_list, dy_list = self._resolve_pass_dxdy_list(thetas, pass_alpha_hints, dx_um, dy_um, pmma_nm, pmgi_nm)
        fx, fy = f.patch_end[0]-f.stub_end[0], f.patch_end[1]-f.stub_end[1]
        flen = math.hypot(fx, fy) or 1.0
        axis_toward_patch = (fx/flen, fy/flen)
        axis_toward_stub = (-axis_toward_patch[0], -axis_toward_patch[1])
        stub_depth, stub_extend = self._net_depth_multi(axis_toward_stub, thetas, dx_list, dy_list)
        associated_plate_found = self._find_associated_plate(junction, f)
        associated_plate = associated_plate_found[0] if associated_plate_found is not None else None
        if associated_plate is not None:
            shoulder_depth, shoulder_extend = self._net_depth_multi(axis_toward_patch, thetas, dx_list, dy_list)
            patch_depth, patch_extend = 0.0, True
        else:
            shoulder_depth, shoulder_extend = None, None
            patch_depth, patch_extend = self._net_depth_multi(axis_toward_patch, thetas, dx_list, dy_list)
        new_pts = self._compute_shadowed_polygon(f.points, f.stub_end, f.patch_end,
                                                  stub_depth, stub_extend, patch_depth, patch_extend)
        if associated_plate is not None:
            new_pts = self._apply_finger_shoulder_patch_end_shadow(
                f, new_pts, associated_plate, shoulder_depth, shoulder_extend)
            if new_pts is None:
                return []  # this finger's own shoulders (past its narrower plate's footprint)
                           # are fully consumed by the shadow at every active pass combined --
                           # no metal reaches them, but see the per-pass loop below for whether
                           # any INDIVIDUAL pass still covers them
        new_pts = self._apply_cross_axis_shadow(new_pts, axis_toward_patch, thetas, dx_list, dy_list,
                                                 origin=f.patch_end)
        if new_pts is None:
            return []  # this finger's active theta(s) are nearly perpendicular to its own drawn
                       # axis -- the shadow throw crosses its ENTIRE linewidth (see
                       # _apply_cross_axis_shadow) and no metal reaches it at all
        # Bug fix, found while verifying the new finger-
        # shoulder mechanism above at real oblique thetas: a finger with a
        # narrower attached plate can come out of the shoulder step with a
        # non-convex, "notched" cross-section (a fixed center strip with
        # two separate flanges extending past it on either side) that
        # _apply_cross_axis_shadow's own per-side translation was never
        # exercised against before (every PRE-EXISTING caller only ever
        # fed it a plain rectangle or the plate's simpler single-step
        # near edge) -- at a genuinely oblique theta the two flanges can
        # shift past each other or past the fixed center strip far enough
        # to self-intersect. Repaired with the exact same buffer(0)-and-
        # take-largest-piece idiom already used for this same class of
        # GEOS self-intersection elsewhere in this file (the per-pass
        # cascade just below, and _compute_plate_shadowed_points' own
        # near-edge construction).
        try:
            _finger_check_poly = sg.Polygon(new_pts)
            if not _finger_check_poly.is_valid:
                _finger_check_poly = _finger_check_poly.buffer(0)
                if _finger_check_poly.is_empty:
                    return []
                _finger_geoms = list(_finger_check_poly.geoms) if hasattr(_finger_check_poly, "geoms") else [_finger_check_poly]
                _finger_largest = max(_finger_geoms, key=lambda g: g.area)
                if not hasattr(_finger_largest, "exterior") or _finger_largest.exterior is None:
                    return []
                new_pts = list(_finger_largest.exterior.coords)
        except Exception:
            pass
        # Bug fix (verified against real design
        # geometry): this used to also require associated_plate is
        # None, tying the electrode-crossing shadow to the SAME condition
        # as the overlap-length shrink above -- but they're genuinely
        # different mechanisms. The overlap-length shrink is about how far
        # the finger's own end overlaps a patch/plate lengthwise (legitimately
        # skipped -- hardcoded to always-extend -- when there's an attached
        # plate, since a wide pad doesn't shrink the same way). The
        # electrode-crossing shadow is about whether the FINGER'S OWN
        # geometry crosses the electrode's topographic step at a risky
        # angle, independent of whether a plate happens to be attached at
        # its tip -- exactly the fix already applied on the annotation side
        # (_draw_sim_shadow_visualization, its own fix comment)
        # but never carried over to this function, which computes the REAL
        # post-shadow geometry that Post-Shadow Result renders and that
        # _check_post_shadow_disconnections tests. That mismatch is exactly
        # why the Simulated Design view's shadow-region overlay could look
        # correct while Post-Shadow Result stayed fully connected and no
        # disconnection warning fired, for a NoPatch design (finger meets an
        # adhesion plate directly, no patch shape in between) at a risky
        # theta. Gate is align<0 (downhill, matching Warning #1 and
        # _electrode_shadow_addon_um), not "not patch_extend" -- patch_extend
        # is hardcoded True whenever there's an associated plate, so it can
        # never itself signal risk in that branch.
        #
        # Bug fix: the alterable Plassys tilt alpha needs to be
        # wired into the electrode shadowing calculator, since the tilt
        # affects the shadowing the electrode does. This used to check
        # ONLY thetas[0] against the single shared `alpha` scalar,
        # regardless of how many passes were actually active -- so a
        # per-pass alpha edit (already wired into every OTHER shadow
        # mechanism this file has) had no effect on this specific
        # carve. Fixed by checking EVERY active pass independently, each
        # against its OWN resolved alpha (from `run[alpha_key]`, falling
        # back to the shared `alpha` exactly like every other per-pass
        # resolution in this file) -- matching the per-pass-independent
        # model _draw_sim_shadow_visualization's own finger loop already
        # documents and implements ("each pass's own risky angle still
        # casts its own electrode shadow independently -- a different
        # pass extending safely doesn't retroactively erase a risky
        # pass's own missing-metal region"). A pass whose OWN direction
        # is safe (align>=0) never contributes a shadow region at all,
        # matching _electrode_shadow_addon_um's own "only applies on the
        # risky side" rule; the union of every risky pass's own region is
        # subtracted once, so a design with two genuinely risky passes at
        # two genuinely different tilts now gets two genuinely different
        # carves, combined, instead of only ever seeing the first pass's.
        pass_alphas = self._resolve_pass_alpha_list(thetas, pass_alpha_hints, alpha)
        risky_indices = [k for k, t_i in enumerate(thetas)
                          if f.warning_source in ("finger", "both")
                          and self._shadow_alignment(axis_toward_patch, t_i) < 0]
        if not risky_indices:
            return [new_pts]

        # Second bug fix (found and reproduced): the
        # fix above reasoned "a different pass extending safely doesn't
        # retroactively erase a risky pass's own missing-metal region"
        # and subtracted the union of every
        # RISKY pass's own electrode-shadow hole from the single SHARED
        # combined footprint (`new_pts`) above. That reasoning was
        # backwards. Each deposition pass lays down its OWN real,
        # independent layer of metal; a risky pass's electrode-shadow
        # hole only means THAT PASS's own metal has a gap there -- it
        # says nothing about whether a DIFFERENT, genuinely safe-angle
        # pass (whose own line of sight to the substrate past the
        # electrode step is never blocked at all) already deposits real
        # metal at that exact same spot. Found and reproduced: a vertical
        # finger deposited twice for extra thickness (pass 1: theta=270,
        # alpha=30 -- the safe direction here; pass 2: theta=90,
        # alpha=30) showed a disconnection warning from pass 2's own
        # risky-angle electrode shadow alone, even though pass 1 already
        # fully covers that same span from the safe side -- the theta=270
        # vertical deposition step should cover the side of the electrode
        # and not be shadowed by it, but the shadowing system only read
        # the theta=90 step and assumed the shadowing polygon was there
        # no matter what the previous step was.
        #
        # Fixed by computing EACH pass's own complete footprint
        # independently -- its own axial/cross-axis shrink from THIS
        # theta alone, with its own electrode-shadow hole cut out of
        # THAT footprint only if it's the risky direction -- then taking
        # the geometric UNION of every pass's own footprint. This is the
        # exact same "each pass is its own independently-shadowed real
        # 2D layer, combined by union" model _apply_cross_axis_shadow's
        # own docstring already documents one mechanism over ("the
        # surviving result is the union of whichever passes individually
        # still bridge ... at all"). A location is only a genuine, no-
        # metal-reaches-here open if EVERY active pass, independently,
        # fails to cover it there -- not merely because ONE risky pass
        # does, while a safe pass alongside it does not. Only entered
        # when at least one pass is actually risky (`risky_indices`
        # above) -- the overwhelmingly common all-safe case returns
        # `new_pts` untouched, byte-identical to every pre-existing test.
        per_pass_polys = []
        for t_i, dx_i, dy_i, a_i in zip(thetas, dx_list, dy_list, pass_alphas):
            stub_depth_i, stub_extend_i = self._net_depth_multi(axis_toward_stub, [t_i], [dx_i], [dy_i])
            if associated_plate is not None:
                shoulder_depth_i, shoulder_extend_i = self._net_depth_multi(axis_toward_patch, [t_i], [dx_i], [dy_i])
                patch_depth_i, patch_extend_i = 0.0, True
            else:
                shoulder_depth_i, shoulder_extend_i = None, None
                patch_depth_i, patch_extend_i = self._net_depth_multi(axis_toward_patch, [t_i], [dx_i], [dy_i])
            pts_i = self._compute_shadowed_polygon(f.points, f.stub_end, f.patch_end,
                                                    stub_depth_i, stub_extend_i, patch_depth_i, patch_extend_i)
            if associated_plate is not None:
                pts_i = self._apply_finger_shoulder_patch_end_shadow(
                    f, pts_i, associated_plate, shoulder_depth_i, shoulder_extend_i)
                if pts_i is None:
                    continue  # this pass ALONE fully consumes this finger's own shoulders past
                              # its narrower plate's footprint -- a different pass may still cover it
            pts_i = self._apply_cross_axis_shadow(pts_i, axis_toward_patch, [t_i], [dx_i], [dy_i],
                                                   origin=f.patch_end)
            if pts_i is None:
                continue  # this pass ALONE is nearly perpendicular to the finger's own drawn
                          # axis -- it deposits no metal here at all and contributes nothing
                          # to the union (a different pass may still cover this span)
            try:
                poly_i = sg.Polygon(pts_i)
                if not poly_i.is_valid:
                    poly_i = poly_i.buffer(0)
            except Exception:
                continue
            if poly_i.is_empty:
                continue
            if self._shadow_alignment(axis_toward_patch, t_i) < 0 and f.warning_source in ("finger", "both"):
                shadow_i = self._compute_electrode_shadow_region(junction, f.points, t_i, a_i)
                if shadow_i is not None and not shadow_i.is_empty:
                    try:
                        poly_i = poly_i.difference(shadow_i.buffer(0.002, join_style=2))
                    except Exception:
                        pass
            if not poly_i.is_empty:
                per_pass_polys.append(poly_i)
        if not per_pass_polys:
            return []
        try:
            combined = per_pass_polys[0] if len(per_pass_polys) == 1 else so.unary_union(per_pass_polys)
            pieces = list(combined.geoms) if hasattr(combined, "geoms") else [combined]
            result = [list(piece.exterior.coords) for piece in pieces
                     if hasattr(piece, "exterior") and piece.exterior is not None]
            if result:
                return result
        except Exception:
            pass
        return [new_pts]

    def _compute_plate_shadowed_points(self, junction, plate_shape, run, theta_overrides, alpha, dx_um, dy_um):
        """Extracted so the disconnection check can get a SPECIFIC
        plate's own post-shadow points directly, rather than trying to
        match one back out of the full _compute_post_shadow_shapes
        output -- confirmed that matching approach was actually broken:
        nothing in that flat list ties a specific returned points-list
        back to which source shape produced it, so a "find the plate
        whose finger is X" search just grabbed the first plate entry
        every time regardless of which one was actually wanted. This
        computes exactly one plate's own points directly, unambiguous
        by construction. Returns None if that plate's finger has zero
        active deposition layers (not deposited at all).

        Resolves this plate's own per-pass alpha
        the same way _compute_finger_shadowed_pieces does (same list_key
        into run["theta_a_alphas"]/["theta_b_alphas"], since a plate's
        own passes are always its owning finger's own passes -- see
        _all_deposition_pass_records' own docstring), falling back to
        the shared `alpha` param -- see _resolve_pass_dxdy_list."""
        nearest_finger = self._find_finger_for_plate(junction, plate_shape)
        idx = junction.fingers.index(nearest_finger)
        thetas = self._run_finger_thetas(run, idx, nearest_finger, theta_overrides)
        if not thetas:
            return None
        try:
            pmma_nm = float(self.pmma_edit.text()) if hasattr(self, "pmma_edit") else 875.0
        except ValueError:
            pmma_nm = 875.0
        try:
            pmgi_nm = float(self.pmgi_edit.text()) if hasattr(self, "pmgi_edit") else 600.0
        except ValueError:
            pmgi_nm = 600.0
        dx_list, dy_list = self._resolve_pass_dxdy_list(thetas, self._run_finger_alphas(run, idx), dx_um, dy_um, pmma_nm, pmgi_nm)
        near_end, far_end, plate_w = self._project_plate_onto_finger_axis(nearest_finger, plate_shape.points)
        axis_toward_near = (-(far_end[0]-near_end[0]), -(far_end[1]-near_end[1]))
        nl = math.hypot(*axis_toward_near) or 1.0
        axis_toward_near = (axis_toward_near[0]/nl, axis_toward_near[1]/nl)
        axis_toward_far = (-axis_toward_near[0], -axis_toward_near[1])
        depth_near, extend_near = self._net_depth_multi(axis_toward_near, thetas, dx_list, dy_list)
        depth_far, extend_far = self._net_depth_multi(axis_toward_far, thetas, dx_list, dy_list)
        perp = (-axis_toward_far[1], axis_toward_far[0])
        half_plate = plate_w / 2.0

        # Significant bug fix (direct user report,
        # found by ruler-measuring Post-Shadow Result against Simulated
        # Design's annotation, in THREE stages): an earlier version
        # hardcoded the near end to depth=0/always-extend (wrong -- see
        # below). The SECOND version replaced that with a uniform shift
        # of the WHOLE near edge, which severed the finger/plate
        # connection outright (the center strip must stay fixed -- see
        # the two "shoulder" bullets below). The THIRD version (this
        # one's immediate predecessor) fixed the connection by manually
        # relocating each corner and connecting them in a point list --
        # but a plate's own near edge has corners that move by DIFFERENT
        # amounts (the shoulders shift, the center strip doesn't), and
        # connecting differently-shifted corners with a single straight
        # polygon edge draws a DIAGONAL between them -- the reported
        # "house/roof" artifact, and a real, elementary drafting error:
        # manually picking new corner positions and connecting them by
        # hand isn't the same thing as describing what actually
        # happened physically.
        #
        # The fix: build the shadow/overdeposit region for each edge
        # segment as its OWN real 2D rectangle (exactly the same shape
        # the red/blue hatch already represents in Simulated Design),
        # and combine it with the plate's own NOMINAL polygon via a real
        # boolean op -- union for an extend (new metal added),
        # difference for a shrink (metal that never arrives, cut away)
        # -- instead of ever hand-picking or reconnecting corners.
        # Subtracting (or adding) an axis-aligned rectangle from a
        # rectangle can only ever produce OTHER axis-aligned edges at
        # the boundary between a touched segment and an untouched one --
        # a proper right-angle step, never a diagonal -- so restricting
        # the near edge's shadow region to just the two shoulder
        # segments (never computing or applying one across the center
        # strip at all) makes the stepped, still-connected boundary fall
        # out of the geometry on its own, exactly as it should.
        poly = sg.Polygon([
            (near_end[0] - perp[0]*half_plate, near_end[1] - perp[1]*half_plate),
            (near_end[0] + perp[0]*half_plate, near_end[1] + perp[1]*half_plate),
            (far_end[0] + perp[0]*half_plate, far_end[1] + perp[1]*half_plate),
            (far_end[0] - perp[0]*half_plate, far_end[1] - perp[1]*half_plate),
        ])

        def edge_region(edge_point, outward_dir, perp_lo, perp_hi, depth, extend):
            """The real 2D shadow/overdeposit rectangle for one segment
            of an edge -- perpendicular range [perp_lo, perp_hi] from
            the plate's own centerline, `depth` deep from the nominal
            edge. This IS the same region the red/blue hatch band
            represents; never used to relocate a corner by hand, only to
            union/difference against the plate's polygon.

            outward_dir is the direction AWAY from the plate's own body
            for this edge (axis_toward_near for the near edge,
            axis_toward_far for the far edge) -- an EXTEND region is
            built extruding outward (new metal added beyond the nominal
            edge, to be unioned in); a SHRINK region must extrude the
            OPPOSITE way, INTO the plate's own body (metal that never
            arrives, to be subtracted from area the polygon actually
            has) -- extruding a "shrink" region outward instead (a real
            bug caught here: outward_dir was used unconditionally,
            regardless of extend/shrink) builds a rectangle that never
            overlaps the polygon at all, so difference() silently
            removes nothing."""
            extrude = outward_dir if extend else (-outward_dir[0], -outward_dir[1])
            p1 = (edge_point[0] + perp[0]*perp_lo, edge_point[1] + perp[1]*perp_lo)
            p2 = (edge_point[0] + perp[0]*perp_hi, edge_point[1] + perp[1]*perp_hi)
            p3 = (p2[0] + extrude[0]*depth, p2[1] + extrude[1]*depth)
            p4 = (p1[0] + extrude[0]*depth, p1[1] + extrude[1]*depth)
            return sg.Polygon([p1, p2, p3, p4])

        # Far edge: uniform across the WHOLE width -- already confirmed
        # correct (this is the edge that's a genuine boundary all the
        # way across, no finger attached there).
        #
        # Near edge: ONLY the two shoulders outside the finger's own
        # linewidth get a shadow region at all -- the center strip
        # (matching the finger's own width) never gets one, so it can
        # never be touched by the union/difference below, and the
        # finger/plate connection there is preserved by construction,
        # not by hoping the corner math happens to line up.
        finger_perp_offset = ((nearest_finger.stub_end[0]-near_end[0])*perp[0]
                               + (nearest_finger.stub_end[1]-near_end[1])*perp[1])
        half_finger = nearest_finger.width_um / 2.0
        left_edge = finger_perp_offset - half_finger
        right_edge = finger_perp_offset + half_finger

        # Bug fix (found on a real DIAGONAL/rotated
        # finger, unlike every earlier axis-aligned
        # verification case): whenever a near-edge shoulder region only
        # partly covers the near edge (its inner corner lands strictly
        # BETWEEN the plate's two true corners, at left_edge/right_edge,
        # not ON either one -- true for both shoulders whenever a center
        # strip exists between them), GEOS has to split an existing edge
        # of `poly` at that point rather than just matching a whole
        # shared edge end-to-end. For an axis-aligned finger every
        # coordinate involved is a "nice" rational value and this
        # splits cleanly; for a rotated one every coordinate here comes
        # from irrational sqrt(2)/2-style terms, and GEOS's internal
        # orientation tests for "does this point lie exactly on that
        # edge" lose robustness at that scale -- confirmed directly: it
        # silently downgrades the cut from "carve the boundary" to
        # "drop a same-shaped, same-AREA HOLE inside the polygon"
        # instead (still perfectly `is_valid`, area reduced exactly
        # right -- only `.interiors` reveals the hole is there at all).
        # Only `.exterior.coords` is ever read back out below, so that
        # hole vanishes with no trace: the shoulder's area is genuinely
        # gone from the total, but the OUTLINE never moved there --
        # matching the reported symptom of a shoulder that never appeared
        # to get deleted, plus extra vertices from whichever OTHER
        # shoulder/edge cut carved cleanly (the reported stray lines).
        # Combining both shoulders into one union before a single
        # `.difference()` call does NOT fix this (verified directly --
        # the same hole reappears identically either way): the
        # underlying issue is the mid-edge split itself, not operation
        # order. The real fix is a precision grid: `shapely.set_precision`
        # snaps every vertex of every operand to a common, tiny grid
        # (1e-6 um = 1 picometer -- far below any physically meaningful
        # feature size here) before each boolean op, which is enough to
        # make GEOS's own internal arithmetic agree with itself and
        # carve the boundary correctly instead of guessing wrong --
        # verified directly on this exact repro case (`len(interiors)`
        # goes from 1 to 0, and the exterior boundary gains the expected
        # extra vertices instead of staying unchanged).
        _PLATE_GEOM_GRID = 1e-6

        def _snap(geom):
            return shapely.set_precision(geom, _PLATE_GEOM_GRID)

        poly = _snap(poly)
        shrink_regions = []
        extend_regions = []
        if depth_far > 0.005:
            r = _snap(edge_region(far_end, axis_toward_far, -half_plate, half_plate, depth_far, extend_far))
            (extend_regions if extend_far else shrink_regions).append(r)
        if depth_near > 0.005:
            if left_edge > -half_plate + 0.005:
                r = _snap(edge_region(near_end, axis_toward_near, -half_plate, left_edge, depth_near, extend_near))
                (extend_regions if extend_near else shrink_regions).append(r)
            if right_edge < half_plate - 0.005:
                r = _snap(edge_region(near_end, axis_toward_near, right_edge, half_plate, depth_near, extend_near))
                (extend_regions if extend_near else shrink_regions).append(r)

        if shrink_regions:
            poly = _snap(poly.difference(_snap(so.unary_union(shrink_regions))))
        if extend_regions:
            poly = _snap(poly.union(_snap(so.unary_union(extend_regions))))

        if poly.is_empty:
            return None
        geoms = list(poly.geoms) if hasattr(poly, "geoms") else [poly]
        largest = max(geoms, key=lambda g: g.area)
        if not hasattr(largest, "exterior") or largest.exterior is None:
            return None
        result_pts = list(largest.exterior.coords)

        # Gap fix: the cos(theta)
        # shadowing application rule needs to be applied to every single
        # shape in the junction, including adhesion plates and patches,
        # which it was not doing yet. Everything above only ever handles the plate's
        # near/far ends (tip-style, along the finger's own approach
        # axis) -- the width-wise (cross-axis) self-shadow mechanism
        # fingers and patches already got (_apply_cross_axis_shadow) was
        # simply never applied to plates at all. A real adhesion plate is
        # usually wide enough that this rarely changes anything visible,
        # but the mechanism itself was absent, not just negligible --
        # a thin enough plate would have shown NO width-wise shadow
        # regardless of how far off-axis theta was. Applied to the
        # ALREADY near/far-shadowed points (matching the finger/patch
        # order: tip shift first, cross-axis shrink second), using
        # axis_toward_far as the length axis so perp_hat is the plate's
        # own width direction -- the SAME shared _cross_axis_boundaries
        # core fingers/patches use, so this can't independently drift
        # from either of them.
        #
        # Significant bug fix, found after changing a
        # finger's committed deposition theta by 30deg, which left the
        # junction finger no longer centered on the adhesion plate:
        # passing no explicit origin here used to make
        # this measure perp position from THIS PLATE'S OWN centroid,
        # while the finger's own _apply_cross_axis_shadow call (in
        # _compute_finger_shadowed_pieces) measures from the FINGER's own
        # centroid. Those two centroids only agree on where perp=0 sits
        # (i.e. only classify "left side"/"right side" identically) when
        # the plate happens to be perfectly centered on the finger's own
        # axis -- true for a plain, symmetric finger/plate connection, false
        # the moment a real connection has ANY perpendicular offset
        # between finger and plate (exactly what `finger_perp_offset`
        # above already has to account for). A mismatched origin doesn't
        # move the two shapes apart in space (that risk was already
        # checked -- see the docstring history on _apply_cross_axis_
        # shadow), but it CAN make the finger and its plate disagree
        # about which of THEIR OWN edges the shadow throw is even shrinking
        # vs extending right at their shared seam, for any off-axis theta.
        # Anchoring both this call and the finger's own call at the same
        # explicit point -- `nearest_finger.patch_end`, which sits ON the
        # finger's own axis line by definition -- removes the ambiguity
        # entirely: near_end/far_end above are each the MIDPOINT of the
        # plate's own near/far corners, not guaranteed to sit exactly ON
        # that axis line themselves whenever finger_perp_offset != 0, so
        # they are not used as the origin here even though they're
        # otherwise convenient.
        cross_pts = self._apply_cross_axis_shadow(result_pts, axis_toward_far, thetas, dx_list, dy_list,
                                                    origin=nearest_finger.patch_end)
        if cross_pts is None:
            return None
        return cross_pts

    def _resolve_patch_thetas(self, junction, run, theta_overrides):
        """Which theta(s) patches actually deposit at, in priority order:
        an explicit override from the last Run Simulation click, else
        compute_recommended_angles' own patch recommendation (when
        Warning #1 concerns patches for this design), else BOTH fingers'
        own active thetas together (patches get every blanket deposition
        pass regardless of which finger they're nearest to). Factored out
        of _compute_post_shadow_shapes (which used to recompute this
        once per patch group even though it never varies by group) so
        the post-shadow-disconnection check below can resolve the exact
        same active theta(s) without risking the two ever disagreeing."""
        rec = ji.compute_recommended_angles(junction)
        patches_rec = rec.get("patches")
        global_patch_thetas = patches_rec["angles"] if patches_rec else None
        fallback_thetas = []
        for idx, other_finger in enumerate(junction.fingers):
            t = theta_overrides[idx] if idx < len(theta_overrides) and theta_overrides[idx] is not None else other_finger.theta_toward_patch_deg
            if t not in fallback_thetas:
                fallback_thetas.append(t)
        patch_thetas_override = run.get("patch_thetas_override")
        return patch_thetas_override if patch_thetas_override is not None else (global_patch_thetas if global_patch_thetas is not None else fallback_thetas)

    def _true_order_patch_thetas(self, junction, run, theta_overrides, patch_thetas):
        """Reorders a resolved patch_thetas list so index 0 is the
        chronologically FIRST patch deposition pass and index 1 the
        second, matching the REAL order the recipe generator already
        commits to.

        Bug fix, in an EARLIER version of this same
        function (found on a real double-deposition patch design):
        that version tried to derive patch order from
        whichever FINGER deposits first (apply_deposit_order's
        first-finger identity) on the theory that patches are
        blanket-deposited in the same wafer rotations as the fingers.
        That's only true when a patch's own theta literally coincides
        with one of the fingers' own active thetas -- for a design like
        this one, where the fingers deposit at their own diagonal
        angles (e.g. 315/225) and patches need a COMPLETELY SEPARATE
        pair of angles (e.g. 0/180, generated in their own dedicated
        recipe block strictly AFTER both fingers -- see
        junction_import.generate_recipe_steps), patch order has no
        relationship to finger order at all, and guessing one from
        angular closeness produced a wrong reordering that (combined
        with the new cascade math) fabricated a spurious electrode-
        crossing shadow cut that was never there before. That version
        was replaced with an unconditional ascending sort instead.

        Second bug fix: when the
        deposition of the patches was first 0deg then 180deg, the
        shadowing looked fine, but it did not change when reversed to
        180deg first and then 0deg second -- it should mirror, since
        that's a genuinely different physical process run in the
        opposite sequence. The
        unconditional ascending sort above was ONLY ever correct for the
        no-override case, where patch_thetas comes from
        compute_recommended_angles' own `sorted(set(patch_recs))` (see
        junction_import.py) and is already ascending, so re-sorting it is
        a harmless no-op. But whenever the user has committed rows to the
        Deposition Angles tree (self._sim_patch_layers, threaded through
        here as run["patch_thetas_override"]), that IS a real,
        user-chosen chronological order -- junction_import.
        generate_recipe_steps' own patch block assigns
        `patches_thetas = override_patch_thetas` VERBATIM (never sorted)
        and emits "pass 1"/"pass 2" straight from that real order. Force-
        sorting it here silently discarded the user's actual configured
        sequence and replaced it with a canonical ascending one no matter
        which way they'd set it up -- which is exactly why reversing the
        tree's row order (180 then 0, instead of 0 then 180) produced an
        IDENTICAL simulated result instead of the mirrored one: both
        orders sorted to the same [0, 180] before the cascade math ever
        saw them. Now checks for that override FIRST and preserves it
        exactly as configured; only the no-override (computed-
        recommendation) path still gets the ascending default, where it
        was always a no-op anyway."""
        override = run.get("patch_thetas_override") if run else None
        if override is not None and len(override) >= 2:
            return list(override)
        if len(patch_thetas) < 2:
            return list(patch_thetas)
        return sorted(patch_thetas)

    def _patches_for_group(self, junction, finger, patch_count):
        """The patch shapes assigned to one finger's patch group, ordered
        along the finger's own axis (stub -> patch end) -- factored out
        of _compute_post_shadow_shapes so the disconnection check below
        can get the identical assignment (nearest patch_count patches by
        distance to finger.patch_end) without re-deriving it. Deliberately
        does NOT require the patches to already be touching the finger --
        same nearest-by-distance logic junction_import._assign_shapes_to_fingers
        uses -- so a patch that a drastic edit has pulled away from its
        finger is still correctly identified as belonging to it (and can
        then be reported as disconnected), rather than silently dropped."""
        all_shapes = [s for s in junction.other_shapes if s.kind == "patch"]
        fx, fy = finger.patch_end[0] - finger.stub_end[0], finger.patch_end[1] - finger.stub_end[1]
        flen = math.hypot(fx, fy) or 1.0
        fu, fv = fx / flen, fy / flen

        def pos(s):
            cx = sum(p[0] for p in s.points) / len(s.points)
            cy = sum(p[1] for p in s.points) / len(s.points)
            return (cx - finger.stub_end[0]) * fu + (cy - finger.stub_end[1]) * fv

        nearby = sorted(all_shapes, key=lambda s: sg.Polygon(s.points).distance(sg.Point(finger.patch_end)))[:patch_count]
        return sorted(nearby, key=pos)

    def _compute_one_patch_shadowed_pieces(self, junction, finger, patch_shape, patch_thetas, alpha, dx_um, dy_um, patch_alphas=None):
        """One patch's own post-shadow polygon(s) (usually one piece,
        possibly more if the electrode-crossing shadow splits it) --
        factored out of _compute_post_shadow_shapes' per-patch loop body
        so the disconnection check below can get a SPECIFIC patch's
        post-shadow geometry directly, the exact same way the real
        Post-Shadow Result computes it, rather than duplicating this
        two-pass cascade math (already bug-fixed here more than once --
        see the bug-fix comments below) a second time. Returns a
        list of point-lists; empty only if patch_thetas is empty (not
        deposited at all -- callers should already skip that case).

        `patch_alphas` is an OPTIONAL trailing
        param -- this patch's own per-pass alpha list, ALREADY reordered
        to match `patch_thetas` (mirrors how `patch_thicknesses` already
        survives _true_order_patch_thetas' reordering, via the same
        _match_pass_thicknesses helper, just called with default=None
        here instead of 0.0 -- see that function's own docstring for
        why). Missing/None/short entries fall back to the shared `alpha`
        param, exactly like every other feature-geometry function --
        omitting it entirely reproduces today's exact
        single-shared-alpha behavior, byte-identical for every existing
        caller."""
        try:
            pmma_nm = float(self.pmma_edit.text()) if hasattr(self, "pmma_edit") else 875.0
        except ValueError:
            pmma_nm = 875.0
        try:
            pmgi_nm = float(self.pmgi_edit.text()) if hasattr(self, "pmgi_edit") else 600.0
        except ValueError:
            pmgi_nm = 600.0
        dx_list, dy_list = self._resolve_pass_dxdy_list(patch_thetas, patch_alphas, dx_um, dy_um, pmma_nm, pmgi_nm)
        fx, fy = finger.patch_end[0] - finger.stub_end[0], finger.patch_end[1] - finger.stub_end[1]
        flen = math.hypot(fx, fy) or 1.0
        fu, fv = fx / flen, fy / flen

        axis_angle, end_a, end_b, _w = ji._polygon_axis_and_ends(patch_shape.points)
        proj_a = (end_a[0] - finger.stub_end[0]) * fu + (end_a[1] - finger.stub_end[1]) * fv
        proj_b = (end_b[0] - finger.stub_end[0]) * fu + (end_b[1] - finger.stub_end[1]) * fv
        near_end, far_end = (end_a, end_b) if proj_a < proj_b else (end_b, end_a)
        axis_toward_near = (-(far_end[0] - near_end[0]), -(far_end[1] - near_end[1]))
        nl = math.hypot(*axis_toward_near) or 1.0
        axis_toward_near = (axis_toward_near[0] / nl, axis_toward_near[1] / nl)
        axis_toward_far = (-axis_toward_near[0], -axis_toward_near[1])

        if len(patch_thetas) >= 2:
            t1, t2 = patch_thetas[0], patch_thetas[1]
            depths = {}
            any_extends = {}
            for end_key, axis_toward in (("near", axis_toward_near), ("far", axis_toward_far)):
                a1 = self._shadow_alignment(axis_toward, t1)
                a2 = self._shadow_alignment(axis_toward, t2)
                depth1, extend1 = self._scaled_shadow_depth(dx_list[0], dy_list[0], a1)
                depth2, extend2 = self._scaled_shadow_depth(dx_list[1], dy_list[1], a2)
                signed1 = depth1 if extend1 else -depth1
                signed2 = depth2 if extend2 else -depth2
                # Physics fix,
                # reverting the prior "shrink-then-extend CASCADE"
                # special case that used to live here (net = signed1 +
                # signed2 when pass 1 shrank this end and pass 2
                # extended it): the resist trench is fixed, and the
                # shadowing should not depend on the previous feature or
                # deposition pass of a feature -- it should depend only
                # on the shape of the trench itself. The resist trench is cut once,
                # before any deposition, and stays fixed for every pass
                # -- pass 2's own metal reach is governed only by that
                # fixed opening and pass 2's own angle, never by where
                # pass 1's metal ended up, so there is no physical
                # mechanism for pass 2's boundary to cumulate from pass
                # 1's. The removed cascade actually made a genuinely
                # FURTHER-reaching pass 2 look SHORTER than its true
                # independent reach whenever pass 1 had shrunk that end
                # (e.g. pass 1 shrinks 0.5um in, pass 2 independently
                # extends 0.3um past nominal -- the old formula reported
                # a net of -0.2, i.e. still 0.2um short of nominal, when
                # pass 2 alone genuinely reaches 0.3um past it). Plain
                # max(signed1, signed2) -- "whichever pass's own
                # independent reach goes furthest wins" -- is exactly
                # the same order-and-count-independent combination rule
                # fingers/plates already use via _net_depth_multi; a
                # later shrink pass still never erases metal an earlier
                # pass already deposited, so that half of the union
                # guarantee is unchanged. See
                # _patch_pass_axial_positions for the same fix applied
                # to the thickness-banding overlay.
                net = max(signed1, signed2)
                depths[end_key] = (abs(net), net > 0)
                # Tracked SEPARATELY from the cumulative net above, and
                # used only to gate the electrode-crossing subtraction
                # below -- bug fix (direct user
                # report): using the cumulative net's own extend/shrink
                # direction for that gate meant a shrink-then-extend end
                # whose dx > dy (a genuine, real net shrink -- exactly
                # what the fix above was for) got treated as if NO pass
                # ever reached it at all, spuriously triggering an
                # additional electrode-topology shadow cut that was
                # never there before. But metal from pass 2's extend
                # genuinely DOES bridge the gap regardless of what pass
                # 1 did earlier -- the electrode-crossing mechanism only
                # cares whether ANY pass's own independent shadow reaches
                # across, not the cumulative resist-stack position -- so
                # this keeps the ORIGINAL (still correct) gating
                # semantics: only a doubly-risky end (neither pass
                # extends it at all) gets the extra electrode-shadow cut.
                any_extends[end_key] = extend1 or extend2
        elif len(patch_thetas) == 1:
            t = patch_thetas[0]
            depths = {}
            any_extends = {}
            for end_key, axis_toward in (("near", axis_toward_near), ("far", axis_toward_far)):
                a = self._shadow_alignment(axis_toward, t)
                depths[end_key] = self._scaled_shadow_depth(dx_list[0], dy_list[0], a)
                any_extends[end_key] = depths[end_key][1]
        else:
            depths = {"near": (0.0, True), "far": (0.0, True)}
            any_extends = {"near": True, "far": True}

        new_pts = self._compute_shadowed_polygon(
            patch_shape.points, near_end, far_end,
            depths["near"][0], depths["near"][1], depths["far"][0], depths["far"][1])
        new_pts = self._apply_cross_axis_shadow(new_pts, axis_toward_far, patch_thetas, dx_list, dy_list)
        if new_pts is None:
            return []  # this patch's active theta(s) are nearly perpendicular to its own drawn
                       # axis -- the shadow throw crosses its ENTIRE linewidth (see
                       # _apply_cross_axis_shadow) and no metal reaches it at all -- the
                       # real fully-self-shadowed failure mode this feature was built to reproduce
        # Same final subtraction step as the finger's own case: the
        # patch's far end is the electrode-facing side when patches are
        # this design's crossing mechanism -- use whichever theta
        # actually determines that end's final direction (the second
        # pass in the two-angle case, since it's the one that sets the
        # final boundary in the cascade model above) to find the real
        # crossing line and subtract the resulting shadow region. Gated
        # on any_extends, NOT depths["far"][1] -- see the comment above
        # where any_extends is built: whether the CUMULATIVE net ends up
        # a shrink is not the same question as whether metal from some
        # pass actually reaches across the gap.
        if finger.warning_source in ("patches", "both") and not any_extends["far"]:
            # Bug fix, generalizing the finger multi-pass electrode-
            # crossing fix to patches: the same fix applied to the
            # multi-pass junction fingers needs to generalize to all the
            # shapes, since patches also often get two passes, and a
            # single-layer region that doesn't get an electrode shadow
            # was still being outlined by the electrode polygon whenever
            # there were two passes.
            #
            # OLD (buggy): always subtracted only `patch_thetas[-1]`'s (the
            # LAST pass's) own electrode-shadow hole from the ONE shared
            # combined shape -- the exact same mistake already fixed for
            # fingers: a location only genuinely lacks metal if EVERY
            # active pass, independently, fails to cover it there. A
            # "single-layer" region reached by only ONE pass, whose OWN
            # crossing hole doesn't happen to overlap that spot, was still
            # being carved out whenever the OTHER pass's differently-
            # shaped hole happened to cover it -- because only one pass's
            # hole was ever consulted, regardless of the other pass's own
            # (possibly non-overlapping) geometry.
            #
            # FIX: this branch only runs when neither pass extends this
            # end (any_extends["far"] is False), so for the len>=2 case
            # BOTH t1 and t2 are already known to be the risky/shrinking
            # direction here -- unlike the finger fix's own risky_indices,
            # no extra per-pass risky check is needed. What was missing is
            # that each pass's own independent electrode-crossing hole can
            # be a DIFFERENT shape (different theta/alpha) -- metal is
            # truly absent only where BOTH holes overlap. Subtracting
            # their INTERSECTION is the algebraic equivalent of computing
            # each pass's own (shared-shape minus its own hole) footprint
            # and taking the union of the two -- de Morgan's law:
            # union_i(base - hole_i) == base - intersection_i(hole_i) --
            # exactly mirroring the finger fix's per-pass-then-union model.
            # The axial net above is now always a plain
            # max(signed1, signed2) with no cross-pass coupling, but this
            # branch was never reached for a shrink-then-extend end
            # anyway (any_extends["far"] is True there), so it is
            # unaffected either way. The single-pass case (len == 1)
            # is unchanged -- there's only ever one pass's own hole to
            # consult, exactly like before.
            resolved_alphas = self._resolve_pass_alpha_list(patch_thetas, patch_alphas, alpha)
            shadow_region = None
            if len(patch_thetas) >= 2:
                shadow_1 = self._compute_electrode_shadow_region(junction, patch_shape.points, patch_thetas[0], resolved_alphas[0])
                shadow_2 = self._compute_electrode_shadow_region(junction, patch_shape.points, patch_thetas[1], resolved_alphas[1])
                if shadow_1 is not None and not shadow_1.is_empty and shadow_2 is not None and not shadow_2.is_empty:
                    try:
                        shadow_region = shadow_1.buffer(0.002, join_style=2).intersection(shadow_2.buffer(0.002, join_style=2))
                    except Exception:
                        shadow_region = None
            else:
                crossing_theta = patch_thetas[-1] if patch_thetas else None
                if crossing_theta is not None:
                    # Bug fix (same issue as
                    # the finger's own case just above): this used to pass the
                    # single shared `alpha` scalar regardless of this crossing
                    # pass's own real per-pass alpha -- reusing `patch_alphas`
                    # (this function's own already-reordered per-pass alpha
                    # param) directly rather than re-deriving.
                    crossing_alpha = resolved_alphas[-1]
                    region = self._compute_electrode_shadow_region(junction, patch_shape.points, crossing_theta, crossing_alpha)
                    if region is not None and not region.is_empty:
                        shadow_region = region.buffer(0.002, join_style=2)
            if shadow_region is not None and not shadow_region.is_empty:
                try:
                    remaining = sg.Polygon(new_pts).difference(shadow_region)
                    pieces = list(remaining.geoms) if hasattr(remaining, "geoms") else [remaining]
                    result = [list(piece.exterior.coords) for piece in pieces
                             if hasattr(piece, "exterior") and piece.exterior is not None]
                    if result:
                        return result
                except Exception:
                    pass
        return [new_pts]

    def _compute_post_shadow_shapes(self, junction, report):
        """The ACTUAL final geometry after all depositions, factoring in
        every over- and under-shadowing effect already modeled for the
        annotation view -- reuses the EXACT same alignment/dx/dy/
        two-pass-cascade logic as _draw_sim_shadow_visualization so the
        two views can never disagree, just applied to produce real
        polygons instead of overlay bands. Returns a list of
        (points, kind, finger_index) tuples ready to draw -- finger_index
        is which junction.fingers[i] this shape belongs to (for "finger"
        and "plate" kinds -- a plate's finger_index is whichever finger
        it's physically paired with, via the same real touching-point
        check _find_associated_plate uses) or the finger whose patch
        group this shape is part of (for "patch"). This identity is what
        the Deposition Slideshow's progressive-reveal filter uses to
        decide which shapes are visible as of a given step -- added here
        rather than re-deriving it after the fact, since the shadowed
        polygon alone doesn't carry its origin.

        Extension (based on real SEM
        reference images of a fabricated junction's shade variation
        between single- and double-deposited metal): every returned tuple is
        now (points, kind, finger_index, thickness_nm) -- a shape whose
        area receives more than one committed deposition pass is split
        into thickness-banded sub-regions (see _thickness_shaded_
        pieces_for_ends / _patch_thickness_bands) rather than returned
        as one flat piece, so a doubly-deposited core can be colored
        darker than a singly-shadowed end/edge. thickness_nm can be
        None (finger/plate whose owning tree state can't be resolved --
        e.g. a synthetic `run` in a test) -- _thickness_to_color treats
        that as 'unknown', not zero.

        Extension: the white outline
        should only surround the perimeter of the overall feature, not
        the interior line thicknesses, since the difference in color
        already indicates the complicated overlaps. Every returned tuple is
        now a 5-tuple, (points, kind, finger_index, thickness_nm,
        group_id) -- group_id is a per-PIECE identity (one real,
        physically-contiguous post-shadow silhouette -- e.g. one
        specific patch's own clipped geometry, or one disconnected
        piece of a finger split by an electrode crossing), shared by
        every thickness band cut from that SAME piece. _draw_shadow_
        shapes uses this to draw each band's fill with no seam edge,
        then draw exactly ONE white outline per group around the union
        of its own bands -- so the white line traces the real outer
        silhouette only, never an internal band-to-band boundary.

        Extension ("ghost junction
        lines", corrected model -- see _ghost_junction_slivers): every
        returned tuple is now a 6-tuple, (points, kind, finger_index,
        thickness_nm, group_id, is_ghost). is_ghost=True marks a sliver
        of a DIFFERENT feature's own metal landing in THIS (kind,
        finger_index)'s target aperture -- deliberately tagged with the
        DEPOSITING pass's own kind/finger_index/thickness_nm (confirmed
        there should be no visual distinction: it renders with the same
        color as the depositing feature), so consumers that gather "this
        feature's own real footprint" by (kind, finger_index) alone --
        e.g. an area-conservation check -- must also filter on
        is_ghost=False, since a ghost sliver attributed to feature X
        physically sits inside a DIFFERENT feature's own trench, not
        X's own silhouette at all."""
        run = self._sim_last_run or {}
        alpha = run.get("alpha", 30.0)
        try:
            pmma_nm = float(self.pmma_edit.text()) if hasattr(self, "pmma_edit") else 875.0
        except ValueError:
            pmma_nm = 875.0
        try:
            pmgi_nm = float(self.pmgi_edit.text()) if hasattr(self, "pmgi_edit") else 600.0
        except ValueError:
            pmgi_nm = 600.0
        dx_um, dy_um = self._shadow_dxdy(pmma_nm, pmgi_nm, alpha)
        theta_overrides = [run.get("theta_a"), run.get("theta_b")]

        # "Ghost junction lines" corrected model:
        # patch_thetas/patch_thicknesses computed once, up front (moved
        # up from their old spot right before the patch loop -- neither
        # depends on anything the finger loop computes), so the full
        # recipe-wide pool of real deposition passes (every finger's own
        # passes + every patch's own passes, each tagged with its own
        # kind/feature-index/thickness) is available before any feature
        # kind's own ghost-line check below -- see
        # _all_deposition_pass_records/_foreign_pass_records/
        # _ghost_junction_slivers for the corrected physical model.
        patch_thetas = self._true_order_patch_thetas(junction, run, theta_overrides,
                                                      self._resolve_patch_thetas(junction, run, theta_overrides))
        patch_layers_ref = run.get("patch_thetas_override")
        if patch_layers_ref is None:
            patch_layers_ref = self._sim_patch_layers or []
        patch_thicknesses_ref = self._sim_patch_thicknesses or []
        patch_thicknesses = self._match_pass_thicknesses(patch_thetas, patch_layers_ref, patch_thicknesses_ref) if patch_thetas else []
        # This patch group's own per-pass alpha,
        # reordered to match patch_thetas exactly like patch_thicknesses
        # already is above -- default=None (NOT 0.0) so a missing/
        # unmatched entry correctly falls back to the shared Active-
        # alpha field downstream, rather than silently becoming a real
        # (and very different) alpha of 0deg.
        patch_alphas_ref = run.get("patch_alphas_override") or []
        patch_alphas = self._match_pass_thicknesses(patch_thetas, patch_layers_ref, patch_alphas_ref, default=None) if patch_thetas else []
        patch_dx_list, patch_dy_list = self._resolve_pass_dxdy_list(patch_thetas, patch_alphas, dx_um, dy_um, pmma_nm, pmgi_nm) if patch_thetas else ([], [])
        all_pass_records = self._all_deposition_pass_records(junction, run, theta_overrides,
                                                              patch_thetas, patch_thicknesses,
                                                              patch_alphas=patch_alphas,
                                                              alpha=alpha, dx_um=dx_um, dy_um=dy_um)

        shapes = []
        group_counter = [0]

        def _next_group_id():
            gid = group_counter[0]
            group_counter[0] += 1
            return gid

        for i, f in enumerate(junction.fingers):
            thetas = self._run_finger_thetas(run, i, f, theta_overrides)
            layers_ref = self._sim_finger_layers.get(i) or thetas
            thicknesses_ref = self._sim_finger_thicknesses.get(i, [])
            pass_thicknesses = self._match_pass_thicknesses(thetas, layers_ref, thicknesses_ref)
            # Bug fix: wire per-pass alpha into the multi-pass
            # shading gradient. `passes`
            # now carries this finger's own per-pass alpha as a 3rd tuple
            # element, so _finger_pass_footprint below (this finger's OWN
            # multi-pass thickness-banding overlay, previously flagged as
            # a known, deferred gap) can give each pass its own real tilt
            # instead of always falling back to the shared Active-alpha
            # field -- the actual silhouette geometry (finger_pieces,
            # just below) was already correctly per-pass; only this
            # shading-gradient overlay lagged.
            pass_alphas = self._resolve_pass_alpha_list(thetas, self._run_finger_alphas(run, i), alpha)
            passes = list(zip(thetas, pass_thicknesses, pass_alphas))
            fx, fy = f.patch_end[0] - f.stub_end[0], f.patch_end[1] - f.stub_end[1]
            flen = math.hypot(fx, fy) or 1.0
            axis_toward_patch = (fx / flen, fy / flen)
            axis_toward_stub = (-axis_toward_patch[0], -axis_toward_patch[1])
            stub_ranked = self._end_depth_ranking(axis_toward_stub, passes, dx_um, dy_um)
            patch_ranked = self._end_depth_ranking(axis_toward_patch, passes, dx_um, dy_um)

            def _finger_pass_footprint(theta, alpha_override=None, _f=f, _i=i):
                """Generalized model: this pass's
                own COMPLETE, independently-shadowed real footprint --
                reuses _compute_finger_shadowed_pieces itself, called
                with a synthetic single-theta run, so every already-
                validated per-pass physics this feature kind has
                (electrode-crossing subtraction, the associated-plate
                patch-end gating, etc.) applies automatically and can
                never drift from what the real multi-pass computation
                above actually does.

                `alpha_override`, when given (this
                pass's own real per-pass alpha, from the 3-tuple `passes`
                above), is injected into the synthetic single-theta run
                under this finger's own alpha key -- mirroring
                _plate_pass_footprint's identical pattern -- so
                _compute_finger_shadowed_pieces' own already-fixed
                per-pass alpha resolution (dx/dy AND the electrode-
                crossing carve) picks it up
                automatically. None (an old 2-tuple `passes` caller, or
                simply no override for this pass) falls back to the
                shared `alpha` scalar, unchanged.

                Series-chain generalization: the synthetic
                single-pass run now goes through _single_pass_run, keyed
                by this finger's own real index `_i` (via
                run["finger_theta_lists"]) instead of the old finger-0/1-
                only theta_a_list/theta_b_list literal -- see
                _run_finger_thetas' docstring."""
                single_run = self._single_pass_run(_i, theta, alpha_override)
                pieces = self._compute_finger_shadowed_pieces(junction, _f, _i, single_run, [None, None],
                                                               alpha, dx_um, dy_um)
                if not pieces:
                    return None
                if len(pieces) == 1:
                    return pieces[0]
                return so.unary_union([sg.Polygon(p) for p in pieces])

            # EXPLICITLY SCOPED AWAY from fingers: given the nature of
            # the bilayer resist, the thin linewidths, and a typical
            # deposition tilt (e.g. 30 degrees), fingers should not widen
            # from another feature's pass, unless a finger's own design
            # is much wider such that it enables shadowing of the finger
            # on its wide side. Unlike an adhesion plate (routinely
            # wider than the lateral shadow-throw distance, so a foreign
            # pass can genuinely reach new territory past its own edge),
            # a finger's linewidth is normally well inside that reach, so
            # it is already fully self-shadowed before any foreign pass
            # could plausibly add real width. So: NO geometric widening
            # and NO extra thickness passes for fingers -- only the
            # official, self-computed pieces below, using this finger's
            # own official `passes` only. finger_foreign is still needed
            # (unchanged) for the ghost-sliver check right after this
            # loop -- a foreign pass landing in a DIFFERENT, still-open
            # aperture is a separate physical situation (metal in a gap,
            # not lateral reach past a resist wall) and unaffected by
            # this scoping decision. Cross-finger/finger-plate overlap
            # darkening (mechanism B) still applies to fingers' own
            # unwidened shapes via _cross_feature_thickness_overlay at
            # the end of this function.
            finger_perp_hat = (-axis_toward_patch[1], axis_toward_patch[0])
            finger_foreign = self._foreign_pass_records(all_pass_records, "finger", i)

            finger_pieces = self._compute_finger_shadowed_pieces(junction, f, i, run, theta_overrides, alpha, dx_um, dy_um)

            for piece_pts in finger_pieces:
                gid = _next_group_id()
                for band_pts, thickness in self._thickness_shaded_pieces_for_ends(
                        f.points, f.stub_end, f.patch_end, stub_ranked, patch_ranked, piece_pts,
                        axis_toward_far=axis_toward_patch, thetas=thetas, dx_um=dx_um, dy_um=dy_um, origin=f.patch_end,
                        passes=passes, pass_footprint_fn=_finger_pass_footprint):
                    shapes.append((band_pts, "finger", i, thickness, gid, False))
            # "Ghost junction lines" corrected
            # model: a fragment of a DIFFERENT feature's own metal
            # landing in THIS finger's still-open aperture undercut --
            # see _ghost_junction_slivers for the full physical
            # reasoning and the real SEM evidence this was built
            # from. Uses this finger's own NOMINAL (undeposited) points
            # -- f.points, not finger_pieces (already shadow-computed,
            # and possibly already blanket-widened above) -- since the
            # aperture a foreign pass floods is the as-patterned resist
            # opening, not this finger's own final shadowed shape.
            # Attributed to (and rendered as) the FOREIGN pass's own
            # kind/thickness, never a special "ghost" hue.
            for sliver in self._ghost_junction_slivers(f.points, axis_toward_patch, finger_perp_hat,
                                                        f.patch_end, finger_foreign, dx_um, dy_um, junction=junction, alpha_deg=alpha):
                ggid = _next_group_id()
                shapes.append((sliver["pts"], sliver["kind"], sliver["feature_index"], sliver["thickness"], ggid, True))

        for pg in report.patch_groups:
            finger = junction.fingers[pg.finger_index]
            if not patch_thetas:
                continue  # zero active patch depositions -- these patches are not deposited at all
            fx, fy = finger.patch_end[0] - finger.stub_end[0], finger.patch_end[1] - finger.stub_end[1]
            flen = math.hypot(fx, fy) or 1.0
            fu, fv = fx / flen, fy / flen
            for s in self._patches_for_group(junction, finger, pg.patch_count):
                _axis_angle, end_a, end_b, _w = ji._polygon_axis_and_ends(s.points)
                proj_a = (end_a[0] - finger.stub_end[0]) * fu + (end_a[1] - finger.stub_end[1]) * fv
                proj_b = (end_b[0] - finger.stub_end[0]) * fu + (end_b[1] - finger.stub_end[1]) * fv
                near_end, far_end = (end_a, end_b) if proj_a < proj_b else (end_b, end_a)
                axis_toward_near = (-(far_end[0] - near_end[0]), -(far_end[1] - near_end[1]))
                nl = math.hypot(*axis_toward_near) or 1.0
                axis_toward_near = (axis_toward_near[0] / nl, axis_toward_near[1] / nl)
                axis_toward_far = (-axis_toward_near[0], -axis_toward_near[1])
                patch_pieces = self._compute_one_patch_shadowed_pieces(junction, finger, s, patch_thetas, alpha, dx_um, dy_um, patch_alphas)
                for piece_pts in patch_pieces:
                    gid = _next_group_id()
                    for band_pts, thickness in self._patch_thickness_bands(
                            s, near_end, far_end, axis_toward_near, axis_toward_far,
                            patch_thetas, patch_thicknesses,
                            patch_dx_list[0] if patch_dx_list else dx_um,
                            patch_dy_list[0] if patch_dy_list else dy_um,
                            piece_pts,
                            dx2_um=patch_dx_list[1] if len(patch_dx_list) > 1 else None,
                            dy2_um=patch_dy_list[1] if len(patch_dy_list) > 1 else None):
                        shapes.append((band_pts, "patch", pg.finger_index, thickness, gid, False))
                # "Ghost junction lines" corrected model -- same
                # mechanism as fingers above,
                # applied to this patch's own nominal points (s.points),
                # own axis/width direction, and the pool of every OTHER
                # feature's own passes (every finger, excluding all
                # "patch"-kind records -- a patch checking against
                # patch_thetas would just be checking its own official
                # pass, not a foreign one; see _foreign_pass_records).
                patch_perp_hat = (-axis_toward_far[1], axis_toward_far[0])
                patch_foreign = self._foreign_pass_records(all_pass_records, "patch", None)
                for sliver in self._ghost_junction_slivers(s.points, axis_toward_far, patch_perp_hat,
                                                            near_end, patch_foreign, dx_um, dy_um, junction=junction, alpha_deg=alpha):
                    ggid = _next_group_id()
                    shapes.append((sliver["pts"], sliver["kind"], sliver["feature_index"], sliver["thickness"], ggid, True))

        # Gap fix: adhesion/overlap plates are a
        # SEPARATE shape kind ("plate", not "patch") and were entirely
        # invisible to this computation before -- they never appeared
        # in the shadow visualization or the post-shadow result at all.
        # Plates deposit in the SAME step as their finger (no separate
        # recommendation angle of their own), so this uses a single
        # theta -- the attached finger's own active theta -- rather
        # than the two-pass patch model.
        # Gap fix: generalize this model so it works
        # with every feature that is deposited more than once -- the
        # junction fingers, adhesion plates, and patches. Plates previously got a single FLAT
        # thickness (the owning finger's passes summed) with zero
        # internal sub-region splitting at all -- unlike fingers and
        # patches, a plate deposited across 2+ genuinely different
        # thetas never showed ANY thickness banding, let alone the
        # generalized per-pass-footprint decoherence now applied to
        # fingers/patches above. Fixed via the new _plate_thickness_
        # bands, built the same way as the finger case just above:
        # each pass's own real footprint via _compute_plate_shadowed_
        # points itself (reused with a synthetic single-theta run, so
        # the already-validated stepped-shoulder/center-strip geometry
        # applies per-pass automatically), overlaid via the shared
        # _pass_footprint_overlay.
        plate_shapes = [s for s in junction.other_shapes if s.kind == "plate"]
        for s in plate_shapes:
            owner = self._find_finger_for_plate(junction, s)
            owner_idx = junction.fingers.index(owner) if owner in junction.fingers else None
            new_pts = self._compute_plate_shadowed_points(junction, s, run, theta_overrides, alpha, dx_um, dy_um)
            # Bug fix: whenever adhesion plates are long or
            # wide enough to be deposited at least partially in any
            # given step, the number of adhesion-plate-related
            # depositions seen in the final view should equal the number
            # of deposition steps that actually reach it.
            # `new_pts is None` here means only "this plate's
            # OWN owning finger hasn't deposited yet" -- but the plate
            # itself is still a real, already-patterned aperture sitting
            # on the open wafer, so (per the exact same "every
            # deposition step exposes the whole open wafer" blanket
            # model already used for a not-yet-introduced finger's own
            # ghost-sliver aperture, see _all_deposition_pass_records'
            # own docstring) it can still legitimately receive metal
            # from an OTHER finger's own foreign pass before its own
            # official one ever happens. The old `continue` here skipped
            # this plate's entire foreign-exposure computation outright
            # whenever its own owning finger hadn't deposited -- in the
            # Deposition Slideshow specifically (see the identical fix
            # in _compute_post_shadow_shapes_upto just below) this meant
            # a plate showed NOTHING at the step where only some OTHER
            # finger had deposited, then jumped straight to its own
            # official piece PLUS a disjoint foreign lobe the moment its
            # own finger finally deposited -- looking like "two
            # depositions appeared at once" instead of accumulating one
            # per step in the right order. Fixed by substituting this
            # plate's own NOMINAL (undeposited) points as the base
            # whenever its own official pass hasn't happened yet, so the
            # foreign-exposure machinery just below (already correct)
            # still runs against it -- but only actually emitting
            # anything for it if a real foreign contribution is found
            # (see the guard right after plate_foreign/foreign_
            # footprints/disjoint_lobes are computed) -- a plate that
            # truly has NO deposition at all yet, own or foreign, still
            # shows nothing, exactly as before.
            own_pass_pending = new_pts is None
            plate_foreign = self._foreign_pass_records(all_pass_records, "finger", owner_idx) if owner_idx is not None else []
            if own_pass_pending:
                if not plate_foreign:
                    continue  # truly nothing has deposited here yet -- own finger AND every other feature both empty
                # Bug fix: found against a real Deposition
                # Slideshow case where, in the first deposition pass, an
                # adhesion plate was rightfully red-hatched, yet its
                # post-deposition view still showed the whole plate.
                # new_pts is
                # intentionally left None here rather than substituted with
                # this plate's own full NOMINAL (undeposited) points. See
                # _widen_with_foreign_footprints' own updated docstring --
                # unioning a foreign pass's real (smaller-or-equal)
                # footprint against the FULL nominal outline is a geometric
                # no-op (union never shrinks), which is exactly why the
                # post-deposition view always showed the entire, uncut
                # plate no matter what the shadow math said. Leaving
                # new_pts as None tells _widen_with_foreign_footprints
                # there is no real official geometry to anchor to yet, so
                # it unions ONLY the foreign footprints and returns their
                # own real, correctly-shadowed combined shape instead.
            # Gap: adhesion pad shadowing/thicknesses need to
            # incorporate the overshadow extra-deposition material (where
            # the blue hatches appear) -- an adhesion plate is wide enough
            # that
            # it's routinely still exposed to OTHER fingers' own
            # deposition passes -- see a real SEM reference showing one
            # plate pushed in three different directions by three
            # different fingers' own passes -- yet _compute_plate_
            # shadowed_points above only ever used this plate's OWN
            # owning finger's official theta list. Widen the real
            # geometry itself (not just its color) by unioning in every
            # foreign pass's own solo footprint on this SAME plate
            # shape, reusing _compute_plate_shadowed_points itself
            # (synthetic single-theta run) exactly the way _plate_
            # thickness_bands' own per-pass footprint already does, so
            # this can never independently drift from that math.
            def _plate_pass_footprint(theta, alpha_override=None, _s=s, _owner_idx=owner_idx):
                single_run = self._single_pass_run(_owner_idx, theta, alpha_override)
                return self._compute_plate_shadowed_points(junction, _s, single_run, [None, None], alpha, dx_um, dy_um)

            foreign_footprints = self._foreign_blanket_footprints(plate_foreign, _plate_pass_footprint) if plate_foreign else []
            # Bug fix, found on a real test design
            # where the post-deposition view showed an adhesion plate
            # with two depositions -- the proper one, shadowed downward
            # axially, and then an unrelated one offset to the side.
            # Root cause:
            # _widen_with_foreign_footprints' own "largest lobe" bug (see
            # its docstring) used to silently REPLACE this plate's real
            # geometry with an unrelated foreign blob whenever a foreign
            # pass's own solo footprint landed disjoint from -- and
            # happened to be larger than -- this plate's own official
            # area. That's fixed now (this plate's own official geometry
            # can never be discarded that way), but a genuinely disjoint
            # foreign footprint is real, physically-deposited metal all
            # the same -- exactly the same physical situation _ghost_
            # junction_slivers already models for fingers/patches (a
            # foreign pass's metal landing disconnected from a feature's
            # own real line), just at a plate's own much larger scale
            # rather than a thin dx/dy-sized sliver. Surfaced here as its
            # own separate, real (is_ghost=True) piece per offending
            # foreign pass, rather than either wrongly merging it into
            # the main plate shape (the old bug) or silently dropping it
            # on the floor (an incomplete fix that would under-report a
            # real risk the same way a missing ghost-line warning would).
            if foreign_footprints:
                widened_pts, _multi = self._widen_with_foreign_footprints(new_pts, foreign_footprints)
                new_pts = widened_pts
            disjoint_lobes = (self._disjoint_foreign_plate_lobes(new_pts if new_pts is not None else s.points,
                                                                    plate_foreign, _plate_pass_footprint)
                               if plate_foreign else [])
            # This is the other half of the
            # own_pass_pending guard above -- a plate substituted to its
            # own nominal points because its OWN finger hasn't deposited
            # yet must still show NOTHING if no real foreign contribution
            # (touching OR disjoint) actually reaches it either, exactly
            # matching the pre-fix "not deposited at all" behavior for
            # the common case where a design's plates simply don't reach
            # each other at all.
            if own_pass_pending and not foreign_footprints and not disjoint_lobes:
                continue
            if new_pts is None:
                # Defensive only -- should be unreachable (foreign_footprints
                # empty implies disjoint_lobes is also empty, since both are
                # derived from the same per-pass footprint function over the
                # same plate_foreign records, so the continue above already
                # fires first), but guarantees real geometry reaches the
                # thickness-band/ghost-sliver code below no matter what.
                new_pts = s.points
            for lobe_pts, lobe_thickness in disjoint_lobes:
                lgid = _next_group_id()
                shapes.append((lobe_pts, "plate", owner_idx, lobe_thickness, lgid, True))
            extra_passes = [(rec["theta"], rec["thickness"], rec.get("alpha", alpha)) for rec in plate_foreign] if foreign_footprints else []
            gid = _next_group_id()
            for band_pts, thickness in self._plate_thickness_bands(junction, s, run, theta_overrides, alpha, dx_um, dy_um,
                                                                     new_pts, extra_passes=extra_passes):
                shapes.append((band_pts, "plate", owner_idx, thickness, gid, False))
            # "Ghost junction lines" corrected
            # model -- same mechanism again, applied to this plate's
            # own NOMINAL points (s.points, not new_pts -- already
            # shadow-computed, and possibly already blanket-widened
            # above) and own width direction. Recomputes the same near/
            # far/perp geometry _compute_plate_shadowed_points itself
            # derives internally (not returned outward by that
            # function) -- kept as a direct, minimal re-derivation here
            # rather than changing that function's own return signature
            # for every caller. Excludes the OWNING finger's own records
            # (a plate deposits in lockstep with its finger, pre-6ai
            # convention, and contributes no records of its own -- see
            # _all_deposition_pass_records), not a "plate" kind -- same
            # pool already computed as `plate_foreign` above.
            if owner is not None:
                near_end, far_end, plate_w = self._project_plate_onto_finger_axis(owner, s.points)
                axis_toward_near = (-(far_end[0] - near_end[0]), -(far_end[1] - near_end[1]))
                nl = math.hypot(*axis_toward_near) or 1.0
                axis_toward_near = (axis_toward_near[0] / nl, axis_toward_near[1] / nl)
                axis_toward_far = (-axis_toward_near[0], -axis_toward_near[1])
                plate_perp_hat = (-axis_toward_far[1], axis_toward_far[0])
                for sliver in self._ghost_junction_slivers(s.points, axis_toward_far, plate_perp_hat,
                                                            near_end, plate_foreign, dx_um, dy_um, junction=junction, alpha_deg=alpha):
                    ggid = _next_group_id()
                    shapes.append((sliver["pts"], sliver["kind"], sliver["feature_index"], sliver["thickness"], ggid, True))

        # NEW, section 7a ("triangular deposition artifacts"): computed
        # once per junction, from the same all_pass_records pool ghost
        # slivers use -- see _triangle_anomaly_slivers' own docstring.
        # Deliberately done LAST, after every ghost sliver above is
        # already in `shapes` -- fix for a
        # white outline seam cutting through a triangle in Post-Shadow
        # Result): _merge_triangle_group_id needs those ghost slivers
        # already present to find and reuse the matching one's group_id
        # instead of always minting a fresh one, so the two pieces of
        # what is physically the same deposited metal share one outline.
        for sliver in self._triangle_anomaly_slivers(junction, all_pass_records, dy_um, pmma_nm, pmgi_nm, alpha):
            ggid = self._merge_triangle_group_id(sliver["pts"], sliver["kind"], sliver["thickness"],
                                                  sliver["merge_finger_index"], shapes, _next_group_id)
            shapes.append((sliver["pts"], sliver["kind"], sliver["feature_index"], sliver["thickness"], ggid, True))
        return self._cross_feature_thickness_overlay(shapes)

    def _plate_thickness_bands(self, junction, plate_shape, run, theta_overrides, alpha, dx_um, dy_um, clip_pts,
                                extra_passes=None):
        """New feature -- plates previously had NO
        thickness banding at all (a single flat shade for the whole
        plate, regardless of how many genuinely different-theta passes
        deposited it) -- see _compute_post_shadow_shapes' own comment at
        this function's call site for the full context. Builds each of
        the owning finger's own active passes' REAL, independently-
        shadowed plate footprint (reusing _compute_plate_shadowed_points
        itself with a synthetic single-theta run, so the already-
        validated stepped near-edge shoulder/center-strip geometry --
        see that function's own extensive history -- applies per-pass
        automatically and can never drift from what the real multi-pass
        computation does), then overlays them via the shared
        _pass_footprint_overlay -- the exact same generalized model now
        used for fingers and patches. Degrades to a single (clip_pts,
        total_thickness_or_None) piece for 0/1 real passes or an
        unresolvable owner, matching every other thickness-banding
        function's own safety-net convention (None, not 0.0, when the
        owning tree state can't be resolved at all -- _thickness_to_
        color treats that as 'unknown').

        `extra_passes` (see
        _foreign_blanket_footprints' own docstring for the full real-SEM
        reasoning): an optional list of additional (theta, thickness)
        pairs from OTHER features' own foreign deposition passes that
        also reach this SAME plate -- appended onto this plate's own
        official (theta, thickness) pairs before the overlay, so a
        plate with only ONE official pass (the common case that used to
        always take the `len(real_thetas) < 2` fallback below, never
        showing any banding at all) correctly gets the SAME multi-pass
        decoherence treatment the moment blanket foreign exposure gives
        it a second real contributing pass -- reusing this function's
        own `_plate_pass_footprint`, so a foreign theta gets exactly
        the same validated per-pass physics an official one already
        does.

        Each `extra_passes` entry may be
        either the old (theta, thickness) 2-tuple OR a (theta, thickness,
        alpha) 3-tuple -- unpacked via `theta, thickness, *rest = pair`
        so an old 2-tuple still works unchanged (rest is empty -> falls
        back to the shared `alpha` param). This plate's own OFFICIAL
        passes get the same per-pass alpha treatment too, resolved from
        `run["theta_a_alphas"]`/`run["theta_b_alphas"]` exactly like
        every other per-finger geometry function in this file --
        `_plate_pass_footprint` now forwards each pass's own resolved
        alpha into the synthetic single-theta `single_run` it builds
        (as that SAME alpha-list key), so _compute_plate_shadowed_points'
        own per-pass alpha resolution applies
        here automatically, with no separate dx/dy math duplicated."""
        nearest_finger = self._find_finger_for_plate(junction, plate_shape)
        if nearest_finger is None or nearest_finger not in junction.fingers:
            return [(clip_pts, None)]
        idx = junction.fingers.index(nearest_finger)
        thetas = self._run_finger_thetas(run, idx, nearest_finger, theta_overrides)
        real_thetas = [t for t in thetas if t is not None]
        layers_ref = self._sim_finger_layers.get(idx) or real_thetas
        thicknesses_ref = self._sim_finger_thicknesses.get(idx, [])
        pass_thicknesses = self._match_pass_thicknesses(real_thetas, layers_ref, thicknesses_ref) if real_thetas else []
        alphas_ref = self._run_finger_alphas(run, idx) or []
        pass_alphas = self._match_pass_thicknesses(real_thetas, layers_ref, alphas_ref, default=None) if real_thetas else []
        known_vals = [v for v in pass_thicknesses if v is not None]
        total = sum(known_vals) if known_vals else None
        extra_triples = []
        for pair in (extra_passes or []):
            t, th, *rest = pair
            if t is None:
                continue
            a = rest[0] if rest else None
            extra_triples.append((t, th if th is not None else 0.0, a))
        extra_total = sum(th for _t, th, _a in extra_triples)
        fallback = [(clip_pts, (total if total is not None else 0.0) + extra_total if (total is not None or extra_triples) else None)]
        official_triples = list(zip(real_thetas, pass_thicknesses, pass_alphas)) if real_thetas else []
        all_triples = official_triples + extra_triples
        if len(all_triples) < 2:
            return fallback

        def _plate_pass_footprint(theta, alpha_override=None, _s=plate_shape, _idx=idx):
            single_run = self._single_pass_run(_idx, theta, alpha_override)
            return self._compute_plate_shadowed_points(junction, _s, single_run, [None, None], alpha, dx_um, dy_um)

        footprints = [(_plate_pass_footprint(t, a), (th if th is not None else 0.0)) for t, th, a in all_triples]
        return self._pass_footprint_overlay(footprints, clip_pts)

    def _draw_post_shadow_design(self, ax, junction, report):
        """Draws the ACTUAL final design after all depositions --
        computed real polygons, not the nominal design with annotation
        bands overlaid -- so the user can see the complete result of
        every over- and under-shadowing effect combined, the way it
        will actually come out of the chamber.

        Reverted: an earlier version
        added a `_draw_post_shadow_cross_axis_ghosts` overlay
        here (a dotted "masked pass" annotation, reusing Simulated
        Design's own ghost-band mechanism) to represent a mis-angled
        pass's contribution even where the real final boundary is
        carried by a different, surviving pass. Reverted on principle --
        this view is just supposed to show the final shape after
        all depositions, not an annotation of intermediate passes --
        and because it also had a real rendering bug
        (the ghost bands' text labels, sized for Simulated Design's
        typically much-more-zoomed-out view, rendered gigantic and
        illegible against Post-Shadow Result's tightly-fitted axes).
        Removed outright rather than fixed -- the user's actual ask
        (see _compute_post_shadow_shapes' own updated docstring) is for
        the REAL final geometry itself to correctly show a mis-angled
        pass's decoherence from its sibling pass as real, separate
        thickness-banded sub-regions, not as an annotation drawn on top
        of a single unioned shape."""
        shapes = self._compute_post_shadow_shapes(junction, report)
        self._draw_shadow_shapes(ax, junction, shapes)
        self._fit_shadow_axes(ax, shapes)

    def _draw_shadow_shapes(self, ax, junction, shapes, thickness_range=None):
        """Shared rendering step used by both _draw_post_shadow_design
        (the complete final design) and the Deposition Slideshow's
        progressive/truncated view -- draws whatever shapes list it's
        given (already computed at the right level of completeness by
        the caller) plus the always-visible electrode background.
        Factored out so the two callers can never draw with different
        styling/z-order and drift apart.

        `shapes` entries are (points, kind, finger_index, thickness_nm,
        group_id, is_ghost) 6-tuples (see _compute_post_shadow_shapes) --
        each piece is shaded within its kind's own base hue by its
        thickness_nm (see _thickness_to_color), lighter for a thinner,
        singly-deposited region and darker for a thicker, multiply-
        deposited one, based on real SEM
        reference images. thickness_range, when given, is the (min_nm,
        max_nm) to shade against -- the Deposition Slideshow passes the
        COMPLETE design's own range here so a region's shade stays fixed
        across frames as more of the design is progressively revealed;
        omitted (the complete-design call site), the range is derived
        from `shapes` itself, which already IS the complete set.

        Fix: every band used to be drawn
        with its own white (OUTLINE_COLOR) edge, so a feature split into
        several thickness bands showed a distracting white seam at every
        internal band-to-band boundary -- the white highlight should
        only surround the perimeter of the overall feature, not the
        interior line thicknesses, since the difference in color already
        indicates the complicated overlaps. Fixed by drawing every band's FILL
        with no edge at all, then, once per group_id (one real physical
        piece -- see _compute_post_shadow_shapes' own docstring for what
        group_id identifies), taking the real union of that piece's own
        bands and drawing exactly ONE white outline around it -- so the
        white line traces only the true outer silhouette, never an
        interior seam, however many thickness bands make it up."""
        if thickness_range is not None:
            min_th, max_th = thickness_range
        else:
            min_th, max_th = self._thickness_range(shapes)
        for pts, kind, _finger_idx, thickness, gid, _is_ghost in shapes:
            color = self._thickness_to_color(kind, thickness, min_th, max_th)
            poly = MplPolygon(pts, closed=True, facecolor=color, edgecolor="none",
                              linewidth=0.0, alpha=1.0, zorder=5)
            ax.add_patch(poly)
        # Declutter: reduce
        # the clutter of many small triangles crowding a dense adhesion-
        # pad area while preserving all the layering/shape/feature
        # information. Previously outlined once PER group_id (one real,
        # already-finalized piece of ONE feature -- see
        # _compute_post_shadow_shapes' own docstring) -- correct for
        # avoiding a seam WITHIN one piece's own thickness bands, but two
        # DIFFERENT group_ids that happen to physically touch (routine
        # once several crossings/passes are active near the same spot: a
        # triangle already merges into a SAME-(kind,thickness) neighbor
        # per _merge_triangle_group_id, but a real finger/plate/patch
        # boundary, or two different passes' triangles that touch without
        # sharing a (kind, thickness) match, still drew two separate
        # outlines with a visible white seam at their shared edge) is
        # exactly the "spiderweb of crossing white lines" reported around
        # dense multi-pass patch/adhesion-pad areas (10-20+ triangles from
        # crossed 45/225deg patch passes in one real report). Generalizes
        # the same reasoning `_merge_triangle_group_id`'s own fix
        # already established for one specific pair (a triangle and
        # the ghost sliver it sits beside are the same physical event, so
        # they share one outline) to EVERY pair of touching bands, of any
        # kind/thickness: computes ONE union across the WHOLE drawing and
        # outlines only the resulting CONNECTED regions, so a white line
        # now traces only a genuine physical gap, never an internal seam
        # between two touching pieces. Changes NOTHING about what's
        # visible otherwise -- every band's own fill color (already fully
        # encoding kind and thickness, the real "layering/shape/feature
        # information" being preserved) is drawn exactly as before by the
        # loop above; only the count of redundant white outline segments
        # drawn on top of already-adjacent color changes goes down. A
        # small (10nm) buffer-then-erode also bridges hairline numerical
        # gaps two independently-derived shapes (e.g. a triangle's own
        # vertex formula vs. a ghost sliver's) can leave even where they
        # are, physically, the same edge -- far too small to ever bridge
        # a real, intentional gap (real linewidths/spacings here are
        # hundreds of nm to microns).
        try:
            bridge_um = 0.01
            all_polys = [sg.Polygon(pts).buffer(bridge_um, join_style=2) for pts, *_ in shapes]
            merged = so.unary_union(all_polys).buffer(-bridge_um, join_style=2)
        except Exception:
            merged = None
        if merged is not None and not merged.is_empty:
            geoms = list(merged.geoms) if hasattr(merged, "geoms") else [merged]
            for g in geoms:
                if not hasattr(g, "exterior") or g.exterior is None:
                    continue
                outline = MplPolygon(list(g.exterior.coords), closed=True, facecolor="none",
                                     edgecolor=OUTLINE_COLOR, linewidth=1.0, zorder=6)
                ax.add_patch(outline)
                for interior in g.interiors:
                    hole_outline = MplPolygon(list(interior.coords), closed=True, facecolor="none",
                                              edgecolor=OUTLINE_COLOR, linewidth=1.0, zorder=6)
                    ax.add_patch(hole_outline)
        if junction.electrode_polygons:
            for poly_pts in junction.electrode_polygons:
                if len(poly_pts) >= 3:
                    poly = MplPolygon(poly_pts, closed=True, facecolor="#6b5b8c", edgecolor="none",
                                      alpha=0.35, zorder=1)
                    ax.add_patch(poly)

    def _fit_shadow_axes(self, ax, shapes):
        """Fits `ax`'s limits to `shapes` -- factored out so the
        Slideshow can fit to the COMPLETE design's shapes while drawing
        only a truncated subset, keeping the view from jumping around
        as more of the design is progressively revealed."""
        all_x = [p[0] for pts, _k, _fi, _th, _gid, _ghost in shapes for p in pts]
        all_y = [p[1] for pts, _k, _fi, _th, _gid, _ghost in shapes for p in pts]
        if all_x and all_y:
            pad = max(max(all_x)-min(all_x), max(all_y)-min(all_y)) * 0.15 + 0.5
            ax.set_xlim(min(all_x)-pad, max(all_x)+pad)
            ax.set_ylim(min(all_y)-pad, max(all_y)+pad)
        ax.set_aspect("equal")

    def _slideshow_cumulative_thetas(self, junction, upto_index):
        """Walks the recipe from its start through -- and including --
        Deposition Slideshow step `upto_index`, and returns the REAL
        per-feature theta HISTORY so far, not just a shown/hidden flag:
        (finger_theta_lists: {finger_index: [thetas actually deposited
        at, in order]}, patch_thetas: [patch thetas actually deposited
        at, in order]).

        Bug fix (direct user report): the previous
        progressive-reveal implementation only tracked whether a
        feature had started depositing at all, then always rendered it
        using the FINAL, complete theta list from _resolve_patch_thetas/
        self._sim_last_run -- so the very first patch deposition step
        already showed BOTH required passes fully cascaded together,
        even though only one had actually happened yet. A patch group
        that needs two depositions (one from each side) should show a
        real, asymmetric one-pass shadow after its first deposition --
        one side connected/extended, the other still short/shadowed --
        and only look fully connected on both sides after its SECOND
        deposition actually occurs. This function supplies the
        TRUNCATED theta lists that make that possible:
        _compute_post_shadow_shapes_upto feeds them into the exact same
        multi-pass cascade math (_net_depth_multi et al) Post-Shadow
        Result itself uses for the final state, just stopped at however
        many passes have actually happened by this step -- so the
        step-by-step shadowing mechanics (which sides lengthen or
        shadow, in which direction, at each pass) are the real thing,
        not a shown/hidden approximation.

        A deposition step is matched back to a finger by comparing its
        theta against THAT finger's own two possible axis directions
        (theta_toward_patch_deg / theta_toward_stub_deg), the same
        tolerance convention recipe_generator._classify_feature uses --
        deliberately NOT via the recipe step's "horizontal"/"vertical"
        feature tag, since that tag is keyed to Create / Import's global design-
        parameter angles, which can drift from an imported/GDS
        junction's real per-finger axis angles. A deposition step whose
        theta doesn't match any finger is treated as a patch deposition
        (patches share one physical layer across both fingers' groups,
        per _resolve_patch_thetas, so they're tracked as one collective
        theta history, not per-patch-group).

        Mill steps never change what's visible (they don't add
        material) -- they're simply skipped here, so a mill step's
        state is exactly whatever theta history had already accumulated
        from the steps before it.

        Also returns `finger_alpha_lists`
        ({finger_index: [alphas so far]}) and `patch_alphas` ([alphas so
        far]), parallel index-for-index to `finger_theta_lists`/
        `patch_thetas`, collected from each step's own real `step.alpha`
        (RecipeStep already carries this -- see recipe_generator.py -- it
        was simply never read here before, the same class of gap as
        _sync_sim_layers_from_recipe_features not reading feat.alpha).
        This is what lets the Deposition Slideshow's progressive Post-
        Deposition/Shadow-Sim views reflect a genuinely different
        per-pass alpha the same way the final Post-Shadow Result now
        does, instead of only ever replaying the one shared Active-alpha
        value regardless of what each individual recipe step's own
        real tilt was."""
        TOL_DEG = 2.0

        def close(a, b):
            if a is None or b is None:
                return False
            return abs(((a - b + 180.0) % 360.0) - 180.0) <= TOL_DEG

        finger_theta_lists = {i: [] for i in range(len(junction.fingers))}
        finger_alpha_lists = {i: [] for i in range(len(junction.fingers))}
        patch_thetas = []
        patch_alphas = []
        steps = self._slideshow_steps[:max(0, upto_index) + 1]
        for step in steps:
            if step.category != "deposition" or step.theta is None:
                continue
            matched = False
            for i, f in enumerate(junction.fingers):
                if close(step.theta, f.theta_toward_patch_deg) or close(step.theta, f.theta_toward_stub_deg):
                    finger_theta_lists[i].append(step.theta)
                    finger_alpha_lists[i].append(getattr(step, "alpha", None))
                    matched = True
            if not matched:
                patch_thetas.append(step.theta)
                patch_alphas.append(getattr(step, "alpha", None))
        return finger_theta_lists, patch_thetas, finger_alpha_lists, patch_alphas

    def _slideshow_visible_features(self, junction, upto_index):
        """Thin boolean convenience wrapper over
        _slideshow_cumulative_thetas, for callers that only need "has
        finger i started depositing at all" / "have any patches
        deposited at all" -- NOT the actual per-pass theta history. The
        reference panel itself calls _slideshow_cumulative_thetas
        directly, since it needs the real theta lists to compute true
        partial-pass shadow geometry, not just shown/hidden."""
        finger_theta_lists, patch_thetas, _finger_alpha_lists, _patch_alphas = self._slideshow_cumulative_thetas(junction, upto_index)
        finger_visible = {i for i, thetas in finger_theta_lists.items() if thetas}
        patches_visible = bool(patch_thetas)
        return finger_visible, patches_visible

    def _slideshow_all_deposition_passes_upto(self, upto_index, alpha=None, from_index=0):
        """For the Deposition Slideshow's Shadow Sim
        view: every theta belonging to a deposition step in the recipe,
        from step `from_index` through step `upto_index` (inclusive),
        regardless of which feature the recipe generated that step FOR.

        from_index: bug fix --
        defaulting this to the very start of the recipe fed every
        already-introduced feature the SAME global pool, including
        deposition steps that happened BEFORE that specific feature was
        even introduced. That's backwards: a feature that has just
        received its OWN first pass this step hasn't been sitting open
        since the start of the recipe waiting for it -- the only passes
        that can additionally affect it are the ones from THIS point
        onward (see _slideshow_feature_intro_indices, which finds each
        feature's own first-deposition step index to use here). Left at
        its default (0) only by a caller that genuinely wants the whole
        recipe from the start.

        PHYSICAL REASONING: a single lithography
        step patterns every feature's resist aperture at once, and every
        deposition step afterward is one continuous evaporation that
        exposes the WHOLE open wafer -- not just the feature(s) a given
        step happens to have been generated to deposit metal onto. An
        already-introduced feature's own aperture is still open (nothing
        re-masks it between passes), so it is physically exposed to
        EVERY later deposition step's own angle too, whether or not that
        step was "for" it. This is already half-true in the existing
        code -- _draw_sim_shadow_visualization's patch loop already
        treats both fingers' own thetas as blanket depositions landing on
        every patch -- this function generalizes that to ALL features,
        symmetrically, accumulated step by step.

        _slideshow_cumulative_thetas (above) deliberately does NOT do
        this: it exists to answer "which passes are THIS feature's own,
        in order" for the real multi-pass cascade math Post-Shadow
        Result/the Post Deposition slideshow view use, which must stay
        exactly as before (this function changes NOTHING about that
        engine -- this is a Shadow Sim view-only
        concept, see _slideshow_draw_shadow_sim_view).

        alpha: when given, a deposition step whose OWN alpha disagrees
        with it (by more than 0.05 deg) is excluded from the returned
        pool rather than silently mixed in -- recipe_generator.py's committed
        steps technically allow an independently-set alpha per sub-step,
        but every real design built through this app's own Tab 2 UI
        commits ONE alpha for the whole sequence, and this function's
        only caller computes one shared dx/dy for the whole pool
        (matching _draw_sim_shadow_visualization's own existing single-
        alpha-per-call design) -- so a genuinely mixed-alpha recipe is
        handled by leaving out whichever passes don't match, not by
        computing physics for the wrong alpha. Left None (no filtering)
        by any caller that doesn't have a single alpha to compare against."""
        passes = []
        steps = self._slideshow_steps[max(0, from_index):max(0, upto_index) + 1]
        for step in steps:
            if step.category != "deposition" or step.theta is None:
                continue
            if alpha is not None and step.alpha is not None and abs(step.alpha - alpha) > 0.05:
                continue
            passes.append(step.theta)
        return passes

    def _slideshow_feature_intro_indices(self, junction):
        """For each finger (by index) and for
        "patches" as one shared group, the STEP INDEX (into
        self._slideshow_steps) of that feature's own FIRST deposition --
        the earliest point its own resist crevasse actually starts
        receiving metal, and therefore the earliest point any OTHER
        step's angle can be considered to affect it at all (see
        _slideshow_all_deposition_passes_upto's `from_index`). Uses the
        exact same finger-vs-patch step classification as
        _slideshow_cumulative_thetas (a deposition step matches a finger
        if its theta is close to that finger's own theta_toward_patch_deg/
        theta_toward_stub_deg; everything else is a patch deposition), so
        this can never disagree with that function about which step
        belongs to which feature. A fixed property of the (design,
        recipe) pair -- independent of upto_index -- computed once per
        draw rather than re-derived per feature."""
        TOL_DEG = 2.0

        def close(a, b):
            if a is None or b is None:
                return False
            return abs(((a - b + 180.0) % 360.0) - 180.0) <= TOL_DEG

        finger_intro = {i: None for i in range(len(junction.fingers))}
        patch_intro = None
        for idx, step in enumerate(self._slideshow_steps):
            if step.category != "deposition" or step.theta is None:
                continue
            matched = False
            for i, f in enumerate(junction.fingers):
                if close(step.theta, f.theta_toward_patch_deg) or close(step.theta, f.theta_toward_stub_deg):
                    if finger_intro[i] is None:
                        finger_intro[i] = idx
                    matched = True
            if not matched and patch_intro is None:
                patch_intro = idx
        return finger_intro, patch_intro

    def _slideshow_feature_theta_split(self, junction, upto_index, from_index, owner, alpha=None):
        """Splits every deposition step's theta
        in slideshow steps [from_index, upto_index] into (own_thetas,
        foreign_thetas) relative to `owner` -- ("finger", i) for finger i,
        or ("patch", None) for the shared patch group -- using the exact
        same finger-vs-patch step classification as
        _slideshow_cumulative_thetas. own_thetas holds exactly the steps
        classified as belonging to `owner` itself (a step can belong to
        more than one finger at once if their axes coincide, matching
        that function's own no-break matching loop); foreign_thetas holds
        every OTHER deposition step's theta in the window, regardless of
        which other feature it actually belongs to.

        Bug fix, found against the Shadow
        Sim view: feeding a feature's OWN on-axis theta into the SAME
        cross-axis combination as genuinely foreign thetas lets that
        zero-effect pass "rescue" the combined result on every edge (see
        ShadowThetaProvider's own docstring for the full mechanism) --
        the fix is for the CROSS-AXIS overlay specifically to only ever
        see `foreign_thetas`, never mixing in `owner`'s own pass(es) at
        all, so a genuinely foreign, off-axis pass's shrink can actually
        show through instead of being structurally un-losable."""
        TOL_DEG = 2.0

        def close(a, b):
            if a is None or b is None:
                return False
            return abs(((a - b + 180.0) % 360.0) - 180.0) <= TOL_DEG

        own, foreign = [], []
        steps = self._slideshow_steps[max(0, from_index):max(0, upto_index) + 1]
        for step in steps:
            if step.category != "deposition" or step.theta is None:
                continue
            if alpha is not None and step.alpha is not None and abs(step.alpha - alpha) > 0.05:
                continue
            matched_fingers = [i for i, f in enumerate(junction.fingers)
                                if close(step.theta, f.theta_toward_patch_deg) or close(step.theta, f.theta_toward_stub_deg)]
            is_patch_step = not matched_fingers
            if owner[0] == "finger":
                (own if owner[1] in matched_fingers else foreign).append(step.theta)
            else:  # owner[0] == "patch"
                (own if is_patch_step else foreign).append(step.theta)
        return own, foreign

    def _slideshow_draw_shadow_sim_view(self, ax, junction, report, upto_index):
        """The Deposition Slideshow's second view,
        toggled against the existing Post Deposition view (see
        _slideshow_draw_reference). Shows the NOMINAL (pre-shadow) design
        -- the same shapes Create/Import draws -- filtered to only the
        features already introduced by step `upto_index` (same gate the
        Post Deposition view uses, _slideshow_visible_features), each
        overlaid with the SAME hatch-band visualization Simulated Design
        already uses (_draw_sim_shadow_visualization). No thickness-
        banding here -- this view is nominal shape + hatch overlay, the
        same visual language as Simulated Design, not the thickness-
        colored Post-Shadow style.

        A fundamental model correction, replacing an earlier approach:
        this view
        is a per-STEP SNAPSHOT of what the planetary is doing to the
        wafer RIGHT NOW, not a running ledger of everything that has
        happened to a feature so far. The shadowing should be
        functioning based on the orientation of the planetary IN THE
        CURRENT STEP: every feature already deposited shadows depending
        on the planetary orientation of that current step. It does not
        add up what the shadowing looks like across the first, second,
        third, fourth... step for that singular shape -- it presents the
        shadowing that the pre-deposited shape goes through as another
        shape is being deposited at its angle. The only thing that
        accumulates is the number of features/shapes that need to be
        simulated as they are deposited one-by-one.

        The earlier approach (see git history / shadowing_design_rules.md) had it
        backwards: it pooled EVERY deposition theta from a feature's own
        introduction through `upto_index` and fed the whole history into
        the shadow math at once, as if every past pass were still
        actively landing simultaneously. That's not what a step-by-step
        slideshow means -- at step N, exactly ONE planetary orientation
        is physically active (this step's own theta, if step N is even a
        deposition step at all), and every already-introduced feature's
        aperture -- whether this is its OWN official step or a totally
        foreign one -- sees exactly that one angle, nothing more. A
        feature's real multi-pass history (e.g. a patch that needs two
        passes to fully connect) is exactly what the existing Post
        Deposition view already models correctly via
        _slideshow_cumulative_thetas -- this view is not that, and was
        never meant to be.

        This also structurally retires both follow-up 2 bugs (and the
        window/from_index machinery built to fix them) rather than
        patching them further: with never more than a single active
        theta at a time, there is nothing left to combine, so the
        "enclosing hull always gets rescued by a zero-effect own pass"
        failure mode and the "which window does a mirror-opposite
        foreign pass fall into" failure mode both simply cannot occur
        any more. (The old _slideshow_all_deposition_passes_upto/
        _slideshow_feature_intro_indices/_slideshow_feature_theta_split
        helpers are left in place, unused by this function, rather than
        deleted outright, in case a future feature genuinely needs a
        windowed history again -- but nothing here calls them.)

        A DIRECTLY RELATED VISUAL BUG this same fix resolves: the blue
        "extend" annotation band on an already-deposited feature was
        reported drawn reaching noticeably further outward than the real
        Post-Shadow geometry for that same feature ever actually grows --
        because the annotation was being fed the WHOLE pooled history's
        "furthest pass wins" depth (accumulated across several steps),
        while a real single historical pass, taken alone, never reached
        that far. Feeding this view the same single current-step theta
        the real geometry would see for that one instant removes the
        inflation at its source -- the annotation and the real geometry
        are now computing the exact same single-pass depth, not two
        different pools.

        Corrected model, then a follow-up bug
        fix: this function's OWN separate closing section also draws
        'ghost junction line' overlays (see _ghost_junction_slivers) for
        any visible feature whose still-open aperture some OTHER
        feature's own deposition pass genuinely floods past its own
        nominal edge. UNLIKE the ordinary extend/shrink hatch bands
        above, this check is NOT limited to this one step's own current
        theta -- FOLLOW-UP 6, a direct bug fix, corrected this: a ghost
        sliver is real deposited metal, so once a foreign pass creates
        one it stays on the wafer forever, and must keep showing on
        every later step too, not just the one instant it was formed
        (which, before this fix, also meant a ghost caused by a pass
        that happened BEFORE its target feature was even introduced
        could never show up at all, since the causing theta was already
        gone from `current_thetas` by the time the target became
        visible). This section instead pools the full cumulative history
        so far (_slideshow_cumulative_thetas/_all_deposition_pass_records)
        and, per target, excludes only that target's own official
        pass(es) (_foreign_pass_records) -- so a ghost line first appears
        at exactly the step where the offending pass actually happens and
        then persists on every subsequent step, matching Post-Shadow
        Result's own (also cumulative, non-decaying) ghost geometry.

        This view renders every
        qualifying sliver as a BLUE HATCH BAND (reusing _draw_shadow_
        band's own "extend" styling/colors exactly), not a flat fill in
        a special "ghost" hue -- the same visual language already used
        for the ordinary extend/shrink annotations this view draws
        everywhere else, since a ghost sliver IS that same physical
        mechanism (dx/dy shadow throw), just landing disjoint from the
        nominal span instead of merely extending past it. A small
        "⚠" caution glyph is additionally drawn centered on each
        sliver so a ghost line -- otherwise styled
        identically to an ordinary hatch band -- can't be missed."""
        run = self._sim_last_run or {}
        current_step = self._slideshow_steps[upto_index] if 0 <= upto_index < len(self._slideshow_steps) else None
        current_theta = (current_step.theta if current_step is not None
                          and current_step.category == "deposition" and current_step.theta is not None else None)
        alpha = (current_step.alpha if current_step is not None and current_step.alpha is not None
                 else run.get("alpha", 30.0))
        finger_theta_lists, patch_thetas, finger_alpha_lists, patch_alphas = self._slideshow_cumulative_thetas(junction, upto_index)
        finger_visible = {i for i, thetas in finger_theta_lists.items() if thetas}
        patches_visible = bool(patch_thetas)

        # Bug fix: adhesion plate shadowing was not appearing in
        # the shadow sim even when it appeared in the post-deposition
        # view. Root cause: once
        # an earlier fix made the Post Deposition view so a plate can show
        # real metal from a DIFFERENT, already-deposited feature's blanket
        # pass even before its OWN owning finger's official pass happens,
        # this view's plate gate -- both its nominal background polygon
        # below and its shadow-hatch overlay further down -- was left
        # exactly as before, still requiring `idx in finger_visible` (the
        # plate's own finger's own official pass) with no foreign-contact
        # fallback at all. That made the two views disagree again, the
        # same class of bug as FOLLOW-UP 1's ghost-gate fix. Fixed by
        # deriving plate visibility from the SAME real geometry function
        # Post Deposition itself uses (_compute_post_shadow_shapes_upto)
        # instead of a second, narrower, hand-rolled heuristic -- Shadow
        # Sim's plate gate now literally IS Post Deposition's own answer
        # for "has this plate received any real metal by this step", so
        # the two views structurally cannot drift apart on this again.
        shapes_upto_for_plate_visibility = self._compute_post_shadow_shapes_upto(
            junction, report, run, finger_theta_lists, patch_thetas,
            finger_alpha_lists=finger_alpha_lists, patch_alphas=patch_alphas)
        plate_visible_idxs = {s[2] for s in shapes_upto_for_plate_visibility if s[1] == "plate"}

        # Bug fix: once a shape is deposited on and the
        # slideshow progresses, the shadowing needs to be thrown on the
        # updated and shadowed, completed-deposit shape, not the presumed
        # design shape pre-shadowing -- so if that same feature is being
        # deposited a second time the opposite way, the shape that was
        # shadowed one way and deposited as such needs to appear, with
        # its new shadows going the other way.
        # Root cause: the background fill drawn below (over which this
        # step's own hatch-band overlay is drawn) was unconditionally
        # each feature's raw NOMINAL polygon (f.points / s.points) --
        # never the REAL shape resulting from whatever passes had already
        # actually happened to it by the PRIOR step. Fixed by computing
        # the real post-shadow geometry as of one step BEFORE this one
        # (upto_index - 1) -- the exact same real cascade machinery
        # (_compute_post_shadow_shapes_upto) the "Post Deposition" view
        # itself uses -- and using THAT as the background for any
        # already-visible finger/plate whose own history didn't start
        # fresh this exact step; a feature receiving its very first
        # deposition THIS step correctly still shows its nominal
        # (untouched) shape, since that genuinely IS its real state one
        # step ago. Deliberately kept SEPARATE from the current step's own
        # hatch overlay below (which still represents only THIS step's
        # single active planetary angle, per FOLLOW-UP 3) -- the real
        # prior shape is the surface that hatch is now correctly shown
        # landing on, rather than the two being silently inconsistent.
        #
        # SCOPED to fingers and plates this round, not patches: a finger
        # or plate maps 1:1 onto a single junction.fingers[i] index
        # (exactly how plate_visible_idxs above already keys them), so
        # re-associating each one's own prior real piece(s) is
        # unambiguous. A patch does not have that same clean identity
        # here (more than one patch shape can share one patch-group
        # finger_index), so patches are left on their nominal background
        # for now -- a known, explicitly tracked remaining gap, not
        # silently unaddressed.
        prior_index = upto_index - 1
        if prior_index >= 0:
            (finger_theta_lists_prior, patch_thetas_prior,
             finger_alpha_lists_prior, patch_alphas_prior) = self._slideshow_cumulative_thetas(junction, prior_index)
        else:
            finger_theta_lists_prior = {i: [] for i in range(len(junction.fingers))}
            patch_thetas_prior, finger_alpha_lists_prior, patch_alphas_prior = [], {i: [] for i in range(len(junction.fingers))}, []
        has_prior_history = any(finger_theta_lists_prior.values()) or bool(patch_thetas_prior)
        prior_shapes = (self._compute_post_shadow_shapes_upto(
            junction, report, run, finger_theta_lists_prior, patch_thetas_prior,
            finger_alpha_lists=finger_alpha_lists_prior, patch_alphas=patch_alphas_prior)
            if has_prior_history else [])
        prior_finger_pieces = {i: [] for i in range(len(junction.fingers))}
        prior_plate_pieces = {i: [] for i in range(len(junction.fingers))}
        for s in prior_shapes:
            s_pts, s_kind, s_idx = s[0], s[1], s[2]
            if s_kind == "finger" and s_idx in prior_finger_pieces:
                prior_finger_pieces[s_idx].append(s_pts)
            elif s_kind == "plate" and s_idx in prior_plate_pieces:
                prior_plate_pieces[s_idx].append(s_pts)

        # Background: electrode polygons first (same purple fill
        # _draw_shadow_shapes itself uses), then each introduced feature's
        # own real prior-shadowed polygon (fingers/plates) or nominal
        # (pre-shadow) polygon (patches, and any finger/plate with no
        # prior history yet) in its kind's base color.
        if junction.electrode_polygons:
            for poly_pts in junction.electrode_polygons:
                if len(poly_pts) >= 3:
                    poly = MplPolygon(poly_pts, closed=True, facecolor="#6b5b8c", edgecolor="none",
                                      alpha=0.35, zorder=1)
                    ax.add_patch(poly)
        for i, f in enumerate(junction.fingers):
            if i not in finger_visible:
                continue
            pieces = prior_finger_pieces.get(i) or [f.points]
            for pts in pieces:
                poly = MplPolygon(pts, closed=True, facecolor=SHADOW_KIND_BASE_COLOR["finger"],
                                  edgecolor=OUTLINE_COLOR, linewidth=1.0, zorder=2)
                ax.add_patch(poly)
        if patches_visible:
            for s in junction.other_shapes:
                if s.kind != "patch":
                    continue
                poly = MplPolygon(s.points, closed=True, facecolor=SHADOW_KIND_BASE_COLOR["patch"],
                                  edgecolor=OUTLINE_COLOR, linewidth=1.0, zorder=2)
                ax.add_patch(poly)
        for s in junction.other_shapes:
            if s.kind != "plate":
                continue
            nearest_finger = self._find_finger_for_plate(junction, s)
            if nearest_finger is None:
                continue
            idx = junction.fingers.index(nearest_finger)
            if idx not in plate_visible_idxs:
                continue
            pieces = prior_plate_pieces.get(idx) or [s.points]
            for pts in pieces:
                poly = MplPolygon(pts, closed=True, facecolor=SHADOW_KIND_BASE_COLOR["plate"],
                                  edgecolor=OUTLINE_COLOR, linewidth=1.0, zorder=2)
                ax.add_patch(poly)

        # Bug fix: using the most updated version of the
        # deposited metal in the slideshow was not quite right -- the
        # shapes deposited should show their proper red and blue hatching
        # at any step in time, but the blue hatching appeared to float
        # when the shadowing was actually coming from the original
        # trench, not the current shape. It should show the previous
        # deposited shapes, and for the applicable depositions that use
        # the original trench/design feature, show how that feature gets
        # shadowed.
        #
        # The background fill just above intentionally shows each
        # finger/plate's REAL, already-shadowed shape from any prior
        # passes -- an earlier fix, still correct and
        # still wanted. But the hatch-band overlay drawn just below this
        # (_draw_sim_shadow_visualization, called against the nominal
        # `junction` object) is, correctly, always measured from the
        # ORIGINAL nominal trench edge -- that matches how this whole
        # engine actually combines multiple passes everywhere else: each
        # pass is computed independently against the nominal aperture,
        # then the results are combined (enclosing hull / max), never
        # chained edge-to-edge from whatever the PREVIOUS pass happened
        # to leave behind. Once a prior pass has moved a feature's real
        # edge away from its nominal position, those two correct-but-
        # different references stop visually lining up, and the hatch
        # band reads as floating disconnected in space next to the solid
        # background shape instead of visibly growing out of anything.
        #
        # Hybrid fix, exactly matching what was asked for: keep the real
        # accumulated shape as the solid background (still answers "what
        # has actually been deposited so far"), and additionally draw a
        # thin dashed outline of the ORIGINAL nominal trench/design
        # feature for any feature that is actually receiving a new hatch
        # band THIS step ("the applicable depositions that use the
        # original trench/design feature") -- a visual anchor showing
        # exactly where that hatch is really being measured from, so the
        # two stay visually cohesive instead of one appearing to float.
        # Drawn only where the two have genuinely diverged: a feature
        # with no prior history yet has a background that already IS its
        # nominal shape, so there's nothing to reconcile and no extra
        # outline is drawn there (it would just be a second identical
        # outline sitting exactly on top of the first).
        #
        # A follow-up explanatory caption (text boxes reading "dashed
        # outline = original trench... solid fill = metal already
        # deposited") was tried and explicitly REJECTED, since it added
        # unwanted text boxes to the preview -- the
        # dashed outline itself was kept as the right approach, just
        # without any on-canvas text.
        if current_theta is not None:
            for i, f in enumerate(junction.fingers):
                if i in finger_visible and prior_finger_pieces.get(i):
                    poly = MplPolygon(f.points, closed=True, facecolor="none", edgecolor="#c9cbd6",
                                      linewidth=1.1, linestyle=(0, (4, 3)), alpha=0.9, zorder=10)
                    ax.add_patch(poly)
            for s in junction.other_shapes:
                if s.kind != "plate":
                    continue
                nearest_finger = self._find_finger_for_plate(junction, s)
                if nearest_finger is None:
                    continue
                idx = junction.fingers.index(nearest_finger)
                if idx in plate_visible_idxs and prior_plate_pieces.get(idx):
                    poly = MplPolygon(s.points, closed=True, facecolor="none", edgecolor="#c9cbd6",
                                      linewidth=1.1, linestyle=(0, (4, 3)), alpha=0.9, zorder=10)
                    ax.add_patch(poly)

        # Per-step snapshot pool: every visible feature (own step or
        # foreign) sees exactly the SAME single-element (or empty) list --
        # this instant's one active theta, nothing pooled from earlier
        # steps. Cross-axis gets the identical list; there is no own-vs-
        # foreign split left to make, since a single theta can never
        # "rescue" or get mis-combined with anything else (see this
        # function's own docstring).
        current_thetas = [current_theta] if current_theta is not None else []

        def _finger_thetas(idx, official):
            return current_thetas if idx in finger_visible else []

        def _finger_cross_axis_thetas(idx, resolved_thetas):
            return current_thetas if idx in finger_visible else []

        def _patch_thetas(official):
            return current_thetas if patches_visible else []

        def _patch_cross_axis_thetas(resolved_thetas):
            return current_thetas if patches_visible else []

        def _plate_thetas(idx, official):
            # Gated on `plate_visible_idxs` (real
            # foreign-or-own contact, matching Post Deposition), not just
            # `idx in finger_visible` (this plate's own finger's own pass)
            # -- see this function's own docstring above for the bug this
            # fixes.
            return current_thetas if idx in plate_visible_idxs else []

        def _plate_cross_axis_thetas(idx, resolved_thetas):
            return current_thetas if idx in plate_visible_idxs else []

        provider = ShadowThetaProvider(finger_thetas_fn=_finger_thetas, patch_thetas_fn=_patch_thetas,
                                       plate_thetas_fn=_plate_thetas,
                                       finger_cross_axis_thetas_fn=_finger_cross_axis_thetas,
                                       patch_cross_axis_thetas_fn=_patch_cross_axis_thetas,
                                       plate_cross_axis_thetas_fn=_plate_cross_axis_thetas)
        # This view
        # can pile many more simultaneous passes onto one feature than the
        # angle-degree/"(masked)"/"(net)" text labels were ever designed to
        # show at once, and they overlapped into unreadable clutter. The
        # angles are already fully known from the Recipe Steps list next to
        # this view, so the labels add no information here -- suppressed
        # for this call only via _suppress_shadow_band_labels (see
        # _draw_shadow_band), restored in `finally` so a raised exception
        # can never leave Simulate tab's own labels suppressed afterward.
        self._suppress_shadow_band_labels = True
        try:
            self._draw_sim_shadow_visualization(ax, junction, report, theta_provider=provider)
        finally:
            self._suppress_shadow_band_labels = False

        # Bug fix: the
        # blue ghost-sliver hatch never appeared in this view at all.
        # An earlier attempt fed the ghost check `current_thetas`
        # -- this step's own single active theta -- on the theory that
        # ghosts should follow the same "per-step snapshot" model as the
        # ordinary extend/shrink hatch bands above. That's wrong for
        # ghosts specifically: a ghost sliver is REAL METAL, physically
        # deposited the instant a foreign pass happens, and it does not
        # un-deposit itself on later steps -- it must stay visible in
        # EVERY subsequent step once it has occurred, not flicker on only
        # for the one instant that caused it (and, in the common case
        # where the feature receiving the ghost is only introduced by a
        # LATER step than the foreign pass that caused it, the old
        # current-theta-only check could never show it at all, since the
        # causing theta had already scrolled out of `current_thetas` by
        # the time the target feature was even visible). Fixed by reusing
        # the exact same cumulative-history pass pool
        # (_slideshow_cumulative_thetas/_all_deposition_pass_records/
        # _foreign_pass_records) that _compute_post_shadow_shapes_upto
        # already uses for the real Post Deposition geometry, so a ghost
        # sliver appears here starting at exactly the step where the
        # offending pass actually happens and then persists on every
        # later step -- and, unlike the ordinary hatch bands, DOES use a
        # proper self/foreign split (_foreign_pass_records) per target,
        # since a target's own official pass(es) must never be allowed to
        # "ghost" against its own aperture.
        try:
            pmma_nm = float(self.pmma_edit.text()) if hasattr(self, "pmma_edit") else 875.0
        except ValueError:
            pmma_nm = 875.0
        try:
            pmgi_nm = float(self.pmgi_edit.text()) if hasattr(self, "pmgi_edit") else 600.0
        except ValueError:
            pmgi_nm = 600.0
        dx_um, dy_um = self._shadow_dxdy(pmma_nm, pmgi_nm, alpha)
        # Bug fix: the post-dep view showed
        # no triangles, but the shadow sim view showed triangles that did
        # not exist. Root cause, found by
        # direct comparison of every _triangle_anomaly_slivers call site:
        # `dy_um` there is DELIBERATELY a single, uniform value shared by
        # every pass being checked (a modeling choice -- see that
        # function's own docstring, "dy stays the caller's own UNIFORM
        # value... independent of any specific pass's tilt"), and both
        # ground-truth views (_compute_post_shadow_shapes for the final
        # Post-Shadow Result, _compute_post_shadow_shapes_upto for this
        # same Slideshow's own "Post Deposition" view) always derive that
        # shared value from the flat, global `run.get("alpha", 30.0)` --
        # the Active-alpha field -- never from any one pass's own real
        # tilt. This function, however, was feeding the triangle check
        # `dy_um` derived from `alpha` (line ~12622: THIS STEP's own real
        # per-step alpha, correct and intentional for the ordinary self-
        # shadow hatch bands and ghost slivers below, which DO correctly
        # resolve real per-pass dx/dy -- see _ghost_junction_slivers'
        # `rec.get("dx_um"/"dy_um", ...)` fallback). Once per-pass alpha
        # editing made a step's own real alpha routinely differ from the
        # flat Active-alpha field (e.g. raising finger deposition alpha
        # for specific passes), the two views' triangle checks silently
        # started disagreeing -- a pocket that's still open at one dy_um
        # can already be shadowed shut at another. Fixed by computing the
        # SAME flat, run-level alpha/dy_um the ground-truth views use,
        # specifically for the triangle check below, leaving the ordinary
        # per-step hatch bands and ghost-sliver checks (which correctly
        # want THIS step's own real tilt) untouched.
        triangle_alpha = run.get("alpha", 30.0)
        _, triangle_dy_um = self._shadow_dxdy(pmma_nm, pmgi_nm, triangle_alpha)
        theta_overrides = [run.get("theta_a"), run.get("theta_b")]
        finger_theta_lists, patch_thetas_so_far, finger_alpha_lists, _patch_alphas_raw = self._slideshow_cumulative_thetas(junction, upto_index)
        patch_thicknesses_so_far = self._match_pass_thicknesses(
            patch_thetas_so_far, self._sim_patch_layers or patch_thetas_so_far,
            self._sim_patch_thicknesses or []) if patch_thetas_so_far else []
        # Patch alpha resolved the SAME way patch
        # thickness already is just above -- matched back against the
        # final committed _sim_patch_layers/_sim_patch_alphas (not the
        # raw per-step history _slideshow_cumulative_thetas also
        # returns), for the same staleness-tolerance reason thickness
        # already uses that path; default=None so a genuinely unmatched
        # entry falls back to the shared Active-alpha field downstream.
        patch_alphas_so_far = self._match_pass_thicknesses(
            patch_thetas_so_far, self._sim_patch_layers or patch_thetas_so_far,
            self._sim_patch_alphas or [], default=None) if patch_thetas_so_far else []
        all_pass_records = self._all_deposition_pass_records(
            junction, run, theta_overrides, patch_thetas_so_far, patch_thicknesses_so_far,
            finger_theta_lists=finger_theta_lists, finger_alpha_lists=finger_alpha_lists,
            patch_alphas=patch_alphas_so_far, alpha=alpha, dx_um=dx_um, dy_um=dy_um)

        # Every ghost caution-glyph Text artist
        # this render creates is tracked here so _on_slideshow_xlim_
        # changed can rescale them (fontsize is in fixed screen points,
        # not data units, so it would otherwise stay visually the same
        # absolute size whether the user zooms in or out -- see that
        # callback for the same rescale-in-place pattern Create/Import's
        # own overlay labels already use, _on_create_import_xlim_changed).
        # Reset on every redraw since self.slideshow_ax.clear() (called
        # by _slideshow_draw_reference just before this function runs)
        # already discarded whatever the list pointed to last time.
        self._slideshow_ghost_icon_texts = []

        def _draw_ghost_slivers(nominal_pts, axis_hat, perp_hat, origin, foreign_records):
            for sliver in self._ghost_junction_slivers(nominal_pts, axis_hat, perp_hat, origin,
                                                        foreign_records, dx_um, dy_um, junction=junction, alpha_deg=alpha):
                # Same fill/edge/hatch as _draw_shadow_band's "extend"
                # (blue) band -- confirmed that
                # this view should show a ghost sliver as the SAME visual
                # language as the existing extend-hatch annotation, not
                # a special flat "ghost" color.
                poly = MplPolygon(sliver["pts"], closed=True, facecolor="#c9cbd6", edgecolor="#7fd4ff",
                                  linewidth=1.3, linestyle=(0, (3, 2)), hatch="////", alpha=0.62, zorder=17)
                ax.add_patch(poly)
                # A small caution glyph over the
                # ghost sliver itself -- the same "⚠" caution character
                # already used everywhere else in this app's own warning
                # text (e.g. Simulate tab's "⚠ Caution"/"⚠ W1 risky"
                # verdicts), drawn ON the canvas here since a ghost line
                # is otherwise easy to miss among the ordinary hatch
                # bands (same fill/edge style, matching the "no
                # visual distinction" convention used for Post-Shadow
                # Result -- this view is the one place that gets an
                # explicit call-out).
                #
                # Fixed here: an earlier caution
                # symbol was much too big. The first attempt used a 1.6x-scaled glyph
                # inside a padded, opaque, filled circle badge -- at
                # typical zoom that badge rendered far larger than the
                # sliver it was meant to merely flag. Replaced with a
                # bare, modestly-sized glyph (roughly the same scale as
                # every other overlay label in this file, e.g.
                # _draw_shadow_band's own pass-count label) with a thin
                # dark stroke outline (matplotlib patheffects, not a
                # filled bbox) for legibility against any hatch/
                # background color underneath -- sleeker, and no longer
                # visually competing with the geometry it's annotating.
                # Also newly size-adjustable on zoom (see this function's
                # own _slideshow_ghost_icon_texts list, above, and
                # _on_slideshow_xlim_changed), which the original static
                # fontsize was not.
                gx = sum(p[0] for p in sliver["pts"]) / 4.0
                gy = sum(p[1] for p in sliver["pts"]) / 4.0
                fs = self._overlay_fontsize(ax) * 0.95
                t = ax.text(gx, gy, "⚠", color="#ffb020", fontsize=fs, fontweight="bold",
                            ha="center", va="center", zorder=23,
                            path_effects=[mpatheffects.withStroke(linewidth=1.6, foreground="#241a00")])
                self._slideshow_ghost_icon_texts.append(t)

        # NEW, section 7a ("triangular deposition artifacts") -- drawn with
        # the exact same blue hatch/caution-glyph styling as a ghost
        # sliver just above (same physical family: foreign metal landing
        # somewhere it isn't officially deposited), computed once for the
        # whole junction rather than per finger/patch/plate loop -- see
        # _triangle_anomaly_slivers' own docstring for why. Uses the same
        # cumulative (non-decaying) `all_pass_records` pool as the ghost
        # slivers below it, so a triangle -- like a ghost line -- first
        # appears at exactly the step where the offending (bisecting)
        # patch pass happens and then persists on every later step.
        for sliver in self._triangle_anomaly_slivers(junction, all_pass_records, triangle_dy_um, pmma_nm, pmgi_nm, triangle_alpha):
            poly = MplPolygon(sliver["pts"], closed=True, facecolor="#c9cbd6", edgecolor="#7fd4ff",
                              linewidth=1.3, linestyle=(0, (3, 2)), hatch="////", alpha=0.62, zorder=17)
            ax.add_patch(poly)
            gx = sum(p[0] for p in sliver["pts"]) / len(sliver["pts"])
            gy = sum(p[1] for p in sliver["pts"]) / len(sliver["pts"])
            fs = self._overlay_fontsize(ax) * 0.95
            t = ax.text(gx, gy, "⚠", color="#ffb020", fontsize=fs, fontweight="bold",
                        ha="center", va="center", zorder=23,
                        path_effects=[mpatheffects.withStroke(linewidth=1.6, foreground="#241a00")])
            self._slideshow_ghost_icon_texts.append(t)

        # Bug fix: found on a real design where the
        # shadow sim view of an early deposition step showed a junction
        # finger with its proper shadowing, but no ghost line, while the
        # post-deposition view of that exact same step showed a ghost
        # line. Root cause: the
        # three loops below used to gate ghost-sliver drawing on
        # `finger_visible`/`patches_visible` -- the SAME per-step
        # "introduced yet" gate the ordinary self-shadow hatch bands
        # above correctly use (per FOLLOW-UP 3's per-step-snapshot
        # model). That gate is right for the hatch bands (a feature's
        # OWN self-shadow only matters once its own pass has happened),
        # but wrong for ghost slivers: a ghost is a FOREIGN pass's metal
        # landing in a TARGET feature's still-open aperture, and that
        # aperture is opened by lithography before any deposition at
        # all -- it does not matter whether the target's own official
        # pass has happened yet, exactly what the docstring above
        # already establishes: a ghost sliver first appears at exactly
        # the step where the OFFENDING pass actually happens, including
        # the common case where the feature RECEIVING the ghost is only
        # introduced by a LATER step. _compute_post_
        # shadow_shapes_upto (Post Deposition) already gets this right --
        # its own ghost-sliver calls run unconditionally per shape,
        # never gated by that shape's own introduction -- so removing
        # the same stale gate here makes the two views agree, matching
        # Post Deposition's already-correct behavior instead of hiding
        # a real, already-happened foreign contamination.
        for i, f in enumerate(junction.fingers):
            fx, fy = f.patch_end[0] - f.stub_end[0], f.patch_end[1] - f.stub_end[1]
            flen = math.hypot(fx, fy) or 1.0
            axis_toward_patch = (fx / flen, fy / flen)
            perp_hat = (-axis_toward_patch[1], axis_toward_patch[0])
            finger_foreign = self._foreign_pass_records(all_pass_records, "finger", i)
            _draw_ghost_slivers(f.points, axis_toward_patch, perp_hat, f.patch_end, finger_foreign)
        patch_foreign = self._foreign_pass_records(all_pass_records, "patch", None)
        for s in junction.other_shapes:
            if s.kind != "patch":
                continue
            _axis_angle, end_a, end_b, _w = ji._polygon_axis_and_ends(s.points)
            plen = math.hypot(end_b[0] - end_a[0], end_b[1] - end_a[1]) or 1.0
            axis_hat = ((end_b[0] - end_a[0]) / plen, (end_b[1] - end_a[1]) / plen)
            perp_hat = (-axis_hat[1], axis_hat[0])
            _draw_ghost_slivers(s.points, axis_hat, perp_hat, end_a, patch_foreign)
        for s in junction.other_shapes:
            if s.kind != "plate":
                continue
            nearest_finger = self._find_finger_for_plate(junction, s)
            if nearest_finger is None:
                continue
            idx = junction.fingers.index(nearest_finger)
            near_end, far_end, plate_w = self._project_plate_onto_finger_axis(nearest_finger, s.points)
            axis_toward_near = (-(far_end[0] - near_end[0]), -(far_end[1] - near_end[1]))
            nl = math.hypot(*axis_toward_near) or 1.0
            axis_toward_near = (axis_toward_near[0] / nl, axis_toward_near[1] / nl)
            axis_toward_far = (-axis_toward_near[0], -axis_toward_near[1])
            perp_hat = (-axis_toward_far[1], axis_toward_far[0])
            plate_foreign = self._foreign_pass_records(all_pass_records, "finger", idx)
            _draw_ghost_slivers(s.points, axis_toward_far, perp_hat, near_end, plate_foreign)

    def _on_slideshow_xlim_changed(self, ax):
        """Rescales the Deposition Slideshow's ghost
        caution-glyph Text artists in place, exactly mirroring Create/
        Import's own _on_create_import_xlim_changed -- a Text artist's
        fontsize is a fixed screen-point size, so without this it would
        stay the same absolute size on screen regardless of zoom level,
        drifting out of proportion with the geometry as the user zooms
        (mouse-wheel zoom here, _on_canvas_scroll/_zoom_step, only ever
        changes xlim/ylim in place -- it does not call back into
        _slideshow_draw_shadow_sim_view, so nothing else recomputes this
        automatically). No clear/redraw of anything else, for the same
        reason Create/Import's version avoids it: a full redraw would
        itself reset xlim/ylim and immediately re-trigger this same
        xlim_changed callback."""
        texts = getattr(self, "_slideshow_ghost_icon_texts", None)
        if not texts:
            return
        fs = self._overlay_fontsize(ax) * 0.95
        for t in texts:
            t.set_fontsize(fs)
        self.slideshow_canvas.draw_idle()

    def _compute_post_shadow_shapes_upto(self, junction, report, run, finger_theta_lists, patch_thetas,
                                          finger_alpha_lists=None, patch_alphas=None):
        """Same computation as _compute_post_shadow_shapes, but using
        CALLER-SUPPLIED (possibly truncated) per-finger and patch theta
        lists instead of always reading the full/final active lists off
        `run` -- this is what makes the Deposition Slideshow's
        progressive reveal physically correct: reuses the exact same
        _compute_finger_shadowed_pieces / _compute_one_patch_shadowed_
        pieces / _compute_plate_shadowed_points functions Post-Shadow
        Result itself uses, just fed a truncated theta history so the
        real one-pass-vs-two-pass shadow geometry comes out, not the
        fully-cascaded final result. A finger/plate whose theta list is
        empty is fully absent (zero active layers, matching how
        self._sim_finger_layers already models "not deposited yet").
        finger_theta_lists: {finger_index: [thetas so far]}. patch_thetas:
        [patch thetas so far] (0, 1, or 2 entries).

        Extends this the same way _compute_post_shadow_
        shapes is extended: returns (points, kind, finger_index, thickness_nm,
        group_id) 5-tuples too (see _compute_post_shadow_shapes' own
        docstring for what group_id is for), thickness-banded the same
        way -- a partially-deposited feature mid-slideshow is shaded
        using only however many of its passes have actually happened by
        this step (a feature on its first of two passes renders as a
        single flat shade, since _thickness_shaded_pieces_for_ends/
        _patch_thickness_bands both correctly no-op/degrade with N<=1
        pass).

        `finger_alpha_lists`/`patch_alphas` are
        OPTIONAL, additive parameters -- caller-supplied per-pass
        alpha histories, parallel index-for-index to `finger_theta_lists`/
        `patch_thetas` exactly (see _slideshow_cumulative_thetas' own new
        return values, and _all_deposition_pass_records' own docstring
        for the same "caller resolves, this consumes" contract already
        used for `patch_thicknesses`-equivalent inputs elsewhere). Fed
        into each feature's own `sub_run` (as `"theta_a_alphas"`/
        `"theta_b_alphas"`) so _compute_finger_shadowed_pieces/
        _compute_plate_shadowed_points/_compute_one_patch_shadowed_pieces
        (already fixed to resolve per-pass alpha from `run`) apply it
        automatically here too, and into _all_deposition_pass_records so
        every cross-feature ghost/widening mechanism gets it as well.
        Omitting both (the old 5-arg call shape, still used by the 3
        existing direct-call test files) reproduces today's exact
        shared-alpha behavior -- fully backward compatible."""
        alpha = run.get("alpha", 30.0)
        try:
            pmma_nm = float(self.pmma_edit.text()) if hasattr(self, "pmma_edit") else 875.0
        except ValueError:
            pmma_nm = 875.0
        try:
            pmgi_nm = float(self.pmgi_edit.text()) if hasattr(self, "pmgi_edit") else 600.0
        except ValueError:
            pmgi_nm = 600.0
        dx_um, dy_um = self._shadow_dxdy(pmma_nm, pmgi_nm, alpha)
        theta_overrides = [run.get("theta_a"), run.get("theta_b")]

        # "Ghost junction lines" corrected model:
        # the pass pool here is built from finger_theta_lists/patch_thetas
        # (already truncated to "so far" by the caller), so a ghost line
        # correctly can't appear before the pass that actually causes it
        # happens in the slideshow -- see _all_deposition_pass_records'
        # own finger_theta_lists parameter.
        patch_thicknesses_upto = self._match_pass_thicknesses(
            patch_thetas, self._sim_patch_layers or patch_thetas, self._sim_patch_thicknesses or []) if patch_thetas else []
        all_pass_records = self._all_deposition_pass_records(
            junction, run, theta_overrides, patch_thetas, patch_thicknesses_upto,
            finger_theta_lists=finger_theta_lists, finger_alpha_lists=finger_alpha_lists,
            patch_alphas=patch_alphas, alpha=alpha, dx_um=dx_um, dy_um=dy_um)

        shapes = []
        group_counter = [0]

        def _next_group_id():
            gid = group_counter[0]
            group_counter[0] += 1
            return gid

        for i, f in enumerate(junction.fingers):
            thetas = finger_theta_lists.get(i, [])
            sub_run = dict(run)
            # Series-chain generalization: keyed by this
            # finger's own real index via "finger_theta_lists"/
            # "finger_alpha_lists" (read first by _run_finger_thetas/
            # _run_finger_alphas) instead of the old finger-0/1-only
            # theta_a_list/theta_b_list aliasing -- see _run_finger_
            # thetas' docstring for why that aliasing was a real bug for
            # finger index >= 2.
            sub_run["finger_theta_lists"] = {i: thetas}
            if finger_alpha_lists is not None:
                sub_run["finger_alpha_lists"] = {i: finger_alpha_lists.get(i, [])}
            layers_ref = self._sim_finger_layers.get(i) or thetas
            thicknesses_ref = self._sim_finger_thicknesses.get(i, [])
            pass_thicknesses = self._match_pass_thicknesses(thetas, layers_ref, thicknesses_ref) if thetas else []
            # Same fix as _compute_post_shadow_
            # shapes' own finger loop -- this finger's own per-pass alpha
            # (from finger_alpha_lists when the caller supplied it,
            # falling back to the shared `alpha`) threaded through
            # `passes` as a 3rd tuple element, so the Slideshow's own
            # progressive thickness-shading gradient matches the final
            # Post-Shadow Result's, not just its silhouette.
            alpha_hints = finger_alpha_lists.get(i) if finger_alpha_lists is not None else None
            pass_alphas = self._resolve_pass_alpha_list(thetas, alpha_hints, alpha) if thetas else []
            passes = list(zip(thetas, pass_thicknesses, pass_alphas))
            fx, fy = f.patch_end[0] - f.stub_end[0], f.patch_end[1] - f.stub_end[1]
            flen = math.hypot(fx, fy) or 1.0
            axis_toward_patch = (fx / flen, fy / flen)
            axis_toward_stub = (-axis_toward_patch[0], -axis_toward_patch[1])
            stub_ranked = self._end_depth_ranking(axis_toward_stub, passes, dx_um, dy_um)
            patch_ranked = self._end_depth_ranking(axis_toward_patch, passes, dx_um, dy_um)

            def _finger_pass_footprint(theta, alpha_override=None, _f=f, _i=i):
                """Same generalized-model reuse as _compute_post_shadow_
                shapes' own _finger_pass_footprint -- applied
                here too so the Deposition Slideshow's progressive-reveal
                view shows the same real per-pass decoherence as the
                final Post-Shadow Result, not just the final step.
                `alpha_override` follows an identical
                pattern to the final Post-Shadow Result's own fix."""
                single_run = self._single_pass_run(_i, theta, alpha_override)
                pieces = self._compute_finger_shadowed_pieces(junction, _f, _i, single_run, [None, None],
                                                               alpha, dx_um, dy_um)
                if not pieces:
                    return None
                if len(pieces) == 1:
                    return pieces[0]
                return so.unary_union([sg.Polygon(p) for p in pieces])

            # Deliberately NOT widened here: see
            # _compute_post_shadow_shapes' own finger loop comment for
            # the full reasoning (fingers are thin enough to already be
            # fully self-shadowed within a bilayer resist's lateral
            # shadow-throw at this tilt, so a foreign pass can't
            # plausibly add real geometric width the way it can for a
            # wide adhesion plate).
            # finger_foreign is still needed for the ghost-sliver check
            # right below, which models a different physical situation
            # (metal landing in a separate still-open aperture).
            finger_perp_hat = (-axis_toward_patch[1], axis_toward_patch[0])
            finger_foreign = self._foreign_pass_records(all_pass_records, "finger", i)

            finger_pieces_upto = self._compute_finger_shadowed_pieces(junction, f, i, sub_run, theta_overrides, alpha, dx_um, dy_um)

            for piece_pts in finger_pieces_upto:
                gid = _next_group_id()
                for band_pts, thickness in self._thickness_shaded_pieces_for_ends(
                        f.points, f.stub_end, f.patch_end, stub_ranked, patch_ranked, piece_pts,
                        axis_toward_far=axis_toward_patch, thetas=thetas, dx_um=dx_um, dy_um=dy_um, origin=f.patch_end,
                        passes=passes, pass_footprint_fn=_finger_pass_footprint):
                    shapes.append((band_pts, "finger", i, thickness, gid, False))
            for sliver in self._ghost_junction_slivers(f.points, axis_toward_patch, finger_perp_hat,
                                                        f.patch_end, finger_foreign, dx_um, dy_um, junction=junction, alpha_deg=alpha):
                ggid = _next_group_id()
                shapes.append((sliver["pts"], sliver["kind"], sliver["feature_index"], sliver["thickness"], ggid, True))

        if patch_thetas:
            patch_layers_ref = self._sim_patch_layers or patch_thetas
            patch_thicknesses_ref = self._sim_patch_thicknesses or []
            patch_thicknesses = self._match_pass_thicknesses(patch_thetas, patch_layers_ref, patch_thicknesses_ref)
            # Same per-pass dx/dy resolution
            # _compute_post_shadow_shapes' own patch loop already applies,
            # so this patch group's own thickness bands (below) reflect
            # per-pass alpha the same way in the Slideshow's progressive
            # view, not just the final Post-Shadow Result.
            patch_dx_list, patch_dy_list = self._resolve_pass_dxdy_list(patch_thetas, patch_alphas, dx_um, dy_um, pmma_nm, pmgi_nm)
            for pg in report.patch_groups:
                finger = junction.fingers[pg.finger_index]
                fx, fy = finger.patch_end[0] - finger.stub_end[0], finger.patch_end[1] - finger.stub_end[1]
                flen = math.hypot(fx, fy) or 1.0
                fu, fv = fx / flen, fy / flen
                for s in self._patches_for_group(junction, finger, pg.patch_count):
                    _axis_angle, end_a, end_b, _w = ji._polygon_axis_and_ends(s.points)
                    proj_a = (end_a[0] - finger.stub_end[0]) * fu + (end_a[1] - finger.stub_end[1]) * fv
                    proj_b = (end_b[0] - finger.stub_end[0]) * fu + (end_b[1] - finger.stub_end[1]) * fv
                    near_end, far_end = (end_a, end_b) if proj_a < proj_b else (end_b, end_a)
                    axis_toward_near = (-(far_end[0] - near_end[0]), -(far_end[1] - near_end[1]))
                    nl = math.hypot(*axis_toward_near) or 1.0
                    axis_toward_near = (axis_toward_near[0] / nl, axis_toward_near[1] / nl)
                    axis_toward_far = (-axis_toward_near[0], -axis_toward_near[1])
                    patch_pieces_upto = self._compute_one_patch_shadowed_pieces(junction, finger, s, patch_thetas, alpha, dx_um, dy_um, patch_alphas)
                    for piece_pts in patch_pieces_upto:
                        gid = _next_group_id()
                        for band_pts, thickness in self._patch_thickness_bands(
                                s, near_end, far_end, axis_toward_near, axis_toward_far,
                                patch_thetas, patch_thicknesses,
                                patch_dx_list[0] if patch_dx_list else dx_um,
                                patch_dy_list[0] if patch_dy_list else dy_um,
                                piece_pts,
                                dx2_um=patch_dx_list[1] if len(patch_dx_list) > 1 else None,
                                dy2_um=patch_dy_list[1] if len(patch_dy_list) > 1 else None):
                            shapes.append((band_pts, "patch", pg.finger_index, thickness, gid, False))
                    patch_perp_hat = (-axis_toward_far[1], axis_toward_far[0])
                    patch_foreign = self._foreign_pass_records(all_pass_records, "patch", None)
                    for sliver in self._ghost_junction_slivers(s.points, axis_toward_far, patch_perp_hat,
                                                                near_end, patch_foreign, dx_um, dy_um, junction=junction, alpha_deg=alpha):
                        ggid = _next_group_id()
                        shapes.append((sliver["pts"], sliver["kind"], sliver["feature_index"], sliver["thickness"], ggid, True))

        plate_shapes = [s for s in junction.other_shapes if s.kind == "plate"]
        for s in plate_shapes:
            owner = self._find_finger_for_plate(junction, s)
            owner_idx = junction.fingers.index(owner) if owner in junction.fingers else None
            thetas = finger_theta_lists.get(owner_idx, []) if owner_idx is not None else []
            sub_run = dict(run)
            if owner_idx is not None:
                # Series-chain generalization: see the
                # matching finger-loop comment above for why this is now
                # keyed by owner_idx via "finger_theta_lists" instead of
                # the old finger-0/1-only theta_a_list/theta_b_list pair.
                sub_run["finger_theta_lists"] = {owner_idx: thetas}
                if finger_alpha_lists is not None:
                    sub_run["finger_alpha_lists"] = {owner_idx: finger_alpha_lists.get(owner_idx, [])}
            new_pts = self._compute_plate_shadowed_points(junction, s, sub_run, theta_overrides, alpha, dx_um, dy_um)
            # Bug fix: when a second finger gets deposited, its
            # adhesion plate should not already show two depositions --
            # both adhesion plates and the first junction finger should
            # be shown deposited only in their actual first deposition
            # step. `new_pts
            # is None` here means only "this plate's OWN owning finger
            # hasn't deposited yet AS OF THIS SLIDESHOW STEP" -- but the
            # plate itself is still a real, already-patterned aperture on
            # the open wafer, so (per the exact same "every deposition
            # step exposes the whole open wafer" blanket model already
            # used for a not-yet-introduced finger's own ghost-sliver
            # aperture) it can still legitimately receive metal from an
            # OTHER finger's own foreign pass at an EARLIER step, before
            # its own official pass ever happens. The old `continue` here
            # skipped this plate's entire foreign-exposure computation
            # outright at every step before its own finger's turn -- so
            # it showed NOTHING at the step where only the OTHER finger
            # had deposited, then jumped straight to its own official
            # piece PLUS a disjoint foreign lobe (2 pieces) the very
            # instant its own finger finally deposited, looking like "two
            # depositions appeared at once" instead of the plate
            # correctly accumulating one per step, in order, matching the
            # rule above: a wide/long-enough-to-reach plate's own
            # deposition count should track the number of deposition
            # steps that have actually happened, not just its own
            # finger's. Fixed identically to _compute_post_shadow_
            # shapes' own plate loop (see that fix's own comment for the
            # full writeup): substitute this plate's own NOMINAL
            # (undeposited) points whenever its own official pass hasn't
            # happened YET AT THIS STEP, so the foreign-exposure machinery
            # just below still runs against it -- but only actually
            # emitting anything if a real foreign contribution is found
            # (the guard right after foreign_footprints/disjoint_lobes
            # are computed) -- a plate truly untouched so far, own or
            # foreign, still shows nothing, exactly as before.
            own_pass_pending = new_pts is None
            plate_foreign = self._foreign_pass_records(all_pass_records, "finger", owner_idx) if owner_idx is not None else []
            if own_pass_pending:
                if not plate_foreign:
                    continue  # truly nothing has deposited here yet, this step or any earlier one
                # Bug fix: found on the Deposition Slideshow's
                # Post Deposition view (see the identical fix's full writeup in
                # _compute_post_shadow_shapes' own plate loop above --
                # this Slideshow copy had the byte-identical bug). Leave
                # new_pts as None instead of substituting this plate's own
                # full nominal (undeposited) points -- see
                # _widen_with_foreign_footprints' own updated docstring for
                # why that substitution made the union below a no-op that
                # always showed the entire, uncut plate.

            def _plate_pass_footprint(theta, alpha_override=None, _s=s, _owner_idx=owner_idx):
                # `alpha_override` -- now genuinely
                # wired, now that _slideshow_cumulative_thetas returns a
                # parallel alpha history (finger_alpha_lists) and
                # all_pass_records above is called with it -- a foreign
                # plate record's own "alpha" key (stamped there) flows
                # through _foreign_blanket_footprints/
                # _disjoint_foreign_plate_lobes into this exact parameter.
                # Keyed via _single_pass_run (works for any
                # finger index) instead of the old finger-0/1-only key.
                single_run = self._single_pass_run(_owner_idx, theta, alpha_override)
                return self._compute_plate_shadowed_points(junction, _s, single_run, [None, None], alpha, dx_um, dy_um)

            foreign_footprints = self._foreign_blanket_footprints(plate_foreign, _plate_pass_footprint) if plate_foreign else []
            if foreign_footprints:
                widened_pts, _multi = self._widen_with_foreign_footprints(new_pts, foreign_footprints)
                new_pts = widened_pts
            # Slideshow Post-Deposition view: mirror the
            # identical fix applied above in _compute_post_shadow_shapes's own
            # plate loop. _widen_with_foreign_footprints now correctly refuses
            # to replace this plate's own official geometry with an unrelated,
            # merely-larger foreign lobe when the two don't actually touch --
            # but a foreign pass's own solo footprint on this plate can still
            # be real, physically-deposited metal that simply lands disjoint
            # from the plate's own geometry (confirmed on a real design
            # via probe9_solo_foreign_plate.py: finger B's plate sees
            # its own official footprint on the left half and a disjoint,
            # comparable-area foreign footprint from finger A's pass on the
            # right half). Surface each such disjoint lobe as its own
            # separate is_ghost=True piece (same physical model as
            # _ghost_junction_slivers, just at plate scale) instead of
            # silently dropping it, so this real deposition risk is still
            # visible rather than just no longer corrupting the plate's own
            # shape. _disjoint_foreign_plate_lobes checks each foreign record
            # against the now-official-only new_pts, so an overlapping record
            # (already contributing its thickness below via extra_passes /
            # _plate_thickness_bands) is correctly excluded here, avoiding
            # double-counting.
            disjoint_lobes = (self._disjoint_foreign_plate_lobes(new_pts if new_pts is not None else s.points,
                                                                    plate_foreign, _plate_pass_footprint)
                               if plate_foreign else [])
            # The other half of the own_pass_
            # pending guard above -- see _compute_post_shadow_shapes' own
            # identical guard for the full writeup.
            if own_pass_pending and not foreign_footprints and not disjoint_lobes:
                continue
            if new_pts is None:
                # Defensive only -- see the identical fallback's comment in
                # _compute_post_shadow_shapes' own plate loop above.
                new_pts = s.points
            for lobe_pts, lobe_thickness in disjoint_lobes:
                lgid = _next_group_id()
                shapes.append((lobe_pts, "plate", owner_idx, lobe_thickness, lgid, True))
            extra_passes = [(rec["theta"], rec["thickness"], rec.get("alpha", alpha)) for rec in plate_foreign] if foreign_footprints else []
            gid = _next_group_id()
            for band_pts, thickness in self._plate_thickness_bands(junction, s, sub_run, theta_overrides, alpha, dx_um, dy_um,
                                                                     new_pts, extra_passes=extra_passes):
                shapes.append((band_pts, "plate", owner_idx, thickness, gid, False))
            if owner is not None:
                near_end, far_end, plate_w = self._project_plate_onto_finger_axis(owner, s.points)
                axis_toward_near = (-(far_end[0] - near_end[0]), -(far_end[1] - near_end[1]))
                nl = math.hypot(*axis_toward_near) or 1.0
                axis_toward_near = (axis_toward_near[0] / nl, axis_toward_near[1] / nl)
                axis_toward_far = (-axis_toward_near[0], -axis_toward_near[1])
                plate_perp_hat = (-axis_toward_far[1], axis_toward_far[0])
                for sliver in self._ghost_junction_slivers(s.points, axis_toward_far, plate_perp_hat,
                                                            near_end, plate_foreign, dx_um, dy_um, junction=junction, alpha_deg=alpha):
                    ggid = _next_group_id()
                    shapes.append((sliver["pts"], sliver["kind"], sliver["feature_index"], sliver["thickness"], ggid, True))

        # NEW, section 7a ("triangular deposition artifacts") -- see
        # _compute_post_shadow_shapes' identical call/ordering and
        # _triangle_anomaly_slivers'/_merge_triangle_group_id's own
        # docstrings. Using the truncated `all_pass_records` pool above
        # means a triangle correctly can't appear in the slideshow before
        # the patch pass that causes it has actually happened yet. Done
        # LAST (after every ghost sliver above is already in `shapes`)
        # so _merge_triangle_group_id can find and reuse a matching
        # sliver's group_id instead of always minting a fresh one.
        for sliver in self._triangle_anomaly_slivers(junction, all_pass_records, dy_um, pmma_nm, pmgi_nm, alpha):
            ggid = self._merge_triangle_group_id(sliver["pts"], sliver["kind"], sliver["thickness"],
                                                  sliver["merge_finger_index"], shapes, _next_group_id)
            shapes.append((sliver["pts"], sliver["kind"], sliver["feature_index"], sliver["thickness"], ggid, True))
        return self._cross_feature_thickness_overlay(shapes)

    def _mill_target_anchors(self, junction):
        """The real, physical electrode-contact point(s) for THIS
        design -- one per finger/patch/plate that actually crosses
        junction.electrode_polygons (the same hole-based definition
        Warning #1 and _find_electrode_crossing_line already use
        everywhere else in the app), used to LOCALLY anchor the ion-mill
        highlight below instead of guessing from whatever the camera
        happens to be showing.

        Root cause: found on a real array-structure design
        where the highlight logic was incorrect most of the time,
        zooming the screen entirely out of view and showing the entire
        electrode highlighted: the previous approach scoped candidate edges by the
        SLIDESHOW'S OWN CAMERA STATE (near_bounds / a 3x-view-width
        margin) rather than by real geometry. For a real GDS import,
        electrode_material is one CONNECTED sweep (junction_import.
        nearby_material) that can legitimately span an entire electrode
        array as a single polygon (or a few large ones) -- once ANY
        part of that polygon fell inside the camera's search margin, the
        WHOLE polygon (routinely hundreds of vertices, spanning the
        entire array) became a fallback candidate, and its single
        globally-best-facing edge could sit anywhere on it, often far
        from the junction actually being milled. Widening the camera to
        include that one far edge then dragged the whole array into
        view -- exactly the reported symptom.

        This anchor list is the fix's foundation: instead of "what does
        the camera currently see," ask "where does this design's own
        finger/patch actually touch the electrode" -- a question with a
        single, deterministic, already-correct answer
        (_find_electrode_crossing_line, the same function the
        electrode-crossing shadow/ghost-junction-line mechanisms already
        rely on). Every candidate edge below is then judged by real
        distance to one of THESE points, never by camera state -- fixing
        the wrong-side/wrong-fragment bug and the zoom-out bug with the
        same change, since a highlight tied to a real, LOCAL contact
        point can never legitimately need to reach far away in the first
        place. Works identically for a hand-drawn Create/Import shape
        promoted to a finger/patch/plate: by the time it's in
        junction.fingers/other_shapes it's the same ImportedFinger/
        ImportedShape representation regardless of origin, so no special
        casing is needed for hand-created electrodes.

        Returns a list of (x, y) crossing-line midpoints, one per
        feature that actually crosses the electrode -- empty if nothing
        does (e.g. a design with no finger/patch contact yet, or a
        synthetic/fake junction with no .fingers/.other_shapes at all),
        in which case the caller falls back to the older camera-based
        heuristic below rather than highlighting nothing."""
        anchors = []
        fingers = getattr(junction, "fingers", None) or []
        other_shapes = getattr(junction, "other_shapes", None) or []
        for feat in list(fingers) + list(other_shapes):
            pts = getattr(feat, "points", None)
            if not pts or len(pts) < 3:
                continue
            try:
                edge = self._find_electrode_crossing_line(junction, pts)
            except Exception:
                edge = None
            if edge is None:
                continue
            p1, p2 = edge
            anchors.append(((p1[0] + p2[0]) / 2.0, (p1[1] + p2[1]) / 2.0))
        return anchors

    @staticmethod
    def _mill_trench_union(junction):
        """Restricts ion-mill exposure to real lithographic trenches, fixing
        a missing-physics gap found when a highlight landed well away from
        the actual junction crossing, on an unrelated real electrode edge.
        The beam can only reach material inside a feature's own
        lithographically-opened resist trench; nowhere else on the wafer is
        ever exposed to it.

        Earlier revisions of this ion-mill feature searched for an exposed
        electrode/deposited-material edge ANYWHERE within `local_radius_um`
        of a real contact anchor, with no concept of resist at all -- so on
        a design whose electrode has real topology/steps within that radius
        that have nothing to do with the junction, an edge that is actually
        still buried under resist could win the search purely by being
        geometrically closer/better-facing than the real, resist-opened
        crossing edge. This gap stayed hidden on designs whose electrode
        hugs the finger tightly enough that "anywhere nearby" and "inside
        the real trench" always happened to coincide.

        This is not a new concept invented for this fix -- "aperture"
        (an as-patterned resist opening that stays open, unchanged, for
        the entire finger/patch/plate/mill/oxidation sequence until
        final liftoff) is already the load-bearing concept behind every
        cross-feature deposition mechanism in this file (ghost junction
        slivers, foreign-pass blanket footprints, etc. -- see
        _ghost_junction_slivers' own docstring). This function just
        finally applies that SAME concept to the ion-mill search: the
        trench/aperture region for the WHOLE design is the union of
        every finger/patch/plate's own as-drawn nominal polygon
        (`.points` on each junction.fingers/junction.other_shapes
        entry) -- literally where lithography has developed the resist
        away, on day one, before any deposition or milling happens, and
        never resist-covered again until the whole junction is done.
        Nothing outside this union is ever reachable by the beam, no
        matter how well an edge there faces the beam or how close it
        sits to a real anchor.

        Returns None (never an empty geometry) when this junction has no
        real finger/patch/plate geometry to build a trench from at all
        (a synthetic/fake junction with empty/absent .fingers/
        .other_shapes, e.g. most of this file's own hand-built test
        fixtures) -- callers MUST treat None as "no trench restriction
        available, don't clip," not "nothing is ever exposed," so every
        pre-existing synthetic test (which never modeled a trench to
        begin with) keeps its exact prior behavior."""
        fingers = getattr(junction, "fingers", None) or []
        other_shapes = getattr(junction, "other_shapes", None) or []
        polys = []
        for feat in list(fingers) + list(other_shapes):
            pts = getattr(feat, "points", None)
            if not pts or len(pts) < 3:
                continue
            try:
                poly = sg.Polygon(pts).buffer(0)
                if not poly.is_empty:
                    polys.append(poly)
            except Exception:
                continue
        if not polys:
            return None
        try:
            union = so.unary_union(polys)
            return None if union.is_empty else union
        except Exception:
            return None

    def _mill_touched_electrode_fragment_indices(self, junction):
        """Which specific junction.electrode_polygons fragments a real
        finger/patch/plate feature genuinely touches or overlaps,
        independent of simple anchor-radius proximity.

        This closes a missing-physics gap where a highlight could land far
        from the real junction crossing, on an unrelated but nearby
        electrode fragment: because photoresist covers the wafer except
        inside each feature's own lithographically-opened trench, the ion
        beam can only reach electrode material within one of those
        trenches, and a nearby-but-untouched fragment must not win the
        search just by being geometrically close.

        An earlier approach applied resist-locality literally: only
        material inside a finger/patch/plate's own bare drawn polygon
        could ever be exposed (that approach is still available as its own
        building block in _mill_trench_union, though no longer wired into
        the exposure search). That is too narrow -- verified against two
        other already-validated regression scenarios
        (test_mill_highlight_local_anchor.py's array-structure "local
        square", and this file's own default 2-electrode parametric
        junction): a real finger's own linewidth is routinely much
        narrower than the local contact PAD/electrode fragment it lands
        on, and the far side of that SAME small, self-contained local
        fragment is still a genuinely valid, physically-correct mill
        target (e.g. a small isolated electrode rectangle's OWN far edge,
        even though no finger polygon literally overlaps that edge's
        exact coordinates) -- the literal-polygon-containment version
        wrongly zeroed both of those already-correct behaviors out.

        The real distinguishing fact in every one of these cases turns out
        to be FRAGMENT IDENTITY, not literal footprint overlap: a small,
        self-contained electrode fragment that a real feature's own
        polygon genuinely touches/overlaps is this junction's own local
        contact structure, in full (matches the default-junction and
        local-anchor cases, where the touched fragment IS the whole local
        square/rectangle). A SEPARATE, disjoint electrode_polygons
        fragment that merely happens to sit within local_radius_um of a
        real anchor -- but that no real finger/patch/plate polygon
        actually overlaps -- is a different, resist-covered piece of
        electrode/routing that just happens to be nearby (a real chip
        layout's electrode_polygons is routinely several separate small
        pad/routing fragments, not one shape per junction, and a
        genuinely different, untouched one landing inside the generous
        existing proximity radius is exactly what could let an unrelated
        "isolated square" win the old search). Restricting the candidate
        electrode pool to only genuinely-touched fragments (when this
        junction has any real finger/patch/plate geometry to test against
        at all) fixes that over-broad candidate set without disturbing
        either already-validated "whole local fragment is exposed"
        behavior.

        Returns an empty set when this junction has no electrode_polygons,
        or no real finger/patch/plate geometry to test against at all (a
        synthetic/fake junction with empty/absent .fingers/.other_shapes,
        e.g. most of this file's own hand-built anchor-only test
        fixtures) -- callers MUST treat an empty set as "no fragment-
        identity restriction available, use every fragment near an
        anchor as before," not "nothing is touched.\""""
        electrode = [p for p in (getattr(junction, "electrode_polygons", None) or []) if len(p) >= 3]
        if not electrode:
            return set()
        fingers = getattr(junction, "fingers", None) or []
        other_shapes = getattr(junction, "other_shapes", None) or []
        features = list(fingers) + list(other_shapes)
        if not features:
            return set()
        elec_polys = []
        for p in electrode:
            try:
                poly = sg.Polygon(p).buffer(0)
            except Exception:
                poly = None
            elec_polys.append(poly)
        touched = set()
        for feat in features:
            pts = getattr(feat, "points", None)
            if not pts or len(pts) < 3:
                continue
            try:
                feat_poly = sg.Polygon(pts).buffer(0)
            except Exception:
                continue
            if feat_poly.is_empty:
                continue
            probe = feat_poly.buffer(1e-3)
            for i, ep in enumerate(elec_polys):
                if i in touched or ep is None or ep.is_empty:
                    continue
                try:
                    if probe.intersects(ep):
                        touched.add(i)
                except Exception:
                    continue
        return touched

    @staticmethod
    def _ring_signed_area(points):
        """Twice-the-signed-area formula (returns the actual signed area,
        not doubled) for a closed ring given as a list of (x, y) points
        with NO repeated closing point. Sign is the standard math
        convention: positive for counter-clockwise, negative for
        clockwise -- a global, topological property of the ring as a
        whole, unlike a per-edge "which way is outward" guess. Used by
        _mill_exposed_ring_edges to get the correct outward-normal
        rotation for ANY simple ring (a polygon's own exterior, or one of
        its interior/hole rings) regardless of how concave it is -- see
        that function's docstring for why this replaces the older
        centroid-relative heuristic."""
        n = len(points)
        area = 0.0
        for i in range(n):
            x1, y1 = points[i]
            x2, y2 = points[(i + 1) % n]
            area += x1 * y2 - x2 * y1
        return area / 2.0

    def _mill_electrode_occluder_union(self, junction, anchors, local_radius_um, extra_polys=None):
        """The real, LOCAL, seam-free electrode silhouette near this
        design's own real contact anchors (see _mill_target_anchors):
        every junction.electrode_polygons fragment that genuinely
        TOUCHES OR OVERLAPS a fragment already known to sit near a real
        anchor, dissolved together (a bounded flood fill, never
        unbounded -- see the prefilter below).

        ROOT CAUSE #1, found on a real design where the highlight picked
        out an interior shape inside the electrode rather than the true
        boundary between the electrode and the substrate: a real electrode
        is frequently stored as several separate polygon fragments that
        are only touching or overlapping each other, not one clean
        silhouette. Scanning each fragment's own edges independently --
        what _mill_highlighted_edges' legacy path still does, and what
        this whole function replaces for the anchor-based path -- can
        select an edge that is really an INTERNAL SEAM between two
        fragments of the SAME physical electrode, never a true
        electrode/substrate boundary. Dissolving genuinely-touching
        fragments together first makes that seam disappear entirely,
        exactly like it disappears from the real, physical, continuous
        piece of Nb.

        ROOT CAUSE #2, found the hard way after root cause #1's fix alone
        was verified against a synthetic reproduction but STILL didn't
        reproduce the true bowtie/hourglass shape (or the correct side)
        against a real design with a concave, pinched electrode: the source array
        this function unions from is junction.electrode_polygons, NOT
        junction.electrode_material. electrode_material's own docstring
        in junction_import.py says it is "for background display only,
        not for warning calculations" -- and a first attempt at this fix
        used it anyway (via a "material minus nearby holes" difference),
        which happened to LOOK plausible (a "material" fragment there
        really was a coarse, un-pinched rectangle, and electrode_polygons
        really did carry the fine pinch as what looked like "holes" to
        subtract) but was geometrically backwards: subtracting a polygon
        out of another one reverses that polygon's own ring winding in
        the result, which flips the ring-signed-area-derived outward
        normal (see _mill_exposed_ring_edges) for every edge along the
        carved boundary -- so that attempt highlighted the correct
        FEATURE (the fine bowtie curve) on the WRONG SIDE every time
        (confirmed: it swapped which of two real, separate electrodes
        theta=0 vs theta=180 exposed, root-caused by hand-tracing the
        winding of a difference() result vs the operand's own standalone
        ring). electrode_polygons is not "holes to cut out of the real
        material" at all -- despite the confusing internal name (it
        comes from a junction_import query called nearby_holes), it IS
        the electrode, directly, at full precision -- confirmed by
        _find_electrode_crossing_line's own docstring, which documents
        switching TO electrode_polygons FROM electrode_material for
        exactly this reason, and by every other warning/crossing/contact
        computation in this file already trusting it the same way (e.g.
        the outward/inward patch-end classification in junction_import.py
        tests `electrode_union.contains(point)` against an
        electrode_polygons-built union to decide which end of a patch
        group has actually reached the electrode). So the fix is simply
        to union electrode_polygons fragments directly, as the electrode
        they already are, with no difference/subtraction step at all --
        which also means a real design's electrode can legitimately
        dissolve into two genuinely SEPARATE local pieces here (e.g. two
        distinct electrodes on either side of a junction barrier, a real
        situation this fix was verified against), each highlighted
        independently at its own matching theta, which is physically
        correct.

        Deliberately NOT done by "gather everything within some radius of
        an anchor and union it" -- that would have the exact same failure
        mode this whole file's array-structure fix (see
        _mill_target_anchors) was written to avoid: two genuinely
        SEPARATE, disjoint electrodes that merely happen to sit near each
        other would get silently merged into one shape just because of
        distance, not real contact. Group membership is decided ONLY by
        real geometric touching/overlap (a tiny 1nm buffer to bridge
        floating-point-exact-but-not-quite-touching seams from GDS
        snapping, nothing more); a cheap prefilter-by-distance is used
        ONLY to keep the candidate pool small on a design with many far-
        away, unrelated fragments, never to decide the final grouping.

        A later addition lets the mill also expose the sides of features
        that have already been deposited -- useful for limiting how long
        the ion mill needs to run once junction fingers are already in
        place: this function now accepts an optional `extra_polys` -- point-list
        polygons for whatever finger/patch/plate metal has ALREADY been
        deposited by this point in the recipe (the Slideshow's own
        `upto_shapes`, see _slideshow_draw_mill_highlight) -- and folds
        them into the exact same touching-based union pool as the
        electrode fragments, via the shared `_touching_union_near_
        anchors` engine (extracted from this function's own prior body,
        behavior-preserving). Physically: once metal has landed on top of
        the electrode's contact area, a LATER sidewall mill no longer
        strikes the (now-covered) electrode there -- it strikes the
        deposited metal's own exposed sidewall instead. Unioning both
        sources together and re-deriving the boundary from the combined
        silhouette gets this right automatically, with no separate
        "is this location covered yet" bookkeeping needed: wherever
        deposited material extends past/over the electrode, the combined
        union's boundary naturally follows the metal (now outermost);
        wherever nothing has landed yet, it still follows the bare
        electrode, exactly as before. Self-shadowing (_mill_exposed_ring_
        edges) then applies uniformly to the combined shape too, so a
        raised, already-deposited finger can correctly shadow part of the
        electrode or another stacked layer behind it, and vice versa.
        Omitted or empty reproduces today's electrode-only silhouette
        exactly (verified: every pre-existing caller passes only the
        first three positional args).

        Candidate electrode fragments are further restricted to those a
        real finger/patch/plate feature genuinely touches/overlaps (see
        _mill_touched_electrode_fragment_indices), when this junction has
        any such real geometry to test against at all -- this fixes a case
        where an "isolated square" of electrode, well within
        `local_radius_um` of a real anchor but not actually touched by
        anything, could win the search anyway. A junction with no real
        finger/patch/plate geometry (synthetic anchor-only test fixtures)
        gets no restriction here, exactly as before.

        Returns None if there's nothing to highlight at all (no anchors,
        or nothing electrode_polygons/extra_polys-shaped near any of
        them)."""
        electrode_all = [p for p in (junction.electrode_polygons or []) if len(p) >= 3]
        touched = self._mill_touched_electrode_fragment_indices(junction)
        electrode = [p for i, p in enumerate(electrode_all) if i in touched] if touched else electrode_all
        extra = [p for p in (extra_polys or []) if len(p) >= 3]
        return self._touching_union_near_anchors(electrode + extra, anchors, local_radius_um)

    @staticmethod
    def _touching_union_near_anchors(polys, anchors, local_radius_um):
        """Shared engine, extracted from _mill_electrode_occluder_union
        so it can also be reused to build a DEPOSITED-
        MATERIAL-ONLY silhouette (for classifying/coloring a mill
        highlight segment as "bare electrode" vs "already-deposited
        metal", see _slideshow_draw_mill_highlight) without duplicating
        this logic. Dissolves genuinely-touching/overlapping fragments of
        `polys` within reach of `anchors` into one shapely silhouette --
        see _mill_electrode_occluder_union's own docstring (the root-cause
        analysis and the "deliberately NOT distance-based merging"
        note) for the full reasoning; behavior for the electrode-only
        case is UNCHANGED from before this extraction.

        Returns None if there's nothing to highlight at all (no anchors,
        or nothing in `polys` near any of them)."""
        valid = [p for p in (polys or []) if len(p) >= 3]
        if not valid or not anchors:
            return None
        prefilter_radius = local_radius_um * 4.0
        pool_polys = {}
        for i, p in enumerate(valid):
            if not any(math.hypot(px - ax_, py - ay_) <= prefilter_radius for px, py in p for ax_, ay_ in anchors):
                continue
            try:
                poly = sg.Polygon(p).buffer(0)
                if not poly.is_empty:
                    pool_polys[i] = poly
            except Exception:
                continue
        if not pool_polys:
            return None
        # Seed: fragments genuinely near a real anchor (the tighter,
        # final radius -- prefilter_radius above only widened the pool so
        # a touching neighbor further out can still be found below).
        group = {i for i in pool_polys if any(
            math.hypot(px - ax_, py - ay_) <= local_radius_um for px, py in valid[i] for ax_, ay_ in anchors)}
        if not group:
            return None
        touch_buffer = 1e-3
        changed = True
        while changed:
            changed = False
            for i in pool_polys:
                if i in group:
                    continue
                probe = pool_polys[i].buffer(touch_buffer)
                for j in group:
                    try:
                        if probe.intersects(pool_polys[j]):
                            group.add(i)
                            changed = True
                            break
                    except Exception:
                        continue
        try:
            union = so.unary_union([pool_polys[i] for i in group])
            return None if union.is_empty else union
        except Exception:
            return None

    def _mill_electrode_occluder_groups(self, junction, anchors, local_radius_um, extra_polys=None):
        """A regression found against two real designs -- one where nothing
        showed up in the highlight at all, and another where the electrode
        highlighting appeared far below the actual junction -- traced to
        the single shared flood-fill pool used at the time
        (_touching_union_near_anchors, folding electrode_polygons AND
        deposited_polys together indiscriminately), which can let a thin
        deposited finger that genuinely bridges the gap between two real,
        physically SEPARATE electrodes (exactly the
        two-huge-slabs-either-side-of-a-junction-barrier shape a
        Josephson junction's own finger crossing is built to create)
        dissolve those two electrodes into ONE connected polygon. Once
        merged, _mill_exposed_ring_edges' own self-shadowing ray-cast
        (deliberately scoped to "this ring's own connected geom" so two
        genuinely separate electrodes never shadow each other -- see its
        docstring's root-cause writeup) now sees the far electrode as
        part of that SAME geom, so a candidate edge on one slab's near
        face routinely ray-casts straight into the OTHER slab a few
        units away and comes back "shadowed" -- confirmed against a real
        cell with two large, well-separated electrode slabs bridged by a
        real finger: electrode-only union has 2 disjoint
        components (11/24 exposed segments at theta=0/180); folding in
        the real deposited finger merges them into 1 component, and
        despite candidate-edge selection finding MORE raw candidates
        (14/31) than before, the ray-cast step returns EXACTLY ZERO
        exposed segments for both thetas -- matching the "nothing shows
        up" report precisely.

        FIRST FIX ATTEMPT, found too aggressive against another real
        design before being shipped: deciding electrode-to-electrode
        connectivity from electrode_polygons ALONE and only ever growing
        each electrode component's own occluder with deposited fragments
        that DIRECTLY touch that electrode (never letting a deposited-
        only group stand on its own) silently zeroed out a different real
        design's own previously-verified deposited-sidewall highlighting
        (13 "deposited" segments -> 0) -- its real finger happens not to
        overlap electrode_polygons tightly enough to ever touch an
        electrode-anchored group directly (confirmed: its own with-
        deposited union already stayed at 15 separate small components,
        13 of them pure-deposited slivers touching no electrode fragment
        at all), so under the first attempt those 13 legitimate,
        anchor-adjacent finger slivers were dropped from consideration
        entirely rather than self-shadowed as their own valid occluder.

        The actual fix: electrode-to-electrode connectivity is still
        decided from electrode_polygons alone (that invariant must never
        move), but deposited material is otherwise folded in exactly
        like the shared engine used elsewhere (anchor-proximity seeding
        across BOTH sources, not just "touches an electrode") -- the two are
        reconciled by computing the real, honest connected-component
        partition of the FULL combined (electrode + deposited) pool
        first, then only SPLITTING a resulting piece if it actually
        spans more than one distinct electrode-only component (the
        genuine bridging case). A piece that contains zero or exactly
        one electrode component -- including a pure-deposited sliver
        that touches no electrode at all, exactly the case described
        above -- is kept exactly as the honest union already produced it, so
        that legitimate case is untouched. A piece that DOES span two or
        more electrode components (the genuine bridging case) is split back into
        one occluder per electrode component, each independently grown
        from that component's own electrode fragments plus only the
        deposited fragments that connect to IT specifically within that
        same combined piece -- a bridging fragment lands in both split
        occluders separately rather than merging them. Each returned
        geom is exactly the scope _mill_exposed_ring_edges should self-
        shadow one electrode's edges against -- callers must invoke it
        once per returned geom and concatenate (with de-duplication,
        since a bridging deposited fragment can legitimately appear, and
        get ray-cast, inside more than one split occluder).

        Omitted/empty extra_polys reproduces the exact electrode-only
        partition _touching_union_near_anchors already gave (each
        genuinely separate electrode component as its own list entry) --
        no electrode component can ever "span more than one electrode
        component", so nothing is ever split in that case. Returns [] if
        there's nothing to highlight (no anchors, or nothing near any of
        them).

        Like _mill_electrode_occluder_union, the candidate
        electrode fragments are further restricted to those a real
        finger/patch/plate feature genuinely touches/overlaps (see
        _mill_touched_electrode_fragment_indices), when this junction has
        any such real geometry to test against -- this fixes the case
        of an unrelated, untouched-but-nearby electrode fragment winning
        the search. No restriction when there is no real finger/patch/
        plate geometry at all (synthetic anchor-only test fixtures)."""
        electrode_all = [p for p in (junction.electrode_polygons or []) if len(p) >= 3]
        touched = self._mill_touched_electrode_fragment_indices(junction)
        electrode = [p for i, p in enumerate(electrode_all) if i in touched] if touched else electrode_all
        extra = [p for p in (extra_polys or []) if len(p) >= 3]
        if not anchors or (not electrode and not extra):
            return []
        n_elec = len(electrode)
        combined = electrode + extra
        prefilter_radius = local_radius_um * 4.0
        touch_buffer = 1e-3

        def build_pool(polys, offset=0):
            pool = {}
            for i, p in enumerate(polys):
                if not any(math.hypot(px - ax_, py - ay_) <= prefilter_radius
                           for px, py in p for ax_, ay_ in anchors):
                    continue
                try:
                    poly = sg.Polygon(p).buffer(0)
                    if not poly.is_empty:
                        pool[offset + i] = poly
                except Exception:
                    continue
            return pool

        def partition(pool):
            remaining = set(pool.keys())
            comps = []
            while remaining:
                seed_i = remaining.pop()
                comp = {seed_i}
                frontier = [seed_i]
                while frontier:
                    cur = frontier.pop()
                    probe = pool[cur].buffer(touch_buffer)
                    for j in list(remaining):
                        try:
                            if probe.intersects(pool[j]):
                                comp.add(j)
                                remaining.discard(j)
                                frontier.append(j)
                        except Exception:
                            continue
                comps.append(comp)
            return comps

        # Step 1 -- electrode-to-electrode connectivity, decided from
        # electrode_polygons ALONE (an invariant that must never
        # move): the genuine partition of "which fragments
        # are really one physical electrode."
        elec_pool = build_pool(electrode, offset=0)
        elec_components = partition(elec_pool)
        qualifying_elec = [comp for comp in elec_components if any(
            math.hypot(px - ax_, py - ay_) <= local_radius_um
            for i in comp for px, py in electrode[i] for ax_, ay_ in anchors)]

        # Step 2 -- the full, honest combined pool (electrode + deposited),
        # seeded by anchor proximity across BOTH sources and grown by
        # touching, exactly like the shared engine used elsewhere -- this is
        # what lets a pure-deposited sliver near an anchor stand on its
        # own even when it never touches any electrode fragment (the
        # case described in this function's own docstring).
        dep_pool = build_pool(extra, offset=n_elec)
        full_pool = dict(elec_pool)
        full_pool.update(dep_pool)
        if not full_pool:
            return []
        seed_set = {i for i in full_pool if any(
            math.hypot(px - ax_, py - ay_) <= local_radius_um for px, py in combined[i] for ax_, ay_ in anchors)}
        if not seed_set:
            return []
        group_all = set(seed_set)
        changed = True
        while changed:
            changed = False
            for i in full_pool:
                if i in group_all:
                    continue
                probe = full_pool[i].buffer(touch_buffer)
                for j in group_all:
                    try:
                        if probe.intersects(full_pool[j]):
                            group_all.add(i)
                            changed = True
                            break
                    except Exception:
                        continue
        if not group_all:
            return []

        try:
            combined_union = so.unary_union([full_pool[i] for i in group_all])
        except Exception:
            return []
        sub_geoms = list(combined_union.geoms) if hasattr(combined_union, "geoms") else [combined_union]

        # Step 3 -- for each genuinely-connected combined piece, check
        # whether it spans more than one qualifying electrode component.
        # If not (zero, e.g. pure deposited; or exactly one), it is
        # already the correct occluder as-is. If it DOES span more than
        # one -- the real bridging case -- split it back into one
        # occluder per electrode component, each grown independently.
        groups = []
        for sub in sub_geoms:
            probe_sub = sub.buffer(touch_buffer)
            spanning = [comp for comp in qualifying_elec
                        if any(elec_pool[i].intersects(probe_sub) for i in comp)]
            if len(spanning) <= 1:
                groups.append(sub)
                continue
            for comp in spanning:
                member_polys = [elec_pool[i] for i in comp]
                included_dep = set()
                changed = True
                while changed:
                    changed = False
                    current_pieces = member_polys + [full_pool[i] for i in included_dep]
                    for i in group_all:
                        if i < n_elec or i in included_dep:
                            continue
                        probe = full_pool[i].buffer(touch_buffer)
                        try:
                            if any(probe.intersects(piece) for piece in current_pieces):
                                included_dep.add(i)
                                changed = True
                        except Exception:
                            continue
                try:
                    group_union = so.unary_union(member_polys + [full_pool[i] for i in included_dep])
                    if not group_union.is_empty:
                        groups.append(group_union)
                except Exception:
                    continue
        return groups

    def _mill_exposed_ring_edges(self, union_geom, theta, tol_deg, anchors, local_radius_um, trench_union=None):
        """The REAL beam-of-light visibility model for ion-mill exposure:
        there needs to be geometry that tracks where the milling beam
        actually hits, modeled as a beam of light shining at a given alpha
        and theta, so the code can determine what gets shadowed and what
        doesn't. Replaces the old "one best-facing edge per
        polygon, all-or-nothing" selection with: find every boundary
        edge of the real, LOCAL, seam-free electrode silhouette
        (union_geom, from _mill_electrode_occluder_union) whose outward
        normal faces the beam, then sample each one finely and ray-cast
        every sample point back toward the beam source THROUGH THAT SAME
        SILHOUETTE -- a sample is exposed only if nothing else in the
        local electrode geometry sits between it and the source. Only
        the genuinely-unshadowed sub-pieces of each edge are returned, so
        a partially self-shadowed diagonal edge (matching a real report
        that the diagonal section of an electrode should be milled at
        least partially) now highlights partially
        instead of all-or-nothing.

        SIGN/ROBUSTNESS FIX, found on the same
        real design (which reported that theta=0 and theta=180 were
        milling the completely opposite side to what they should be): the
        outward normal for each edge is now derived from its own ring's
        SIGNED AREA (see
        _ring_signed_area) -- a CCW ring's outward normal is its edge
        vector rotated -90 deg, a CW ring's is +90 deg, full stop, no
        exceptions. This is a global, topological fact about the ring as
        a whole, unlike the older per-edge "flip toward/away from the
        polygon's own centroid" heuristic, which silently assumes the
        polygon is convex (or at least star-shaped from its centroid).
        A real electrode with two lobes pinched together into an
        hourglass/bowtie by a diagonal finger crossing is exactly
        the kind of concave shape that centroid-relative test gets
        backwards on for edges near the pinch, which is exactly what
        made theta=0 and theta=180 come out swapped.

        Works uniformly on every ring union_geom has -- a polygon's own
        exterior AND any interior/hole ring -- since _ring_signed_area
        gives the objectively correct rotation sign for either kind
        without needing to know which one it's looking at.

        Fix found immediately after root cause #2's fix to
        _mill_electrode_occluder_union above, against a real design with
        two separate electrodes): union_geom can now legitimately be a
        MultiPolygon of two or more genuinely SEPARATE, disjoint
        electrodes (e.g. the two real electrodes on either side of an
        actual junction barrier) -- that is the whole point of switching
        to electrode_polygons and NOT merging by distance. The ray-cast
        visibility test below is a "self-shadowing" model: does THIS
        electrode's OWN geometry block THIS electrode's OWN edge from
        the source. It must never ray-cast an edge against a DIFFERENT,
        separate electrode's geometry too -- a first pass here checked
        every ring's rays against the whole union_geom (every disjoint
        piece at once), and immediately found each electrode's own real,
        genuinely-exposed contact fillet reported as 100% shadowed by
        the OTHER electrode sitting a few nm away across the junction
        gap. Two electrodes meant to be milled/contacted independently
        (that is exactly why _mill_electrode_occluder_union keeps them
        as separate pieces instead of merging them) cannot be allowed to
        "shadow" each other here; each ring is now ray-cast only against
        the one geom it came from.

        A missing-physics gap was found on a real design where the highlight
        landed well away from the real junction crossing, on a real but
        entirely unrelated electrode edge: every ring here used to be
        scanned for exposure with no
        regard for resist at all -- an edge nowhere near any real
        finger/patch/plate trench could still win purely by facing the
        beam and sitting within `local_radius_um` of an anchor. Real
        photoresist covers the WHOLE wafer except inside each feature's
        own lithographically-opened trench, so the beam can only ever
        reach material within one of those trenches (see
        _mill_trench_union's own docstring). `trench_union` (optional,
        the real design's own trench/aperture union) is now ANDed into
        every sample point's exposure test, exactly like the existing
        self-shadowing test -- a sample only counts as exposed if it is
        BOTH geometrically unshadowed AND inside a real trench, so an
        exposed run now correctly stops right at the resist boundary
        instead of continuing onto resist-covered material just because
        nothing else happens to occlude it. `trench_union=None` (every
        pre-existing caller predating this restriction, and any synthetic/fake
        junction with no real finger/patch/plate geometry to build a
        trench from) applies no restriction at all -- byte-for-bit the
        prior behavior.

        Returns a list of (p1, p2) sub-segment tuples (possibly several
        per original edge, possibly a partial piece of one), or an empty
        list if union_geom is None or nothing qualifies."""
        if union_geom is None:
            return []
        target_normal_deg = (theta + 180.0) % 360.0
        target_rad = math.radians(target_normal_deg)
        retrace = (math.cos(target_rad), math.sin(target_rad))
        eps = 1e-3
        max_probe = max(local_radius_um * 2.0, 5.0)
        trench_buffered = trench_union.buffer(1e-3) if trench_union is not None else None

        def make_is_exposed(occluder):
            def is_exposed(pt):
                probe_start = (pt[0] + eps * retrace[0], pt[1] + eps * retrace[1])
                probe_end = (pt[0] + max_probe * retrace[0], pt[1] + max_probe * retrace[1])
                try:
                    ray = sg.LineString([probe_start, probe_end])
                    return not ray.intersects(occluder)
                except Exception:
                    return True
            return is_exposed

        geoms = list(union_geom.geoms) if hasattr(union_geom, "geoms") else [union_geom]
        rings = []
        for g in geoms:
            if not hasattr(g, "exterior") or g.exterior is None:
                continue
            rings.append((list(g.exterior.coords)[:-1], g))
            for interior in g.interiors:
                rings.append((list(interior.coords)[:-1], g))

        segments = []
        for ring, own_geom in rings:
            if len(ring) < 3:
                continue
            is_exposed = make_is_exposed(own_geom)
            area = self._ring_signed_area(ring)
            if area == 0.0:
                continue
            n = len(ring)
            for k in range(n):
                p1, p2 = ring[k], ring[(k + 1) % n]
                ex, ey = p2[0] - p1[0], p2[1] - p1[1]
                elen = math.hypot(ex, ey)
                if elen < 1e-9:
                    continue
                nx, ny = (ey, -ex) if area > 0 else (-ey, ex)
                normal_deg = math.degrees(math.atan2(ny, nx)) % 360.0
                diff = abs(((normal_deg - target_normal_deg + 180.0) % 360.0) - 180.0)
                if diff > tol_deg:
                    continue
                mx, my = (p1[0] + p2[0]) / 2.0, (p1[1] + p2[1]) / 2.0
                if not any(math.hypot(mx - ax_, my - ay_) <= local_radius_um for ax_, ay_ in anchors):
                    continue
                # Find the EXACT sub-interval(s) of this edge's
                # own [0,1] parameter range that lie inside the real trench,
                # via a genuine geometric intersection (never point-sampling
                # against a fixed grid) -- a narrow trench (a bare finger's
                # own linewidth, often far narrower than the fixed sampling
                # step this loop used to use for the whole edge) must not be
                # able to fall entirely BETWEEN two sample points and get
                # silently lost. Verified via the default 2-finger
                # junction: a finger only 0.22 units wide crossing a 1.5-
                # unit-wide electrode edge -- the old fixed-step sampling
                # (~0.4 unit steps, sized for local_radius_um, not for the
                # trench) never once landed a sample inside that trench,
                # so the genuinely-exposed sub-segment right at the real
                # contact point silently vanished to zero. trench_union
                # None keeps the whole edge as a single (0.0, 1.0) interval,
                # byte-for-bit prior behavior.
                if trench_buffered is None:
                    intervals = [(0.0, 1.0)]
                else:
                    edge_line = sg.LineString([p1, p2])
                    inter = edge_line.intersection(trench_buffered)
                    if inter.is_empty:
                        intervals = []
                    else:
                        pieces = list(inter.geoms) if hasattr(inter, "geoms") else [inter]
                        raw_intervals = []
                        for piece in pieces:
                            coords = list(getattr(piece, "coords", []))
                            if len(coords) < 2:
                                continue
                            t_a = ((coords[0][0] - p1[0]) * ex + (coords[0][1] - p1[1]) * ey) / (elen * elen)
                            t_b = ((coords[-1][0] - p1[0]) * ex + (coords[-1][1] - p1[1]) * ey) / (elen * elen)
                            lo, hi = (t_a, t_b) if t_a <= t_b else (t_b, t_a)
                            lo, hi = max(0.0, lo), min(1.0, hi)
                            if hi > lo:
                                raw_intervals.append((lo, hi))
                        raw_intervals.sort()
                        intervals = []
                        for lo, hi in raw_intervals:
                            if intervals and lo <= intervals[-1][1] + 1e-9:
                                intervals[-1] = (intervals[-1][0], max(intervals[-1][1], hi))
                            else:
                                intervals.append((lo, hi))

                for lo, hi in intervals:
                    sub_len = (hi - lo) * elen
                    n_samples = max(2, min(40, int(sub_len / max(local_radius_um * 0.01, 1e-6)) + 1))
                    ts = [lo + (hi - lo) * i / float(n_samples) for i in range(n_samples + 1)]
                    sample_pts = [(p1[0] + ex * t, p1[1] + ey * t) for t in ts]
                    exposed_flags = [is_exposed(pt) for pt in sample_pts]
                    run_start = None
                    for i, flag in enumerate(exposed_flags):
                        if flag and run_start is None:
                            run_start = i
                        elif not flag and run_start is not None:
                            if i - run_start >= 1:
                                t0, t1 = ts[run_start], ts[i]
                                segments.append(((p1[0] + ex * t0, p1[1] + ey * t0),
                                                  (p1[0] + ex * t1, p1[1] + ey * t1)))
                            run_start = None
                    if run_start is not None and len(exposed_flags) - 1 - run_start >= 1:
                        t0, t1 = ts[run_start], ts[-1]
                        segments.append(((p1[0] + ex * t0, p1[1] + ey * t0),
                                          (p1[0] + ex * t1, p1[1] + ey * t1)))
        return segments

    def _mill_highlighted_edges(self, junction, theta, tol_deg=45.0, near_bounds=None, anchors=None, local_radius_um=40.0, deposited_polys=None):
        """The REAL physical target of an ion mill: the exposed
        sidewall of the Nb ELECTRODE facing the beam -- ion milling
        exists specifically to strip the electrode's native oxide right
        before a deposition needs metal-on-metal contact with it, NOT
        to re-mill Al that's already been deposited (corrected from an
        earlier version that highlighted the currently-deposited
        finger/patch/plate shapes' own edges instead, which is
        physically backwards). Returns the single most beam-facing edge
        of each electrode_material polygon -- the actual drawn Nb metal,
        not electrode_polygons (which represent absent-space/holes used
        only for the warning math). Electrode material is pre-existing
        chamber background, not part of this recipe's own deposition
        sequence, so unlike the finger/patch/plate progressive reveal
        this is never gated by which recipe steps have run yet -- the
        electrode is physically there in the chamber from step 1.

        A later addition lets the mill also expose the sides of
        previously-deposited features -- useful for limiting how long the
        ion mill needs to run once junction fingers, and adhesion pads
        stacked up layer-by-layer, have already been deposited: the paragraph above is the physical reasoning for a mill
        happening BEFORE anything has been deposited yet -- it no longer
        tells the whole story once a design has one or more mill steps
        that occur AFTER some deposition has already happened (a real,
        common recipe shape: mill, deposit fingers, mill again to clear
        oxide off the new metal, deposit patches). At that point the ion
        beam's real physical target is whatever is CURRENTLY topmost and
        exposed -- which can now be the deposited metal's own sidewall
        (or a still-bare stretch of electrode the metal hasn't reached),
        not the pristine pre-deposition electrode alone. `deposited_polys`
        (new, optional) -- point-list polygons for material already
        deposited by this point (the Slideshow's own `upto_shapes`,
        passed straight through to `_mill_electrode_occluder_union`'s own
        `extra_polys`) -- lets the anchor-based primary path below
        account for this: the combined electrode+deposited silhouette's
        boundary is what's actually exposed, and the same self-shadowing
        ray-cast then correctly lets a raised, already-deposited feature
        (including a multi-pass adhesion pad built up layer-by-layer --
        its accumulated XY footprint by this step is all that matters for
        occlusion, not how many passes/how thick) shadow part of the
        electrode or another stacked layer behind it. Omitted or empty
        (every pre-existing caller) reproduces today's electrode-only
        behavior exactly -- this is purely additive to the anchor-based
        primary path, and has NO effect on the older near_bounds-based
        legacy fallback (still electrode_material-only, still ungated by
        deposit state, unchanged).

        A polygon edge's outward normal is the real geometric definition
        of "which side faces the beam": for each edge, rotate the edge
        vector -90 deg to get a normal, flip it if it points toward the
        polygon's own centroid rather than away from it, then compare
        that normal's compass angle against theta+180. The edge whose
        normal points most directly at theta+180 is the one the beam
        actually strikes; edges more than tol_deg off are treated as
        effectively shadowed by the electrode's own bulk and not
        highlighted.

        SIGN FIX, found against a real 2-electrode
        design (measured by hand against the actual drawn geometry, not
        just theory): the target compass direction for "which edge faces
        the beam" is theta+180, NOT theta itself. theta is the SAME
        parameter deposition uses for "the direction a feature EXTENDS
        toward" (_shadow_alignment's own convention) -- i.e. theta names
        where the METAL ends up reaching, which is the side AWAY from
        the physical source. The ion beam (and, by the same shared-theta
        convention, the evaporation source for the deposition this mill
        precedes) therefore travels FROM the theta+180 side TOWARD theta,
        striking the electrode surface it passes on its way in -- the
        surface whose outward normal points back at the source, i.e.
        toward theta+180, not the far side facing theta. Verified against
        two independent real cases: a mill at theta=0 must highlight the
        LEFT-facing (normal=180) side of both electrodes it's near, and a
        mill at theta=270 must highlight the TOP-facing (normal=90)
        side -- both are theta+180, and both were previously (wrongly)
        highlighting the theta-facing side instead, on the electrode's
        FAR side from where the following deposition actually lands.

        BUG FIX, found against a real imported design where none of the
        argon milling appeared at all: a real
        GDS import's electrode_material comes from nearby_material's own
        600um search radius (junction_import.import_gds_cell) -- easily
        a chip-scale pad/groundplane polygon spanning far more area than
        the junction itself. Scanning that WHOLE polygon for its single
        globally most-theta-facing edge, with no regard for where that
        edge actually sits, routinely picked an edge nowhere near the
        junction -- often well outside the slideshow's own view (which
        is fit tightly to the finger/patch/plate extent, not to
        electrode_material's much larger extent), so the highlight was
        being drawn but never visible. It's also physically wrong even
        when it WOULD have been visible: "the part of the electrode
        being milled" has to be the part actually near where THIS
        finger/patch will contact it, not just any edge on the same
        background polygon that happens to face theta well somewhere
        else on the chip. near_bounds (x0, x1, y0, y1) -- normally the
        slideshow's own already-fitted axis limits -- now restricts the
        search to edges genuinely near the junction first; only if a
        polygon has NOTHING in that window does this fall back to its
        globally best edge (so a real, relevant electrode still gets
        highlighted even if its best-facing edge sits just past the
        padded view), and a polygon that doesn't come near the junction
        at all (an unrelated pad/structure elsewhere on the chip) is
        skipped entirely rather than forced onto screen.

        FOLLOW-UP FIX, found against a real
        array-structure design where the fallback was wrong most of the
        time: it zoomed the screen entirely out of view of
        the junction and highlighted the entire electrode instead.
        near_bounds and the view-based fallback above are now used ONLY
        when this design offers no real electrode-contact anchors at all
        (see _mill_target_anchors) -- a synthetic/fake junction in a
        test, or a design where nothing currently crosses the electrode.
        Whenever at least one real anchor exists, candidate edges are
        restricted to those within `local_radius_um` of ONE OF THEM
        instead -- tied to actual finger/patch contact geometry, not to
        whatever the camera happens to be showing or how far a
        polygon's OWN vertices happen to wander. This is what actually
        fixes the array-structure case the view-based approach couldn't:
        a single electrode_material polygon can legitimately span an
        entire array, but only the small part of it near a real contact
        point is ever a valid mill target, regardless of what the
        camera is currently showing."""
        target_normal_deg = (theta + 180.0) % 360.0

        def candidate_edges(points):
            cx = sum(p[0] for p in points) / len(points)
            cy = sum(p[1] for p in points) / len(points)
            n = len(points)
            edges = []
            for k in range(n):
                p1, p2 = points[k], points[(k + 1) % n]
                mx, my = (p1[0] + p2[0]) / 2.0, (p1[1] + p2[1]) / 2.0
                ex, ey = p2[0] - p1[0], p2[1] - p1[1]
                nx, ny = ey, -ex  # rotate edge vector -90 deg
                if (nx * (mx - cx) + ny * (my - cy)) < 0:
                    nx, ny = -nx, -ny  # make sure it points outward, away from centroid
                if nx == 0.0 and ny == 0.0:
                    continue
                normal_deg = math.degrees(math.atan2(ny, nx)) % 360.0
                # Sign fix (see docstring) -- compare against
                # theta+180 (target_normal_deg), NOT theta itself.
                diff = abs(((normal_deg - target_normal_deg + 180.0) % 360.0) - 180.0)
                edges.append((p1, p2, mx, my, diff))
            return edges

        def best_of(edges):
            if not edges:
                return None, None
            p1, p2, _mx, _my, diff = min(edges, key=lambda e: e[4])
            return (p1, p2), diff

        if anchors is None:
            anchors = self._mill_target_anchors(junction)

        segments = []
        if anchors:
            # PRIMARY path -- a follow-up fix
            # against a real design with a complex, concave,
            # multi-fragment electrode (two lobes pinched together at a
            # diagonal neck where the fingers cross), where the highlight
            # picked out an interior shape rather than the true electrode
            # boundary, milled the wrong side at theta=0, and only
            # partially milled the diagonal section of the electrode where
            # it should have milled it fully. Three real, distinct
            # bugs in the OLD per-polygon-independent edge scan, all
            # fixed together below -- see _mill_electrode_occluder_union
            # and _mill_exposed_ring_edges for the full writeup of each:
            #   1. A real GDS electrode is routinely stored as several
            #      separate-but-touching/overlapping polygon fragments
            #      (junction_import.nearby_material never guarantees one
            #      clean silhouette per electrode). Scanning each
            #      fragment's edges independently -- the old approach --
            #      can pick an edge that is really an INTERNAL SEAM
            #      between two fragments of the SAME physical electrode,
            #      not a true electrode/substrate boundary at all. Fixed
            #      by dissolving genuinely-touching fragments into one
            #      real silhouette first (_mill_electrode_occluder_union)
            #      and only ever taking edges from ITS boundary.
            #   2. The old outward-normal test flipped a raw rotated edge
            #      normal based on which side of the polygon's OWN
            #      CENTROID it fell on -- a heuristic that only works for
            #      a convex, star-shaped-from-its-centroid polygon. A
            #      real electrode pinched into an hourglass/bowtie by a
            #      diagonal finger crossing is exactly the concave shape
            #      that heuristic gets backwards on, which is why theta=0
            #      and theta=180 milled the "completely opposite" side of
            #      what they should have. Fixed by computing the outward
            #      normal from each RING's own signed area (a global,
            #      topological property that is correct for any simple
            #      polygon regardless of concavity) instead of a local,
            #      per-edge guess relative to the centroid.
            #   3. The old algorithm always picked exactly ONE best-
            #      facing edge per polygon, all-or-nothing -- it had no
            #      concept of one part of an edge being shadowed by
            #      another part of the SAME (concave) electrode while the
            #      rest stays exposed, so a genuinely part-exposed
            #      diagonal neck edge either highlighted in full (wrong)
            #      or, if it lost the single-best-edge contest to a
            #      flatter face elsewhere, not at all (also wrong). Fixed
            #      with real
            #      directional visibility: every candidate edge is
            #      sampled finely and each sample is ray-cast back toward
            #      the beam source through the local electrode geometry
            #      itself, modeling exactly a beam of light and what
            #      gets shadowed and what doesn't -- only the
            #      genuinely-unshadowed sub-pieces are returned, so a
            #      diagonal edge can now highlight PARTIALLY, matching
            #      the real physical exposure instead of an all-or-
            #      nothing single edge.
            #   4. A REGRESSION FIX found
            #      against two more real designs, one where
            #      nothing showed up in the highlight at all and another
            #      where the highlighting appeared
            #      far below the actual junction: folding
            #      deposited material into the SAME shared flood-fill
            #      pool as the electrode could let a thin
            #      deposited finger that genuinely bridges the gap
            #      between two real, separate electrodes merge them into
            #      ONE connected polygon -- defeating fix #2/#3's own
            #      per-electrode self-shadowing scope and making every
            #      candidate edge ray-cast straight into the OTHER
            #      electrode a few units away (verified: a real two-electrode cell
            #      goes from 11/24 correctly-exposed segments at
            #      theta=0/180 with electrode alone, to EXACTLY ZERO once
            #      the real bridging finger is folded in the old way,
            #      despite MORE raw candidates being found first). Fixed
            #      by _mill_electrode_occluder_groups: electrode-to-
            #      electrode connectivity is decided from electrode_
            #      polygons alone, and deposited
            #      material only ever GROWS one already-decided electrode
            #      component's own occluder -- a bridging fragment is
            #      included in both components separately rather than
            #      merging them. Each group self-shadows independently,
            #      and results are de-duplicated since a bridging
            #      fragment's own edges can legitimately appear (and get
            #      ray-cast, with the same result either time) inside
            #      more than one group.
            if deposited_polys:
                seen_keys = set()
                for group_geom in self._mill_electrode_occluder_groups(junction, anchors, local_radius_um,
                                                                        extra_polys=deposited_polys):
                    for seg in self._mill_exposed_ring_edges(group_geom, theta, tol_deg, anchors, local_radius_um):
                        (x1, y1), (x2, y2) = seg
                        key = tuple(sorted([(round(x1, 6), round(y1, 6)), (round(x2, 6), round(y2, 6))]))
                        if key in seen_keys:
                            continue
                        seen_keys.add(key)
                        segments.append(seg)
            else:
                union_geom = self._mill_electrode_occluder_union(junction, anchors, local_radius_um)
                segments.extend(self._mill_exposed_ring_edges(union_geom, theta, tol_deg, anchors, local_radius_um))
        else:
            for poly_pts in (junction.electrode_material or []):
                if len(poly_pts) < 3:
                    continue
                edges = candidate_edges(poly_pts)
                if near_bounds is not None:
                    x0, x1, y0, y1 = near_bounds
                    nearby = [e for e in edges if x0 <= e[2] <= x1 and y0 <= e[3] <= y1]
                    if nearby:
                        edge, diff = best_of(nearby)
                    else:
                        # No edge of this polygon falls inside the current
                        # view at all -- only fall back to its globally best
                        # edge if the polygon comes near the view in the
                        # first place (any vertex within a margin around it);
                        # a polygon that's nowhere near the junction (e.g. a
                        # separate bond pad elsewhere on the chip) is skipped
                        # outright rather than highlighted off-screen.
                        mx_span, my_span = (x1 - x0), (y1 - y0)
                        mx0, mx1 = x0 - mx_span, x1 + mx_span
                        my0, my1 = y0 - my_span, y1 + my_span
                        touches_view = any(mx0 <= px <= mx1 and my0 <= py <= my1 for px, py in poly_pts)
                        edge, diff = best_of(edges) if touches_view else (None, None)
                else:
                    edge, diff = best_of(edges)
                if edge is not None and diff is not None and diff <= tol_deg:
                    segments.append(edge)

        # FIX, made to ensure ion milling highlights
        # on the electrodes always show up for any design: a real GDS import's
        # electrode_material can sit entirely outside the tightly-fit
        # junction view -- not just "close but past the padding" (the
        # touches_view margin above already covers that), but genuinely
        # a bit farther out (a real electrode whose contact point sits
        # just past the padded junction crop). When that happens for
        # EVERY polygon, the loop above returns nothing at all, and every
        # mill step for that design silently shows no highlight, ever.
        #
        # REGRESSION FOUND AND FIXED, found on a follow-up
        # check against real geometry where the fallback failed to detect
        # the sides of the electrode nearest the junction: the first
        # version of this fallback fell back to EVERY polygon in
        # electrode_material with no distance gate at all -- more
        # permissive than even the touches_view check above. A real GDS
        # import's electrode_material comes from a 600um-radius sweep
        # (junction_import.nearby_material) and routinely contains many
        # DISJOINT fragments -- other bond pads, ground plane pieces,
        # neighboring structures on the same chip -- most of them
        # unrelated to this specific junction. Accepting one edge from
        # EVERY fragment that happened to face roughly the right way lit
        # up several disconnected, unrelated shapes at once, and the
        # caller's view-widening (unioned across all of them) had to
        # stretch to cover all those scattered points simultaneously --
        # collapsing the actual tiny junction down to unreadable slivers.
        # The fix keeps
        # this a bounded, LOCAL fallback -- only consider a polygon that
        # has at least one vertex within a few view-widths of the
        # already-fitted junction view (generous enough to reach a real
        # electrode whose contact point sits just past the padding, but
        # nowhere near "anywhere on the whole chip"), and among those,
        # keep only the SINGLE nearest one (by centroid distance to the
        # view's own center) -- never more than one fallback edge. A
        # design where nothing at all qualifies now shows no highlight
        # for that step rather than a misleading, badly-scaled one.
        if not anchors and near_bounds is not None and not segments:
            x0, x1, y0, y1 = near_bounds
            cx, cy = (x0 + x1) / 2.0, (y0 + y1) / 2.0
            far_span_x, far_span_y = (x1 - x0), (y1 - y0)
            far_margin_x = max(far_span_x, 1e-9) * 3.0
            far_margin_y = max(far_span_y, 1e-9) * 3.0
            fx0, fx1 = x0 - far_margin_x, x1 + far_margin_x
            fy0, fy1 = y0 - far_margin_y, y1 + far_margin_y
            best_edge, best_diff, best_dist = None, None, None
            for poly_pts in (junction.electrode_material or []):
                if len(poly_pts) < 3:
                    continue
                touches_far_view = any(fx0 <= px <= fx1 and fy0 <= py <= fy1 for px, py in poly_pts)
                if not touches_far_view:
                    continue
                edge, diff = best_of(candidate_edges(poly_pts))
                if edge is None or diff is None or diff > tol_deg:
                    continue
                pcx = sum(p[0] for p in poly_pts) / len(poly_pts)
                pcy = sum(p[1] for p in poly_pts) / len(poly_pts)
                dist = math.hypot(pcx - cx, pcy - cy)
                if best_dist is None or dist < best_dist:
                    best_edge, best_diff, best_dist = edge, diff, dist
            if best_edge is not None:
                segments.append(best_edge)
        return segments

    def _mill_trench_exposed_region(self, points, theta, dx_um, dy_um):
        """A COMPLETE REMODEL of ion-mill exposure so that ion
        milling behaves the same way as the shadow
        simulation: at the given alpha and theta, the parts within
        the trenches of the junction design that the mill's own beam
        actually touches are computed with the same shadow-simulation
        geometry, just with a few tweaks. Instead of deleting material
        like a deposition step does, the red-hatched areas just show
        where the light doesn't touch for ion milling, and any blue-
        hatched area that a deposition step would fill in with
        material instead simply gets highlighted -- so if the same
        alpha and theta are used in a patch deposition step as in the
        ion milling step, the milling highlight touches the
        exact same locations which the deposition of the patches
        touches.

        Given ANY trench polygon (a finger/patch/plate's own drawn
        `.points` -- the same litho-opened aperture already
        established as the only place a beam can ever reach at all),
        reuses the EXACT SAME directional shrink/extend shadow model a
        deposition pass already uses on that same polygon
        (_shadow_alignment / _scaled_shadow_depth / _compute_shadowed_
        polygon / _apply_cross_axis_shadow) -- so a mill run at the same
        (theta, dx_um, dy_um) as a real deposition pass touches the
        IDENTICAL physical area that pass would deposit metal onto, by
        construction, not by coincidence.

        The trench's own long axis is derived from its own minimum
        rotated bounding rectangle's longer edge pair (see the
        note below for why the more obvious "farthest-apart vertex
        pair" is NOT reliable here) -- works uniformly for a finger, a
        patch, or a plate's own drawn polygon, with no per-feature-type
        stub/patch-end convention needed (unlike the deposition engine's
        own finger-specific stub_end/patch_end, which doesn't exist for
        a patch/plate). One tip end and one long edge (whichever theta
        points AWAY from -- see _shadow_alignment) SHRINK, matching a
        deposition pass's own "red hatch" self-shadowed side: the trench
        wall on the source (theta+180) side blocks the SAME beam
        entering at the SAME shallow angle, so nothing here is reached
        either. The opposite tip end and edge (theta points TOWARD them)
        EXTEND, matching "blue hatch": the beam reaches all the way to,
        and past, this side's own nominal edge, exactly like the SAME
        pass's own deposition "overspray" would (see the note
        below on why this is deliberately NOT clipped back to the
        nominal trench polygon -- doing so broke byte-for-bit agreement
        with the deposition engine's own shape at the same angle).

        alpha=0 (a top/blanket mill) needs no special case at all: dx_um
        and dy_um are both exactly 0 at alpha=0 (compute_overlap_shadow_
        bounds' own tan(alpha) formula), so every shrink/extend depth
        below computes to 0 and the ENTIRE nominal trench polygon comes
        back exposed automatically -- one single continuous model for
        any alpha from 0-360 and any theta from 0-360, not a separate
        "top mill" branch.

        Returns a shapely Polygon/MultiPolygon of the exposed sub-region
        (possibly the whole trench, at alpha=0 or when theta is exactly
        perpendicular to a genuinely shadow-immune axis), or None if
        `points` is degenerate or theta shadows the ENTIRE trench (a
        real possibility at a large alpha close to grazing incidence,
        exactly mirroring how a deposition pass can fail to bridge an
        entire linewidth at extreme angles -- see _apply_cross_axis_
        shadow's own docstring)."""
        if not points or len(points) < 3:
            return None
        try:
            trench_poly = sg.Polygon(points).buffer(0)
        except Exception:
            return None
        if trench_poly.is_empty:
            return None
        # BUG, fixed here (found via a direct cross-check
        # against a real finger's own deposition shadow, this feature's own
        # central verification test): the trench's own long axis is NOT
        # reliably the direction between its two farthest-apart VERTICES
        # -- for a thin elongated rectangle (any real finger/patch
        # linewidth), the DIAGONAL corner-to-corner distance is very
        # slightly longer than the true long-edge distance (e.g. a
        # 5x0.2 finger's diagonal is sqrt(5^2+0.2^2)=5.004 vs the long
        # edge's own 5.0), so a farthest-pair search silently picks the
        # diagonal and rotates the whole shrink/extend axis a hair off
        # true -- enough to measurably diverge from the SAME finger's
        # own deposition-engine shadow at the same angle (confirmed:
        # dropped a direct IoU check from ~1.0 to ~0.72). Fixed by
        # deriving the axis from the polygon's own minimum ROTATED
        # bounding rectangle instead -- its longer pair of parallel
        # edges is, by construction, the shape's true long axis for any
        # elongated polygon, thin or not, with no diagonal artifact.
        try:
            mrr = trench_poly.minimum_rotated_rectangle
            mrr_coords = list(mrr.exterior.coords)
            if len(mrr_coords) >= 5:
                mrr_coords = mrr_coords[:-1]
        except Exception:
            mrr_coords = []
        axis_hat = None
        if len(mrr_coords) == 4:
            e1 = (mrr_coords[1][0] - mrr_coords[0][0], mrr_coords[1][1] - mrr_coords[0][1])
            e2 = (mrr_coords[2][0] - mrr_coords[1][0], mrr_coords[2][1] - mrr_coords[1][1])
            l1, l2 = math.hypot(*e1), math.hypot(*e2)
            if max(l1, l2) > 1e-9:
                axis_hat = (e1[0] / l1, e1[1] / l1) if l1 >= l2 else (e2[0] / l2, e2[1] / l2)
        if axis_hat is None:
            # Degenerate minimum-rotated-rectangle (shouldn't normally
            # happen for a valid polygon) -- fall back to the simpler
            # farthest-vertex-pair heuristic rather than failing outright.
            best_pair, best_d = None, -1.0
            n = len(points)
            for i in range(n):
                for j in range(i + 1, n):
                    d = math.hypot(points[i][0] - points[j][0], points[i][1] - points[j][1])
                    if d > best_d:
                        best_d = d
                        best_pair = (points[i], points[j])
            if best_pair is None or best_d < 1e-9:
                return None
            pa, pb = best_pair
            axis_hat = ((pb[0] - pa[0]) / best_d, (pb[1] - pa[1]) / best_d)
        centroid = trench_poly.centroid
        cx, cy = centroid.x, centroid.y
        projs = [(p[0] - cx) * axis_hat[0] + (p[1] - cy) * axis_hat[1] for p in points]
        t_min, t_max = min(projs), max(projs)
        if (t_max - t_min) < 1e-9:
            return None
        end_a = (cx + axis_hat[0] * t_min, cy + axis_hat[1] * t_min)
        end_b = (cx + axis_hat[0] * t_max, cy + axis_hat[1] * t_max)
        align_b = self._shadow_alignment(axis_hat, theta)
        depth_b, extend_b = self._scaled_shadow_depth(dx_um, dy_um, align_b)
        depth_a, extend_a = self._scaled_shadow_depth(dx_um, dy_um, -align_b)
        new_pts = self._compute_shadowed_polygon(points, end_a, end_b, depth_a, extend_a, depth_b, extend_b)
        new_pts = self._apply_cross_axis_shadow(new_pts, axis_hat, [theta], dx_um, dy_um)
        if new_pts is None:
            return None
        # Verified via this feature's own central verification
        # test (a direct IoU comparison against the SAME finger's real
        # deposition shadow at the SAME angle): an earlier version of
        # this function intersected `new_pts` back against the nominal
        # trench polygon before returning it, on the reasoning that a
        # beam can never reach outside the litho-opened window. That
        # over-corrects -- the deposition engine's OWN shadow model
        # (_compute_shadowed_polygon/_apply_cross_axis_shadow) does NOT
        # clip its own "extend" side back to the nominal footprint
        # either (real overspray is allowed to sit slightly past the
        # nominal drawn edge, still within the same open aperture, e.g.
        # reaching into an adjoining patch/plate's own trench at a real
        # finger-to-plate seam), so clipping only on the MILL side broke
        # the explicit litmus test that a milling highlight
        # should touch the exact same locations which the deposition of
        # the patches touches -- confirmed directly: IoU dropped to
        # ~0.81 purely from this extra clip, on a perfectly ordinary,
        # non-extreme (alpha=10, theta=15) synthetic case. Returning
        # `new_pts` unclipped, exactly like the deposition engine
        # already does, restores byte-for-bit-equivalent geometry
        # between a mill and a deposition pass run at the same angle.
        try:
            exposed = sg.Polygon(new_pts).buffer(0)
        except Exception:
            return None
        return None if exposed.is_empty else exposed

    def _mill_electrode_shadow_gate(self, junction, feature_points, theta_deg):
        """A follow-up to the ion-mill exposure remodel: the electrode-edge
        shadowing physics needs to be applied to the
        ion milling as well, because the electrode edge creates a
        shadow where the argon atoms/light are not able to reach.
        The deposition engine already models this exact mechanism
        (_compute_electrode_shadow_region / _electrode_shadow_strip /
        compute_electrode_shadow -- the electrode's own physical HEIGHT,
        not the resist-stack overlap shadow, blocking flux from reaching
        the substrate immediately past its own step edge), but every
        existing call site only ever applies it when this feature's own
        theta is on the "risky" side of its stub/patch axis (align<0) --
        "when theta is safe, the feature travels uphill onto the
        electrode and this mechanism doesn't apply at all"
        (_electrode_shadow_addon_um's own docstring). _electrode_shadow_
        strip itself doesn't encode that distinction: it always forces
        its shadow band onto the substrate side regardless of which way
        theta actually points, so calling it unconditionally for milling
        would carve a shadow gap even in the "safe"/uphill direction
        where physically none exists.

        This generalizes that SAME condition to any trench (finger,
        patch, or plate -- milling has no stub/patch-end convention to
        reuse) using only the real crossing-line geometry: find the
        electrode/substrate crossing line, probe which side is
        genuinely `electrode_polygons` (not just assumed), and check
        whether theta's own direction points from the electrode side
        toward the substrate side -- the same "beam arrives already
        past the step, casting a shadow on the low ground it just
        crossed" condition align<0 encodes for a finger's own patch
        axis, just derived directly from geometry instead. Returns False
        (no shadow) whenever the feature doesn't cross the electrode at
        all, or theta points the other way (the "uphill"/safe
        direction)."""
        edge = self._find_electrode_crossing_line(junction, feature_points)
        if edge is None:
            return False
        p1, p2 = edge
        edge_vec = (p2[0] - p1[0], p2[1] - p1[1])
        edge_len = math.hypot(*edge_vec)
        if edge_len < 1e-9:
            return False
        eu = (edge_vec[0] / edge_len, edge_vec[1] / edge_len)
        edge_mid = ((p1[0] + p2[0]) / 2.0, (p1[1] + p2[1]) / 2.0)
        perp = (-eu[1], eu[0])
        try:
            electrode_union = sg.MultiPolygon(
                [sg.Polygon(p) for p in junction.electrode_polygons if len(p) >= 3]).buffer(0)
        except Exception:
            electrode_union = None
        probe_dist = max(edge_len * 0.1, 0.01)
        probe_plus = (edge_mid[0] + perp[0] * probe_dist, edge_mid[1] + perp[1] * probe_dist)
        try:
            plus_is_electrode = electrode_union is not None and electrode_union.contains(sg.Point(probe_plus))
        except Exception:
            plus_is_electrode = False
        substrate_dir = (-perp[0], -perp[1]) if plus_is_electrode else perp
        theta_rad = math.radians(theta_deg)
        theta_hat = (math.cos(theta_rad), math.sin(theta_rad))
        return (theta_hat[0] * substrate_dir[0] + theta_hat[1] * substrate_dir[1]) > 1e-9

    def _mill_exposure_regions(self, junction, theta, dx_um, dy_um, alpha=None):
        """For EVERY finger and EVERY other_shape (patch/
        plate) in this design -- never gated by whether it has actually
        been deposited yet by this recipe step, since the resist stays
        open there from day one regardless, and every feature stays
        exposed to possible milling damage until it's actually covered --
        computes the
        sub-region of its OWN trench a mill beam at (theta, dx_um,
        dy_um) actually reaches, via _mill_trench_exposed_region. This
        naturally covers exposure on top of already-deposited features
        (like the fingers/adhesion plates) too, with no separate deposited-
        material code path needed at all: the exposed sub-region is
        purely a function of the trench's own geometry and the beam
        direction, identical whether the trench floor is still bare
        electrode or already has metal sitting in it, since oxide forms
        on (and gets milled off) either one.

        After computing the raw trench-shadow exposed region,
        also subtracts the electrode's OWN topology shadow (see
        _mill_electrode_shadow_gate's docstring) whenever this trench
        genuinely crosses the electrode boundary AND theta is on the
        risky/downhill side of that crossing -- no hatching, just an
        empty shadow where the milling does not hit, reusing
        _compute_electrode_shadow_region exactly as deposition already
        does, at the mill step's own (theta, alpha). `alpha=None` (the
        older call signature) skips this entirely, matching every
        existing caller/test that predates the electrode-shadow gate.

        Returns a list of (feature, region) pairs, omitting any feature
        whose trench is fully self-shadowed at this angle (region is
        None) or has no usable `.points` at all."""
        results = []
        fingers = getattr(junction, "fingers", None) or []
        other_shapes = getattr(junction, "other_shapes", None) or []
        for feat in list(fingers) + list(other_shapes):
            pts = getattr(feat, "points", None)
            if not pts or len(pts) < 3:
                continue
            region = self._mill_trench_exposed_region(pts, theta, dx_um, dy_um)
            if region is None:
                continue
            if alpha is not None and self._mill_electrode_shadow_gate(junction, pts, theta):
                try:
                    shadow_region = self._compute_electrode_shadow_region(junction, pts, theta, alpha)
                except Exception:
                    shadow_region = None
                if shadow_region is not None and not shadow_region.is_empty:
                    try:
                        region = region.difference(shadow_region.buffer(0.002, join_style=2))
                    except Exception:
                        pass
                    if region is None or region.is_empty:
                        continue
            results.append((feat, region))
        return results

    def _mill_electrode_edges_in_region(self, junction, region):
        """The ONE piece of the old ion-mill logic kept from the earlier
        angle-based approach: within the area of the trench that gets
        filled by the milling light, there still needs to be detection and
        a highlight of the side of the electrode within the trench and
        within the region the milling zone covers -- edge detection
        between the substrate and the edge of the electrode.

        Far simpler than the old angle-based search it replaces (no
        beam-facing-normal test, no self-shadowing ray-cast): `region`
        (an already-computed mill-exposed sub-region of one trench, from
        _mill_trench_exposed_region) already IS the beam-reachable area
        by construction, so any real electrode boundary that falls
        inside it is automatically the edge the beam strikes -- this
        just clips junction.electrode_polygons' own boundary down to
        wherever it overlaps `region`.

        Returns a list of shapely LineString/MultiLineString pieces
        (possibly empty, when no electrode boundary passes through this
        particular trench's exposed region at all)."""
        pieces = []
        for poly_pts in (getattr(junction, "electrode_polygons", None) or []):
            if len(poly_pts) < 3:
                continue
            try:
                epoly = sg.Polygon(poly_pts).buffer(0)
            except Exception:
                continue
            if epoly.is_empty or not epoly.intersects(region):
                continue
            try:
                clipped = epoly.boundary.intersection(region)
            except Exception:
                continue
            if not clipped.is_empty:
                pieces.append(clipped)
        return pieces

    def _slideshow_draw_mill_highlight(self, ax, junction, report, step, upto_shapes):
        """A COMPLETE REMODEL of the ion-mill highlight (see
        _mill_trench_exposed_region's own docstring for the physical
        reasoning this implements). Every earlier version of this feature
        searched for a single beam-facing
        ELECTRODE edge by outward-normal angle and self-shadowing ray-
        cast, entirely independent of the deposition engine's own
        directional shadow-throw math -- confirmed to still
        be the wrong model even after the fragment-identity fix:
        it could only ever find electrode material (no way to represent
        milling already-deposited metal), it searched by angle/
        proximity rather than genuine trench-bounded reach, and it could
        still land on a real but physically-unreachable part of the
        electrode. That entire angle-based search (_mill_target_anchors,
        _mill_highlighted_edges, _mill_electrode_occluder_union/_groups,
        _mill_exposed_ring_edges, _mill_touched_electrode_fragment_
        indices) is no longer called from here -- left in the file only
        because existing unit tests still exercise it directly; it is
        dead code from this function's own perspective now.

        Three visual layers:
          1. A faint, CONSTANT wash over the entire current view --
             the milling cannot just do its shadowing in the patch
             trench region; even on top of the EBeam resist, the
             entire screen should be the semi-opaque orange of the
             milling light too. Present at every alpha/theta, even
             where nothing else below has anything to highlight.
          2. Each trench's own mill-exposed sub-region (_mill_exposure_
             regions), filled more strongly than layer 1 -- the blue
             hatch that would otherwise be filled with metal is
             instead highlighted, for every finger/patch/plate in the
             whole design.
          3. The electrode-edge-within-the-exposed-region lines
             (_mill_electrode_edges_in_region), drawn brightest and
             thickest of all with a soft glow halo, for maximum
             visibility.

        Needs no anchors, no local_radius_um, and no widening of the
        already-fitted view at all: every region and edge piece drawn
        here is derived from some trench's own nominal polygon (plus, at
        most, the same small alpha-scaled "extend" overspray a real
        deposition pass at this angle would also produce -- see
        _mill_trench_exposed_region's own note on why that is
        deliberately NOT clipped back to the nominal footprint), and the
        view is already fit to the complete finger/patch/plate extent by
        _fit_shadow_axes just before this runs -- so the
        junction stays at 100% of the view exactly as requested, with no
        risk of a highlight landing outside what's already shown."""
        from matplotlib.patches import Rectangle

        xlim, ylim = ax.get_xlim(), ax.get_ylim()
        ax.add_patch(Rectangle((xlim[0], ylim[0]), xlim[1] - xlim[0], ylim[1] - ylim[0],
                                facecolor=WARN_COLOR, edgecolor="none", alpha=0.13, zorder=2))
        ax.set_xlim(xlim)
        ax.set_ylim(ylim)

        alpha = step.alpha if step.alpha is not None else 0.0
        theta = step.theta if step.theta is not None else 0.0
        try:
            pmma_nm = float(self.pmma_edit.text()) if hasattr(self, "pmma_edit") else 875.0
        except ValueError:
            pmma_nm = 875.0
        try:
            pmgi_nm = float(self.pmgi_edit.text()) if hasattr(self, "pmgi_edit") else 600.0
        except ValueError:
            pmgi_nm = 600.0
        dx_um, dy_um = self._shadow_dxdy(pmma_nm, pmgi_nm, alpha)

        def _polygon_rings(geom):
            if geom is None or geom.is_empty:
                return
            geoms = list(geom.geoms) if hasattr(geom, "geoms") else [geom]
            for g in geoms:
                if hasattr(g, "exterior") and g.exterior is not None:
                    yield list(g.exterior.coords)

        def _line_pieces(geom):
            if geom is None or geom.is_empty:
                return
            geoms = list(geom.geoms) if hasattr(geom, "geoms") else [geom]
            for g in geoms:
                coords = list(getattr(g, "coords", []))
                if len(coords) >= 2:
                    yield coords

        # A blanket mill on
        # the top at alpha = 0 doesn't actually hit the sides of
        # the electrode -- the highlighting of the electrode side is
        # specifically meant for the angles that mill the sides. A top
        # mill does not do that. A purely vertical beam (dx_um and
        # dy_um both ~0, which is what alpha=0/180/360 etc already
        # collapse to via _shadow_dxdy's own tan(alpha) formula) can
        # never strike a vertical sidewall at all -- the electrode-edge
        # highlight (layer 3) is gated on there being some real tilt-
        # driven throw to speak of; a pure top mill still gets its
        # trench-exposure fill (layer 2, the top surfaces genuinely do
        # get hit) but never the sidewall-specific edge line.
        sidewall_capable = abs(dx_um) > 1e-9 or abs(dy_um) > 1e-9

        edge_pieces = []
        for _feat, region in self._mill_exposure_regions(junction, theta, dx_um, dy_um, alpha=alpha):
            for ring in _polygon_rings(region):
                poly = MplPolygon(ring, closed=True, facecolor=WARN_COLOR, edgecolor=WARN_COLOR,
                                  linewidth=1.2, alpha=0.5, zorder=6)
                ax.add_patch(poly)
            # CORRECTED (an earlier "fix" here was
            # reverted -- it was never a bug): edge detection uses this
            # SAME electrode-shadow-adjusted `region`, not a raw pre-
            # subtraction one. If the electrode's own topology shadows
            # this part of the trench at this angle, the beam genuinely
            # never reaches the electrode there either -- when the
            # shadowing exists from the electrode step, the electrode is
            # not being hit by the milling, and thus it shouldn't be
            # highlighted. A crossing edge sitting exactly on the
            # boundary of the shadowed area correctly stops appearing;
            # that's the model working as intended, not a dropped
            # highlight.
            if sidewall_capable:
                edge_pieces.extend(self._mill_electrode_edges_in_region(junction, region))

        for edge_geom in edge_pieces:
            for coords in _line_pieces(edge_geom):
                xs = [c[0] for c in coords]
                ys = [c[1] for c in coords]
                ax.plot(xs, ys, color=MILL_EDGE_HIGHLIGHT_COLOR, linewidth=9.0, alpha=0.22,
                        solid_capstyle="round", zorder=8)
                ax.plot(xs, ys, color=MILL_EDGE_HIGHLIGHT_COLOR, linewidth=3.5, alpha=0.95,
                        solid_capstyle="round", zorder=9)

    def _mill_history_shade(self, covered):
        """Derives the "still exposed" (lighter) vs "since
        covered by later deposition" (darker) undertone shade from the
        ONE dedicated MILL_HISTORY_COLOR hue, via the same HLS-lightness
        interpolation _thickness_to_color already uses for kind-based
        shading -- so the two variants always read as the same hue
        family, just a small step apart, and
        neither is a hardcoded second color that could drift from the
        first."""
        r, g, b = (int(MILL_HISTORY_COLOR[i:i + 2], 16) / 255.0 for i in (1, 3, 5))
        h, l, s = colorsys.rgb_to_hls(r, g, b)
        new_l = min(0.95, l + 0.12) if not covered else max(0.05, l - 0.16)
        nr, ng, nb = colorsys.hls_to_rgb(h, new_l, s)
        return "#{:02x}{:02x}{:02x}".format(int(round(nr * 255)), int(round(ng * 255)), int(round(nb * 255)))

    def _slideshow_draw_mill_history(self, ax, junction, upto_shapes):
        """An explicit follow-up to the mill remodel: a subtle way to see
        where the milling hit in every deposition step after the
        milling, without dominating the screen or the shadowing
        or the deposition step logic -- a subtle
        undertone that shows where the oxides were stripped vs.
        where the patches landed, with a slight
        difference in color when the milling is still on the top layer
        vs when the milling location has been covered in deposited
        metal: the milling-exposed region is a touch lighter
        than the covered milling region, which is slightly
        darker to look as if it is covered, and neither shade matches any
        color already used for another feature.

        Unlike _slideshow_draw_mill_highlight (called ONLY while the
        currently-viewed step IS a mill step, and deliberately bold/
        attention-grabbing), this is called on EVERY "post" view render
        regardless of the current step's own category, and only ever
        draws a faint, low-alpha tint -- the CUMULATIVE union of every
        mill step's own exposure UP TO AND INCLUDING the current step,
        split into two sub-regions by comparing against `upto_shapes`
        (the real deposited geometry visible so far, exactly the same
        progressively-revealed set _draw_shadow_shapes just rendered):
        the part still bare (not yet covered by any later deposition)
        gets the LIGHTER shade, the part some later pass has since
        covered gets the DARKER shade. Before any mill step has occurred
        yet, this draws nothing at all -- there is no history to show.

        Reuses _mill_exposure_regions at each historical mill step's own
        (theta, alpha) -- the SAME geometry _slideshow_draw_mill_highlight
        itself uses for that step's own layer 2 -- so this is guaranteed
        to agree with what that step's own highlight showed while it was
        the active step, never a separately-derived approximation."""
        steps = getattr(self, "_slideshow_steps", None) or []
        if not steps:
            return
        i = max(0, min(getattr(self, "_slideshow_index", 0), len(steps) - 1))
        mill_steps_so_far = [s for s in steps[:i + 1] if getattr(s, "category", None) == "mill"]
        if not mill_steps_so_far:
            return
        try:
            pmma_nm = float(self.pmma_edit.text()) if hasattr(self, "pmma_edit") else 875.0
        except ValueError:
            pmma_nm = 875.0
        try:
            pmgi_nm = float(self.pmgi_edit.text()) if hasattr(self, "pmgi_edit") else 600.0
        except ValueError:
            pmgi_nm = 600.0
        mill_polys = []
        for mstep in mill_steps_so_far:
            m_alpha = mstep.alpha if mstep.alpha is not None else 0.0
            m_theta = mstep.theta if mstep.theta is not None else 0.0
            m_dx, m_dy = self._shadow_dxdy(pmma_nm, pmgi_nm, m_alpha)
            for _feat, region in self._mill_exposure_regions(junction, m_theta, m_dx, m_dy, alpha=m_alpha):
                if region is not None and not region.is_empty:
                    mill_polys.append(region)
        if not mill_polys:
            return
        try:
            mill_union = mill_polys[0] if len(mill_polys) == 1 else so.unary_union(mill_polys)
        except Exception:
            return
        if mill_union is None or mill_union.is_empty:
            return
        deposited_polys = []
        for pts, _kind, _fi, _th, _gid, _ghost in (upto_shapes or []):
            if not pts or len(pts) < 3:
                continue
            try:
                p = sg.Polygon(pts).buffer(0)
            except Exception:
                continue
            if not p.is_empty:
                deposited_polys.append(p)
        covered_region, exposed_region = None, mill_union
        if deposited_polys:
            try:
                deposited_union = deposited_polys[0] if len(deposited_polys) == 1 else so.unary_union(deposited_polys)
                covered_region = mill_union.intersection(deposited_union)
                exposed_region = mill_union.difference(deposited_union)
            except Exception:
                covered_region, exposed_region = None, mill_union

        def _rings(geom):
            if geom is None or geom.is_empty:
                return
            geoms = list(geom.geoms) if hasattr(geom, "geoms") else [geom]
            for g in geoms:
                if hasattr(g, "exterior") and g.exterior is not None:
                    yield list(g.exterior.coords)

        # Subtle, deliberately low-alpha fills with no outline stroke at
        # all -- an undertone, not a highlight.
        #
        # Bug found and fixed while verifying this against a
        # real design's screenshot (nothing visible at all, even though
        # the correct patches were genuinely being added to the axes):
        # _draw_shadow_shapes draws every deposited shape's own fill at
        # zorder=5 with alpha=1.0 (fully OPAQUE) -- an overlay at
        # zorder=4 is BELOW that opaque fill and therefore completely
        # hidden by it, invisible over any already-deposited region
        # (exactly the "covered" case this function exists to show).
        # zorder=5.5 sits strictly above the deposited fills (still
        # showing as a visible tint even over opaque metal) and strictly
        # below _slideshow_draw_mill_highlight's own layer 2/3 (zorder
        # 6/8/9) for whichever step is currently a mill step, so the two
        # never visually compete.
        for ring in _rings(exposed_region):
            ax.add_patch(MplPolygon(ring, closed=True, facecolor=self._mill_history_shade(covered=False),
                                     edgecolor="none", alpha=0.16, zorder=5.5))
        if covered_region is not None:
            for ring in _rings(covered_region):
                ax.add_patch(MplPolygon(ring, closed=True, facecolor=self._mill_history_shade(covered=True),
                                         edgecolor="none", alpha=0.16, zorder=5.5))

    def _draw_sim_shadow_visualization(self, ax, junction, report, theta_provider=None):
        """The ACTUAL shadow effect at the currently active angles (not
        the worst-case envelope the numeric risk check above shows).

        Corrections made here, based on feedback on a
        real design:
        1. Each finger has TWO ends -- the crossing/stub side AND its
           own tip/patch side -- and BOTH experience a shift from the
           SAME deposition step (one shrinks, the other extends). The
           previous version only drew a band at the stub end, leaving
           the tip end looking untouched even though the same
           deposition necessarily affects it too.
        2. Patches routinely need TWO SEPARATE deposition passes (one
           per finger's patch group, e.g. 0 deg and 180 deg) since they
           share one physical layer -- confirmed directly via
           compute_recommended_angles' own "patches" entry. That means
           EVERY patch receives metal from BOTH passes, not just "its
           own" angle, so both passes' shadow contributions are drawn
           at both ends of every patch, deliberately allowed to overlap
           rather than picking just one.

        theta_provider: optional ShadowThetaProvider
        that overrides which thetas get used at the three places this
        function resolves them (finger tip/stub ends, patches, plates),
        WITHOUT touching anything downstream of that resolution --
        alignment, depth, band drawing, cross-axis bands, and the
        electrode-crossing parallelogram are already fully generic and
        don't care whether a theta is "this feature's own" or a foreign
        one. Added for the Deposition Slideshow's new Shadow Sim view
        (see _slideshow_draw_shadow_sim_view), which needs every
        already-introduced feature's shadow re-evaluated against EVERY
        deposition step's theta in the whole recipe so far, not just the
        step(s) originally generated for that specific feature -- see
        that function's own docstring for the physical reasoning
        (one continuous evaporation exposes the whole open wafer, so an
        already-patterned aperture is exposed to every deposition step,
        not just the one 'intended' for it). theta_provider=None (every
        pre-existing caller: the Simulate tab's two call sites) preserves
        this function's exact prior behavior bit for bit -- confirmed via
        a dedicated regression test.

        BUG FIX (the exact scenario
        reproduced: raising alpha for just the
        patch depositions, theta unchanged, changed literally nothing
        anywhere -- including here, the "Simulated Design" annotation
        view): every finger/patch/plate axial and cross-axis band below
        used to be computed from ONE shared (dx_um, dy_um), derived from
        ONE shared alpha, for every active pass -- now each resolves its
        OWN per-pass dx/dy from run["theta_a_alphas"]/["theta_b_alphas"]/
        patch_alphas_override (falling back to the shared alpha for any
        pass without its own override), via the same _resolve_pass_dxdy_
        list helper the real Post-Shadow Result geometry uses, so this
        annotation view can never silently drift out of sync with it
        again. Deliberately skipped whenever `theta_provider is not
        None` (the Slideshow's Shadow Sim view): that call path already
        resolves its own single current-step alpha into `alpha`/`dx_um`/
        `dy_um` before calling here, so re-deriving per-pass alpha from
        `run`'s ORIGINAL, pre-override theta lists would be wrong -- that
        call path's own thetas can differ entirely from run's own
        lists."""
        # Use the COMMITTED values from the last Run Simulation click,
        # not whatever's currently typed -- this function is only ever
        # invoked in Simulated Design view after a run, so a committed
        # snapshot should always exist, but fall back to live field
        # reads defensively if it somehow doesn't.
        run = self._sim_last_run or {}
        alpha = run.get("alpha")
        if alpha is None:
            try:
                alpha = float(self.sim_alpha_override_edit.text())
            except ValueError:
                alpha = 30.0
        try:
            pmma_nm = float(self.pmma_edit.text()) if hasattr(self, "pmma_edit") else 875.0
        except ValueError:
            pmma_nm = 875.0
        try:
            pmgi_nm = float(self.pmgi_edit.text()) if hasattr(self, "pmgi_edit") else 600.0
        except ValueError:
            pmgi_nm = 600.0
        dx_um, dy_um = self._shadow_dxdy(pmma_nm, pmgi_nm, alpha)

        theta_overrides = [run.get("theta_a"), run.get("theta_b")]

        for i, f in enumerate(junction.fingers):
            # A feature can have
            # MULTIPLE active depositions, or zero -- read from the
            # COMMITTED run state (matching how Run Shadow Simulation
            # already works: typing doesn't live-update anything, only
            # clicking Run does), same source _compute_post_shadow_
            # shapes reads from, so the two views can't disagree about
            # which depositions are active.
            thetas = self._run_finger_thetas(run, i, f, theta_overrides)
            # Per-pass alpha, resolved BEFORE any
            # theta_provider override -- see this function's own
            # docstring update below for why a theta_provider call path
            # (the Slideshow's Shadow Sim view, always exactly one
            # active theta) is already correct without this and must NOT
            # have its own already-correct single dx_um/dy_um replaced by
            # a mismatched per-index lookup against the ORIGINAL,
            # pre-override thetas list.
            if theta_provider is None:
                dx_list, dy_list = self._resolve_pass_dxdy_list(thetas, self._run_finger_alphas(run, i), dx_um, dy_um, pmma_nm, pmgi_nm)
                # This finger's own per-pass alpha
                # (the raw angle, not a dx/dy translation of it) -- the
                # electrode-crossing parallelogram below needs alpha
                # itself, resolved the same way and under the same
                # theta_provider guard as dx_list/dy_list just above.
                alpha_list = self._resolve_pass_alpha_list(thetas, self._run_finger_alphas(run, i), alpha)
            else:
                dx_list, dy_list = dx_um, dy_um
                alpha_list = alpha
            if theta_provider is not None:
                thetas = theta_provider.finger_thetas(i, thetas)
            if not thetas:
                continue  # zero active depositions -- nothing to draw for this finger at all
            fx, fy = f.patch_end[0]-f.stub_end[0], f.patch_end[1]-f.stub_end[1]
            flen = math.hypot(fx, fy) or 1.0
            axis_toward_patch = (fx/flen, fy/flen)
            axis_toward_stub = (-axis_toward_patch[0], -axis_toward_patch[1])
            perp = (-axis_toward_patch[1], axis_toward_patch[0])
            has_plate = self._find_associated_plate(junction, f) is not None

            for layer_pos, theta in enumerate(thetas):
                layer_label = f" (dep {layer_pos+1})" if len(thetas) > 1 else ""
                # This pass's own dx/dy (per-pass
                # when theta_provider is None -- dx_list/dy_list are real
                # lists there; otherwise dx_list/dy_list ARE dx_um/dy_um,
                # the plain scalar, unchanged).
                dx_i = dx_list[layer_pos] if isinstance(dx_list, (list, tuple)) else dx_list
                dy_i = dy_list[layer_pos] if isinstance(dy_list, (list, tuple)) else dy_list
                alpha_i = alpha_list[layer_pos] if isinstance(alpha_list, (list, tuple)) else alpha_list
                # Crossing/stub end
                align_stub = self._shadow_alignment(axis_toward_stub, theta)
                depth_stub, extend_stub = self._scaled_shadow_depth(dx_i, dy_i, align_stub)
                self._draw_shadow_band(ax, f.stub_end, axis_toward_stub, perp, f.width_um/2.0, depth_stub, extend_stub,
                                       label=f"{theta:g}\u00b0{layer_label}")
                # Tip/patch end -- physics fix, based on
                # feedback, verified against real geometry first: when this
                # finger has an adhesion plate touching its tip (same
                # deposition step, continuous metal, no edge between them),
                # that tip does NOT get its own independent shadow band --
                # the plate's own far end carries the shadow effect instead
                # (drawn in the plate loop below). Only draw a tip band here
                # when there's no associated plate.
                if not has_plate:
                    align_tip = self._shadow_alignment(axis_toward_patch, theta)
                    depth_tip, extend_tip = self._scaled_shadow_depth(dx_i, dy_i, align_tip)
                    self._draw_shadow_band(ax, f.patch_end, axis_toward_patch, perp, f.width_um/2.0, depth_tip, extend_tip,
                                           label=f"{theta:g}\u00b0{layer_label}")
                # Note: the electrode-crossing shadow is a SEPARATE
                # mechanism from the plate-merge overlap-shadow logic above
                # -- it's about whether the FINGER'S OWN geometry crosses
                # the electrode, independent of whether a plate is also
                # attached at its tip. Checked unconditionally here (not
                # gated on "no associated plate"), using the finger's own
                # points -- confirmed directly that _find_electrode_
                # crossing_line correctly returns None (a no-op) for a
                # finger that doesn't actually reach the electrode, so this
                # is safe to attempt for every finger where Warning #1 could
                # apply. With multiple layers, each pass's own risky angle
                # still casts its own electrode shadow independently -- a
                # different pass extending safely doesn't retroactively
                # erase a risky pass's own missing-metal region, since
                # that's a real gap regardless of what other metal exists
                # elsewhere.
                align_own_tip = self._shadow_alignment(axis_toward_patch, theta)
                if f.warning_source in ("finger", "both") and align_own_tip < 0:
                    # This pass's own resolved
                    # alpha (alpha_i), not the shared scalar -- matches
                    # the identical fix just made to the real geometry
                    # in _compute_finger_shadowed_pieces, so this
                    # annotation can never again drift from what
                    # Post-Shadow Result actually computes.
                    self._draw_electrode_shadow_parallelogram(ax, junction, f.points, theta, alpha_i)

            # Cross-axis (wrong-deposition-angle) self-shadow: drawn ONCE
            # per finger across all of its active passes at once -- exactly
            # matching _apply_cross_axis_shadow's own "worst of any active
            # pass" model (see _compute_finger_shadowed_pieces, which calls
            # it with this same axis_toward_patch/thetas pair) -- rather
            # than per-pass like the tip bands above, since a later pass
            # can only narrow the surviving strip further, never widen it.
            # Resolved via a SEPARATE cross-axis hook
            # (see ShadowThetaProvider's own docstring) rather than reusing
            # `thetas` directly -- a caller that only overrode the axial
            # resolver above (every pre-existing behavior) still gets
            # `thetas` unchanged here, a true no-op.
            cross_axis_thetas = thetas
            if theta_provider is not None:
                cross_axis_thetas = theta_provider.finger_cross_axis_thetas(i, thetas)
            self._draw_cross_axis_shadow_bands(ax, f.points, axis_toward_patch, cross_axis_thetas, dx_list, dy_list,
                                               label="⊥" if len(cross_axis_thetas) == 1 else "⊥ (net)",
                                               origin=f.patch_end)

        # Patches: figure out the actual deposition theta(s) required --
        # may be ONE shared angle, or TWO if the fingers' patch groups
        # disagree (the common case) -- rather than assuming the
        # patch's own drawn shape angle is the deposition theta at all.
        rec = ji.compute_recommended_angles(junction)
        patches_rec = rec.get("patches")
        global_patch_thetas = patches_rec["angles"] if patches_rec else None

        for pg in report.patch_groups:
            finger = junction.fingers[pg.finger_index]
            # Gap fixed here (same as _compute_post_shadow_shapes):
            # both fingers' own deposition passes are blanket depositions
            # that land on EVERY patch regardless of which finger it's
            # attached to -- the fallback must use both active thetas
            # together, not just the associated finger's own single
            # theta, or the second pass silently disappears whenever
            # patches_rec is None.
            fallback_thetas = []
            for idx, other_finger in enumerate(junction.fingers):
                t = theta_overrides[idx] if idx < len(theta_overrides) and theta_overrides[idx] is not None else other_finger.theta_toward_patch_deg
                if t not in fallback_thetas:
                    fallback_thetas.append(t)
            patch_thetas_override = run.get("patch_thetas_override")
            patch_thetas_raw = patch_thetas_override if patch_thetas_override is not None else (global_patch_thetas if global_patch_thetas is not None else fallback_thetas)
            patch_thetas = self._true_order_patch_thetas(junction, run, theta_overrides, patch_thetas_raw)
            # This patch group's own per-pass
            # alpha, resolved BEFORE any theta_provider override -- same
            # reasoning as the finger loop above (a theta_provider call
            # path is already correct via its own single current-step
            # alpha, and must not have a mismatched per-index lookup
            # against the ORIGINAL, pre-override patch_thetas forced onto
            # it).
            if theta_provider is None:
                patch_layers_ref = run.get("patch_thetas_override")
                if patch_layers_ref is None:
                    patch_layers_ref = self._sim_patch_layers or []
                patch_alphas_ref = run.get("patch_alphas_override") or []
                patch_alphas = self._match_pass_thicknesses(patch_thetas, patch_layers_ref, patch_alphas_ref, default=None) if patch_thetas else []
                patch_dx_list, patch_dy_list = self._resolve_pass_dxdy_list(patch_thetas, patch_alphas, dx_um, dy_um, pmma_nm, pmgi_nm) if patch_thetas else ([], [])
            else:
                patch_dx_list, patch_dy_list = dx_um, dy_um
                # Kept in sync with patch_dx_list/
                # patch_dy_list's own theta_provider guard just above --
                # patch_alphas is only ever resolved (and only ever
                # index-aligned with patch_thetas) in the theta_provider
                # is None branch, so it's set to None here rather than
                # left undefined, and every reader below falls back to
                # the shared `alpha` scalar whenever it's None.
                patch_alphas = None
            if theta_provider is not None:
                patch_thetas = theta_provider.patch_thetas(patch_thetas)
            # See ShadowThetaProvider's own docstring
            # -- a separate, foreign-only theta list for the cross-axis
            # band below, resolved once per patch group (every patch in
            # `nearby` shares the same group-wide patch_thetas already).
            patch_cross_axis_thetas = patch_thetas
            if theta_provider is not None:
                patch_cross_axis_thetas = theta_provider.patch_cross_axis_thetas(patch_thetas)
            shapes = [s for s in junction.other_shapes if s.kind == "patch"]
            fx, fy = finger.patch_end[0]-finger.stub_end[0], finger.patch_end[1]-finger.stub_end[1]
            flen = math.hypot(fx, fy) or 1.0
            fu, fv = fx/flen, fy/flen

            def pos(s):
                cx = sum(p[0] for p in s.points)/len(s.points)
                cy = sum(p[1] for p in s.points)/len(s.points)
                return (cx-finger.stub_end[0])*fu + (cy-finger.stub_end[1])*fv

            nearby = sorted(shapes, key=lambda s: sg.Polygon(s.points).distance(sg.Point(finger.patch_end)))[:pg.patch_count]
            nearby = sorted(nearby, key=pos)
            if not patch_thetas:
                continue  # zero active patch depositions -- nothing to draw for these patches at all
            for k, s in enumerate(nearby):
                axis_angle, end_a, end_b, _w = ji._polygon_axis_and_ends(s.points)
                proj_a = (end_a[0]-finger.stub_end[0])*fu + (end_a[1]-finger.stub_end[1])*fv
                proj_b = (end_b[0]-finger.stub_end[0])*fu + (end_b[1]-finger.stub_end[1])*fv
                near_end, far_end = (end_a, end_b) if proj_a < proj_b else (end_b, end_a)
                p_ang = math.radians(axis_angle)
                p_hat = (math.cos(p_ang), math.sin(p_ang))
                pperp = (-p_hat[1], p_hat[0])
                w_um = pg.individual_widths_um[k] if k < len(pg.individual_widths_um) else s.width_um

                axis_toward_near = (-(far_end[0]-near_end[0]), -(far_end[1]-near_end[1]))
                nl = math.hypot(*axis_toward_near) or 1.0
                axis_toward_near = (axis_toward_near[0]/nl, axis_toward_near[1]/nl)
                axis_toward_far = (-axis_toward_near[0], -axis_toward_near[1])

                # PHYSICS FIX, reverting the prior CHAINED drawing this used to do for
                # a shrink-then-extend end (pass 2's band drawn starting
                # from the END of pass 1's band instead of from the
                # nominal edge): the trench is fixed, and the shadowing
                # doesn't depend on the previous feature or deposition
                # pass of a feature -- it should depend only on the shape of
                # the trench itself. The resist trench never moves
                # between passes, so both passes' bands are always drawn
                # from the SAME nominal edge (end_pt) -- mirrors
                # _compute_one_patch_shadowed_pieces's own fix exactly,
                # so the two views can never disagree. Whichever band
                # reaches less far (by signed depth) is drawn as a
                # masked ghost -- a later shrink never erases metal an
                # earlier pass already deposited there.
                if len(patch_thetas) >= 2:
                    theta_first, theta_second = patch_thetas[0], patch_thetas[1]
                    # Pass 1/pass 2's own dx/dy --
                    # per-pass when theta_provider is None (patch_dx_list/
                    # patch_dy_list are real lists there), else the plain
                    # shared scalar, unchanged.
                    pdx1 = patch_dx_list[0] if isinstance(patch_dx_list, (list, tuple)) else patch_dx_list
                    pdy1 = patch_dy_list[0] if isinstance(patch_dy_list, (list, tuple)) else patch_dy_list
                    pdx2 = patch_dx_list[1] if isinstance(patch_dx_list, (list, tuple)) and len(patch_dx_list) > 1 else pdx1
                    pdy2 = patch_dy_list[1] if isinstance(patch_dy_list, (list, tuple)) and len(patch_dy_list) > 1 else pdy1
                    for end_pt, axis_toward in ((near_end, axis_toward_near), (far_end, axis_toward_far)):
                        align1 = self._shadow_alignment(axis_toward, theta_first)
                        align2 = self._shadow_alignment(axis_toward, theta_second)
                        depth1, outward1 = self._scaled_shadow_depth(pdx1, pdy1, align1)
                        depth2, outward2 = self._scaled_shadow_depth(pdx2, pdy2, align2)
                        signed1 = depth1 if outward1 else -depth1
                        signed2 = depth2 if outward2 else -depth2
                        net = max(signed1, signed2)
                        self._draw_shadow_band(ax, end_pt, axis_toward, pperp, w_um/2.0, depth1, outward1,
                                               label=f"{theta_first:g}\u00b0" + ("" if signed1 >= net else " (masked)"),
                                               masked=(signed1 < net))
                        self._draw_shadow_band(ax, end_pt, axis_toward, pperp, w_um/2.0, depth2, outward2,
                                               label=f"{theta_second:g}\u00b0" + ("" if signed2 >= net else " (masked)"),
                                               masked=(signed2 < net))
                elif len(patch_thetas) == 1:
                    theta = patch_thetas[0]
                    pdx1 = patch_dx_list[0] if isinstance(patch_dx_list, (list, tuple)) else patch_dx_list
                    pdy1 = patch_dy_list[0] if isinstance(patch_dy_list, (list, tuple)) else patch_dy_list
                    align_near = self._shadow_alignment(axis_toward_near, theta)
                    depth_near, extend_near = self._scaled_shadow_depth(pdx1, pdy1, align_near)
                    self._draw_shadow_band(ax, near_end, axis_toward_near, pperp, w_um/2.0,
                                           depth_near, extend_near, label=f"{theta:g}\u00b0")
                    align_far = self._shadow_alignment(axis_toward_far, theta)
                    depth_far, extend_far = self._scaled_shadow_depth(pdx1, pdy1, align_far)
                    self._draw_shadow_band(ax, far_end, axis_toward_far, pperp, w_um/2.0,
                                           depth_far, extend_far, label=f"{theta:g}\u00b0")
                    # The patch's far end is the electrode-facing side --
                    # same electrode-crossing mechanism as the finger's
                    # own tip, applied here using the PATCH's own shape
                    # (not the plate's, confirmed separately that plates
                    # never touch the electrode at all).
                    if finger.warning_source in ("patches", "both") and align_far < 0:
                        # This patch's own
                        # resolved alpha (patch_alphas[0], matching this
                        # single-pass branch's own theta), falling back
                        # to the shared scalar when unavailable (a
                        # theta_provider call path, or no per-pass
                        # override set) -- same fix as the finger's own
                        # case, matching _compute_one_patch_shadowed_
                        # pieces' identical real-geometry fix.
                        pass_alpha = (patch_alphas[0] if patch_alphas and patch_alphas[0] is not None else alpha) \
                            if patch_alphas is not None else alpha
                        self._draw_electrode_shadow_parallelogram(ax, junction, s.points, theta, pass_alpha)

                # Cross-axis (wrong-deposition-angle) self-shadow -- same
                # mechanism and same axis_toward_far/patch_thetas pair
                # _compute_one_patch_shadowed_pieces itself uses, drawn
                # once across all active patch passes at once (matching
                # _apply_cross_axis_shadow's own "worst of any active
                # pass" model, not per-pass like the near/far bands above).
                # This is the direct fix for a real design where a patch
                # crossed its deposition angle badly: instead of
                # only a text warning when a patch fully vanishes (and
                # nothing at all for a smaller mismatch), this shows the
                # real, continuous eaten width as red hatching on both of
                # the patch's long edges.
                self._draw_cross_axis_shadow_bands(ax, s.points, axis_toward_far, patch_cross_axis_thetas, patch_dx_list, patch_dy_list,
                                                   label="⊥" if len(patch_cross_axis_thetas) == 1 else "⊥ (net)")
                # VISUALIZATION GAP, fixed here -- see this
                # method's own docstring for the full report: a
                # per-pass masked ghost for whichever individual pass(es)
                # the net result above actually masked out, so a
                # catastrophically self-shadowed pass is never silently
                # invisible just because another pass in the same group
                # happens to mask it in the final result.
                self._draw_cross_axis_shadow_bands_masked_passes(ax, s.points, axis_toward_far, patch_cross_axis_thetas, patch_dx_list, patch_dy_list)

        # Adhesion/overlap plates ("plate" shape kind) were entirely
        # invisible to the shadow visualization before -- never drawn,
        # never accounted for. Fixed here.
        # Single theta (the attached finger's own active theta), since
        # plates deposit in the same step as their finger.
        plate_shapes = [s for s in junction.other_shapes if s.kind == "plate"]
        for s in plate_shapes:
            nearest_finger = self._find_finger_for_plate(junction, s)
            idx = junction.fingers.index(nearest_finger)
            # A plate deposits in the
            # SAME step as its finger -- zero active layers for that
            # finger means the plate isn't deposited either, matching
            # the same fix applied in _compute_post_shadow_shapes.
            thetas = self._run_finger_thetas(run, idx, nearest_finger, theta_overrides)
            # Same per-pass alpha resolution as the
            # finger loop above, resolved BEFORE any theta_provider
            # override.
            if theta_provider is None:
                dx_list, dy_list = self._resolve_pass_dxdy_list(thetas, self._run_finger_alphas(run, idx), dx_um, dy_um, pmma_nm, pmgi_nm)
            else:
                dx_list, dy_list = dx_um, dy_um
            if theta_provider is not None:
                thetas = theta_provider.plate_thetas(idx, thetas)
            if not thetas:
                continue
            # Fixed here (same as _compute_post_shadow_
            # shapes): near_end/far_end/width from the plate's OWN long
            # axis breaks down for a near-square plate whose own long
            # dimension doesn't match the direction its finger actually
            # approaches from -- this shows up on a real plate
            # where the finger approaches along the SHORT dimension.
            # Projecting onto the finger's own axis instead works
            # regardless of the plate's own aspect ratio.
            near_end, far_end, plate_w = self._project_plate_onto_finger_axis(nearest_finger, s.points)
            fx, fy = nearest_finger.patch_end[0]-nearest_finger.stub_end[0], nearest_finger.patch_end[1]-nearest_finger.stub_end[1]
            flen = math.hypot(fx, fy) or 1.0
            fu, fv = fx/flen, fy/flen
            axis_toward_near = (-(far_end[0]-near_end[0]), -(far_end[1]-near_end[1]))
            nl = math.hypot(*axis_toward_near) or 1.0
            axis_toward_near = (axis_toward_near[0]/nl, axis_toward_near[1]/nl)
            axis_toward_far = (-axis_toward_near[0], -axis_toward_near[1])
            pperp = (-axis_toward_far[1], axis_toward_far[0])
            # BUG, fixed here directly against real
            # geometry: the finger was assumed to sit at the CENTER of
            # the plate's near edge (symmetric half_exposed on each
            # side), but a real design's bottom-left finger connects 2 units off
            # the plate's own centerline -- measured directly, not
            # assumed. Computing the finger's actual perpendicular
            # offset from near_end (rather than assuming zero) gives
            # the real, generally asymmetric shoulder widths on each
            # side. This geometry is the SAME regardless of which
            # deposition layer, so it's computed once outside the loop
            # below.
            finger_perp_offset = ((nearest_finger.stub_end[0]-near_end[0])*pperp[0]
                                   + (nearest_finger.stub_end[1]-near_end[1])*pperp[1])
            half_finger = nearest_finger.width_um / 2.0
            left_width = (plate_w/2.0) + finger_perp_offset - half_finger
            right_width = (plate_w/2.0) - finger_perp_offset - half_finger
            for layer_pos, theta in enumerate(thetas):
                layer_label = f" (dep {layer_pos+1})" if len(thetas) > 1 else ""
                # This pass's own dx/dy (per-pass
                # when theta_provider is None, plain scalar otherwise --
                # same convention as the finger loop above).
                dx_i = dx_list[layer_pos] if isinstance(dx_list, (list, tuple)) else dx_list
                dy_i = dy_list[layer_pos] if isinstance(dy_list, (list, tuple)) else dy_list
                # This is NOT a separate mechanism --
                # the SAME dx/dy shadow, using the STANDARD alignment toward
                # the finger, just not applied across the center strip
                # matching the finger's own linewidth (continuous metal,
                # same deposition, no real edge there). Both exposed outer
                # portions of the near edge get the SAME depth/direction
                # (not opposite signs): theta=45 gives extend/blue on both,
                # theta=225 gives shrink/red on both, for a finger with
                # theta_toward_stub=45.
                align_near = self._shadow_alignment(axis_toward_near, theta)
                depth_near, extend_near = self._scaled_shadow_depth(dx_i, dy_i, align_near)
                if left_width > 0.005:
                    left_far_edge = -plate_w/2.0
                    left_near_edge = finger_perp_offset - half_finger
                    left_center_perp = (left_far_edge + left_near_edge) / 2.0
                    left_center = (near_end[0] + pperp[0]*left_center_perp, near_end[1] + pperp[1]*left_center_perp)
                    self._draw_shadow_band(ax, left_center, axis_toward_near, pperp, left_width/2.0,
                                           depth_near, extend_near, label=f"{theta:g}\u00b0{layer_label}")
                if right_width > 0.005:
                    right_far_edge = plate_w/2.0
                    right_near_edge = finger_perp_offset + half_finger
                    right_center_perp = (right_far_edge + right_near_edge) / 2.0
                    right_center = (near_end[0] + pperp[0]*right_center_perp, near_end[1] + pperp[1]*right_center_perp)
                    self._draw_shadow_band(ax, right_center, axis_toward_near, pperp, right_width/2.0,
                                           depth_near, extend_near, label=f"{theta:g}\u00b0{layer_label}")
                align_far = self._shadow_alignment(axis_toward_far, theta)
                depth_far, extend_far = self._scaled_shadow_depth(dx_i, dy_i, align_far)
                self._draw_shadow_band(ax, far_end, axis_toward_far, pperp, plate_w/2.0,
                                       depth_far, extend_far, label=f"{theta:g}\u00b0{layer_label}")
            # GAP, fixed here: the
            # cos(theta) shadowing application rule needs to be applied
            # to every single shape in the junction, including adhesion
            # plates and patches, not just fingers. Adhesion plates had the
            # near/far (tip-style) shadow above, but NEVER the width-wise
            # (cross-axis) self-shadow mechanism fingers and patches
            # already got -- a plate is usually wide enough that
            # this rarely matters in practice, but the mechanism itself
            # was simply absent, not just negligible, so a thin enough
            # plate would have silently shown no width-wise shadow at
            # all regardless of how far off-axis theta was. Drawn ONCE
            # per plate across all active passes at once (net across
            # passes via the shared _cross_axis_boundaries), exactly
            # matching how fingers/patches already draw this band --
            # never per-pass like the near/far bands above, since this
            # is the SAME "worst/combined across active passes" model.
            # See ShadowThetaProvider's own docstring
            # -- resolved via a separate cross-axis hook, a no-op unless
            # a caller explicitly overrides it.
            plate_cross_axis_thetas = thetas
            if theta_provider is not None:
                plate_cross_axis_thetas = theta_provider.plate_cross_axis_thetas(idx, thetas)
            self._draw_cross_axis_shadow_bands(ax, s.points, axis_toward_far, plate_cross_axis_thetas, dx_list, dy_list,
                                               label="\u22a5" if len(plate_cross_axis_thetas) == 1 else "\u22a5 (net)",
                                               origin=nearest_finger.patch_end)
            # Verified directly on real geometry: plates do
            # NOT cross the electrode at all (a real adhesion pad's own
            # crossing-line check returned zero crossings, while
            # its finger returned exactly two) -- the electrode-shadow
            # parallelogram belongs on whichever shape actually touches
            # the electrode (the finger itself, handled above, or the
            # patch shape specifically, handled in the patch loop
            # below), never the plate. No call here.

    def _evaluate_warnings_at_theta(self, finger, theta):
        """Warning #1/#2 status at an ARBITRARY theta, not just the two
        canonical directions the recommendation tree already covers --
        reuses the same _shadow_alignment technique already verified
        for the shadow visualization, against the SAME reference
        directions compute_recommended_angles itself uses
        (theta_toward_patch_deg = safe for W1/risky for W2,
        theta_toward_stub_deg = the reverse) -- confirmed this
        reproduces the known canonical verdicts exactly before using it
        here for angles the recommendation engine never explicitly
        evaluates.

        Also flags when theta is neither of the two axis-aligned
        options (theta_toward_patch or theta_toward_stub) -- shadowing
        still gets computed and shown (scaled by how far off-axis theta
        is), but a genuinely off-axis choice deserves its own clear
        note rather than silently blending into the W1/W2 verdict."""
        fx, fy = finger.patch_end[0]-finger.stub_end[0], finger.patch_end[1]-finger.stub_end[1]
        flen = math.hypot(fx, fy) or 1.0
        axis_toward_patch = (fx/flen, fy/flen)
        align = self._shadow_alignment(axis_toward_patch, theta)
        w1_applies = finger.warning_source in ("finger", "both")
        w2_applies = getattr(finger, "deposited_second", False)
        parts = []
        if w1_applies:
            parts.append("\u2713 W1 safe" if align > 0 else "\u26a0 W1 risky" if align < 0 else "? W1 borderline")
        if w2_applies:
            parts.append("\u2713 W2 safe" if align < 0 else "\u26a0 W2 risky" if align > 0 else "? W2 borderline")
        if not parts:
            parts.append("no warning applies to this finger")
        off_axis = abs(align) < 0.9
        return ", ".join(parts), off_axis, align

    def _feature_widget_row(self, tree, parent_item, default_theta):
        """One feature's embedded [Custom checkbox][theta field] pair --
        unchecked uses the recommendation (field disabled, shows the
        recommended value greyed out); checked lets the user type any
        angle, which then drives the shadow visualization, risk check,
        AND gets a live Warning #1/#2 verdict -- the part that was
        missing before and made the override fields feel pointless."""
        row_widget = QWidget()
        row = QHBoxLayout(row_widget)
        row.setContentsMargins(2, 0, 2, 0)
        custom_check = QCheckBox("Custom")
        custom_check.setStyleSheet("font-size: 8pt;")
        edit = QLineEdit(f"{default_theta:g}" if default_theta is not None else "")
        edit.setEnabled(False)
        edit.setMaximumWidth(70)
        row.addWidget(custom_check)
        row.addWidget(edit)
        row.addStretch()
        tree.setItemWidget(parent_item, 1, row_widget)

        def on_toggle(checked):
            edit.setEnabled(checked)
            self._update_sim_angle_verdicts()
        custom_check.toggled.connect(on_toggle)
        edit.textChanged.connect(self._update_sim_angle_verdicts)
        return custom_check, edit

    def _layer_widget_row(self, tree, parent_item, theta_value, on_edit, on_remove,
                           thickness_value=None, on_edit_thickness=None, removable=True):
        """A feature can have MULTIPLE
        active depositions (e.g. two adhesion passes with no oxidation
        between them, as seen on a real design's vertical finger) or
        can be reduced to ZERO (meaning that shape never gets deposited
        at all). Each layer is an editable angle, an editable target
        thickness, and a remove button -- no Custom checkbox needed,
        since a layer existing at all already means it's active.
        Modeled after the old chamber tab's own add/remove deposition-
        step mechanism, applied here per feature branch instead of one
        global sequence.

        thickness_value/on_edit_thickness let the user set the
        target thickness of each deposition step right here, under
        Deposition Angles in
        the simulation tab, next to this same pass's angle,
        since this tree already shows exactly the features/passes being
        deposited and (via the verdict row) whether a Warning #2-risky
        angle is in play -- the natural place to decide thickness too.
        Passing on_edit_thickness=None omits the field entirely (kept
        optional so this row-builder still works for any future caller
        that has no notion of thickness)."""
        row_widget = QWidget()
        row = QHBoxLayout(row_widget)
        row.setContentsMargins(2, 0, 2, 0)
        edit = QLineEdit(f"{theta_value:g}")
        edit.setMaximumWidth(70)
        edit.setToolTip("Deposition angle (theta, deg)")
        row.addWidget(edit)
        edit.textChanged.connect(on_edit)
        thickness_edit = None
        if on_edit_thickness is not None:
            deg_label = QLabel("deg,")
            deg_label.setStyleSheet("font-size: 8pt;")
            row.addWidget(deg_label)
            thickness_edit = QLineEdit(f"{thickness_value:g}" if thickness_value is not None else "")
            thickness_edit.setMaximumWidth(55)
            thickness_edit.setToolTip("Target deposition thickness for this pass (nm)")
            row.addWidget(thickness_edit)
            nm_label = QLabel("nm")
            nm_label.setStyleSheet("font-size: 8pt;")
            row.addWidget(nm_label)
            thickness_edit.textChanged.connect(on_edit_thickness)
        if removable:
            remove_btn = QPushButton("\u2715")
            remove_btn.setCursor(Qt.PointingHandCursor)
            remove_btn.setFixedSize(20, 20)
            remove_btn.setStyleSheet("""
                QPushButton { background-color: #3a2a2e; color: #e08a8a; border: 1px solid #5a3a3e;
                             border-radius: 4px; font-size: 8pt; padding: 0px; }
                QPushButton:hover { background-color: #4a3236; }
            """)
            remove_btn.clicked.connect(on_remove)
            row.addWidget(remove_btn)
        row.addStretch()
        tree.setItemWidget(parent_item, 1, row_widget)
        return edit, thickness_edit

    def _on_add_finger_layer(self, finger_idx, fallback_theta, fallback_thickness=None, insert_pos=None):
        # `insert_pos` is a new, OPTIONAL trailing
        # param -- where in THIS finger's own layer list the new pass
        # goes. None (every pre-existing caller, e.g. the per-finger "+"
        # button in the Deposition Angles tree) means "append", exactly
        # today's behavior, byte-identical. A real index is what
        # _insert_deposition_step now passes so a step
        # inserted at a specific point in the Predicted Recipe Sequence
        # actually lands there for this finger too, instead of always
        # being appended after every pass this finger already had -- see
        # that function's own docstring for the full report.
        layers = self._sim_finger_layers.setdefault(finger_idx, [])
        pos = len(layers) if insert_pos is None else max(0, min(insert_pos, len(layers)))
        layers.insert(pos, fallback_theta)
        thicknesses = self._sim_finger_thicknesses.setdefault(finger_idx, [])
        tpos = len(thicknesses) if insert_pos is None else max(0, min(insert_pos, len(thicknesses)))
        thicknesses.insert(tpos, fallback_thickness)
        if self._sim_cached_junction is not None:
            rec = ji.compute_recommended_angles(self._sim_cached_junction)
            self._rebuild_sim_angles_tree(self._sim_cached_junction, rec)
        # BUG FIX, found while investigating an
        # "Insert Step" misplacement: when self._sim_has_run is
        # already True, _rebuild_sim_angles_tree above cascades (via
        # _update_sim_angle_verdicts -> _refresh_recipe_features ->
        # _rebuild_recipe_from_features -> _sync_sim_layers_from_recipe_
        # features) all the way to _recommit_sim_run, which recomputes
        # self._sim_last_run from the just-inserted pass AND sets
        # self._sim_stale = False (see _recommit_sim_run's own docstring
        # -- the user only ever needs to click Run once per design). The old
        # unconditional call to _mark_sim_stale() right below immediately
        # flipped self._sim_stale back to True and re-showed the "stale --
        # click Run Shadow Simulation to update it" banner over a view
        # that had, in fact, JUST been correctly recomputed one line
        # earlier -- a false positive telling the user to re-click Run
        # for no reason, on every single attributed insert. Only mark
        # stale here when the cascade above did NOT already run the
        # auto-recompute (no junction yet, or no committed Run yet to
        # keep in sync) -- matches the exact same condition _sync_sim_
        # layers_from_recipe_features already uses for the identical
        # choice.
        if not (getattr(self, "_sim_has_run", False) and self._sim_cached_junction is not None):
            self._mark_sim_stale()  # item #105 -- adding a pass changes what a committed Run reflects

    def _on_remove_finger_layer(self, finger_idx, layer_pos):
        layers = self._sim_finger_layers.get(finger_idx, [])
        if 0 <= layer_pos < len(layers):
            layers.pop(layer_pos)
        thicknesses = self._sim_finger_thicknesses.get(finger_idx, [])
        if 0 <= layer_pos < len(thicknesses):
            thicknesses.pop(layer_pos)
        if self._sim_cached_junction is not None:
            rec = ji.compute_recommended_angles(self._sim_cached_junction)
            self._rebuild_sim_angles_tree(self._sim_cached_junction, rec)
        self._mark_sim_stale()  # item #105

    def _on_edit_finger_layer(self, finger_idx, layer_pos, text):
        layers = self._sim_finger_layers.get(finger_idx, [])
        if 0 <= layer_pos < len(layers):
            try:
                layers[layer_pos] = float(text)
            except ValueError:
                pass
        self._update_sim_angle_verdicts()
        self._mark_sim_stale()  # item #105

    def _on_edit_finger_thickness(self, finger_idx, layer_pos, text):
        thicknesses = self._sim_finger_thicknesses.get(finger_idx, [])
        if 0 <= layer_pos < len(thicknesses):
            try:
                thicknesses[layer_pos] = float(text)
            except ValueError:
                pass
        self._mark_sim_stale()  # item #105

    def _on_add_patch_layer(self, fallback_theta, fallback_thickness=None, insert_pos=None):
        # Same optional insert_pos fix as _on_add_finger_layer above --
        # None (every pre-existing caller) means "append", unchanged.
        if self._sim_patch_layers is None:
            self._sim_patch_layers = []
        pos = len(self._sim_patch_layers) if insert_pos is None else max(0, min(insert_pos, len(self._sim_patch_layers)))
        self._sim_patch_layers.insert(pos, fallback_theta)
        if self._sim_patch_thicknesses is None:
            self._sim_patch_thicknesses = []
        tpos = len(self._sim_patch_thicknesses) if insert_pos is None else max(0, min(insert_pos, len(self._sim_patch_thicknesses)))
        self._sim_patch_thicknesses.insert(tpos, fallback_thickness)
        if self._sim_cached_junction is not None:
            rec = ji.compute_recommended_angles(self._sim_cached_junction)
            self._rebuild_sim_angles_tree(self._sim_cached_junction, rec)
        # See the identical fix (and full explanation)
        # in _on_add_finger_layer just above: the cascade one line up
        # already re-commits a fresh, non-stale run via _recommit_sim_run
        # whenever a Run was already committed, so unconditionally calling
        # _mark_sim_stale() here was re-flagging an up-to-date view as
        # stale on every single attributed patches insert.
        if not (getattr(self, "_sim_has_run", False) and self._sim_cached_junction is not None):
            self._mark_sim_stale()  # item #105

    def _on_remove_patch_layer(self, layer_pos):
        layers = self._sim_patch_layers or []
        if 0 <= layer_pos < len(layers):
            layers.pop(layer_pos)
        thicknesses = self._sim_patch_thicknesses or []
        if 0 <= layer_pos < len(thicknesses):
            thicknesses.pop(layer_pos)
        if self._sim_cached_junction is not None:
            rec = ji.compute_recommended_angles(self._sim_cached_junction)
            self._rebuild_sim_angles_tree(self._sim_cached_junction, rec)
        self._mark_sim_stale()  # item #105

    def _on_edit_patch_layer(self, layer_pos, text):
        layers = self._sim_patch_layers or []
        if 0 <= layer_pos < len(layers):
            try:
                layers[layer_pos] = float(text)
            except ValueError:
                pass
        self._update_sim_angle_verdicts()
        self._mark_sim_stale()  # item #105

    def _on_edit_patch_thickness(self, layer_pos, text):
        thicknesses = self._sim_patch_thicknesses or []
        if 0 <= layer_pos < len(thicknesses):
            try:
                thicknesses[layer_pos] = float(text)
            except ValueError:
                pass
        self._mark_sim_stale()  # item #105

    def _rebuild_sim_angles_tree(self, junction, rec):
        """Rebuilds the per-feature angle tree whenever the design
        changes -- one entry per finger plus patches (if this design's
        patches need it), each with its own Recommended/Custom state
        and a live verdict child row.

        This used to unconditionally
        reset every feature back to Recommended/unchecked on every
        rebuild -- which fires after every Run Simulation click (since
        that triggers a full preview redraw) -- so the Custom checkbox
        and typed angle visually vanished right after clicking Run,
        even though the click itself had already captured the value
        correctly. Preserving prior state across the rebuild removes
        that "did my input get thrown away?" impression.

        A separate bug: that same "preserve
        prior state" logic didn't check WHICH design the prior state
        belonged to, so switching from one imported design to a
        completely different one (different file, different geometry)
        silently carried over the previous design's Custom angles and
        checkbox state, as long as the finger indices lined up (e.g.
        both designs having a finger 0 and finger 1). Tracking the
        junction's own identity and only preserving state when it's
        literally the same design object (a Run click or redraw of
        what's already loaded) fixes this without breaking the
        same-design preservation above."""
        if not hasattr(self, "sim_angles_tree"):
            return
        same_design = getattr(self, "_sim_angle_tree_junction", None) is junction
        # Finger entries no longer have "check"/"edit"
        # keys (they use "layer_edits", a list, with state persisted
        # directly in self._sim_finger_layers instead) -- only patches
        # still use the single check/edit pattern, so only those need
        # prior-state preservation through this dict.
        prior_state = ({k: (v["check"].isChecked(), v["edit"].text()) for k, v in self._sim_angle_state.items() if "check" in v}
                       if same_design else {})
        self._sim_angle_tree_junction = junction
        tree = self.sim_angles_tree
        # Fixes a crash after repeated Run Simulation/Run
        # Angle Diagnostic clicks, especially across several loaded
        # designs: prune every themed widget embedded in the OLD tree
        # (via setItemWidget, at any depth -- finger rows, their
        # deposition-layer children, the "+ Add Deposition" buttons,
        # the verdict/off-axis rows) out of self._themed_widgets before
        # tree.clear() tears the old items down -- see
        # _prune_themed_widgets's own docstring for the full story.
        old_item_widgets = []
        def _collect_item_widgets(item):
            for col in range(tree.columnCount()):
                w = tree.itemWidget(item, col)
                if w is not None:
                    old_item_widgets.append(w)
            for i in range(item.childCount()):
                _collect_item_widgets(item.child(i))
        for i in range(tree.topLevelItemCount()):
            _collect_item_widgets(tree.topLevelItem(i))
        self._prune_themed_widgets(old_item_widgets)
        tree.clear()
        self._sim_angle_state = {}
        if junction is None or not junction.fingers or rec.get("not_set"):
            return

        # Per-pass target thickness is
        # user-set right here, alongside each pass's own angle -- needed
        # to seed a freshly-added pass row with a real, sensible starting
        # number (see junction_import.default_finger_pass_thickness/
        # default_patch_pass_thickness) rather than leaving it blank.
        thickness_params = self._current_recipe_params()

        # ROOT-CAUSE FIX, found against a real
        # 4-finger series-chain design: this used to iterate only the two
        # REPRESENTATIVE recommendations ("first_finger"/"second_finger"),
        # so a 3rd+ finger never got an entry in this loop at all -- and
        # since this loop is what SEEDS self._sim_finger_layers[idx] with
        # that finger's own default angle the first time it's seen (see
        # the comment just below), a chain's higher-indexed fingers never
        # received a seeded default angle here. rec["fingers"] (see
        # compute_recommended_angles' own generalization) holds every
        # finger's own real recommendation, keyed by its real index --
        # iterating sorted indices keeps this deterministic and, for a
        # classic 2-finger design, in the exact same finger-0-then-1
        # order the old ("first_finger", "second_finger") tuple gave.
        for idx in sorted(rec.get("fingers", {}).keys()):
            entry = rec["fingers"][idx]
            fname = ji.finger_display_label(idx)
            default_theta = entry["angles"][0] if entry["angles"] else None
            # A feature's active
            # depositions now live in self._sim_finger_layers directly
            # (a persistent list of floats), not reconstructed from
            # widget checkbox/text state on every rebuild -- this is
            # what actually lets a feature go all the way to ZERO
            # layers (a checkbox-based "off" state doesn't generalize
            # to "remove this specific one of three layers"). The list
            # is seeded from the recommendation the first time this
            # finger is seen; afterward it's the source of truth.
            if idx not in self._sim_finger_layers:
                self._sim_finger_layers[idx] = [default_theta] if default_theta is not None else []
            layers = self._sim_finger_layers[idx]
            finger_obj = junction.fingers[idx]
            # Keep the parallel thickness list in sync with layers,
            # seeding any newly-appeared pass with the auto-computed
            # default for ITS OWN angle (so a fresh design, or a pass
            # added through some other path, always shows a real,
            # sensible number -- never blank).
            thicknesses = self._sim_finger_thicknesses.setdefault(idx, [])
            while len(thicknesses) < len(layers):
                pos = len(thicknesses)
                thicknesses.append(ji.default_finger_pass_thickness(finger_obj, layers[pos], thickness_params))
            del thicknesses[len(layers):]
            item = QTreeWidgetItem(tree, [f"Finger {fname}", ""])
            layer_edits = []
            for pos, theta_val in enumerate(layers):
                layer_item = QTreeWidgetItem(item, [f"Deposition {pos+1}", ""])
                edit, thickness_edit = self._layer_widget_row(
                    tree, layer_item, theta_val,
                    on_edit=lambda text, i=idx, p=pos: self._on_edit_finger_layer(i, p, text),
                    on_remove=lambda _c=False, i=idx, p=pos: self._on_remove_finger_layer(i, p),
                    thickness_value=thicknesses[pos],
                    on_edit_thickness=lambda text, i=idx, p=pos: self._on_edit_finger_thickness(i, p, text),
                    removable=True)
                layer_edits.append(edit)
            add_item = QTreeWidgetItem(item, ["", ""])
            add_btn = QPushButton("+ Add Deposition")
            add_btn.setCursor(Qt.PointingHandCursor)
            add_btn.setStyleSheet("""
                QPushButton { background-color: #22303a; color: #7fc8e6; border: 1px solid #3a5a6a;
                             border-radius: 4px; font-size: 8pt; padding: 2px 8px; }
                QPushButton:hover { background-color: #2a3d4a; }
            """)
            angles = entry.get("angles") or []
            fallback = angles[1] if len(angles) > 1 else (default_theta if default_theta is not None else 0.0)
            fallback_thickness = ji.default_finger_pass_thickness(finger_obj, fallback, thickness_params)
            add_btn.clicked.connect(lambda _c=False, i=idx, t=fallback, th=fallback_thickness:
                                     self._on_add_finger_layer(i, t, th))
            tree.setItemWidget(add_item, 1, add_btn)
            verdict_item = QTreeWidgetItem(item, ["", ""])
            offaxis_item = QTreeWidgetItem(item, ["", ""])
            offaxis_item.setFirstColumnSpanned(True)
            offaxis_item.setForeground(0, QColor("#ffb454"))
            item.setExpanded(True)
            self._sim_angle_state[f"finger_{idx}"] = {
                "finger": junction.fingers[idx], "layer_edits": layer_edits,
                "verdict_item": verdict_item, "offaxis_item": offaxis_item, "default_theta": default_theta,
            }

        patches_rec = rec.get("patches")
        # SIGNIFICANT BUG, fixed here: this
        # was gated on "patches_rec is not None" -- but patches_rec only
        # exists when patches themselves are the electrode-crossing
        # mechanism. Whenever a finger crosses the electrode DIRECTLY
        # instead (confirmed this is common: several real designs tested
        # have warning_source="finger" for both fingers even though
        # patches physically exist as adhesion/connection structures),
        # patches_rec is None and this section was skipped ENTIRELY --
        # patches vanished from the tree completely, with no way to see,
        # customize, or add/remove their deposition layers, even though
        # they still get deposited during both fingers' blanket passes.
        # Now checks whether patches physically EXIST in the design at
        # all, independent of patches_rec, and falls back to both
        # fingers' own active thetas (deduplicated) when there's no
        # patches-specific recommendation -- and uses the SAME
        # persistent layer-list architecture as fingers (self.
        # _sim_patch_layers), so add/remove works here too, which it
        # never did with the old fixed dep1/dep2 checkbox pair.
        has_patches = any(s.kind == "patch" for s in junction.other_shapes)
        if has_patches:
            if self._sim_patch_layers is None:
                if patches_rec is not None:
                    self._sim_patch_layers = list(patches_rec["angles"])
                else:
                    fallback = []
                    for f in junction.fingers:
                        t = f.theta_toward_patch_deg
                        if t not in fallback:
                            fallback.append(t)
                    self._sim_patch_layers = fallback
            if self._sim_patch_thicknesses is None:
                self._sim_patch_thicknesses = []
            patch_default_thickness = ji.default_patch_pass_thickness(thickness_params)
            while len(self._sim_patch_thicknesses) < len(self._sim_patch_layers):
                self._sim_patch_thicknesses.append(patch_default_thickness)
            del self._sim_patch_thicknesses[len(self._sim_patch_layers):]
            item = QTreeWidgetItem(tree, ["Patches", ""])
            layer_edits = []
            for pos, theta_val in enumerate(self._sim_patch_layers):
                layer_item = QTreeWidgetItem(item, [f"Deposition {pos+1}", ""])
                edit, thickness_edit = self._layer_widget_row(
                    tree, layer_item, theta_val,
                    on_edit=lambda text, p=pos: self._on_edit_patch_layer(p, text),
                    on_remove=lambda _c=False, p=pos: self._on_remove_patch_layer(p),
                    thickness_value=self._sim_patch_thicknesses[pos],
                    on_edit_thickness=lambda text, p=pos: self._on_edit_patch_thickness(p, text),
                    removable=True)
                layer_edits.append(edit)
            add_item = QTreeWidgetItem(item, ["", ""])
            add_btn = QPushButton("+ Add Deposition")
            add_btn.setCursor(Qt.PointingHandCursor)
            add_btn.setStyleSheet("""
                QPushButton { background-color: #22303a; color: #7fc8e6; border: 1px solid #3a5a6a;
                             border-radius: 4px; font-size: 8pt; padding: 2px 8px; }
                QPushButton:hover { background-color: #2a3d4a; }
            """)
            fallback_new = self._sim_patch_layers[-1] if self._sim_patch_layers else 0.0
            add_btn.clicked.connect(lambda _c=False, t=fallback_new, th=patch_default_thickness:
                                     self._on_add_patch_layer(t, th))
            tree.setItemWidget(add_item, 1, add_btn)
            verdict_item = QTreeWidgetItem(item, ["", ""])
            if patches_rec is not None:
                note_text = "Recommended: " + ", ".join(f"{a:g}\u00b0" for a in patches_rec["angles"])
                if patches_rec.get("needs_two_depositions"):
                    note_text += " (2 passes)"
            else:
                note_text = "No patch-specific recommendation for this design (a finger crosses " \
                           "the electrode directly) -- defaulted to both fingers' own active angles."
            note = QTreeWidgetItem(item, [note_text, ""])
            item.setExpanded(True)
            self._sim_angle_state["patches"] = {
                "layer_edits": layer_edits, "verdict_item": verdict_item, "is_patches": True,
            }
        self._update_sim_angle_verdicts()

    def _get_active_theta(self, feature_key, fallback=None):
        """The angle actually in effect for this feature right now --
        the typed custom value if Custom is checked, otherwise the
        recommendation. Used by patches (still a single Custom
        checkbox per deposition slot) -- fingers now have a list of
        layers instead (self._sim_finger_layers), read directly by
        whatever needs them rather than through this single-value
        helper."""
        state = self._sim_angle_state.get(feature_key)
        if state is None:
            return fallback
        if state["check"].isChecked():
            try:
                return float(state["edit"].text())
            except ValueError:
                return state["default_theta"] if state["default_theta"] is not None else fallback
        return state["default_theta"] if state["default_theta"] is not None else fallback

    def _update_sim_angle_verdicts(self, *_args):
        """Refreshes each feature's live Warning #1/#2 verdict against
        whatever angle(s) are CURRENTLY active for it -- this is what
        makes typing a custom angle actually useful instead of just
        silently accepted. Fingers can have multiple active layers now
        (or zero), so their verdict covers every layer, and an empty
        list gets its own explicit "not deposited" state rather than
        crashing or silently showing nothing."""
        zero_deposition_features = []
        for key, state in self._sim_angle_state.items():
            if state.get("is_patches"):
                thetas = self._sim_patch_layers or []
                if not thetas:
                    if "verdict_item" in state:
                        state["verdict_item"].setText(0, "\u26a0 NOT DEPOSITED -- no active layers for patches")
                        state["verdict_item"].setForeground(0, QColor("#ff6b6b"))
                    zero_deposition_features.append("Patches")
                    continue
                text = ", ".join(f"{t:g}\u00b0 (dep {i+1})" for i, t in enumerate(thetas))
                if "verdict_item" in state:
                    state["verdict_item"].setForeground(0, QColor(TEXT_COLOR))
                    state["verdict_item"].setText(0, f"Active: {text}")
            elif key.startswith("finger"):
                idx = int(key.split("_")[1])
                thetas = self._sim_finger_layers.get(idx, [])
                finger = state["finger"]
                if not thetas:
                    # Removing a
                    # feature's only deposition layer means it's never
                    # deposited at all -- surfaced here as an explicit
                    # verdict rather than an empty/blank row, so it's
                    # unambiguous this is a deliberate zero-deposition
                    # state, not a UI glitch.
                    if "verdict_item" in state:
                        state["verdict_item"].setText(0, "\u26a0 NOT DEPOSITED -- no active layers for this feature")
                        state["verdict_item"].setForeground(0, QColor("#ff6b6b"))
                    if "offaxis_item" in state:
                        state["offaxis_item"].setHidden(True)
                    fname = ji.finger_display_label(idx)
                    zero_deposition_features.append(f"Finger {fname}")
                    continue
                verdict_parts = []
                worst_off_axis = False
                worst_align = 1.0
                for layer_pos, theta in enumerate(thetas):
                    verdict, off_axis, align = self._evaluate_warnings_at_theta(finger, theta)
                    verdict_parts.append(f"\u03b8={theta:g}\u00b0 (dep {layer_pos+1}): {verdict}")
                    if off_axis and abs(align) < abs(worst_align):
                        worst_off_axis = True
                        worst_align = align
                text = " | ".join(verdict_parts)
                if "verdict_item" in state:
                    state["verdict_item"].setForeground(0, QColor(TEXT_COLOR))
                    state["verdict_item"].setText(0, text)
                if "offaxis_item" in state:
                    if worst_off_axis:
                        pct = round(abs(worst_align) * 100)
                        state["offaxis_item"].setText(0,
                            f"\u26a0 Off-axis layer -- shadowing at only ~{pct}% strength. Full strength at "
                            f"\u03b8={finger.theta_toward_patch_deg:g}\u00b0 or \u03b8={finger.theta_toward_stub_deg:g}\u00b0.")
                        state["offaxis_item"].setHidden(False)
                    else:
                        state["offaxis_item"].setHidden(True)
        # Stored here (not written
        # straight to the label) so _update_sim_shadow_risk can combine
        # these with the SEPARATE post-shadow disconnection warnings
        # (a different, additional category -- a feature can have
        # active layers and still end up geometrically disconnected
        # from what it's supposed to touch) without one overwriting
        # the other.
        self._sim_zero_dep_warnings = list(zero_deposition_features)
        self._refresh_shadow_warnings_label()
        self._refresh_recipe_features()

    @staticmethod
    def _recipe_feature_stable_key(feature, position_within_group):
        """A feature-identity key that survives a PASS-COUNT change --
        fixes a real bug where adding a new deposition step reverted the
        manually-changed angles of any previously-edited deposition step
        back to their original values, forcing every step's angle to be
        re-entered after each insertion. Root cause: _reapply_manual_angle_overrides used
        to match features by (kind, label) -- but junction_import.
        build_simulation_result's own labels embed a mutable "(pass i of
        N)" suffix (e.g. "Deposit patches (pass 1 of 2)"), and N changes
        the instant a new deposition step targeting that same finger/
        patch group is added, even though pass 1 itself didn't move at
        all. That silently changed EVERY existing pass's label at once,
        so none of them matched their old override anymore.

        Fixed by keying on (kind, source_id, position_within_group)
        instead: source_id is the stable_id of the originating finger/
        patch group (unaffected by pass count), and
        position_within_group is this feature's own 0-based rank among
        every OTHER feature sharing the same (kind, source_id) seen so
        far, in list order -- exactly the same enumerate() index
        build_simulation_result itself uses to build the "(pass i of
        N)" label to begin with (see its own active_thetas/
        patches_thetas/mill_thetas loops), so an existing pass keeps its
        same rank when a new one is appended after it, even though N
        (and therefore its label) changes. Falls back to the OLD (kind,
        label) key only when source_id is missing entirely (should not
        happen for any real deposition/mill feature, but keeps this from
        ever raising)."""
        source_id = getattr(feature, "source_id", None)
        if not source_id:
            return (feature.kind, feature.label)
        return (feature.kind, source_id, position_within_group)

    @staticmethod
    def _index_recipe_features_by_stable_key(features):
        """Returns {stable_key: feature} for every feature in `features`,
        assigning position_within_group by walking the list in order and
        counting each (kind, source_id) pair's own occurrences so far --
        see _recipe_feature_stable_key's own docstring for why this
        exactly reproduces build_simulation_result's own per-group pass
        ordering."""
        counts = {}
        by_key = {}
        for f in features:
            group = (f.kind, getattr(f, "source_id", None))
            pos = counts.get(group, 0)
            counts[group] = pos + 1
            by_key[MainWindow._recipe_feature_stable_key(f, pos)] = f
        return by_key

    def _reapply_manual_angle_overrides(self, old_features, new_features):
        """A manual alpha/theta override typed directly onto a feature
        in Simulate Design's "Predicted Recipe Sequence" card (see
        _on_recipe_feature_angle_edited) must survive a fresh geometry
        recompute -- fixes a real bug where hand-changing a
        patch's tilt (e.g. 30 -> 45, for design reasons unrelated to
        this bug) and then
        clicking Generate Recipe silently discarded it, landing the
        OLD tilt in the generated recipe instead. Root cause: both
        _refresh_recipe_features (runs live on every Simulate Design
        edit) and _generate_recipe_from_sim (runs first thing on every
        Generate Recipe click) call junction_import.build_simulation_
        result fresh and replace self._recipe_features wholesale with
        newly-computed, non-overridden features -- an override lives
        only on the OLD feature objects being thrown away, never fed
        back into the geometry recompute itself. Matched by a stable
        (kind, source_id, position_within_group) key -- see
        _recipe_feature_stable_key's own docstring for a SECOND,
        directly-reported bug this same function fixes (matching by
        (kind, label) alone broke the moment a pass-count-dependent
        label changed, e.g. from adding an unrelated new deposition
        step). NOTE: this intentionally changes prior behavior from an
        earlier session (test_recipe_link_and_override.py used to
        assert overrides are cleared on regeneration) -- this direct,
        current report supersedes that: an override the user typed by
        hand must keep applying until they change something that
        actually invalidates it (a design/geometry change removing
        that exact feature), not merely because ANY regeneration ran.

        ALSO carries forward any fully hand-created step inserted via
        _insert_recipe_feature (previously-deferred item #107 --
        source_id == "__manual_insert__"): those steps have no
        corresponding geometry-derived feature to receive an override
        onto, so they must be RE-INSERTED into new_features at (as
        closely as possible) the same relative position, or they would
        be silently dropped on every live regeneration -- which runs on
        every single Simulate Design edit, see _refresh_recipe_features
        -- making the insert feature nearly useless the moment the user
        touched anything else. Anchored to the nearest surviving non-
        manual-insert neighbor's stable key; if that neighbor no longer
        exists either (the geometry change removed it), falls back to
        the old numeric index clamped into the new list rather than
        dropping the insert outright."""
        if not old_features:
            return
        old_by_key = self._index_recipe_features_by_stable_key(old_features)
        overrides = {key: (f.alpha, f.theta) for key, f in old_by_key.items()
                     if getattr(f, "manual_override", False)
                     and getattr(f, "source_id", None) != "__manual_insert__"}

        counts = {}
        for f in new_features:
            group = (f.kind, getattr(f, "source_id", None))
            pos = counts.get(group, 0)
            counts[group] = pos + 1
            key = self._recipe_feature_stable_key(f, pos)
            if key in overrides:
                f.alpha, f.theta = overrides[key]
                f.manual_override = True

        new_key_to_index = {}
        counts = {}
        for idx, f in enumerate(new_features):
            group = (f.kind, getattr(f, "source_id", None))
            pos = counts.get(group, 0)
            counts[group] = pos + 1
            new_key_to_index[self._recipe_feature_stable_key(f, pos)] = idx

        manual_inserts = [(i, f) for i, f in enumerate(old_features)
                           if getattr(f, "source_id", None) == "__manual_insert__"]
        old_index_to_key = {}
        counts = {}
        for idx, f in enumerate(old_features):
            group = (f.kind, getattr(f, "source_id", None))
            pos = counts.get(group, 0)
            counts[group] = pos + 1
            old_index_to_key[idx] = self._recipe_feature_stable_key(f, pos)
        for orig_idx, feat in manual_inserts:
            insert_at = None
            for j in range(orig_idx - 1, -1, -1):
                anchor = old_features[j]
                if getattr(anchor, "source_id", None) == "__manual_insert__":
                    continue
                anchor_key = old_index_to_key[j]
                if anchor_key in new_key_to_index:
                    insert_at = new_key_to_index[anchor_key] + 1
                break
            if insert_at is None:
                for j in range(orig_idx + 1, len(old_features)):
                    anchor = old_features[j]
                    if getattr(anchor, "source_id", None) == "__manual_insert__":
                        continue
                    anchor_key = old_index_to_key[j]
                    if anchor_key in new_key_to_index:
                        insert_at = new_key_to_index[anchor_key]
                    break
            if insert_at is None:
                insert_at = min(orig_idx, len(new_features))
            new_features.insert(insert_at, feat)

    def _sync_sim_layers_from_recipe_features(self):
        """BUG FIX: a second deposition step added to overlap a
        vertical junction finger did not update the
        shadowing on the vertical finger/adhesion plate after re-running the
        shadow simulation. Generalized to all designs since this
        was a systemic disconnect, not a one-off: self._sim_finger_layers/
        _sim_patch_layers are the ONLY state _on_run_simulation_clicked /
        _compute_finger_shadowed_pieces actually read to compute shadow
        geometry, but _insert_recipe_feature/_on_recipe_feature_angle_
        edited/_move_recipe_feature/_delete_recipe_feature (the "Predicted
        Recipe Sequence" card's own edit handlers) only ever mutated
        self._recipe_features -- so ANY edit made there (not just a
        manually-inserted step) had zero effect on the actual shadow
        calculation, only on the recipe text/steps.

        Fix: called from _rebuild_recipe_from_features (the single shared
        tail of all four edit handlers, and of every live regeneration),
        this rebuilds self._sim_finger_layers/_sim_patch_layers from the
        CURRENT self._recipe_features by grouping its deposition-kind
        entries by attribution -- source_id "finger_0"/"finger_1", or
        warning_source == "patches" -- and taking their thetas/thicknesses
        IN ORDER. This is a lossless, order-preserving exact inverse of
        the forward direction: junction_import.build_simulation_result's
        finger and patch loops each emit EXACTLY one deposition
        SimulationFeature per input override theta, in the same order,
        with no per-theta filtering (verified directly against its
        source -- only MILL features are ever filtered there, via
        contact_passes) -- so this can never silently drop a real,
        attributed angle the way a naive round-trip might. A feature with
        no attribution at all (source_id == "__manual_insert__", the
        explicit no-shadow-target/freeform fallback) is intentionally
        excluded here -- it still has no shadow effect, exactly as
        before -- see _insert_deposition_step for how a new
        pass gets real attribution (and therefore a real shadow effect)
        from the moment it's created.

        BUG FIX, found and
        reproduced: raising a patch deposition's own alpha (tilt) here
        from 30 to 45 (theta left unchanged) had ZERO effect on the
        shadow sim/post-deposition view. Root cause: this function
        already extracts feat.theta/feat.thickness_nm into the parallel
        state the shadow math actually reads, but never extracted
        feat.alpha (which _on_recipe_feature_angle_edited DOES update on
        the live SimulationFeature the instant a row's alpha field is
        edited) -- so an edited alpha reached the exported recipe text
        (_rebuild_recipe_from_features's own custom_steps build) but
        never reached _sim_finger_layers-adjacent state, and therefore
        never reached _sim_last_run or any shadow geometry function.
        Fixed by extracting feat.alpha into new_finger_alphas/
        new_patch_alphas, parallel to the existing thickness extraction,
        exactly the same way.

        MAJOR BUG FIX, found and reproduced against
        a real GDS import: reclassifying a misidentified shape via
        the Mark-as-Finger toolbar (which needs to do more than just change
        the color of the shape -- relinking a shape from one classification
        to another should give it the exact treatment of that new
        classification) left the
        newly-corrected finger showing "NO ACTIVE DEPOSITION LAYERS" in
        Simulate Design, even though a fresh recommendation for it (and a
        freshly-seeded self._sim_finger_layers entry) was demonstrably
        non-empty moments earlier in the very same click. Root cause: the
        attribution check below used to be `sid.startswith("finger_")`
        then `idx = int(sid.split("_", 1)[1])` -- silently assuming a
        finger's own stable_id is ALWAYS literally the string "finger_0"/
        "finger_1", the naming convention classify_fingers() happens to
        use for a shape it recognizes as a finger from the start. But
        promote_shape_to_finger (the Mark-as-Finger correction tool)
        deliberately PRESERVES a promoted shape's ORIGINAL stable_id
        (e.g. "other_6") rather than renaming it, specifically so
        selection/measurement caches keyed by that id don't lose track of
        it (see its own docstring). So a reclassified finger's deposition
        passes (source_id="other_6") never matched "finger_" at all here,
        and were silently treated as unattributed -- dropped from
        new_finger_layers entirely. Since this function runs on every
        live recipe regeneration (including the ordinary Run Simulation/
        Run Angle Diagnostic flow via _refresh_recipe_features, not just
        a genuine hand-edit), this ROUND-TRIPPED a correctly-seeded fresh
        recommendation straight back down to an empty list on the very
        same click that seeded it. Fixed by resolving attribution against
        the LIVE junction's own fingers (a real identity lookup by
        stable_id, exactly how every other per-shape cache in this file
        already works) instead of pattern-matching a naming convention
        that a reclassification can -- and, for exactly this reported
        design, does -- break."""
        if not hasattr(self, "_sim_finger_layers"):
            return
        junction = getattr(self, "_sim_cached_junction", None)
        finger_idx_by_stable_id = ({f.stable_id: i for i, f in enumerate(junction.fingers)}
                                    if junction is not None else {})
        new_finger_layers: Dict[int, List[float]] = {}
        new_finger_thicknesses: Dict[int, List[Optional[float]]] = {}
        new_finger_alphas: Dict[int, List[Optional[float]]] = {}
        new_patch_layers: List[float] = []
        new_patch_thicknesses: List[Optional[float]] = []
        new_patch_alphas: List[Optional[float]] = []
        for feat in self._recipe_features:
            if feat.kind != "deposition" or feat.theta is None:
                continue
            sid = getattr(feat, "source_id", None)
            if sid == "__manual_insert__":
                continue
            if sid is not None and sid in finger_idx_by_stable_id:
                # FIX for redundant duplicate
                # recipe steps: a merged shared-pass feature (see
                # build_simulation_result/SimulationFeature.group_source_
                # ids) represents ONE physical pass covering several
                # fingers at once -- an edit to its theta/thickness/alpha
                # here must fan out to EVERY member finger's own shadow-
                # calc state, not just the primary source_id, or a
                # parallel-axis partner would silently stop tracking a
                # hand-edited angle the moment its pass got merged.
                # group_source_ids is None/empty for every pre-existing,
                # unmerged feature, so this loop runs exactly once (just
                # `sid`) and is byte-identical to the old single-id
                # behavior in that overwhelmingly common case.
                for msid in [sid] + list(getattr(feat, "group_source_ids", None) or []):
                    if msid not in finger_idx_by_stable_id:
                        continue
                    idx = finger_idx_by_stable_id[msid]
                    new_finger_layers.setdefault(idx, []).append(feat.theta)
                    new_finger_thicknesses.setdefault(idx, []).append(feat.thickness_nm)
                    new_finger_alphas.setdefault(idx, []).append(feat.alpha)
            elif feat.warning_source == "patches":
                new_patch_layers.append(feat.theta)
                new_patch_thicknesses.append(feat.thickness_nm)
                new_patch_alphas.append(feat.alpha)
        # Found while regression-testing the fix above:
        # this runs from _rebuild_recipe_from_features, which fires on
        # EVERY live regeneration -- including the normal Run Simulation
        # flow itself (via _refresh_recipe_features), not just a genuine
        # hand-edit. Unconditionally calling _mark_sim_stale() here broke
        # "a fresh Run must not immediately show as stale" -- a no-op
        # resync (the common case: nothing actually changed) must not
        # flag staleness. Only mark stale when the rebuilt layers/
        # thicknesses actually differ from what was already there.
        if not hasattr(self, "_sim_finger_alphas"):
            self._sim_finger_alphas = {}
        if not hasattr(self, "_sim_patch_alphas"):
            self._sim_patch_alphas = None
        all_idxs = set(self._sim_finger_layers.keys()) | set(new_finger_layers.keys())
        changed = False
        for idx in all_idxs:
            resolved_layers = new_finger_layers.get(idx, [])
            resolved_thicknesses = new_finger_thicknesses.get(idx, [])
            resolved_alphas = new_finger_alphas.get(idx, [])
            if self._sim_finger_layers.get(idx, []) != resolved_layers:
                changed = True
            if self._sim_finger_thicknesses.get(idx, []) != resolved_thicknesses:
                changed = True
            if self._sim_finger_alphas.get(idx, []) != resolved_alphas:
                changed = True
            self._sim_finger_layers[idx] = resolved_layers
            self._sim_finger_thicknesses[idx] = resolved_thicknesses
            self._sim_finger_alphas[idx] = resolved_alphas
        if self._sim_patch_layers is not None or new_patch_layers:
            if (self._sim_patch_layers or []) != new_patch_layers:
                changed = True
            if (self._sim_patch_thicknesses or []) != new_patch_thicknesses:
                changed = True
            if (self._sim_patch_alphas or []) != new_patch_alphas:
                changed = True
            self._sim_patch_layers = new_patch_layers
            self._sim_patch_thicknesses = new_patch_thicknesses
            self._sim_patch_alphas = new_patch_alphas
        _debug_log(f"SYNC changed={changed} sim_has_run={getattr(self, '_sim_has_run', None)} "
                   f"new_finger_layers={new_finger_layers} new_patch_layers={new_patch_layers}")
        if changed:
            # A MAJOR BEHAVIOR CHANGE: changing an angle or anything else
            # in the predicted order
            # tab should not require reclicking Run Angle
            # Diagnostic and Run Shadow Simulation -- the math should
            # automatically update immediately. Once a design has
            # had its required first Run, a genuine edit here (a
            # Predicted Recipe Sequence angle hand-edit, an inserted/
            # removed/moved deposition step) now recomputes and redraws
            # immediately via _recommit_sim_run instead of only marking
            # the result stale and waiting for the user to click Run
            # again. Before the first Run, nothing has been committed
            # yet at all, so this still just marks pending (the user only
            # ever needs to click Run once per design).
            if getattr(self, "_sim_has_run", False):
                self._recommit_sim_run()
            else:
                self._mark_sim_stale()
            # BUG FIX, found and reproduced against
            # a real patch-integrated design where deleting the
            # theta=180deg second patch pass, then clicking Insert Step
            # right after the 0-degree first patch deposition pass,
            # placed the new step right after the
            # second finger deposition pass instead, and AGAIN against a
            # second real design after the first fix below still left a gap: the
            # first fix only called _refresh_recipe_features from INSIDE
            # the `if self._sim_has_run:` branch above (reasoning: that
            # branch already reaches back to it indirectly via
            # _recommit_sim_run -> _update_simulate_preview's `if self.
            # _sim_angle_diagnostic_run:` gate -> _rebuild_sim_angles_tree
            # -> _update_sim_angle_verdicts -> _refresh_recipe_features,
            # so it seemed like only that path needed a direct,
            # unconditional call to stop depending on that unrelated
            # gate). But self._recipe_features's own freshness has NO
            # dependency on self._sim_has_run either -- a design that has
            # only had "Run Angle Diagnostic" clicked (never "Run Shadow
            # Simulation" -- letting the angle diagnostic generate
            # the predicted recipe steps on its own)
            # takes the `else: self._mark_sim_stale()` branch above
            # instead, which never reaches _refresh_recipe_features at
            # all -- so self._recipe_features still froze at whatever the
            # raw list mutation alone left behind (e.g. a deleted
            # deposition pass's own now-redundant "Mill before patches
            # (pass 2 of 2)" mill sub-step staying displayed with its
            # stale pre-delete label) every time _sim_has_run happened to
            # be False at the moment of the edit -- reproduced directly.
            # A later Insert Step click then computes its own target
            # scope and local insert position against this stale,
            # un-regenerated list. Fixed by moving the direct refresh
            # call OUT of the `if self._sim_has_run:` branch entirely, so
            # self._recipe_features is kept fresh on every genuine layer-
            # state change regardless of whether a shadow Run has been
            # committed yet -- exactly mirroring how _recommit_sim_run/
            # _mark_sim_stale above are the ONLY things gated on self.
            # _sim_has_run (whether the Post-Shadow Result geometry itself
            # gets recomputed immediately vs. marked pending), never the
            # Predicted Recipe Sequence display itself. Bounded by the
            # same reentrancy depth cap _recommit_sim_run already uses for
            # this exact recursive shape (this reaches back into
            # _rebuild_recipe_from_features -> this same method), and
            # gated on real junction geometry being present -- _refresh_
            # recipe_features's own guard wipes self._recipe_features to
            # [] whenever no junction is cached at all, which is correct
            # for a genuinely gone design but would wrongly erase a
            # deliberate freeform/no-shadow-target step (_insert_recipe_
            # feature's own documented fallback, used exactly BECAUSE
            # there's no junction) the instant one is added with no
            # junction cached -- confirmed via test_add_deposition_step_
            # all_targets.py's own no-junction-fallback check.
            junction = getattr(self, "_sim_cached_junction", None)
            if junction is not None and junction.fingers:
                depth = getattr(self, "_sim_recompute_depth", 0)
                _debug_log(f"SYNC direct-refresh-call check: junction_present=True depth={depth} "
                           f"cap={self._SIM_RECOMPUTE_DEPTH_CAP}")
                if depth < self._SIM_RECOMPUTE_DEPTH_CAP:
                    self._sim_recompute_depth = depth + 1
                    try:
                        self._refresh_recipe_features()
                    finally:
                        self._sim_recompute_depth = depth
                else:
                    _debug_log("SYNC direct-refresh-call SKIPPED -- depth cap reached")
            else:
                _debug_log(f"SYNC direct-refresh-call SKIPPED -- junction={junction!r} "
                           f"fingers={getattr(junction, 'fingers', None) if junction is not None else None}")

    def _refresh_recipe_features(self):
        """Keeps self._recipe_features -- the full mill/deposition/
        oxidation PLACEMENT sequence, not just per-feature angles -- in
        sync with whatever the user currently has set in the Deposition
        Angles (per feature) tree above.
        This prediction used to only run once the user clicked "Generate
        Recipe from Simulation" over on the Recipe tab; now it runs live,
        right here, every time _update_sim_angle_verdicts runs (i.e.
        after every layer/patch add/remove/edit -- see that method's own
        callers), so mill/oxidation placement is visible and editable in
        Simulate Design itself. The Recipe tab's "Generate Recipe" then
        just reads self._recipe_features as already-decided, rather than
        recomputing it. Mirrors exactly what _generate_recipe_from_sim
        used to compute (kept for backward compatibility -- it still
        works, it's just no longer the only path that populates this)."""
        if not hasattr(self, "sim_feature_sequence_layout"):
            _debug_log("REFRESH_FEATURES early-return: no sim_feature_sequence_layout attribute yet")
            return
        junction = self._sim_cached_junction
        if junction is None or not junction.fingers or any(f.deposited_second is None for f in junction.fingers):
            _debug_log(f"REFRESH_FEATURES WIPE to [] -- junction={junction!r} "
                       f"fingers={getattr(junction, 'fingers', None) if junction is not None else None} "
                       f"deposited_second={[getattr(f, 'deposited_second', 'N/A') for f in junction.fingers] if junction is not None and junction.fingers else 'N/A'}")
            self._recipe_features = []
            self._recipe_sim_result = None
            self._rebuild_recipe_from_features()
            return
        params = self._current_recipe_params()
        disconnection_notes = list(getattr(self, "_sim_disconnection_warnings", []) or [])
        sim_result = ji.build_simulation_result(
            junction, params, disconnection_notes=disconnection_notes,
            finger_layer_overrides=dict(self._sim_finger_layers),
            patch_layer_overrides=(list(self._sim_patch_layers) if self._sim_patch_layers is not None else None),
            finger_thickness_overrides=dict(self._sim_finger_thicknesses),
            patch_thickness_overrides=(list(self._sim_patch_thicknesses) if self._sim_patch_thicknesses is not None else None),
        )
        old_features = self._recipe_features
        if sim_result.not_set:
            _debug_log("REFRESH_FEATURES sim_result.not_set -- wiping to []")
            self._recipe_features = []
            self._recipe_sim_result = None
        else:
            self._recipe_sim_result = sim_result
            self._recipe_features = list(sim_result.features)
            self._recipe_generated_fingerprint = sim_result.fingerprint
            _debug_log(f"REFRESH_FEATURES regenerated -- finger_overrides={dict(self._sim_finger_layers)} "
                       f"patch_overrides={list(self._sim_patch_layers) if self._sim_patch_layers is not None else None} "
                       f"new_labels={[f.label for f in self._recipe_features]} "
                       f"new_source_ids={[f.source_id for f in self._recipe_features]}")
            self._reapply_manual_angle_overrides(old_features, self._recipe_features)
            _debug_log(f"REFRESH_FEATURES after reapply-overrides -- "
                       f"labels={[f.label for f in self._recipe_features]}")
        self._rebuild_recipe_from_features()

    def _refresh_shadow_warnings_label(self):
        if not hasattr(self, "sim_shadow_warnings_label"):
            return
        zero_dep = getattr(self, "_sim_zero_dep_warnings", [])
        disconnections = getattr(self, "_sim_disconnection_warnings", [])
        lines = []
        if zero_dep:
            names = ", ".join(zero_dep)
            lines.append(f"\u26a0 {names} {'has' if len(zero_dep)==1 else 'have'} no active deposition "
                        f"layers and will not appear in the Post-Shadow Result.")
        if disconnections:
            for w in disconnections:
                lines.append(f"\u26a0 {w}")
        if lines:
            self.sim_shadow_warnings_label.setText("\n\n".join(lines))
            self.sim_shadow_warnings_label.setStyleSheet("color: #ff6b6b; font-size: 9pt; font-weight: bold;")
        else:
            self.sim_shadow_warnings_label.setText("No zero-deposition features or post-shadow disconnections.")
            self._themed(self.sim_shadow_warnings_label, lambda: f"color: {TEXT_COLOR}; font-size: 9pt;")

    def _mark_sim_stale(self, *_args):
        """(Previously-deferred item #105):
        the single place that flags "whatever Simulated Design / Post-
        Shadow Result is currently showing no longer matches the design's
        current settings" -- called from every input that can invalidate
        a committed Run (active alpha, per-layer angle/thickness add/
        edit/remove for either fingers or patches, and which finger
        deposits first), not just the Active-alpha field the old "\u2022"-only
        version covered. Deliberately does NOT trigger a redraw itself --
        Run Shadow Simulation stays an explicit click, per the earlier,
        separate direct request that typing alone must not fire the
        (potentially slow) shadow calculation."""
        if hasattr(self, "sim_run_button") and getattr(self, "_sim_has_run", False):
            self._sim_stale = True
        if hasattr(self, "sim_run_button"):
            self.sim_run_button.setText(
                "\u25b6 Run Shadow Simulation \u2022" if not self._sim_has_run else "\u25b6 Run Simulation \u2022")
        self._refresh_sim_stale_banner()

    def _refresh_sim_stale_banner(self):
        """Shows/hides the prominent banner above Simulate Design's
        canvas (see its construction in _build_simulate_tab) -- visible
        only while there's actually something stale to warn about: a Run
        has happened, something changed since, AND the view currently
        being shown is one that a stale Run would misrepresent (Optimal
        Design doesn't depend on a committed Run at all, so it's exempt)."""
        if not hasattr(self, "sim_stale_banner"):
            return
        show = bool(self._sim_stale) and getattr(self, "_sim_has_run", False) \
            and self._sim_view_mode in ("simulated", "postshadow")
        if show:
            self.sim_stale_banner.setText(
                "\u26a0 Stale -- a parameter changed since the last Run. This view still reflects the "
                "OLD committed angles/thicknesses; click \u25b6 Run Shadow Simulation to update it.")
        self.sim_stale_banner.setVisible(show)

    def _on_sim_override_edited(self, *_args):
        """Active alpha is a real physical process parameter (the wafer
        tilt actually used in the chamber), exactly like the resist
        stack/electrode height fields _on_resist_stack_changed already
        treats as live -- a MAJOR BEHAVIOR CHANGE
        reversing an earlier explicit decision that typing
        here must never auto-redraw: a change to the resist or
        electrode thicknesses should not require the user to
        reclick anything, the math should automatically update
        immediately as they type. Unlike the resist stack fields (read live from
        their own QLineEdit every time regardless of any snapshot),
        alpha IS snapshotted into self._sim_last_run at commit time (it
        has to be -- Run Simulation's whole "committed angles" concept
        includes which alpha they were computed against), so simply
        redrawing isn't enough here: _recommit_sim_run rebuilds that
        snapshot from the current field value first. Before the
        design's required first Run, there is nothing to recommit yet,
        so this still just marks the pending cue -- the user only ever
        needs to click Run once per design."""
        if getattr(self, "_sim_has_run", False):
            self._recommit_sim_run()
        else:
            self._mark_sim_stale()

    def _set_sim_view_mode(self, mode):
        self._sim_view_mode = mode
        self.sim_view_optimal_btn.setChecked(mode == "optimal")
        self.sim_view_simulated_btn.setChecked(mode == "simulated")
        self.sim_view_postshadow_btn.setChecked(mode == "postshadow")
        if self._sim_cached_junction is not None:
            self._update_simulate_preview(self._sim_cached_junction, self._sim_cached_report)
        self._refresh_sim_stale_banner()  # item #105 -- banner only applies to simulated/postshadow views

    def _on_resist_stack_changed(self, *_args):
        """Resist stack thickness (PMMA,
        PMGI, electrode height) is a PHYSICAL PARAMETER, not a
        hypothetical angle to test -- unlike theta overrides (which
        intentionally require an explicit Run Simulation click), a
        thickness change should propagate immediately to whatever
        simulation is already showing, with no extra click. This works
        because the drawing functions already read these fields live
        each time they run (not from a cached snapshot) -- so simply
        triggering a redraw here, without touching _sim_last_run's
        committed angles at all, is enough."""
        if getattr(self, "_sim_has_run", False) and self._sim_cached_junction is not None:
            self._update_simulate_preview(self._sim_cached_junction, self._sim_cached_report)

    def _on_toggle_angle_panel(self, checked):
        if hasattr(self, "sim_angle_panel"):
            self.sim_angle_panel.setVisible(checked)

    def _on_toggle_sim_right_panel(self, checked):
        if hasattr(self, "sim_right_panel"):
            self.sim_right_panel.setVisible(checked)

    def _on_run_angle_diagnostic_clicked(self):
        """Step 1 of the two-step workflow: computes and reveals the
        recommendations, warnings, and per-feature angle tree (with
        live verdicts) -- these were already computed automatically
        before, just gated behind this explicit click now, per direct
        request for a guided sequence. Enables Run Shadow Simulation,
        which stays disabled until this has run at least once."""
        self._sim_angle_diagnostic_run = True
        self.sim_run_button.setEnabled(True)
        if self._sim_cached_junction is not None:
            self._populate_sim_recommendations_tree(self._sim_cached_junction)
            self._populate_sim_warnings_tree(self._sim_cached_junction)
            rec = ji.compute_recommended_angles(self._sim_cached_junction) if self._sim_cached_junction.fingers else {"not_set": True}
            self._rebuild_sim_angles_tree(self._sim_cached_junction, rec)
        # Clicking Run Angle Diagnostic used to
        # visibly do nothing until the user separately clicked
        # Simulated Design -- auto-switching to that view here means
        # the newly-revealed warnings/recommendations are immediately
        # visible, giving the click actual feedback instead of looking
        # like a no-op.
        self._set_sim_view_mode("simulated")

    def _recommit_sim_run(self):
        """Rebuilds self._sim_last_run from the CURRENT
        self._sim_finger_layers/_sim_patch_layers/Active-alpha field and
        redraws -- the actual recompute step, factored out of
        _on_run_simulation_clicked so it can also be called
        automatically once a design's first Run has already happened.

        A MAJOR BEHAVIOR CHANGE, reversing
        an earlier explicit design decision (item #105: Run Shadow
        Simulation must stay an explicit click, not fire on every
        keystroke): once a design already has a committed Run, a further
        change made within the simulation tab
        should not require reclicking Run Angle Diagnostic and
        Run Shadow Simulation again -- the math should automatically
        update immediately as the user edits it, so they only ever need to
        click Run Angle Diagnostic and Run Shadow Simulation once per design.
        This is now the single shared recompute step called both by the
        Run Simulation button itself (the required FIRST click for a
        design) and automatically thereafter -- see
        _sync_sim_layers_from_recipe_features (a Predicted Recipe
        Sequence angle edit), _on_resist_stack_changed (PMMA/PMGI/
        electrode height), and _on_sim_override_edited (Active alpha) --
        each of which now calls this directly instead of merely marking
        the result stale, but ONLY once self._sim_has_run is already
        True for the current design (the very first Run for a design
        still requires the explicit click)."""
        def get_float(edit, fallback):
            try:
                return float(edit.text())
            except (ValueError, AttributeError):
                return fallback
        # Patches now use the same
        # persistent layer-list architecture as fingers (self.
        # _sim_patch_layers), supporting add/remove, and always
        # populated even when patches_rec is None (a finger, not
        # patches, crosses the electrode) -- reading it directly here
        # instead of reconstructing from the old fixed dep1/dep2
        # checkbox pair, which never supported add/remove at all.
        patch_thetas_override = list(self._sim_patch_layers) if self._sim_patch_layers is not None else None
        # Parallel per-pass alpha lists, mirroring
        # theta_a_list/theta_b_list/patch_thetas_override exactly -- this is what
        # finally lets a Predicted-Recipe-Sequence alpha edit (already correctly
        # captured into self._sim_finger_alphas/_sim_patch_alphas by
        # _sync_sim_layers_from_recipe_features) reach the shadow math at all.
        # "alpha" (the Active-alpha field) is DELIBERATELY kept as-is below -- it
        # remains the fallback default for any pass whose own per-pass alpha
        # entry is missing or shorter than its theta list (e.g. a pass added
        # directly via the Deposition Angles tree, which has no per-pass alpha
        # editor of its own yet), never removed or repurposed.
        finger_alphas = getattr(self, "_sim_finger_alphas", {}) or {}
        patch_alphas = getattr(self, "_sim_patch_alphas", None)
        self._sim_last_run = {
            "alpha": get_float(self.sim_alpha_override_edit, 30.0),
            "theta_a": self._sim_finger_layers.get(0, [None])[0] if self._sim_finger_layers.get(0) else None,
            "theta_b": self._sim_finger_layers.get(1, [None])[0] if self._sim_finger_layers.get(1) else None,
            "theta_a_list": list(self._sim_finger_layers.get(0, [])),
            "theta_b_list": list(self._sim_finger_layers.get(1, [])),
            "patch_thetas_override": patch_thetas_override,
            "theta_a_alphas": list(finger_alphas.get(0, [])),
            "theta_b_alphas": list(finger_alphas.get(1, [])),
            "patch_alphas_override": list(patch_alphas) if patch_alphas is not None else None,
            # ROOT-CAUSE FIX, found
            # against a real 4-finger series-chain design (a layered
            # Manhattan junction array): theta_a_list/theta_b_list above
            # only ever capture finger index 0/1's own history --
            # _sim_finger_layers has ALWAYS correctly stored every
            # finger's own theta history by its real index, but nothing
            # downstream ever read past index 1, so index 2 ("Finger C"),
            # 3 ("Finger D"), etc. were silently evaluated against Finger
            # B's own angle instead of their own. finger_theta_lists (and
            # its alpha counterpart) is a full copy of that same source,
            # read first by every _run_finger_thetas/_run_finger_alphas
            # call site in this file -- theta_a_list/theta_b_list are
            # kept, byte-identical, purely for backward compatibility
            # (every small synthetic single-pass `run` dict elsewhere in
            # this file, plus any test that builds a `run` by hand).
            "finger_theta_lists": {idx: list(lst) for idx, lst in self._sim_finger_layers.items()},
            "finger_alpha_lists": {idx: list(lst) for idx, lst in finger_alphas.items()},
        }
        self._sim_stale = False  # item #105 -- this Run now matches everything currently set
        if hasattr(self, "sim_run_button"):
            self.sim_run_button.setText("\u25b6 Run Simulation")
        self._refresh_sim_stale_banner()
        # CRASH FIX: found after a report of the program crashing during
        # heavy interactive use, especially after repeatedly
        # hand-editing angles, clicking buttons, and adjusting recipes.
        # Root cause, confirmed
        # by direct tracing: this call below re-enters the exact live-
        # auto-recompute chain that got US here in the first place --
        # _update_simulate_preview -> _rebuild_sim_angles_tree ->
        # _update_sim_angle_verdicts -> _refresh_recipe_features ->
        # _rebuild_recipe_from_features -> _sync_sim_layers_from_recipe_
        # features -> (if it finds the layer state it just extracted
        # differs at all from what's currently set) -> back to
        # _recommit_sim_run -> back to here. In the common case this
        # settles after exactly one bounce (the second pass's extraction
        # matches what was just fed in, so "changed" goes False) -- but
        # nothing ever guaranteed that convergence, and no reentrancy
        # guard existed anywhere in this chain (confirmed: no
        # _in_recompute/_recompute_guard/_updating_sim-style flag exists
        # in this file). A compounding sequence of hand-edits/clicks can
        # make _reapply_manual_angle_overrides or build_simulation_result
        # land on a genuinely different feature order/attribution on
        # successive passes, which never settles -- an unbounded mutual
        # recursion, each lap several frames deep, that eventually blows
        # the interpreter's recursion limit (RecursionError) or, since
        # much of this happens inside Qt paint/layout callbacks, a hard
        # native crash rather than a catchable Python exception.
        #
        # Fixed with a small bounded depth counter around the one edge
        # that actually closes the loop (this call). The common
        # (converges-in-1-bounce) case is completely unaffected --
        # _SIM_RECOMPUTE_DEPTH_CAP gives a generous margin above that.
        # If some pathological edit sequence genuinely never converges,
        # this guarantees a hard, shallow stop instead of an unbounded
        # crash: the redraw simply settles for the last-computed state
        # rather than chasing a moving target forever, and the next
        # explicit user action (another edit, another click) gets a
        # fully fresh recompute as normal.
        depth = getattr(self, "_sim_recompute_depth", 0)
        if self._sim_cached_junction is not None and depth < self._SIM_RECOMPUTE_DEPTH_CAP:
            self._sim_recompute_depth = depth + 1
            try:
                self._update_simulate_preview(self._sim_cached_junction, self._sim_cached_report)
            finally:
                self._sim_recompute_depth = depth

    def _on_run_simulation_clicked(self):
        """Commits whatever's currently typed in the override fields as
        the ACTIVE simulation angles for the FIRST time on this design,
        switches to Simulated Design view automatically (so clicking Run
        naturally shows the result), and redraws using these committed
        values. This remains the one required manual click per design --
        see _recommit_sim_run's own docstring for how every SUBSEQUENT
        change auto-recomputes from here on, without needing this
        button again."""
        self._sim_has_run = True
        self._recommit_sim_run()
        self._set_sim_view_mode("simulated")  # triggers the redraw (and refreshes the stale banner)

    def _check_jj_crossing_overlap(self, tree, junction, run, theta_overrides, alpha, dx_um, dy_um, add_row):
        """Verified directly against real geometry on
        multiple test files before trusting it: computes the two
        crossing fingers' own POST-SHADOW polygons (the exact same
        helper Post-Shadow Result itself uses, so this can never show
        a different verdict than what's actually rendered) and
        intersects them directly, rather than a 1D nominal-length
        formula that ignored which theta(s) were actually active."""
        if len(junction.fingers) < 2:
            return
        f0, f1 = junction.fingers[0], junction.fingers[1]
        pieces0 = self._compute_finger_shadowed_pieces(junction, f0, 0, run, theta_overrides, alpha, dx_um, dy_um)
        pieces1 = self._compute_finger_shadowed_pieces(junction, f1, 1, run, theta_overrides, alpha, dx_um, dy_um)
        item = QTreeWidgetItem(["JJ Crossing Overlap", ""])
        tree.addTopLevelItem(item)
        if not pieces0 or not pieces1:
            missing = []
            if not pieces0:
                missing.append("Finger A")
            if not pieces1:
                missing.append("Finger B")
            item.setText(1, f"\u2717 FAILS -- {' and '.join(missing)} not deposited (zero active layers)")
            item.setForeground(1, QBrush(QColor("#ff5c5c")))
            return
        try:
            poly0 = so.unary_union([sg.Polygon(p) for p in pieces0])
            poly1 = so.unary_union([sg.Polygon(p) for p in pieces1])
            overlap = poly0.intersection(poly1)
            overlap_area = overlap.area if not overlap.is_empty else 0.0
        except Exception:
            overlap_area = 0.0
        # A tiny nonzero area from floating-point boundary noise
        # shouldn't count as "survives" -- verified the two fingers'
        # NOMINAL (undrawn) polygons already overlap by ~0.13 um^2 on
        # real geometry, so a genuine threshold well below that (not
        # simply > 0) is needed to distinguish real contact from noise.
        is_safe = overlap_area > 1e-4
        verdict = "\u2713 survives" if is_safe else "\u2717 FAILS"
        color = "#8fd694" if is_safe else "#ff5c5c"
        item.setText(1, f"{verdict} (post-shadow overlap area: {overlap_area:.4f} \u00b5m\u00b2)")
        item.setForeground(1, QBrush(QColor(color)))
        add_row(item, "Finger A active layers", ", ".join(f"{t:g}\u00b0" for t in (run.get("theta_a_list") or ([run.get("theta_a")] if run.get("theta_a") is not None else []))) or "none")
        add_row(item, "Finger B active layers", ", ".join(f"{t:g}\u00b0" for t in (run.get("theta_b_list") or ([run.get("theta_b")] if run.get("theta_b") is not None else []))) or "none")
        # Restoring the same worst-case/
        # best-case detail level the old 1D formula used to show,
        # computed the CORRECT way this time -- real geometric overlap
        # at each finger's own two axis-aligned options. NOT labeled
        # "worst"/"best" -- verified directly that which one is
        # actually worse depends on WHERE the crossing sits relative to
        # each finger's own geometry (on one real design the crossing sits
        # near both fingers' stub ends, while on another it sits quite
        # differently), so a fixed
        # "stub=worst, patch=best" labeling would be actively wrong on
        # some real designs. Both are shown, neutrally described by
        # which angle produced them, letting the actual numbers speak.
        try:
            stub_run = {"theta_a_list": [f0.theta_toward_stub_deg], "theta_b_list": [f1.theta_toward_stub_deg]}
            sp0 = self._compute_finger_shadowed_pieces(junction, f0, 0, stub_run, [None, None], alpha, dx_um, dy_um)
            sp1 = self._compute_finger_shadowed_pieces(junction, f1, 1, stub_run, [None, None], alpha, dx_um, dy_um)
            stub_area = so.unary_union([sg.Polygon(p) for p in sp0]).intersection(
                so.unary_union([sg.Polygon(p) for p in sp1])).area if sp0 and sp1 else 0.0
        except Exception:
            stub_area = None
        try:
            patch_run = {"theta_a_list": [f0.theta_toward_patch_deg], "theta_b_list": [f1.theta_toward_patch_deg]}
            pp0 = self._compute_finger_shadowed_pieces(junction, f0, 0, patch_run, [None, None], alpha, dx_um, dy_um)
            pp1 = self._compute_finger_shadowed_pieces(junction, f1, 1, patch_run, [None, None], alpha, dx_um, dy_um)
            patch_area = so.unary_union([sg.Polygon(p) for p in pp0]).intersection(
                so.unary_union([sg.Polygon(p) for p in pp1])).area if pp0 and pp1 else 0.0
        except Exception:
            patch_area = None
        add_row(item, "Nominal (undrawn) overlap area", f"{sg.Polygon(f0.points).intersection(sg.Polygon(f1.points)).area:.4f} \u00b5m\u00b2")
        add_row(item, "Post-shadow overlap area (active angles)", f"{overlap_area:.4f} \u00b5m\u00b2")
        if stub_area is not None:
            add_row(item, f"Overlap if both at theta_toward_stub ({f0.theta_toward_stub_deg:g}\u00b0/{f1.theta_toward_stub_deg:g}\u00b0)", f"{stub_area:.4f} \u00b5m\u00b2")
        if patch_area is not None:
            add_row(item, f"Overlap if both at theta_toward_patch ({f0.theta_toward_patch_deg:g}\u00b0/{f1.theta_toward_patch_deg:g}\u00b0)", f"{patch_area:.4f} \u00b5m\u00b2")

    def _check_post_shadow_disconnections(self, junction, report, run, theta_overrides, alpha, dx_um, dy_um):
        """A dedicated check for
        shapes that end up geometrically disconnected from each other
        in the actual post-shadow result -- distinct from the zero-
        deposition warning (a feature can have active layers and still
        end up disconnected from what it's supposed to touch, purely
        from shadow shrinkage). Checks three real connection types
        using the SAME post-shadow geometry Post-Shadow Result itself
        renders (via _compute_finger_shadowed_pieces and
        _compute_post_shadow_shapes), so this can never disagree with
        what's actually drawn: (1) a finger split into multiple pieces
        by its own electrode-crossing shadow, (2) the JJ crossing
        overlap between the two fingers, (3) a finger's own connection
        to its associated adhesion plate. A finger-to-PATCH connectivity
        check deliberately does NOT belong here -- see
        _check_patch_contact_disconnections' docstring for why a
        patch-vs-finger touching test is the wrong model for that
        (multi-patch groups are legitimately NOT meant to touch the
        finger, or each other, directly in real designs; a patch reaches
        the rest of the circuit through the shared adhesion plate/
        electrode instead). Returns a list of specific, named warning
        strings."""
        warnings = []
        try:
            pieces_by_finger = []
            for i, f in enumerate(junction.fingers):
                pieces = self._compute_finger_shadowed_pieces(junction, f, i, run, theta_overrides, alpha, dx_um, dy_um)
                pieces_by_finger.append(pieces)
                fname = ji.finger_display_label(i)
                if len(pieces) > 1:
                    warnings.append(f"Finger {fname} shadows into {len(pieces)} disconnected pieces at the active angle(s).")

            # GENERALIZATION for series-chain
            # designs: this used to check ONLY the finger-0/finger-1
            # pair, regardless of how many real JJ crossings the design
            # actually has. find_all_finger_crossings identifies every
            # REAL pairwise finger-polygon overlap from the base (nominal,
            # pre-shadow) design geometry -- the correct list of "which
            # pairs are actually supposed to form a junction" -- and each
            # one is checked here against its own POST-SHADOW pieces, so
            # a 4-finger chain (3 real crossings) gets 3 independent
            # continuity checks instead of just one. A classic 2-finger
            # design still resolves to exactly [(0, 1)] (and, same as
            # before, is still checked even if the base fingers don't
            # overlap at all, so a broken 2-finger design keeps warning).
            crossing_pairs = ji.find_all_finger_crossings(junction.fingers)
            if len(junction.fingers) == 2 and not crossing_pairs:
                crossing_pairs = [(0, 1)]
            for ci, cj in crossing_pairs:
                if not pieces_by_finger[ci] or not pieces_by_finger[cj]:
                    continue
                try:
                    poly_i = so.unary_union([sg.Polygon(p) for p in pieces_by_finger[ci]])
                    poly_j = so.unary_union([sg.Polygon(p) for p in pieces_by_finger[cj]])
                    overlap_area = poly_i.intersection(poly_j).area
                    if overlap_area <= 1e-4:
                        label_i, label_j = ji.finger_display_label(ci), ji.finger_display_label(cj)
                        warnings.append(f"Finger {label_i} and Finger {label_j} are disconnected at the JJ crossing after shadowing.")
                except Exception:
                    pass

            for i, f in enumerate(junction.fingers):
                associated = self._find_associated_plate(junction, f)
                if associated is None or not pieces_by_finger[i]:
                    continue
                plate_shape = associated[0]
                fname = ji.finger_display_label(i)
                try:
                    finger_poly = so.unary_union([sg.Polygon(p) for p in pieces_by_finger[i]])
                    # This used to search
                    # _compute_post_shadow_shapes' flat output for "the
                    # plate whose finger is f" -- but nothing in that
                    # list ties a returned points-list back to which
                    # source shape produced it, so the search always
                    # grabbed the FIRST plate entry regardless of which
                    # one was actually wanted, comparing finger B
                    # against finger A's own plate. Computing this
                    # specific plate's own points directly (unambiguous
                    # by construction) instead of trying to match one
                    # back out of an unordered list.
                    plate_pts = self._compute_plate_shadowed_points(junction, plate_shape, run, theta_overrides, alpha, dx_um, dy_um)
                    if plate_pts is not None:
                        plate_poly = sg.Polygon(plate_pts)
                        if finger_poly.distance(plate_poly) > 1e-4:
                            warnings.append(f"Finger {fname} is disconnected from its adhesion plate after shadowing.")
                except Exception:
                    pass
        except Exception:
            pass
        return warnings

    def _min_axis_offset_deg(self, theta_deg, axis_deg):
        """How far theta_deg sits off the UNDIRECTED line through
        axis_deg, in [0, 90] -- axis_deg is a drawn feature's own axis
        heading (e.g. 315deg), which is physically the SAME line as
        axis_deg+180 (135deg), so 300deg is exactly as far off that line
        as 120deg is (both 15deg away). Returns 0 for theta exactly on
        (or exactly opposite) the axis, 90 for theta exactly
        perpendicular to it -- this is precisely the angle whose sine
        _apply_cross_axis_shadow's shrink scales with, extracted here
        purely for HUMAN-READABLE reporting in warning text (see the
        fix on the message below)."""
        mod180 = (theta_deg - axis_deg) % 180.0
        return min(mod180, 180.0 - mod180)

    def _check_cross_axis_self_shadow_warnings(self, junction, report, run, theta_overrides, alpha, dx_um, dy_um):
        """A warning validated against a real
        SEM failure: patches drawn along 135/315 deg but deposited
        at 45/225 deg -- 90 deg off, completely orthogonal to the patch
        design -- produced a real fabricated result with NO patches at all,
        just bare 'stumps', because the shadow throw crossed their entire
        linewidth instead of nibbling their tips (see the new
        _apply_cross_axis_shadow, now wired into both
        _compute_finger_shadowed_pieces and
        _compute_one_patch_shadowed_pieces). Generalized so that
        this is not hardcoded to patches or to a
        90 deg mismatch: it fires for ANY finger or patch whose ACTIVE
        committed deposition angle(s) fully self-shadow it this way, at
        any angle, so the user sees this warning BEFORE fabrication
        (right here in the shadow-risk tree) instead of discovering it
        only after an SEM comes back wrong.

        BUG FIX, found against a real design
        where changing Finger
        A's committed deposition angle from 315deg (its own drawn axis)
        to 300deg -- only 15deg off -- fully self-shadowed it, and this
        warning's message flatly called that "nearly perpendicular,"
        which was inaccurate (15deg
        is nowhere near 90deg). Fixed by reporting the REAL measured
        offset (via _min_axis_offset_deg) instead of a canned phrase, so
        the message is honest for a 90deg mismatch AND for a small one,
        whenever a genuine full self-shadow does occur.

        PARTIAL RETRACTION, from a LATER pass (see
        test_cross_axis_directional_shadow.py): this docstring originally
        also claimed that design's 315/300 full-vanish OUTCOME was itself
        correct physics (re-verified against a ~6.6deg tolerance for that
        design's real numbers), and that only the message wording was
        wrong. That verification was run against a SECOND, since-fixed
        bug in _apply_cross_axis_shadow / _cross_axis_boundaries: a
        single deposition pass was shrinking BOTH of a feature's long
        edges at once, when a single directional deposition can only
        shadow ONE edge (confirmed directly against a real report that
        two shadows were coming in from either side when only one was
        expected, since a single deposition should be one-sided). Once
        that directional bug
        was fixed too, that same real 315/300 case no longer fully vanishes
        at all (it survives with roughly a third of its nominal area,
        shifted toward one edge) -- so this warning now correctly stays
        SILENT for that exact scenario. The wording fix here remains
        correct and still matters whenever an offset genuinely IS large
        enough to fully self-shadow a feature under the now-corrected
        directional model."""
        warnings = []
        for i, f in enumerate(junction.fingers):
            thetas = self._run_finger_thetas(run, i, f, theta_overrides)
            if not thetas:
                continue  # zero active layers -- already covered by the separate zero-deposition warning
            try:
                pieces = self._compute_finger_shadowed_pieces(junction, f, i, run, theta_overrides, alpha, dx_um, dy_um)
            except Exception:
                continue
            if not pieces:
                fname = ji.finger_display_label(i)
                angle_txt = "/".join(f"{t:g}" for t in thetas)
                offset_deg = min(self._min_axis_offset_deg(t, f.theta_toward_patch_deg) for t in thetas)
                warnings.append(
                    f"Finger {fname} deposits at {angle_txt}°, {offset_deg:.1f}° off its own drawn "
                    f"axis ({f.theta_toward_patch_deg:g}°/{f.theta_toward_stub_deg:g}°) -- at this "
                    f"offset the shadow throw already exceeds this finger's own linewidth (a thin "
                    f"line against this resist stack has little angular tolerance), so no metal "
                    f"will actually form there.")

        try:
            patch_thetas = self._true_order_patch_thetas(junction, run, theta_overrides,
                                                          self._resolve_patch_thetas(junction, run, theta_overrides))
        except Exception:
            patch_thetas = []
        if patch_thetas:
            for pg in report.patch_groups:
                finger = junction.fingers[pg.finger_index]
                fname = ji.finger_display_label(pg.finger_index)
                for k, s in enumerate(self._patches_for_group(junction, finger, pg.patch_count)):
                    try:
                        pieces = self._compute_one_patch_shadowed_pieces(junction, finger, s, patch_thetas, alpha, dx_um, dy_um)
                    except Exception:
                        continue
                    if not pieces:
                        patch_axis_deg, _a, _b, _w = ji._polygon_axis_and_ends(s.points)
                        angle_txt = "/".join(f"{t:g}" for t in patch_thetas)
                        offset_deg = min(self._min_axis_offset_deg(t, patch_axis_deg) for t in patch_thetas)
                        warnings.append(
                            f"Finger {fname}'s patch[{k}] deposits at {angle_txt}°, {offset_deg:.1f}° off "
                            f"its own drawn axis ({patch_axis_deg:g}°) -- at this offset the shadow throw "
                            f"already exceeds this patch's own linewidth (a thin line against this resist "
                            f"stack has little angular tolerance), so no metal will actually form there.")

        # GAP, fixed here: the cos(theta)
        # shadowing application rule needs to be applied to every single
        # shape in the junction, including adhesion plates and patches,
        # not just fingers. Plates now get the same real cross-axis geometry
        # (_compute_plate_shadowed_points, extended to call
        # _apply_cross_axis_shadow) and the same visualization
        # (_draw_cross_axis_shadow_bands in _draw_sim_shadow_visualization)
        # as fingers/patches -- so a plate that fully self-shadows this
        # way needs the same warning, or a thin-enough plate could
        # silently vanish with no text warning at all, exactly the gap
        # this whole warning exists to close for the other two shapes.
        for s in junction.other_shapes:
            if s.kind != "plate":
                continue
            nearest_finger = self._find_finger_for_plate(junction, s)
            if nearest_finger is None:
                continue
            fi = junction.fingers.index(nearest_finger)
            plate_thetas = self._run_finger_thetas(run, fi, nearest_finger, theta_overrides)
            if not plate_thetas:
                continue
            try:
                plate_pts = self._compute_plate_shadowed_points(junction, s, run, theta_overrides, alpha, dx_um, dy_um)
            except Exception:
                continue
            if plate_pts is None:
                fname = ji.finger_display_label(fi)
                plate_axis_deg, _a, _b, _w = ji._polygon_axis_and_ends(s.points)
                angle_txt = "/".join(f"{t:g}" for t in plate_thetas)
                offset_deg = min(self._min_axis_offset_deg(t, plate_axis_deg) for t in plate_thetas)
                warnings.append(
                    f"Finger {fname}'s adhesion plate deposits at {angle_txt}°, {offset_deg:.1f}° off "
                    f"its own drawn axis ({plate_axis_deg:g}°) -- at this offset the shadow throw "
                    f"already exceeds this plate's own width (a thin enough plate has little angular "
                    f"tolerance too), so no metal will actually form there.")
        return warnings

    def _check_ghost_junction_line_warnings(self, junction, report, run, theta_overrides, alpha, dx_um, dy_um):
        """A warning category ('Warning #3') for ghost junction lines (see
        _ghost_junction_slivers' own docstring
        for the full physical background: a fragment of a DIFFERENT
        feature's own metal landing in THIS feature's still-open
        aperture undercut, a mechanism confirmed with real SEM
        evidence from a real design and its accompanying poster). Checked with the
        exact SAME dx_um/dy_um and _ghost_junction_slivers geometry that
        makes _compute_post_shadow_shapes / _compute_post_shadow_shapes_
        upto draw a real disconnected sliver, so this warning and that
        geometry can never disagree about which features are at risk.

        Each message also names a
        concrete remedy, not just the risk -- either lower the e-beam
        dose slightly for the OFFENDING (foreign, currently-depositing)
        pass, or reduce the AT-RISK feature's own linewidth/width in the
        Create/Import tab (per the confirmed formula, ghost width = LW -
        PMMA*tan(alpha)*|align|, so narrowing that feature's own aperture
        shrinks or eliminates the sliver directly)."""
        warnings = []
        try:
            patch_thetas = self._true_order_patch_thetas(junction, run, theta_overrides,
                                                          self._resolve_patch_thetas(junction, run, theta_overrides))
        except Exception:
            patch_thetas = []
        patch_layers_ref = run.get("patch_thetas_override")
        if patch_layers_ref is None:
            patch_layers_ref = self._sim_patch_layers or []
        patch_thicknesses_ref = self._sim_patch_thicknesses or []
        patch_thicknesses = self._match_pass_thicknesses(patch_thetas, patch_layers_ref, patch_thicknesses_ref) if patch_thetas else []
        patch_alphas_ref = run.get("patch_alphas_override") or []
        patch_alphas = self._match_pass_thicknesses(patch_thetas, patch_layers_ref, patch_alphas_ref, default=None) if patch_thetas else []
        all_pass_records = self._all_deposition_pass_records(junction, run, theta_overrides,
                                                              patch_thetas, patch_thicknesses,
                                                              patch_alphas=patch_alphas,
                                                              alpha=alpha, dx_um=dx_um, dy_um=dy_um)
        if not all_pass_records:
            return warnings

        def _source_name(sliver):
            if sliver["kind"] == "finger" and sliver["feature_index"] is not None:
                fi = sliver["feature_index"]
                return f"Finger {'AB'[fi] if fi < 2 else str(fi)}'s"
            return "the patch deposition's"

        def _sliver_width_nm(sliver, perp_hat, origin):
            """A BUG found and reported
            against a real test case, where the shadowing reported a
            ghost junction over 16,000 nm wide when that was clearly
            wrong -- the visuals and shadowing geometry itself looked
            correct, so the issue was in how the width was measured.
            The old version measured the distance between sliver["pts"][0]
            and sliver["pts"][1], relying on _ghost_junction_slivers' own
            un-carved vertex order ([near-corner, far-corner-across-width,
            ...], so index 0-1 was always the short cross-axis (WIDTH)
            edge) -- true only for the plain rectangle case. The
            electrode-carving addition (see _ghost_junction_slivers'
            `junction`/`alpha_deg` docstring section) runs the sliver
            through a real shapely `.difference()` whenever it crosses an
            electrode step, and `.exterior.coords` on THAT result comes
            back in shapely's own arbitrary vertex order -- no longer
            guaranteed to start with the short edge. For a long trench
            (a real finger length of ~16 um) that let pts[0]-pts[1]
            land on two vertices spanning nearly the FULL LENGTH of the
            carved sliver instead of its width, exactly matching the
            reported ~16186.3 nm bogus value (that finger's own length in
            nm) -- the drawn GEOMETRY was never wrong, only this
            after-the-fact measurement of it. Fixed by computing the
            sliver's real extent along the caller's own known `perp_hat`
            (the cross-axis direction _ghost_junction_slivers itself
            projects onto internally) over EVERY vertex of the returned
            polygon, which is correct regardless of how many vertices
            the carve produced or what order shapely returned them in."""
            cx, cy = origin
            perp_vals = [(p[0] - cx) * perp_hat[0] + (p[1] - cy) * perp_hat[1] for p in sliver["pts"]]
            return (max(perp_vals) - min(perp_vals)) * 1000.0

        for i, f in enumerate(junction.fingers):
            fx, fy = f.patch_end[0] - f.stub_end[0], f.patch_end[1] - f.stub_end[1]
            flen = math.hypot(fx, fy) or 1.0
            axis_toward_patch = (fx / flen, fy / flen)
            perp_hat = (-axis_toward_patch[1], axis_toward_patch[0])
            foreign = self._foreign_pass_records(all_pass_records, "finger", i)
            slivers = self._ghost_junction_slivers(f.points, axis_toward_patch, perp_hat,
                                                    f.patch_end, foreign, dx_um, dy_um, junction=junction, alpha_deg=alpha)
            if not slivers:
                continue
            fname = ji.finger_display_label(i)
            worst = max(slivers, key=lambda sl: _sliver_width_nm(sl, perp_hat, f.patch_end))
            warnings.append(
                f"Ghost junction line risk: Finger {fname}'s own aperture (linewidth "
                f"{f.width_um * 1000.0:g} nm) is still open when {_source_name(worst)} own deposition "
                f"pass happens -- that pass will likely leave a disconnected sliver of its own metal "
                f"(~{_sliver_width_nm(worst, perp_hat, f.patch_end):.1f} nm wide) in Finger {fname}'s bottom-resist undercut, "
                f"beyond its own nominal edge and separate from Finger {fname}'s own real line "
                f"(see Post-Shadow Result). To fix: slightly lower {_source_name(worst)} e-beam "
                f"dose, or reduce Finger {fname}'s own linewidth in the Create/Import tab so its "
                f"aperture is no longer wide enough for the sliver to fit.")

        if patch_thetas:
            for pg in report.patch_groups:
                finger = junction.fingers[pg.finger_index]
                fname = ji.finger_display_label(pg.finger_index)
                fx, fy = finger.patch_end[0] - finger.stub_end[0], finger.patch_end[1] - finger.stub_end[1]
                flen = math.hypot(fx, fy) or 1.0
                fu, fv = fx / flen, fy / flen
                for k, s in enumerate(self._patches_for_group(junction, finger, pg.patch_count)):
                    _axis_angle, end_a, end_b, _w = ji._polygon_axis_and_ends(s.points)
                    proj_a = (end_a[0] - finger.stub_end[0]) * fu + (end_a[1] - finger.stub_end[1]) * fv
                    proj_b = (end_b[0] - finger.stub_end[0]) * fu + (end_b[1] - finger.stub_end[1]) * fv
                    near_end, far_end = (end_a, end_b) if proj_a < proj_b else (end_b, end_a)
                    axis_toward_far = (far_end[0] - near_end[0], far_end[1] - near_end[1])
                    al = math.hypot(*axis_toward_far) or 1.0
                    axis_toward_far = (axis_toward_far[0] / al, axis_toward_far[1] / al)
                    perp_hat = (-axis_toward_far[1], axis_toward_far[0])
                    foreign = self._foreign_pass_records(all_pass_records, "patch", None)
                    slivers = self._ghost_junction_slivers(s.points, axis_toward_far, perp_hat,
                                                            near_end, foreign, dx_um, dy_um, junction=junction, alpha_deg=alpha)
                    if not slivers:
                        continue
                    worst = max(slivers, key=lambda sl: _sliver_width_nm(sl, perp_hat, near_end))
                    warnings.append(
                        f"Ghost junction line risk: Finger {fname}'s patch[{k}] aperture (linewidth "
                        f"{_w * 1000.0:g} nm) is still open when {_source_name(worst)} own deposition pass "
                        f"happens -- that pass will likely leave a disconnected sliver of its own metal "
                        f"(~{_sliver_width_nm(worst, perp_hat, near_end):.1f} nm wide) in this patch's bottom-resist undercut, "
                        f"separate from the patch's own real line. To fix: slightly lower "
                        f"{_source_name(worst)} e-beam dose, or reduce this patch's own linewidth in "
                        f"the Create/Import tab so its aperture is no longer wide enough for the sliver "
                        f"to fit.")

        for s in junction.other_shapes:
            if s.kind != "plate":
                continue
            nearest_finger = self._find_finger_for_plate(junction, s)
            if nearest_finger is None:
                continue
            fi = junction.fingers.index(nearest_finger)
            fname = ji.finger_display_label(fi)
            near_end, far_end, plate_w = self._project_plate_onto_finger_axis(nearest_finger, s.points)
            axis_toward_far = (far_end[0] - near_end[0], far_end[1] - near_end[1])
            al = math.hypot(*axis_toward_far) or 1.0
            axis_toward_far = (axis_toward_far[0] / al, axis_toward_far[1] / al)
            perp_hat = (-axis_toward_far[1], axis_toward_far[0])
            foreign = self._foreign_pass_records(all_pass_records, "finger", fi)
            slivers = self._ghost_junction_slivers(s.points, axis_toward_far, perp_hat,
                                                    near_end, foreign, dx_um, dy_um, junction=junction, alpha_deg=alpha)
            if not slivers:
                continue
            worst = max(slivers, key=lambda sl: _sliver_width_nm(sl, perp_hat, near_end))
            warnings.append(
                f"Ghost junction line risk: Finger {fname}'s adhesion plate aperture (width "
                f"{plate_w * 1000.0:g} nm) is still open when {_source_name(worst)} own deposition pass "
                f"happens -- that pass will likely leave a disconnected sliver of its own metal "
                f"(~{_sliver_width_nm(worst, perp_hat, near_end):.1f} nm wide) in this plate's bottom-resist undercut, "
                f"separate from the plate's own real line. To fix: slightly lower "
                f"{_source_name(worst)} e-beam dose, or reduce this plate's own width in the "
                f"Create/Import tab so its aperture is no longer wide enough for the sliver to fit.")
        return warnings

    def _check_triangle_anomaly_warnings(self, junction, run, theta_overrides, alpha, dx_um, dy_um):
        """NEW warning category, section 7a ("triangular deposition
        artifacts") -- checked with the exact same all_pass_records pool
        and _triangle_anomaly_slivers geometry that makes
        _compute_post_shadow_shapes / _compute_post_shadow_shapes_upto /
        _slideshow_draw_shadow_sim_view draw the real triangles, so this
        warning and that geometry can never disagree about which
        junctions are at risk (same "two views can never disagree"
        contract _check_ghost_junction_line_warnings already follows).

        CONSOLIDATED: rather than an individual
        warning for every single triangle that gets deposited (which,
        with all the triangles found inside of adhesion pads, could
        mean 10, 15, or 20 triangles), this reports one warning for
        every clump of deposited triangles that are deposited at the
        same time, split between the junction-centric triangles and the
        patch-centric triangles. Previously fired ONE warning per
        triangle actually present, which was fine for the original
        one-crossing/45deg-bisector-only mechanism but became unusable
        clutter once the RIGHT-ANGLE ASSUMPTION ELIMINATED generalization
        let any pair of crossing trenches (finger, plate, or patch)
        anomaly-triangulate at any qualifying pass -- a dense patch/
        adhesion-pad area can genuinely produce a triangle at every
        finger-patch/patch-plate crossing it has, all from the SAME
        deposition pass. Grouped by (a) which deposition pass caused
        them (kind, feature_index, thickness, theta -- the same real
        identity `_merge_triangle_group_id` already treats as "the same
        physical metal"), and (b) whether the crossing itself is
        junction-centric (both trenches are fingers -- the main JJ
        crossing) or patch-centric (anything involving a patch/plate --
        the adhesion-pad clutter), using the new `pair_kinds` field
        `_triangle_anomaly_slivers` now returns per triangle. One
        warning per group, reporting the count and the min-max leg range
        actually present, so the count/size range shown here can never
        disagree with what's actually drawn -- just no longer one line
        per triangle."""
        warnings = []
        try:
            patch_thetas = self._true_order_patch_thetas(junction, run, theta_overrides,
                                                          self._resolve_patch_thetas(junction, run, theta_overrides))
        except Exception:
            patch_thetas = []
        patch_layers_ref = run.get("patch_thetas_override")
        if patch_layers_ref is None:
            patch_layers_ref = self._sim_patch_layers or []
        patch_thicknesses_ref = self._sim_patch_thicknesses or []
        patch_thicknesses = self._match_pass_thicknesses(patch_thetas, patch_layers_ref, patch_thicknesses_ref) if patch_thetas else []
        patch_alphas_ref = run.get("patch_alphas_override") or []
        patch_alphas = self._match_pass_thicknesses(patch_thetas, patch_layers_ref, patch_alphas_ref, default=None) if patch_thetas else []
        all_pass_records = self._all_deposition_pass_records(junction, run, theta_overrides,
                                                              patch_thetas, patch_thicknesses,
                                                              patch_alphas=patch_alphas,
                                                              alpha=alpha, dx_um=dx_um, dy_um=dy_um)
        slivers = self._triangle_anomaly_slivers(junction, all_pass_records, dy_um,
                                                  *self._pmma_pmgi_nm(), alpha)
        if not slivers:
            return warnings
        groups = {}
        group_order = []
        for sl in slivers:
            leg_um = math.hypot(sl["pts"][0][0] - sl["pts"][1][0], sl["pts"][0][1] - sl["pts"][1][1])
            pair_kinds = sl.get("pair_kinds", ("finger", "finger"))
            is_junction = pair_kinds[0] == "finger" and pair_kinds[1] == "finger"
            key = ("junction" if is_junction else "patch", sl["kind"], sl["feature_index"],
                   sl["thickness"], sl.get("pass_theta"))
            if key not in groups:
                groups[key] = []
                group_order.append(key)
            groups[key].append(leg_um * 1000.0)
        for key in group_order:
            group_kind = key[0]
            legs_nm = sorted(groups[key])
            n = len(legs_nm)
            if n == 1:
                size_text = f"a ~{legs_nm[0]:.1f} nm-leg triangle"
            else:
                size_text = f"{n} triangles (legs ~{legs_nm[0]:.1f}-{legs_nm[-1]:.1f} nm)"
            location_text = ("at the main junction crossing" if group_kind == "junction"
                              else "around the adhesion pads/patch crossings")
            warnings.append(
                f"Triangular deposition anomaly risk: a deposition pass's azimuth is close enough "
                f"to one of this design's own trench axes to leave a small pocket open in the "
                f"undercut -- expect {size_text} of foreign metal {location_text} once that pass "
                f"runs (see Post-Shadow Result). To fix: move that pass's own angle further from "
                f"the trench axis it's nearly crossing, or increase the relevant linewidths/PMGI "
                f"undercut so the pocket(s) close up.")
        return warnings

    def _pmma_pmgi_nm(self):
        """Small shared helper -- the same 'read self.pmma_edit/pmgi_edit,
        fall back to the file's own defaults on a bad/missing value'
        pattern every feature-geometry function in this file already
        repeats independently; factored out here since the new triangle-
        anomaly warning check is the first CALLER (not geometry function)
        that needs it standalone rather than inline."""
        try:
            pmma_nm = float(self.pmma_edit.text()) if hasattr(self, "pmma_edit") else 875.0
        except ValueError:
            pmma_nm = 875.0
        try:
            pmgi_nm = float(self.pmgi_edit.text()) if hasattr(self, "pmgi_edit") else 600.0
        except ValueError:
            pmgi_nm = 600.0
        return pmma_nm, pmgi_nm

    def _check_patch_contact_disconnections(self, junction, report):
        """Found via a real report: after editing an imported
        finger's length down far enough (the new Properties dock
        imported-shape editor -- junction_import.apply_finger_edit), a
        patch ends up with literally zero contact with anything, and
        nothing warned about it -- the Post-Shadow disconnection check
        above only checks finger-self-split / JJ-crossing / finger-to-
        plate, and the Near-side/Far-side checks in _update_sim_shadow_risk
        only test whether an ALREADY-POSITIVE nominal overhang survives
        shrinking further from shadow evaporation, never whether it
        started at zero. The first attempt at this fix modeled the
        connection as 'does the patch polygon touch the finger polygon',
        post-shadow -- this turned out to be wrong, found by testing directly against a real,
        already-verified design: both of its
        patches sit 1.3-2.3 um from the finger and from EACH OTHER, in
        both nominal and post-shadow geometry, by design
        (patch_spacing_um deliberately keeps them apart) -- yet the
        design is completely valid, because compute_measurements'
        individual_overlap_area_um2 (already shown in Create / Import's tree
        as 'Contact area (finger/plate)') reports it touching the
        finger's own ADHESION PLATE instead, not the finger's bare
        strip. So 'touches the finger' was simply never the right test.
        This instead reuses that same already-computed, already-correct
        measurement (patch polygon intersected with finger UNION its
        associated plate) and just checks whether it's exactly zero --
        confirmed against real files this correctly stays silent
        for a valid design (0.506, 0.505 um^2, both positive) and correctly fires
        for the reported scenario (0.0, 0.0 after the edit, versus
        0.106, 0.106 before it). Purely geometric -- no alpha/theta/run
        state needed, so unlike the checks above this doesn't depend on
        Run Simulation having been clicked."""
        warnings = []
        for pg in report.patch_groups:
            fname = ji.finger_display_label(pg.finger_index)
            for k in range(pg.patch_count):
                area = pg.individual_overlap_area_um2[k] if k < len(pg.individual_overlap_area_um2) else None
                if area is not None and area <= 1e-6:
                    warnings.append(
                        f"Finger {fname}'s patch[{k}] has zero contact area -- it does not touch the "
                        f"finger or plate. Lengthen the finger or move the patch so they meet.")
        return warnings

    def _check_electrode_contact_disconnections(self, junction, report):
        """A GAP found via real usage: none of the
        other disconnection checks ever test whether a finger's OWN
        electrode-facing chain -- the finger itself, its adhesion
        plate, and its patches, whichever of those actually reach
        toward the electrode -- makes contact with the electrode AT
        ALL. _check_post_shadow_disconnections only checks finger
        self-split, the JJ-crossing overlap between the two fingers,
        and finger-to-plate distance; _check_patch_contact_disconnections
        only checks a patch's contact with its OWN finger/plate.
        Neither one notices a design that's been rigidly translated (or
        otherwise moved) so that NOTHING in it reaches the electrode
        anymore, even though every INTERNAL connection (finger-to-
        plate, patch-to-finger) stays perfectly intact -- reproduced
        directly: nudging a whole junction layer away from its
        electrode left every existing check silent, since a pure
        translation can't break any of THOSE relationships, only the
        one relationship none of them tested.

        Purely geometric (same as the patch-contact check above) -- no
        alpha/theta/Run Simulation needed, since "does this design's
        electrode-facing end touch the electrode at all" doesn't depend
        on which angle it's deposited at, only on where it's drawn.
        Tests the UNION of each finger's own polygon + its associated
        plate (if any) + every patch in its patch group (if any)
        against electrode_polygons -- the real hole/contact region
        already used everywhere else for Warning #1 classification
        (_assign_warning_sources, compute_recommended_angles). Uses
        electrode_polygons specifically, NOT electrode_material (the
        background-only "actual drawn Nb metal" set used for milling --
        see _mill_highlighted_edges' own docstring on that distinction,
        and _find_electrode_crossing_line's matching fix below). If
        that union doesn't touch electrode_polygons at all, this leg is
        open regardless of any shadow evaporation."""
        warnings = []
        if not junction.electrode_polygons:
            return warnings  # no electrode geometry loaded at all -- can't tell either way
        try:
            electrode_union = so.unary_union([sg.Polygon(p) for p in junction.electrode_polygons if len(p) >= 3])
        except Exception:
            return warnings
        patch_groups_by_finger = {pg.finger_index: pg for pg in report.patch_groups}
        n = len(junction.fingers)
        finger_legs = {}
        direct_contact = set()
        for i, f in enumerate(junction.fingers):
            try:
                finger_poly = sg.Polygon(f.points)
                candidates = []
                associated = self._find_associated_plate(junction, f)
                if associated is not None:
                    candidates.append(sg.Polygon(associated[0].points))
                pg = patch_groups_by_finger.get(i)
                if pg is not None:
                    for s in self._patches_for_group(junction, f, pg.patch_count):
                        candidates.append(sg.Polygon(s.points))
                # BUG FIX: after scaling a
                # finger away from its own (unmoved) adhesion plate/
                # patches, this used to unconditionally union the finger
                # with EVERY candidate plate/patch _find_associated_plate/
                # patch_groups_by_finger nominally names for it, with no
                # check that they're still actually touching one
                # another. Reproduced directly: a finger shrunk far
                # enough to sit 0.18-1.7 um from its own patches (no
                # longer touching them at all) still registered
                # "direct_contact" with the electrode, because one of
                # those same patches happened to still touch the
                # electrode independently, in its own unmoved position --
                # the union doesn't care that the finger itself was never
                # actually joined to that patch any more, so a real open
                # circuit at the finger silently inherited a totally
                # separate piece's own contact. This finger's "leg" (its
                # docstring's own words: "whichever of those actually
                # reach toward the electrode") is now grown as a real
                # connectivity fixed-point instead: only a candidate that
                # is genuinely touching (within a small, shadow-agnostic
                # geometric tolerance -- this check is pure nominal
                # geometry, no Run Simulation involved) the chain built
                # so far is folded in, repeated until nothing more
                # qualifies -- so a plate/patch that's drifted away from
                # this finger can never again smuggle its own, unrelated
                # electrode contact onto it. Order-independent: a patch
                # that only touches ANOTHER patch (not the plate/finger
                # directly) still gets folded in once that other patch
                # has itself joined the chain.
                connected_parts = [finger_poly]
                connected_poly = finger_poly
                remaining = candidates
                changed = True
                while changed and remaining:
                    changed = False
                    still_remaining = []
                    for cand in remaining:
                        try:
                            touches = connected_poly.distance(cand) <= 1e-4
                        except Exception:
                            touches = False
                        if touches:
                            connected_parts.append(cand)
                            connected_poly = so.unary_union(connected_parts)
                            changed = True
                        else:
                            still_remaining.append(cand)
                    remaining = still_remaining
                leg_union = connected_poly
            except Exception:
                leg_union = None
            finger_legs[i] = leg_union
            if leg_union is not None:
                try:
                    if leg_union.intersection(electrode_union).area > 1e-6:
                        direct_contact.add(i)
                except Exception:
                    pass

        # GENERALIZATION for series-chain /
        # layered Manhattan junction array designs: a finger no longer
        # needs to touch the electrode ITSELF to be considered connected
        # -- its end can instead form a real JJ crossing with ANOTHER
        # finger, which reaches the electrode (directly, or through yet
        # another finger down the chain). Walk the finger-to-finger
        # adjacency graph -- built from real leg-polygon overlaps, the
        # same physical test used for direct electrode contact above --
        # outward from every finger already in direct_contact; only a
        # finger this walk never reaches is a genuine open circuit. A
        # classic 2-finger design is unaffected: when both fingers touch
        # the electrode directly, both already start in direct_contact,
        # so this walk finds nothing new and warns exactly as before.
        adjacency = {i: set() for i in range(n)}
        for i in range(n):
            li = finger_legs.get(i)
            if li is None:
                continue
            for j in range(i + 1, n):
                lj = finger_legs.get(j)
                if lj is None:
                    continue
                try:
                    if li.intersection(lj).area > 1e-9:
                        adjacency[i].add(j)
                        adjacency[j].add(i)
                except Exception:
                    continue

        reached = set(direct_contact)
        frontier = list(direct_contact)
        while frontier:
            cur = frontier.pop()
            for nb in adjacency[cur]:
                if nb not in reached:
                    reached.add(nb)
                    frontier.append(nb)

        for i in range(n):
            if i not in reached:
                fname = ji.finger_display_label(i)
                warnings.append(
                    f"Finger {fname} never makes contact with the electrode -- this leg is an open circuit.")
        return warnings

    def _check_design_stage_warnings(self, junction, report):
        """A notification-style warning system for Create / Import
        itself, covering the quality of the
        shapes and how the junction looks at the design stage.
        Warnings include when a shape is not attached to
        another -- for example when the junction fingers are not
        overlapping and no junction is formed, a patch is stranded by
        itself and not attached to anything, or a patch is not fully
        overlapping an adhesion plate -- plus a warning
        when the patch-to-adhesion-plate overlap area is less than the
        area of the junction overlap (since that would become a
        source of resistance), and the warning for
        junction fingers that are not perfectly orthogonal to each
        other, which now lives here instead of its earlier location.

        Deliberately independent of Run Simulation / alpha / theta --
        every check here is pure as-drawn geometry, unlike Simulate
        Design's own shadow-risk checks, so this always reflects the
        CURRENT design the instant it's edited, exactly like the old
        Finger Geometry panel's perpendicularity warning did.

        Reuses the two existing pure-geometric disconnection checks
        (_check_patch_contact_disconnections, _check_electrode_contact_
        disconnections) rather than duplicating their logic -- both were
        previously surfaced only inside Simulate Design's Shadowing Risk
        Check, gated behind having clicked Run Simulation at least once,
        even though neither one actually needs any simulation state.
        They're genuinely useful earlier too, at the design stage, which
        is exactly what's being added here."""
        warnings = []

        # 1. No junction formed at all: the two fingers don't actually
        # overlap/cross. Generalizes cleanly to any 2-finger design
        # (parametric or a real import) since jj_crossing_area_um2 is
        # computed from real polygon intersection, not a design parameter.
        if len(junction.fingers) == 2:
            area = report.jj_crossing_area_um2 if report is not None else None
            if area is None or area <= 1e-6:
                warnings.append(
                    "No junction is formed -- Finger A and Finger B do not overlap/cross at all.")

        # 2. Fingers not perfectly orthogonal -- moved here from its
        # earlier location, and GENERALIZED along the way: the old
        # perp_warning_label only ever compared the two PARAMETRIC design
        # fields (horizontal_finger_angle/vertical_finger_angle), so a
        # real GDS import never got this warning at all, no matter how
        # far off-perpendicular its two fingers actually were. Comparing
        # each finger's own real axis_angle_deg (mod 180, since a line's
        # axis has no inherent direction) works identically for both
        # sources, using the same formula the old parametric-only check used.
        if len(junction.fingers) == 2:
            a = junction.fingers[0].axis_angle_deg % 180.0
            b = junction.fingers[1].axis_angle_deg % 180.0
            perp_off = abs(((a - b) % 180.0) - 90.0)
            if perp_off > 0.5:
                warnings.append(
                    f"Fingers should be perpendicular -- currently off by {perp_off:.1f}° "
                    f"(Finger A axis {a:.1f}°, Finger B axis {b:.1f}°).")

        # 3. Patch stranded / not attached to anything at all -- reuses
        # the existing pure-geometric check unchanged.
        warnings.extend(self._check_patch_contact_disconnections(junction, report))

        # 3b. A finger's whole electrode-facing chain never reaches the
        # electrode at all -- also pure-geometric, also previously
        # Simulate-Design-only. Genuinely a design-stage concern too (a
        # design that's been nudged/translated away from its electrode
        # is broken regardless of deposition angle).
        warnings.extend(self._check_electrode_contact_disconnections(junction, report))

        # 4/5. Patch-to-plate coverage checks.
        # For each finger that HAS an adhesion plate, look at that
        # finger's own patch group (if any) against the plate specifically
        # (not finger-or-plate combined, unlike individual_overlap_area_um2
        # above -- these two checks are specifically ABOUT the plate).
        for i, f in enumerate(junction.fingers):
            fname = ji.finger_display_label(i)
            plate = ji._find_finger_plate(junction, f)
            if plate is None:
                continue
            pg = next((g for g in report.patch_groups if g.finger_index == i), None)
            if pg is None or pg.patch_count == 0:
                continue
            try:
                plate_poly = sg.Polygon(plate.points)
                patches = self._patches_for_group(junction, f, pg.patch_count)
                total_plate_overlap_area = 0.0
                overlaps = []  # (k, overlap_area, patch_area) -- gathered first so item 4
                               # below can compare each patch against its OWN siblings,
                               # not just against "is it literally 100%".
                for k, s in enumerate(patches):
                    patch_poly = sg.Polygon(s.points)
                    overlap_area = patch_poly.intersection(plate_poly).area
                    total_plate_overlap_area += overlap_area
                    overlaps.append((k, overlap_area, patch_poly.area))

                # 4. BUG, fixed here, found against a
                # real multi-patch design: the old rule flagged ANY patch with
                # even a negligible sliver outside the plate's own
                # footprint, which fires on nearly EVERY real multi-patch
                # design -- patches are routinely drawn a bit larger than,
                # or offset past, their own plate ON PURPOSE (the plate
                # only needs to make real contact, not fully contain the
                # patch), so this warned on all 4 patches of a perfectly
                # normal design at once, every one of them identically
                # "partial" by simple design intent, not because anything
                # was actually wrong. The
                # real signal isn't "is this ONE patch's overlap literally
                # 100%", it's whether this patch's overlap area deviates
                # SIGNIFICANTLY from its own sibling patches' overlap
                # areas in the same group -- if every patch overlaps its
                # plate about the same amount (even if that shared amount
                # is well under 100%), that's consistent, intentional
                # geometry, not a defect; if one patch's contact is far
                # below what its siblings achieve, THAT one is the real
                # outlier -- only slightly catching a corner, possibly
                # close to fully separating -- and gets flagged alone.
                # A lone patch (no siblings to compare against) has no
                # relative baseline, so it falls back to an absolute
                # floor instead: less than half of ITS OWN area actually
                # contacting the plate.
                if len(overlaps) >= 2:
                    areas_sorted = sorted(a for _, a, _ in overlaps)
                    mid = len(areas_sorted) // 2
                    median_area = areas_sorted[mid] if len(areas_sorted) % 2 == 1 else \
                        (areas_sorted[mid - 1] + areas_sorted[mid]) / 2.0
                    if median_area > 1e-6:
                        for k, overlap_area, _patch_area in overlaps:
                            if overlap_area < 0.5 * median_area:
                                warnings.append(
                                    f"Finger {fname}'s patch[{k}] overlaps its adhesion plate by "
                                    f"only {overlap_area:.4f} µm², far less than its sibling "
                                    f"patches in this group (median {median_area:.4f} µm²) -- it "
                                    f"may be only partially attached or close to fully separated, "
                                    f"unlike the rest of the group.")
                elif overlaps:
                    k, overlap_area, patch_area = overlaps[0]
                    if patch_area > 1e-9 and (overlap_area / patch_area) < 0.5:
                        warnings.append(
                            f"Finger {fname}'s patch[{k}] only overlaps its adhesion plate across "
                            f"{overlap_area / patch_area:.0%} of its own area -- it may be only "
                            f"partially attached or close to fully separated.")

                # 5. The new patch-to-plate contact is narrower than the
                # original JJ crossing: when the
                # patch-to-adhesion-plate overlap area is less than the
                # area of the junction overlap, that would
                # become a source of resistance. Compared against the
                # GROUP's total contact with the plate, since that's the
                # real current-carrying cross-section for this leg once
                # patches replace the finger's own direct electrode
                # contact.
                jj_area = report.jj_crossing_area_um2
                if jj_area is not None and jj_area > 1e-6 and total_plate_overlap_area < jj_area:
                    warnings.append(
                        f"Finger {fname}'s patch-to-plate contact area ({total_plate_overlap_area:.4f} "
                        f"µm²) is less than the JJ crossing area ({jj_area:.4f} µm²) "
                        f"-- this new contact could become the design's real resistance bottleneck.")
            except Exception:
                continue

        return warnings

    def _update_design_warnings_panel(self, junction, report):
        """Populates the always-visible Create / Import 'Design Warnings'
        banner from _check_design_stage_warnings -- runs on every
        _update_preview, so it reflects the CURRENT design the instant
        it changes, same as the old inline perpendicularity warning did,
        just consolidated with the other design-quality checks now
        living alongside it.

        Only actually triggers the slide-in/fade-in
        appearance animation (_show_design_warnings_banner) on the
        TRANSITION from hidden to shown -- if it's already visible and
        the message text just changes (e.g. the warning list flickers
        during a live drag), the text is updated in place with no
        re-animation, so a fast, repeated retrigger during a drag can
        never itself become distracting or jittery. Likewise only calls
        _hide_design_warnings_banner (its own quick fade-out) on the
        opposite transition, shown to hidden."""
        if not hasattr(self, "design_warnings_banner"):
            return
        try:
            warnings = self._check_design_stage_warnings(junction, report) if report is not None else []
        except Exception:
            warnings = []
        was_visible = self.design_warnings_banner.isVisible()
        if not warnings:
            self.design_warnings_label.setText("")
            if was_visible:
                self._hide_design_warnings_banner()
            return
        header = f"⚠ {len(warnings)} Design Warning{'s' if len(warnings) != 1 else ''}"
        body = "\n".join(f"• {w}" for w in warnings)
        self.design_warnings_label.setText(f"{header}\n{body}")
        if was_visible:
            self._position_design_warnings_banner()  # re-anchor in place; content may have
                                                        # changed the banner's own height
            self.design_warnings_banner.raise_()  # stay on top even if the canvas was
                                                    # redrawn/re-raised in between
        else:
            self._show_design_warnings_banner()  # computes its own start/end geometry,
                                                    # including the resting position

    def _design_warnings_target_rect(self):
        """Computes (without applying) the floating Design Warnings
        banner's resting geometry -- anchored just inside the top-right
        corner of the Create/Import preview canvas. Returns None if the
        canvas isn't ready yet (e.g. very early during window
        construction, before it has a real size). Factored out of
        _position_design_warnings_banner so _show_design_warnings_banner
        can compute its own end_rect directly, unconditionally -- see
        that function's own docstring for why it must NOT go through
        _position_design_warnings_banner (which deliberately no-ops
        while an animation is already in flight)."""
        if not hasattr(self, "design_warnings_banner") or not hasattr(self, "create_import_canvas"):
            return None
        banner = self.design_warnings_banner
        canvas_geo = self.create_import_canvas.geometry()
        if canvas_geo.width() <= 0 or canvas_geo.height() <= 0:
            return None
        margin = 14
        max_w = int(min(340, max(160, canvas_geo.width() - 2 * margin)))
        banner.setFixedWidth(max_w)
        banner.adjustSize()  # recomputes height for the CURRENT text at this width
                              # (design_warnings_label word-wraps)
        x = canvas_geo.right() - margin - banner.width()
        y = canvas_geo.top() + margin
        return QRect(x, y, banner.width(), banner.height())

    def _position_design_warnings_banner(self):
        """Anchors the floating Design Warnings banner to
        the top-right corner of the Create/Import preview canvas, just
        inside its edge -- called after every content change (so a
        longer/shorter message re-sizes correctly) and on every resize
        of the tab (_ResizeNotifyingWidget.on_resize). Purely a
        repositioning helper: it never touches the canvas's own
        geometry, which is exactly the point -- this banner is a
        free-floating overlay child, not a layout item, so nothing it
        does here can ever reflow anyone else's geometry (see
        _build_create_import_tab's own comment on the
        precision-loss bug this eliminates).

        CRASH FIX: rotating the entire junction was found to
        crash the program, severely enough to trip the OS's own crash
        reporter. This used to
        gate itself on `anim_group.state() == QAbstractAnimation.Running`
        -- but this banner's animations start with
        QAbstractAnimation.DeleteWhenStopped, meaning the underlying C++
        QParallelAnimationGroup/QPropertyAnimation object is destroyed
        the instant it finishes. self._design_warnings_anim_group kept
        pointing at that now-deleted object, so the VERY NEXT
        _update_preview() (which fires on every single mouse-motion
        frame of a live rotate/scale drag -- and a whole-junction rotate
        can easily cross a warning's on/off threshold, e.g. 'fingers not
        perpendicular', many times during one gesture) called
        .state() on a deleted Qt object and raised a bare
        RuntimeError('Internal C++ object ... already deleted') --
        propagating straight out of the mouse-motion handler on every
        subsequent frame, which is exactly what a rapid, repeated,
        never-resolving exception during live mouse tracking looks like
        from the outside: the redraw never completes (so the canvas
        visibly stops updating after only a few degrees of real
        rotation, and patches -- whose geometry WAS still being updated
        underneath, just never actually got drawn -- look like they
        never moved at all), the app appears to hang/lag as the event
        queue backs up behind the same crashing handler, and eventually
        the OS's own hang-detector reports it. Fixed by never touching
        the animation object's own .state() at all -- a plain Python
        flag (_design_warnings_anim_running, set True on start and
        cleared by _on_design_warnings_anim_finished's `finished` slot)
        tracks whether one is in flight instead, which is always safe
        to read regardless of whether the underlying C++ object still
        exists."""
        if getattr(self, "_design_warnings_anim_running", False):
            return  # an in-flight slide/fade owns the geometry right now -- don't fight it
        target = self._design_warnings_target_rect()
        if target is not None:
            self.design_warnings_banner.setGeometry(target)

    def _on_design_warnings_anim_finished(self):
        """Clears the running flag/reference once a show or hide
        animation finishes. This plain Python flag is the
        ONLY thing anything else in this file ever checks to ask "is a
        Design Warnings animation currently running" -- never the
        QAbstractAnimation object's own .state(), which can already be a
        dangling reference to a deleted C++ object by the time anything
        else runs (see _position_design_warnings_banner's own
        crash-fix comment for the exact crash this avoids)."""
        self._design_warnings_anim_running = False
        self._design_warnings_anim_group = None

    def _show_design_warnings_banner(self):
        """Warnings animate in by sliding from the right and
        fading in, kept extremely quick (under half a second) so the
        effect stays subtle:
        slides the banner in from just off the right edge of its
        resting spot while fading it in, landing at the exact top-right
        anchor _design_warnings_target_rect computes. 350ms, well under
        the half-second ceiling. Purely cosmetic -- the
        banner is a free-floating overlay (see _build_create_import_tab),
        so this animation can never itself affect the canvas's own
        geometry the way the old always-in-the-layout banner did.

        Deliberately calls _design_warnings_target_rect() directly
        instead of _position_design_warnings_banner() -- the latter
        no-ops while `_design_warnings_anim_running` is already True,
        which would leave end_rect stale (the banner's PREVIOUS resting
        spot) if this show is itself triggered while an earlier
        show/hide is still finishing up (e.g. a warning flickers on/off
        rapidly during a fast drag)."""
        banner = self.design_warnings_banner
        end_rect = self._design_warnings_target_rect()
        if end_rect is None:
            banner.setVisible(True)
            return
        start_rect = QRect(end_rect)
        start_rect.moveLeft(end_rect.left() + 44)  # starts 44px further right, slides into place

        # Only ever touch the previous animation object when
        # the flag says it's still genuinely alive -- see
        # _position_design_warnings_banner's own crash-fix
        # comment for why .state() itself is never queried here.
        if getattr(self, "_design_warnings_anim_running", False):
            old_group = getattr(self, "_design_warnings_anim_group", None)
            if old_group is not None:
                old_group.stop()

        effect = self._design_warnings_opacity_effect
        effect.setOpacity(0.0)
        banner.setGeometry(start_rect)
        banner.setVisible(True)
        banner.raise_()

        pos_anim = QPropertyAnimation(banner, b"geometry", self)
        pos_anim.setDuration(350)
        pos_anim.setStartValue(start_rect)
        pos_anim.setEndValue(end_rect)
        pos_anim.setEasingCurve(QEasingCurve.OutCubic)
        fade_anim = QPropertyAnimation(effect, b"opacity", self)
        fade_anim.setDuration(300)
        fade_anim.setStartValue(0.0)
        fade_anim.setEndValue(1.0)
        fade_anim.setEasingCurve(QEasingCurve.OutCubic)
        group = QParallelAnimationGroup(self)
        group.addAnimation(pos_anim)
        group.addAnimation(fade_anim)
        self._design_warnings_anim_group = group
        self._design_warnings_anim_running = True
        group.finished.connect(self._on_design_warnings_anim_finished)
        group.start(QAbstractAnimation.DeleteWhenStopped)

    def _hide_design_warnings_banner(self):
        """The reverse of _show_design_warnings_banner -- a quick
        fade-out (220ms) once every Design Warning has been resolved.
        Kept just as fast/unobtrusive as the appearance animation, for
        the same reason: this is a live-updating notification, not
        something the user should have to wait on mid-gesture. See
        _position_design_warnings_banner's own crash-fix
        comment for why the previous animation is only ever
        stopped when `_design_warnings_anim_running` says it's still
        alive, never by querying its own .state()."""
        banner = self.design_warnings_banner
        if getattr(self, "_design_warnings_anim_running", False):
            old_group = getattr(self, "_design_warnings_anim_group", None)
            if old_group is not None:
                old_group.stop()
        effect = self._design_warnings_opacity_effect
        fade_anim = QPropertyAnimation(effect, b"opacity", self)
        fade_anim.setDuration(220)
        fade_anim.setStartValue(effect.opacity())
        fade_anim.setEndValue(0.0)
        fade_anim.setEasingCurve(QEasingCurve.InCubic)
        fade_anim.finished.connect(lambda: banner.setVisible(False))
        fade_anim.finished.connect(self._on_design_warnings_anim_finished)
        self._design_warnings_anim_group = fade_anim
        self._design_warnings_anim_running = True
        fade_anim.start(QAbstractAnimation.DeleteWhenStopped)

    def _oxide_barrier_between_fingers(self, junction, sid_a=None, sid_b=None):
        """True if an "oxidation"-kind feature sits somewhere between
        the earliest and latest deposition feature attributed (by
        source_id, the finger's own stable_id -- see
        _rebuild_recipe_from_features's identical attribution logic) to
        EITHER of the two given fingers, in the live
        self._recipe_features order (the same ordered list the
        Predicted Recipe Sequence card shows). False if that span
        exists but genuinely has no oxidation feature in it -- directly
        catches the scenario where a user deletes that oxidation step and
        creates an unintended short. None if it can't be determined yet
        (fewer than 2 fingers, or neither finger's own deposition passes
        have been attributed in self._recipe_features yet -- e.g. before
        Run Angle Diagnostic has ever populated it) -- callers treat
        None as "don't flag a short from this check", not as "no
        barrier", since asserting a short from a state we can't actually
        verify would be a false positive.

        GENERALIZATION for series-chain
        designs: this used to hardcode junction.fingers[0]/[1] as THE
        two fingers to check -- correct for a classic 2-finger design
        (the only crossing there), but meaningless for a >2-finger chain
        with several real crossings, each of which needs its OWN oxide-
        barrier check between its own two participating fingers.
        sid_a/sid_b are now explicit parameters -- the caller passes the
        specific crossing pair's own two stable_ids (see
        _compute_postshadow_report's generalized JJ-crossing loop);
        omitting them falls back to junction.fingers[0]/[1]'s own
        stable_ids, keeping every existing caller (a classic 2-finger
        design has exactly one crossing pair anyway) byte-identical."""
        features = list(getattr(self, "_recipe_features", None) or [])
        if len(junction.fingers) < 2 or not features:
            return None
        if sid_a is None or sid_b is None:
            sid_a, sid_b = junction.fingers[0].stable_id, junction.fingers[1].stable_id

        def _attributed_to(feat, sid):
            # A merged single-pass-group feature (see SimulationFeature.
            # group_source_ids) attributes to every one of its group
            # members, not just the primary source_id.
            return feat.source_id == sid or sid in (getattr(feat, "group_source_ids", None) or [])

        idx_a = [i for i, feat in enumerate(features) if feat.kind == "deposition" and _attributed_to(feat, sid_a)]
        idx_b = [i for i, feat in enumerate(features) if feat.kind == "deposition" and _attributed_to(feat, sid_b)]
        if not idx_a or not idx_b:
            return None
        lo, hi = min(idx_a + idx_b), max(idx_a + idx_b)
        return any(feat.kind == "oxidation" for feat in features[lo:hi + 1])

    def _collect_ghost_and_triangle_measurements(self, junction, report, run, theta_overrides,
                                                  alpha, dx_um, dy_um, electrode_union):
        """Real dimensions for every ghost sliver and triangle deposition
        anomaly this design can produce at the committed run, established
        alongside the rest of this card's overhaul. Mirrors the exact same per-finger/patch/
        plate loops and _ghost_junction_slivers/_triangle_anomaly_slivers
        calls _check_ghost_junction_line_warnings/_check_triangle_
        anomaly_warnings already use for the separate Shadowing Warnings
        card (so the two can never disagree about which slivers exist),
        but collects EVERY sliver's own real dimensions here instead of
        just the single worst one folded into a human-readable warning
        string. Also flags whether a ghost sliver's own real polygon
        touches the electrode -- the new SHORT criterion #2."""
        ghost_out = []
        # BUG, caught while verifying this card against a real
        # patch-less design: _resolve_patch_thetas/_true_order_
        # patch_thetas (like every other caller in this file, e.g. the
        # main Post-Shadow orchestrator and _check_ghost_junction_line_
        # warnings itself) return a real fallback theta even when this
        # design has NO patches at all -- fine for those callers, since
        # they only ever fold every sliver found down to a single
        # worst-case value/string, silently absorbing the resulting
        # phantom "patch" pass record. THIS function instead lists EVERY
        # sliver individually, establishing the
        # dimensions of each ghost line, so that same phantom
        # record was showing up as a spurious duplicate ghost entry,
        # numerically identical to the real foreign-finger sliver that
        # caused it. Gated here (only here) on real patch geometry
        # actually existing in this junction.
        has_real_patches = any(s.kind == "patch" for s in junction.other_shapes)
        try:
            patch_thetas = self._true_order_patch_thetas(junction, run, theta_overrides,
                                                          self._resolve_patch_thetas(junction, run, theta_overrides)) \
                if has_real_patches else []
        except Exception:
            patch_thetas = []
        patch_layers_ref = run.get("patch_thetas_override")
        if patch_layers_ref is None:
            patch_layers_ref = self._sim_patch_layers or []
        patch_thicknesses_ref = self._sim_patch_thicknesses or []
        patch_thicknesses = self._match_pass_thicknesses(patch_thetas, patch_layers_ref, patch_thicknesses_ref) if patch_thetas else []
        patch_alphas_ref = run.get("patch_alphas_override") or []
        patch_alphas = self._match_pass_thicknesses(patch_thetas, patch_layers_ref, patch_alphas_ref, default=None) if patch_thetas else []
        all_pass_records = self._all_deposition_pass_records(junction, run, theta_overrides,
                                                              patch_thetas, patch_thicknesses,
                                                              patch_alphas=patch_alphas,
                                                              alpha=alpha, dx_um=dx_um, dy_um=dy_um)

        def sliver_dims(sliver, axis_hat, perp_hat, origin):
            ax_vals = [(p[0] - origin[0]) * axis_hat[0] + (p[1] - origin[1]) * axis_hat[1] for p in sliver["pts"]]
            pv_vals = [(p[0] - origin[0]) * perp_hat[0] + (p[1] - origin[1]) * perp_hat[1] for p in sliver["pts"]]
            return (max(ax_vals) - min(ax_vals)), (max(pv_vals) - min(pv_vals)) * 1000.0

        def touches_electrode(sliver):
            if electrode_union is None:
                return False
            try:
                return sg.Polygon(sliver["pts"]).buffer(0).intersection(electrode_union).area > 1e-6
            except Exception:
                return False

        if all_pass_records:
            for i, f in enumerate(junction.fingers):
                fname = ji.finger_display_label(i)
                fx, fy = f.patch_end[0] - f.stub_end[0], f.patch_end[1] - f.stub_end[1]
                flen = math.hypot(fx, fy) or 1.0
                axis_hat = (fx / flen, fy / flen)
                perp_hat = (-axis_hat[1], axis_hat[0])
                foreign = self._foreign_pass_records(all_pass_records, "finger", i)
                slivers = self._ghost_junction_slivers(f.points, axis_hat, perp_hat, f.patch_end, foreign,
                                                        dx_um, dy_um, junction=junction, alpha_deg=alpha)
                for sl in slivers:
                    length_um, width_nm = sliver_dims(sl, axis_hat, perp_hat, f.patch_end)
                    ghost_out.append({"location": f"Finger {fname}'s aperture", "length_um": length_um,
                                       "width_nm": width_nm, "touches_electrode": touches_electrode(sl),
                                       "finger_index": i})

            if patch_thetas:
                for pg in report.patch_groups:
                    finger = junction.fingers[pg.finger_index]
                    fname = ji.finger_display_label(pg.finger_index)
                    fx, fy = finger.patch_end[0] - finger.stub_end[0], finger.patch_end[1] - finger.stub_end[1]
                    flen = math.hypot(fx, fy) or 1.0
                    fu, fv = fx / flen, fy / flen
                    for k, s in enumerate(self._patches_for_group(junction, finger, pg.patch_count)):
                        _axis_angle, end_a, end_b, _w = ji._polygon_axis_and_ends(s.points)
                        proj_a = (end_a[0] - finger.stub_end[0]) * fu + (end_a[1] - finger.stub_end[1]) * fv
                        proj_b = (end_b[0] - finger.stub_end[0]) * fu + (end_b[1] - finger.stub_end[1]) * fv
                        near_end, far_end = (end_a, end_b) if proj_a < proj_b else (end_b, end_a)
                        axis_toward_far = (far_end[0] - near_end[0], far_end[1] - near_end[1])
                        al = math.hypot(*axis_toward_far) or 1.0
                        axis_toward_far = (axis_toward_far[0] / al, axis_toward_far[1] / al)
                        perp_hat = (-axis_toward_far[1], axis_toward_far[0])
                        foreign = self._foreign_pass_records(all_pass_records, "patch", None)
                        slivers = self._ghost_junction_slivers(s.points, axis_toward_far, perp_hat, near_end, foreign,
                                                                dx_um, dy_um, junction=junction, alpha_deg=alpha)
                        for sl in slivers:
                            length_um, width_nm = sliver_dims(sl, axis_toward_far, perp_hat, near_end)
                            ghost_out.append({"location": f"Finger {fname}'s patch[{k}] aperture", "length_um": length_um,
                                               "width_nm": width_nm, "touches_electrode": touches_electrode(sl),
                                               "finger_index": pg.finger_index})

            for s in junction.other_shapes:
                if s.kind != "plate":
                    continue
                nearest_finger = self._find_finger_for_plate(junction, s)
                if nearest_finger is None:
                    continue
                fi = junction.fingers.index(nearest_finger)
                fname = ji.finger_display_label(fi)
                near_end, far_end, _plate_w = self._project_plate_onto_finger_axis(nearest_finger, s.points)
                axis_toward_far = (far_end[0] - near_end[0], far_end[1] - near_end[1])
                al = math.hypot(*axis_toward_far) or 1.0
                axis_toward_far = (axis_toward_far[0] / al, axis_toward_far[1] / al)
                perp_hat = (-axis_toward_far[1], axis_toward_far[0])
                foreign = self._foreign_pass_records(all_pass_records, "finger", fi)
                slivers = self._ghost_junction_slivers(s.points, axis_toward_far, perp_hat, near_end, foreign,
                                                        dx_um, dy_um, junction=junction, alpha_deg=alpha)
                for sl in slivers:
                    length_um, width_nm = sliver_dims(sl, axis_toward_far, perp_hat, near_end)
                    ghost_out.append({"location": f"Finger {fname}'s adhesion plate aperture", "length_um": length_um,
                                       "width_nm": width_nm, "touches_electrode": touches_electrode(sl),
                                       "finger_index": fi})

        triangles_out = []
        if all_pass_records:
            try:
                slivers = self._triangle_anomaly_slivers(junction, all_pass_records, dy_um, *self._pmma_pmgi_nm(), alpha)
            except Exception:
                slivers = []
            groups = {}
            group_order = []
            for sl in slivers:
                # Report length, width, and side lengths for each
                # deposition anomaly. This construction's own docstring
                # (_triangle_anomaly_slivers) explicitly eliminated the
                # old right-angle assumption -- these are generally
                # SCALENE triangles, so there is no universal
                # "leg"/"hypotenuse" pair the way a right triangle has.
                # Report all 3 real side lengths instead of asserting a
                # hypotenuse that may not exist -- side 3 (sorted
                # longest) is the closest honest analogue of "the long
                # side" a hypotenuse would be.
                # `leg_um` (pts[0]-pts[1], one specific side) is kept
                # as-is, unchanged, purely for backward compatibility --
                # existing readers of leg_min_nm/leg_max_nm keep working.
                pts = sl["pts"]
                leg_um = math.hypot(pts[0][0] - pts[1][0], pts[0][1] - pts[1][1])
                side_lengths_um = sorted(
                    math.hypot(pts[a][0] - pts[b][0], pts[a][1] - pts[b][1]) for a, b in ((0, 1), (1, 2), (2, 0)))
                try:
                    area_um2 = sg.Polygon(pts).area
                except Exception:
                    area_um2 = 0.0
                pair_kinds = sl.get("pair_kinds", ("finger", "finger"))
                is_junction = pair_kinds[0] == "finger" and pair_kinds[1] == "finger"
                key = ("junction" if is_junction else "patch", sl["kind"], sl["feature_index"],
                       sl["thickness"], sl.get("pass_theta"))
                if key not in groups:
                    groups[key] = []
                    group_order.append(key)
                groups[key].append((leg_um, area_um2, side_lengths_um))
            for key in group_order:
                entries = groups[key]
                legs_nm = sorted(e[0] * 1000.0 for e in entries)
                areas = sorted(e[1] for e in entries)
                # Per-rank min/max across the group -- side1 = shortest
                # side of each triangle, side3 = longest ("hypotenuse-
                # like") side, side2 = the remaining middle side.
                sides_nm = [[s * 1000.0 for s in e[2]] for e in entries]
                side1_nm = sorted(s[0] for s in sides_nm)
                side2_nm = sorted(s[1] for s in sides_nm)
                side3_nm = sorted(s[2] for s in sides_nm)
                triangles_out.append({
                    "location": "Main JJ crossing" if key[0] == "junction" else "Adhesion pad/patch crossing",
                    "count": len(entries), "leg_min_nm": legs_nm[0], "leg_max_nm": legs_nm[-1],
                    "area_min_um2": areas[0], "area_max_um2": areas[-1],
                    "side1_min_nm": side1_nm[0], "side1_max_nm": side1_nm[-1],
                    "side2_min_nm": side2_nm[0], "side2_max_nm": side2_nm[-1],
                    "side3_min_nm": side3_nm[0], "side3_max_nm": side3_nm[-1],
                })
        return ghost_out, triangles_out

    def _compute_postshadow_report(self, junction, report, run, theta_overrides, alpha, dx_um, dy_um):
        """Builds the full post-shadow measurement + continuity report
        for the "Post-Shadow Measurements & Continuity" card. This
        replaces the old per-shape "survives/doesn't survive" tally with
        this card's originally-intended purpose: the Simulate tab's
        counterpart to Create/Import's own Measurements tree
        (_populate_measurements_tree), but with every dimension
        recalculated from real post-shadow geometry (the exact same
        _compute_finger_shadowed_pieces / _compute_plate_shadowed_points
        / _compute_one_patch_shadowed_pieces functions Post-Shadow
        Result itself renders, so this can never disagree with what's
        actually drawn), plus one final OPEN/SHORTED circuit-continuity
        verdict.

        OPEN reasons are exactly the existing, already-verified
        _check_electrode_contact_disconnections (a leg -- finger + its
        plate + its patches -- never reaches the electrode, i.e. the
        patches are not connected properly to the electrode, or are no
        longer attached to one side or both) and
        _check_post_shadow_disconnections (a finger self-shadows into
        multiple disconnected pieces, plus finger-to-plate gaps and a
        fully-disconnected JJ crossing, all still "major disconnects" in
        the same family) -- reused verbatim rather than re-derived, so
        this can never disagree with the separate Shadowing Warnings
        card.

        SHORT is genuinely new logic, based on three criteria:
          1. No oxide barrier between the two junction fingers -- see
             _oxide_barrier_between_fingers.
          2. A ghost line crosses over the electrode and touches it --
             see _collect_ghost_and_triangle_measurements's
             touches_electrode flag.
          3. Metal-on-metal contact between the two fingers' own "legs"
             (finger + plate + patches) beyond the one legitimate JJ
             crossing footprint -- the two legs are only ever supposed
             to touch at the finger-vs-finger crossing (where the oxide
             barrier actually is, deposited between the two passes);
             any extra overlap between the two full leg unions beyond
             that one footprint (a plate or patch reaching over and
             touching the other leg directly) bridges the barrier and
             is flagged as a short."""
        data = {
            "fingers": [], "plates": {}, "patch_groups": [], "jj_crossing_area_um2": 0.0,
            "ghost_slivers": [], "triangle_groups": [], "open_reasons": [], "short_reasons": [],
        }

        electrode_union = None
        if junction.electrode_polygons:
            try:
                electrode_union = so.unary_union([sg.Polygon(p) for p in junction.electrode_polygons if len(p) >= 3])
            except Exception:
                electrode_union = None

        def electrode_contact_um2(poly):
            if poly is None or electrode_union is None or poly.is_empty:
                return None
            try:
                return poly.intersection(electrode_union).area
            except Exception:
                return None

        def axis_extent(points, axis_hat, perp_hat, origin):
            if not points:
                return 0.0, 0.0
            ax_vals = [(p[0] - origin[0]) * axis_hat[0] + (p[1] - origin[1]) * axis_hat[1] for p in points]
            pv_vals = [(p[0] - origin[0]) * perp_hat[0] + (p[1] - origin[1]) * perp_hat[1] for p in points]
            return (max(ax_vals) - min(ax_vals)), (max(pv_vals) - min(pv_vals))

        # ---- per-finger real geometry (shared by measurements + legs) ----
        pieces_by_finger = []
        axis_by_finger = []
        for i, f in enumerate(junction.fingers):
            try:
                pieces = self._compute_finger_shadowed_pieces(junction, f, i, run, theta_overrides, alpha, dx_um, dy_um)
            except Exception:
                pieces = []
            pieces_by_finger.append(pieces)
            fx, fy = f.patch_end[0] - f.stub_end[0], f.patch_end[1] - f.stub_end[1]
            flen = math.hypot(fx, fy) or 1.0
            axis_hat = (fx / flen, fy / flen)
            perp_hat = (-axis_hat[1], axis_hat[0])
            axis_by_finger.append((axis_hat, perp_hat))

        finger_union_by_idx = {}
        for i, f in enumerate(junction.fingers):
            fname = ji.finger_display_label(i)
            pieces = pieces_by_finger[i]
            axis_hat, perp_hat = axis_by_finger[i]
            finger_polys = []
            for p in pieces:
                try:
                    finger_polys.append(sg.Polygon(p).buffer(0))
                except Exception:
                    pass
            finger_union = so.unary_union(finger_polys) if finger_polys else None
            finger_union_by_idx[i] = finger_union
            length_um, width_um = axis_extent([pt for p in pieces for pt in p], axis_hat, perp_hat, f.stub_end)
            data["fingers"].append({
                "name": fname, "length_um": length_um, "linewidth_nm": width_um * 1000.0,
                "n_pieces": len(pieces), "electrode_um2": electrode_contact_um2(finger_union),
                # Filled in below, once patch groups are known -- a
                # finger's own "end margin" is how far its real
                # post-shadow tip sits past its outermost real patch (the
                # same tip_margin_um already computed per patch group,
                # just surfaced at the finger's own level too instead of
                # being buried only under its patches). None for a
                # finger with no patches at all -- there is no "past the
                # last patch" to measure.
                "end_margin_um": None,
            })

        # ---- JJ crossing(s) (real tunnel-junction footprint) ----
        # Generalized for series-chain designs: this used to hardcode
        # finger index 0 x 1 as the JJ crossing, so a >2-finger chain's
        # other real crossings (and any crossing at all on a design
        # where finger 0/1 aren't the pair that actually crosses) never
        # got a real post-shadow area at all. Generalized to loop every
        # real crossing pair compute_measurements already found
        # (report.jj_crossings, the same N-1-for-a-valid-chain set
        # junction_import.find_all_finger_crossings produces), computing
        # each pair's own real (post-shadow) intersection area from
        # finger_union_by_idx -- byte-identical to the old value for a
        # classic 2-finger design (exactly one crossing pair, (0, 1)).
        data["jj_crossings"] = []
        for cx in report.jj_crossings:
            ci, cj = cx.finger_i, cx.finger_j
            real_area = 0.0
            if finger_union_by_idx.get(ci) is not None and finger_union_by_idx.get(cj) is not None:
                try:
                    real_area = finger_union_by_idx[ci].intersection(finger_union_by_idx[cj]).area
                except Exception:
                    real_area = 0.0
            data["jj_crossings"].append({
                "finger_i": ci, "finger_j": cj,
                "label_i": ji.finger_display_label(ci), "label_j": ji.finger_display_label(cj),
                "area_um2": real_area, "nominal_area_um2": cx.nominal_area_um2,
            })
        # Backward-compat scalar: the first (and, for a classic 2-finger
        # design, only) crossing's own real area -- every existing
        # reader of this field (tests, the tree's per-finger row) keeps
        # working unchanged.
        jj_area = data["jj_crossings"][0]["area_um2"] if data["jj_crossings"] else 0.0
        data["jj_crossing_area_um2"] = jj_area

        # ---- per-plate real geometry ----
        plate_union_by_finger = {}
        for s in junction.other_shapes:
            if s.kind != "plate":
                continue
            nearest_finger = self._find_finger_for_plate(junction, s)
            if nearest_finger is None:
                continue
            fi = junction.fingers.index(nearest_finger)
            try:
                real_pts = self._compute_plate_shadowed_points(junction, s, run, theta_overrides, alpha, dx_um, dy_um)
            except Exception:
                real_pts = None
            plate_poly = None
            length_um = width_um = 0.0
            if real_pts:
                try:
                    plate_poly = sg.Polygon(real_pts).buffer(0)
                except Exception:
                    plate_poly = None
                axis_hat, perp_hat = axis_by_finger[fi]
                length_um, width_um = axis_extent(real_pts, axis_hat, perp_hat, nearest_finger.stub_end)
            plate_union_by_finger[fi] = plate_poly
            fname = ji.finger_display_label(fi)
            # Number of times this adhesion plate is deposited across the
            # whole process: a plate rides along with every one of its
            # owning finger's own official deposition passes (it isn't a
            # separately-scheduled feature), so the count is simply how
            # many real (non-None) thetas that finger has committed --
            # the same theta list _plate_thickness_bands already reads to
            # build this same plate's own thickness banding, reused here
            # rather than re-derived.
            try:
                plate_pass_thetas = [t for t in self._run_finger_thetas(run, fi, nearest_finger, theta_overrides)
                                      if t is not None]
            except Exception:
                plate_pass_thetas = []
            data["plates"][fi] = {
                "name": fname, "length_um": length_um, "width_um": width_um,
                "electrode_um2": electrode_contact_um2(plate_poly),
                "deposition_pass_count": len(plate_pass_thetas),
            }

        # ---- per-patch real geometry, grouped by finger ----
        try:
            patch_thetas = self._true_order_patch_thetas(junction, run, theta_overrides,
                                                          self._resolve_patch_thetas(junction, run, theta_overrides))
        except Exception:
            patch_thetas = []
        patch_union_by_finger = {}
        for pg in report.patch_groups:
            finger = junction.fingers[pg.finger_index]
            fname = ji.finger_display_label(pg.finger_index)
            axis_hat, perp_hat = axis_by_finger[pg.finger_index]
            connector = ji.finger_connector_union(junction, finger)
            patch_entries = []
            group_polys = []
            for k, s in enumerate(self._patches_for_group(junction, finger, pg.patch_count)):
                pieces = []
                if patch_thetas:
                    try:
                        pieces = self._compute_one_patch_shadowed_pieces(junction, finger, s, patch_thetas, alpha, dx_um, dy_um)
                    except Exception:
                        pieces = []
                patch_poly = None
                overlap_um2 = 0.0
                near_ext_um = far_ext_um = None
                width_um = 0.0
                if pieces:
                    try:
                        patch_poly = so.unary_union([sg.Polygon(p).buffer(0) for p in pieces])
                        overlap_um2 = patch_poly.intersection(connector).area
                    except Exception:
                        patch_poly = None
                    all_pts = [pt for p in pieces for pt in p]
                    _len_um, width_um = axis_extent(all_pts, axis_hat, perp_hat, finger.stub_end)
                    ax_vals = [(p[0] - finger.stub_end[0]) * axis_hat[0] + (p[1] - finger.stub_end[1]) * axis_hat[1] for p in all_pts]
                    patch_end_proj = ((finger.patch_end[0] - finger.stub_end[0]) * axis_hat[0]
                                       + (finger.patch_end[1] - finger.stub_end[1]) * axis_hat[1])
                    near_ext_um = min(ax_vals) - patch_end_proj
                    far_ext_um = max(ax_vals) - patch_end_proj
                    group_polys.append(patch_poly)
                patch_entries.append({
                    "k": k, "linewidth_nm": width_um * 1000.0, "overlap_um2": overlap_um2,
                    "near_ext_um": near_ext_um, "far_ext_um": far_ext_um,
                    "electrode_um2": electrode_contact_um2(patch_poly), "real_pieces": pieces,
                })
            group_union = so.unary_union(group_polys) if group_polys else None
            patch_union_by_finger[pg.finger_index] = group_union
            # Post-shadow tip margin: same _finger_past_last_patch_geometry
            # math Create/Import already uses for the nominal figure
            # (pg.finger_tip_past_last_patch_um), just fed this finger's
            # REAL post-shadow tip point + REAL last-patch polygon
            # instead of the as-drawn ones.
            tip_margin = None
            if patch_entries and patch_entries[-1]["real_pieces"]:
                try:
                    finger_union = finger_union_by_idx.get(pg.finger_index)
                    all_finger_pts = [pt for p in pieces_by_finger[pg.finger_index] for pt in p]
                    real_tip = max(
                        all_finger_pts,
                        key=lambda pt: (pt[0] - finger.stub_end[0]) * axis_hat[0] + (pt[1] - finger.stub_end[1]) * axis_hat[1],
                        default=None) if all_finger_pts else None
                    last_patch_real_pts = [pt for p in patch_entries[-1]["real_pieces"] for pt in p]
                    if real_tip is not None and finger_union is not None:
                        plate_poly = plate_union_by_finger.get(pg.finger_index)
                        connector_real = so.unary_union([poly for poly in (finger_union, plate_poly) if poly is not None])
                        _l, _r, shortest = ji._measure_finger_past_last_patch(
                            finger.stub_end, real_tip, connector_real, last_patch_real_pts)
                        tip_margin = shortest
                except Exception:
                    tip_margin = None
            total_contact = sum(e["overlap_um2"] for e in patch_entries) if patch_entries else 0.0
            data["patch_groups"].append({
                "finger_index": pg.finger_index, "name": fname, "patches": patch_entries,
                "tip_margin_um": tip_margin, "total_contact_um2": total_contact,
            })
            # Surface this same tip margin at the finger's own level too
            # (see the "end_margin_um" placeholder set when data["fingers"]
            # was first built above), which was previously only reachable
            # by drilling into this finger's patch group.
            if 0 <= pg.finger_index < len(data["fingers"]):
                data["fingers"][pg.finger_index]["end_margin_um"] = tip_margin

        # ---- ghost slivers + triangle anomalies (with real dimensions) ----
        ghost, triangles = self._collect_ghost_and_triangle_measurements(
            junction, report, run, theta_overrides, alpha, dx_um, dy_um, electrode_union)
        data["ghost_slivers"] = ghost
        data["triangle_groups"] = triangles

        # Total write area: two genuinely distinct totals, both real
        # simulation output, neither a restatement of the other --
        # (1) the nominal (as-drawn) e-beam write area, i.e.
        # report.total_exposed_area_um2 (already computed by
        # junction_import.compute_measurements as the union of every
        # as-designed shape, no double-counting -- this is the area the
        # resist itself gets exposed/patterned to, fixed regardless of
        # deposition angle), and (2) the real, post-shadow total metal
        # footprint actually left behind once shadow-evaporation is
        # accounted for (the union of every real finger/plate/patch
        # polygon this function already computed above, not previously
        # summed anywhere as one combined number).
        data["total_write_area_nominal_um2"] = getattr(report, "total_exposed_area_um2", None)
        try:
            all_real_polys = ([p for p in finger_union_by_idx.values() if p is not None]
                               + [p for p in plate_union_by_finger.values() if p is not None]
                               + [p for p in patch_union_by_finger.values() if p is not None])
            data["total_postshadow_metal_area_um2"] = (
                so.unary_union(all_real_polys).area if all_real_polys else 0.0)
        except Exception:
            data["total_postshadow_metal_area_um2"] = None

        # ==================== FINAL CONTINUITY VERDICT ====================
        data["open_reasons"] = list(
            self._check_electrode_contact_disconnections(junction, report)
            + self._check_post_shadow_disconnections(junction, report, run, theta_overrides, alpha, dx_um, dy_um)
        )

        # Generalized for series-chain designs: both the oxide-barrier
        # check and the leg-bridging check below used to hardcode
        # junction.fingers[0]/[1] as the one JJ crossing to check --
        # meaningless for a >2-finger chain with several real crossings
        # (report.jj_crossings / data["jj_crossings"], from the same
        # generalized find_all_finger_crossings already wired into
        # compute_measurements). Now loops every real crossing pair,
        # checking each one's own oxide barrier and leg-bridge
        # independently -- for a classic 2-finger design there is
        # exactly one crossing pair (0, 1) labeled "A"/"B", so the
        # wording and behavior are byte-identical to before.
        short_reasons = []
        crossing_infos = data["jj_crossings"]
        leg_polys = {}
        for i in range(len(junction.fingers)):
            parts = [poly for poly in (finger_union_by_idx.get(i), plate_union_by_finger.get(i),
                                        patch_union_by_finger.get(i)) if poly is not None]
            leg_polys[i] = so.unary_union(parts) if parts else None
        for cx in crossing_infos:
            ci, cj, li, lj = cx["finger_i"], cx["finger_j"], cx["label_i"], cx["label_j"]
            sid_i, sid_j = junction.fingers[ci].stable_id, junction.fingers[cj].stable_id
            barrier_status = self._oxide_barrier_between_fingers(junction, sid_i, sid_j)
            if barrier_status is False:
                short_reasons.append(
                    f"No oxidation step sits between Finger {li}'s and Finger {lj}'s own deposition passes in the "
                    f"Predicted Recipe Sequence -- there is no tunnel barrier between them.")
            if leg_polys.get(ci) is not None and leg_polys.get(cj) is not None:
                try:
                    total_overlap = leg_polys[ci].intersection(leg_polys[cj]).area
                    if total_overlap > cx["area_um2"] + 1e-4:
                        short_reasons.append(
                            f"Finger {li}'s and Finger {lj}'s own metal (including plates/patches) touch each other "
                            f"over a {total_overlap:.4f} µm² area -- {cx['area_um2']:.4f} µm² of that is the "
                            f"intended JJ crossing, but the rest bridges the two legs somewhere else, bypassing the "
                            f"oxide barrier.")
                except Exception:
                    pass
        for g in ghost:
            if g["touches_electrode"]:
                short_reasons.append(
                    f"A ghost line at {g['location']} (~{g['width_nm']:.1f} nm wide) crosses over and touches the electrode.")
        data["short_reasons"] = short_reasons

        # Area-reduced check: any real post-shadow crossing area below
        # its nominal (as-drawn) area is reported as a failure,
        # independent of whether that crossing is otherwise still
        # "connected". This is a separate failure mode from OPEN/SHORTED:
        # a junction that's fully intact but under-strength is not the
        # same as an open or a short, but it should be flagged just as
        # clearly.
        #
        # Noise tolerance: a very slight deviation between the real and
        # nominal crossing area is expected and should not by itself be
        # considered "area reduced" -- much of the time the shadowing
        # doesn't actually affect the area of the junction at all. The
        # original 1e-6 um^2 absolute floor only ever absorbed the very
        # last bit of float64 rounding noise -- nowhere near enough for
        # the real noise this multi-step shadow geometry pipeline
        # (mill/deposit/foreign-pass polygon ops, each with their own
        # tiny numerical slop) can leave behind on an otherwise perfectly
        # intact crossing, so a design whose shadowing genuinely never
        # touches a crossing at all could still get flagged over a
        # deviation of a small fraction of a percent. Fixed with a
        # two-part check -- both must hold for a shortfall to be treated
        # as real (as opposed to noise):
        #   1. relative_area_ok: the real/nominal ratio (not a fixed
        #      absolute floor) is at or above JJ_CROSSING_FULL_OVERLAP_
        #      RATIO -- the exact same 99.5%-of-nominal threshold this
        #      app's own as-drawn JJ-crossing check (junction_import.
        #      compute_measurements) already uses for the identical
        #      "clean full crossing vs. genuine partial overlap"
        #      judgment call, reused here (not a new, second, possibly-
        #      drifting number) so post-shadow and as-drawn never
        #      disagree about how much shortfall counts as noise.
        #   2. full_overlap_ok: whether the fingers fully overlap after
        #      the shadowing process -- a real geometry sanity check,
        #      not just an area-ratio coincidence: the real post-shadow
        #      crossing (finger_union_by_idx[ci] intersect [cj]) must
        #      still be one single, genuinely continuous region, not
        #      several disjoint fragments that only coincidentally sum to
        #      a similar total area as a real, single full crossing
        #      would. (An earlier draft of this check instead compared
        #      against the as-drawn finger polygons' own raw intersection
        #      -- confirmed wrong by direct testing: real shadow-angle
        #      deposition routinely and correctly produces a post-shadow
        #      metal footprint that legitimately extends beyond the
        #      as-drawn mask shape at the crossing (that's the entire
        #      point of choosing a shadow angle for a T-style crossing),
        #      so the as-drawn polygon is the wrong reference and
        #      incorrectly failed perfectly good designs.)
        # A crossing that fails either check still gets reported exactly
        # as before -- this only widens what counts as "not actually
        # reduced", never narrows it.
        #
        # The "is this crossing's shortfall real, or just noise"
        # determination is stashed directly onto each crossing dict
        # (cx["is_area_reduced"]) rather than only living in area_reasons
        # below -- _populate_postshadow_tree's "Shrink vs. nominal" row
        # and the HTML export's own per-crossing detail line each used to
        # independently re-derive this with the old, much stricter
        # absolute-1e-6 rule, which would have silently kept painting a
        # crossing red / "X% under nominal" even after this fix correctly
        # decided it wasn't a real reduction -- a genuine three-way
        # inconsistency (verdict says fine, tree/HTML still says
        # reduced). Both now just read this single stashed, authoritative
        # answer instead of recomputing their own.
        area_reasons = []
        for cx in crossing_infos:
            real_area, nominal_area = cx["area_um2"], cx["nominal_area_um2"]
            if nominal_area is None or nominal_area <= 1e-9 or real_area >= nominal_area - 1e-9:
                cx["is_area_reduced"] = False
                continue  # not reduced at all (or larger/equal) -- always fine
            relative_area_ok = real_area >= nominal_area * ji.JJ_CROSSING_FULL_OVERLAP_RATIO
            full_overlap_ok = False
            try:
                ci, cj = cx["finger_i"], cx["finger_j"]
                poly_i, poly_j = finger_union_by_idx.get(ci), finger_union_by_idx.get(cj)
                if poly_i is not None and poly_j is not None:
                    post_shadow_crossing = poly_i.intersection(poly_j)
                    full_overlap_ok = (not post_shadow_crossing.is_empty
                                       and post_shadow_crossing.geom_type == "Polygon")
            except Exception:
                full_overlap_ok = False
            if relative_area_ok and full_overlap_ok:
                cx["is_area_reduced"] = False
                continue  # a tiny, noise-level deviation on an otherwise still-fully-crossing junction
            cx["is_area_reduced"] = True
            shrink_pct = (1.0 - real_area / nominal_area) * 100.0
            area_reasons.append(
                f"Finger {cx['label_i']} x Finger {cx['label_j']}'s real (post-shadow) JJ crossing area "
                f"({real_area:.5f} µm²) is less than its nominal design area ({nominal_area:.5f} µm²) -- "
                f"shrunk by {shrink_pct:.1f}%. This junction is under-strength even though it is not fully "
                f"disconnected.")
        data["area_reasons"] = area_reasons

        # Top-level summary tier: at the top of the report, state the
        # overall condition of the junction -- whether the simulation
        # considers it open, shorted, functioning, or "caution" for too
        # many anomalous depositions. OPEN/SHORTED/AREA REDUCED above are
        # all genuine circuit-correctness failures; a design can pass
        # every one of those and still be "functioning" while covered in
        # ghost slivers and triangle deposition artifacts (see
        # ghost/triangle above) that never rise to a hard OPEN/SHORT/AREA
        # verdict on their own (a ghost sliver only becomes a SHORT
        # reason if it actually touches the electrode; most don't). This
        # tier is purely a count of those already-computed,
        # already-displayed anomalies -- no new geometry, no new
        # simulation inputs, nothing beyond what
        # _collect_ghost_and_triangle_measurements already returns -- so
        # it stays entirely derived from this design's own simulation
        # result. Threshold picked as "more than a couple, on an
        # otherwise-clean design" -- a lone stray ghost line is normal
        # background noise on most real geometries and isn't worth a
        # banner; three or more independent artifacts is a real signal
        # something about the deposition sequence/angles is producing
        # more foreign metal than intended, worth a human double-check
        # even though nothing here failed outright. Threshold itself is
        # the module-level ANOMALY_CAUTION_THRESHOLD (single source of
        # truth shared with the tree/PDF explanatory text below).
        non_electrode_ghost_count = sum(1 for g in ghost if not g["touches_electrode"])
        triangle_anomaly_count = sum(tg["count"] for tg in triangles)
        data["anomaly_count"] = non_electrode_ghost_count + triangle_anomaly_count

        active_categories = []
        if data["open_reasons"]:
            active_categories.append("OPEN")
        if short_reasons:
            active_categories.append("SHORTED")
        if area_reasons:
            active_categories.append("AREA REDUCED")
        if not active_categories and data["anomaly_count"] >= ANOMALY_CAUTION_THRESHOLD:
            active_categories.append("CAUTION")
        data["verdict"] = " + ".join(active_categories) if active_categories else "OK"
        return data

    def _populate_postshadow_tree(self, tree, data):
        """Renders _compute_postshadow_report's data into
        self.sim_postshadow_tree, following the exact same add_row
        closure / collapsed-by-default-except-the-important-bit pattern
        _populate_measurements_tree uses for Create/Import's own
        Measurements tree."""
        def add_row(parent, label, value=""):
            item = QTreeWidgetItem([label, value])
            (parent.addChild if parent is not None else tree.addTopLevelItem)(item)
            return item

        # Avoid redundant rows: each feature's top-level row already
        # states its own headline number(s) in its value column (e.g.
        # "L=4.148 um, W=180.0 nm") -- children used to then restate
        # those exact same numbers a second time under generic labels
        # ("Total post-shadow length", "Linewidth"). Removed throughout
        # this function: a child row now only appears when it carries
        # genuinely new information the parent row didn't already show.
        for i, fd in enumerate(data["fingers"]):
            finger_item = add_row(None, f"Finger {fd['name']}",
                                   f"L={fd['length_um']:.3f} µm, W={fd['linewidth_nm']:.1f} nm")
            if fd["n_pieces"] > 1:
                piece_item = add_row(finger_item, "Post-shadow pieces (disconnected)", str(fd["n_pieces"]))
                piece_item.setForeground(1, QBrush(QColor("#ff5c5c")))
            if fd["electrode_um2"] is not None:
                add_row(finger_item, "Contact area with electrode", f"{fd['electrode_um2']:.4f} µm²")
            # Finger end margin: the same real tip-margin figure already
            # computed per patch group, surfaced here too so it reads
            # naturally under the finger's own row, not only nested
            # under "... Patches" further down.
            if fd.get("end_margin_um") is not None:
                add_row(finger_item, "End margin (real tip past last patch)", f"{fd['end_margin_um']:+.3f} µm")

        # Generalized for series-chain designs: a dedicated section
        # listing every real JJ crossing (not just finger 0 x 1's,
        # folded silently into finger 0's own row) with its real
        # post-shadow area next to its nominal (as-drawn) area and the
        # shrink, if any -- the same "real vs nominal" comparison
        # area_reasons below flags as a failure.
        if data["jj_crossings"]:
            for cx in data["jj_crossings"]:
                real_area, nominal_area = cx["area_um2"], cx["nominal_area_um2"]
                cx_item = add_row(None, f"JJ Crossing: Finger {cx['label_i']} x Finger {cx['label_j']}",
                                   f"{real_area:.5f} µm²")
                if nominal_area is not None:
                    add_row(cx_item, "Nominal (as-drawn) area", f"{nominal_area:.5f} µm²")
                    # "under" (any real numeric shortfall, shown for
                    # transparency) and "is_area_reduced" (the
                    # authoritative "does this actually count as reduced"
                    # answer, stashed by _compute_postshadow_report's own
                    # combined relative-area + geometric-overlap check)
                    # are deliberately different: a noise-level shortfall
                    # still shows its real percentage here (so it's never
                    # hidden), it just isn't colored/treated as a failure
                    # the way a genuine reduction is.
                    under = nominal_area > 1e-9 and real_area < nominal_area - 1e-9
                    is_reduced = cx.get("is_area_reduced", False)
                    if under:
                        shrink_text = f"{(1.0 - real_area / nominal_area) * 100.0:.1f}% under nominal"
                        if not is_reduced:
                            shrink_text += " (within noise tolerance -- not counted as reduced)"
                    else:
                        shrink_text = "none -- at or above nominal"
                    shrink_row = add_row(cx_item, "Shrink vs. nominal", shrink_text)
                    if is_reduced:
                        shrink_row.setForeground(1, QBrush(QColor("#ff5c5c")))

        for fi in sorted(data["plates"].keys()):
            pd = data["plates"][fi]
            plate_item = add_row(None, f"Finger {pd['name']}'s Adhesion Plate",
                                  f"{pd['length_um']:.3f} × {pd['width_um']:.3f} µm")
            if pd["electrode_um2"] is not None:
                add_row(plate_item, "Contact area with electrode", f"{pd['electrode_um2']:.4f} µm²")
            # Number of times this adhesion plate is deposited across
            # the whole process.
            if pd.get("deposition_pass_count") is not None:
                add_row(plate_item, "Deposition passes reaching this plate", str(pd["deposition_pass_count"]))

        for pgd in data["patch_groups"]:
            group_item = add_row(None, f"Finger {pgd['name']} Patches", f"n={len(pgd['patches'])}")
            for pe in pgd["patches"]:
                patch_item = add_row(group_item, f"patch[{pe['k']}]", f"W={pe['linewidth_nm']:.1f} nm")
                # Same real, already-computed post-shadow numbers,
                # labeled as near/far "margin" rather than "extension" to
                # match how these measurements are commonly described.
                # near = the patch edge closest to the finger's own
                # connection point; far = its outermost edge.
                if pe["near_ext_um"] is not None:
                    add_row(patch_item, "Near-end margin (post-shadow)", f"{pe['near_ext_um']:+.3f} µm")
                if pe["far_ext_um"] is not None:
                    add_row(patch_item, "Far-end margin (post-shadow)", f"{pe['far_ext_um']:+.3f} µm")
                add_row(patch_item, "Overlap with connector (finger/plate)", f"{pe['overlap_um2']:.4f} µm²")
                if pe["electrode_um2"] is not None:
                    add_row(patch_item, "Contact area with electrode", f"{pe['electrode_um2']:.4f} µm²")
            if pgd["tip_margin_um"] is not None:
                add_row(group_item, "Tip margin (finger tip past last patch)", f"{pgd['tip_margin_um']:.3f} µm")
            add_row(group_item, "Total contact area (all patches)", f"{pgd['total_contact_um2']:.4f} µm²")

        if data["ghost_slivers"]:
            ghost_item = add_row(None, "Ghost Lines (foreign metal slivers)", f"n={len(data['ghost_slivers'])}")
            for g in data["ghost_slivers"]:
                row = add_row(ghost_item, g["location"], f"{g['length_um']:.3f} µm × {g['width_nm']:.1f} nm")
                if g["touches_electrode"]:
                    touch_item = add_row(row, "Touches electrode", "YES -- shorts to electrode")
                    touch_item.setForeground(1, QBrush(QColor("#ff5c5c")))

        if data["triangle_groups"]:
            tri_item = add_row(None, "Triangle Deposition Anomalies", f"{len(data['triangle_groups'])} group(s)")
            for tg in data["triangle_groups"]:
                size_text = (f"leg~{tg['leg_min_nm']:.1f} nm, area~{tg['area_min_um2']:.5f} µm²" if tg["count"] == 1
                             else f"{tg['count']}x, legs {tg['leg_min_nm']:.1f}-{tg['leg_max_nm']:.1f} nm, "
                                  f"areas {tg['area_min_um2']:.5f}-{tg['area_max_um2']:.5f} µm²")
                tri_row = add_row(tri_item, tg["location"], size_text)
                # Length, width, and side lengths for deposition
                # anomalies: this construction's own geometry is a
                # generally scalene triangle (the old right-angle
                # assumption was explicitly eliminated -- see
                # _collect_ghost_and_triangle_measurements's own
                # comment), so there is no universal "hypotenuse" the
                # way a right triangle has one. All 3 real side lengths
                # are shown instead of asserting one that may not exist;
                # side 3 (the longest) is the closest honest analogue of
                # "the long side" a hypotenuse would be.
                if tg["count"] == 1:
                    add_row(tri_row, "3 side lengths",
                            f"{tg['side1_min_nm']:.1f} / {tg['side2_min_nm']:.1f} / {tg['side3_min_nm']:.1f} nm "
                            "(shortest / middle / longest -- generally scalene, not a right triangle, so there "
                            "is no single \"hypotenuse\")")
                else:
                    add_row(tri_row, "3 side lengths across the group",
                            f"shortest {tg['side1_min_nm']:.1f}-{tg['side1_max_nm']:.1f} nm, middle "
                            f"{tg['side2_min_nm']:.1f}-{tg['side2_max_nm']:.1f} nm, longest "
                            f"{tg['side3_min_nm']:.1f}-{tg['side3_max_nm']:.1f} nm")

        # Total write area: the nominal (as-drawn, e-beam exposed) write
        # area and the real post-shadow total metal footprint are
        # genuinely different numbers -- shown together, clearly
        # labeled, so neither reads as a restatement of the other.
        if data.get("total_write_area_nominal_um2") is not None or data.get("total_postshadow_metal_area_um2") is not None:
            totals_item = add_row(None, "Design Totals")
            if data.get("total_write_area_nominal_um2") is not None:
                add_row(totals_item, "Total write area (nominal, as-drawn e-beam exposure)",
                        f"{data['total_write_area_nominal_um2']:.4f} µm²")
            if data.get("total_postshadow_metal_area_um2") is not None:
                add_row(totals_item, "Total metal area (real, post-shadow)",
                        f"{data['total_postshadow_metal_area_um2']:.4f} µm²")

        verdict = data["verdict"]
        verdict_item = add_row(None, "Circuit Continuity")
        verdict_item.setExpanded(True)
        if verdict == "OK":
            vrow = add_row(verdict_item, "Verdict", "✓ OK -- appears electrically continuous, no short detected")
            vrow.setForeground(1, QBrush(QColor("#8fd694")))
        elif verdict == "CAUTION":
            vrow = add_row(verdict_item, "Verdict",
                            f"⚠ CAUTION -- no open/short/area failure, but {data['anomaly_count']} "
                            "ghost-line/triangle deposition anomalies were found (see below)")
            vrow.setForeground(1, QBrush(QColor("#ffcc66")))
        else:
            vrow = add_row(verdict_item, "Verdict", f"✗ {verdict}")
            vrow.setForeground(1, QBrush(QColor("#ff5c5c")))
        for reason in data["open_reasons"]:
            r = add_row(verdict_item, "Open", reason)
            r.setForeground(1, QBrush(QColor("#ff5c5c")))
        for reason in data["short_reasons"]:
            r = add_row(verdict_item, "Short", reason)
            r.setForeground(1, QBrush(QColor("#ff8f6b")))
        for reason in data.get("area_reasons", []):
            r = add_row(verdict_item, "Area", reason)
            r.setForeground(1, QBrush(QColor("#ffcc66")))
        if verdict == "CAUTION":
            r = add_row(verdict_item, "Caution",
                        f"{data['anomaly_count']} anomalous deposition artifact(s) found (ghost slivers not "
                        "touching the electrode + triangle deposition artifacts) -- at or above the "
                        f"{ANOMALY_CAUTION_THRESHOLD}-artifact caution threshold. None of these individually "
                        "broke a connection or shorted the electrode, but this many suggests the deposition "
                        "sequence/angles are producing more stray metal than intended.")
            r.setForeground(1, QBrush(QColor("#ffcc66")))

    def _update_sim_shadow_risk(self):
        """Builds the "Post-Shadow Measurements & Continuity" card:
        real post-shadow dimensions for every finger/plate/patch/ghost-
        line/triangle-anomaly (see _compute_postshadow_report), plus the
        disconnection/ghost/triangle WARNING strings that feed the
        separate "Shadowing Warnings" card. Name kept from the card's
        previous "Shadowing Risk Check" incarnation -- still the single
        correct hook point (called from _update_simulate_preview and
        the PDF exporter) for anything that needs the committed run's
        resist stack / PMMA-PMGI-alpha-derived dx,dy."""
        if not hasattr(self, "sim_postshadow_tree"):
            return
        tree = self.sim_postshadow_tree
        tree.clear()
        junction = getattr(self, "_sim_cached_junction", None)
        report = getattr(self, "_sim_cached_report", None)
        if junction is None or report is None:
            return

        # Fixes a significant bug (confirmed against multiple real
        # designs): the disconnection-warning list and
        # the "SHADOWING WARNINGS" banner used to only get (re)computed
        # while this tree's own "Simulated Design" section was the
        # active view -- every other branch below returned before ever
        # touching self._sim_disconnection_warings. So a design that
        # was genuinely disconnected (a patch resized off its finger, a
        # whole layer nudged away from its electrode) showed "No ...
        # disconnections" the instant the view switched to Post-Shadow
        # Result to actually look at the result -- exactly backwards,
        # since that's the view most likely to be open when checking
        # for exactly this. These checks are a design-correctness
        # concern, not a rendering concern, so they no longer depend on
        # which of the three sim views is showing. Split into two
        # categories:
        #   - Nominal checks (patch-contact, electrode-contact): pure
        #     geometry, no theta/alpha/Run Simulation needed at all --
        #     computed unconditionally on every redraw, even before
        #     Run has ever been clicked (a warning should be raised even
        #     before shadowing is simulated).
        #   - Post-shadow checks (finger self-split, JJ crossing
        #     overlap, finger-to-plate gap): need the committed run
        #     angles, so they only apply once Run Simulation has
        #     actually been clicked -- but from then on, apply
        #     regardless of which view is currently showing.
        nominal_warnings = (
            self._check_patch_contact_disconnections(junction, report)
            + self._check_electrode_contact_disconnections(junction, report)
        )

        if not self._sim_has_run:
            QTreeWidgetItem(tree, ["Click \u25b6 Run Shadow Simulation to see the full post-shadow measurement report."])
            self.sim_resist_label.setText("")
            if hasattr(self, "sim_postshadow_verdict_label"):
                self.sim_postshadow_verdict_label.setText("Run \u25b6 Run Shadow Simulation to check circuit continuity.")
                self.sim_postshadow_verdict_label.setStyleSheet(f"color: {TEXT_COLOR}; font-size: 9pt; font-weight: bold;")
            self._sim_disconnection_warnings = nominal_warnings
            self._refresh_shadow_warnings_label()
            return

        run = self._sim_last_run or {}
        alpha = run.get("alpha", 30.0)
        try:
            pmma_nm = float(self.pmma_edit.text()) if hasattr(self, "pmma_edit") else 875.0
        except ValueError:
            pmma_nm = 875.0
        try:
            pmgi_nm = float(self.pmgi_edit.text()) if hasattr(self, "pmgi_edit") else 600.0
        except ValueError:
            pmgi_nm = 600.0
        # Generalized: these labels used to hardcode "PMMA="/"PMGI="
        # regardless of what resist names were actually configured; now
        # reads the same live names the Simulate tab's own card shows
        # (see _sim_resist_label_text).
        top_name = self._sim_resist_label_text("top").rsplit(" thickness", 1)[0]
        bottom_name = self._sim_resist_label_text("bottom").rsplit(" thickness", 1)[0]
        self.sim_resist_label.setText(
            f"Resist stack (from Recipe): {top_name}={pmma_nm:g} nm, {bottom_name}={pmgi_nm:g} nm, alpha={alpha:g}\u00b0")

        # Post-shadow disconnection checks need the committed run
        # angles, computed here so they're available regardless of
        # which view is showing below -- moved ahead of the
        # Simulated-Design-only tree population so switching to Post-
        # Shadow Result (or Optimal Design) right after Run Simulation
        # can never leave these stale (see the bug-fix note above this
        # method).
        theta_overrides = [run.get("theta_a"), run.get("theta_b")]
        try:
            pmma_nm2 = float(self.pmma_edit.text()) if hasattr(self, "pmma_edit") else 875.0
        except ValueError:
            pmma_nm2 = 875.0
        try:
            pmgi_nm2 = float(self.pmgi_edit.text()) if hasattr(self, "pmgi_edit") else 600.0
        except ValueError:
            pmgi_nm2 = 600.0
        dx_um2, dy_um2 = self._shadow_dxdy(pmma_nm2, pmgi_nm2, alpha)
        postshadow_warnings = self._check_post_shadow_disconnections(
            junction, report, run, theta_overrides, alpha, dx_um2, dy_um2)
        cross_axis_warnings = self._check_cross_axis_self_shadow_warnings(
            junction, report, run, theta_overrides, alpha, dx_um2, dy_um2)
        # Ghost junction lines (corrected model) -- dx_um2/dy_um2 reused
        # so this warning can never disagree with the resist stack the
        # rest of this function's own post-shadow checks just used.
        ghost_warnings = self._check_ghost_junction_line_warnings(
            junction, report, run, theta_overrides, alpha, dx_um2, dy_um2)
        # Triangular deposition artifacts -- same dx_um2/dy_um2 reuse as
        # ghost_warnings just above, for the same "can't disagree with
        # the rest of this function's own resist stack" reason.
        triangle_warnings = self._check_triangle_anomaly_warnings(
            junction, run, theta_overrides, alpha, dx_um2, dy_um2)
        self._sim_disconnection_warnings = (nominal_warnings + postshadow_warnings + cross_axis_warnings
                                             + ghost_warnings + triangle_warnings)
        self._refresh_shadow_warnings_label()

        # Shown regardless of which of the three Simulate views
        # (Optimal/Simulated/Post-Shadow) is currently active -- this is
        # a final measurement record, not a rendering concern, same
        # reasoning as the disconnection/ghost/triangle warnings just
        # above (see the bug-fix note near the top of this function).
        data = self._compute_postshadow_report(junction, report, run, theta_overrides, alpha, dx_um2, dy_um2)
        self._sim_postshadow_data = data
        self._populate_postshadow_tree(tree, data)
        if hasattr(self, "sim_postshadow_verdict_label"):
            if data["verdict"] == "OK":
                self.sim_postshadow_verdict_label.setText(
                    "\u2713 Circuit continuity: OK -- appears electrically continuous, no short detected")
                self.sim_postshadow_verdict_label.setStyleSheet("color: #8fd694; font-size: 9pt; font-weight: bold;")
            elif data["verdict"] == "CAUTION":
                # A real, distinct amber state -- no OPEN/SHORTED/AREA
                # REDUCED failure, but enough ghost/triangle deposition
                # anomalies to flag. Kept visually distinct (amber, not
                # red) from a genuine continuity failure below.
                self.sim_postshadow_verdict_label.setText(
                    f"\u26a0 Circuit continuity: CAUTION -- {data['anomaly_count']} deposition anomalies found")
                self.sim_postshadow_verdict_label.setStyleSheet("color: #ffcc66; font-size: 9pt; font-weight: bold;")
            else:
                self.sim_postshadow_verdict_label.setText(f"\u2717 Circuit continuity: {data['verdict']}")
                self.sim_postshadow_verdict_label.setStyleSheet("color: #ff5c5c; font-size: 9pt; font-weight: bold;")

    def _current_recipe_params(self) -> DesignParameters:
        """Same as _current_params(), but with notes cleared -- matches
        the Tk version's for_preview=True convention, since a recipe
        preview/generation pass shouldn't carry stray Tab-1 notes text
        into the recipe context."""
        p = self._current_params()
        return p

    def _hand_edit_fields_for_step(self, step: RecipeStep):
        """Every editable (field_name, label, unit, current_value_str,
        kind) tuple for ONE step -- kind is "regex" (one of
        _HAND_EDIT_FIELD_SPECS, read from .detail) or "angle" (alpha/theta,
        read directly off the RecipeStep). Only fields whose regex
        actually finds a match in THIS step's real detail text are
        offered, so a step that doesn't carry a given parameter (e.g. a
        non-ramp-owner deposition sub-step, which never repeats the rate
        line) never shows a dead/no-op edit field. Searches a sentinel-
        stripped copy of .detail (see
        _apply_hand_edit_to_step): once a field has already been hand-
        edited once, its sentinel markers sit directly between the
        label and its digits and would otherwise make THIS step's own
        pattern stop matching, silently dropping that field's row from
        the panel and losing its 'current value' for the tally."""
        clean_detail = (step.detail or "").replace(_HAND_EDIT_MARK_START, "").replace(_HAND_EDIT_MARK_END, "")
        out = []
        for field_name, label, unit, applies_fn, pattern, fmt in _HAND_EDIT_FIELD_SPECS:
            if not applies_fn(step):
                continue
            m = pattern.search(clean_detail)
            if not m:
                continue
            out.append((field_name, label, unit, m.group(1), "regex"))
        # NOTE: alpha/theta are deliberately NOT offered here anymore --
        # they already sit inside the existing "angle:" navigation link
        # (see _on_recipe_angle_clicked) and nesting a double-click-edit
        # anchor inside that link would be invalid/undefined HTML. Their
        # primary editing surface is Simulate Design's Deposition Angles tree.
        # The old _apply_hand_edit_to_step/_highlight_field_in_detail
        # alpha/theta branches are left in place so OLD saved designs
        # with a persisted Alpha/Theta hand-edit still re-render correctly.
        return out

    def _highlight_field_in_detail(self, detail_text: str, field_label: str) -> str:
        """Wraps whatever value CURRENTLY sits at field_label's spot in
        detail_text (a sentinel-STRIPPED string -- see
        _apply_hand_edit_to_step) in the sentinel highlight markers,
        leaving every other part of the text untouched. A no-op
        (returns detail_text unchanged) if the field's pattern isn't
        found -- shouldn't normally happen since callers only pass
        labels that were actually offered/edited on this step, but a
        silent no-op is safer than raising here (this runs once per
        already-tracked hand-edit while re-rendering, not on the fresh
        edit itself, which already validated its own match)."""
        if field_label in ("Alpha", "Theta"):
            m = _ALPHA_THETA_DETAIL_RE.search(detail_text)
            if not m:
                return detail_text
            group_idx = 1 if field_label == "Alpha" else 2
            return (detail_text[:m.start(group_idx)]
                    + f"{_HAND_EDIT_MARK_START}{m.group(group_idx)}{_HAND_EDIT_MARK_END}"
                    + detail_text[m.end(group_idx):])
        spec = next((s for s in _HAND_EDIT_FIELD_SPECS if s[1] == field_label), None)
        if spec is None:
            return detail_text
        _, label, unit, applies_fn, pattern, fmt = spec
        # Wraps every occurrence the pattern finds, not just
        # the first -- "Target thickness" echoes twice inside .detail (see
        # _HAND_EDIT_FIELD_SPECS above), and both need the highlight so a
        # re-rendered saved edit doesn't show one echo as edited and the
        # other as untouched. Walked back-to-front so earlier spans' string
        # offsets stay valid as later (rightward) ones get their sentinel
        # characters spliced in. Every other field here still has exactly
        # one match, so this is a strict no-op change for them.
        spans = [(m.start(1), m.end(1)) for m in pattern.finditer(detail_text)]
        if not spans:
            return detail_text
        for start, end in reversed(spans):
            detail_text = (detail_text[:start]
                            + f"{_HAND_EDIT_MARK_START}{detail_text[start:end]}{_HAND_EDIT_MARK_END}"
                            + detail_text[end:])
        return detail_text

    def _apply_hand_edit_to_step(self, step: RecipeStep, field_name: str, new_value: float) -> RecipeStep:
        """Returns a NEW RecipeStep (dataclasses.replace -- RecipeStep is
        never mutated in place anywhere else in this app, so this keeps
        the same convention) with field_name freshly hand-edited AND
        every OTHER field this step already has a tracked hand-edit for
        (self._recipe_hand_edits) still highlighted -- not just the
        newest one. Always starts from a sentinel-STRIPPED copy of
        .detail before searching for anything: a left-over sentinel
        from an earlier edit sits directly between a label ("V=") and
        its digits, which otherwise breaks THAT field's own regex match
        on a second edit (a bug caught by
        test_recipe_hand_edit.py -- a repeat edit silently failed to
        match, raised ValueError, and its QMessageBox.critical() modal
        then hung the whole app in headless/offscreen test runs since
        nothing can dismiss it). Raises ValueError if the requested
        field isn't actually present on this step (the panel only
        offers fields _hand_edit_fields_for_step found, so this should
        only trip if called some other way)."""
        clean_detail = (step.detail or "").replace(_HAND_EDIT_MARK_START, "").replace(_HAND_EDIT_MARK_END, "")
        new_alpha, new_theta = step.alpha, step.theta

        if field_name in ("alpha", "theta"):
            # Both the mill and deposition detail-builders
            # (recipe_generator.py) also print "alpha=X deg, theta=Y deg" as
            # the very first line of .detail, entirely separately from
            # the RecipeStep.alpha/.theta fields the on-screen badge and
            # Deposition Slideshow read -- mutating only the field would
            # leave that first line showing the stale value right above
            # the (correctly updated) badge.
            m = _ALPHA_THETA_DETAIL_RE.search(clean_detail)
            if not m:
                raise ValueError("This step's angle text couldn't be found to edit.")
            group_idx = 1 if field_name == "alpha" else 2
            clean_detail = clean_detail[:m.start(group_idx)] + f"{new_value:g}" + clean_detail[m.end(group_idx):]
            this_label = "Alpha" if field_name == "alpha" else "Theta"
            if field_name == "alpha":
                new_alpha = new_value
            else:
                new_theta = new_value
        else:
            spec = next((s for s in _HAND_EDIT_FIELD_SPECS if s[0] == field_name), None)
            if spec is None:
                raise ValueError(f"Unknown hand-edit field '{field_name}'.")
            _, this_label, unit, applies_fn, pattern, fmt = spec
            # Replaces every occurrence the pattern finds,
            # not just the first -- needed for "target_thickness_nm",
            # whose value echoes twice inside .detail ("Target thickness:
            # X nm." and "...cuts shutter at X nm"; see
            # _HAND_EDIT_FIELD_SPECS). Walked back-to-front so earlier
            # matches' offsets stay valid while later ones are rewritten.
            # Every other field here has exactly one match, so this is a
            # strict no-op change for them.
            spans = [(m.start(1), m.end(1)) for m in pattern.finditer(clean_detail)]
            if not spans:
                raise ValueError(f"'{this_label}' doesn't appear in this step's text.")
            new_text = fmt(new_value)
            for start, end in reversed(spans):
                clean_detail = clean_detail[:start] + new_text + clean_detail[end:]

        edited_labels = {he.field_label for he in self._recipe_hand_edits if he.step_index == step.index}
        edited_labels.add(this_label)
        final_detail = clean_detail
        for label in edited_labels:
            final_detail = self._highlight_field_in_detail(final_detail, label)

        # A deposition step's title (a field entirely
        # separate from .detail) carries its own independent " -- Xnm"
        # thickness echo (recipe_generator.py's generate_recipe_steps) -- keep
        # it in sync so a hand-edited thickness never leaves a stale
        # number visible in the title even though .detail was correctly
        # updated. No other hand-editable field appears in a step's title.
        new_title = step.title
        if field_name == "target_thickness_nm":
            tm = _TITLE_THICKNESS_RE.search(step.title or "")
            if tm:
                new_title = step.title[:tm.start(2)] + f"{new_value:g}" + step.title[tm.end(2):]

        return dataclasses.replace(step, title=new_title, alpha=new_alpha, theta=new_theta, detail=final_detail)

    def _on_recipe_hand_edit_committed(self, step_index: str, field_name: str,
                                        field_label: str, new_value_text: str):
        """Applies one hand-edit given the raw text the user typed into
        the inline _InlineHandEditPopup. new_value_text has already been
        validated as a parseable float by the popup itself (it refuses
        to close on a bad value except via Escape-cancel), but this is
        re-validated defensively rather than trusting the caller blindly
        -- a silent `return` on bad input here (no blocking QMessageBox),
        since the popup already gave the user in-place error feedback
        (red border) before ever calling this."""
        try:
            new_value = float(new_value_text)
        except ValueError:
            return
        steps = self._recipe_last_steps
        for i, step in enumerate(steps):
            if step.index != step_index:
                continue
            old_display = None
            for fn, lbl, unit, cur, kind in self._hand_edit_fields_for_step(step):
                if fn == field_name:
                    old_display = cur
                    break
            try:
                new_step = self._apply_hand_edit_to_step(step, field_name, new_value)
            except ValueError:
                return
            steps[i] = new_step
            # Replace any earlier edit to this exact (step, field) rather
            # than piling up duplicate tally entries for the same value.
            self._recipe_hand_edits = [
                he for he in self._recipe_hand_edits
                if not (he.step_index == step_index and he.field_label == field_label)
            ]
            self._recipe_hand_edits.append(RecipeHandEdit(
                step_index=step_index, step_title=step.title, field_label=field_label,
                old_value=str(old_display) if old_display is not None else "?",
                new_value=new_value_text.strip(),
            ))
            self._refresh_recipe_display_after_edit()
            return

    def _refresh_recipe_display_after_edit(self):
        """Re-renders the recipe browser (with the new highlight + tally)
        from the CURRENT self._recipe_last_steps/_recipe_hand_edits --
        shared by every edit commit, and by design-library reload (so a
        restored design shows its saved edits highlighted immediately,
        no re-generation needed). Targets whichever browser last
        actually displayed this recipe (self._recipe_last_browser,
        stashed by _render_recipe_output/_render_recipe_sim_output) -- a
        hand-edit can follow either a Recipe deterministic generation
        (recipe_sim_browser) or an adopted AI draft (whichever
        ctx.recipe_browser rendered it), and both must redraw in place
        rather than always assuming Recipe's own pane. NOTE: the old
        Recipe-tab "Expanded Recipe" text-blob pane (recipe_sim_browser)
        was removed once the Recipe tab switched to showing the real,
        directly-editable recipe tree/table instead -- this whole
        HTML-anchor hand-edit mechanism is now dead code kept only for
        the (currently unused) AI-draft-adoption path, so there is no
        more Recipe-tab browser to fall back to; if nothing has ever
        rendered into a browser via _render_recipe_output, there is
        simply nothing to refresh."""
        if self._recipe_last_params is None:
            return
        target = getattr(self, "_recipe_last_browser", None)
        if target is None:
            return
        target.setHtml(self._build_recipe_html(
            self._recipe_last_steps, self._recipe_last_warnings, self._recipe_last_params,
            source_label=self._recipe_last_source_label))

    def _on_recipe_hand_edit_anchor_double_clicked(self, href: str):
        """Handles a double-click on an `hedit:{step_index}:{field_name}`
        anchor inside a recipe browser (see _RecipeTextBrowser and
        _editable_detail_html) -- the real interaction the user actually
        asked for: double-click a number in the GENERATED recipe text
        itself, backspace it, type a replacement, in place. Replaces the
        earlier separate "Hand-Edit Process Values" card entirely.
        Pops up a small floating _InlineHandEditPopup right where the
        user clicked, pre-filled with the field's current value; on
        commit (Enter, or losing focus with valid text) it calls the
        same _on_recipe_hand_edit_committed that used to be wired to the
        old panel's embedded QLineEdits, so the underlying edit/tally/
        persistence logic is unchanged -- only how the user GETS to it."""
        try:
            _prefix, step_index, field_name = href.split(":", 2)
        except ValueError:
            return
        step = next((s for s in self._recipe_last_steps if s.index == step_index), None)
        if step is None:
            return
        field_label, current_text = None, None
        for fn, lbl, unit, cur, kind in self._hand_edit_fields_for_step(step):
            if fn == field_name:
                field_label, current_text = lbl, cur
                break
        if field_label is None:
            return
        popup = _InlineHandEditPopup(
            current_text,
            on_commit=lambda text, si=step_index, fn=field_name, lbl=field_label:
                self._on_recipe_hand_edit_committed(si, fn, lbl, text),
            parent=self)
        # Stashed on self (not just a local) for two reasons: it's a
        # WA_DeleteOnClose top-level popup, so nothing else keeps a Python
        # reference alive between "show it" and "the user interacts with
        # it" -- and it gives tests something to grab and drive directly
        # (type text, press Enter) without needing real mouse/window-
        # manager double-click simulation under QT_QPA_PLATFORM=offscreen.
        self._active_hand_edit_popup = popup
        popup.move(QCursor.pos())
        popup.show()
        popup.setFocus()

    def _render_recipe_output(self, steps, warnings, params: DesignParameters,
                               source_label: Optional[str] = None, browser: Optional[QTextBrowser] = None):
        """Renders into a recipe pane as HTML -- angle badges become
        <a href="angle:alpha:theta:title"> links, caught by
        _on_recipe_angle_clicked, replicating clickable text-tag behavior
        with Qt's native mechanism for it. `browser` must be passed
        explicitly -- there is no longer a default recipe pane to fall
        back to, so calling this without one is a no-op rather than a
        crash."""
        if browser is None:
            return
        self._recipe_last_browser = browser
        browser.setHtml(self._build_recipe_html(steps, warnings, params, source_label))

    def _build_recipe_html(self, steps, warnings, params: DesignParameters, source_label: Optional[str] = None) -> str:
        """Pure HTML-string builder, factored out of _render_recipe_output
        so Recipe's own recipe browser can reuse the exact same
        rendering (including the clickable angle links) without
        duplicating it or being forced to write into the old tab's
        widget. Also the single place _last_recipe_text (read by both
        tabs' shared Export PDF / Save as .txt handlers) gets set --
        this fixes a bug where it used to sit after an unconditional
        `return`, so it was dead code and _last_recipe_text was never
        actually populated by either tab, making Export/Save silently
        report "nothing to export" even right after generating a recipe."""
        import html as _html
        # Any value in .detail wrapped in
        # the hand-edit sentinel pair (see _apply_hand_edit_to_step) gets
        # a visible highlight right where it appears -- escape first,
        # THEN substitute the sentinels, so the highlight markup itself
        # is never escaped.
        def _highlight(escaped_text: str) -> str:
            return (escaped_text
                    .replace(_HAND_EDIT_MARK_START,
                             "<span style='background-color:#fff3b0; color:#5c4600; "
                             "padding:0 2px; border-radius:2px;'>")
                    .replace(_HAND_EDIT_MARK_END, "</span>"))

        hand_edits = list(getattr(self, "_recipe_hand_edits", []) or [])
        edited_angle_fields = {(he.step_index, he.field_label) for he in hand_edits
                                if he.field_label in ("Alpha", "Theta")}
        edited_labels_by_step = {}
        for he in hand_edits:
            edited_labels_by_step.setdefault(he.step_index, set()).add(he.field_label)

        def _editable_detail_html(step) -> str:
            """Builds one step's rendered detail text with every hand-
            editable numeric field (per _hand_edit_fields_for_step)
            wrapped in an <a href='hedit:index:field_name'> anchor --
            caught by _RecipeTextBrowser's double-click override, which
            pops open _InlineHandEditPopup right there in the text. This
            is the actual intended interaction: double-click a
            number in the generated recipe, backspace it, retype it --
            no separate override panel. A field that already has a
            tracked hand-edit renders bright/white instead of the
            ordinary light-grey so it visually stands out, highlighted
            compared to the other light-grey steps. Alpha/Theta keep their EXISTING
            yellow sentinel-highlight treatment (_highlight/
            _highlight_field_in_detail) since they're edited elsewhere
            (Simulate Design's Deposition Angles tree), not through this
            anchor mechanism -- see _hand_edit_fields_for_step's note on
            why alpha/theta are deliberately excluded from it."""
            clean = (step.detail or "").replace(_HAND_EDIT_MARK_START, "").replace(_HAND_EDIT_MARK_END, "")
            edited = edited_labels_by_step.get(step.index, set())
            # Restore the existing alpha/theta highlight (a *different*
            # sentinel-pair mechanism, unaffected by the hedit-anchor
            # wrapping below since the two use disjoint control chars).
            marked = clean
            if "Alpha" in edited:
                marked = self._highlight_field_in_detail(marked, "Alpha")
            if "Theta" in edited:
                marked = self._highlight_field_in_detail(marked, "Theta")

            fields = self._hand_edit_fields_for_step(step)
            field_label_by_name = {fn: lbl for fn, lbl, unit, cur, kind in fields}
            matches = []
            for field_name, label, unit, current, kind in fields:
                spec = next((sp for sp in _HAND_EDIT_FIELD_SPECS if sp[0] == field_name), None)
                if spec is None:
                    continue
                _, _, _, applies_fn, pattern, fmt = spec
                # Wraps every occurrence the pattern finds
                # (not just the first) in its own anchor -- "Target
                # thickness" echoes twice inside .detail (see
                # _HAND_EDIT_FIELD_SPECS), and both need to be
                # double-click targets pointing at the SAME underlying
                # step_index:field_name so editing either one edits the
                # one real value. Every other field here still has
                # exactly one match, so this is a strict no-op change
                # for them.
                for m in pattern.finditer(marked):
                    matches.append((m.start(1), m.end(1), field_name))
            # Right-to-left so an earlier match's offsets never shift as
            # a later one gets wrapped in sentinel markup first.
            matches.sort(key=lambda t: t[0], reverse=True)
            for start, end, field_name in matches:
                marked = (marked[:start]
                          + _HAND_EDIT_LINK_START + f"{step.index}:{field_name}" + _HAND_EDIT_LINK_SEP
                          + marked[start:end] + _HAND_EDIT_LINK_END
                          + marked[end:])

            escaped = _html.escape(marked).replace("\n", "<br>")
            escaped = _highlight(escaped)  # alpha/theta yellow highlight, if any

            def _sub(m):
                meta, value_text = m.group(1), m.group(2)
                _fn = meta.split(":", 1)[1] if ":" in meta else meta
                label = field_label_by_name.get(_fn, "")
                if label in edited:
                    style = ("color:#ffffff; font-weight:600; text-decoration:underline; "
                              "text-decoration-style:dotted; cursor:pointer;")
                else:
                    style = ("color:#8a8d9e; text-decoration:underline; "
                              "text-decoration-style:dotted; cursor:pointer;")
                return f"<a href='hedit:{meta}' style='{style}' title='Double-click to edit'>{value_text}</a>"

            return _HAND_EDIT_LINK_RE.sub(_sub, escaped)

        parts = ["<div style='font-family: monospace;'>"]
        parts.append("<h2 style='color:#7fb8ff;'>PLASSYS RECIPE</h2>")
        if source_label:
            parts.append(f"<p style='color:#ff8f6b;'>{_html.escape(source_label)}</p>")
        if getattr(params, "project_name", ""):
            parts.append(f"<p style='color:#8a8d9e;'>Project: {_html.escape(params.project_name)}</p>")
        parts.append(f"<p>Deposition Metal: {_html.escape(params.metal_type)} | "
                     f"Electrode Metal: {_html.escape(getattr(params, 'electrode_metal_type', 'Nb'))} | "
                     f"Deposition Alpha: {params.alpha_deposition:.2f} deg | "
                     f"Mill Alpha: {getattr(params, 'alpha_mill', 50.0):.2f} deg</p>")
        # If settings are adjusted for a design and the design is saved,
        # those settings should be exported when the design is exported:
        # this on-screen
        # header used to show only 3 values, well short of what
        # format_recipe_text (recipe_generator.py) already puts at the top
        # of the PLAIN-TEXT recipe that _last_recipe_text feeds to BOTH
        # the .txt and PDF exports below (see _on_ai_save_recipe /
        # _on_ai_export_pdf) -- resist stack, safety margin, JJ area.
        # Bringing the on-screen HTML header up to the same content
        # means whatever Settings actually shaped this design/recipe are
        # visibly tied to it everywhere: on screen, in the saved design
        # (see _save_current_design/_load_design_from_library), and in
        # every exported file, not just buried inside individual mill/
        # gather steps' own detail text.
        resist_bits = []
        if params.pmma_thickness_nm:
            resist_bits.append(f"{_html.escape(params.top_resist_name)} {params.pmma_thickness_nm:g}nm")
        if params.pmgi_thickness_nm:
            resist_bits.append(f"{_html.escape(params.bottom_resist_name)} {params.pmgi_thickness_nm:g}nm")
        if resist_bits:
            parts.append(f"<p style='color:#8a8d9e;'>Resist stack: {' / '.join(resist_bits)} "
                         f"(safety margin {params.safety_margin_nm:g} nm)</p>")
        try:
            jj_area = params.jj_area_um2()
        except Exception:
            jj_area = None
        if jj_area is not None:
            parts.append(f"<p style='color:#8a8d9e;'>JJ area: {jj_area:.4f} µm² "
                         f"({params.horizontal_lw_nm:g} nm horiz x {params.vertical_lw_nm:g} nm vert)</p>")

        for s in steps:
            star = "\u2605 " if s.starred else ""
            color = "#ffd166" if s.starred else "#e8e8ef"
            if s.alpha is not None and s.theta is not None:
                href = f"angle:{s.alpha}:{s.theta}:{_html.escape(s.title)}"
                alpha_txt = f"alpha={s.alpha:.2f}"
                theta_txt = f"theta={s.theta:.2f}"
                if (s.index, "Alpha") in edited_angle_fields:
                    alpha_txt = _highlight(alpha_txt)
                if (s.index, "Theta") in edited_angle_fields:
                    theta_txt = _highlight(theta_txt)
                parts.append(f"<p style='color:{color}; margin-bottom:0;'>{star}[{s.index}] "
                             f"{_html.escape(s.title)} (<a href='{href}' style='color:#8fd694;'>"
                             f"{alpha_txt}, {theta_txt}</a>)</p>")
            else:
                parts.append(f"<p style='color:{color}; margin-bottom:0;'>{star}[{s.index}] "
                             f"{_html.escape(s.title)}</p>")
            detail_html = _editable_detail_html(s)
            parts.append(f"<p style='color:#8a8d9e; margin-top:2px; margin-left: 20px;'>{detail_html}</p>")

        if warnings:
            parts.append("<h3 style='color:#7fb8ff;'>WARNINGS / THINGS TO VERIFY</h3>")
            for w in warnings:
                parts.append(f"<p style='color:#ff8f6b;'>- {_html.escape(w)}</p>")

        if hand_edits:
            parts.append("<h3 style='color:#ffd166;'>HAND-EDITED VALUES</h3>")
            parts.append("<p style='color:#c9c9d4;'>The following were changed by hand after "
                         "generation -- verify each before running on the tool:</p>")
            for he in hand_edits:
                parts.append(
                    f"<p style='color:#ffd166; margin:1px 0;'>- <b>{_html.escape(he.field_label)}</b> "
                    f"for step {_html.escape(he.step_index)} "
                    f"({_html.escape(he.old_value)} \u2192 {_html.escape(he.new_value)})</p>")
        parts.append("</div>")

        # format_recipe_text just echoes s.detail verbatim (recipe_generator.py),
        # so the sentinel-marked text flows straight into _last_recipe_text
        # too -- .txt export and PDF export each do their own final
        # substitution (see _on_ai_save_recipe / _on_ai_export_pdf), plus
        # get the same plain-text tally appended below.
        text = format_recipe_text(steps, warnings, params)
        if hand_edits:
            tally_lines = ["", "-" * 60, "HAND-EDITED VALUES (changed by hand after generation):"]
            for he in hand_edits:
                tally_lines.append(f"  - {he.field_label} for step {he.step_index} "
                                    f"({he.old_value} -> {he.new_value})")
            tally_lines.append("-" * 60)
            text += "\n" + "\n".join(tally_lines)
        self._last_recipe_text = text
        return "".join(parts)

    def _on_recipe_angle_clicked(self, url: QUrl):
        """An underlined alpha/theta link inside a rendered recipe (the
        retired AI Recipe & Verification tab's MY RECIPE pane, or
        Recipe's own recipe pane -- both wire anchorClicked to this same
        handler).

        Fixes a bug: this used to jump to
        the retired Live Angle Tester's own live chamber canvas (self.live_alpha_edit /
        self.live_theta_edit, nav_list row 1) -- a page that only exists
        because the old tabs haven't been removed yet, so this link was
        already scheduled to break. Routes to the shared, always-
        available Settings > Chamber Reference Model page instead (the
        same _ChamberPreviewWidget every other consumer -- Simulate Design's
        inline preview, the Slideshow -- already uses), with the
        clicked step's alpha/theta typed straight into its own fields."""
        href = url.toString()
        if not href.startswith("angle:"):
            return
        _, alpha_s, theta_s, title = href.split(":", 3)
        alpha, theta = float(alpha_s), float(theta_s)
        is_dep = "dep" in title.lower()
        self._show_chamber_reference_tab()
        crw = self.chamber_reference_widget
        idx = crw.reference_combo.findData("deposition" if is_dep else "mill")
        if idx >= 0:
            crw.reference_combo.setCurrentIndex(idx)
        crw.alpha_edit.setText(f"{alpha:g}")
        crw.theta_edit.setText(f"{theta:g}")

    def _make_ai_assistant(self, ctx: _AICtx) -> AIRecipeAssistant:
        host = ctx.host_edit.text().strip() or None
        model = ctx.model_edit.text().strip() or AI_DEFAULT_MODEL
        return AIRecipeAssistant(host=host, model=model)

    def _on_ai_add_images(self, ctx: _AICtx):
        paths, _ = QFileDialog.getOpenFileNames(self, "Add Reference Photos", "",
                                                "Images (*.png *.jpg *.jpeg *.gif *.webp)")
        for p in paths:
            if p not in ctx.reference_images:
                ctx.reference_images.append(p)
                ctx.image_list.addItem(p.split("/")[-1])

    def _on_ai_remove_image(self, ctx: _AICtx):
        row = ctx.image_list.currentRow()
        if row < 0:
            return
        ctx.image_list.takeItem(row)
        del ctx.reference_images[row]

    def _ai_set_busy(self, ctx: _AICtx, busy: bool, message: str = ""):
        ctx.busy = busy
        self._themed(ctx.status_label, lambda: f"color: {DIM_COLOR}; font-size: 8pt; padding-top: 4px;")
        if busy:
            ctx.phase = message
            ctx.progress_chars = 0
            ctx.start_time = time.time()
            ctx.last_activity_time = ctx.start_time
            ctx.timeout_call_id = ctx.call_seq  # snapshot: this timer only applies to THIS call
            ctx.idle_timeout_dynamic = self.AI_IDLE_TIMEOUT_SECONDS  # reset; bumped once image count is known
            ctx.status_label.setText(message)
            ctx.timer.start()
        else:
            ctx.timer.stop()
            ctx.status_label.setText(message)

    def _ai_update_phase(self, ctx: _AICtx, call_id: int, phase_text: str):
        """A phase change IS progress -- reset the idle clock. Ignored if
        a newer/timed-out call has since superseded this one."""
        if call_id != ctx.call_seq:
            return
        ctx.phase = phase_text
        ctx.progress_chars = 0
        ctx.last_activity_time = time.time()

    def _ai_set_image_count(self, ctx: _AICtx, call_id: int, n: int):
        """Called once we know exactly how many images are going into
        this call, so the idle-timeout budget can scale with it. Local
        VL-model prefill time scales with image count, not just
        wall-clock chance -- a fixed 240s budget that's barely enough for
        0 images will legitimately not be enough for 10, independent of
        anything being 'stuck': this is exactly
        what broke down around 16 images before this scaling existed."""
        if call_id != ctx.call_seq:
            return
        ctx.idle_timeout_dynamic = self.AI_IDLE_TIMEOUT_SECONDS + self.AI_IDLE_TIMEOUT_PER_IMAGE_SECONDS * n
        ctx.last_activity_time = time.time()  # knowing the image count is itself real progress

    def _ai_update_progress(self, ctx: _AICtx, call_id: int, chars_so_far: int):
        """Called as the model streams its response, so the person can
        see it's actively writing rather than staring at a static
        message. Each call is itself evidence the call is alive -- reset
        the idle clock regardless of whether the char count changed."""
        if call_id != ctx.call_seq:
            return
        ctx.progress_chars = chars_so_far
        ctx.last_activity_time = time.time()

    def _ai_tick(self, ctx: _AICtx):
        """Runs once a second (per-ctx timer) while that ctx's AI call is
        in flight: updates the elapsed-time + live phase/progress
        display, and gives up (treating it as a failure) if there's been
        no progress for the dynamic idle budget, or if
        AI_ABSOLUTE_MAX_SECONDS is hit regardless of ongoing progress."""
        if not ctx.busy or ctx.timeout_call_id != ctx.call_seq:
            return  # a newer call superseded this one, or we're not busy anymore -- stop ticking

        now = time.time()
        elapsed = now - ctx.start_time
        idle = now - ctx.last_activity_time
        idle_budget = ctx.idle_timeout_dynamic
        timed_out_idle = idle > idle_budget
        timed_out_absolute = elapsed > self.AI_ABSOLUTE_MAX_SECONDS
        if timed_out_idle or timed_out_absolute:
            # Invalidate this call's id so if the worker thread DOES
            # eventually finish (we can't forcibly kill it), its result
            # gets silently discarded instead of popping up after the
            # fact and confusing whatever the user's doing by then.
            ctx.call_seq += 1
            self._ai_set_busy(ctx, False, "")
            if timed_out_idle:
                reason = (
                    f"No progress for {idle_budget:.0f}s (last activity: {ctx.phase!r}) -- "
                    "treating it as stuck. Check `ollama ps` in Terminal (empty = it never even started; "
                    "a model listed with no progress for a while = genuinely stuck, try `brew services "
                    "restart ollama`). You can also use fewer reference photos or shorten your notes and try again."
                )
            else:
                reason = (
                    f"Hit the hard {self.AI_ABSOLUTE_MAX_SECONDS}s cap even though it was still making "
                    "progress -- this is an unusually long response. If this keeps happening, consider "
                    "a smaller/faster model, fewer reference photos, or a shorter recipe/notes."
                )
            ctx.status_label.setStyleSheet("color: #ffd166; font-size: 8pt; padding-top: 4px;")
            ctx.status_label.setText(f"AI call gave up after {elapsed:.0f}s -- {reason}")
            return

        progress_note = f", {ctx.progress_chars} chars written so far" if ctx.progress_chars else ""
        ctx.status_label.setText(
            f"{ctx.phase}  ({elapsed:.0f}s elapsed{progress_note}; "
            f"will give up after {idle_budget:.0f}s with no progress, "
            f"hard cap {self.AI_ABSOLUTE_MAX_SECONDS}s)"
        )

    def _gather_app_context(self) -> dict:
        """Defensively collects whatever live app state currently exists,
        for the app-wide "Ask AI" assistant (see ASSISTANT_SYSTEM_PROMPT).
        Deliberately NOT keyed off which literal tab index is active --
        the assistant works the same way regardless of which tab the
        question was asked from, so this just gathers everything that
        might exist right now and lets the model use whatever's relevant.
        Every field is wrapped defensively: an empty/mid-setup design
        (nothing created yet, diagnostic not run, no recipe generated)
        is a completely normal state to ask a question from, not an
        error -- so a missing piece just becomes None/empty here rather
        than raising."""
        context = {}

        try:
            current_item = self.nav_list.currentItem()
            context["current_tab"] = current_item.text() if current_item else None
        except Exception:
            context["current_tab"] = None

        try:
            params = self._current_recipe_params()
            context["design_parameters"] = _ai_params_to_dict(params)
        except Exception:
            context["design_parameters"] = None

        context["junction_created_or_imported"] = getattr(self, "_sim_cached_junction", None) is not None
        context["angle_diagnostic_run"] = bool(getattr(self, "_sim_angle_diagnostic_run", False))

        # Real per-finger computed geometry -- the app's own rotation-math
        # engine's exact theta_toward_patch_deg/theta_toward_stub_deg/
        # self_shadow_safe_theta_deg values (see junction_import.ImportedFinger),
        # not something to re-derive. This is needed so that a question
        # like "why theta=270 and not 90 for this finger" has something
        # concrete to cite, rather than the model fabricating a tan(theta)
        # derivation instead (theta is never inside tan() in this app's
        # formulas -- see APP_REFERENCE) -- this is what that answer
        # should actually be grounded in.
        try:
            junction = getattr(self, "_sim_cached_junction", None)
            if junction is not None:
                context["junction_geometry"] = {
                    "source_label": junction.source_label,
                    "fingers": [
                        {
                            "stable_id": f.stable_id,
                            "axis_angle_deg": f.axis_angle_deg,
                            "theta_toward_patch_deg": f.theta_toward_patch_deg,
                            "theta_toward_stub_deg": f.theta_toward_stub_deg,
                            "self_shadow_safe_theta_deg": f.self_shadow_safe_theta_deg,
                            "deposited_second": f.deposited_second,
                            "linewidth_um": f.width_um,
                            "length_um": f.length_um,
                        }
                        for f in junction.fingers
                    ],
                }
            else:
                context["junction_geometry"] = None
        except Exception:
            context["junction_geometry"] = None

        # The exact alpha/theta actually committed at the last "Run Angle
        # Diagnostic" / simulation run -- real, already-chosen values, not
        # a recommendation to recompute.
        try:
            run = getattr(self, "_sim_last_run", None)
            context["last_committed_angles"] = dict(run) if run else None
        except Exception:
            context["last_committed_angles"] = None

        try:
            context["shadowing_warnings"] = {
                "zero_deposition_features": list(getattr(self, "_sim_zero_dep_warnings", None) or []),
                "disconnection_warnings": list(getattr(self, "_sim_disconnection_warnings", None) or []),
            }
        except Exception:
            context["shadowing_warnings"] = None

        try:
            steps = getattr(self, "_recipe_last_steps", None)
            context["generated_recipe"] = {
                "step_count": len(steps) if steps else 0,
                "steps": _ai_deterministic_steps_to_dicts(steps) if steps else [],
                "warnings": list(getattr(self, "_recipe_last_warnings", None) or []),
            }
        except Exception:
            context["generated_recipe"] = None

        try:
            context["measurement_tab"] = {
                "has_active_scan_state": getattr(self, "meas_scan_state", None) is not None,
            }
        except Exception:
            context["measurement_tab"] = None

        # Live state for the hand-authored "Recipe Builder (from scratch)"
        # mode -- a separate feature from the deterministic generated_recipe
        # above (see APP_REFERENCE's RECIPE BUILDER section). This is
        # needed so a question like "explain how to use the Recipe
        # Builder" has real grounding for this feature instead of the
        # model fabricating a generic, unrelated tutorial -- APP_REFERENCE
        # now describes the real mechanics, and this block gives it the
        # actual live recipe on top of that static reference, the same
        # way junction_geometry/last_committed_angles ground angle
        # questions instead of leaving the model to guess.
        try:
            builder_open = bool(getattr(self, "recipe_mode_builder_btn", None) and
                                 self.recipe_mode_builder_btn.isChecked())
            path = getattr(self, "_recipe_builder_current_path", None)
            node = self._recipe_builder_current_node() if hasattr(self, "_recipe_builder_current_node") else None
            rb_warnings: list = []
            if node is not None and path:
                try:
                    rb_warnings = [w.display_text() for w in rr.validate_recipe(self._recipe_tree_root, path)]
                except Exception:
                    rb_warnings = []
            context["recipe_builder"] = {
                "mode_active": builder_open,
                "recipe_open": path if node is not None else None,
                "step_count": len(node.steps) if node is not None else 0,
                "warnings": rb_warnings,
            }
        except Exception:
            context["recipe_builder"] = None

        return context

    def _render_ask_ai_history(self, ctx: _AICtx) -> str:
        """Builds the Ask AI panel's full HTML: every completed (question,
        answer/error) pair in ctx.ask_history, PLUS -- if a call is
        currently streaming -- the in-flight question and whatever of its
        answer has arrived so far. Shared by _on_ask_ai_stream (live
        typing, called repeatedly while a call is in flight) and
        _on_ask_ai_done (the final render), so the two can never drift
        out of sync with each other."""
        import html as _html
        parts = []
        for q, a, err in ctx.ask_history:
            if q is not None:
                parts.append(f"<p style='color:{ACCENT_COLOR}; margin-bottom:2px;'><b>You:</b> {_html.escape(q)}</p>")
            if err:
                parts.append(f"<p style='color:#ff5c5c; margin-top:0; margin-bottom:12px;'>{_html.escape(err)}</p>")
            elif a is not None:
                # Keep this readable prose, not recipe-JSON formatting -- convert blank-line-
                # separated paragraphs to <p> tags; everything else stays plain escaped text.
                for p in [p.strip() for p in a.split("\n\n") if p.strip()]:
                    parts.append(f"<p style='margin-top:0; margin-bottom:8px;'>{_html.escape(p)}</p>")
        pending_q = getattr(ctx, "pending_question", None)
        if pending_q is not None:
            parts.append(f"<p style='color:{ACCENT_COLOR}; margin-bottom:2px;'><b>You:</b> {_html.escape(pending_q)}</p>")
            pending_text = getattr(ctx, "pending_stream_text", "") or ""
            if pending_text:
                for p in [p.strip() for p in pending_text.split("\n\n") if p.strip()]:
                    parts.append(f"<p style='margin-top:0; margin-bottom:8px;'>{_html.escape(p)}</p>")
                parts.append("<p style='color:#8a8d9e; margin-top:0;'>&#9646;</p>")  # live typing cursor
            else:
                parts.append("<p style='color:#8a8d9e; margin-top:0;'>...</p>")
        return "".join(parts) if parts else "<p style='color:#8a8d9e;'>Ask a question below.</p>"

    def _on_ask_ai_stream(self, ctx: _AICtx, call_id: int, text_so_far: str):
        """Live-typing display: called as the model streams its response
        (throttled inside AIRecipeAssistant._call to every few chunks, or
        on completion), so the person watches the actual answer appear in
        the panel in real time instead of only a 'N chars written so far'
        status line, matching the live-typing feel of a normal chat
        interface."""
        if call_id != ctx.call_seq:
            return
        ctx.pending_stream_text = text_so_far
        ctx.output_browser.setHtml(self._render_ask_ai_history(ctx))
        sb = ctx.output_browser.verticalScrollBar()
        if sb is not None:
            sb.setValue(sb.maximum())

    def _on_ask_ai_submit(self, ctx: _AICtx):
        """The 'Ask AI' assistant's submit handler -- worker-thread /
        signals / watchdog pattern (see _ai_tick, _ai_set_busy), calling
        answer_question (the sole remaining AI job: open-ended Q&A, never
        recipe generation/judgment) with a freshly gathered app_context,
        and streaming the live answer text into the panel as it's written
        (see _on_ask_ai_stream)."""
        if ctx.busy:
            return
        question = ctx.notes_edit.toPlainText().strip()
        if not question:
            ctx.status_label.setText("Type a question first.")
            return
        assistant = self._make_ai_assistant(ctx)
        app_context = self._gather_app_context()
        images = list(ctx.reference_images)

        ctx.call_seq += 1
        call_id = ctx.call_seq
        if not hasattr(ctx, "ask_history"):
            ctx.ask_history = []  # [(question, answer_text_or_None, error_or_None)] -- this ctx's own Q&A log
        ctx.pending_question = question
        ctx.pending_stream_text = ""
        ctx.output_browser.setHtml(self._render_ask_ai_history(ctx))

        signals = _AIWorkerSignals()
        signals.phase.connect(lambda msg: self._ai_update_phase(ctx, call_id, msg))
        signals.progress.connect(lambda n: self._ai_update_progress(ctx, call_id, n))
        signals.image_count.connect(lambda n: self._ai_set_image_count(ctx, call_id, n))
        signals.answer_stream.connect(lambda text: self._on_ask_ai_stream(ctx, call_id, text))
        signals.done.connect(lambda result, error: self._on_ask_ai_done(ctx, call_id, question, result, error))
        self._ai_set_busy(ctx, True, "Preparing question...")

        def on_progress(text_so_far, chunk_count):
            signals.progress.emit(len(text_so_far))
            signals.answer_stream.emit(text_so_far)

        def worker():
            try:
                signals.image_count.emit(len(images))
                result = assistant.answer_question(
                    app_context, question, image_paths=images,
                    on_phase=lambda m: signals.phase.emit(m),
                    on_progress=on_progress,
                )
                signals.done.emit(result, None)
            except Exception as e:
                signals.done.emit(None, str(e))
        ctx.call_signals = signals  # keep alive for the duration of the call
        threading.Thread(target=worker, daemon=True).start()

    def _on_ask_ai_done(self, ctx: _AICtx, call_id, question: str, answer: Optional[AIAnswer], error: Optional[str]):
        if call_id != ctx.call_seq:
            return
        self._ai_set_busy(ctx, False, "")
        if not hasattr(ctx, "ask_history"):
            ctx.ask_history = []
        ctx.pending_question = None
        ctx.pending_stream_text = ""
        if error:
            ctx.ask_history.append((question, None, error))
        else:
            ctx.status_label.setText("")
            ctx.notes_edit.clear()
            ctx.ask_history.append((question, answer.answer_text, None))
            if answer.image_warnings:
                for w in answer.image_warnings:
                    ctx.ask_history.append((None, None, f"Reference photo warning: {w}"))
        ctx.output_browser.setHtml(self._render_ask_ai_history(ctx))
        # Scroll to the bottom so the newest answer is what's visible.
        sb = ctx.output_browser.verticalScrollBar()
        if sb is not None:
            sb.setValue(sb.maximum())

    def _build_ask_ai_widget(self, bar):
        """The app-wide contextual 'Ask AI' assistant (works across all
        tabs, distinct color, watchdog stays active, can take reference
        photos): a QToolButton pinned to the status
        bar (the one place proven to stay in the same spot on every tab --
        see _build_status_bar's docstring), popping a QWidgetAction-hosted
        panel with a question box, Ask button, photo attach/remove, a
        scrollable Q&A history, and the reused watchdog status label.
        This is purely explanatory/advisory -- see ASSISTANT_SYSTEM_PROMPT
        in ai_assistant.py -- it never generates or edits a
        recipe; the deterministic generator (plus the separate AI
        Draft/Review on Recipe) remains the sole recipe authority."""
        ASK_AI_COLOR = "#c98bff"  # the app's established AI-purple accent, reused here for "distinct color"

        btn = QToolButton(self)
        btn.setText("✨ Ask AI")
        btn.setToolTip("Ask the AI assistant anything about this app, your design, or the physics behind it.")
        btn.setCursor(Qt.PointingHandCursor)
        btn.setStyleSheet(
            f"QToolButton {{ background-color: #2a2140; color: {ASK_AI_COLOR}; border: 1px solid {ASK_AI_COLOR}; "
            f"border-radius: 4px; padding: 3px 10px; font-weight: bold; }} "
            f"QToolButton:hover {{ background-color: #362a52; }} "
            f"QToolButton::menu-indicator {{ image: none; }}"
        )

        panel = QWidget()
        panel.setMinimumWidth(480)
        panel_layout = QVBoxLayout(panel)
        panel_layout.setContentsMargins(10, 10, 10, 10)
        panel_layout.setSpacing(6)

        header = QLabel("Ask AI -- app-wide assistant")
        header.setStyleSheet(f"color: {ASK_AI_COLOR}; font-weight: bold; font-size: 10pt;")
        panel_layout.addWidget(header)
        sub = QLabel("Ask about processes, parameters, why a step is where it is, whether your design "
                     "is viable, how a tab works, etc. This is purely explanatory -- it never generates "
                     "or edits your recipe; the Recipe tab's deterministic generator does that.")
        sub.setWordWrap(True)
        sub.setStyleSheet(f"color: {DIM_COLOR}; font-size: 8pt;")
        panel_layout.addWidget(sub)

        output_browser = QTextBrowser()
        output_browser.setOpenExternalLinks(True)
        output_browser.setMinimumHeight(220)
        output_browser.setHtml("<p style='color:#8a8d9e;'>Ask a question below.</p>")
        panel_layout.addWidget(output_browser, 1)

        question_edit = QTextEdit()
        question_edit.setPlaceholderText("Type anything -- e.g. \"why is there a mill step before the "
                                          "second deposition?\" or \"is my current design viable?\"")
        question_edit.setFixedHeight(70)
        panel_layout.addWidget(question_edit)

        img_row = QHBoxLayout()
        image_list = QListWidget()
        image_list.setFixedHeight(60)
        img_btn_col = QVBoxLayout()
        add_img_btn = QPushButton("Add Photo(s)")
        remove_img_btn = QPushButton("Remove")
        img_btn_col.addWidget(add_img_btn)
        img_btn_col.addWidget(remove_img_btn)
        img_btn_col.addStretch(1)
        img_row.addWidget(image_list, 1)
        img_row.addLayout(img_btn_col)
        panel_layout.addLayout(img_row)

        ask_btn = QPushButton("Ask")
        ask_btn.setStyleSheet(
            f"QPushButton {{ background-color: {ASK_AI_COLOR}; color: #1a1420; font-weight: bold; "
            f"border-radius: 4px; padding: 5px; }} QPushButton:hover {{ background-color: #dbb0ff; }}"
        )
        panel_layout.addWidget(ask_btn)

        status_label = QLabel("")
        status_label.setWordWrap(True)
        status_label.setStyleSheet(f"color: {DIM_COLOR}; font-size: 8pt; padding-top: 4px;")
        panel_layout.addWidget(status_label)

        # Hidden/trivial widgets purely so this reuses _AICtx / _make_ai_assistant
        # unchanged -- Ask AI defaults to the standard local Ollama host/model
        # already used elsewhere in the app; there's no per-panel UI for these
        # since there's only one AI panel left.
        host_edit = QLineEdit("")
        model_edit = QLineEdit(AI_DEFAULT_MODEL)
        for w in (host_edit, model_edit):
            w.setVisible(False)

        ctx = _AICtx(
            self, host_edit=host_edit, model_edit=model_edit, image_list=image_list,
            notes_edit=question_edit, status_label=status_label, output_browser=output_browser,
        )
        self._ask_ai_ctx = ctx  # kept for tests / debugging

        add_img_btn.clicked.connect(lambda: self._on_ai_add_images(ctx))
        remove_img_btn.clicked.connect(lambda: self._on_ai_remove_image(ctx))
        ask_btn.clicked.connect(lambda: self._on_ask_ai_submit(ctx))

        action = QWidgetAction(btn)
        action.setDefaultWidget(panel)
        menu = QMenu(btn)
        self._themed(menu, lambda: (
            f"QMenu {{ background-color: {PANEL_COLOR}; color: {TEXT_COLOR}; border: 1px solid {ASK_AI_COLOR}; }}"
        ))
        menu.addAction(action)
        btn.setMenu(menu)
        btn.setPopupMode(QToolButton.InstantPopup)

        self.ask_ai_button = btn
        bar.addPermanentWidget(btn)

    def _on_ai_save_recipe(self):
        """Shared by the old AI Recipe tab's 'Save Recipe (.txt)' button,
        Recipe's equivalent button, and File > Save Recipe... --
        _last_recipe_text is the one place a generated/adopted recipe's
        text ends up (see _render_recipe_output), regardless of which of
        those entry points produced it."""
        text = getattr(self, "_last_recipe_text", None)
        if not text:
            QMessageBox.information(self, "Nothing to save",
                                     "No recipe has been generated yet -- generate one on the Recipe tab first.")
            return
        path, _ = QFileDialog.getSaveFileName(self, "Save Recipe", "my_plassys_recipe.txt", "Text files (*.txt)")
        if not path:
            return
        # A plain .txt file can't show color, so the hand-edit sentinel
        # pair (see _apply_hand_edit_to_step) becomes a plain-text-safe
        # asterisk marker here instead -- the tally section already
        # appended to _last_recipe_text (see _build_recipe_html) still
        # lists exactly what changed and on which step.
        text = text.replace(_HAND_EDIT_MARK_START, "*").replace(_HAND_EDIT_MARK_END, "*")
        with open(path, "w") as f:
            f.write(text)

    def _recipe_pdf_story(self, text, styles):
        """Builds the reportlab flowable list for a recipe's plain text
        (the same _last_recipe_text this app already builds for .txt
        export) -- bold step headers with an angle badge, indented
        process detail in monospace, and a highlighted warnings section.
        Factored out of _on_ai_export_pdf so the "Final Diagnostic"
        combined report can reuse this exact same recipe rendering as one
        of its sections, rather than reimplementing it --
        _on_ai_export_pdf now just calls this and
        wraps it in its own single-recipe document; the Final Diagnostic
        export calls it too and appends the result into its own larger,
        multi-section story instead of building a separate document."""
        from reportlab.lib import colors
        from reportlab.lib.styles import ParagraphStyle
        from reportlab.platypus import Paragraph, HRFlowable, KeepTogether

        blocks = _parse_recipe_display_text(text)

        title_style = ParagraphStyle("RecipeTitle", parent=styles["Title"], fontSize=17, spaceAfter=2)
        meta_style = ParagraphStyle("RecipeMeta", parent=styles["Normal"], fontSize=9,
                                     textColor=colors.HexColor("#555555"), spaceAfter=6)
        note_style = ParagraphStyle("RecipeNote", parent=styles["Normal"], fontSize=9,
                                     textColor=colors.HexColor("#8a5a10"), spaceAfter=6)
        step_header_style = ParagraphStyle("StepHeader", parent=styles["Heading3"], fontSize=11.5,
                                            textColor=colors.HexColor("#1a3d6d"), spaceBefore=10, spaceAfter=2)
        star_header_style = ParagraphStyle("StepHeaderStar", parent=step_header_style,
                                            textColor=colors.HexColor("#9a6a00"))
        angle_style = ParagraphStyle("Angle", parent=styles["Normal"], fontSize=9,
                                      fontName="Courier", textColor=colors.HexColor("#4a4a4a"), spaceAfter=3)
        detail_style = ParagraphStyle("Detail", parent=styles["Normal"], fontSize=8.3, fontName="Courier",
                                       leading=11, leftIndent=14, spaceAfter=9,
                                       textColor=colors.HexColor("#333333"))
        warn_header_style = ParagraphStyle("WarnHeader", parent=styles["Heading3"], fontSize=11,
                                            textColor=colors.HexColor("#8a1f1f"), spaceBefore=16, spaceAfter=4)
        warn_style = ParagraphStyle("Warn", parent=styles["Normal"], fontSize=9.5,
                                     textColor=colors.HexColor("#8a1f1f"), leftIndent=10, spaceAfter=4)
        hand_edit_header_style = ParagraphStyle("HandEditHeader", parent=styles["Heading3"], fontSize=11,
                                                 textColor=colors.HexColor("#8a6a00"), spaceBefore=16, spaceAfter=4)
        hand_edit_style = ParagraphStyle("HandEdit", parent=styles["Normal"], fontSize=9.5,
                                          textColor=colors.HexColor("#8a6a00"), leftIndent=10, spaceAfter=4)

        def esc(s: str) -> str:
            return (s or "").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")

        # A hand-edited value inside a step's detail text (see
        # _apply_hand_edit_to_step's sentinel wrapping) gets the same
        # highlight treatment in the PDF as on screen --
        # reportlab's own inline <font> markup, applied AFTER esc() so the
        # markup itself survives.
        def pdf_highlight(escaped_text: str) -> str:
            return (escaped_text
                    .replace(_HAND_EDIT_MARK_START, '<font backColor="#fff3b0" color="#5c4600">')
                    .replace(_HAND_EDIT_MARK_END, '</font>'))

        story = []
        for kind, payload in blocks:
            if kind == "preamble" and payload:
                story.append(Paragraph(esc(payload[0]), title_style))
                for line in payload[1:]:
                    style = note_style if line.strip().startswith("\u26a0") else meta_style
                    story.append(Paragraph(esc(line.strip()), style))
                story.append(HRFlowable(width="100%", thickness=0.75, color=colors.HexColor("#999999"), spaceAfter=8))
            elif kind == "step":
                s = payload
                hstyle = star_header_style if s["starred"] else step_header_style
                header_txt = ("\u2605 " if s["starred"] else "") + f"[{s['index']}] {esc(s['title'])}"
                flow = [Paragraph(header_txt, hstyle)]
                if s["angles"]:
                    flow.append(Paragraph(esc(s["angles"]), angle_style))
                if s["detail_lines"]:
                    detail_html = "<br/>".join(pdf_highlight(esc(ln)) for ln in s["detail_lines"])
                    flow.append(Paragraph(detail_html, detail_style))
                story.append(KeepTogether(flow))
            elif kind == "warnings":
                story.append(Paragraph("WARNINGS / THINGS TO VERIFY", warn_header_style))
                for w in payload:
                    story.append(Paragraph("\u2022 " + esc(w), warn_style))
            elif kind == "hand_edits":
                story.append(Paragraph("HAND-EDITED VALUES", hand_edit_header_style))
                story.append(Paragraph("Changed by hand after generation -- verify each before "
                                        "running on the tool.", hand_edit_style))
                for he in payload:
                    story.append(Paragraph("\u2022 " + esc(he), hand_edit_style))
        return story

    def _recipe_tree_pdf_story(self, root, start_path, styles):
        """Builds the reportlab flowable list for the real recipe-tree
        format's Final Diagnostic Report Recipe section. Earlier versions
        of the exported PDF did not recognize the newer recipe-tree
        format at all; this renders the entire Plassys recipe after it
        has been either generated or created by hand, laid out in the
        same list style the old plain-text recipe used, with the added
        detail this tree-based view provides.

        Unlike the old _recipe_pdf_story (which renders a fixed,
        already-flattened text blob only the old recipe_generator pipeline
        ever produces), this works from the real recipe tree directly --
        generated_recipe_export.flatten_recipe_for_report recursively expands
        every "Recipe"-type call row inline, so it renders identically
        whichever way the recipe was built: one level of expansion for
        an Auto-Generated recipe (Complete Process calling its mill/
        Ti-gather/deposition/oxidation leaves), or arbitrarily deep for a
        hand-built one. Every "Recipe" call row is shown with the same
        derived name/thickness/tilt/time summary the on-screen Complete
        Process table shows, immediately followed by the real literal
        Step Type/Parameter/Comment rows it calls into -- giving the same
        sequential list layout the old plain-text recipe had, just for
        the real, directly-editable format."""
        from reportlab.lib import colors
        from reportlab.lib.styles import ParagraphStyle
        from reportlab.platypus import Paragraph, HRFlowable

        def esc(s: str) -> str:
            # reportlab's base14 Helvetica fonts silently drop the small
            # triangle bullet this function uses for nested "Recipe"
            # call rows (title_txt = f"▸ {name_raw}" below) --
            # rendered as a blank/missing glyph in the exported PDF even
            # though it displays fine everywhere this app shows it on
            # screen (a real Qt font engine). See _on_export_final_
            # diagnostic's own esc() for the full glyph-testing writeup;
            # same fix, applied here since this function has its own
            # separate esc().
            s = (s or "").replace("µ", "u").replace("μ", "u").replace(
                "²", "^2").replace("³", "^3").replace("▸", "-").replace("⚠", "!")
            return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")

        title_style = ParagraphStyle("TreeRecipeTitle", parent=styles["Title"], fontSize=17, spaceAfter=2)
        meta_style = ParagraphStyle("TreeRecipeMeta", parent=styles["Normal"], fontSize=9,
                                     textColor=colors.HexColor("#555555"), spaceAfter=6)
        call_style_base = ParagraphStyle("TreeCallHeader", parent=styles["Heading3"], fontSize=11.5,
                                          textColor=colors.HexColor("#1a3d6d"), spaceBefore=8, spaceAfter=1)
        comment_style_base = ParagraphStyle("TreeCallComment", parent=styles["Normal"], fontSize=8.5,
                                             textColor=colors.HexColor("#666666"), spaceAfter=3)
        detail_style_base = ParagraphStyle("TreeDetail", parent=styles["Normal"], fontSize=8.3, fontName="Courier",
                                            leading=11, spaceAfter=7, textColor=colors.HexColor("#333333"))
        warn_style_base = ParagraphStyle("TreeRecipeWarn", parent=styles["Normal"], fontSize=9.5,
                                          textColor=colors.HexColor("#8a1f1f"), spaceBefore=3, spaceAfter=4)

        story = []
        if not start_path:
            story.append(Paragraph(
                "Not yet reached for this design -- build or adopt a recipe on the Recipe "
                "tab to include this section.", meta_style))
            return story

        start_node, rows = rte.flatten_recipe_for_report(root, start_path)
        if start_node is None:
            story.append(Paragraph(
                f'This design\'s linked recipe ("{esc(start_path)}") no longer exists in the '
                "Recipe Library -- it may have been deleted or renamed since it was linked.",
                warn_style_base))
            return story

        story.append(Paragraph(esc(rte._leaf_name(start_path)), title_style))
        story.append(Paragraph(esc(start_path.replace(rtm.PATH_SEP, "  \u203a  ")), meta_style))
        story.append(HRFlowable(width="100%", thickness=0.75, color=colors.HexColor("#999999"), spaceAfter=8))

        INDENT = 14

        def fmt_step_line(step) -> str:
            parts = [p for p in (step.param1, step.param2, step.param3, step.param4) if (p or "").strip()]
            line = step.step_type + ("  " + "  ".join(parts) if parts else "")
            if (step.comment or "").strip():
                line += f"   -- {step.comment.strip()}"
            return line

        buffer_lines: List[str] = []
        buffer_depth = [None]

        def flush():
            if buffer_lines:
                style = ParagraphStyle(f"TreeDetail_{buffer_depth[0]}", parent=detail_style_base,
                                        leftIndent=INDENT + buffer_depth[0] * INDENT)
                story.append(Paragraph("<br/>".join(esc(ln) for ln in buffer_lines), style))
                buffer_lines.clear()
            buffer_depth[0] = None

        call_counter = 0
        for r in rows:
            depth, kind, step, summary = r["depth"], r["kind"], r["step"], r["summary"]
            if kind == "call":
                flush()
                summary = summary or {}
                name_raw = summary.get("name") or step.param1
                if depth == 0:
                    call_counter += 1
                    title_txt = f"[{call_counter}] {name_raw}"
                else:
                    title_txt = f"\u25b8 {name_raw}"
                bits = []
                if summary.get("thickness_nm"):
                    bits.append(f"{summary['thickness_nm']} nm")
                if summary.get("tilt_deg"):
                    bits.append(f"tilt {summary['tilt_deg']}\u00b0")
                if summary.get("time_str"):
                    bits.append(f"time {summary['time_str']}")
                if bits:
                    title_txt += "  \u2014  " + ", ".join(bits)
                style = ParagraphStyle(f"TreeCall_{depth}", parent=call_style_base,
                                        leftIndent=depth * INDENT, fontSize=max(9.5, 11.5 - depth))
                story.append(Paragraph(esc(title_txt), style))
                if (step.comment or "").strip():
                    cstyle = ParagraphStyle(f"TreeCallComment_{depth}", parent=comment_style_base,
                                             leftIndent=depth * INDENT)
                    story.append(Paragraph(esc(step.comment.strip()), cstyle))
            elif kind in ("missing", "cycle"):
                flush()
                if kind == "missing":
                    msg = f'\u26a0 calls "{step.param1}" -- recipe not found (deleted since this was generated/built?)'
                else:
                    msg = (f'\u26a0 calls "{step.param1}" -- already expanded above (circular reference); '
                           "not expanding it again")
                style = ParagraphStyle(f"TreeWarn_{depth}", parent=warn_style_base, leftIndent=depth * INDENT)
                story.append(Paragraph(esc(msg), style))
            else:  # "step"
                if buffer_depth[0] is not None and buffer_depth[0] != depth:
                    flush()
                buffer_depth[0] = depth
                buffer_lines.append(fmt_step_line(step))
        flush()
        return story

    def _on_ai_export_pdf(self):
        """Export the current recipe -- deterministic-generated or
        AI-adopted -- as a nicely typeset PDF. See _recipe_pdf_story for
        the actual flowable-building logic, shared with the "Final
        Diagnostic" combined report's own Recipe section."""
        text = getattr(self, "_last_recipe_text", None)
        if not text or not text.strip():
            QMessageBox.information(self, "Nothing to export", "Generate or adopt a recipe first.")
            return

        try:
            from reportlab.lib.pagesizes import letter
            from reportlab.lib.units import inch
            from reportlab.lib.styles import getSampleStyleSheet
            from reportlab.platypus import SimpleDocTemplate
        except ImportError:
            QMessageBox.critical(
                self, "Missing dependency",
                "PDF export needs the 'reportlab' package, which isn't installed.\n\n"
                "Install it with:\n    pip install reportlab\n\nthen try again.",
            )
            return

        path, _ = QFileDialog.getSaveFileName(self, "Export Recipe PDF", "plassys_recipe.pdf", "PDF (*.pdf)")
        if not path:
            return

        story = self._recipe_pdf_story(text, getSampleStyleSheet())

        try:
            doc = SimpleDocTemplate(
                path, pagesize=letter, title="Plassys Recipe",
                topMargin=0.6 * inch, bottomMargin=0.6 * inch,
                leftMargin=0.7 * inch, rightMargin=0.7 * inch,
            )
            doc.build(story)
        except Exception as e:
            QMessageBox.critical(self, "Export failed", f"Couldn't write the PDF:\n{e}")
            return
        QMessageBox.information(self, "Exported", f"Recipe exported to:\n{path}")

    def _diagnostic_active_state(self):
        """The CURRENTLY ACTIVE design's own junction/report/params,
        mirroring the same source-of-truth switch used everywhere else
        in the app (_display_source: "imported" vs "parametric") --
        shared by the Final Diagnostic report so it always reports on
        whatever design is actually loaded right now, same as every
        other tab."""
        junction = self._imported_junction if self._display_source == "imported" else self._junction
        report = self._imported_report if self._display_source == "imported" else self._report
        params = self._current_params()
        return junction, report, params

    def _meas_table_has_data(self):
        """True once the user has recorded at least one real reading in
        the Measure Resistance table -- the progress signal for the
        Final Diagnostic report's Measurements section (an empty,
        freshly-built table with no readings yet must NOT count as
        'this stage has been reached')."""
        if not hasattr(self, "meas_table"):
            return False
        for r in range(self.meas_table.rowCount()):
            for c in range(self.meas_table.columnCount()):
                item = self.meas_table.item(r, c)
                if item is not None and item.text().strip():
                    return True
        return False

    def _diagnostic_recipe_tree_path(self):
        """Whichever real recipe-tree node currently represents this
        design's Recipe tab state -- the Final Diagnostic Report's Recipe
        section (and its progress gate) must recognize a recipe after it
        has been either generated or created by hand, not just the old
        recipe_generator-based pipeline (self._last_recipe_text), which is
        stale for Auto-Generated mode (it's only ever refreshed as a
        SIDE EFFECT of _generate_recipe_from_sim, purely to feed this
        and a couple of other legacy consumers -- see
        _on_generate_recipe_click's own comment) and never populated at
        all for By-Hand mode.

        Priority, matching how each signal is actually maintained:
          1. This design's own Auto-Generated complete-process link
             (self._current_design_recipe_links["complete_process"]) --
             set directly in memory by _on_generate_recipe_click, so it's
             current even before the design is ever saved.
          2. This design's saved/loaded By-Hand link
             (self._current_design_recipe_link) -- only ever set by
             _save_current_design/_load_design_from_library (see
             _recipe_builder_refresh_design_link_banner), so it's the
             right signal for a design that already has a linked by-hand
             recipe from a prior save.
          3. Whatever recipe is simply open in the shared Recipe tab
             panel right now (self._recipe_builder_current_path) -- the
             only reachable signal for a brand-new, not-yet-saved
             by-hand recipe, which has no formal "link" until Save
             Design is clicked.
        Returns None unless the resolved path is a real, still-existing
        (non-folder) recipe -- a stale/deleted link doesn't count as
        "reached".

        All three signals above are kept correctly scoped to whichever
        project is actually active -- see self._batch_recipe_links' own
        declaration and _switch_active_project_recipe_links for the
        mechanics. Switching to a different cell/junction within the same
        project (e.g. one chip cell vs. another on the same layout)
        leaves all three untouched, so they keep naturally applying
        (letting one project share a single recipe across its cells);
        switching to a genuinely different project (a different GDS/
        script file, or flipping Created<->Imported) replaces all three
        with that project's own last-known state instead (empty/None the
        first time it's seen) -- avoiding a bug where a Final Diagnostic
        export could silently keep showing an unrelated, earlier
        project's recipe."""
        root = getattr(self, "_recipe_tree_root", None)
        if root is None:
            return None
        candidates = [
            (getattr(self, "_current_design_recipe_links", {}) or {}).get("complete_process"),
            getattr(self, "_current_design_recipe_link", None),
            getattr(self, "_recipe_builder_current_path", None),
        ]
        for path in candidates:
            if not path:
                continue
            node = rtm.resolve_path(root, path)
            if node is not None and not node.is_folder:
                return path
        return None

    def _diagnostic_progress_gates(self):
        """Which sections of the Final Diagnostic report have real
        content for the currently active design. The export button needs
        to detect how far along each tab the design actually is, so the
        program can determine the progress made with a given design
        before deciding what to include in the report.

        Each gate reflects a stage genuinely being REACHED for THIS
        design, not just "some state object happens to be non-None
        from a previous design": the simulation gate in particular only
        fires when self._sim_cached_junction IS this design's own
        junction (same identity check the rest of the app already uses
        to detect a stale cache -- see _update_simulate_preview's own
        "switching to a genuinely different design" bug fix), so
        loading a fresh design that's never been simulated doesn't
        pick up a previous design's leftover diagnostic results.

        Recipe/Slideshow state, by contrast, has no such per-design
        identity in the rest of this app either (Slideshow's own
        _on_slideshow_refresh docstring: "a manual pull... whatever
        Recipe last generated") -- gating strictly on "was a recipe
        actually generated this session" matches that existing
        convention rather than inventing a stricter rule found nowhere
        else in the app."""
        junction, report, params = self._diagnostic_active_state()
        sim_matches = junction is not None and getattr(self, "_sim_cached_junction", None) is junction
        gates = {
            "design": junction is not None,
            "sim": sim_matches and (self._sim_angle_diagnostic_run or self._sim_has_run),
            # The old gate only recognized the old recipe_generator text
            # pipeline, which is stale for Auto-Generated recipes and
            # never populated for By-Hand ones, so it failed to detect
            # the newer recipe-tree format at all. See
            # _diagnostic_recipe_tree_path.
            "recipe": self._diagnostic_recipe_tree_path() is not None,
            "measure": self._meas_table_has_data(),
            "interp": getattr(self, "_interp_last_result", None) is not None,
        }
        return junction, report, params, gates

    def _pdf_embed_figure(self, fig, target_width):
        """Rasterizes a matplotlib Figure into a reportlab Image
        flowable scaled to target_width with its original aspect ratio
        preserved. Every Final Diagnostic call site passes either a
        throwaway scratch Figure (built fresh, so the user's own live
        view on screen is never touched/redrawn) or one of the app's
        already-rendered canvases (Create / Import's design, Interpret
        Results' plots) captured exactly as currently shown."""
        import io
        from reportlab.platypus import Image as RLImage
        from reportlab.lib.utils import ImageReader
        buf = io.BytesIO()
        fig.savefig(buf, format="png", dpi=150, facecolor=BG_COLOR)
        buf.seek(0)
        reader = ImageReader(buf)
        iw, ih = reader.getSize()
        height = target_width * (ih / iw) if iw else target_width
        buf.seek(0)
        return RLImage(buf, width=target_width, height=height)

    def _qtree_to_lines(self, tree_widget):
        """Flattens a 2-column QTreeWidget (label, value) into indented
        plain-text lines, depth-first -- used by the Final Diagnostic
        report to reproduce the Shadowing Risk Check panel's own
        Connection/Result tree exactly, instead of re-deriving the same
        survives/fails verdicts a second time and risking the two
        disagreeing."""
        lines = []

        def walk(item, depth):
            label = item.text(0)
            value = item.text(1) if tree_widget.columnCount() > 1 else ""
            lines.append(("  " * depth) + (f"{label}: {value}" if value else label))
            for i in range(item.childCount()):
                walk(item.child(i), depth + 1)

        for i in range(tree_widget.topLevelItemCount()):
            walk(tree_widget.topLevelItem(i), 0)
        return lines

    def _on_export_final_diagnostic(self):
        """A single combined "Final Diagnostic" PDF for the currently
        active design, pulling together every other exportable fact or
        image of that design into one file: dimensions, a design
        picture, simulation/shadowing diagnostics and the
        post-deposition preview, the committed Plassys recipe, the
        room-temperature measurement table, and Interpret Results'
        fit/graphs -- each section included only if that stage has
        actually been reached for this design this session (see
        _diagnostic_progress_gates's own docstring for exactly what
        "reached" means per section), so a design that's only been
        imported and measured produces a report with just those two
        sections, nothing invented or left blank for the rest.

        The layout is reorganized to be compact and polished, with all
        images displaying properly, following a look intended to mirror
        a small design repository/atlas view: a top verdict banner
        (state of the junction -- OK/CAUTION/OPEN/SHORTED/AREA REDUCED,
        echoing a "pill" verdict style) plus a compact KPI tile strip
        (resist thicknesses, electrode thickness, alphas, metals, JJ
        crossing area, anomaly count) now sit right under the title,
        before any section. The color palette, pill/KPI-tile/card visual
        language is a look-and-feel reference only -- every word and
        number below is still pulled from this design's own live
        simulation state exactly as before, never from any external
        source. Section content/gating text is otherwise unchanged from
        the prior version (same "Not yet reached for this design" gating
        strings, same "Committed deposition angles"/"Shadowing
        diagnostics" wording) so nothing that already worked regresses --
        only the layout, styling, and the new banner/KPI strip are new.
        The "Post-shadow measurements & circuit continuity" subsection is
        renamed to "Per-connection survival check": this content was
        never actually lost, it was only ever renamed from sim_risk_tree
        to sim_postshadow_tree as part of a genuine improvement. This is
        a clearer heading, not a restoration."""
        try:
            from reportlab.lib.pagesizes import letter
            from reportlab.lib.units import inch
            from reportlab.lib import colors
            from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
            from reportlab.platypus import (SimpleDocTemplate, Paragraph, HRFlowable, Spacer,
                                             Table, TableStyle, KeepTogether)
        except ImportError:
            QMessageBox.critical(
                self, "Missing dependency",
                "PDF export needs the 'reportlab' package, which isn't installed.\n\n"
                "Install it with:\n    pip install reportlab\n\nthen try again.",
            )
            return

        junction, report, params, gates = self._diagnostic_progress_gates()
        if not gates["design"]:
            QMessageBox.information(self, "Nothing to export", "Create or import a design first.")
            return

        experiment_name = (getattr(params, "project_name", "") or "").strip() or "plassys_design"
        default_name = f"{experiment_name}_final_diagnostic.pdf".replace(" ", "_")
        path, _ = QFileDialog.getSaveFileName(self, "Export Final Diagnostic Report", default_name, "PDF (*.pdf)")
        if not path:
            return

        # ---- palette (style reference ONLY -- see the docstring above) --
        NB = colors.HexColor("#2F5D8C")
        NB_SOFT = colors.HexColor("#eaf0f8")
        OK_C = colors.HexColor("#1f6d2f")
        OK_SOFT = colors.HexColor("#e9f6ec")
        WARN_C = colors.HexColor("#8a5a00")
        WARN_SOFT = colors.HexColor("#fff3d9")
        BAD_C = colors.HexColor("#8a1f1f")
        BAD_SOFT = colors.HexColor("#fdeaea")
        INK = colors.HexColor("#1c2430")
        DIM = colors.HexColor("#5b6472")
        PANEL_BG = colors.HexColor("#f4f6fa")
        BORDER = colors.HexColor("#d8dee8")

        styles = getSampleStyleSheet()
        title_style = ParagraphStyle("FDTitle", parent=styles["Title"], fontName="Helvetica-Bold",
                                      fontSize=21, textColor=NB, spaceAfter=2, leading=25)
        meta_style = ParagraphStyle("FDMeta", parent=styles["Normal"], fontSize=9,
                                     textColor=DIM, spaceAfter=8)
        section_title_style = ParagraphStyle("FDSectionTitle", parent=styles["Normal"], fontSize=12.5,
                                              fontName="Helvetica-Bold", textColor=colors.white)
        subsection_style = ParagraphStyle("FDSubsection", parent=styles["Heading3"], fontSize=10.5,
                                           textColor=NB, spaceBefore=7, spaceAfter=2, fontName="Helvetica-Bold")
        body_style = ParagraphStyle("FDBody", parent=styles["Normal"], fontSize=9, leading=12, spaceAfter=3,
                                     textColor=INK)
        warn_style = ParagraphStyle("FDWarn", parent=styles["Normal"], fontSize=9,
                                     textColor=BAD_C, leftIndent=10, spaceAfter=2)
        ok_style = ParagraphStyle("FDOk", parent=styles["Normal"], fontSize=9,
                                   textColor=OK_C, spaceAfter=3)
        skip_style = ParagraphStyle("FDSkip", parent=styles["Normal"], fontSize=8.5, fontName="Helvetica-Oblique",
                                     textColor=DIM, spaceAfter=3)
        kpi_value_style = ParagraphStyle("FDKpiValue", parent=styles["Normal"], fontSize=11.5,
                                          fontName="Helvetica-Bold", textColor=INK, leading=13)
        kpi_label_style = ParagraphStyle("FDKpiLabel", parent=styles["Normal"], fontSize=7,
                                          textColor=DIM, leading=9)
        verdict_big_style = ParagraphStyle("FDVerdictBig", parent=styles["Normal"], fontSize=16,
                                            fontName="Helvetica-Bold", leading=19)
        verdict_sub_style = ParagraphStyle("FDVerdictSub", parent=styles["Normal"], fontSize=9, leading=12)

        def esc(s):
            # Fixes a bug caught while visually inspecting a real
            # export: reportlab's base14 Helvetica fonts
            # silently drop a handful of glyphs this codebase's own
            # on-screen Qt widgets use freely (µ MICRO SIGN --
            # "µm", ² SUPERSCRIPT TWO -- "µm²", and
            # ⚠ WARNING SIGN) -- Qt renders them fine (real font
            # engine, real Unicode support), so text scraped verbatim
            # from a QTreeWidget (see _qtree_to_lines) into a reportlab
            # Paragraph rendered as a silent blank gap where "µm"
            # should be. Verified directly: degree/times/arrow/em-dash/
            # curly-quote/checkmark/crossmark all render fine in
            # Helvetica; micro sign, superscript two/three, the small
            # triangle bullet (▸, used by _recipe_tree_pdf_story's
            # own esc()), and the warning sign do not. Substituted for
            # ASCII-safe equivalents here, once, so every piece of text
            # this report renders -- KPI tiles, the verdict banner, and
            # every line scraped from the Per-Connection Survival Check
            # tree -- is guaranteed rendered, not silently dropped.
            s = str(s) if s is not None else ""
            s = (s.replace("µ", "u").replace("μ", "u")
                   .replace("²", "^2").replace("³", "^3")
                   .replace("▸", "-").replace("⚠", "!"))
            return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")

        IMG_WIDTH = 6.4 * inch

        def section_bar(text_html):
            """A full-width colored bar flowable -- gives each section a
            card-like divider, echoing the reference repository's own
            panel headers, in place of the old plain heading text."""
            t = Table([[Paragraph(text_html, section_title_style)]], colWidths=[IMG_WIDTH])
            t.setStyle(TableStyle([
                ("BACKGROUND", (0, 0), (-1, -1), NB),
                ("LEFTPADDING", (0, 0), (-1, -1), 9),
                ("TOPPADDING", (0, 0), (-1, -1), 5),
                ("BOTTOMPADDING", (0, 0), (-1, -1), 5),
            ]))
            return t

        def kpi_grid(items):
            """items: [(label, value), ...] -- a compact 4-column KPI
            tile grid (Table cells accept a list of flowables directly),
            matching the reference repository's own KPI-tile look."""
            items = list(items)
            while len(items) % 4 != 0:
                items.append(("", ""))
            cells = [[Paragraph(esc(v), kpi_value_style), Paragraph(esc(k), kpi_label_style)] for k, v in items]
            rows = [cells[i:i + 4] for i in range(0, len(cells), 4)]
            tbl = Table(rows, colWidths=[IMG_WIDTH / 4.0] * 4)
            tbl.setStyle(TableStyle([
                ("BACKGROUND", (0, 0), (-1, -1), PANEL_BG),
                ("BOX", (0, 0), (-1, -1), 0.5, BORDER),
                ("INNERGRID", (0, 0), (-1, -1), 0.5, BORDER),
                ("LEFTPADDING", (0, 0), (-1, -1), 9), ("RIGHTPADDING", (0, 0), (-1, -1), 9),
                ("TOPPADDING", (0, 0), (-1, -1), 6), ("BOTTOMPADDING", (0, 0), (-1, -1), 7),
                ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
            ]))
            return tbl

        story = []
        source_txt = "Created (parametric)" if self._display_source == "parametric" else "Imported"
        story.append(Paragraph(esc(f"Final Diagnostic Report — {experiment_name}"), title_style))
        story.append(Paragraph(
            esc(f"Design source: {source_txt}  |  Generated: "
                f"{datetime.datetime.now().strftime('%Y-%m-%d %H:%M')}"), meta_style))

        # ---------------- Top verdict banner + KPI strip ------------------
        # At the very top of the PDF, state the overall condition of the
        # junction or design being simulated -- whether the simulation
        # considers it open, shorted, functioning, or "caution" for too
        # many anomalous depositions. Computed from the same
        # _compute_postshadow_report data the on-screen Per-Connection
        # Survival Check card and Section 2 below both read -- this
        # banner can never disagree with either. self._update_sim_shadow_
        # risk() is called here, once, up front (rather than down in
        # Section 2 as before) so both the banner and Section 2 read the
        # identical, single computation for this export.
        postshadow_data = None
        if gates["sim"] and hasattr(self, "sim_postshadow_tree"):
            self._update_sim_shadow_risk()
            postshadow_data = getattr(self, "_sim_postshadow_data", None)

        if postshadow_data is None:
            verdict = None
            banner_bg, banner_fg = PANEL_BG, DIM
            banner_label = "— NOT YET SIMULATED"
            banner_sub = ("Run the Angle Diagnostic and Run Simulation on the Simulate Design tab to determine "
                          "circuit continuity for this design.")
        else:
            verdict = postshadow_data["verdict"]
            n_open = len(postshadow_data.get("open_reasons", []))
            n_short = len(postshadow_data.get("short_reasons", []))
            n_area = len(postshadow_data.get("area_reasons", []))
            anomaly_count = postshadow_data.get("anomaly_count", 0)
            if verdict == "OK":
                banner_bg, banner_fg = OK_SOFT, OK_C
                banner_label = "✓ FUNCTIONING"
                banner_sub = ("No open, shorted, or under-area JJ crossings detected -- this design's circuit "
                              "appears fully continuous as configured.")
            elif verdict == "CAUTION":
                banner_bg, banner_fg = WARN_SOFT, WARN_C
                banner_label = "⚠ CAUTION"
                banner_sub = (f"No open/short/area failure, but {anomaly_count} ghost-line/triangle deposition "
                              "anomalies were found -- see “Per-connection survival check” below.")
            else:
                banner_bg, banner_fg = BAD_SOFT, BAD_C
                banner_label = f"✗ {verdict}"
                parts = []
                if n_open:
                    parts.append(f"{n_open} open reason(s)")
                if n_short:
                    parts.append(f"{n_short} short reason(s)")
                if n_area:
                    parts.append(f"{n_area} under-area crossing(s)")
                banner_sub = ((", ".join(parts) + " -- see “Per-connection survival check” below for full "
                               "detail.") if parts else "See “Per-connection survival check” below for full detail.")

        vbig = ParagraphStyle("FDVerdictBigC", parent=verdict_big_style, textColor=banner_fg)
        vsub = ParagraphStyle("FDVerdictSubC", parent=verdict_sub_style, textColor=banner_fg)
        banner = Table([[Paragraph(esc(banner_label), vbig)], [Paragraph(esc(banner_sub), vsub)]],
                       colWidths=[IMG_WIDTH])
        banner.setStyle(TableStyle([
            ("BACKGROUND", (0, 0), (-1, -1), banner_bg),
            ("BOX", (0, 0), (-1, -1), 1.0, banner_fg),
            ("LEFTPADDING", (0, 0), (-1, -1), 12), ("RIGHTPADDING", (0, 0), (-1, -1), 12),
            ("TOPPADDING", (0, 0), (0, 0), 8), ("BOTTOMPADDING", (0, 0), (0, 0), 1),
            ("TOPPADDING", (0, 1), (0, 1), 1), ("BOTTOMPADDING", (0, 1), (0, 1), 8),
        ]))
        story.append(banner)
        story.append(Spacer(1, 6))

        # KPI strip -- the resist thicknesses and electrode thicknesses
        # need to appear somewhere in the report. Resist thicknesses come
        # from params.pmma_thickness_nm/pmgi_thickness_nm (the exact live
        # Simulate Design tab fields -- see MainWindow._current_params).
        # Electrode height comes from self.es_height_edit, a real
        # simulation input (electrode_height_nm * tan(alpha) is the
        # actual electrode-shadow formula the simulation uses -- see
        # compute_electrode_shadow) that previously had no home anywhere
        # in this report.
        try:
            electrode_height_nm = (float(self.es_height_edit.text())
                                    if hasattr(self, "es_height_edit") and self.es_height_edit.text().strip()
                                    else None)
        except ValueError:
            electrode_height_nm = None
        kpi_items = [
            ("Deposition metal", params.metal_type),
            ("Electrode metal", getattr(params, "electrode_metal_type", "Nb")),
            ("Deposition alpha", f"{params.alpha_deposition:.1f}°"),
            ("Mill alpha", f"{getattr(params, 'alpha_mill', 50.0):.1f}°"),
            (f"{params.top_resist_name} thickness",
             f"{params.pmma_thickness_nm:g} nm" if params.pmma_thickness_nm else "—"),
            (f"{params.bottom_resist_name} thickness",
             f"{params.pmgi_thickness_nm:g} nm" if params.pmgi_thickness_nm else "—"),
            ("Electrode height", f"{electrode_height_nm:g} nm" if electrode_height_nm is not None else "—"),
            ("Resist safety margin", f"{params.safety_margin_nm:g} nm"),
        ]
        if report is not None and getattr(report, "jj_crossing_area_um2", None) is not None:
            kpi_items.append(("JJ crossing area", f"{report.jj_crossing_area_um2:.4f} µm²"))
        if postshadow_data is not None:
            kpi_items.append(("Deposition anomalies", str(postshadow_data.get("anomaly_count", 0))))
        story.append(kpi_grid(kpi_items))
        story.append(Spacer(1, 8))
        story.append(HRFlowable(width="100%", thickness=0.75, color=BORDER, spaceAfter=6))

        # ---------------- Section 1: Design Overview (always present) --
        story.append(section_bar("1. Design Overview"))
        story.append(Spacer(1, 4))
        # Fixes a discrepancy where the measured JJ crossing area could
        # appear much bigger than the "nominal" crossing area, even
        # though theoretically they should be the same: params.
        # jj_area_um2() reads the Create tab's own linewidth fields
        # (horizontal_lw_nm/vertical_lw_nm), which only describe the
        # geometry for a parametric ("Created") design -- for an
        # Imported design those fields are just whatever the Create tab
        # last happened to hold, unrelated to the imported geometry, so
        # showing both side by side as "nominal" vs "measured" compared
        # two unrelated numbers and looked like a bug. Only show this
        # line for a parametric design, where it genuinely IS the
        # design's own crossing area; an Imported design's crossing
        # area (below, from the real finger geometry) is the only
        # meaningful "nominal/designed" figure available for it.
        if self._display_source == "parametric":
            try:
                jj_area = params.jj_area_um2()
            except Exception:
                jj_area = None
            if jj_area is not None:
                story.append(Paragraph(esc(f"JJ area (nominal): {jj_area:.4f} um^2 "
                                            f"({params.horizontal_lw_nm:g} nm horiz x {params.vertical_lw_nm:g} nm vert)"),
                                        body_style))
        if report is not None:
            if getattr(report, "jj_crossing_area_um2", None) is not None:
                # compute_measurements() now reports the REAL finger-vs-
                # finger polygon intersection whenever it differs
                # meaningfully from the naive width-product (see its own
                # docstring) -- this is the design's actual crossing
                # area, not a separate "measured after the fact" value.
                story.append(Paragraph(esc(f"JJ crossing area: {report.jj_crossing_area_um2:.4f} um^2"),
                                        body_style))
            if getattr(report, "total_exposed_area_um2", None) is not None:
                story.append(Paragraph(esc(f"Total exposed metal area: {report.total_exposed_area_um2:.4f} um^2"),
                                        body_style))
            if getattr(report, "finger_lengths_um", None):
                lens = ", ".join(f"{v:.3f}" for v in report.finger_lengths_um)
                widths = ", ".join(f"{v:.1f}" for v in getattr(report, "finger_widths_nm", []) or [])
                story.append(Paragraph(esc(f"Finger lengths (um): {lens}"), body_style))
                if widths:
                    story.append(Paragraph(esc(f"Finger widths (nm): {widths}"), body_style))
        # The real, currently-visible Create / Import design preview is
        # self.create_import_fig/self.create_import_ax (see _build_create_import_*/
        # _update_create_import_preview) -- that's what gets embedded below as
        # "a picture of the design" the user is actually looking at. Kept
        # together with its own caption so the two can't be split across
        # a page break.
        if hasattr(self, "create_import_fig"):
            story.append(Spacer(1, 4))
            story.append(KeepTogether([
                Paragraph("Design preview:", subsection_style),
                self._pdf_embed_figure(self.create_import_fig, IMG_WIDTH),
            ]))

        # ---------------- Section 2: Simulation & Shadowing Diagnostics -
        story.append(Spacer(1, 8))
        story.append(section_bar("2. Simulation &amp; Shadowing Diagnostics"))
        story.append(Spacer(1, 4))
        if not gates["sim"]:
            story.append(Paragraph(
                "Not yet reached for this design — run the Angle Diagnostic and/or Run "
                "Simulation on the Simulate Design tab to include this section.", skip_style))
        else:
            run = self._sim_last_run or {}
            if self._sim_has_run:
                angle_bits = [f"alpha={run.get('alpha')}"]
                if run.get("theta_a") is not None:
                    angle_bits.append(f"finger A theta={run.get('theta_a')}")
                if run.get("theta_b") is not None:
                    angle_bits.append(f"finger B theta={run.get('theta_b')}")
                story.append(Paragraph(esc("Committed deposition angles: " + ", ".join(angle_bits)), body_style))
            # Fixes a discrepancy where the PDF could show an issue with
            # the shadowing diagnostics when the app itself showed no
            # warning: this used to dump report.warnings verbatim under
            # an "issues found" heading -- but report.warnings is a
            # general-purpose note list
            # that also carries harmless accounting footnotes (e.g.
            # "shapes overlap by X um^2 -- don't double-count this in a
            # write-time estimate", from patches legitimately
            # overlapping their own finger), NOT the same thing the
            # on-screen Shadowing Risk Check / Shadowing Warnings panels
            # actually check (zero-deposition features and post-shadow
            # disconnections -- see _refresh_shadow_warnings_label).
            # Read the SAME source those panels use instead, so this
            # section can never disagree with what's on screen.
            zero_dep = list(getattr(self, "_sim_zero_dep_warnings", []) or [])
            disconnections = list(getattr(self, "_sim_disconnection_warnings", []) or [])
            if zero_dep or disconnections:
                story.append(Paragraph("Shadowing diagnostics — issues found:", subsection_style))
                if zero_dep:
                    names = ", ".join(zero_dep)
                    story.append(Paragraph(
                        "• " + esc(f"{names} {'has' if len(zero_dep) == 1 else 'have'} no active deposition "
                                   f"layers and will not appear in the result."), warn_style))
                for wtxt in disconnections:
                    story.append(Paragraph("• " + esc(wtxt), warn_style))
            else:
                story.append(Paragraph("Shadowing diagnostics: no warnings — every connection survives as "
                                        "configured.", ok_style))
            # Per-connection survival check -- renamed, same data as
            # before: the same tree the "Per-Connection Survival Check"
            # card on screen shows (real
            # per-feature dimensions, ghost-line/triangle-anomaly sizes,
            # and the final OPEN/SHORTED/AREA REDUCED/CAUTION verdict).
            # Already computed once, up top, for the banner -- just
            # scrape the tree's rows here, no second computation.
            if hasattr(self, "sim_postshadow_tree"):
                risk_lines = self._qtree_to_lines(self.sim_postshadow_tree)
                if risk_lines:
                    story.append(Paragraph("Per-connection survival check:", subsection_style))
                    for line in risk_lines:
                        story.append(Paragraph(esc(line), body_style))
            finger_explanations = getattr(report, "finger_explanations", None) if report is not None else None
            if finger_explanations:
                story.append(Paragraph("Per-finger contact detail:", subsection_style))
                for exp_txt in finger_explanations:
                    story.append(Paragraph("• " + esc(exp_txt), body_style))
            # Images -- each on its OWN throwaway scratch figure so the
            # user's live Simulate Design view is never redrawn/touched.
            # Each is KeepTogether'd with its own caption so a page
            # break can never separate a heading from its image or crop
            # an image mid-figure.
            if self._sim_angle_diagnostic_run:
                fig = Figure(figsize=(6, 6), dpi=100, facecolor=BG_COLOR)
                ax = fig.add_subplot(1, 1, 1)
                draw_imported_junction_preview(ax, junction, report, show_caption=False,
                                                warning1_enabled=True, warning2_enabled=True, show_badges=True)
                ax.set_facecolor(BG_COLOR)
                story.append(Spacer(1, 4))
                story.append(KeepTogether([
                    Paragraph("Angle diagnostic view:", subsection_style),
                    self._pdf_embed_figure(fig, IMG_WIDTH),
                ]))
            if self._sim_has_run:
                fig2 = Figure(figsize=(6, 6), dpi=100, facecolor=BG_COLOR)
                ax2 = fig2.add_subplot(1, 1, 1)
                draw_imported_junction_preview(ax2, junction, report, show_caption=False,
                                                warning1_enabled=True, warning2_enabled=True, show_badges=True)
                self._draw_sim_shadow_visualization(ax2, junction, report)
                ax2.set_facecolor(BG_COLOR)
                story.append(Spacer(1, 4))
                story.append(KeepTogether([
                    Paragraph("Simulated Design (shadow bands):", subsection_style),
                    self._pdf_embed_figure(fig2, IMG_WIDTH),
                ]))

                fig3 = Figure(figsize=(6, 6), dpi=100, facecolor=BG_COLOR)
                ax3 = fig3.add_subplot(1, 1, 1)
                self._draw_post_shadow_design(ax3, junction, report)
                ax3.set_facecolor(BG_COLOR)
                story.append(Spacer(1, 4))
                story.append(KeepTogether([
                    Paragraph("Post-deposition preview (Post-Shadow Result):", subsection_style),
                    self._pdf_embed_figure(fig3, IMG_WIDTH),
                ]))

        # ---------------- Section 3: Recipe ------------------------------
        story.append(Spacer(1, 8))
        story.append(section_bar("3. Plassys Recipe"))
        story.append(Spacer(1, 4))
        if not gates["recipe"]:
            story.append(Paragraph(
                "Not yet reached for this design — build or adopt a recipe on the Recipe "
                "tab to include this section.", skip_style))
        else:
            story.extend(self._recipe_tree_pdf_story(
                self._recipe_tree_root, self._diagnostic_recipe_tree_path(), styles))

        # ---------------- Section 4: Measurements ------------------------
        story.append(Spacer(1, 8))
        story.append(section_bar("4. Room-Temperature Resistance Measurements"))
        story.append(Spacer(1, 4))
        if not gates["measure"]:
            story.append(Paragraph(
                "Not yet reached for this design — record readings on the Measure "
                "Resistance tab to include this section.", skip_style))
        else:
            exp_name = self.meas_experiment_name_edit.text().strip() or "(unnamed experiment)"
            unit = self.meas_unit_combo.currentText()
            pattern_label = self.meas_pattern_combo.currentText()
            story.append(Paragraph(esc(f"Experiment: {exp_name}  |  Pattern: {pattern_label}  |  Units: {unit}"),
                                    body_style))
            rows = self.meas_table.rowCount()
            cols = self.meas_table.columnCount()
            header = [""] + [f"Col {c + 1}" for c in range(cols)]
            table_data = [header]
            for r in range(rows):
                row_vals = [str(r + 1)]
                for c in range(cols):
                    item = self.meas_table.item(r, c)
                    row_vals.append(item.text() if item and item.text().strip() else "-")
                table_data.append(row_vals)
            tbl = Table(table_data, hAlign="LEFT")
            tbl.setStyle(TableStyle([
                ("FONTSIZE", (0, 0), (-1, -1), 7.5),
                ("GRID", (0, 0), (-1, -1), 0.4, BORDER),
                ("BACKGROUND", (0, 0), (-1, 0), NB_SOFT),
                ("ALIGN", (0, 0), (-1, -1), "CENTER"),
            ]))
            story.append(Spacer(1, 3))
            story.append(tbl)

        # ---------------- Section 5: Interpret Results --------------------
        story.append(Spacer(1, 8))
        story.append(section_bar("5. Interpret Results"))
        story.append(Spacer(1, 4))
        if not gates["interp"]:
            story.append(Paragraph(
                "Not yet reached for this design — process a dataset on the Interpret "
                "Results tab to include this section.", skip_style))
        else:
            dataset = self._interp_last_dataset
            result = self._interp_last_result
            if dataset is not None:
                story.append(Paragraph(esc(f"Dataset: {getattr(dataset, 'name', '')}  |  "
                                            f"T_c: {getattr(dataset, 'T_c_kelvin', float('nan')):g} K"), body_style))
            fit = (result or {}).get("fit")
            if fit:
                story.append(Paragraph(esc(
                    f"R_n vs 1/A fit: slope={fit['a1']:.4g}, intercept={fit['a0']:.4g}, "
                    f"R^2={fit['r2']:.4f}  |  J_c = {fit['J_c_uA_um2']:.4g} uA/um^2"), body_style))
            else:
                story.append(Paragraph("No linear fit available (fewer than 2 valid rows).", body_style))
            if hasattr(self, "interp_fig"):
                story.append(Spacer(1, 4))
                story.append(KeepTogether([
                    Paragraph("Main plot:", subsection_style),
                    self._pdf_embed_figure(self.interp_fig, IMG_WIDTH),
                ]))
            if self._interp_last_compare_results and hasattr(self, "interp_compare_fig"):
                story.append(Spacer(1, 4))
                story.append(KeepTogether([
                    Paragraph("Comparison plot:", subsection_style),
                    self._pdf_embed_figure(self.interp_compare_fig, IMG_WIDTH),
                ]))

        try:
            doc = SimpleDocTemplate(
                path, pagesize=letter, title=f"Final Diagnostic Report - {experiment_name}",
                topMargin=0.6 * inch, bottomMargin=0.6 * inch,
                leftMargin=0.7 * inch, rightMargin=0.7 * inch,
            )
            doc.build(story)
        except Exception as e:
            QMessageBox.critical(self, "Export failed", f"Couldn't write the PDF:\n{e}")
            return
        QMessageBox.information(self, "Exported", f"Final Diagnostic Report exported to:\n{path}")

    # ========================================================================
    # Final Diagnostic Report -- HTML "repository" view.
    #
    # An alternative to the PDF export: instead of only a printable PDF,
    # the final diagnostic can also be viewed as a dynamic mini-repository
    # of content from the program's own simulation -- a viewable, dynamic
    # .html file that is far more organized and clickable, and a way to
    # build a steady repository of one's own simulated designs over time.
    # The PDF (_on_export_final_diagnostic, above) stays exactly as it is
    # -- its whole point is printing/viewing in a cleanroom. This is a
    # second, independent view of the exact same underlying data: a
    # single self-contained HTML file (no external fonts/scripts/
    # stylesheets -- must open standalone, offline, on a lab machine),
    # styled in this app's own "quantum blue" palette (BG_COLOR/
    # PANEL_COLOR/ACCENT_COLOR/etc, the same constants the rest of this
    # app already themes with -- see this file's own "Reuse the exact
    # existing palette" comment near their definitions), with native
    # <details>/<summary> collapsible cards (clickable, no JS framework
    # needed) and measurements grouped by feature (finger -> its own
    # plate -> its own patches -> crossings involving it -> anomalies
    # located at it) instead of the flat list the on-screen tree and PDF
    # both still use.
    #
    # Style reference only: an external HTML layout and a folder of
    # example designs were used purely as a look-and-feel reference
    # (panel/KPI-tile/pill patterns) during development -- nothing extra
    # is pulled from that reference. This code reads neither at runtime
    # and contains no data from either; every word/number this function
    # ever writes comes from _diagnostic_progress_gates/
    # _compute_postshadow_report/params/report, i.e. this app's own live
    # simulation state for the currently active design, exactly like the
    # PDF exporter right above it.
    # ========================================================================

    def _fig_to_data_uri(self, fig):
        """Rasterizes a matplotlib Figure to a base64 PNG data: URI --
        the HTML-embedding equivalent of _pdf_embed_figure, so the exact
        same throwaway scratch figures built for the PDF's images can be
        reused verbatim for the HTML repository view (same call sites,
        same figures, just a different final encoding)."""
        import io
        import base64
        buf = io.BytesIO()
        fig.savefig(buf, format="png", dpi=150, facecolor=BG_COLOR)
        buf.seek(0)
        encoded = base64.b64encode(buf.read()).decode("ascii")
        return f"data:image/png;base64,{encoded}"

    @staticmethod
    def _html_esc(s):
        """Plain HTML escaping -- unlike the PDF exporter's esc(), this
        does NOT need to substitute micro-sign/superscript/etc: browsers
        render full Unicode natively, so µm²/± /° all display correctly
        as-is. Only the standard 5 HTML-reserved characters need escaping."""
        s = str(s) if s is not None else ""
        return (s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
                 .replace('"', "&quot;").replace("'", "&#39;"))

    def _recipe_tree_html_story(self, root, start_path):
        """HTML equivalent of _recipe_tree_pdf_story: renders the same
        real recipe-tree data (generated_recipe_export.flatten_recipe_for_report)
        as nested, collapsible <details> cards, so the recipe reads and
        is viewable the way a real Plassys recipe would be. Each "Recipe"
        call is its own
        card (open by default at the top level, collapsed one level
        deeper to keep a big Auto-Generated recipe from opening as one
        enormous wall of text), followed immediately by its own literal
        Step Type/Parameter/Comment rows in a monospace list -- the same
        sequential, real-recipe "list fashion" the PDF's Section 3 uses,
        just clickable/collapsible instead of flat."""
        esc = self._html_esc
        if not start_path:
            return ('<p class="skip">Not yet reached for this design -- build or adopt a recipe on the '
                    'Recipe tab to include this section.</p>')
        start_node, rows = rte.flatten_recipe_for_report(root, start_path)
        if start_node is None:
            return (f'<p class="warn">This design\'s linked recipe ("{esc(start_path)}") no longer exists in '
                     'the Recipe Library -- it may have been deleted or renamed since it was linked.</p>')

        def fmt_step_line(step) -> str:
            parts = [p for p in (step.param1, step.param2, step.param3, step.param4) if (p or "").strip()]
            line = step.step_type + ("  " + "  ".join(parts) if parts else "")
            if (step.comment or "").strip():
                line += f"   -- {step.comment.strip()}"
            return line

        html = [f'<p class="meta">{esc(rte._leaf_name(start_path))} '
                f'<span class="dim">({esc(start_path.replace(rtm.PATH_SEP, " › "))})</span></p>']
        buffer_lines: List[str] = []
        buffer_open = [False]
        call_counter = 0

        def flush():
            if buffer_lines:
                html.append('<pre class="recipe-steps">' + "\n".join(esc(ln) for ln in buffer_lines) + "</pre>")
                buffer_lines.clear()
            if buffer_open[0]:
                html.append("</details>")
                buffer_open[0] = False

        for r in rows:
            depth, kind, step, summary = r["depth"], r["kind"], r["step"], r["summary"]
            if kind == "call":
                flush()
                summary = summary or {}
                name_raw = summary.get("name") or step.param1
                if depth == 0:
                    call_counter += 1
                    title_txt = f"[{call_counter}] {name_raw}"
                else:
                    title_txt = f"▸ {name_raw}"
                bits = []
                if summary.get("thickness_nm"):
                    bits.append(f"{summary['thickness_nm']} nm")
                if summary.get("tilt_deg"):
                    bits.append(f"tilt {summary['tilt_deg']}°")
                if summary.get("time_str"):
                    bits.append(f"time {summary['time_str']}")
                summary_txt = f'<span class="dim"> — {esc(", ".join(bits))}</span>' if bits else ""
                comment_txt = (f'<div class="recipe-comment">{esc(step.comment.strip())}</div>'
                               if (step.comment or "").strip() else "")
                open_attr = " open" if depth == 0 else ""
                html.append(f'<details class="recipe-call depth-{min(depth, 3)}"{open_attr}>'
                            f'<summary>{esc(title_txt)}{summary_txt}</summary>{comment_txt}')
                buffer_open[0] = True
            elif kind in ("missing", "cycle"):
                flush()
                if kind == "missing":
                    msg = f'⚠ calls "{step.param1}" -- recipe not found (deleted since this was generated/built?)'
                else:
                    msg = (f'⚠ calls "{step.param1}" -- already expanded above (circular reference); '
                           "not expanding it again")
                html.append(f'<p class="warn indent-{min(depth, 3)}">{esc(msg)}</p>')
            else:  # "step"
                buffer_lines.append(fmt_step_line(step))
        flush()
        return "\n".join(html)

    def _diagnostic_html_feature_cards(self, data):
        """Builds the HTML repository view's central "grouped by feature"
        measurement section -- makes sure every measurement is presented
        and grouped by feature, addressing the same redundancy the PDF/
        tree's own line cleanup addressed, where a bunch of rows said the
        exact same measurement in two different ways. One
        card per finger, containing that finger's own geometry, its own
        adhesion plate (if any), its own patches (if any, as a compact
        table -- linewidth, near/far margin, overlap with connector,
        electrode contact), every real JJ crossing this finger takes part
        in (real vs. nominal area, shrink), and every ghost-line anomaly
        located at this specific finger (matched via ghost_slivers'
        "finger_index", added this round for exactly this purpose) --
        plus one shared closing card for triangle deposition anomalies
        (these belong to a CROSSING, not one single finger, per
        _triangle_anomaly_slivers' own docstring, so they're listed
        once, clearly, rather than force-fit under an arbitrary finger)."""
        esc = self._html_esc
        cards = []
        crossings_by_finger = {}
        for cx in data.get("jj_crossings", []):
            crossings_by_finger.setdefault(cx["finger_i"], []).append(cx)
            crossings_by_finger.setdefault(cx["finger_j"], []).append(cx)
        ghosts_by_finger = {}
        for g in data.get("ghost_slivers", []):
            ghosts_by_finger.setdefault(g.get("finger_index"), []).append(g)
        patch_group_by_finger = {pg["finger_index"]: pg for pg in data.get("patch_groups", [])}

        for i, fd in enumerate(data.get("fingers", [])):
            rows = [f'<div class="kv"><span>Post-shadow length</span><b>{fd["length_um"]:.3f} µm</b></div>',
                    f'<div class="kv"><span>Linewidth</span><b>{fd["linewidth_nm"]:.1f} nm</b></div>']
            if fd["n_pieces"] > 1:
                rows.append(f'<div class="kv bad"><span>Post-shadow pieces (disconnected)</span>'
                            f'<b>{fd["n_pieces"]}</b></div>')
            if fd["electrode_um2"] is not None:
                rows.append(f'<div class="kv"><span>Contact area with electrode</span>'
                            f'<b>{fd["electrode_um2"]:.4f} µm²</b></div>')
            if fd.get("end_margin_um") is not None:
                rows.append(f'<div class="kv"><span>End margin (real tip past last patch)</span>'
                            f'<b>{fd["end_margin_um"]:+.3f} µm</b></div>')

            plate_html = ""
            pd = data.get("plates", {}).get(i)
            if pd is not None:
                plate_rows = [f'<div class="kv"><span>Dimensions</span>'
                              f'<b>{pd["length_um"]:.3f} × {pd["width_um"]:.3f} µm</b></div>']
                if pd["electrode_um2"] is not None:
                    plate_rows.append(f'<div class="kv"><span>Contact area with electrode</span>'
                                      f'<b>{pd["electrode_um2"]:.4f} µm²</b></div>')
                if pd.get("deposition_pass_count") is not None:
                    plate_rows.append(f'<div class="kv"><span>Deposition passes reaching this plate</span>'
                                      f'<b>{pd["deposition_pass_count"]}</b></div>')
                plate_html = (f'<details class="subcard" open><summary>Adhesion plate</summary>'
                              f'{"".join(plate_rows)}</details>')

            patches_html = ""
            pg = patch_group_by_finger.get(i)
            if pg is not None:
                patch_rows_html = []
                for pe in pg["patches"]:
                    bits = [f'W={pe["linewidth_nm"]:.1f} nm']
                    if pe["near_ext_um"] is not None:
                        bits.append(f'near margin {pe["near_ext_um"]:+.3f} µm')
                    if pe["far_ext_um"] is not None:
                        bits.append(f'far margin {pe["far_ext_um"]:+.3f} µm')
                    bits.append(f'overlap w/ connector {pe["overlap_um2"]:.4f} µm²')
                    if pe["electrode_um2"] is not None:
                        bits.append(f'electrode contact {pe["electrode_um2"]:.4f} µm²')
                    patch_rows_html.append(f'<div class="kv"><span>patch[{pe["k"]}]</span>'
                                           f'<b>{esc(", ".join(bits))}</b></div>')
                extra = []
                if pg["tip_margin_um"] is not None:
                    extra.append(f'<div class="kv"><span>Tip margin (finger tip past last patch)</span>'
                                 f'<b>{pg["tip_margin_um"]:.3f} µm</b></div>')
                extra.append(f'<div class="kv"><span>Total contact area (all patches)</span>'
                            f'<b>{pg["total_contact_um2"]:.4f} µm²</b></div>')
                patches_html = (f'<details class="subcard" open><summary>Patches (n={len(pg["patches"])})</summary>'
                                f'{"".join(patch_rows_html)}{"".join(extra)}</details>')

            crossings_html = ""
            my_crossings = crossings_by_finger.get(i, [])
            if my_crossings:
                cross_rows = []
                for cx in my_crossings:
                    partner = cx["label_j"] if cx["finger_i"] == i else cx["label_i"]
                    real_area, nominal_area = cx["area_um2"], cx["nominal_area_um2"]
                    detail = f'real {real_area:.5f} µm²'
                    if nominal_area is not None:
                        # "under" (any real numeric shortfall) vs.
                        # "is_area_reduced" (the authoritative,
                        # noise-tolerant answer stashed by
                        # _compute_postshadow_report) -- see the matching
                        # comment in _populate_postshadow_tree for why
                        # these are deliberately different.
                        under = nominal_area > 1e-9 and real_area < nominal_area - 1e-9
                        is_reduced = cx.get("is_area_reduced", False)
                        detail += f', nominal {nominal_area:.5f} µm²'
                        if under:
                            shrink_pct = (1.0 - real_area / nominal_area) * 100.0
                            if is_reduced:
                                detail += f', <span class="bad">{shrink_pct:.1f}% under nominal</span>'
                            else:
                                detail += f', {shrink_pct:.1f}% under nominal (within noise tolerance)'
                    cross_rows.append(f'<div class="kv"><span>Crossing with Finger {partner}</span>'
                                      f'<b>{detail}</b></div>')
                crossings_html = (f'<details class="subcard" open><summary>Junction crossings '
                                  f'(finger–finger overlap)</summary>{"".join(cross_rows)}</details>')

            anomalies_html = ""
            my_ghosts = ghosts_by_finger.get(i, [])
            if my_ghosts:
                ghost_rows = []
                for g in my_ghosts:
                    tag = ' <span class="bad">touches electrode -- shorts</span>' if g["touches_electrode"] else ""
                    ghost_rows.append(f'<div class="kv"><span>{esc(g["location"])}</span>'
                                      f'<b>{g["length_um"]:.3f} µm × {g["width_nm"]:.1f} nm{tag}</b></div>')
                anomalies_html = (f'<details class="subcard"><summary>Ghost-line anomalies '
                                  f'(n={len(my_ghosts)})</summary>{"".join(ghost_rows)}</details>')

            cards.append(
                f'<details class="feature-card" open><summary>Finger {esc(fd["name"])}</summary>'
                f'<div class="kv-grid">{"".join(rows)}</div>'
                f'{plate_html}{patches_html}{crossings_html}{anomalies_html}</details>')

        # Triangle deposition anomalies -- belong to a CROSSING (finger x
        # finger, or a patch/plate crossing a trench), not one single
        # finger, so shown once here rather than force-attached to an
        # arbitrary card above.
        if data.get("triangle_groups"):
            tri_rows = []
            for tg in data["triangle_groups"]:
                if tg["count"] == 1:
                    sides = (f'{tg["side1_min_nm"]:.1f} / {tg["side2_min_nm"]:.1f} / {tg["side3_min_nm"]:.1f} nm '
                             '(shortest / middle / longest)')
                else:
                    sides = (f'shortest {tg["side1_min_nm"]:.1f}-{tg["side1_max_nm"]:.1f} nm, middle '
                             f'{tg["side2_min_nm"]:.1f}-{tg["side2_max_nm"]:.1f} nm, longest '
                             f'{tg["side3_min_nm"]:.1f}-{tg["side3_max_nm"]:.1f} nm')
                area = (f'{tg["area_min_um2"]:.5f} µm²' if tg["count"] == 1 else
                        f'{tg["area_min_um2"]:.5f}-{tg["area_max_um2"]:.5f} µm²')
                tri_rows.append(
                    f'<div class="kv"><span>{esc(tg["location"])} ({tg["count"]}x)</span>'
                    f'<b>sides: {sides} &middot; area: {area}</b></div>')
            cards.append(
                '<details class="feature-card"><summary>Triangle deposition anomalies '
                '<span class="dim">(generally scalene -- not a right triangle, so no single "hypotenuse")</span>'
                f'</summary><div class="kv-grid">{"".join(tri_rows)}</div></details>')

        return "\n".join(cards) if cards else '<p class="skip">No per-feature measurements to show yet.</p>'

    def _on_export_final_diagnostic_html(self):
        """The HTML "repository" counterpart to _on_export_final_
        diagnostic (PDF) -- same gating, same underlying data
        (_diagnostic_progress_gates/_compute_postshadow_report/params/
        report), rendered as a single self-contained, offline-viewable
        HTML file instead of a printable PDF. See this section's own
        top-of-block docstring for the full rationale and the
        simulation-only data constraint."""
        junction, report, params, gates = self._diagnostic_progress_gates()
        if not gates["design"]:
            QMessageBox.information(self, "Nothing to export", "Create or import a design first.")
            return

        experiment_name = (getattr(params, "project_name", "") or "").strip() or "plassys_design"
        default_name = f"{experiment_name}_diagnostic_repository.html".replace(" ", "_")
        path, _ = QFileDialog.getSaveFileName(self, "Export Final Diagnostic Repository (HTML)",
                                               default_name, "HTML (*.html)")
        if not path:
            return

        esc = self._html_esc

        postshadow_data = None
        if gates["sim"] and hasattr(self, "sim_postshadow_tree"):
            self._update_sim_shadow_risk()
            postshadow_data = getattr(self, "_sim_postshadow_data", None)

        # ---- verdict banner ----
        if postshadow_data is None:
            verdict_class, verdict_label = "neutral", "— NOT YET SIMULATED"
            verdict_sub = ("Run the Angle Diagnostic and Run Simulation on the Simulate Design tab to "
                           "determine circuit continuity for this design.")
        else:
            verdict = postshadow_data["verdict"]
            n_open = len(postshadow_data.get("open_reasons", []))
            n_short = len(postshadow_data.get("short_reasons", []))
            n_area = len(postshadow_data.get("area_reasons", []))
            anomaly_count = postshadow_data.get("anomaly_count", 0)
            if verdict == "OK":
                verdict_class, verdict_label = "ok", "✓ FUNCTIONING"
                verdict_sub = ("No open, shorted, or under-area JJ crossings detected -- this design's "
                               "circuit appears fully continuous as configured.")
            elif verdict == "CAUTION":
                verdict_class, verdict_label = "warn", "⚠ CAUTION"
                verdict_sub = (f"No open/short/area failure, but {anomaly_count} ghost-line/triangle "
                               "deposition anomalies were found -- see the anomaly cards below.")
            else:
                verdict_class, verdict_label = "bad", f"✗ {verdict}"
                parts = []
                if n_open:
                    parts.append(f"{n_open} open reason(s)")
                if n_short:
                    parts.append(f"{n_short} short reason(s)")
                if n_area:
                    parts.append(f"{n_area} under-area crossing(s)")
                verdict_sub = (", ".join(parts) + " -- see the Per-Connection Survival Check below for full "
                               "detail.") if parts else "See the Per-Connection Survival Check below for full detail."

        # ---- KPI strip (same real inputs the PDF's KPI strip reads) ----
        try:
            electrode_height_nm = (float(self.es_height_edit.text())
                                    if hasattr(self, "es_height_edit") and self.es_height_edit.text().strip()
                                    else None)
        except ValueError:
            electrode_height_nm = None
        kpi_items = [
            ("Deposition metal", params.metal_type),
            ("Electrode metal", getattr(params, "electrode_metal_type", "Nb")),
            ("Deposition alpha", f"{params.alpha_deposition:.1f}°"),
            ("Mill alpha", f"{getattr(params, 'alpha_mill', 50.0):.1f}°"),
            (f"{params.top_resist_name} thickness",
             f"{params.pmma_thickness_nm:g} nm" if params.pmma_thickness_nm else "—"),
            (f"{params.bottom_resist_name} thickness",
             f"{params.pmgi_thickness_nm:g} nm" if params.pmgi_thickness_nm else "—"),
            ("Electrode height", f"{electrode_height_nm:g} nm" if electrode_height_nm is not None else "—"),
            ("Resist safety margin", f"{params.safety_margin_nm:g} nm"),
        ]
        if report is not None and getattr(report, "jj_crossing_area_um2", None) is not None:
            kpi_items.append(("JJ crossing area", f"{report.jj_crossing_area_um2:.4f} µm²"))
        if postshadow_data is not None:
            kpi_items.append(("Deposition anomalies", str(postshadow_data.get("anomaly_count", 0))))
            if postshadow_data.get("total_write_area_nominal_um2") is not None:
                kpi_items.append(("Total write area (nominal)",
                                  f"{postshadow_data['total_write_area_nominal_um2']:.4f} µm²"))
            if postshadow_data.get("total_postshadow_metal_area_um2") is not None:
                kpi_items.append(("Total metal area (real)",
                                  f"{postshadow_data['total_postshadow_metal_area_um2']:.4f} µm²"))
        kpi_html = "".join(
            f'<div class="kpi"><div class="value">{esc(v)}</div><div class="label">{esc(k)}</div></div>'
            for k, v in kpi_items)

        # ---- Section 1: Design Overview ----
        overview_rows = []
        if self._display_source == "parametric":
            try:
                jj_area = params.jj_area_um2()
            except Exception:
                jj_area = None
            if jj_area is not None:
                overview_rows.append(
                    f'<div class="kv"><span>JJ area (nominal)</span><b>{jj_area:.4f} µm² '
                    f'({params.horizontal_lw_nm:g} nm horiz × {params.vertical_lw_nm:g} nm vert)</b></div>')
        if report is not None:
            if getattr(report, "jj_crossing_area_um2", None) is not None:
                overview_rows.append(f'<div class="kv"><span>JJ crossing area</span>'
                                     f'<b>{report.jj_crossing_area_um2:.4f} µm²</b></div>')
            if getattr(report, "total_exposed_area_um2", None) is not None:
                overview_rows.append(f'<div class="kv"><span>Total exposed metal area</span>'
                                     f'<b>{report.total_exposed_area_um2:.4f} µm²</b></div>')
            if getattr(report, "finger_lengths_um", None):
                lens = ", ".join(f"{v:.3f}" for v in report.finger_lengths_um)
                widths = ", ".join(f"{v:.1f}" for v in getattr(report, "finger_widths_nm", []) or [])
                overview_rows.append(f'<div class="kv"><span>Finger lengths (µm)</span><b>{esc(lens)}</b></div>')
                if widths:
                    overview_rows.append(f'<div class="kv"><span>Finger widths (nm)</span><b>{esc(widths)}</b></div>')
        design_img_html = ""
        if hasattr(self, "create_import_fig"):
            design_img_html = (f'<img class="fig" alt="Design preview" '
                               f'src="{self._fig_to_data_uri(self.create_import_fig)}">')

        # ---- Section 2: Simulation & Shadowing ----
        sim_html_parts = []
        if not gates["sim"]:
            sim_html_parts.append('<p class="skip">Not yet reached for this design -- run the Angle '
                                   'Diagnostic and/or Run Simulation on the Simulate Design tab to include '
                                   'this section.</p>')
        else:
            run = self._sim_last_run or {}
            if self._sim_has_run:
                angle_bits = [f"alpha={run.get('alpha')}"]
                if run.get("theta_a") is not None:
                    angle_bits.append(f"finger A theta={run.get('theta_a')}")
                if run.get("theta_b") is not None:
                    angle_bits.append(f"finger B theta={run.get('theta_b')}")
                sim_html_parts.append(f'<p>Committed deposition angles: {esc(", ".join(angle_bits))}</p>')
            zero_dep = list(getattr(self, "_sim_zero_dep_warnings", []) or [])
            disconnections = list(getattr(self, "_sim_disconnection_warnings", []) or [])
            if zero_dep or disconnections:
                warn_lines = []
                if zero_dep:
                    names = ", ".join(zero_dep)
                    verb = "has" if len(zero_dep) == 1 else "have"
                    zero_dep_msg = f"{names} {verb} no active deposition layers and will not appear in the result."
                    warn_lines.append(f'<li>{esc(zero_dep_msg)}</li>')
                for wtxt in disconnections:
                    warn_lines.append(f'<li>{esc(wtxt)}</li>')
                sim_html_parts.append(f'<p class="warn">Shadowing diagnostics — issues found:</p>'
                                       f'<ul class="warn-list">{"".join(warn_lines)}</ul>')
            else:
                sim_html_parts.append('<p class="ok">Shadowing diagnostics: no warnings — every '
                                       'connection survives as configured.</p>')
            finger_explanations = getattr(report, "finger_explanations", None) if report is not None else None
            if finger_explanations:
                exp_lines = "".join(f"<li>{esc(t)}</li>" for t in finger_explanations)
                sim_html_parts.append(f'<details class="subcard"><summary>Per-finger contact detail</summary>'
                                       f'<ul>{exp_lines}</ul></details>')
            images_html = []
            if self._sim_angle_diagnostic_run:
                fig = Figure(figsize=(6, 6), dpi=100, facecolor=BG_COLOR)
                ax = fig.add_subplot(1, 1, 1)
                draw_imported_junction_preview(ax, junction, report, show_caption=False,
                                                warning1_enabled=True, warning2_enabled=True, show_badges=True)
                ax.set_facecolor(BG_COLOR)
                images_html.append(f'<figure><figcaption>Angle diagnostic view</figcaption>'
                                   f'<img class="fig" src="{self._fig_to_data_uri(fig)}"></figure>')
            if self._sim_has_run:
                fig2 = Figure(figsize=(6, 6), dpi=100, facecolor=BG_COLOR)
                ax2 = fig2.add_subplot(1, 1, 1)
                draw_imported_junction_preview(ax2, junction, report, show_caption=False,
                                                warning1_enabled=True, warning2_enabled=True, show_badges=True)
                self._draw_sim_shadow_visualization(ax2, junction, report)
                ax2.set_facecolor(BG_COLOR)
                images_html.append(f'<figure><figcaption>Simulated Design (shadow bands)</figcaption>'
                                   f'<img class="fig" src="{self._fig_to_data_uri(fig2)}"></figure>')
                fig3 = Figure(figsize=(6, 6), dpi=100, facecolor=BG_COLOR)
                ax3 = fig3.add_subplot(1, 1, 1)
                self._draw_post_shadow_design(ax3, junction, report)
                ax3.set_facecolor(BG_COLOR)
                images_html.append(f'<figure><figcaption>Post-deposition preview (Post-Shadow Result)</figcaption>'
                                   f'<img class="fig" src="{self._fig_to_data_uri(fig3)}"></figure>')
            if images_html:
                sim_html_parts.append(f'<div class="fig-grid">{"".join(images_html)}</div>')

            # Per-connection survival check + per-feature grouping --
            # every measurement here is presented and grouped by feature.
            if postshadow_data is not None:
                sim_html_parts.append('<h3>Per-connection survival check</h3>')
                sim_html_parts.append(self._diagnostic_html_feature_cards(postshadow_data))
        sim_html = "\n".join(sim_html_parts)

        # ---- Section 3: Recipe ----
        if not gates["recipe"]:
            recipe_html = ('<p class="skip">Not yet reached for this design -- build or adopt a recipe on '
                           'the Recipe tab to include this section.</p>')
        else:
            recipe_html = self._recipe_tree_html_story(self._recipe_tree_root, self._diagnostic_recipe_tree_path())

        # ---- Section 4: Measurements ----
        if not gates["measure"]:
            meas_html = ('<p class="skip">Not yet reached for this design -- record readings on the '
                        'Measure Resistance tab to include this section.</p>')
        else:
            exp_name = self.meas_experiment_name_edit.text().strip() or "(unnamed experiment)"
            unit = self.meas_unit_combo.currentText()
            pattern_label = self.meas_pattern_combo.currentText()
            rows_html = []
            cols = self.meas_table.columnCount()
            header_html = "".join(f"<th>Col {c + 1}</th>" for c in range(cols))
            for r in range(self.meas_table.rowCount()):
                cells = []
                for c in range(cols):
                    item = self.meas_table.item(r, c)
                    cells.append(f"<td>{esc(item.text()) if item and item.text().strip() else '-'}</td>")
                rows_html.append(f"<tr><td class=\"rownum\">{r + 1}</td>{''.join(cells)}</tr>")
            meas_html = (f'<p>Experiment: <b>{esc(exp_name)}</b> &middot; Pattern: {esc(pattern_label)} '
                        f'&middot; Units: {esc(unit)}</p>'
                        f'<table class="meas-table"><thead><tr><th></th>{header_html}</tr></thead>'
                        f'<tbody>{"".join(rows_html)}</tbody></table>')

        # ---- Section 5: Interpret Results ----
        if not gates["interp"]:
            interp_html = ('<p class="skip">Not yet reached for this design -- process a dataset on the '
                          'Interpret Results tab to include this section.</p>')
        else:
            dataset = self._interp_last_dataset
            result = self._interp_last_result
            interp_parts = []
            if dataset is not None:
                interp_parts.append(f'<p>Dataset: <b>{esc(getattr(dataset, "name", ""))}</b> &middot; '
                                    f'T_c: {getattr(dataset, "T_c_kelvin", float("nan")):g} K</p>')
            fit = (result or {}).get("fit")
            if fit:
                interp_parts.append(
                    f'<p>R_n vs 1/A fit: slope={fit["a1"]:.4g}, intercept={fit["a0"]:.4g}, '
                    f'R²={fit["r2"]:.4f} &middot; J_c = {fit["J_c_uA_um2"]:.4g} µA/µm²</p>')
            else:
                interp_parts.append('<p>No linear fit available (fewer than 2 valid rows).</p>')
            interp_images = []
            if hasattr(self, "interp_fig"):
                interp_images.append(f'<figure><figcaption>Main plot</figcaption>'
                                     f'<img class="fig" src="{self._fig_to_data_uri(self.interp_fig)}"></figure>')
            if self._interp_last_compare_results and hasattr(self, "interp_compare_fig"):
                interp_images.append(f'<figure><figcaption>Comparison plot</figcaption>'
                                     f'<img class="fig" src="{self._fig_to_data_uri(self.interp_compare_fig)}"></figure>')
            if interp_images:
                interp_parts.append(f'<div class="fig-grid">{"".join(interp_images)}</div>')
            interp_html = "\n".join(interp_parts)

        source_txt = "Created (parametric)" if self._display_source == "parametric" else "Imported"
        generated_txt = datetime.datetime.now().strftime("%Y-%m-%d %H:%M")
        page_title = f"Final Diagnostic Repository — {experiment_name}"

        html_doc = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{esc(page_title)}</title>
<style>
{self._diagnostic_html_css()}
</style>
</head>
<body>
<header class="hero">
  <h1>{esc(page_title)}</h1>
  <p class="meta">Design source: {esc(source_txt)} &middot; Generated: {esc(generated_txt)}</p>
  <div class="verdict-banner {verdict_class}">
    <div class="verdict-label">{esc(verdict_label)}</div>
    <div class="verdict-sub">{esc(verdict_sub)}</div>
  </div>
  <div class="kpi-grid">{kpi_html}</div>
</header>
<nav class="toc">
  <a href="#sec-design">Design Overview</a>
  <a href="#sec-sim">Simulation &amp; Shadowing</a>
  <a href="#sec-recipe">Plassys Recipe</a>
  <a href="#sec-meas">Measurements</a>
  <a href="#sec-interp">Interpret Results</a>
</nav>
<main>
  <section id="sec-design" class="panel">
    <h2>1. Design Overview</h2>
    <div class="kv-grid">{"".join(overview_rows)}</div>
    {design_img_html}
  </section>

  <section id="sec-sim" class="panel">
    <h2>2. Simulation &amp; Shadowing Diagnostics</h2>
    {sim_html}
  </section>

  <section id="sec-recipe" class="panel">
    <h2>3. Plassys Recipe</h2>
    {recipe_html}
  </section>

  <section id="sec-meas" class="panel">
    <h2>4. Room-Temperature Resistance Measurements</h2>
    {meas_html}
  </section>

  <section id="sec-interp" class="panel">
    <h2>5. Interpret Results</h2>
    {interp_html}
  </section>
</main>
<footer>
  <p>This page is generated entirely from this program's own simulation, recipe, and measurement data for the
  currently active design -- no content is pulled from any external repository or reference material.</p>
</footer>
</body>
</html>
"""
        try:
            with open(path, "w", encoding="utf-8") as fh:
                fh.write(html_doc)
        except Exception as e:
            QMessageBox.critical(self, "Export failed", f"Couldn't write the HTML file:\n{e}")
            return
        QMessageBox.information(self, "Exported", f"Final Diagnostic Repository (HTML) exported to:\n{path}")

    @staticmethod
    def _diagnostic_html_css():
        """The Final Diagnostic Repository page's stylesheet -- mimics the
        look and feel of a design-atlas style repository page (panel
        cards, KPI tiles, pill-style verdict badges) but in this app's
        own "quantum blue" palette, not a copy of any other page's colors
        or branding. Every color below is
        one of this file's own existing theme constants (BG_COLOR,
        PANEL_COLOR, TEXT_COLOR, ACCENT_COLOR, DIM_COLOR, BORDER_COLOR,
        HOVER_COLOR, plus the same OK/WARN/BAD semantic colors already
        used throughout the Simulate Design tab's own risk/verdict
        rendering), inlined here as literal hex so the exported file is
        fully self-contained (opens correctly offline, no dependency on
        this app or any network resource)."""
        return f"""
:root {{
  --bg: {BG_COLOR}; --panel: {PANEL_COLOR}; --ink: {TEXT_COLOR}; --dim: {DIM_COLOR};
  --accent: {ACCENT_COLOR}; --border: {BORDER_COLOR}; --hover: {HOVER_COLOR};
  --ok: #8fd694; --warn: #ffcc66; --bad: #ff5c5c;
}}
* {{ box-sizing: border-box; }}
body {{
  margin: 0; background: var(--bg); color: var(--ink);
  font-family: "Segoe UI", -apple-system, "Helvetica Neue", Arial, sans-serif;
  line-height: 1.5;
}}
.hero {{ padding: 28px 32px 20px; border-bottom: 1px solid var(--border); }}
.hero h1 {{ margin: 0 0 4px; font-size: 1.7rem; color: var(--accent); }}
.meta {{ color: var(--dim); font-size: 0.85rem; margin: 0 0 16px; }}
.dim {{ color: var(--dim); }}
.verdict-banner {{
  border-radius: 10px; padding: 14px 18px; margin-bottom: 18px; border: 1px solid var(--border);
  background: var(--panel);
}}
.verdict-banner.ok {{ border-color: var(--ok); background: rgba(143,214,148,0.10); }}
.verdict-banner.warn {{ border-color: var(--warn); background: rgba(255,204,102,0.10); }}
.verdict-banner.bad {{ border-color: var(--bad); background: rgba(255,92,92,0.10); }}
.verdict-banner.ok .verdict-label {{ color: var(--ok); }}
.verdict-banner.warn .verdict-label {{ color: var(--warn); }}
.verdict-banner.bad .verdict-label {{ color: var(--bad); }}
.verdict-banner.neutral .verdict-label {{ color: var(--dim); }}
.verdict-label {{ font-size: 1.3rem; font-weight: 700; margin-bottom: 4px; }}
.verdict-sub {{ font-size: 0.9rem; color: var(--ink); opacity: 0.9; }}
.kpi-grid {{ display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }}
.kpi {{ background: var(--panel); border: 1px solid var(--border); border-radius: 8px; padding: 10px 12px; }}
.kpi .value {{ font-size: 1.15rem; font-weight: 700; }}
.kpi .label {{ font-size: 0.7rem; color: var(--dim); margin-top: 2px; }}
.toc {{
  display: flex; gap: 4px; flex-wrap: wrap; padding: 10px 32px; background: var(--panel);
  border-bottom: 1px solid var(--border); position: sticky; top: 0; z-index: 10;
}}
.toc a {{
  color: var(--ink); text-decoration: none; padding: 6px 14px; border-radius: 999px;
  font-size: 0.85rem; border: 1px solid transparent;
}}
.toc a:hover {{ background: var(--hover); border-color: var(--border); }}
main {{ padding: 20px 32px 40px; max-width: 1100px; margin: 0 auto; }}
.panel {{ background: var(--panel); border: 1px solid var(--border); border-radius: 10px;
          padding: 18px 20px; margin-bottom: 20px; scroll-margin-top: 56px; }}
.panel h2 {{ margin-top: 0; color: var(--accent); font-size: 1.15rem; border-bottom: 1px solid var(--border);
             padding-bottom: 8px; }}
.panel h3 {{ color: var(--accent); font-size: 1rem; margin: 18px 0 8px; }}
.kv-grid {{ display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 6px 16px;
            margin: 8px 0; }}
.kv {{ display: flex; justify-content: space-between; gap: 10px; padding: 4px 0; border-bottom: 1px dashed var(--border);
       font-size: 0.88rem; }}
.kv span {{ color: var(--dim); }}
.kv b {{ text-align: right; font-weight: 600; }}
.kv.bad b {{ color: var(--bad); }}
.bad {{ color: var(--bad); }}
.ok {{ color: var(--ok); }}
.warn {{ color: var(--warn); }}
p.warn, p.ok, p.skip {{ font-size: 0.9rem; }}
p.skip {{ color: var(--dim); font-style: italic; }}
ul.warn-list {{ color: var(--bad); font-size: 0.88rem; }}
.feature-card {{
  border: 1px solid var(--border); border-left: 4px solid var(--accent); border-radius: 8px;
  padding: 10px 14px; margin: 10px 0; background: rgba(127,184,255,0.04);
}}
.feature-card > summary {{ cursor: pointer; font-weight: 700; font-size: 1rem; color: var(--ink); }}
.subcard {{
  border: 1px solid var(--border); border-radius: 6px; padding: 6px 12px; margin: 8px 0 0;
  background: var(--panel);
}}
.subcard > summary {{ cursor: pointer; font-weight: 600; color: var(--accent); font-size: 0.9rem; }}
details > summary {{ list-style: none; }}
details > summary::-webkit-details-marker {{ display: none; }}
details > summary::before {{ content: "\\25b8"; display: inline-block; margin-right: 6px; transition: transform 0.15s; color: var(--dim); }}
details[open] > summary::before {{ transform: rotate(90deg); }}
.fig-grid {{ display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 14px; margin: 12px 0; }}
figure {{ margin: 0; }}
figcaption {{ font-size: 0.8rem; color: var(--dim); margin-bottom: 4px; }}
img.fig {{ width: 100%; border-radius: 8px; border: 1px solid var(--border); display: block; }}
.recipe-call {{ border: 1px solid var(--border); border-radius: 6px; padding: 6px 12px; margin: 6px 0; background: var(--panel); }}
.recipe-call.depth-0 {{ border-left: 3px solid var(--accent); }}
.recipe-call.depth-1, .recipe-call.depth-2, .recipe-call.depth-3 {{ margin-left: 20px; border-left: 3px solid var(--dim); }}
.recipe-call > summary {{ font-weight: 600; color: var(--accent); }}
.recipe-comment {{ color: var(--dim); font-size: 0.85rem; margin-top: 2px; }}
pre.recipe-steps {{
  background: var(--bg); border: 1px solid var(--border); border-radius: 6px; padding: 8px 12px;
  font-family: "Consolas", "Courier New", monospace; font-size: 0.82rem; color: var(--ink);
  overflow-x: auto; margin: 6px 0 10px 20px;
}}
table.meas-table {{ border-collapse: collapse; width: 100%; margin-top: 10px; font-size: 0.88rem; }}
table.meas-table th, table.meas-table td {{ border: 1px solid var(--border); padding: 6px 10px; text-align: center; }}
table.meas-table th {{ background: var(--hover); color: var(--accent); }}
table.meas-table td.rownum {{ color: var(--dim); }}
footer {{ padding: 16px 32px 32px; color: var(--dim); font-size: 0.8rem; max-width: 1100px; margin: 0 auto; }}
@media (max-width: 700px) {{
  .kpi-grid {{ grid-template-columns: repeat(2, 1fr); }}
  .kv-grid {{ grid-template-columns: 1fr; }}
  main, .hero, .toc {{ padding-left: 16px; padding-right: 16px; }}
}}
"""

    # ========================================================================
    # Recipe (Recipe) -- auto-generates a recipe directly from the
    # unified warning classification and Simulate Design's last simulation run.
    # Every step traces back to exactly which finger/patch and which
    # warning put it there (the "Traced Recipe Timeline" design). Recipe
    # generation is deterministic/rule-based only (see recipe_generator.py's
    # generate_recipe_steps) -- there is no AI-generated or AI-reviewed
    # recipe option; the app-wide "Ask AI" assistant (_build_ask_ai_widget)
    # is explanatory only and never writes to the recipe.
    # ========================================================================

    _FEATURE_COLOR = {
        "finger": "#ffb454", "both": "#ff5c5c", "patches": "#ffb454",
        "none": "#8fd694", None: "#8ea3c2",
    }

    def _build_recipe_tab(self) -> QWidget:
        """Recipe -- now TWO independent recipe creators living
        in the same tab, switched by a mode toggle at the very top
        (kept together in the recipe creator tab rather than a separate
        nav-rail entry):

          - "Auto-Generated (from Design)" (page 0, UNCHANGED below):
            the existing deterministic engine (recipe_generator.py's
            generate_recipe_steps_from_simulation) that computes a JJ
            recipe automatically from Simulate Design's simulated
            geometry. Reads self._current_recipe_params() as its process-
            value source -- as of the Settings > Process Parameters
            removal round, that's built from the Recipe Parameters panel
            (metal/electrode metal/project name/oxidation time),
            Simulate Design's own Active alpha field (deposition tilt),
            and DesignParameters' own hardcoded defaults for everything
            else, rather than a Settings page.

          - "Recipe Builder (from scratch)" (page 1, NEW -- see
            _build_recipe_builder_view): a manual, from-scratch
            recipe author using the exact mechanics the real Plassys
            tool itself uses -- a TREE of named recipes (e.g.
            "Root\\Evap\\Ti"), each one a literal Step Type/Parameter
            1-4/Comment grid, where a step can itself call another
            named recipe as a nested sub-table (recipe_builder_model.py).
            Completely independent of any JJ design/simulation -- it's
            a generic recipe author for any process.

        How _current_recipe_params() relates to BOTH: it remains the
        single shared "current defaults" source app-wide. The
        Auto-Generated page is driven ENTIRELY by it (as before). The
        Recipe Builder never reads it automatically -- a raw, from-
        scratch recipe should not be silently coupled to values meant
        for a different, JJ-specific design -- but its "Insert Typical
        Step" helper (see _build_recipe_builder_view) offers the SAME
        current values as convenient, fully-editable starting points for
        common step types, so nothing has to be re-typed from memory."""
        outer = QWidget()
        outer_layout = QVBoxLayout(outer)
        outer_layout.setContentsMargins(0, 0, 0, 0)
        outer_layout.setSpacing(0)

        # --- mode toggle row ---
        toggle_bar = QWidget()
        toggle_layout = QHBoxLayout(toggle_bar)
        toggle_layout.setContentsMargins(16, 10, 16, 6)
        toggle_layout.setSpacing(8)
        mode_label = QLabel("RECIPE MODE")
        self._themed(mode_label, lambda: f"color: {DIM_COLOR}; font-size: 7.5pt; letter-spacing: 1px;")
        toggle_layout.addWidget(mode_label)

        # "Quantum blue" styling pass: the "Auto Generated" and "Recipe
        # Builder" buttons are styled to match the rest of the app --
        # same QuantumSegmentButton rail as Simulate Design's
        # VIEW group, joined into one continuous pill, each segment
        # keeping its own already-established accent (cyan for Auto-
        # Generated, gold for Recipe Builder). Same attribute names,
        # same real QButtonGroup exclusivity below -- only the widget
        # class and paint job are new.
        self.recipe_mode_auto_btn = QuantumSegmentButton("Auto-Generated (from Design)", "#7fc8e6", "left")
        self.recipe_mode_builder_btn = QuantumSegmentButton("Recipe Builder (from scratch)", "#ffd166", "right")
        self.recipe_mode_auto_btn.setChecked(True)
        mode_pill_group = QWidget()
        mode_pill_layout = QHBoxLayout(mode_pill_group)
        mode_pill_layout.setContentsMargins(0, 0, 0, 0)
        mode_pill_layout.setSpacing(0)
        mode_pill_layout.addWidget(self.recipe_mode_auto_btn)
        mode_pill_layout.addWidget(self.recipe_mode_builder_btn)
        toggle_layout.addWidget(mode_pill_group)
        toggle_layout.addStretch()
        self._recipe_mode_group = QButtonGroup(outer)
        self._recipe_mode_group.setExclusive(True)
        self._recipe_mode_group.addButton(self.recipe_mode_auto_btn)
        self._recipe_mode_group.addButton(self.recipe_mode_builder_btn)
        outer_layout.addWidget(toggle_bar)

        # Architecture change, verified against a real generated design:
        # the generated recipe now shows up under the "auto-generated"
        # button directly, instead of the old "Expanded recipe" text
        # view -- a Plassys-style, user-generated-looking recipe shows up
        # there instead, first showing the complete overall recipe, with
        # each sub-step clickable to open its own sub-step recipe.
        # Clicking Generate used to jump the WHOLE tab over to "Recipe
        # Builder (from scratch)" mode -- jarring, and made the generated
        # recipe feel like it lived somewhere else entirely. Now the
        # breadcrumb/table/warnings panel on the right is SHARED between
        # both modes (built once, below, via _build_recipe_table_panel/
        # _build_recipe_warnings_panel) and stays visible regardless of
        # which mode is active -- only the LEFT column switches between
        # "Recipe Parameters" (this generation's overrides + the Generate
        # button) and "Recipe Library" (the from-scratch tree browser/
        # CRUD toolbar). Generating a recipe simply opens the result in
        # that always-visible right panel; no page-switch needed at all.
        content_splitter = QSplitter(Qt.Horizontal)
        outer_layout.addWidget(content_splitter, stretch=1)

        self.recipe_mode_stack = QStackedWidget()

        # ================================================================
        # LEFT, page 0 -- Auto-Generated (from Design): Recipe Parameters
        # panel + Generate button. Everything BUT the old "Expanded
        # Recipe" text-blob panel, which is gone -- the generated result
        # now opens directly in the shared right panel (see above).
        # ================================================================
        left_scroll = QScrollArea()
        left_scroll.setWidgetResizable(True)
        left_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        left = QWidget()
        left_layout = QVBoxLayout(left)
        left_scroll.setWidget(left)

        header = QLabel("Recipe Parameters")
        self._themed(header, lambda: f"color: {TEXT_COLOR}; font-weight: bold; font-size: 11pt;")
        left_layout.addWidget(header)
        sub = QLabel("Type these in BEFORE generating -- the mill/deposition/oxidation sequence "
                     "(order, tilt, planetary angle) comes from Simulate Design's Deposition "
                     "Angles tree; anything left blank below falls back to Settings > Process "
                     "Parameters' current value.")
        sub.setWordWrap(True)
        self._themed(sub, lambda: f"color: {DIM_COLOR}; font-size: 8pt;")
        left_layout.addWidget(sub)

        left_layout.addWidget(self._build_recipe_parameters_panel())

        self.recipe_staleness_banner = QLabel("")
        self.recipe_staleness_banner.setWordWrap(True)
        self.recipe_staleness_banner.setVisible(False)
        left_layout.addWidget(self.recipe_staleness_banner)

        gen_row = QHBoxLayout()
        gen_btn = QPushButton("Generate Recipe")
        gen_btn.clicked.connect(self._on_generate_recipe_click)
        gen_row.addWidget(gen_btn)
        left_layout.addLayout(gen_row)

        self.recipe_generate_status_label = QLabel("")
        self.recipe_generate_status_label.setWordWrap(True)
        self._themed(self.recipe_generate_status_label, lambda: f"color: {DIM_COLOR}; font-size: 8pt;")
        left_layout.addWidget(self.recipe_generate_status_label)
        left_layout.addStretch(1)

        self.recipe_mode_stack.addWidget(left_scroll)

        # ================================================================
        # LEFT, page 1 -- Recipe Builder (from scratch): the Recipe
        # Library tree + its CRUD toolbar (New Folder/New Recipe/Rename/
        # Duplicate/Move/Delete). The table/breadcrumb/warnings panel a
        # click here opens is the SAME shared one page 0 uses -- see
        # above.
        # ================================================================
        self.recipe_mode_stack.addWidget(self._build_recipe_library_tree_panel())

        self.recipe_mode_auto_btn.clicked.connect(lambda: self.recipe_mode_stack.setCurrentIndex(0))
        self.recipe_mode_builder_btn.clicked.connect(lambda: self.recipe_mode_stack.setCurrentIndex(1))

        recipe_table_panel = self._build_recipe_table_panel()
        recipe_warnings_panel = self._build_recipe_warnings_panel()
        content_splitter.addWidget(self.recipe_mode_stack)
        content_splitter.addWidget(recipe_table_panel)
        content_splitter.addWidget(recipe_warnings_panel)
        content_splitter.setStretchFactor(0, 1)
        content_splitter.setStretchFactor(1, 2)
        content_splitter.setStretchFactor(2, 0)
        # Fixes a splitter resize bug where clicking on the table could
        # resize it unpredictably, sometimes growing it so large that the
        # other tabs were completely out of view, with no way to recover
        # via View > Reset View. Two real causes:
        # (1) double-clicking a QHeaderView section border (easy to do
        # by accident while trying to drag-resize a column) auto-sizes
        # that column to fit its widest cell content -- with this app's
        # own deliberately verbose recipe names, that can
        # make recipe_builder_table's natural width balloon far past what
        # the splitter pane needs; (2) the splitter had no protection
        # against that: no minimum width on any of its 3 panes, and
        # setChildrenCollapsible defaulting to True meant a drag (or the
        # width-balloon in (1) squeezing its neighbors) could push the
        # Recipe Parameters/Library pane or the Warnings pane all the way
        # to zero width -- completely out of view -- with no built-in
        # way back short of restarting. Fixed with: a real minimum width
        # on every pane (never fully squeezable to zero, so a pane can
        # always be found and dragged back), setChildrenCollapsible(False)
        # (dragging a handle past a pane's minimum stops there instead of
        # collapsing it), and self.recipe_content_splitter stored so
        # _reset_recipe_tab_layout (called from View > Reset View, which
        # previously did nothing for this tab at all) can restore sane
        # default proportions and column widths on demand.
        self.recipe_content_splitter = content_splitter
        content_splitter.setChildrenCollapsible(False)
        self.recipe_mode_stack.setMinimumWidth(260)
        recipe_table_panel.setMinimumWidth(320)
        recipe_warnings_panel.setMinimumWidth(180)

        self._recipe_builder_refresh_tree_widget()
        self._recipe_builder_refresh_warnings()
        self._recipe_builder_refresh_design_link_banner()
        return outer

    def _reset_recipe_tab_layout(self):
        """View > Reset View's Recipe-tab counterpart to the canvas reset
        it already does for Create / Import -- restores the Recipe tab's
        3-pane splitter to sane default proportions and puts
        recipe_builder_table's columns back to their own default widths,
        undoing any accidental drag/double-click-to-fit-content resize
        that grew a pane or column far past what's useful (see the
        bug-fix note above content_splitter's construction).
        A no-op if the Recipe tab has never been built yet."""
        if not hasattr(self, "recipe_content_splitter"):
            return
        total = sum(self.recipe_content_splitter.sizes()) or 1200
        # Same 1:2:0(-ish, but never zero thanks to the minimums above)
        # ratio as the splitter's own initial stretch factors.
        self.recipe_content_splitter.setSizes(
            [int(total * 0.23), int(total * 0.57), int(total * 0.20)])
        if hasattr(self, "recipe_builder_table"):
            is_cp = rte.is_complete_process_path(getattr(self, "_recipe_builder_current_path", "") or "")
            self._recipe_builder_configure_table_columns(is_cp)

    # ------------------------------------------------------------------
    # Recipe Parameters panel (auto-generated page, above "Generate
    # Recipe"). This is where a user adjusts the specific recipe
    # parameters, like the type of metal the junction is made of, ion
    # milling times, and the target thickness for each deposition
    # (rather than that living in the simulation tab) -- the parameters
    # subtab sits above the button that generates the recipe, so a user
    # naturally fills these in before generating it.
    #
    # Settings > Process Parameters removed: rather than having numbers
    # hard-coded in from a separate Settings section, these numbers are
    # soft-coded as suggestions, used only if a value isn't typed in, and
    # easily overridden by typing a different value. This panel is now
    # the one live home for metal/electrode metal/project name/oxidation
    # time -- there is no more Settings fallback to hint at. A blank
    # field falls back straight to DesignParameters' own dataclass
    # default (e.g. 25 min oxidation, 1 min ion mill duration) rather
    # than to a second widget elsewhere. Per-pass deposition thickness
    # and mill duration keep their existing dynamic fields below
    # (_rebuild_recipe_panel_dynamic_fields), each seeded with the real
    # auto-computed/default current value as its placeholder. Everything
    # else that used to live in Settings > Process Parameters (deposition
    # rate, Ti-gather rate/duration, ion mill beam gas/voltage/current/
    # accel) is now a pure hardcoded DesignParameters default: for the
    # actual process parameters in the recipes, there are already
    # automatic inputs that go into many of those steps that don't really
    # require logic and are simply values the machine is configured to --
    # a user hand-edits the generated recipe's own step cells afterward
    # if a real run needs something different, and that hand-edit is what
    # persists (see generated_recipe_export.py's duplicate-and-patch
    # regeneration), not a Settings-level default.
    # ------------------------------------------------------------------

    def _build_recipe_parameters_panel(self) -> QWidget:
        card, content = self._sim_card("Recipe Parameters (this generation only)", "#ffd166", collapsed=False)

        def _row(label_text, widget):
            row = QHBoxLayout()
            lbl = QLabel(label_text)
            lbl.setMinimumWidth(120)
            self._themed(lbl, lambda: f"color: {DIM_COLOR}; font-size: 8pt;")
            row.addWidget(lbl)
            row.addWidget(widget, stretch=1)
            content.addLayout(row)

        # A "Project Name" field also belongs under the recipe tab so it
        # is easier to fill out -- project_name already existed
        # (Settings' own "Project name (recipe path label, optional)"
        # field), this just gives it a second, easier-to-reach entry
        # point right here, following the exact same "blank -> falls back
        # to Settings" pattern as every other field in this panel.
        self.recipe_panel_project_name_edit = QLineEdit()
        _row("Project Name:", self.recipe_panel_project_name_edit)

        # With the Settings > Process Parameters section removed: metal
        # type and electrode metal used to live in
        # Settings, with this combo only overriding it "for this
        # generation only" if non-blank. Settings is gone now, so this
        # combo (and the new electrode-metal combo beside it) IS the
        # live value -- no more "(use Settings)" sentinel, just a real
        # current choice, same as any other design field. Read directly
        # by _current_params() (see task tracking in shadowing_design_
        # rules.md), not just at Generate-Recipe time, so it also feeds
        # Interpret Results' T_c default (_refresh_interp_tc_default)
        # and the mill-duration-by-metal suggestion note below.
        self.recipe_panel_metal_combo = QComboBox()
        for m in METAL_OPTIONS:
            self.recipe_panel_metal_combo.addItem(m, m)
        idx = self.recipe_panel_metal_combo.findText("Al")
        self.recipe_panel_metal_combo.setCurrentIndex(idx if idx >= 0 else 0)
        _row("Metal:", self.recipe_panel_metal_combo)
        self.recipe_panel_metal_combo.currentTextChanged.connect(
            lambda _t: self._refresh_interp_tc_default() if hasattr(self, "_refresh_interp_tc_default") else None)

        # "the metal being deposited and what metal the electrode is" are
        # two SEPARATE choices -- the electrode metal specifically drives
        # the ion-mill duration guidance note just below, since the
        # mill's whole purpose is cleaning native oxide off the EXISTING
        # electrode surface before contact.
        self.recipe_panel_electrode_metal_combo = QComboBox()
        for m in METAL_OPTIONS:
            self.recipe_panel_electrode_metal_combo.addItem(m, m)
        idx = self.recipe_panel_electrode_metal_combo.findText("Nb")
        self.recipe_panel_electrode_metal_combo.setCurrentIndex(idx if idx >= 0 else 0)
        _row("Electrode metal:", self.recipe_panel_electrode_metal_combo)

        self.recipe_panel_mill_metal_note = QLabel("")
        self.recipe_panel_mill_metal_note.setWordWrap(True)
        self._themed(self.recipe_panel_mill_metal_note, lambda: f"color: {DIM_COLOR}; font-size: 7.5pt; font-style: italic;")
        content.addWidget(self.recipe_panel_mill_metal_note)

        def _refresh_recipe_panel_mill_metal_note(*_args):
            electrode_metal = self.recipe_panel_electrode_metal_combo.currentText()
            duration = MILL_DURATION_MIN_BY_METAL.get(electrode_metal)
            if duration is None:
                self.recipe_panel_mill_metal_note.setText("")
            elif duration <= 0.3:
                self.recipe_panel_mill_metal_note.setText(
                    f"{electrode_metal} barely oxidizes -- a short mill, or none, is often enough (suggestion only).")
            else:
                self.recipe_panel_mill_metal_note.setText(
                    f"{electrode_metal} oxidizes readily -- around {duration:g} min is a reasonable starting "
                    f"point for a clean contact (suggestion only).")
        self.recipe_panel_electrode_metal_combo.currentTextChanged.connect(_refresh_recipe_panel_mill_metal_note)
        _refresh_recipe_panel_mill_metal_note()

        # An "Oxidation Time" option under "Recipe Parameters" on the
        # recipe tab, so it can be set depending on what's desired,
        # defaulting to 25 minutes if no value is entered. Blank falls
        # back to DesignParameters.oxidation_time_min's own dataclass
        # default (25.0) via _current_recipe_panel_params.
        self.recipe_panel_oxidation_time_edit = QLineEdit()
        self.recipe_panel_oxidation_time_edit.setPlaceholderText(f"{DesignParameters().oxidation_time_min:g} (default)")
        _row("Oxidation time (min):", self.recipe_panel_oxidation_time_edit)

        # Mill angle as a user-alterable option under recipe parameters
        # in the recipe tab, defaulting to 50 degrees. Blank falls back
        # to DesignParameters.alpha_mill's own dataclass default (50.0) via
        # _alpha_mill_or_default -- same pattern as Oxidation time above,
        # and deliberately independent of Simulate Design's own Active
        # alpha (deposition tilt), since the ion-mill sidewall angle is
        # its own fixed convention, not tied to any one deposition pass.
        self.recipe_panel_mill_angle_edit = QLineEdit()
        self.recipe_panel_mill_angle_edit.setPlaceholderText(f"{DesignParameters().alpha_mill:g} (default)")
        _row("Mill angle (deg):", self.recipe_panel_mill_angle_edit)

        # The Recipe Parameters panel's thickness/mill-duration field
        # count is dynamic, matching the actual number of passes the
        # design needs. The four fixed fields this panel used to have
        # (1st/2nd/2nd-Warning#2 dep. thickness, patch thickness) baked
        # in a hardcoded "exactly 2 fingers + optional patches" shape --
        # a design with 3+ deposition passes, or 2+ mill passes each
        # needing a different duration, had no way to address every pass
        # individually, and the classifier that guessed which of the 4
        # buckets each real feature belonged to
        # (_recipe_features_with_panel_thickness, now removed) was
        # itself a fragile heuristic that could misclassify anything
        # outside that assumed shape. Replaced with a container rebuilt
        # from self._recipe_features itself (see
        # _rebuild_recipe_panel_dynamic_fields): exactly one thickness
        # field per predicted deposition pass and one duration field per
        # predicted mill pass, each labeled with that pass's own real
        # description, so the field count always matches what the
        # CURRENT design actually needs.
        self.recipe_panel_dynamic_container = QWidget()
        self.recipe_panel_dynamic_layout = QVBoxLayout(self.recipe_panel_dynamic_container)
        self.recipe_panel_dynamic_layout.setContentsMargins(0, 4, 0, 0)
        self.recipe_panel_dynamic_layout.setSpacing(3)
        content.addWidget(self.recipe_panel_dynamic_container)
        self.recipe_panel_thickness_edits = {}      # (kind, label) -> QLineEdit, deposition passes only
        self.recipe_panel_mill_duration_edits = {}  # base label (pass-suffix stripped) -> QLineEdit
        self._rebuild_recipe_panel_dynamic_fields()

        self.recipe_panel_project_name_edit.textChanged.connect(
            lambda _t: self._refresh_recipe_staleness_banner()
            if hasattr(self, "_refresh_recipe_staleness_banner") else None)
        self.recipe_panel_oxidation_time_edit.textChanged.connect(
            lambda _t: self._refresh_recipe_staleness_banner()
            if hasattr(self, "_refresh_recipe_staleness_banner") else None)

        wrapper = QWidget()
        wrapper_layout = QVBoxLayout(wrapper)
        wrapper_layout.setContentsMargins(0, 0, 0, 0)
        wrapper_layout.addWidget(card)
        return wrapper

    def _rebuild_recipe_panel_dynamic_fields(self):
        """Rebuilds the Recipe Parameters panel's per-pass thickness/mill-
        duration fields from self._recipe_features -- called once at
        panel-build time and again every time _rebuild_recipe_from_
        features runs (i.e. whenever the predicted sequence itself
        changes: a reorder, an insert/delete, or a fresh regeneration),
        so the field count tracks the CURRENT design exactly. Any text
        the user already typed is preserved across a rebuild as long as
        the same pass identity (kind+label for a deposition pass, or the
        pass-suffix-stripped base label for a mill pass) still exists --
        rebuilding must never silently discard an in-progress override."""
        if not hasattr(self, "recipe_panel_dynamic_layout"):
            return
        layout = self.recipe_panel_dynamic_layout
        prior_thickness_text = {k: e.text() for k, e in self.recipe_panel_thickness_edits.items()}
        prior_mill_text = {k: e.text() for k, e in self.recipe_panel_mill_duration_edits.items()}
        # Fixes a crash after repeated Run Simulation/Run
        # Angle Diagnostic clicks, especially after loading several
        # different designs in a row: this function runs on every
        # single predicted-sequence change (see this method's own
        # docstring), and its rows are each a bare `row = QHBoxLayout()`
        # added via `layout.addLayout(row)` (see _dyn_row above) rather
        # than wrapped in their own container widget -- so the OLD
        # cleanup here (`item.widget()` on each top-level layout item)
        # always got None back for every one of these rows and never
        # actually deleteLater()'d their QLabel/QLineEdit at all: they
        # stayed alive, still parented to this panel, forever. Combined
        # with self._themed(lbl, ...) separately remembering each label
        # forever too (see _prune_themed_widgets's own docstring), this
        # was a genuine, unbounded, ever-growing widget leak -- found by
        # gc.get_objects()+shiboken6.isValid() histogramming, which
        # showed exactly this function's rows (by their own label text)
        # surviving as real, live (not merely dead-shell) widgets after
        # every single rebuild. Now recursively collects every widget
        # actually inside `layout` (including these nested rows) via
        # _collect_layout_widgets, prunes them out of
        # self._themed_widgets, and deleteLater()s each one directly.
        old_widgets = self._collect_layout_widgets(layout)
        self._prune_themed_widgets(old_widgets)
        for ow in old_widgets:
            ow.deleteLater()
        while layout.count():
            layout.takeAt(0)
        self.recipe_panel_thickness_edits = {}
        self.recipe_panel_mill_duration_edits = {}

        def _dyn_row(label_text, edit, placeholder, tooltip=None):
            row = QHBoxLayout()
            lbl = QLabel(label_text)
            lbl.setWordWrap(True)
            self._themed(lbl, lambda: f"color: {DIM_COLOR}; font-size: 7.5pt;")
            row.addWidget(lbl, stretch=1)
            edit.setMaximumWidth(70)
            edit.setPlaceholderText(placeholder)
            if tooltip:
                edit.setToolTip(tooltip)
            row.addWidget(edit)
            layout.addLayout(row)

        features = getattr(self, "_recipe_features", None) or []
        if not features:
            hint = QLabel("No predicted deposition/mill passes yet -- run the Angle Diagnostic first; "
                          "per-pass thickness/duration overrides will appear here once a sequence exists.")
            hint.setWordWrap(True)
            self._themed(hint, lambda: f"color: {DIM_COLOR}; font-size: 7.5pt; font-style: italic;")
            layout.addWidget(hint)
            return

        settings_mill_default = self._current_recipe_params().mill_duration_min
        seen_mill_bases = set()
        for feat in features:
            if feat.kind == "deposition":
                key = (feat.kind, feat.label)
                edit = QLineEdit(prior_thickness_text.get(key, ""))
                current = feat.thickness_nm if feat.thickness_nm is not None else 0.0
                _dyn_row(f"{feat.label} thickness (nm):", edit, f"{current:g} (current)")
                self.recipe_panel_thickness_edits[key] = edit
            elif feat.kind == "mill":
                base = rte.strip_pass_suffix(feat.label)
                if base in seen_mill_bases:
                    continue
                seen_mill_bases.add(base)
                edit = QLineEdit(prior_mill_text.get(base, ""))
                current = feat.mill_duration_min if feat.mill_duration_min is not None else settings_mill_default
                # Fixes a bug where a typed "1:30"
                # here used to be silently discarded (see _minutes_opt's
                # own docstring) since only a plain decimal number of
                # minutes ever parsed -- now that both forms are
                # accepted, the placeholder/tooltip say so explicitly so
                # it's clear "1:30" means 1 minute 30 seconds here, the
                # same way it reads in the generated recipe's own Wait
                # step and the Complete Process table's Time column.
                _dyn_row(f"{base} duration (min):", edit,
                         f"{current:g} = {_fmt_mmss(current * 60.0)} (current)",
                         tooltip="Accepts plain minutes (e.g. 1.5) or M:SS (e.g. 1:30 = 1.5 min).")
                self.recipe_panel_mill_duration_edits[base] = edit

    def _current_recipe_panel_params(self) -> DesignParameters:
        """Historically: self._current_recipe_params() overlaid with only
        the non-blank "this generation only" Recipe Parameters panel
        fields. As of the Settings > Process Parameters removal round,
        project name/metal/electrode metal/oxidation time are ALL read
        directly by _current_params() itself (see
        _oxidation_time_min_or_default for why oxidation time moved there
        too -- it needs to be captured by a saved DesignParameters
        snapshot, not just applied "for this generation only"), so there
        is nothing left to overlay here. Kept as a thin alias (rather
        than deleted outright) so every existing call site -- and the
        Recipe tab's own "reads _current_recipe_panel_params()" framing
        -- keeps working unchanged. Per-pass thickness/mill-duration
        overrides (item #108) are, as before, applied directly onto the
        matching feature by _recipe_features_with_panel_overrides
        instead, since a single global value can no longer represent
        "one field per pass"."""
        return self._current_recipe_params()

    # ------------------------------------------------------------------
    # Generate Recipe -- materializes self._recipe_features (predicted
    # live in Simulate Design's "Predicted Recipe Sequence" card) into
    # the REAL Plassys recipe-tree format (generated_recipe_export.py),
    # auto-saved into the shared Recipe Library with content-based dedup
    # and duplicate-and-patch regeneration (see generated_recipe_export.py's
    # module docstring for the full design). The
    # result opens in the same tree/table widgets "Recipe Builder (from
    # scratch)" mode already uses -- the format of the generated recipe
    # matches the format of the Plassys/by-hand recipe, so it's
    # directly, row-by-row editable exactly like a hand-built recipe,
    # not a second, separate renderer.
    # ------------------------------------------------------------------

    def _on_generate_recipe_click(self):
        # Still runs the existing deterministic engine first -- this is
        # what keeps self._recipe_last_steps/_recipe_last_warnings/
        # _recipe_last_params current for every OTHER consumer that
        # already depends on them (Final Diagnostic Report PDF, the
        # front-page dashboard's "recipe" status pill, the app-wide Ask
        # AI assistant's context, File > Save Recipe...) -- none of that
        # changes; this click ADDS the real-tree materialization on top.
        if not self._generate_recipe_from_sim(show_errors=True):
            return
        p = self._current_recipe_panel_params()
        if not self._recipe_features:
            QMessageBox.information(self, "Nothing to generate",
                                     "No mill/deposition/oxidation sequence is predicted yet -- "
                                     "check Simulate Design's \"Predicted Recipe Sequence\" card.")
            return
        design_name = (self.design_name_edit.text().strip()
                        if hasattr(self, "design_name_edit") and self.design_name_edit.text().strip()
                        else self._current_design_display_name())
        # Fixes a bug (found via testing against a real design) where the
        # Recipe Parameters panel's per-deposition thickness overrides
        # were never applied onto the actual features handed to the
        # generator: build_generated_subrecipes only ever reads
        # feat.thickness_nm (baked in back on Simulate Design's own
        # tree), so leaving `p`'s overridden al_thickness_1_nm/
        # al_thickness_2_nm/al_thickness_2_warn2_nm/patch_thickness_nm
        # unapplied to the features meant a typed override in this panel
        # silently did nothing -- the generated recipe kept whatever
        # thickness Simulate Design already had, even though the panel
        # showed the typed value as if it were in effect. A copy of the
        # feature list is overridden here (never the live
        # self._recipe_features -- that stays exactly what Simulate
        # Design's own tree says) so this panel is what actually decides
        # thickness for this generation, moving that decision here rather
        # than keeping it tied to the simulation tab.
        features_for_generation = self._recipe_features_with_panel_overrides()
        subs, gen_warnings = rte.build_generated_subrecipes(
            p, features_for_generation, project_name=p.project_name, design_name=design_name)
        self._recipe_builder_ensure_tree_loaded()
        created, reused, patched = 0, 0, 0
        complete_process_path = None
        # Fixes a critical bug (found via testing against a real design --
        # the app's own Recipe Warnings panel correctly flagged it: a step
        # calling a recipe that doesn't resolve to a real recipe):
        # rte.build_generated_subrecipes bakes each leaf's
        # PROPOSED tree_path directly into the complete_process recipe's
        # own "Recipe"-type call rows AT BUILD TIME, before any of those
        # leaves have actually been resolved/written. resolve_and_write
        # (called per sub, below) can send a leaf to a DIFFERENT real
        # path than what was proposed -- reusing the old linked node
        # as-is (nothing changed), deduping onto some unrelated existing
        # node elsewhere in the tree, or renaming to dodge a collision --
        # so complete_process's own steps, frozen with the ORIGINAL
        # proposed paths, could end up calling a path that was never
        # created at all. path_remap tracks proposed-path -> actual
        # final-path for every leaf as it's resolved, and is applied to
        # every later sub's own "Recipe" call rows (in dependency order,
        # so complete_process -- always last -- sees every leaf's real
        # final path) before that sub is itself resolved/written.
        path_remap: Dict[str, str] = {}
        for sub in subs:
            for row in sub.steps:
                if row.step_type == rtm.RECIPE_STEP_TYPE and row.param1 in path_remap:
                    row.param1 = path_remap[row.param1]
            prior_path = self._current_design_recipe_links.get(sub.kind_key)
            prior_baseline = self._current_design_recipe_baselines.get(sub.kind_key)
            final_path, new_baseline = rte.resolve_and_write(
                self._recipe_tree_root, sub,
                prior_link_path=prior_path, prior_baseline_steps=prior_baseline)
            if final_path != sub.tree_path:
                path_remap[sub.tree_path] = final_path
            if final_path == prior_path:
                reused += 1
            elif prior_path is not None:
                patched += 1
            else:
                created += 1
            self._current_design_recipe_links[sub.kind_key] = final_path
            self._current_design_recipe_baselines[sub.kind_key] = new_baseline
            if sub.kind_key == "complete_process":
                complete_process_path = final_path
        try:
            rtm.save_tree(self._recipe_tree_root)
        except Exception:
            pass
        status_bits = []
        if created:
            status_bits.append(f"{created} new")
        if patched:
            status_bits.append(f"{patched} duplicated+patched (old ones kept, untouched)")
        if reused:
            status_bits.append(f"{reused} reused as-is")
        status = f"Generated: {', '.join(status_bits) if status_bits else 'nothing changed'}."
        if gen_warnings:
            status += " " + " ".join(gen_warnings)
        if hasattr(self, "recipe_generate_status_label"):
            self.recipe_generate_status_label.setText(status)
        # Show the result in the shared breadcrumb/table panel -- the
        # generated recipe should show up under
        # the "Auto-Generated (from Design)" button itself, not require
        # switching over to "Recipe Builder" mode. Since that panel is
        # now shared between both modes (see _build_recipe_tab), simply
        # opening the path here is enough -- no page-switch at all, so
        # whichever left-hand mode the user was already on stays exactly
        # where it was.
        if complete_process_path:
            self._recipe_builder_refresh_tree_widget()
            self._recipe_builder_history = []
            if hasattr(self, "recipe_builder_back_btn"):
                self.recipe_builder_back_btn.setEnabled(False)
            self._recipe_builder_open_path(complete_process_path, push_history=False)

    def _current_design_display_name(self) -> str:
        """Human-readable identifier for the currently-simulated design,
        used as the fallback for generated-recipe naming/paths.

        Fixes a bug (found via testing against a real design) where the
        old fallback was `self._active_design_id`, an opaque UUID
        design_library.py assigns internally (e.g.
        "fdd59ab026ad488eab31b140a4b73765") -- since self.design_name_edit
        does not exist anywhere in this app, that UUID fallback was
        always what got used, defeating the intended verbose/legible
        naming. junction.source_label is already the human-readable
        identifier shown in Simulate Design's own "Simulating: ..."
        status line (e.g. "my_design_ManhattanJJ_resistance_test5.gds ::
        my_design_C9R9_520nm"), so it is used here instead. Sanitized for
        recipe_builder_model.PATH_SEP (a backslash) since this string
        becomes part of a tree path.
        """
        junction = getattr(self, "_sim_cached_junction", None) or getattr(self, "_imported_junction", None)
        label = (getattr(junction, "source_label", "") or "").strip() if junction is not None else ""
        if not label:
            return "design"
        # The naming convention for each of the tables previously read as
        # wrong and misleading -- the ending angle should be the angle
        # that is consistently changing, i.e. the planetary angle.
        # generated_recipe_export.generated_name already puts
        # the planetary angle (theta) last -- but the full source_label
        # (a GDS filename plus the imported cell/measurement label, e.g.
        # "my_design_ManhattanJJ_resistance_test5.gds ::
        # my_design_C0R8_440nm") sits in the middle of every generated
        # name and is so long it pushes that ending planetary angle past
        # where the Recipe tab's own table/breadcrumb visibly truncates
        # -- so in practice the wrong thing (the tilt, or nothing at
        # all) is what's actually visible. The part after "::" is
        # already the more specific, compact identifier (the actual
        # cell/measurement, not the whole file it came from); repeating
        # the entire filename in every sub-recipe name is unnecessary
        # now that the Recipe tab has its own dedicated Project Name
        # field for top-level identification.
        if "::" in label:
            label = label.split("::")[-1].strip()
        sep = getattr(rtm, "PATH_SEP", "\\")
        for bad_char in (sep, "\\", "/"):
            label = label.replace(bad_char, "-")
        return label

    def _recipe_features_with_panel_overrides(self) -> list:
        """Returns self._recipe_features with each pass's thickness (for
        deposition) or duration (for mill) overridden per the Recipe
        Parameters panel's DYNAMIC fields, WITHOUT mutating the live
        list Simulate Design owns -- the copy is what actually goes to
        rte.build_generated_subrecipes for this one generation.

        Replaces this method's earlier fixed-4-field version
        (_recipe_features_with_panel_thickness, a heuristic classifier
        that guessed "1st pass / patch pass / 2nd pass / Warning-2 risky
        2nd pass" from the live junction geometry and could misclassify
        anything outside that exact 2-finger shape): every dynamic field
        is keyed by the SAME (kind, label) / pass-suffix-stripped-label
        identity already used throughout this pipeline (manual
        overrides, dedup, naming), so this is now an exact match, not a
        guess -- a design with any number of deposition/mill passes gets
        exactly the right field applied to exactly the right pass.
        A blank field (or a field with no matching feature to apply to,
        e.g. after the sequence changed since the panel was last
        rebuilt) leaves that feature's own value untouched -- Simulate
        Design's own per-pass thickness, or Settings' mill_duration_min
        fallback for a mill pass with no override, exactly matching this
        panel's "leave blank to keep it as-is" framing."""
        feats = list(self._recipe_features or [])
        if not feats:
            return feats
        thickness_edits = getattr(self, "recipe_panel_thickness_edits", {}) or {}
        mill_edits = getattr(self, "recipe_panel_mill_duration_edits", {}) or {}
        out = []
        for feat in feats:
            if feat.kind == "deposition":
                edit = thickness_edits.get((feat.kind, feat.label))
                new_thickness = self._f_opt(edit) if edit is not None else None
                out.append(dataclasses.replace(feat, thickness_nm=new_thickness)
                           if new_thickness is not None else feat)
            elif feat.kind == "mill":
                edit = mill_edits.get(rte.strip_pass_suffix(feat.label))
                # Fixes a bug: was self._f_opt
                # (plain float() only) -- see _minutes_opt's own
                # docstring for why a typed "1:30" was being silently
                # discarded instead of applied as 1.5 minutes.
                new_duration = self._minutes_opt(edit) if edit is not None else None
                out.append(dataclasses.replace(feat, mill_duration_min=new_duration)
                           if new_duration is not None else feat)
            else:
                out.append(feat)
        return out

    # ------------------------------------------------------------------
    # Recipe, page 1 -- Recipe Builder (from scratch). A manual,
    # from-scratch Plassys recipe author using the real tool's own
    # tree-of-named-recipes / Step Type-Parameter 1-4-Comment grid
    # mechanics (recipe_builder_model.py), completely independent of any
    # JJ design or simulation -- a from-scratch Plassys recipe creator
    # using the exact same mechanics the Plassys tool itself uses to
    # create a recipe: essentially, nested tables. A step of type
    # "Recipe" calls another named
    # recipe elsewhere in the tree as a nested sub-table -- double-
    # clicking such a row drills into it, with a breadcrumb trail and a
    # Back button, matching how the real tool's own recipe tree nests.
    # ------------------------------------------------------------------
    _RECIPE_BUILDER_COLUMNS = ["Step Type", "Parameter 1", "Parameter 2", "Parameter 3", "Parameter 4", "Comment"]

    # Verified against a real machine photo: the
    # top-level "Complete Process" recipe gets its own, real-machine-
    # style column set instead of the generic grid above -- see
    # generated_recipe_export.summarize_complete_process_step, which derives
    # every one of these from the underlying steps (never typed
    # directly on this table; double-click a row to open its own
    # sub-recipe and edit the real numbers there).
    _RECIPE_BUILDER_COMPLETE_PROCESS_COLUMNS = [
        "Subproc Name", "Time (mm:ss)", "Thickness (nm)", "Evap Tilt (°)", "Comment"]

    # (template key, menu label) -- see _recipe_builder_template_step
    _RECIPE_BUILDER_TEMPLATES = [
        ("mill_position", "Mill: Recipe Tilt Substrate (Etch)"),
        ("mill_gas", "Mill: Ar Ion Gun Gas"),
        ("mill_beam", "Mill: Ion Beam strike"),
        ("mill_beam_off", "Mill: Ion Beam off"),
        ("dep_rate", "Deposition: Rate control"),
        ("dep_ramp", "Deposition: E Gun Emission"),
        ("ti_gather_rate", "Ti Gather: Rate control"),
        ("material_select", "Material select"),
        ("operator_requested", "Operator requested (message)"),
        ("recipe_thickness", "Deposition: RecipeThickness"),
        ("oxidation_static", "Oxidation: Static Oxidation"),
        ("oxidation_wait", "Oxidation: Param Wait"),
        ("recipe_call", "Call another recipe..."),
    ]

    def _recipe_builder_ensure_tree_loaded(self):
        """Lazily loads the persistent recipe tree (recipe_builder_model.
        load_tree -- a fresh default_tree() if nothing's been saved
        yet) the first time the Recipe Builder view is built, so it
        survives closing the app the same way the Design Library does."""
        if getattr(self, "_recipe_tree_root", None) is None:
            self._recipe_tree_root = rtm.load_tree()
            self._recipe_builder_current_path = None
            self._recipe_builder_history = []

    def _build_recipe_library_tree_panel(self) -> QWidget:
        """Recipe Library tree + its CRUD toolbar -- the LEFT half of
        the old combined "Recipe Builder (from scratch)" page, now one
        of the two pages in the Recipe tab's left-hand mode stack (see
        _build_recipe_tab). The table/breadcrumb/warnings panel a click
        here opens is built separately (_build_recipe_table_panel /
        _build_recipe_warnings_panel) and SHARED with the "Auto-
        Generated (from Design)" mode -- generating a recipe there opens
        it in the exact same panel this tree opens recipes into, so
        there's only ever one browsable table view in this tab, not two."""
        self._recipe_builder_ensure_tree_loaded()

        # --- Left: recipe tree (folders + named recipes) ---
        left = QVBoxLayout()
        left_header = QLabel("Recipe Library (tree)")
        self._themed(left_header, lambda: f"color: {TEXT_COLOR}; font-weight: bold; font-size: 11pt;")
        left.addWidget(left_header)
        left_sub = QLabel("Matches the real tool's own recipe tree -- a step can call another "
                           "named recipe here as a nested sub-table.")
        left_sub.setWordWrap(True)
        self._themed(left_sub, lambda: f"color: {DIM_COLOR}; font-size: 7.5pt;")
        left.addWidget(left_sub)

        tree_toolbar = QHBoxLayout()
        new_folder_btn = QPushButton("New Folder")
        new_folder_btn.clicked.connect(self._on_recipe_builder_new_folder)
        tree_toolbar.addWidget(new_folder_btn)
        new_recipe_btn = QPushButton("New Recipe")
        new_recipe_btn.clicked.connect(self._on_recipe_builder_new_recipe)
        tree_toolbar.addWidget(new_recipe_btn)
        rename_btn = QPushButton("Rename")
        rename_btn.clicked.connect(self._on_recipe_builder_rename_node)
        tree_toolbar.addWidget(rename_btn)
        # A way to save a certain recipe table that's known to work and
        # is worth reusing across multiple projects -- bring it up and
        # reuse it, matching how someone would actually work: duplicate a
        # known-good recipe, then tweak angles/thickness/times on the
        # copy, leaving the reusable original untouched.
        duplicate_btn = QPushButton("Duplicate")
        duplicate_btn.clicked.connect(self._on_recipe_builder_duplicate_node)
        tree_toolbar.addWidget(duplicate_btn)
        # Sometimes a recipe gets accidentally created in the wrong
        # folder (e.g. an evaporation recipe nested under an ion-milling
        # folder) with no easy way to move that work into the correct
        # folder afterward -- either by copy-pasting all the steps into a
        # new recipe, or by dragging the recipe into a different folder.
        # Both ideas are offered: this button (a destination-folder picker,
        # for when the tree is too big/nested to comfortably drag) and
        # real drag-and-drop on the tree itself (see _RecipeTreeWidget
        # below) -- both go through the exact same recipe_builder_model.
        # move_child, so a folder or a whole recipe (every step,
        # sub-recipe, and call_params underneath it) always moves
        # completely intact, never rebuilt or partially copied.
        move_btn = QPushButton("Move...")
        move_btn.setToolTip("Move the selected folder or recipe into a different folder -- "
                             "you can also just drag it onto the folder in the tree below.")
        move_btn.clicked.connect(self._on_recipe_builder_move_node)
        tree_toolbar.addWidget(move_btn)
        delete_btn = QPushButton("Delete")
        delete_btn.clicked.connect(self._on_recipe_builder_delete_node)
        tree_toolbar.addWidget(delete_btn)
        left.addLayout(tree_toolbar)

        self.recipe_tree_widget = _RecipeTreeWidget()
        self.recipe_tree_widget.setHeaderHidden(True)
        self._themed(self.recipe_tree_widget, lambda: f"""
            QTreeWidget {{ background-color: {PANEL_COLOR}; color: {TEXT_COLOR}; border: 1px solid #2e3040; }}
        """)
        self.recipe_tree_widget.itemClicked.connect(self._on_recipe_builder_tree_clicked)
        self.recipe_tree_widget.item_moved_callback = self._on_recipe_builder_tree_item_dropped
        left.addWidget(self.recipe_tree_widget, stretch=1)

        # Same static "quantum" card chassis as _sim_card's own frame
        # (gradient fill, theme-reactive border) -- this panel sits
        # directly in the Recipe tab's splitter with no _sim_card
        # wrapper of its own, so it was the one bare/unstyled pane next
        # to two that already look like cards; matching them keeps the
        # visual language consistent across all the cards on each tab.
        left_widget = QWidget()
        left_widget.setObjectName("recipeLibraryPanel")
        self._themed(left_widget, lambda: (
            f"QWidget#recipeLibraryPanel {{ "
            f"background: qlineargradient(x1:0, y1:0, x2:0, y2:1, "
            f"stop:0 {QColor(PANEL_COLOR).lighter(114).name()}, stop:1 {PANEL_COLOR}); "
            f"border: 1px solid {BORDER_COLOR}; border-radius: 10px; }}"
        ))
        left.setContentsMargins(12, 10, 12, 10)
        left.setSpacing(6)
        left_widget.setLayout(left)
        return left_widget

    def _build_recipe_table_panel(self) -> QWidget:
        """The breadcrumb/toolbar/step-table panel -- SHARED between
        both Recipe tab modes (see _build_recipe_library_tree_panel's
        docstring). Whatever recipe is currently open (a from-scratch
        one picked from the tree, or the just-generated complete_process
        recipe) renders here via _recipe_builder_open_path, regardless
        of which left-hand mode is active."""
        # --- breadcrumb + step table ---
        right = QVBoxLayout()

        # Design-link banner: saving a design also saves the by-hand
        # recipe linked to it. Shows/hides itself via
        # _recipe_builder_refresh_design_link_banner (called on save,
        # on load, and once here at startup).
        link_row = QHBoxLayout()
        self.recipe_builder_design_link_label = QLabel("")
        self.recipe_builder_design_link_label.setWordWrap(True)
        self._themed(self.recipe_builder_design_link_label, lambda: f"color: {DIM_COLOR}; font-size: 8pt;")
        self.recipe_builder_design_link_label.setVisible(False)
        link_row.addWidget(self.recipe_builder_design_link_label, stretch=1)
        self.recipe_builder_design_link_btn = QPushButton("Open")
        self.recipe_builder_design_link_btn.setVisible(False)
        self.recipe_builder_design_link_btn.clicked.connect(self._on_recipe_builder_open_design_link)
        link_row.addWidget(self.recipe_builder_design_link_btn)
        right.addLayout(link_row)

        crumb_row = QHBoxLayout()
        self.recipe_builder_back_btn = QPushButton("◀ Back")
        self.recipe_builder_back_btn.clicked.connect(self._on_recipe_builder_back)
        self.recipe_builder_back_btn.setEnabled(False)
        crumb_row.addWidget(self.recipe_builder_back_btn)
        self.recipe_builder_breadcrumb = QLabel("Select or create a recipe on the left.")
        self.recipe_builder_breadcrumb.setWordWrap(True)
        self._themed(self.recipe_builder_breadcrumb,
                     lambda: f"color: {TEXT_COLOR}; font-weight: bold; font-size: 10pt;")
        crumb_row.addWidget(self.recipe_builder_breadcrumb)
        crumb_row.addStretch()
        right.addLayout(crumb_row)

        table_toolbar = QHBoxLayout()
        # Stashed on self (not just locals) so _recipe_builder_refresh_table
        # can grey them out while a "Complete Process" node is open --
        # this derived, real-machine-style
        # summary view is a read/drill-down display (double-click a row
        # to open ITS OWN real, directly-editable recipe), not a place to
        # hand-edit the overall step sequence -- that structural editing
        # (insert a step anywhere in the sequence) is the separate,
        # larger "add/subtract steps" ask that belongs in Simulate
        # Design's consolidated predictor tab instead.
        self.recipe_builder_add_step_btn = QPushButton("+ Add Step")
        self.recipe_builder_add_step_btn.clicked.connect(self._on_recipe_builder_add_step)
        table_toolbar.addWidget(self.recipe_builder_add_step_btn)
        self.recipe_builder_del_step_btn = QPushButton("Delete Step")
        self.recipe_builder_del_step_btn.clicked.connect(self._on_recipe_builder_delete_step)
        table_toolbar.addWidget(self.recipe_builder_del_step_btn)
        self.recipe_builder_up_btn = QPushButton("Move Up")
        self.recipe_builder_up_btn.clicked.connect(lambda: self._on_recipe_builder_move_step(-1))
        table_toolbar.addWidget(self.recipe_builder_up_btn)
        self.recipe_builder_down_btn = QPushButton("Move Down")
        self.recipe_builder_down_btn.clicked.connect(lambda: self._on_recipe_builder_move_step(1))
        table_toolbar.addWidget(self.recipe_builder_down_btn)

        self.recipe_builder_template_btn = QToolButton()
        self.recipe_builder_template_btn.setText("Insert Typical Step ▾")
        self.recipe_builder_template_btn.setPopupMode(QToolButton.InstantPopup)
        template_menu = QMenu(self.recipe_builder_template_btn)
        for key, label in self._RECIPE_BUILDER_TEMPLATES:
            action = template_menu.addAction(label)
            action.triggered.connect(lambda checked=False, k=key: self._on_recipe_builder_insert_template(k))
        self.recipe_builder_template_btn.setMenu(template_menu)
        table_toolbar.addWidget(self.recipe_builder_template_btn)

        table_toolbar.addStretch()
        save_tree_btn = QPushButton("Save Recipe Tree")
        save_tree_btn.clicked.connect(self._on_recipe_builder_save_tree)
        table_toolbar.addWidget(save_tree_btn)
        export_btn = QPushButton("Export .txt")
        export_btn.clicked.connect(self._on_recipe_builder_export_txt)
        table_toolbar.addWidget(export_btn)
        right.addLayout(table_toolbar)

        self.recipe_builder_table = QTableWidget(0, len(self._RECIPE_BUILDER_COLUMNS))
        self.recipe_builder_table.verticalHeader().setVisible(False)
        # Fixes a bug where the end of a long subprocess name was not
        # visible -- it only showed part of the name followed by "...",
        # without dropping to the next line. A long "Subproc
        # Name" (the derived Complete Process view's first column, see
        # _recipe_builder_append_complete_process_row) was being elided
        # with "..." instead of wrapping, with no way to read the full
        # name short of widening the column enough to fit the single
        # longest name in the whole table -- exactly the kind of verbose,
        # every-parameter-spelled-out name this app's own naming
        # convention deliberately produces. setWordWrap
        # lets long cell text wrap onto a second line instead of eliding;
        # _recipe_builder_refresh_table calls resizeRowsToContents() right
        # after populating so a wrapped row actually grows tall enough to
        # show its second line (the table's own default row height,
        # verticalHeader().setDefaultSectionSize, would otherwise clip it
        # right back to one line even with wrap turned on).
        self.recipe_builder_table.setWordWrap(True)
        self.recipe_builder_table.cellChanged.connect(self._on_recipe_builder_cell_changed)
        self.recipe_builder_table.cellDoubleClicked.connect(self._on_recipe_builder_row_double_clicked)
        self._themed(self.recipe_builder_table, lambda: f"""
            QTableWidget {{
                background-color: {PANEL_COLOR}; color: {TEXT_COLOR};
                gridline-color: #2e3040; border: 1px solid #2e3040;
            }}
            QHeaderView::section {{
                background-color: #23242e; color: {TEXT_COLOR};
                padding: 4px; border: 1px solid #2e3040; font-weight: bold;
            }}
        """)
        self._recipe_builder_configure_table_columns(is_complete_process=False)
        right.addWidget(self.recipe_builder_table, stretch=1)

        self.recipe_builder_table_hint = QLabel(
            "Double-click a \"Recipe\" step's row to open the sub-recipe it calls. "
            "Call values (e.g. thickness/tilt) go in that row's own Parameter columns.")
        self.recipe_builder_table_hint.setWordWrap(True)
        self._themed(self.recipe_builder_table_hint, lambda: f"color: {DIM_COLOR}; font-size: 7.5pt;")
        right.addWidget(self.recipe_builder_table_hint)

        # Same static "quantum" card chassis as _sim_card / the Recipe
        # Library panel just above -- see that panel's own comment.
        right_widget = QWidget()
        right_widget.setObjectName("recipeTablePanel")
        self._themed(right_widget, lambda: (
            f"QWidget#recipeTablePanel {{ "
            f"background: qlineargradient(x1:0, y1:0, x2:0, y2:1, "
            f"stop:0 {QColor(PANEL_COLOR).lighter(114).name()}, stop:1 {PANEL_COLOR}); "
            f"border: 1px solid {BORDER_COLOR}; border-radius: 10px; }}"
        ))
        right.setContentsMargins(12, 10, 12, 10)
        right.setSpacing(6)
        right_widget.setLayout(right)
        return right_widget

    def _build_recipe_warnings_panel(self) -> QWidget:
        """Far-right Recipe Warnings panel -- a rules engine
        (recipe_builder_rules.py) checks the currently open recipe (expanding
        every nested "Recipe" call it makes) against sequencing/machine-
        safety rules derived from real Plassys recipe-editor vocabulary
        already confirmed elsewhere in this codebase. If a step isn't
        implemented correctly, or a step is missing, a warning raises
        with a brief description of what needs to be done so the warning
        deactivates, checked for every step and substep in a whole
        recipe. Shared between both Recipe tab modes, same as
        _build_recipe_table_panel."""
        warnings_scroll = QScrollArea()
        warnings_scroll.setWidgetResizable(True)
        warnings_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAsNeeded)
        warnings_scroll.setMinimumWidth(260)
        warnings_scroll.setMaximumWidth(360)
        warnings_panel = QWidget()
        warnings_layout = QVBoxLayout(warnings_panel)
        warn_card, warn_content = self._sim_card("Recipe Warnings", "#ff6b6b", collapsed=False)
        warn_note = QLabel("Checks the recipe currently open on the right -- including every "
                            "nested \"Recipe\" call it makes -- against sequencing and machine-safety "
                            "rules confirmed from the real Plassys recipe editor.")
        warn_note.setWordWrap(True)
        self._themed(warn_note, lambda: f"color: {DIM_COLOR}; font-size: 7.5pt;")
        warn_content.addWidget(warn_note)
        self.recipe_builder_warnings_label = QLabel("Select or create a recipe to check it.")
        self.recipe_builder_warnings_label.setWordWrap(True)
        self._themed(self.recipe_builder_warnings_label, lambda: f"color: {TEXT_COLOR}; font-size: 8.5pt;")
        warn_content.addWidget(self.recipe_builder_warnings_label)
        warnings_layout.addWidget(warn_card)
        warnings_layout.addStretch()
        warnings_scroll.setWidget(warnings_panel)
        return warnings_scroll

    def _recipe_builder_refresh_design_link_banner(self):
        """Shows/hides the "this design's own recipe" banner based on
        self._current_design_recipe_link (set by _save_current_design/
        _load_design_from_library -- see design_library.save_design's
        recipe_builder_link docstring for why this is a LINK, not an
        embedded copy)."""
        if not hasattr(self, "recipe_builder_design_link_label"):
            return
        link = getattr(self, "_current_design_recipe_link", None)
        if not link:
            self.recipe_builder_design_link_label.setVisible(False)
            self.recipe_builder_design_link_btn.setVisible(False)
            return
        node = rtm.resolve_path(self._recipe_tree_root, link) if getattr(self, "_recipe_tree_root", None) else None
        self.recipe_builder_design_link_label.setVisible(True)
        if node is None or node.is_folder:
            self.recipe_builder_design_link_label.setText(
                f'This design\'s linked recipe ("{link}") no longer exists in the Recipe Library.')
            self.recipe_builder_design_link_btn.setVisible(False)
        else:
            already_open = getattr(self, "_recipe_builder_current_path", None) == link
            self.recipe_builder_design_link_label.setText(
                f'This design\'s own recipe: "{link}"' + (" (currently open)" if already_open else ""))
            self.recipe_builder_design_link_btn.setVisible(not already_open)

    def _on_recipe_builder_open_design_link(self):
        link = getattr(self, "_current_design_recipe_link", None)
        if not link:
            return
        self.recipe_mode_builder_btn.click()
        self._recipe_builder_history = []
        self.recipe_builder_back_btn.setEnabled(False)
        self._recipe_builder_open_path(link, push_history=False)

    def _recipe_builder_refresh_warnings(self):
        """Re-runs recipe_builder_rules.validate_recipe against whichever recipe
        is currently open in the Recipe Builder and refreshes the
        Recipe Warnings card. Called after every edit that could change
        a recipe's own steps or the tree structure it calls into (see
        callers throughout the Recipe Builder section below)."""
        if not hasattr(self, "recipe_builder_warnings_label"):
            return
        # There should also be a way to save any recipes-in-progress as
        # an independent thing. The
        # Recipe Builder tree already lives independently of any design
        # (a single shared library file -- recipe_builder_model.py), but
        # previously only persisted to disk when "Save Recipe Tree" was
        # clicked explicitly; autosaving on every edit (this method is
        # called from every mutation handler -- add/delete/move step,
        # cell edit, step-type change, template insert, tree rename/
        # delete) means in-progress work is never lost to a forgotten
        # click or a closed app, independent of whether any design is
        # ever saved. Failure here (e.g. a read-only disk) must never
        # break the live UI -- it's silently skipped; "Save Recipe
        # Tree" still exists for an explicit, confirmed save.
        if getattr(self, "_recipe_tree_root", None) is not None:
            try:
                rtm.save_tree(self._recipe_tree_root)
            except Exception:
                pass
        path = getattr(self, "_recipe_builder_current_path", None)
        node = self._recipe_builder_current_node()
        if not path or node is None:
            self.recipe_builder_warnings_label.setText("Select or create a recipe to check it.")
            self._themed(self.recipe_builder_warnings_label, lambda: f"color: {TEXT_COLOR}; font-size: 8.5pt;")
            return
        try:
            warnings = rr.validate_recipe(self._recipe_tree_root, path)
        except Exception as e:
            self.recipe_builder_warnings_label.setText(f"Couldn't check this recipe: {e}")
            self._themed(self.recipe_builder_warnings_label, lambda: f"color: {DIM_COLOR}; font-size: 8.5pt;")
            return
        if not warnings:
            self.recipe_builder_warnings_label.setText(
                "✓ No rule warnings for this recipe (including every recipe it calls).")
            self._themed(self.recipe_builder_warnings_label, lambda: f"color: {TEXT_COLOR}; font-size: 8.5pt;")
            return
        n_critical = sum(1 for w in warnings if w.severity == "critical")
        n_caution = len(warnings) - n_critical
        header = f"{n_critical} critical, {n_caution} caution" if n_caution else f"{n_critical} critical"
        text = f"{header}:\n\n" + "\n\n".join(w.display_text() for w in warnings)
        self.recipe_builder_warnings_label.setText(text)
        self.recipe_builder_warnings_label.setStyleSheet("color: #ff6b6b; font-size: 8.5pt; font-weight: bold;")

    # --- tree widget population / navigation ---

    def _recipe_builder_current_node(self) -> Optional[rtm.PlassysRecipeNode]:
        path = getattr(self, "_recipe_builder_current_path", None)
        node = rtm.resolve_path(self._recipe_tree_root, path) if path else None
        if node is not None and not node.is_folder:
            return node
        # Fixes a bug where a newly created and selected recipe (highlighted
        # in the tree) could still be reported as "no recipe open" when
        # adding a step, because the internal current-path tracker had
        # fallen out of sync with the tree widget's own selection.
        # Whatever the precise cause of that desync (a version mismatch
        # between session runs, or any other edge case), the tree widget's
        # OWN highlighted selection is the more reliable, more visible
        # source of truth for which recipe is meant right now -- a recipe
        # leaf actually highlighted in the tree should always be usable,
        # never blocked by a stale internal path the user has no way to see
        # or fix themselves. Falls back to it here (and ADOPTS it as the
        # new current path + breadcrumb, so the step table -- refreshed by
        # every caller right after this, e.g. _on_recipe_builder_add_step --
        # shows the right thing too) instead of silently reporting nothing
        # is open.
        item = self.recipe_tree_widget.currentItem() if hasattr(self, "recipe_tree_widget") else None
        if item is not None:
            sel_path = item.data(0, Qt.UserRole)
            sel_node = rtm.resolve_path(self._recipe_tree_root, sel_path) if sel_path else None
            if sel_node is not None and not sel_node.is_folder:
                self._recipe_builder_current_path = sel_path
                if hasattr(self, "recipe_builder_breadcrumb"):
                    self.recipe_builder_breadcrumb.setText(sel_path.replace(rtm.PATH_SEP, "  ›  "))
                return sel_node
        return None

    def _recipe_builder_refresh_tree_widget(self):
        self.recipe_tree_widget.blockSignals(True)
        self.recipe_tree_widget.clear()
        root_item = QTreeWidgetItem([self._recipe_tree_root.name])
        root_item.setData(0, Qt.UserRole, self._recipe_tree_root.name)
        root_item.setIcon(0, qta.icon("fa5s.folder", color=DIM_COLOR))
        self.recipe_tree_widget.addTopLevelItem(root_item)

        def _add_children(parent_item, node, path):
            for name in node.child_names():
                child = node.children[name]
                child_path = path + rtm.PATH_SEP + name
                item = QTreeWidgetItem([name])
                item.setData(0, Qt.UserRole, child_path)
                item.setIcon(0, qta.icon("fa5s.folder" if child.is_folder else "fa5s.file-alt",
                                          color=(DIM_COLOR if child.is_folder else "#7fc8e6")))
                parent_item.addChild(item)
                _add_children(item, child, child_path)

        _add_children(root_item, self._recipe_tree_root, self._recipe_tree_root.name)
        self.recipe_tree_widget.expandAll()
        self.recipe_tree_widget.blockSignals(False)

    def _on_recipe_builder_tree_clicked(self, item, column):
        path = item.data(0, Qt.UserRole)
        node = rtm.resolve_path(self._recipe_tree_root, path)
        if node is None or node.is_folder:
            return  # folders aren't opened in the table -- only real recipes are
        self._recipe_builder_history = []
        self.recipe_builder_back_btn.setEnabled(False)
        self._recipe_builder_open_path(path, push_history=False)

    def _recipe_builder_open_path(self, path: str, push_history: bool = True):
        node = rtm.resolve_path(self._recipe_tree_root, path)
        if node is None or node.is_folder:
            QMessageBox.information(self, "Can't open", f'"{path}" is a folder, not a recipe.')
            return
        current = getattr(self, "_recipe_builder_current_path", None)
        if push_history and current:
            self._recipe_builder_history.append(current)
            self.recipe_builder_back_btn.setEnabled(True)
        self._recipe_builder_current_path = path
        self.recipe_builder_breadcrumb.setText(path.replace(rtm.PATH_SEP, "  ›  "))
        self._recipe_builder_refresh_table()
        self._recipe_builder_refresh_design_link_banner()

    def _on_recipe_builder_back(self):
        if not getattr(self, "_recipe_builder_history", None):
            return
        prev = self._recipe_builder_history.pop()
        self._recipe_builder_open_path(prev, push_history=False)
        self.recipe_builder_back_btn.setEnabled(bool(self._recipe_builder_history))

    # --- step table population / editing ---

    def _recipe_builder_configure_table_columns(self, is_complete_process: bool):
        """Switches recipe_builder_table between the generic Step Type/
        Parameter 1-4/Comment grid and the derived, real-machine-style
        Subproc Name/Time/Thickness/Evap Tilt/Comment columns shown for
        the top-level "Complete Process" recipe. Also fixes a separate
        readability issue: uniform Stretch used to give every column the
        exact same width regardless of content, so a short "Step Type"
        combo and a long free-text Comment were squeezed identically --
        each column now gets its own generous,
        still user-resizable (Interactive) starting width, with only
        the last (Comment) column left on Stretch to soak up whatever
        room remains. If the panel is still narrower than that, the
        table scrolls horizontally instead of silently clipping text
        into unreadable slivers."""
        table = self.recipe_builder_table
        cols = (self._RECIPE_BUILDER_COMPLETE_PROCESS_COLUMNS if is_complete_process
                else self._RECIPE_BUILDER_COLUMNS)
        table.setColumnCount(len(cols))
        table.setHorizontalHeaderLabels(cols)
        header = table.horizontalHeader()
        widths = [340, 90, 110, 100] if is_complete_process else [190, 130, 130, 130, 130]
        for col, w in enumerate(widths):
            header.setSectionResizeMode(col, QHeaderView.Interactive)
            table.setColumnWidth(col, w)
        header.setSectionResizeMode(len(cols) - 1, QHeaderView.Stretch)  # Comment
        table.verticalHeader().setDefaultSectionSize(30)
        if hasattr(self, "recipe_builder_table_hint"):
            self.recipe_builder_table_hint.setText(
                "Every value here is derived from the sub-recipe each row calls -- double-click a "
                "row to open it and see/edit the real Step Type/Parameter/Comment table underneath."
                if is_complete_process else
                "Double-click a \"Recipe\" step's row to open the sub-recipe it calls. "
                "Call values (e.g. thickness/tilt) go in that row's own Parameter columns.")

    def _recipe_builder_refresh_structural_controls(self, is_complete_process: bool):
        """Add/Delete/Move used to be entirely disabled while a "Complete
        Process" node is open. This was a bug: if an auto-generated
        Complete Process recipe ended up with an unwanted extra step (for
        example an extra milling step), there was no way to remove it --
        row editing only worked on the underlying sub-recipe steps, not on
        the top-level sequence itself. The underlying data (node.steps) is
        an ordinary mutable list[PlassysStepRow] regardless of which node
        it belongs to -- the old blanket disable was a pure UI gate with no
        data-model justification, and it blocked exactly this kind of
        correction. Add/Delete/Move are now enabled for a Complete Process
        node too (see
        _on_recipe_builder_add_step for how Add there prompts for a
        target recipe path immediately, since a fresh row's cells render
        READ-ONLY in this view -- there is no other way to fill one in).

        Template ("Insert Typical Step") stays gated: it inserts a
        generic mill/deposition/oxidation template step, which has no
        meaning at the Complete Process level (every real row there is
        either a "Recipe" call to a real sub-recipe, or one of a small
        set of fixed boilerplate rows like Pump Chamber/LL Process/
        Wait) -- adapting it to insert a "Recipe call" template instead
        is a separate, deliberately deferred piece of work, not part of
        this fix (which was specifically about add/delete/move)."""
        tip = ("Adding a step here prompts for the recipe path it should call; double-click any "
               "row to open and edit its own recipe."
               if is_complete_process else "")
        for btn in (getattr(self, "recipe_builder_add_step_btn", None),
                    getattr(self, "recipe_builder_del_step_btn", None),
                    getattr(self, "recipe_builder_up_btn", None),
                    getattr(self, "recipe_builder_down_btn", None)):
            if btn is not None:
                btn.setEnabled(True)
                btn.setToolTip(tip)
        template_btn = getattr(self, "recipe_builder_template_btn", None)
        if template_btn is not None:
            template_btn.setEnabled(not is_complete_process)
            template_btn.setToolTip(
                "Insert Typical Step isn't available for the Complete Process sequence -- every real "
                "row there is a call to a real sub-recipe. Use Add Step instead."
                if is_complete_process else "")

    def _recipe_builder_append_complete_process_row(self, step: "rtm.PlassysStepRow"):
        """Populates one READ-ONLY row of the derived Complete-Process
        view (see generated_recipe_export.summarize_complete_process_step).
        Double-click still opens a "Recipe" call's own target exactly
        like the generic grid does -- _on_recipe_builder_row_double_
        clicked reads the underlying node.steps[row] directly, not the
        displayed cell text, so it's unaffected by which column layout
        is currently showing."""
        table = self.recipe_builder_table
        row = table.rowCount()
        table.insertRow(row)
        summary = rte.summarize_complete_process_step(self._recipe_tree_root, step)
        for col, value in enumerate((summary["name"], summary["time_str"], summary["thickness_nm"],
                                      summary["tilt_deg"], summary["comment"])):
            item = QTableWidgetItem(value)
            item.setFlags(item.flags() & ~Qt.ItemIsEditable)
            if value:
                item.setToolTip(value)
            table.setItem(row, col, item)
        return row

    def _recipe_builder_refresh_table(self):
        node = self._recipe_builder_current_node()
        is_cp = rte.is_complete_process_path(getattr(self, "_recipe_builder_current_path", "") or "")
        self._recipe_builder_configure_table_columns(is_cp)
        table = self.recipe_builder_table
        table.blockSignals(True)
        table.setRowCount(0)
        if node is not None:
            for step in node.steps:
                if is_cp:
                    self._recipe_builder_append_complete_process_row(step)
                else:
                    self._recipe_builder_append_row(step)
        table.blockSignals(False)
        table.resizeRowsToContents()  # lets a wrapped long "Subproc Name" cell actually grow
                                       # tall enough to show its second line (setWordWrap alone
                                       # is clipped right back to one line by the table's own
                                       # fixed default row height otherwise)
        self._recipe_builder_refresh_structural_controls(is_cp)
        self._recipe_builder_refresh_warnings()

    def _recipe_builder_param_cell(self, row: int, col: int, step_type: str, value: str):
        """Builds the correct cell content for Parameter column `col`
        (1-4) of `row`, given the step type currently selected for that
        row: an editable QComboBox pre-filled with the real tool's own
        confirmed choices when recipe_builder_model.STEP_TYPE_PARAM_CHOICES
        has an entry for this (step_type, col). Some step types offer a
        small fixed set of options (e.g. "Open"/"Close"), so those are
        presented as a dropdown instead of requiring exact free-text entry
        -- still editable even as a combo (setEditable(True)), so an
        unusual real value can always be typed in directly.

        Otherwise (a genuinely free-typed value with no small fixed set
        of choices -- a target current, a rotation angle, a rate, a
        duration, a message, ...): a real QLineEdit with its
        placeholderText set from recipe_builder_model.STEP_TYPE_PARAM_HINTS,
        so the field shows a greyed-out hint of what belongs there (e.g.
        the tilt angle, or the units expected for that parameter). Qt's
        own placeholder text already does exactly this: it's genuinely empty (not a fake
        value that could be mistaken for a real one), shows the grey
        hint only while the field is empty, and disappears the instant
        real text is typed -- a plain QTableWidgetItem has no equivalent
        of this, which is why a real value used to have to be prefilled
        just to show the user anything at all. A step type/column with
        no hint text (STEP_TYPE_PARAM_HINTS defaults to "") just shows
        no placeholder, same as before."""
        table = self.recipe_builder_table
        # Removing/replacing an item (takeItem, or an old item still
        # sitting under a widget we're about to add) fires the table's
        # own cellChanged -- which would otherwise immediately run
        # _on_recipe_builder_cell_changed and stomp the model value we
        # just set right back to "" (it reads table.item(row, col),
        # which is briefly None/stale mid-rebuild). blockSignals for
        # this purely-visual rebuild so only a REAL user edit (through
        # _on_recipe_builder_cell_changed or the widget's own
        # _on_recipe_builder_param_widget_changed) ever writes back.
        table.blockSignals(True)
        try:
            table.removeCellWidget(row, col)
            table.takeItem(row, col)  # drop any leftover free-text item so it can't shadow the new widget
            choices = rtm.STEP_TYPE_PARAM_CHOICES.get(step_type, {}).get(col)
            if choices:
                combo = QComboBox()
                combo.setEditable(True)
                combo.addItems(choices)
                if value and value not in choices:
                    combo.addItem(value)
                combo.setCurrentText(value or choices[0])  # BEFORE connecting -- avoids a redundant write-back
                combo.currentTextChanged.connect(
                    lambda text, r=row, c=col: self._on_recipe_builder_param_widget_changed(r, c, text))
                table.setCellWidget(row, col, combo)
            else:
                hints = rtm.STEP_TYPE_PARAM_HINTS.get(step_type, ("", "", "", ""))
                placeholder = hints[col - 1] if 1 <= col <= len(hints) else ""
                edit = QLineEdit(value)
                if placeholder:
                    edit.setPlaceholderText(placeholder)
                edit.textChanged.connect(
                    lambda text, r=row, c=col: self._on_recipe_builder_param_widget_changed(r, c, text))
                table.setCellWidget(row, col, edit)
        finally:
            table.blockSignals(False)

    def _recipe_builder_comment_cell(self, row: int, step_type: str, comment: str):
        """The Comment column auto-fills from recipe_builder_model.
        STEP_TYPE_DEFAULT_COMMENT and is locked (not user-editable) for
        every step type except "Comment Only", so comments come
        automatically with the step rather than needing to be typed each
        time. "Comment Only" exists specifically so the user can write
        their own free-form note, so it stays editable and untouched."""
        table = self.recipe_builder_table
        table.blockSignals(True)  # see the note in _recipe_builder_param_cell above
        try:
            table.removeCellWidget(row, 5)
            item = QTableWidgetItem(comment)
            if step_type != "Comment Only":
                item.setFlags(item.flags() & ~Qt.ItemIsEditable)
            table.setItem(row, 5, item)
        finally:
            table.blockSignals(False)

    def _recipe_builder_append_row(self, step: "rtm.PlassysStepRow"):
        table = self.recipe_builder_table
        row = table.rowCount()
        table.insertRow(row)
        combo = QComboBox()
        combo.addItems(rtm.STEP_TYPE_VOCAB)
        if step.step_type not in rtm.STEP_TYPE_VOCAB:
            combo.addItem(step.step_type)
        combo.setCurrentText(step.step_type)  # BEFORE connecting -- avoids a redundant write-back below
        combo.currentTextChanged.connect(lambda text, r=row: self._on_recipe_builder_step_type_changed(r, text))
        table.setCellWidget(row, 0, combo)
        for col, value in enumerate([step.param1, step.param2, step.param3, step.param4], start=1):
            self._recipe_builder_param_cell(row, col, step.step_type, value)
        self._recipe_builder_comment_cell(row, step.step_type, step.comment)
        return row

    def _on_recipe_builder_step_type_changed(self, row: int, text: str):
        node = self._recipe_builder_current_node()
        if node is None or row >= len(node.steps):
            return
        step = node.steps[row]
        changed = text != step.step_type
        step.step_type = text
        if changed:
            # Switching Step Type resets Parameter 1-4 to that type's own
            # safe/neutral defaults (the old type's params rarely mean
            # anything for the new type -- e.g. a duration doesn't belong
            # on a "Material select" row) and re-fills the Comment
            # automatically, since comments come automatically with the
            # step -- except "Comment Only", whose whole purpose is a
            # user-authored note, so switching TO it starts with a blank
            # comment to write, and switching AWAY from it still gets the
            # new type's own auto comment like everything else.
            defaults = rtm.STEP_TYPE_DEFAULT_PARAMS.get(text, ("", "", "", ""))
            step.param1, step.param2, step.param3, step.param4 = defaults
            step.comment = "" if text == "Comment Only" else rtm.STEP_TYPE_DEFAULT_COMMENT.get(text, "")
            table = self.recipe_builder_table
            for col, value in enumerate(defaults, start=1):
                self._recipe_builder_param_cell(row, col, text, value)
            self._recipe_builder_comment_cell(row, text, step.comment)
        self._recipe_builder_refresh_warnings()

    def _on_recipe_builder_param_widget_changed(self, row: int, col: int, text: str):
        """currentTextChanged handler for a Parameter column rendered as
        a dropdown (see _recipe_builder_param_cell) -- a QComboBox is an
        independent widget, not a QTableWidgetItem, so it never raises
        the table's own cellChanged signal; this is that column's
        equivalent of _on_recipe_builder_cell_changed below."""
        node = self._recipe_builder_current_node()
        if node is None or row >= len(node.steps):
            return
        field_names = [None, "param1", "param2", "param3", "param4"]
        setattr(node.steps[row], field_names[col], text)
        self._recipe_builder_refresh_warnings()

    def _on_recipe_builder_cell_changed(self, row: int, col: int):
        node = self._recipe_builder_current_node()
        if node is None or row >= len(node.steps) or col == 0:
            return
        item = self.recipe_builder_table.item(row, col)
        text = item.text() if item is not None else ""
        field_names = [None, "param1", "param2", "param3", "param4", "comment"]
        setattr(node.steps[row], field_names[col], text)
        self._recipe_builder_refresh_warnings()

    def _on_recipe_builder_add_step(self):
        node = self._recipe_builder_current_node()
        if node is None:
            QMessageBox.information(self, "No recipe open", "Select or create a recipe on the left first.")
            return
        is_cp = rte.is_complete_process_path(getattr(self, "_recipe_builder_current_path", "") or "")
        if is_cp:
            # See _recipe_builder_refresh_structural_controls' own
            # docstring for the background: a Complete Process row can
            # only ever be a "Recipe" call to a real sub-recipe (or fixed
            # boilerplate this Add flow doesn't build) -- and its cells
            # render READ-ONLY in this view (_recipe_builder_append_
            # complete_process_row), so a step added with an empty
            # target could never be filled in afterward (double-clicking
            # an empty-target Recipe row just shows "Set Parameter 1..."
            # -- there is no cell to type it into here). Prompt for the
            # target path up front instead, validating it the same way
            # _on_recipe_builder_row_double_clicked does, so a newly
            # added row is immediately usable.
            target_path, ok = QInputDialog.getText(
                self, "Add Step", "Recipe path this step should call (e.g. \"Evap\\Ti\"):")
            if not ok or not target_path.strip():
                return
            target_path = target_path.strip()
            target = rtm.resolve_path(self._recipe_tree_root, target_path)
            if target is None or target.is_folder:
                QMessageBox.warning(self, "Recipe not found",
                                     f'"{target_path}" doesn\'t match any recipe in the tree. '
                                     "Check the spelling/path (e.g. \"Evap\\Ti\").")
                return
            full_path = rtm.node_path(self._recipe_tree_root, target)
            node.steps.append(rtm.PlassysStepRow(step_type=rtm.RECIPE_STEP_TYPE, param1=full_path))
            self._recipe_builder_refresh_table()
            self.recipe_builder_table.selectRow(len(node.steps) - 1)
            return
        # A fresh row starts as its default type's own safe/neutral
        # defaults -- same auto-fill a Step Type change applies (see
        # _on_recipe_builder_step_type_changed) -- rather than blank,
        # so a brand-new row already shows a real comment and sensible
        # parameter choices instead of empty cells.
        default_type = rtm.PlassysStepRow().step_type
        p1, p2, p3, p4 = rtm.STEP_TYPE_DEFAULT_PARAMS.get(default_type, ("", "", "", ""))
        comment = rtm.STEP_TYPE_DEFAULT_COMMENT.get(default_type, "")
        node.steps.append(rtm.PlassysStepRow(step_type=default_type, param1=p1, param2=p2,
                                              param3=p3, param4=p4, comment=comment))
        self._recipe_builder_refresh_table()
        self.recipe_builder_table.selectRow(len(node.steps) - 1)

    def _on_recipe_builder_delete_step(self):
        node = self._recipe_builder_current_node()
        if node is None:
            return
        row = self.recipe_builder_table.currentRow()
        if row < 0 or row >= len(node.steps):
            return
        del node.steps[row]
        self._recipe_builder_refresh_table()

    def _on_recipe_builder_move_step(self, delta: int):
        node = self._recipe_builder_current_node()
        if node is None:
            return
        row = self.recipe_builder_table.currentRow()
        if row < 0:
            return
        new_row = rtm.move_step(node, row, delta)
        self._recipe_builder_refresh_table()
        self.recipe_builder_table.selectRow(new_row)

    def _on_recipe_builder_row_double_clicked(self, row: int, column: int):
        node = self._recipe_builder_current_node()
        if node is None or row >= len(node.steps):
            return
        step = node.steps[row]
        if step.step_type != rtm.RECIPE_STEP_TYPE:
            return
        target_path = (step.param1 or "").strip()
        if not target_path:
            QMessageBox.information(self, "No target set",
                                     "Set Parameter 1 to the recipe path this step should call "
                                     "(e.g. \"Evap\\Ti\") first.")
            return
        target = rtm.resolve_path(self._recipe_tree_root, target_path)
        if target is None or target.is_folder:
            QMessageBox.warning(self, "Recipe not found",
                                 f'"{target_path}" doesn\'t match any recipe in the tree. '
                                 "Check the spelling/path (e.g. \"Evap\\Ti\").")
            return
        full_path = rtm.node_path(self._recipe_tree_root, target)
        self._recipe_builder_open_path(full_path, push_history=True)

    # --- tree structure editing (folders/recipes, not steps) ---

    def _recipe_builder_selected_tree_node(self):
        item = self.recipe_tree_widget.currentItem()
        if item is None:
            return None, None
        path = item.data(0, Qt.UserRole)
        return path, rtm.resolve_path(self._recipe_tree_root, path)

    def _on_recipe_builder_new_folder(self):
        path, node = self._recipe_builder_selected_tree_node()
        parent = node if (node is not None and node.is_folder) else self._recipe_tree_root
        name, ok = QInputDialog.getText(self, "New Folder", "Folder name:")
        if not ok or not name.strip():
            return
        try:
            rtm.add_child(parent, name.strip(), is_folder=True)
        except ValueError as e:
            QMessageBox.warning(self, "Can't create folder", str(e))
            return
        self._recipe_builder_refresh_tree_widget()

    def _on_recipe_builder_new_recipe(self):
        path, node = self._recipe_builder_selected_tree_node()
        parent = node if (node is not None and node.is_folder) else self._recipe_tree_root
        name, ok = QInputDialog.getText(self, "New Recipe", "Recipe name:")
        if not ok or not name.strip():
            return
        try:
            new_node = rtm.add_child(parent, name.strip(), is_folder=False)
        except ValueError as e:
            QMessageBox.warning(self, "Can't create recipe", str(e))
            return
        self._recipe_builder_refresh_tree_widget()
        self._recipe_builder_history = []
        self.recipe_builder_back_btn.setEnabled(False)
        self._recipe_builder_open_path(rtm.node_path(self._recipe_tree_root, new_node), push_history=False)

    def _on_recipe_builder_rename_node(self):
        path, node = self._recipe_builder_selected_tree_node()
        if node is None or node is self._recipe_tree_root:
            QMessageBox.information(self, "Can't rename", "Select a folder or recipe (not Root) first.")
            return
        parent_path = rtm.join_path(rtm.split_path(path)[:-1]) or rtm.ROOT_NAME
        parent = rtm.resolve_path(self._recipe_tree_root, parent_path)
        new_name, ok = QInputDialog.getText(self, "Rename", "New name:", text=node.name)
        if not ok or not new_name.strip():
            return
        old_path = getattr(self, "_recipe_builder_current_path", None)
        try:
            rtm.rename_child(parent, node.name, new_name.strip())
        except ValueError as e:
            QMessageBox.warning(self, "Can't rename", str(e))
            return
        self._recipe_builder_refresh_tree_widget()
        if old_path == path:
            new_path = rtm.node_path(self._recipe_tree_root, node)
            self._recipe_builder_current_path = new_path
            self.recipe_builder_breadcrumb.setText(new_path.replace(rtm.PATH_SEP, "  ›  "))
        # A rename can change whether some OTHER recipe's "Recipe" step
        # (calling this one by its old path) still resolves -- refresh
        # regardless of whether the renamed node is the one open.
        self._recipe_builder_refresh_warnings()

    def _on_recipe_builder_duplicate_node(self):
        """Lets a known-good recipe be saved and reused across multiple
        projects. Duplicating (rather than editing the original in
        place) is what actually matches that workflow -- the reusable
        template stays intact, and this new project's tweaks (angles,
        thickness, times) land on the copy."""
        path, node = self._recipe_builder_selected_tree_node()
        if node is None or node is self._recipe_tree_root:
            QMessageBox.information(self, "Can't duplicate", "Select a folder or recipe (not Root) first.")
            return
        parent_path = rtm.join_path(rtm.split_path(path)[:-1]) or rtm.ROOT_NAME
        parent = rtm.resolve_path(self._recipe_tree_root, parent_path)
        default_new_name = f"{node.name} copy"
        new_name, ok = QInputDialog.getText(self, "Duplicate", "Name for the copy:", text=default_new_name)
        if not ok or not new_name.strip():
            return
        try:
            new_node = rtm.duplicate_child(parent, node.name, new_name.strip())
        except ValueError as e:
            QMessageBox.warning(self, "Can't duplicate", str(e))
            return
        self._recipe_builder_refresh_tree_widget()
        if not new_node.is_folder:
            self._recipe_builder_history = []
            self.recipe_builder_back_btn.setEnabled(False)
            self._recipe_builder_open_path(rtm.node_path(self._recipe_tree_root, new_node), push_history=False)
        else:
            self._recipe_builder_refresh_warnings()  # autosaves the tree even when staying on a recipe leaf

    def _recipe_builder_all_folder_paths(self) -> List[str]:
        """Every FOLDER's full path in the tree, Root included -- the
        candidate destination list for the "Move..." dialog. Walks the
        live model fresh each time it's called, so a folder created a
        moment ago is offered immediately, with no separate list to
        keep in sync."""
        paths: List[str] = []

        def walk(node: "rtm.PlassysRecipeNode", path: str):
            if not node.is_folder:
                return
            paths.append(path)
            for name in node.child_names():
                walk(node.children[name], path + rtm.PATH_SEP + name)

        walk(self._recipe_tree_root, self._recipe_tree_root.name)
        return paths

    def _recipe_builder_reopen_after_move(self, old_path: str, moved_name: str, new_parent_path: str):
        """After a successful move, keeps the breadcrumb/open-recipe
        state consistent if the recipe currently open in the table WAS
        the moved node itself, or was nested somewhere inside a moved
        FOLDER -- exactly the same "does this affect what's currently
        open" bookkeeping _on_recipe_builder_rename_node already does,
        generalized to a node that can jump to a completely different
        parent rather than just changing its own last path segment."""
        new_path = new_parent_path + rtm.PATH_SEP + moved_name
        current = getattr(self, "_recipe_builder_current_path", None)
        if current == old_path:
            self._recipe_builder_current_path = new_path
            self.recipe_builder_breadcrumb.setText(new_path.replace(rtm.PATH_SEP, "  ›  "))
        elif current and current.startswith(old_path + rtm.PATH_SEP):
            updated = new_path + current[len(old_path):]
            self._recipe_builder_current_path = updated
            self.recipe_builder_breadcrumb.setText(updated.replace(rtm.PATH_SEP, "  ›  "))
        # A move can also break or fix some OTHER recipe's "Recipe" call
        # into the node just relocated -- refresh regardless of whether
        # the moved node is the one open, same rationale as rename/delete.
        self._recipe_builder_refresh_warnings()

    def _on_recipe_builder_move_node(self):
        """The button version of moving a folder/recipe. A destination-
        folder PICKER is offered alongside real drag-and-drop (see
        _RecipeTreeWidget /
        _on_recipe_builder_tree_item_dropped below) since dragging
        precisely onto a deeply-nested folder in a long tree can be
        fiddly; both go through the same recipe_builder_model.move_child."""
        path, node = self._recipe_builder_selected_tree_node()
        if node is None or node is self._recipe_tree_root:
            QMessageBox.information(self, "Can't move", "Select a folder or recipe (not Root) first.")
            return
        parent_path = rtm.join_path(rtm.split_path(path)[:-1]) or rtm.ROOT_NAME
        parent = rtm.resolve_path(self._recipe_tree_root, parent_path)
        choices = [p for p in self._recipe_builder_all_folder_paths()
                   if p != parent_path and p != path and not p.startswith(path + rtm.PATH_SEP)]
        if not choices:
            QMessageBox.information(self, "Can't move", "There's no other folder to move this into yet -- "
                                     "create one with New Folder first.")
            return
        dest_path, ok = QInputDialog.getItem(self, "Move", f'Move "{node.name}" into:', choices, 0, False)
        if not ok or not dest_path:
            return
        dest_folder = rtm.resolve_path(self._recipe_tree_root, dest_path)
        try:
            rtm.move_child(parent, node.name, dest_folder)
        except ValueError as e:
            QMessageBox.warning(self, "Can't move", str(e))
            return
        self._recipe_builder_refresh_tree_widget()
        self._recipe_builder_reopen_after_move(path, node.name, dest_path)

    def _on_recipe_builder_tree_item_dropped(self, dragged_item, target_item):
        """Wired as _RecipeTreeWidget.item_moved_callback -- the
        drag-and-drop counterpart to _on_recipe_builder_move_node above,
        going through the exact same recipe_builder_model.move_child so
        dragging and the "Move..." dialog behave identically. Dropping
        onto empty space, onto the dragged item itself, or onto a
        recipe LEAF (which has no children to move anything into) are
        all quietly no-ops -- only a genuine drop onto a DIFFERENT
        folder does anything, matching a real file manager's own
        "drop it near a file and nothing happens" behavior rather than
        guessing the user meant that file's parent folder instead."""
        if target_item is None or target_item is dragged_item:
            return
        source_path = dragged_item.data(0, Qt.UserRole)
        dest_path = target_item.data(0, Qt.UserRole)
        source_node = rtm.resolve_path(self._recipe_tree_root, source_path)
        if source_node is None or source_node is self._recipe_tree_root:
            return
        dest_node = rtm.resolve_path(self._recipe_tree_root, dest_path)
        if dest_node is None or not dest_node.is_folder:
            return  # dropped onto a recipe leaf -- not a valid destination, silently ignored
        parent_path = rtm.join_path(rtm.split_path(source_path)[:-1]) or rtm.ROOT_NAME
        parent = rtm.resolve_path(self._recipe_tree_root, parent_path)
        try:
            rtm.move_child(parent, source_node.name, dest_node)
        except ValueError as e:
            QMessageBox.warning(self, "Can't move", str(e))
            return
        self._recipe_builder_refresh_tree_widget()
        self._recipe_builder_reopen_after_move(source_path, source_node.name, dest_path)

    def _on_recipe_builder_delete_node(self):
        path, node = self._recipe_builder_selected_tree_node()
        if node is None or node is self._recipe_tree_root:
            QMessageBox.information(self, "Can't delete", "Select a folder or recipe (not Root) first.")
            return
        if node.is_folder and node.children:
            reply = QMessageBox.question(self, "Delete folder",
                                          f'"{node.name}" contains {len(node.children)} item(s). '
                                          "Delete it and everything inside?",
                                          QMessageBox.Yes | QMessageBox.No)
            if reply != QMessageBox.Yes:
                return
        parent_path = rtm.join_path(rtm.split_path(path)[:-1]) or rtm.ROOT_NAME
        parent = rtm.resolve_path(self._recipe_tree_root, parent_path)
        rtm.remove_child(parent, node.name)
        if getattr(self, "_recipe_builder_current_path", None) == path:
            self._recipe_builder_current_path = None
            self.recipe_builder_breadcrumb.setText("Select or create a recipe on the left.")
            self.recipe_builder_table.setRowCount(0)
        self._recipe_builder_refresh_tree_widget()
        # A delete can break some OTHER recipe's "Recipe" call into the
        # node just removed -- refresh regardless of what's open now.
        self._recipe_builder_refresh_warnings()

    # --- "Insert Typical Step" templates, sourced from
    # self._current_recipe_params() -- the SAME values the deterministic
    # Auto-Generated engine uses (Recipe Parameters panel fields plus
    # DesignParameters' own hardcoded defaults), offered here purely as
    # convenient, fully-editable starting points. Nothing in the Recipe
    # Builder re-reads them automatically after this. ---

    def _on_recipe_builder_insert_template(self, key: str):
        node = self._recipe_builder_current_node()
        if node is None:
            QMessageBox.information(self, "No recipe open", "Select or create a recipe on the left first.")
            return
        p = self._current_recipe_params()
        step = self._recipe_builder_template_step(key, p)
        if step is None:
            return
        node.steps.append(step)
        self._recipe_builder_refresh_table()
        self.recipe_builder_table.selectRow(len(node.steps) - 1)

    def _recipe_builder_template_step(self, key: str, p: DesignParameters) -> Optional["rtm.PlassysStepRow"]:
        if key == "mill_position":
            # No literal tilt-angle parameter here -- see recipe_tree_
            # model.py's vocabulary note: the real "Recipe Tilt
            # Substrate" step only carries the destination (Deposit/
            # Etch/Load); the tilt magnitude is a Recipe-level value.
            return rtm.PlassysStepRow(step_type="Recipe Tilt Substrate", param1="Etch",
                                       comment=rtm.STEP_TYPE_DEFAULT_COMMENT.get("Recipe Tilt Substrate", ""))
        if key == "mill_gas":
            return rtm.PlassysStepRow(step_type="Ar Ion Gun Gas", param1=f"{p.mill_ar_gas_sccm:g}sccm",
                                       comment=rtm.STEP_TYPE_DEFAULT_COMMENT.get("Ar Ion Gun Gas", ""))
        if key == "mill_beam":
            return rtm.PlassysStepRow(step_type="Ion Beam", param1=f"V={p.mill_beam_voltage_v:g}",
                                       param2=f"I={p.mill_beam_current_ma:.1f}mA",
                                       param3=f"Vacc={p.mill_accel_voltage_v:g}V",
                                       comment=rtm.STEP_TYPE_DEFAULT_COMMENT.get("Ion Beam", ""))
        if key == "mill_beam_off":
            return rtm.PlassysStepRow(step_type="Ion Beam", param1="Off",
                                       comment=rtm.STEP_TYPE_DEFAULT_COMMENT.get("Ion Beam", ""))
        if key == "dep_rate":
            return rtm.PlassysStepRow(step_type="Rate control", param1=f"{p.al_dep_rate_nmps:g}nm/s",
                                       comment=rtm.STEP_TYPE_DEFAULT_COMMENT.get("Rate control", ""))
        if key == "dep_ramp":
            prof = get_ramp_profile(p.metal_type, p.al_dep_rate_nmps, [])
            return rtm.PlassysStepRow(step_type="E Gun Emission",
                                       param1=f"{prof.soak2_ma:g}mA", param2=_fmt_mmss(prof.soak2_time_s),
                                       comment=rtm.STEP_TYPE_DEFAULT_COMMENT.get("E Gun Emission", ""))
        if key == "ti_gather_rate":
            return rtm.PlassysStepRow(step_type="Rate control", param1=f"{p.ti_gather_rate_nmps:g}nm/s",
                                       comment="Ti gather")
        if key == "material_select":
            return rtm.PlassysStepRow(step_type="Material select", param1=p.metal_type,
                                       comment=rtm.STEP_TYPE_DEFAULT_COMMENT.get("Material select", ""))
        if key == "operator_requested":
            return rtm.PlassysStepRow(step_type="Operator requested", param1="Check the beam position",
                                       comment=rtm.STEP_TYPE_DEFAULT_COMMENT.get("Operator requested", ""))
        if key == "recipe_thickness":
            return rtm.PlassysStepRow(step_type="RecipeThickness",
                                       comment=rtm.STEP_TYPE_DEFAULT_COMMENT.get("RecipeThickness", ""))
        if key == "oxidation_static":
            return rtm.PlassysStepRow(step_type="Static Oxidation", param1=f"{p.oxidation_pressure_mbar:.2f}",
                                       param2="Static O2")
        if key == "oxidation_wait":
            return rtm.PlassysStepRow(step_type="Param Wait", param1=f"{p.oxidation_time_min:g} min")
        if key == "recipe_call":
            return rtm.PlassysStepRow(step_type=rtm.RECIPE_STEP_TYPE, param1="Evap\\Ti",
                                       comment="Set Parameter 1 to the recipe path to call")
        return None

    # --- save tree / export current recipe as plain text ---

    def _on_recipe_builder_save_tree(self):
        try:
            path = rtm.save_tree(self._recipe_tree_root)
        except Exception as e:
            QMessageBox.critical(self, "Save failed", f"Couldn't save the recipe tree:\n{e}")
            return
        QMessageBox.information(self, "Saved", f"Recipe tree saved to:\n{path}")

    def _on_recipe_builder_export_txt(self):
        node = self._recipe_builder_current_node()
        if node is None:
            QMessageBox.information(self, "Nothing to export", "Select or create a recipe on the left first.")
            return
        path_label = getattr(self, "_recipe_builder_current_path", None) or "recipe"
        lines = [path_label, "-" * 60]
        for step in node.steps:
            lines.append(step.line_text())
        text = "\n".join(lines)
        default_name = (rtm.split_path(path_label)[-1] if path_label else "recipe") + ".txt"
        save_path, _ = QFileDialog.getSaveFileName(self, "Export Recipe", default_name, "Text files (*.txt)")
        if not save_path:
            return
        with open(save_path, "w") as f:
            f.write(text)

    # ------------------------------------------------------------------
    # Deposition Slideshow -- Deposition Slideshow
    # ------------------------------------------------------------------
    _SLIDESHOW_CATEGORY_COLOR = {
        "prep": "#8a8d9e", "mill": "#e08a5c", "deposition": "#7fc8e6", "misc": "#cfd2e0",
    }
    # Chamber reference frame the wafer sits in during each step
    # category. Deposition steps happen with the chamber in deposition
    # ref, mill steps in mill ref. Categories not listed here (prep,
    # misc) have no alpha/theta at all -- those are the true
    # beginning/end-of-process steps and fall back to "load" ref, which
    # is correct since that's literally the load position.
    _SLIDESHOW_CATEGORY_REFERENCE = {
        "mill": "mill", "deposition": "deposition",
    }

    def _build_slideshow_tab(self) -> QWidget:
        """Deposition Slideshow -- steps through the ACTUAL
        recipe the Recipe tab generated, one step at a time, pairing each
        step's real chamber orientation (via the shared
        _ChamberPreviewWidget -- same wafer_orientation/chamber_plotting functions
        the retired Live Angle Tester uses, just a second independent consumer of them) with
        that step's full detail text and a PROGRESSIVE reference view of
        the design -- showing only the features actually deposited by
        that point, not the complete finished junction the whole time.

        The reconciliation this used to flag as a blocker (recipe_generator.
        py's per-step feature vocabulary -- "horizontal_finger",
        "patch_a", etc -- vs. junction rendering's own shape
        classification) turned out not to need reconciling at all: each
        deposition step's theta is matched directly against each real
        finger's own two possible axis directions (theta_toward_patch_
        deg / theta_toward_stub_deg), which works identically for
        parametric AND imported/GDS designs and doesn't depend on the
        recipe's tag string at all. See _slideshow_visible_features for
        the exact matching logic and _draw_post_shadow_design's
        visible_finger_indices/visible_patches filter for how it's
        applied. A finger's adhesion/overlap plate is tagged with that
        SAME finger's index by _compute_post_shadow_shapes (via
        _find_finger_for_plate), so it appears/disappears together with
        its finger automatically, so an adhesion plate deposits on screen
        at the same time as its junction finger. Patches are shown/hidden
        as ONE collective group, not per-patch, matching the natural
        framing of the three units that progressively appear: finger A,
        finger B, and the patches.

        Mill steps additionally get a highlight of which surface they're
        removing material from -- see _slideshow_draw_mill_highlight: a
        sidewall mill highlights the beam-facing edge of each currently-
        deposited shape; a top mill (alpha ~ 0) tints the WHOLE surface,
        including the substrate and, if a top mill happens to occur
        after some deposition has already happened, that already-
        deposited material's own top face too (falls out naturally from
        reusing the same cumulative visibility, no special-casing).

        SCOPE NOTE: shadowing effects are deliberately NOT modeled within
        this progressive view yet -- a feature is either fully shown
        (once its step has occurred) or not shown at all, never
        partially. That remains a follow-up, not attempted here."""
        outer = QWidget()
        self._themed(outer, lambda: f"background-color: {BG_COLOR};")
        layout = QVBoxLayout(outer)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(0)

        slideshow_toolbar = QToolBar("Slideshow Controls")
        slideshow_toolbar.setMovable(False)
        self._themed(slideshow_toolbar, lambda: f"QToolBar {{ background-color: {PANEL_COLOR}; border: none; spacing: 6px; padding: 4px 8px; }}")
        self.addToolBar(slideshow_toolbar)
        self.slideshow_toolbar = slideshow_toolbar

        # Themed styling pass for the slideshow toolbar buttons, plus a
        # real layout bug fix bundled in at the same time: previously,
        # every time the user clicked through the steps, the toolbar
        # controls would shift position because the step description
        # label changed length, so the user could not click in the same
        # spot to advance to the next step. Root cause: Prev step/
        # Next step used to sandwich self.slideshow_step_label directly
        # in this QToolBar's own left-to-right item flow, with no
        # stretch/spacer anywhere and no fixed width on the label --
        # QToolBar lays its items out strictly by each item's own
        # sizeHint, so every time the label's TEXT changed length (a
        # different step's title is rarely the same length as the
        # last), Next step and everything after it physically shifted
        # to a new on-screen X position. Two changes fix this
        # completely: (1) Prev step and Next step now sit ADJACENT to
        # each other (both fixed-size buttons, right after Reload
        # Recipe), so their own position never depended on the label to
        # begin with; (2) the label itself is now a fixed-width,
        # theme-reactive "readout chip" with its text elided to fit
        # (full text still available as a tooltip) -- CONSTANT width
        # regardless of content, so the Post Deposition / Shadow Sim
        # toggle after it never shifts either. Same attribute names,
        # same connections as before.
        refresh_btn = QuantumPillButton("Reload Recipe", accent="#8fd694", icon_name="fa5s.sync-alt")
        refresh_btn.clicked.connect(self._on_slideshow_refresh)
        slideshow_toolbar.addWidget(refresh_btn)
        slideshow_toolbar.addSeparator()
        self.slideshow_prev_btn = QuantumPillButton("Prev Step", accent=ACCENT_COLOR, icon_name="fa5s.chevron-left")
        self.slideshow_prev_btn.clicked.connect(self._on_slideshow_prev)
        slideshow_toolbar.addWidget(self.slideshow_prev_btn)
        self.slideshow_next_btn = QuantumPillButton("Next Step", accent=ACCENT_COLOR, icon_name="fa5s.chevron-right")
        self.slideshow_next_btn.clicked.connect(self._on_slideshow_next)
        slideshow_toolbar.addWidget(self.slideshow_next_btn)

        self.slideshow_step_label = QLabel("No recipe loaded")
        self.slideshow_step_label.setFixedWidth(440)  # fixes the layout-shift bug above -- constant width
                                    # regardless of content is the whole fix; see the comment block
                                    # just above. Sized generously for a realistic longest step line.
        self.slideshow_step_label.setAlignment(Qt.AlignVCenter | Qt.AlignLeft)
        self._themed(self.slideshow_step_label, lambda: (
            f"color: {TEXT_COLOR}; font-size: 9pt; padding: 0 12px; "
            f"background-color: {PANEL_COLOR}; border: 1px solid {BORDER_COLOR}; border-radius: 13px;"
        ))
        slideshow_toolbar.addWidget(self.slideshow_step_label)
        slideshow_toolbar.addSeparator()

        # Post Deposition vs. Shadow Sim view toggle,
        # mirroring the Simulate tab's own Optimal/Simulated/Post-Shadow
        # checkable-pill pattern (_set_sim_view_mode) for visual
        # consistency. Post Deposition (default) is the existing
        # progressive real-geometry reference; Shadow Sim shows the
        # nominal design with the accumulated cross-feature shadow
        # hatching -- see _slideshow_draw_shadow_sim_view.
        self.slideshow_view_post_btn = QuantumSegmentButton("Post Deposition", "#7fb8ff", "left")
        self.slideshow_view_shadowsim_btn = QuantumSegmentButton("Shadow Sim", "#7fb8ff", "right")
        slideshow_view_group = QWidget()
        slideshow_view_group_layout = QHBoxLayout(slideshow_view_group)
        slideshow_view_group_layout.setContentsMargins(0, 0, 0, 0)
        slideshow_view_group_layout.setSpacing(0)
        slideshow_view_group_layout.addWidget(self.slideshow_view_post_btn)
        slideshow_view_group_layout.addWidget(self.slideshow_view_shadowsim_btn)
        self.slideshow_view_post_btn.setChecked(True)
        self.slideshow_view_post_btn.clicked.connect(lambda: self._set_slideshow_view_mode("post"))
        self.slideshow_view_shadowsim_btn.clicked.connect(lambda: self._set_slideshow_view_mode("shadow_sim"))
        slideshow_toolbar.addWidget(slideshow_view_group)
        self._slideshow_view_mode = "post"

        body = QHBoxLayout()
        body.setContentsMargins(16, 16, 16, 16)
        body.setSpacing(12)

        # --- left: final-design reference (top) + chamber preview (bottom, smaller) ---
        left = QVBoxLayout()
        left.setSpacing(10)
        ref_label = QLabel("FINAL DESIGN (reference)")
        self._themed(ref_label, lambda: f"color: {DIM_COLOR}; font-size: 7.5pt; letter-spacing: 1px;")
        left.addWidget(ref_label)
        self.slideshow_fig = Figure(figsize=(6, 5), dpi=100, facecolor=BG_COLOR)
        self.slideshow_ax = self.slideshow_fig.add_subplot(1, 1, 1)
        self.slideshow_canvas = FigureCanvasQTAgg(self.slideshow_fig)
        self.slideshow_canvas.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
        # Lets the slideshow preview be zoomed in/out the same way the
        # Simulate tab's canvas can, via the SAME shared mouse-centered
        # scroll-to-zoom already used by Create/Import and Simulate Design
        # (_on_canvas_scroll/_zoom_step, operating on whichever of
        # self._active_ax/_active_canvas is current -- wired to this tab's
        # own ax/canvas in _on_nav_changed). Reusing that exact,
        # already-proven mechanism also ensures the view resets cleanly and
        # nothing gets clipped after zooming in and back out:
        # _slideshow_draw_reference already calls
        # _fit_shadow_axes(against the COMPLETE design's bounds) on every
        # single redraw (step navigation, view-mode toggle), so any zoom
        # applied here is naturally, cleanly re-fit the next time the
        # panel actually redraws -- exactly Simulate Design's own behavior,
        # never a stale/clipped view left behind.
        self.slideshow_canvas.mpl_connect("scroll_event", self._on_canvas_scroll)
        # Keeps the Shadow Sim view's ghost
        # caution glyphs (_slideshow_ghost_icon_texts) sized proportional
        # to the current zoom level as the user scrolls in/out, the same
        # rescale-in-place pattern Create/Import's own overlay labels use
        # (_on_create_import_xlim_changed/_create_import_xlim_callback) --
        # see _on_slideshow_xlim_changed's own docstring for why this
        # can't just be left to a full redraw. Stored as a persistent
        # attribute (matching _create_import_xlim_callback's own
        # established pattern) rather than connecting the bound method
        # directly, so _slideshow_draw_reference can cheaply reconnect
        # the SAME callback after every redraw (see its own comment --
        # Axes.clear() unconditionally wipes this axes' entire callback
        # registry, so this initial connect alone would otherwise be
        # destroyed by the very first redraw).
        self._slideshow_xlim_callback = self._on_slideshow_xlim_changed
        self.slideshow_ax.callbacks.connect("xlim_changed", self._slideshow_xlim_callback)
        left.addWidget(self.slideshow_canvas, stretch=3)

        chamber_label = QLabel("CHAMBER ORIENTATION FOR THIS STEP")
        self._themed(chamber_label, lambda: f"color: {DIM_COLOR}; font-size: 7.5pt; letter-spacing: 1px;")
        left.addWidget(chamber_label)
        self.slideshow_chamber_preview = _ChamberPreviewWidget(figsize=(6.0, 2.2))
        left.addWidget(self.slideshow_chamber_preview, stretch=1)

        left_widget = QWidget()
        left_widget.setLayout(left)
        body.addWidget(left_widget, stretch=1)

        # --- right: step list + step detail ---
        sidebar = QVBoxLayout()
        sidebar.setSpacing(10)

        list_card, list_content = self._sim_card("Recipe Steps", "#e0a875", collapsed=False)
        self.slideshow_list = QListWidget()
        self.slideshow_list.setMinimumHeight(260)
        self.slideshow_list.itemClicked.connect(self._on_slideshow_list_clicked)
        list_content.addWidget(self.slideshow_list)
        sidebar.addWidget(list_card, stretch=1)

        detail_card, detail_content = self._sim_card("Step Detail", "#7fb8ff", collapsed=False)
        self.slideshow_detail_text = QTextEdit()
        self.slideshow_detail_text.setReadOnly(True)
        self.slideshow_detail_text.setMinimumHeight(200)
        self._themed(self.slideshow_detail_text, lambda: f"background-color: {PANEL_COLOR}; color: {TEXT_COLOR}; border: 1px solid #2e3040; "
            f"border-radius: 6px;")
        detail_content.addWidget(self.slideshow_detail_text)
        sidebar.addWidget(detail_card)

        sidebar_widget = QWidget()
        sidebar_widget.setLayout(sidebar)
        sidebar_widget.setFixedWidth(320)
        body.addWidget(sidebar_widget)

        body_widget = QWidget()
        body_widget.setLayout(body)
        layout.addWidget(body_widget, stretch=1)

        self._slideshow_steps = []
        self._slideshow_index = 0
        self._on_slideshow_refresh()
        return outer

    def _on_slideshow_refresh(self):
        """Reloads whatever Recipe last generated (self._recipe_last_
        steps) -- a manual pull rather than a live subscription, so
        walking through a slideshow doesn't shift under you if you flip
        back to Recipe and tweak something mid-review; click Reload (or
        just revisit this tab -- _on_nav_changed calls this too) when
        you actually want the newest version.

        Fixes an inconsistency where a deposition thickness typed by hand
        in the recipe tab was not reflected in the junction slideshow's
        display of that step's thickness, which should update to that
        user-specified value, falling back to the default when no
        override was entered. The Recipe Parameters panel's dynamic
        thickness/mill-duration fields have no live textChanged wiring
        of their own (typing in them doesn't push anything anywhere by
        itself -- see _recipe_features_with_panel_overrides's own
        docstring, "this one generation only"), so without forcing a
        fresh rebuild right here, a "manual pull" could still pull in a
        stale self._recipe_last_steps from before the user's latest typed
        thickness, even though this IS the exact moment ("just revisit
        this tab", per this method's own long-standing contract above)
        that's supposed to fetch the newest version. Cheap and safe to
        call unconditionally -- _rebuild_recipe_from_features is already
        called constantly from elsewhere as a no-op-safe idempotent
        resync; it does nothing destructive when nothing has actually
        changed since the last call."""
        if getattr(self, "_recipe_features", None):
            self._rebuild_recipe_from_features()
        steps = list(getattr(self, "_recipe_last_steps", None) or [])
        self._slideshow_steps = steps
        self._slideshow_index = 0
        self.slideshow_list.clear()
        for step in steps:
            color = self._SLIDESHOW_CATEGORY_COLOR.get(step.category, "#cfd2e0")
            star = "★ " if step.starred else ""
            item = QListWidgetItem(f"{star}[{step.index}] {step.title}")
            item.setForeground(QColor(color))
            self.slideshow_list.addItem(item)
        self._slideshow_render_step()

    def _set_slideshow_view_mode(self, mode):
        """Toggles the Deposition Slideshow between the
        existing progressive real-geometry "Post Deposition" view and the
        new "Shadow Sim" view (_slideshow_draw_shadow_sim_view) -- mirrors
        _set_sim_view_mode's exact pattern for the Simulate tab's own
        Optimal/Simulated/Post-Shadow toggle."""
        self._slideshow_view_mode = mode
        self.slideshow_view_post_btn.setChecked(mode == "post")
        self.slideshow_view_shadowsim_btn.setChecked(mode == "shadow_sim")
        self._slideshow_draw_reference()

    def _slideshow_draw_reference(self):
        """Draws the reference panel for the CURRENTLY SELECTED step
        (self._slideshow_index). Two view modes (self._slideshow_view_
        mode):

        "post" (default) -- the REAL post-shadow geometry using only the
        deposition passes that have actually happened by this point (see
        _slideshow_cumulative_thetas / _compute_post_shadow_shapes_upto)
        -- not a simple shown/hidden filter over the already-fully-
        cascaded final shapes. A feature midway through its own multi-
        pass cascade (e.g. a patch group that's only had its first of two
        required depositions) shows the true one-pass shadow: one side
        connected, the other still short/shadowed -- the actual
        step-by-step shadowing mechanics, not an all-or-nothing
        approximation. For a mill step, also highlights which surface
        it's actually removing material from -- the ELECTRODE, per
        _slideshow_draw_mill_highlight.

        "shadow_sim" -- the nominal design, filtered to only already-
        introduced features, with the ordinary extend/shrink hatch bands
        showing only THIS STEP's own single active planetary angle (a
        per-step snapshot, not accumulated -- see
        _slideshow_draw_shadow_sim_view's own docstring, FOLLOW-UP 3, for
        why), PLUS a separate 'ghost junction line' overlay that -- unlike
        those ordinary bands -- IS cumulative: once some foreign pass
        floods a still-open aperture, that real
        deposited metal doesn't go away on later steps, so its blue-hatch
        overlay keeps showing on every step from when it first occurs
        onward. No mill highlight in this view -- it's specifically about
        deposition shadow-casting.

        Thickness shading in the "post" view uses the COMPLETE design's own thickness range
        (full_shapes, already computed here for the fit-bounds call
        below) as a FIXED min/max, not whatever's visible so far -- so a
        region's shade never jumps as more of the design is
        progressively revealed; only which regions are visible changes
        from frame to frame."""
        junction = getattr(self, "_sim_cached_junction", None)
        report = getattr(self, "_sim_cached_report", None)
        self.slideshow_ax.clear()
        # Fixed here (same root cause already documented
        # for Create/Import's own xlim_changed reconnect, see
        # _update_create_import_preview's own comment): Axes.clear()
        # unconditionally wipes the ENTIRE callback registry, not just
        # this axes' plotted artists -- so the connection made once at
        # tab-construction time (_build_slideshow_tab) was being
        # destroyed by the very first redraw and never present again.
        # Must reconnect after every clear(), not just once -- without this
        # the caution-glyph zoom-rescale never actually fires.
        self.slideshow_ax.callbacks.connect("xlim_changed", self._slideshow_xlim_callback)
        view_mode = getattr(self, "_slideshow_view_mode", "post")
        if junction is not None and report is not None:
            run = self._sim_last_run or {}
            full_shapes = self._compute_post_shadow_shapes(junction, report)
            thickness_range = self._thickness_range(full_shapes)
            if view_mode == "shadow_sim":
                self._slideshow_draw_shadow_sim_view(self.slideshow_ax, junction, report, self._slideshow_index)
                self._fit_shadow_axes(self.slideshow_ax, full_shapes)  # bounds from the COMPLETE design -- no camera jump
            else:
                finger_theta_lists, patch_thetas, finger_alpha_lists, patch_alphas_raw = self._slideshow_cumulative_thetas(junction, self._slideshow_index)
                # Patch alpha resolved the SAME way
                # patch thickness already is elsewhere (matched back
                # against the final committed _sim_patch_layers/
                # _sim_patch_alphas, not the raw per-step history), for
                # the same staleness-tolerance reason -- see
                # _slideshow_draw_shadow_sim_view's own identical comment.
                patch_alphas = self._match_pass_thicknesses(
                    patch_thetas, self._sim_patch_layers or patch_thetas,
                    self._sim_patch_alphas or [], default=None) if patch_thetas else []
                upto_shapes = self._compute_post_shadow_shapes_upto(junction, report, run, finger_theta_lists, patch_thetas,
                                                                     finger_alpha_lists=finger_alpha_lists, patch_alphas=patch_alphas)
                self._draw_shadow_shapes(self.slideshow_ax, junction, upto_shapes, thickness_range=thickness_range)
                self._fit_shadow_axes(self.slideshow_ax, full_shapes)  # bounds from the COMPLETE design -- no camera jump
                # The subtle cumulative mill-history undertone is
                # drawn on EVERY "post" step (mill or not) -- it's a no-op
                # until the first mill step has actually happened by this
                # point in the recipe, then persists on every later step,
                # same "once milled, always shows" logic as the ghost-
                # junction-line overlay elsewhere in this file.
                self._slideshow_draw_mill_history(self.slideshow_ax, junction, upto_shapes)
                step = None
                if self._slideshow_steps:
                    i = max(0, min(self._slideshow_index, len(self._slideshow_steps) - 1))
                    step = self._slideshow_steps[i]
                if step is not None and step.category == "mill":
                    self._slideshow_draw_mill_highlight(self.slideshow_ax, junction, report, step, upto_shapes)
        else:
            self.slideshow_ax.text(0.5, 0.5, "Run the simulation on Simulate Design to see the finished\n"
                                             "design here.", color=DIM_COLOR, fontsize=9,
                                   ha="center", va="center", transform=self.slideshow_ax.transAxes)
        self.slideshow_ax.set_facecolor(BG_COLOR)
        for spine in self.slideshow_ax.spines.values():
            spine.set_color(BORDER_COLOR)
        self.slideshow_canvas.draw_idle()

    def _slideshow_set_step_label(self, full_text):
        """Sets self.slideshow_step_label's text elided to fit its now-FIXED
        width (see _build_slideshow_tab) so the readout chip's own width --
        and therefore every toolbar item after it -- never shifts on-screen,
        no matter how long a given step's title is. The untruncated text is
        always available as a tooltip."""
        metrics = QFontMetrics(self.slideshow_step_label.font())
        avail = max(0, self.slideshow_step_label.width() - 24)  # minus padding
        elided = metrics.elidedText(full_text, Qt.ElideRight, avail)
        self.slideshow_step_label.setText(elided)
        self.slideshow_step_label.setToolTip(full_text)

    def _slideshow_render_step(self):
        self._slideshow_draw_reference()
        n = len(self._slideshow_steps)
        if n == 0:
            self._slideshow_set_step_label("No recipe loaded -- generate one on the Recipe tab, then Reload.")
            self.slideshow_detail_text.setPlainText(
                "Nothing to show yet. Go to the Recipe tab, click \"Generate Recipe from "
                "Simulation\", then come back and click \"Reload Recipe\" above "
                "(or just revisit this tab).")
            self.slideshow_chamber_preview.show_placeholder("No recipe loaded.")
            self.slideshow_prev_btn.setEnabled(False)
            self.slideshow_next_btn.setEnabled(False)
            return

        i = max(0, min(self._slideshow_index, n - 1))
        self._slideshow_index = i
        step = self._slideshow_steps[i]

        self._slideshow_set_step_label(f"Step {i + 1} / {n}  --  [{step.index}] {step.title}")
        self.slideshow_prev_btn.setEnabled(i > 0)
        self.slideshow_next_btn.setEnabled(i < n - 1)
        self.slideshow_list.setCurrentRow(i)

        lines = [step.title, f"Category: {step.category}" + (" (starred)" if step.starred else "")]
        if step.alpha is not None and step.theta is not None:
            lines.append(f"alpha = {step.alpha:g} deg, theta = {step.theta:g} deg")
        if step.feature:
            lines.append(f"Feature: {step.feature}")
        lines.append("")
        lines.append(step.detail)
        self.slideshow_detail_text.setPlainText("\n".join(lines))

        if step.alpha is not None and step.theta is not None:
            reference = self._SLIDESHOW_CATEGORY_REFERENCE.get(step.category, "load")
            self.slideshow_chamber_preview.set_orientation(step.alpha, step.theta, reference=reference)
        else:
            self.slideshow_chamber_preview.show_placeholder(
                f"No wafer motion for this step ({step.category}).")

    def _on_slideshow_prev(self):
        if self._slideshow_steps:
            self._slideshow_index = max(0, self._slideshow_index - 1)
            self._slideshow_render_step()

    def _on_slideshow_next(self):
        if self._slideshow_steps:
            self._slideshow_index = min(len(self._slideshow_steps) - 1, self._slideshow_index + 1)
            self._slideshow_render_step()

    def _on_slideshow_list_clicked(self, item):
        row = self.slideshow_list.row(item)
        if 0 <= row < len(self._slideshow_steps):
            self._slideshow_index = row
            self._slideshow_render_step()

    # ------------------------------------------------------------------
    # Measure Resistance -- Measure Resistance (voice-driven RT resistance capture)
    # ------------------------------------------------------------------
    # Cell-state colors -- dark-theme equivalents of what a spreadsheet
    # would show as light yellow/green/red highlighting, since this
    # table is styled dark to match the rest of the app rather than
    # staying the QTableWidget default white.
    _MEAS_CURRENT_BG = QColor("#2a3a52")
    _MEAS_CURRENT_FG = QColor(ACCENT_COLOR)
    _MEAS_DONE_BG = QColor("#1f3a2e")
    _MEAS_DONE_FG = QColor("#8fd694")
    _MEAS_SPECIAL_BG = QColor("#3a2020")
    _MEAS_SPECIAL_FG = QColor(WARN_COLOR)
    _MEAS_UNIT_SCALE_FROM_KOHM = {"kOhm": 1.0, "Ohm": 1000.0, "MOhm": 0.001}

    def _build_measurement_tab(self) -> QWidget:
        """Measure Resistance -- voice-driven room-temperature
        resistance capture for a junction array, feeding the
        Ambegaokar-Baratoff validation step. Originally built and
        verified as a fully standalone PySide6 prototype (its own
        QMainWindow, zero dependency on this file) specifically so the
        risky, only-testable-on-real-hardware part -- an actual
        microphone plus a downloaded Whisper/Vosk model -- could be
        shaken out on the user's own machine before committing to
        wiring it into the real app. Confirmed working end to end on
        real hardware (Whisper, first try) before this integration.
        This method is that same logic and layout translated into a
        page for main_stack: same scan_pattern.py/resistance_parser.py
        modules, same _MeasurementVoiceSignals bridge pattern as
        _AIWorkerSignals above, same card/toolbar/palette conventions
        Simulate Design (Simulate Design) already established via
        self._sim_card and its own sim_toolbar, reused here rather than
        re-invented -- so this reads as a continuation of the existing
        app, not a bolted-on fourth product."""
        meas_toolbar = QToolBar("Measurement Tools")
        meas_toolbar.setMovable(False)
        self._themed(meas_toolbar, lambda: f"QToolBar {{ background-color: {PANEL_COLOR}; border: none; spacing: 6px; padding: 4px 8px; }}")
        self.addToolBar(meas_toolbar)
        self.meas_toolbar = meas_toolbar  # hidden/shown alongside main_toolbar/sim_toolbar in _on_nav_changed

        def _group_label(text):
            lbl = QLabel(text)
            self._themed(lbl, lambda: f"color: {DIM_COLOR}; font-size: 7.5pt; letter-spacing: 1px;")
            lbl.setAlignment(Qt.AlignVCenter)
            return lbl

        def _pill(label, accent=ACCENT_COLOR, checkable=False):
            # Same rounded, accent-highlighted-when-checked style as
            # Simulate Design's own _pill_toggle -- copied rather than shared since
            # that one is a local closure inside _build_simulate_tab,
            # not a method on self.
            btn = QPushButton(label)
            btn.setCheckable(checkable)
            btn.setCursor(Qt.PointingHandCursor)
            btn.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Fixed)
            self._themed(btn, lambda: f"""
                QPushButton {{
                    background-color: #2a2c38; color: #cfd2e0; border: 1px solid #3a3d4d;
                    border-radius: 12px; padding: 5px 14px; font-size: 8pt;
                }}
                QPushButton:checked {{
                    background-color: {accent}22; color: {accent}; border: 1px solid {accent};
                }}
                QPushButton:hover {{ border: 1px solid {ACCENT_COLOR}; }}
            """)
            return btn

        meas_toolbar.addWidget(_group_label("ARRAY:"))
        self.meas_rows_spin = QSpinBox()
        self.meas_rows_spin.setRange(1, 100)
        self.meas_rows_spin.setValue(10)
        self.meas_rows_spin.setPrefix("R ")
        self.meas_rows_spin.setFixedWidth(70)
        meas_toolbar.addWidget(self.meas_rows_spin)
        self.meas_cols_spin = QSpinBox()
        self.meas_cols_spin.setRange(1, 100)
        self.meas_cols_spin.setValue(10)
        self.meas_cols_spin.setPrefix("C ")
        self.meas_cols_spin.setFixedWidth(70)
        meas_toolbar.addWidget(self.meas_cols_spin)

        meas_toolbar.addSeparator()
        meas_toolbar.addWidget(_group_label("PATTERN:"))
        self.meas_pattern_combo = QComboBox()
        for key in PATTERNS:
            self.meas_pattern_combo.addItem(PATTERN_LABELS[key], userData=key)
        self.meas_pattern_combo.addItem("Custom (click cells in order)", userData="custom")
        self.meas_pattern_combo.setMinimumWidth(260)
        meas_toolbar.addWidget(self.meas_pattern_combo)

        build_btn = _pill("Build table / restart scan", accent="#7fc8e6")
        build_btn.clicked.connect(self._on_meas_build_table)
        meas_toolbar.addWidget(build_btn)

        meas_toolbar.addSeparator()
        meas_toolbar.addWidget(_group_label("ENGINE:"))
        self.meas_engine_combo = QComboBox()
        self.meas_engine_combo.addItem("Whisper (recommended)", userData="whisper")
        self.meas_engine_combo.addItem("Vosk (fast, constrained grammar)", userData="vosk")
        meas_toolbar.addWidget(self.meas_engine_combo)

        self.meas_listen_btn = _pill("Start listening", accent="#8fd694", checkable=True)
        self.meas_listen_btn.clicked.connect(self._on_meas_toggle_listening)
        meas_toolbar.addWidget(self.meas_listen_btn)

        meas_toolbar.addSeparator()
        undo_btn = _pill("Undo", accent=WARN_COLOR)
        undo_btn.clicked.connect(self._on_meas_undo)
        meas_toolbar.addWidget(undo_btn)
        skip_btn = _pill("Skip", accent=DIM_COLOR)
        skip_btn.clicked.connect(self._on_meas_skip)
        meas_toolbar.addWidget(skip_btn)

        # --- page content ---
        outer = QWidget()
        self._themed(outer, lambda: f"background-color: {BG_COLOR};")
        layout = QVBoxLayout(outer)
        layout.setContentsMargins(16, 16, 16, 16)
        layout.setSpacing(12)

        header_row = QHBoxLayout()
        header = QLabel("MEASURE RESISTANCE")
        self._themed(header, lambda: f"color: {TEXT_COLOR}; font-weight: bold; font-size: 14pt; letter-spacing: 1px;")
        header_row.addWidget(header)
        header_row.addStretch()
        self.meas_status_pill = QLabel("Build a table to begin.")
        self._themed(self.meas_status_pill, lambda: f"color: {ACCENT_COLOR}; font-size: 9pt; background-color: {PANEL_COLOR}; "
            f"border-radius: 6px; padding: 6px 12px;")
        self.meas_status_pill.setAlignment(Qt.AlignCenter)
        self.meas_status_pill.setSizePolicy(QSizePolicy.Maximum, QSizePolicy.Fixed)
        self.meas_status_pill.setMinimumWidth(0)
        header_row.addWidget(self.meas_status_pill)
        layout.addLayout(header_row, stretch=0)

        body = QHBoxLayout()
        body.setSpacing(12)

        self.meas_table = QTableWidget()
        self._themed(self.meas_table, lambda: f"""
            QTableWidget {{
                background-color: {PANEL_COLOR}; color: {TEXT_COLOR};
                gridline-color: #2e3040; border: 1px solid #2e3040;
            }}
            QHeaderView::section {{
                background-color: #23242e; color: {TEXT_COLOR};
                padding: 4px; border: 1px solid #2e3040; font-weight: bold;
            }}
        """)
        self.meas_table.cellClicked.connect(self._on_meas_cell_clicked)
        self.meas_table.horizontalHeader().setSectionResizeMode(QHeaderView.Stretch)
        self.meas_table.verticalHeader().setSectionResizeMode(QHeaderView.Stretch)
        self.meas_table.verticalHeader().setMinimumSectionSize(22)
        body.addWidget(self.meas_table, stretch=1)

        sidebar = QVBoxLayout()
        sidebar.setSpacing(10)

        progress_card, progress_content = self._sim_card("Scan Progress", "#7fc8e6", collapsed=False)
        self.meas_progress_label = QLabel("No active scan.")
        self.meas_progress_label.setWordWrap(True)
        self._themed(self.meas_progress_label, lambda: f"color: {TEXT_COLOR};")
        progress_content.addWidget(self.meas_progress_label)
        sidebar.addWidget(progress_card)

        export_card, export_content = self._sim_card("Export", "#8fd694", collapsed=False)
        exp_name_row = QHBoxLayout()
        exp_name_row.addWidget(_group_label("EXPERIMENT:"))
        self.meas_experiment_name_edit = QLineEdit()
        self.meas_experiment_name_edit.setPlaceholderText("e.g. Run 1")
        exp_name_row.addWidget(self.meas_experiment_name_edit)
        export_content.addLayout(exp_name_row)

        unit_row = QHBoxLayout()
        unit_row.addWidget(_group_label("UNITS:"))
        self.meas_unit_combo = QComboBox()
        for u in self._MEAS_UNIT_SCALE_FROM_KOHM:
            self.meas_unit_combo.addItem(u)
        unit_row.addWidget(self.meas_unit_combo)
        export_content.addLayout(unit_row)

        export_btn = _pill("Export table to CSV", accent="#8fd694")
        export_btn.clicked.connect(self._on_meas_export)
        export_content.addWidget(export_btn)
        sidebar.addWidget(export_card)

        log_card, log_content = self._sim_card("Transcript / Event Log", "#ffb454", collapsed=False)
        self.meas_log = QTextEdit()
        self.meas_log.setReadOnly(True)
        self.meas_log.setMinimumHeight(220)
        self._themed(self.meas_log, lambda: f"background-color: {PANEL_COLOR}; color: {TEXT_COLOR}; "
                                    f"border: 1px solid #2e3040; border-radius: 6px;")
        log_content.addWidget(self.meas_log)
        sidebar.addWidget(log_card, stretch=1)

        sidebar_widget = QWidget()
        sidebar_widget.setLayout(sidebar)
        sidebar_widget.setFixedWidth(300)
        body.addWidget(sidebar_widget)

        layout.addLayout(body, stretch=1)

        # runtime state
        self.meas_scan_state = None
        self.meas_engine = None
        self.meas_segmenter_thread = None
        self._meas_listening = False
        self._meas_custom_click_mode = False
        self._meas_custom_order = []
        self.meas_voice_signals = _MeasurementVoiceSignals()
        self.meas_voice_signals.utterance_ready.connect(self._on_meas_utterance)
        self.meas_voice_signals.engine_error.connect(self._on_meas_engine_error)

        return outer

    def _on_meas_build_table(self):
        rows = self.meas_rows_spin.value()
        cols = self.meas_cols_spin.value()
        pattern_key = self.meas_pattern_combo.currentData()

        self.meas_table.setRowCount(rows)
        self.meas_table.setColumnCount(cols)
        self.meas_table.setHorizontalHeaderLabels([f"Column {c}" for c in range(1, cols + 1)])
        self.meas_table.setVerticalHeaderLabels([f"{r}" for r in range(1, rows + 1)])
        for r in range(rows):
            for c in range(cols):
                item = QTableWidgetItem("")
                item.setTextAlignment(Qt.AlignCenter)
                self.meas_table.setItem(r, c, item)

        if pattern_key == "custom":
            self._meas_custom_click_mode = True
            self._meas_custom_order = []
            self.meas_scan_state = None
            self._meas_log("Custom pattern selected: click cells in the table, in the order "
                       "you intend to measure them. Voice capture starts once every cell "
                       "has been picked.")
            self.meas_status_pill.setText("Custom pattern: click cells in your measurement order.")
            self.meas_progress_label.setText("Recording custom click order...")
        else:
            self._meas_custom_click_mode = False
            self.meas_scan_state = ScanState.from_pattern(rows, cols, pattern_key)
            self._meas_log(f"Table built: {rows}x{cols}, pattern = {PATTERN_LABELS[pattern_key]}")
            self._meas_highlight_current()

    def _meas_highlight_current(self):
        if not self.meas_scan_state or self.meas_scan_state.current is None:
            msg = "Scan complete." if self.meas_scan_state else ""
            self.meas_status_pill.setText(msg)
            self.meas_progress_label.setText(msg or "No active scan.")
            return
        row, col = self.meas_scan_state.current
        item = self.meas_table.item(row - 1, col - 1)
        if item:
            item.setBackground(self._MEAS_CURRENT_BG)
            item.setForeground(self._MEAS_CURRENT_FG)
        done, total = self.meas_scan_state.progress
        self.meas_status_pill.setText(f"Next: row {row}, col {col}  ({done}/{total})")
        self.meas_progress_label.setText(f"Next cell: row {row}, column {col}\n\n{done} of {total} measured.")
        self.meas_table.scrollToItem(item)

    def _meas_commit_value(self, row: int, col: int, parsed):
        item = self.meas_table.item(row - 1, col - 1)
        if item is None:
            return
        if parsed.kind == "value":
            item.setText(f"{parsed.value_kohm:g}")
            item.setBackground(self._MEAS_DONE_BG)
            item.setForeground(self._MEAS_DONE_FG)
        elif parsed.kind == "special":
            item.setText(parsed.special)
            item.setBackground(self._MEAS_SPECIAL_BG)
            item.setForeground(self._MEAS_SPECIAL_FG)

    def _on_meas_cell_clicked(self, row: int, col: int):
        if self._meas_custom_click_mode:
            coord = (row + 1, col + 1)
            if coord not in self._meas_custom_order:
                self._meas_custom_order.append(coord)
                item = self.meas_table.item(row, col)
                item.setBackground(self._MEAS_CURRENT_BG)
                item.setForeground(self._MEAS_CURRENT_FG)
                self._meas_log(f"Custom order: added ({coord[0]}, {coord[1]}) "
                          f"-- {len(self._meas_custom_order)} cell(s) so far.")
                if len(self._meas_custom_order) == self.meas_table.rowCount() * self.meas_table.columnCount():
                    self.meas_scan_state = ScanState(order=list(self._meas_custom_order))
                    self._meas_custom_click_mode = False
                    self._meas_log("Custom order complete -- scan is now active.")
                    self._meas_highlight_current()
        elif self.meas_scan_state is not None:
            self.meas_scan_state.jump_to(row + 1, col + 1)
            self._meas_highlight_current()

    def _on_meas_undo(self):
        if self.meas_scan_state:
            self.meas_scan_state.undo()
            self._meas_highlight_current()
            self._meas_log("Undo -> back to previous cell.")

    def _on_meas_skip(self):
        if self.meas_scan_state:
            self.meas_scan_state.skip()
            self._meas_highlight_current()
            self._meas_log("Skipped current cell.")

    def _on_meas_toggle_listening(self, checked: bool):
        if checked:
            if self.meas_scan_state is None:
                self.meas_listen_btn.setChecked(False)
                QMessageBox.warning(self, "No table", "Build a table first.")
                return
            self._start_meas_listening()
        else:
            self._stop_meas_listening()

    def _start_meas_listening(self):
        engine_key = self.meas_engine_combo.currentData()
        try:
            if engine_key == "whisper":
                from voice_engine import WhisperEngine
                self._meas_log("Loading Whisper model (first run downloads weights -- needs network)...")
                self.meas_engine = WhisperEngine()
            else:
                from voice_engine import VoskEngine
                self._meas_log("Loading Vosk model (point this at a downloaded model directory -- "
                          "edit VoskEngine(model_path=...) in _start_meas_listening once you've picked one)...")
                self.meas_engine = VoskEngine(model_path="./vosk-model-small-en-us")
        except Exception as e:
            self._on_meas_engine_error(f"Could not load engine: {e}")
            self.meas_listen_btn.setChecked(False)
            return

        self.meas_listen_btn.setText("Stop listening")
        self._meas_listening = True
        self.meas_segmenter_thread = threading.Thread(target=self._meas_listen_loop, daemon=True)
        self.meas_segmenter_thread.start()
        self._meas_log(f"Listening started ({self.meas_engine_combo.currentText()}).")

    def _stop_meas_listening(self):
        self._meas_listening = False
        self.meas_listen_btn.setText("Start listening")
        self._meas_log("Listening stopped.")

    def _meas_listen_loop(self):
        # Runs on a background thread -- must not touch any QWidget
        # directly; everything crosses back to the main thread via
        # meas_voice_signals (same cross-thread pattern _AIWorkerSignals
        # already uses for the Ollama calls elsewhere in this file).
        from voice_engine import SilenceSegmenter
        segmenter = SilenceSegmenter()
        try:
            for utterance in segmenter.listen():
                if not self._meas_listening:
                    segmenter.stop()
                    break
                text = self.meas_engine.transcribe(utterance)
                self.meas_voice_signals.utterance_ready.emit(text)
        except Exception as e:
            self.meas_voice_signals.engine_error.emit(str(e))

    def _on_meas_utterance(self, text: str):
        self._meas_log(f"heard: {text!r}")
        parsed = parse_resistance_utterance(text)
        if parsed is None:
            self._meas_log("  (not recognized as a measurement, special outcome, or command -- ignored)")
            return

        if parsed.kind == "command":
            if parsed.command == "undo":
                self._on_meas_undo()
            elif parsed.command == "skip":
                self._on_meas_skip()
            elif parsed.command == "advance" and self.meas_scan_state:
                self.meas_scan_state.advance()
                self._meas_highlight_current()
            elif parsed.command in ("stop", "pause"):
                self.meas_listen_btn.setChecked(False)
                self._stop_meas_listening()
            return

        if self.meas_scan_state is None or self.meas_scan_state.current is None:
            self._meas_log("  (no active cell -- ignored)")
            return
        row, col = self.meas_scan_state.current
        self._meas_commit_value(row, col, parsed)
        self._meas_log(f"  -> committed to row {row}, column {col}")
        self.meas_scan_state.advance()
        self._meas_highlight_current()

    def _on_meas_engine_error(self, message: str):
        self._meas_log(f"ERROR: {message}")

    def _meas_log(self, message: str):
        self.meas_log.append(message)

    def _on_meas_export(self):
        if self.meas_table.rowCount() == 0:
            return
        experiment_name = self.meas_experiment_name_edit.text().strip() or "(unnamed experiment)"
        unit = self.meas_unit_combo.currentText()
        scale = self._MEAS_UNIT_SCALE_FROM_KOHM[unit]
        pattern_label = self.meas_pattern_combo.currentText()
        timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M")

        default_name = f"{self.meas_experiment_name_edit.text().strip() or 'junction_resistances'}.csv"
        path, _ = QFileDialog.getSaveFileName(self, "Export CSV", default_name, "CSV (*.csv)")
        if not path:
            return

        with open(path, "w", newline="") as f:
            writer = csv_module.writer(f)
            # Header block: experiment identity + provenance, matching the
            # spirit of a typical lab reference sheet (an experiment tag
            # in the corner, a "Junction Resistances (unit)" title row) --
            # plain CSV can't merge/color cells the way Excel does, so this
            # is the same information as plain rows instead.
            writer.writerow(["Experiment:", experiment_name])
            writer.writerow(["Pattern:", pattern_label])
            writer.writerow(["Exported:", timestamp])
            writer.writerow([])
            writer.writerow([f"Junction Resistances ({unit})"])
            writer.writerow([""] + [f"Column {c}" for c in range(1, self.meas_table.columnCount() + 1)])
            for r in range(self.meas_table.rowCount()):
                row_vals = []
                for c in range(self.meas_table.columnCount()):
                    item = self.meas_table.item(r, c)
                    text = item.text() if item else ""
                    try:
                        row_vals.append(f"{float(text) * scale:g}")
                    except ValueError:
                        row_vals.append(text)
                writer.writerow([r + 1] + row_vals)
        self._meas_log(f"Exported to {path} (units: {unit}, experiment: {experiment_name})")

    # ================================================================
    # Interpret Results -- the final pipeline step: room-
    # temperature resistance vs. inverse junction area (Ambegaokar-
    # Baratoff validation), built on top of resistance_interpretation.py
    # -- a direct port of a previously verified filtering+regression
    # analysis method, not a reimplementation from scratch. Three subtabs: Main Plot
    # (load data, tune filter thresholds, see/save the plot), Area
    # Adjustment (per-row nominal LW1/LW2, an SEM/experimental offset --
    # global or per-row -- or a direct per-row area override), and
    # Compare Experiments (save/load named processed datasets and
    # overlay any number of them at once).
    # ================================================================

    def _interp_pill(self, label, accent=ACCENT_COLOR, checkable=False):
        """Same rounded accent-highlighted-when-checked button style
        Simulate Design/Measure Resistance already use -- their own local closures aren't reachable
        from here, so this is this tab's own copy (same convention
        those tabs' own docstrings already established: copied rather
        than shared across tabs, reused freely WITHIN this one tab's
        three subtab builders)."""
        btn = QPushButton(label)
        btn.setCheckable(checkable)
        btn.setCursor(Qt.PointingHandCursor)
        self._themed(btn, lambda: f"""
            QPushButton {{
                background-color: #2a2c38; color: #cfd2e0; border: 1px solid #3a3d4d;
                border-radius: 10px; padding: 6px 12px; font-size: 8pt;
            }}
            QPushButton:checked {{
                background-color: {accent}22; color: {accent}; border: 1px solid {accent};
            }}
            QPushButton:hover {{ border: 1px solid {ACCENT_COLOR}; }}
        """)
        return btn

    def _interp_safe_float(self, s, default=0.0):
        try:
            return float(s)
        except (TypeError, ValueError):
            return default

    def _interp_float_or(self, edit, fallback):
        try:
            return float(edit.text())
        except (ValueError, AttributeError):
            return fallback

    def _refresh_interp_tc_default(self):
        """Seed Interpret Results' T_c field from TC_KELVIN_BY_METAL[deposition
        metal], since the critical temperature should track whichever metal
        is actually being deposited. Called whenever the deposition metal
        changes and whenever this tab becomes visible, so it stays in sync
        with whatever design is active; a no-op once the user has
        hand-edited the field (self._interp_tc_user_edited), matching the
        same seed-don't-overwrite rule used for the mill-duration-by-metal
        guidance note.

        This now reads the Recipe Parameters panel's own metal combo (the
        sole live metal-type widget), following the removal of the old
        Settings > Process Parameters metal-type control that this
        previously depended on."""
        if getattr(self, "_interp_tc_user_edited", False):
            return
        if not hasattr(self, "interp_tc_edit") or not hasattr(self, "recipe_panel_metal_combo"):
            return
        metal = self.recipe_panel_metal_combo.currentText()
        tc = TC_KELVIN_BY_METAL.get(metal)
        if tc is not None:
            self.interp_tc_edit.setText(f"{tc:g}")

    def _build_interpretation_tab(self) -> QWidget:
        outer = QWidget()
        self._themed(outer, lambda: f"background-color: {BG_COLOR};")
        layout = QVBoxLayout(outer)
        layout.setContentsMargins(16, 16, 16, 16)
        layout.setSpacing(10)

        header = QLabel("INTERPRET RESULTS")
        self._themed(header, lambda: f"color: {TEXT_COLOR}; font-weight: bold; font-size: 14pt; letter-spacing: 1px;")
        layout.addWidget(header)
        subtitle = QLabel("Room-temperature resistance vs. inverse junction area -- the Ambegaokar-Baratoff validation step.")
        subtitle.setWordWrap(True)
        self._themed(subtitle, lambda: f"color: {DIM_COLOR}; font-size: 8.5pt;")
        layout.addWidget(subtitle)

        sub = QTabWidget()
        layout.addWidget(sub, stretch=1)

        self._interp_raw_rows = []               # list[list[raw cell values]], most recently loaded
        self._interp_last_dataset = None          # ia.InterpretationDataset of the last successful recompute
        self._interp_last_result = None           # that dataset's .process() output
        self._interp_last_compare_results = None  # last "Plot Checked" results, for theme-refresh redraw
        self._interp_datasets = []                # list[ia.InterpretationDataset] held for comparison
        self._interp_area_table_updating = False  # guards against itemChanged recursion during bulk fills
        self._interp_palette = [
            ("#7fb8ff", "#ff8f6b"), ("#8fd694", "#ffb454"), ("#e88fd6", "#8fd6e8"),
            ("#ffd166", "#ef476f"), ("#b8b8ff", "#06d6a0"), ("#ffa3a3", "#7fb8ff"),
        ]

        sub.addTab(self._build_interp_main_plot_subtab(), "Main Plot")
        sub.addTab(self._build_interp_area_subtab(), "Area Adjustment")
        sub.addTab(self._build_interp_compare_subtab(), "Compare Experiments")
        self._interp_subtabs = sub
        return outer

    def _build_interp_main_plot_subtab(self) -> QWidget:
        page = QWidget()
        outer_layout = QHBoxLayout(page)
        outer_layout.setSpacing(10)

        sidebar = QWidget()
        sb_layout = QVBoxLayout(sidebar)
        sb_layout.setSpacing(10)

        source_card, source_content = self._sim_card("Data Source", "#7fc8e6", collapsed=False)
        name_row = QFormLayout()
        self.interp_dataset_name_edit = QLineEdit()
        self.interp_dataset_name_edit.setPlaceholderText("e.g. Run 1")
        name_row.addRow("Dataset name:", self.interp_dataset_name_edit)
        source_content.addLayout(name_row)
        load_meas_btn = self._interp_pill("Load from Measure Resistance tab", accent="#7fc8e6")
        load_meas_btn.clicked.connect(self._on_interp_load_from_meas_tab)
        source_content.addWidget(load_meas_btn)
        load_csv_btn = self._interp_pill("Import CSV...", accent="#7fc8e6")
        load_csv_btn.clicked.connect(self._on_interp_load_csv)
        source_content.addWidget(load_csv_btn)
        self.interp_source_label = QLabel("No data loaded yet.")
        self.interp_source_label.setWordWrap(True)
        self._themed(self.interp_source_label, lambda: f"color: {DIM_COLOR}; font-size: 8pt;")
        source_content.addWidget(self.interp_source_label)
        sb_layout.addWidget(source_card)

        settings_card, settings_content = self._sim_card("Analysis Settings", "#ffb454", collapsed=False)
        form = QFormLayout()
        self.interp_rbase_edit = QLineEdit("19.65")
        form.addRow("Probe baseline R (kΩ):", self.interp_rbase_edit)
        self.interp_short_thresh_edit = QLineEdit("2.0")
        form.addRow("Short threshold (kΩ):", self.interp_short_thresh_edit)
        self.interp_open_thresh_edit = QLineEdit("500.0")
        form.addRow("Open threshold (kΩ):", self.interp_open_thresh_edit)
        self.interp_z_thresh_edit = QLineEdit("3.0")
        form.addRow("Z-score outlier limit:", self.interp_z_thresh_edit)
        self.interp_tc_edit = QLineEdit("1.2")
        # This used to be a bare
        # Aluminum-only default (1.2 K) no matter which metal the design
        # actually deposits. _refresh_interp_tc_default (called just below,
        # and again on every deposition-metal change / whenever this tab is
        # shown) now seeds it from TC_KELVIN_BY_METAL[metal_type] instead --
        # but only until the user actually edits the field by hand, tracked
        # via self._interp_tc_user_edited, so a manually-entered/measured
        # T_c is never silently clobbered (same "seed, don't force-overwrite"
        # rule used for the Settings mill-duration guidance).
        self.interp_tc_edit.textEdited.connect(lambda _t: setattr(self, "_interp_tc_user_edited", True))
        form.addRow("T_c (K, for J_c):", self.interp_tc_edit)
        settings_content.addLayout(form)
        self.interp_auto_offset_check = QCheckBox("Auto-fit offset (maximize R²) instead\nof Area Adjustment values")
        settings_content.addWidget(self.interp_auto_offset_check)
        sb_layout.addWidget(settings_card)

        recompute_btn = self._interp_pill("▶ Recompute & Plot", accent=ACCENT_COLOR)
        recompute_btn.clicked.connect(self._on_interp_recompute)
        sb_layout.addWidget(recompute_btn)
        save_plot_btn = self._interp_pill("Save Plot...", accent="#8fd694")
        save_plot_btn.clicked.connect(self._on_interp_save_plot)
        sb_layout.addWidget(save_plot_btn)
        add_compare_btn = self._interp_pill("Add to Compare List", accent=ACCENT_COLOR)
        add_compare_btn.clicked.connect(self._on_interp_add_current_to_compare)
        sb_layout.addWidget(add_compare_btn)

        audit_card, audit_content = self._sim_card("Filtering Audit Log", "#ff8f6b", collapsed=True)
        self.interp_audit_log = QTextEdit()
        self.interp_audit_log.setReadOnly(True)
        self.interp_audit_log.setMinimumHeight(160)
        self._themed(self.interp_audit_log, lambda: f"background-color: {PANEL_COLOR}; color: {TEXT_COLOR}; "
                     f"border: 1px solid #2e3040; font-family: monospace; font-size: 7.5pt;")
        audit_content.addWidget(self.interp_audit_log)
        sb_layout.addWidget(audit_card)
        sb_layout.addStretch()

        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setWidget(sidebar)
        scroll.setFixedWidth(320)
        scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        outer_layout.addWidget(scroll)

        right = QWidget()
        right_layout = QVBoxLayout(right)
        right_layout.setContentsMargins(0, 0, 0, 0)
        self.interp_fig = Figure(figsize=(7, 7), dpi=100, facecolor=BG_COLOR)
        self.interp_ax = self.interp_fig.add_subplot(1, 1, 1)
        self.interp_canvas = FigureCanvasQTAgg(self.interp_fig)
        self.interp_canvas.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
        right_layout.addWidget(self.interp_canvas, stretch=1)
        outer_layout.addWidget(right, stretch=1)

        self._interp_draw_placeholder(self.interp_ax)
        return page

