    # ---------------------------------------------------------- chamber_plotting

    def _interp_draw_placeholder(self, ax):
        ax.clear()
        ax.set_facecolor(BG_COLOR)
        ax.text(0.5, 0.5, "Load measurement data, then click\n\"Recompute & Plot\" to see the "
                "resistance vs.\ninverse area plot here.", ha="center", va="center",
                color=DIM_COLOR, fontsize=11, transform=ax.transAxes)
        ax.set_xticks([])
        ax.set_yticks([])
        for spine in ax.spines.values():
            spine.set_color(DIM_COLOR)

    def _interp_draw_main_plot(self, dataset, result):
        ax = self.interp_ax
        ax.clear()
        ax.set_facecolor(BG_COLOR)
        fit = result["fit"]
        inverse_area = result["areas_um2"] ** -1

        for inv_A, clean_row in zip(inverse_area, result["clean_rows"]):
            if len(clean_row) > 0:
                ax.scatter([inv_A] * len(clean_row), clean_row, color=ACCENT_COLOR, alpha=0.3, s=30, zorder=2)
        ax.errorbar(fit["x_reg"], fit["y_reg"], yerr=fit["y_stds_reg"], fmt="o", color=ACCENT_COLOR,
                    ecolor=ACCENT_COLOR, elinewidth=1.5, capsize=4, ms=8,
                    label=r"Filtered Means $\pm\,\sigma$", zorder=3)
        x_range = np.linspace(min(fit["x_reg"]), max(fit["x_reg"]), 100)
        y_range = fit["a0"] + fit["a1"] * x_range
        ax.plot(x_range, y_range, color="#ff8f6b", linestyle="-", linewidth=2.5, label="Linear Fit", zorder=1)

        stats_text = (
            f"y-intercept: {fit['a0']:.2f} k$\\Omega$\n"
            f"Slope: {fit['a1']:.2f} k$\\Omega\\cdot\\mu m^2$\n"
            f"Std Error: {fit['standard_error']:.4f}\n"
            f"$R^2$ Value: {fit['r2']:.4f}"
        )
        ax.text(0.05, 0.95, stats_text, transform=ax.transAxes, fontsize=10, verticalalignment="top",
                color=TEXT_COLOR, bbox=dict(boxstyle="round,pad=0.5", facecolor=PANEL_COLOR, alpha=0.9,
                                             edgecolor=DIM_COLOR))
        jc_text = (r"$\mathbf{Est.\ Critical\ Current\ Density\ (J_c):}$" + "\n" +
                   f"{fit['J_c_A_cm2']:,.1f} A/cm$^2$  ({fit['J_c_uA_um2']:.3f} µA/µm²)")
        ax.text(0.05, 0.68, jc_text, transform=ax.transAxes, fontsize=10, verticalalignment="top",
                color="#ffb454", bbox=dict(boxstyle="round,pad=0.5", facecolor="#2a2410", alpha=0.95,
                                            edgecolor="#ffb454"))
        summary_text = (f"Opens: {result['open_count']}   Shorts: {result['shorted_count']}   "
                         f"Outliers: {result['outlier_count']}")
        # Top-right, deliberately NOT bottom-right -- the legend already
        # lives there (loc="lower right" below), and the two boxes
        # visibly overlapped when both were bottom-right.
        ax.text(0.95, 0.95, summary_text, transform=ax.transAxes, fontsize=9, verticalalignment="top",
                horizontalalignment="right", color=DIM_COLOR,
                bbox=dict(boxstyle="round,pad=0.4", facecolor=PANEL_COLOR, alpha=0.9, edgecolor=DIM_COLOR))

        ax.set_title(f"{dataset.name}: JJ Normal-State Resistance vs. Inverse Area",
                     fontsize=13, color=TEXT_COLOR, fontweight="bold")
        ax.set_xlabel(r"Inverse Junction Area, $1/A$ ($\mu m^{-2}$)", color=TEXT_COLOR)
        ax.set_ylabel(r"Junction Resistance, $R_n$ (k$\Omega$)", color=TEXT_COLOR)
        ax.tick_params(colors=DIM_COLOR)
        for spine in ax.spines.values():
            spine.set_color(DIM_COLOR)
        ax.grid(True, linestyle="--", alpha=0.3, color=DIM_COLOR)
        legend = ax.legend(loc="lower right", fontsize=9, framealpha=0.9)
        legend.get_frame().set_facecolor(PANEL_COLOR)
        legend.get_frame().set_edgecolor(DIM_COLOR)
        for text in legend.get_texts():
            text.set_color(TEXT_COLOR)
        try:
            self.interp_fig.tight_layout()
        except Exception:
            pass
        self.interp_canvas.draw_idle()

    # ------------------------------------------------------------ handlers

    def _on_interp_load_from_meas_tab(self):
        if not hasattr(self, "meas_table") or self.meas_table.rowCount() == 0:
            QMessageBox.information(self, "No measurement data",
                                     "The Measure Resistance table is empty -- fill it in or import a CSV first.")
            return
        raw_rows = []
        for r in range(self.meas_table.rowCount()):
            row_vals = []
            for c in range(self.meas_table.columnCount()):
                item = self.meas_table.item(r, c)
                text = item.text().strip() if item else ""
                row_vals.append(text if text else 0)  # blank cell -> 0 -> classified as Open Circuit
            raw_rows.append(row_vals)
        self._interp_raw_rows = raw_rows
        experiment = self.meas_experiment_name_edit.text().strip() or "(unnamed experiment)"
        self.interp_dataset_name_edit.setText(experiment)
        self.interp_source_label.setText(
            f"Measure Resistance tab -- \"{experiment}\" ({len(raw_rows)}x{self.meas_table.columnCount()})")
        self._on_interp_sync_area_rows()

    def _on_interp_load_csv(self):
        path, _ = QFileDialog.getOpenFileName(self, "Import Measurement CSV", "", "CSV (*.csv)")
        if not path:
            return
        try:
            meta, raw_rows = ia.parse_measurement_csv(path)
        except Exception as e:
            QMessageBox.warning(self, "Could not read CSV", str(e))
            return
        self._interp_raw_rows = raw_rows
        name = meta.get("experiment") or os.path.splitext(os.path.basename(path))[0]
        self.interp_dataset_name_edit.setText(name)
        self.interp_source_label.setText(
            f"CSV: {os.path.basename(path)} -- \"{name}\" ({len(raw_rows)} rows, unit was {meta.get('unit')})")
        self._on_interp_sync_area_rows()

    def _interp_read_area_table(self):
        rows = []
        for r in range(self.interp_area_table.rowCount()):
            def cell(c):
                it = self.interp_area_table.item(r, c)
                return it.text().strip() if it else ""
            rows.append({"lw1": cell(1), "lw2": cell(2), "offset": cell(3), "area_override": cell(4)})
        return rows

    def _on_interp_sync_area_rows(self):
        n = len(self._interp_raw_rows)
        old_data = self._interp_read_area_table()
        self._interp_area_table_updating = True
        try:
            self.interp_area_table.setRowCount(n)
            for r in range(n):
                prev = old_data[r] if r < len(old_data) else {}
                row_item = QTableWidgetItem(f"Row {r + 1}")
                row_item.setFlags(row_item.flags() & ~Qt.ItemIsEditable)
                self.interp_area_table.setItem(r, 0, row_item)
                self.interp_area_table.setItem(r, 1, QTableWidgetItem(prev.get("lw1", "")))
                self.interp_area_table.setItem(r, 2, QTableWidgetItem(prev.get("lw2", "")))
                self.interp_area_table.setItem(r, 3, QTableWidgetItem(prev.get("offset", "")))
                self.interp_area_table.setItem(r, 4, QTableWidgetItem(prev.get("area_override", "")))
                for col in (5, 6):
                    it = QTableWidgetItem("")
                    it.setFlags(it.flags() & ~Qt.ItemIsEditable)
                    self.interp_area_table.setItem(r, col, it)
        finally:
            self._interp_area_table_updating = False
        self._on_interp_refresh_area_table_computed_cols()

    def _on_interp_area_table_changed(self, item):
        if self._interp_area_table_updating:
            return
        if item.column() in (1, 2, 3, 4):
            self._on_interp_refresh_area_table_computed_cols()

    def _on_interp_refresh_area_table_computed_cols(self):
        rows = self._interp_read_area_table()
        global_offset_nm = self._interp_float_or(self.interp_global_offset_edit, 0.0)
        self._interp_area_table_updating = True
        try:
            for r, row in enumerate(rows):
                lw1 = self._interp_safe_float(row["lw1"], 0.0)
                lw2 = self._interp_safe_float(row["lw2"], 0.0)
                offset_nm = self._interp_safe_float(row["offset"], None) if row["offset"] else global_offset_nm
                if offset_nm is None:
                    offset_nm = global_offset_nm
                offset_um = offset_nm / 1000.0
                override = row["area_override"]
                if override:
                    area = self._interp_safe_float(override, 0.0)
                else:
                    area = (lw1 + offset_um) * (lw2 + offset_um)
                area_text = f"{area:.5f}" if area > 0 else ""
                inv_text = f"{1.0 / area:.4f}" if area > 0 else ""
                self.interp_area_table.item(r, 5).setText(area_text)
                self.interp_area_table.item(r, 6).setText(inv_text)
        finally:
            self._interp_area_table_updating = False

    def _on_interp_apply_global_offset(self):
        global_offset_nm = self._interp_float_or(self.interp_global_offset_edit, 0.0)
        self._interp_area_table_updating = True
        try:
            for r in range(self.interp_area_table.rowCount()):
                self.interp_area_table.item(r, 3).setText(f"{global_offset_nm:g}")
        finally:
            self._interp_area_table_updating = False
        self._on_interp_refresh_area_table_computed_cols()

    def _on_interp_fill_ladder(self, which: int):
        edit = self.interp_lw1_ladder_edit if which == 1 else self.interp_lw2_ladder_edit
        col = 1 if which == 1 else 2
        text = edit.text().strip()
        if not text:
            return
        try:
            values = [float(v.strip()) for v in text.split(",") if v.strip()]
        except ValueError:
            QMessageBox.warning(self, "Couldn't parse ladder",
                                 "Enter comma-separated numbers, e.g. 0.08, 0.11, 0.14")
            return
        if not values:
            return
        n_rows = self.interp_area_table.rowCount()
        if n_rows == 0:
            QMessageBox.information(self, "No rows yet",
                                     "Load data on the Main Plot tab and click \"Sync Rows\" first.")
            return
        self._interp_area_table_updating = True
        try:
            for r in range(n_rows):
                v = values[r] if r < len(values) else values[-1]  # broadcast the last value if the
                                                                     # ladder is shorter than the row
                                                                     # count (e.g. one LW2 for all rows)
                self.interp_area_table.item(r, col).setText(f"{v:g}")
        finally:
            self._interp_area_table_updating = False
        self._on_interp_refresh_area_table_computed_cols()

    def _current_interp_dataset(self, name=None) -> "ia.InterpretationDataset":
        rows = self._interp_read_area_table()
        lw1_list, lw2_list, offset_list, override_list = [], [], [], []
        global_offset_nm = self._interp_float_or(self.interp_global_offset_edit, 0.0)
        for row in rows:
            lw1_list.append(self._interp_safe_float(row["lw1"], 0.0))
            lw2_list.append(self._interp_safe_float(row["lw2"], 0.0))
            row_offset_nm = self._interp_safe_float(row["offset"], None) if row["offset"] else global_offset_nm
            if row_offset_nm is None:
                row_offset_nm = global_offset_nm
            offset_list.append(row_offset_nm / 1000.0)
            override_list.append(row["area_override"])
        name = name or (self.interp_dataset_name_edit.text().strip() or "(unnamed dataset)")
        return ia.InterpretationDataset(
            name=name,
            raw_rows=list(self._interp_raw_rows),
            lw1_nominal_um=lw1_list,
            lw2_nominal_um=lw2_list,
            offset_um=offset_list,
            area_override_um2=override_list,
            r_base_kohm=self._interp_float_or(self.interp_rbase_edit, 19.65),
            short_threshold_kohm=self._interp_float_or(self.interp_short_thresh_edit, 2.0),
            open_threshold_kohm=self._interp_float_or(self.interp_open_thresh_edit, 500.0),
            z_threshold=self._interp_float_or(self.interp_z_thresh_edit, 3.0),
            T_c_kelvin=self._interp_float_or(self.interp_tc_edit, 1.2),
        )

    def _interp_fill_audit_log(self, result):
        lines = [
            f"Total removed: {len(result['dropped_log'])}  "
            f"(Opens: {result['open_count']}, Shorts: {result['shorted_count']}, "
            f"Z-Outliers: {result['outlier_count']})",
            "",
            f"{'Coord':<10}{'Row':<6}{'Col':<6}{'Raw':<14}Reason",
        ]
        for coord, r, c, val, reason in result["dropped_log"]:
            val_str = f"{val:.2f}" if isinstance(val, (int, float)) else str(val)
            lines.append(f"{coord:<10}R{r:<5}C{c:<5}{val_str:<14}{reason}")
        self.interp_audit_log.setPlainText("\n".join(lines))

    def _on_interp_recompute(self):
        if not self._interp_raw_rows:
            QMessageBox.information(self, "No data loaded",
                                     "Load data first (from the Measure Resistance tab, or an "
                                     "imported CSV) on the Main Plot tab.")
            return
        n_data_rows = len(self._interp_raw_rows)
        n_area_rows = self.interp_area_table.rowCount()
        if n_area_rows != n_data_rows:
            QMessageBox.warning(self, "Row count mismatch",
                                 f"The loaded data has {n_data_rows} rows but the Area Adjustment "
                                 f"table has {n_area_rows}. Go to Area Adjustment and click "
                                 f"\"Sync Rows from Loaded Data\".")
            return
        dataset = self._current_interp_dataset()
        if self.interp_auto_offset_check.isChecked():
            try:
                filt_only = ia.filter_and_regress(dataset.raw_rows, dataset.r_base_kohm,
                                                   dataset.short_threshold_kohm, dataset.open_threshold_kohm,
                                                   dataset.z_threshold)
                offset = ia.fit_optimal_offset_um(dataset.lw1_nominal_um, dataset.lw2_nominal_um,
                                                   filt_only["clean_rows"],
                                                   area_override_list=dataset.area_override_um2)
                dataset.offset_um = [offset] * len(dataset.offset_um)
            except Exception as e:
                QMessageBox.warning(self, "Auto-fit failed", f"Could not auto-fit an offset: {e}")
        result = dataset.process()
        if result["fit"] is None:
            QMessageBox.warning(self, "Not enough data",
                                 "Fewer than 2 rows have any surviving (non-open/short/outlier) "
                                 "measurements -- can't fit a line. Check your thresholds and the "
                                 "Area Adjustment table.")
            self._interp_last_result = None
            self._interp_fill_audit_log(result)
            return
        self._interp_last_dataset = dataset
        self._interp_last_result = result
        self._interp_draw_main_plot(dataset, result)
        self._interp_fill_audit_log(result)

    def _on_interp_save_plot(self):
        if self._interp_last_result is None:
            QMessageBox.information(self, "Nothing to save", "Click \"Recompute & Plot\" first.")
            return
        default_name = f"{self._interp_last_dataset.name}_Resistance_vs_Inverse_Area.png"
        path, _ = QFileDialog.getSaveFileName(self, "Save Plot", default_name, "PNG (*.png);;PDF (*.pdf)")
        if not path:
            return
        self.interp_fig.savefig(path, facecolor=BG_COLOR, dpi=300, bbox_inches="tight")
        QMessageBox.information(self, "Saved", f"Plot saved to {path}")

    def _on_interp_add_current_to_compare(self):
        if self._interp_last_result is None:
            QMessageBox.information(self, "Nothing to add", "Click \"Recompute & Plot\" first.")
            return
        self._interp_datasets.append(self._interp_last_dataset)
        self._interp_refresh_compare_list()

    def _interp_refresh_compare_list(self):
        self.interp_compare_list.clear()
        for ds in self._interp_datasets:
            item = QListWidgetItem(f"{ds.name}  ({ds.created_at})")
            item.setFlags(item.flags() | Qt.ItemIsUserCheckable)
            item.setCheckState(Qt.Checked)
            self.interp_compare_list.addItem(item)

    def _on_interp_compare_load_files(self):
        paths, _ = QFileDialog.getOpenFileNames(self, "Load Saved Dataset(s)", "", "JSON (*.json)")
        if not paths:
            return
        loaded_any = False
        for path in paths:
            try:
                self._interp_datasets.extend(ia.load_datasets(path))
                loaded_any = True
            except Exception as e:
                QMessageBox.warning(self, "Could not load", f"{path}:\n{e}")
        if loaded_any:
            self._interp_refresh_compare_list()

    def _on_interp_compare_remove_selected(self):
        rows = sorted({idx.row() for idx in self.interp_compare_list.selectedIndexes()}, reverse=True)
        for r in rows:
            del self._interp_datasets[r]
        self._interp_refresh_compare_list()

    def _on_interp_compare_save_checked(self):
        checked = [ds for i, ds in enumerate(self._interp_datasets)
                   if self.interp_compare_list.item(i).checkState() == Qt.Checked]
        if not checked:
            QMessageBox.information(self, "Nothing checked", "Check at least one dataset first.")
            return
        path, _ = QFileDialog.getSaveFileName(self, "Save Datasets", "junction_datasets.json", "JSON (*.json)")
        if not path:
            return
        ia.save_datasets(checked, path)
        QMessageBox.information(self, "Saved", f"{len(checked)} dataset(s) saved to {path}")

    def _on_interp_compare_plot(self):
        checked = [ds for i, ds in enumerate(self._interp_datasets)
                   if self.interp_compare_list.item(i).checkState() == Qt.Checked]
        if not checked:
            QMessageBox.information(self, "Nothing checked", "Check at least one dataset in the list first.")
            return
        results = []
        for ds in checked:
            res = ds.process()
            if res["fit"] is not None:
                results.append((ds, res))
        if not results:
            QMessageBox.warning(self, "Nothing to plot",
                                 "None of the checked datasets had enough surviving data to fit.")
            return

        ax = self.interp_compare_ax
        ax.clear()
        ax.set_facecolor(BG_COLOR)
        all_x = np.concatenate([res["fit"]["x_reg"] for _, res in results])
        x_range = np.linspace(min(all_x), max(all_x), 100)
        stats_y = 0.96
        for i, (ds, res) in enumerate(results):
            scatter_c, line_c = self._interp_palette[i % len(self._interp_palette)]
            fit = res["fit"]
            inverse_area = res["areas_um2"] ** -1
            for inv_A, clean_row in zip(inverse_area, res["clean_rows"]):
                if len(clean_row) > 0:
                    ax.scatter([inv_A] * len(clean_row), clean_row, color=scatter_c, alpha=0.25, s=22, zorder=2)
            ax.errorbar(fit["x_reg"], fit["y_reg"], yerr=fit["y_stds_reg"], fmt="o", color=scatter_c,
                        ecolor=scatter_c, elinewidth=1.3, capsize=3, ms=6, label=f"{ds.name} Means", zorder=3)
            y_range = fit["a0"] + fit["a1"] * x_range
            ax.plot(x_range, y_range, color=line_c, linewidth=2.2,
                    label=f"{ds.name} Fit ($R^2={fit['r2']:.3f}$)", zorder=1)
            stats_text = (f"{ds.name}: $J_c$={fit['J_c_A_cm2']:,.1f} A/cm²  |  "
                          f"slope={fit['a1']:.2f}  |  $R^2$={fit['r2']:.3f}")
            ax.text(0.03, stats_y, stats_text, transform=ax.transAxes, fontsize=8.5, verticalalignment="top",
                    color=scatter_c, bbox=dict(boxstyle="round,pad=0.35", facecolor=PANEL_COLOR, alpha=0.85,
                                                edgecolor=scatter_c))
            stats_y -= 0.065

        ax.set_title("Resistance Comparison: " + " vs. ".join(ds.name for ds, _ in results),
                     fontsize=12, color=TEXT_COLOR, fontweight="bold")
        ax.set_xlabel(r"Inverse Junction Area, $1/A$ ($\mu m^{-2}$)", color=TEXT_COLOR)
        ax.set_ylabel(r"Junction Resistance, $R_n$ (k$\Omega$)", color=TEXT_COLOR)
        ax.tick_params(colors=DIM_COLOR)
        for spine in ax.spines.values():
            spine.set_color(DIM_COLOR)
        ax.grid(True, linestyle="--", alpha=0.3, color=DIM_COLOR)
        legend = ax.legend(loc="lower right", fontsize=8, framealpha=0.9)
        legend.get_frame().set_facecolor(PANEL_COLOR)
        legend.get_frame().set_edgecolor(DIM_COLOR)
        for text in legend.get_texts():
            text.set_color(TEXT_COLOR)
        try:
            self.interp_compare_fig.tight_layout()
        except Exception:
            pass
        self.interp_compare_canvas.draw_idle()
        self._interp_last_compare_results = results

    def _on_interp_compare_save_plot(self):
        if not self._interp_last_compare_results:
            QMessageBox.information(self, "Nothing to save", "Click \"Plot Checked\" first.")
            return
        path, _ = QFileDialog.getSaveFileName(self, "Save Comparison Plot", "junction_comparison.png",
                                               "PNG (*.png);;PDF (*.pdf)")
        if not path:
            return
        self.interp_compare_fig.savefig(path, facecolor=BG_COLOR, dpi=300, bbox_inches="tight")
        QMessageBox.information(self, "Saved", f"Plot saved to {path}")

    def _on_recipe_tab_shown(self):
        """Called every time Recipe becomes the visible page -- refreshes
        the staleness banner against whatever Simulate Design's CURRENT state is,
        since the person may have gone back and changed geometry/angles
        since this recipe was generated."""
        self._refresh_recipe_staleness_banner()

    def _refresh_recipe_staleness_banner(self):
        banner = self.recipe_staleness_banner
        if self._recipe_generated_fingerprint is None:
            banner.setVisible(False)
            return
        junction = self._sim_cached_junction
        params = self._current_recipe_params()
        if junction is None or any(f.deposited_second is None for f in junction.fingers):
            banner.setText("\u26a0 Simulation state is no longer available -- re-run Angle Diagnostic, then regenerate.")
            banner.setStyleSheet("color: #ffb454; font-size: 8pt; padding: 4px; "
                                  f"background-color: #3a2f14; border-radius: 4px;")
            banner.setVisible(True)
            return
        # This used to omit the override args entirely,
        # so it was comparing a fingerprint that ignored the Deposition
        # Angles tree's current state against one (from build_simulation_
        # result) that fully includes it -- an angle or thickness edit
        # made only there, with geometry/params otherwise unchanged,
        # never flagged the banner stale, and any active override at all
        # made the two fingerprints permanently mismatch (an ALWAYS-stale
        # false positive) since the recorded fingerprint always included
        # them. Passing the same override state used to build the recipe
        # fixes both directions.
        current_fp = ji._simulation_fingerprint(
            junction, params,
            finger_layer_overrides=dict(self._sim_finger_layers),
            patch_layer_overrides=(list(self._sim_patch_layers) if self._sim_patch_layers is not None else None),
            finger_thickness_overrides=dict(self._sim_finger_thicknesses),
            patch_thickness_overrides=(list(self._sim_patch_thicknesses) if self._sim_patch_thicknesses is not None else None),
        )
        if current_fp != self._recipe_generated_fingerprint:
            banner.setText("\u26a0 The design has changed -- this recipe no longer reflects it. Regenerate before trusting it.")
            banner.setStyleSheet("color: #ffb454; font-size: 8pt; padding: 4px; "
                                  f"background-color: #3a2f14; border-radius: 4px;")
            banner.setVisible(True)
        else:
            banner.setText("\u2713 This recipe matches the current Simulate Design state.")
            banner.setStyleSheet("color: #8fd694; font-size: 8pt; padding: 4px; "
                                  f"background-color: #1e2e22; border-radius: 4px;")
            banner.setVisible(True)

    def _on_generate_recipe_from_sim(self):
        self._generate_recipe_from_sim(show_errors=True)

    def _generate_recipe_from_sim(self, show_errors: bool) -> bool:
        """The actual body of "Generate Recipe from Simulation" -- pulled
        out so AI Draft can call it directly instead of just refusing when
        self._recipe_last_steps is empty. The AI-generated recipe should
        read the parameters and angles already found in the simulation
        without requiring a separate "Generate Recipe from Simulation"
        click first -- clicking that button separately was never meant to
        be a prerequisite a user has to remember, it's a formality once
        the Angle Diagnostic has already been run, which is normal Create
        / Import/Simulate Design usage regardless of whether the user ever
        intends to look at the deterministic pane.
        Returns True if a recipe now exists in self._recipe_last_steps
        (either just generated, or already there from before) and False if
        there's truly nothing to build from yet (no junction, or deposit
        order not set) -- with show_errors=True, that failure also shows
        the same QMessageBox the button always has; with show_errors=False
        (the AI Draft path), the caller shows its own message instead, so
        the two flows never show two overlapping dialogs for one click."""
        junction = self._sim_cached_junction
        if junction is None or not junction.fingers:
            if show_errors:
                QMessageBox.information(self, "Nothing to generate from",
                                         "Create or import a junction first, then run the Angle Diagnostic.")
            return False
        if any(f.deposited_second is None for f in junction.fingers):
            if show_errors:
                QMessageBox.information(self, "Deposit order not set",
                                         "Set which finger deposits first, then run the Angle Diagnostic.")
            return False
        params = self._current_recipe_params()
        disconnection_notes = list(getattr(self, "_sim_disconnection_warnings", []) or [])
        # Passes through whatever the
        # user has actually committed in Simulate Design's Deposition Angles
        # tree (self._sim_finger_layers/_sim_patch_layers) -- the recipe
        # must be built from the user's FINAL decision (as-recommended,
        # or edited/reordered/added-to), not silently regenerated from
        # the original geometry recommendation every time. See
        # junction_import.build_simulation_result's docstring.
        # Thickness overrides ride along
        # the SAME tree state (self._sim_finger_thicknesses/
        # _sim_patch_thicknesses), so a pass's explicitly-typed thickness
        # actually reaches the generated recipe, not just its angle.
        sim_result = ji.build_simulation_result(
            junction, params, disconnection_notes=disconnection_notes,
            finger_layer_overrides=dict(self._sim_finger_layers),
            patch_layer_overrides=(list(self._sim_patch_layers) if self._sim_patch_layers is not None else None),
            finger_thickness_overrides=dict(self._sim_finger_thicknesses),
            patch_thickness_overrides=(list(self._sim_patch_thicknesses) if self._sim_patch_thicknesses is not None else None),
        )
        if sim_result.not_set:
            if show_errors:
                QMessageBox.information(self, "Can't generate yet", sim_result.not_set_reason)
            return False
        old_features = self._recipe_features
        self._recipe_sim_result = sim_result
        self._recipe_features = list(sim_result.features)  # editable copy -- reorder/delete acts on this
        self._recipe_generated_fingerprint = sim_result.fingerprint
        self._reapply_manual_angle_overrides(old_features, self._recipe_features)
        self._rebuild_recipe_from_features()
        self._refresh_recipe_staleness_banner()
        return True

    def _rebuild_recipe_from_features(self):
        """Rebuilds custom_steps + the literal RecipeStep list from
        self._recipe_features (the editable copy) -- called both right
        after generation and after any reorder/delete override, so the
        timeline, the expanded recipe text (self._recipe_last_steps,
        read directly by this tab's own _AICtx.skeleton_steps_fn), and
        self._recipe_custom_steps can never disagree with each other.

        Fixes an inconsistency where a deposition thickness typed by hand
        in the Recipe tab was not reflected in the steps shown in the
        Deposition Slideshow: the slideshow should display those
        user-specified thicknesses, or whatever thickness is used for
        that step in the complete process recipe, falling back to the
        default when no override was entered. self._recipe_last_steps is what the
        Deposition Slideshow reads verbatim (_on_slideshow_refresh), and
        also feeds the PDF export/front-page status pill/File > Save
        Recipe/the Ask AI assistant's context -- but this method used to
        build custom_steps from the RAW self._recipe_features, which
        never reflects the Recipe Parameters panel's per-pass hand-typed
        thickness override at all (that override was previously applied
        ONLY at "Generate Recipe" click time, onto a separate copy fed to
        rte.build_generated_subrecipes -- see
        _recipe_features_with_panel_overrides's own docstring). So every
        one of those consumers, slideshow included, silently showed the
        un-overridden default even after the real generated recipe (and
        the Recipe Builder tree view of it) already reflected the typed
        value -- two different numbers for the same pass. Fixed by
        building custom_steps from _recipe_features_with_panel_overrides()
        instead of the raw list -- the exact same per-pass override
        application "Generate Recipe" already used, so every consumer of
        self._recipe_last_steps now agrees with the real recipe, and a
        blank panel field still means "use Simulate Design's own value"
        (that method's own "leave untouched" contract), so a blank field
        falls back to showing the default value. Note this deliberately does
        NOT change self._recipe_features itself, or what the Predicted
        Recipe Sequence card (_populate_sim_feature_sequence, below)
        displays -- that card is Simulate Design's own per-pass state,
        which the panel override was always meant to sit on top of for
        "this generation only," never feed back into.

        _rebuild_recipe_panel_dynamic_fields() must run BEFORE the loop
        below, not after (its old position) -- it's what keeps
        recipe_panel_thickness_edits/recipe_panel_mill_duration_edits
        correctly keyed to the CURRENT self._recipe_features (preserving
        any already-typed text by the same pass-identity key); reading
        those widgets for overrides before that sync would apply this
        generation's typed text against the PREVIOUS generation's pass
        identities."""
        self._rebuild_recipe_panel_dynamic_fields()
        params = self._current_recipe_params()
        custom_steps = []
        for feat in self._recipe_features_with_panel_overrides():
            if feat.kind == "mill":
                custom_steps.append({"type": "Mill", "alpha": feat.alpha, "theta": feat.theta})
            elif feat.kind == "deposition":
                custom_steps.append({"type": "Deposition", "alpha": feat.alpha, "theta": feat.theta,
                                      "thickness_nm": feat.thickness_nm})
            elif feat.kind == "oxidation":
                custom_steps.append({"type": "Oxidation"})
        steps, warnings = generate_recipe_steps(params, custom_steps, skip_old_electrode_warnings=True)
        if self._recipe_sim_result is not None and self._recipe_sim_result.has_disconnections:
            warnings = list(self._recipe_sim_result.disconnection_notes) + warnings
        self._recipe_custom_steps = custom_steps
        self._recipe_last_steps = steps
        self._recipe_last_warnings = warnings
        self._recipe_last_params = params
        self._recipe_last_source_label = "Auto-generated from Simulate Design"
        self._recipe_hand_edits = []        # fresh generation -- any prior hand-edits no longer apply
        # Fixes a bug found while extending a diagnostic test to drive a
        # recipe through the real Generate Recipe click instead of poking
        # internals directly: _last_
        # recipe_text is only ever ASSIGNED inside _build_recipe_html
        # (see that method's own docstring -- "the single place
        # _last_recipe_text ... is [set]"), which used to be called from
        # _render_recipe_output when the Recipe tab still rendered into
        # its own "Expanded Recipe" text browser. That browser (and the
        # call to render into it) was removed once Auto-Generated recipes
        # started opening directly into the real tree/table panel instead
        # -- but nothing replaced it as a way to keep _last_recipe_text
        # current, so File > Save Recipe (and this app's other remaining
        # _last_recipe_text consumers) silently stopped working the
        # moment a real user generated ANY recipe, always reporting
        # "Nothing to save" no matter what. _build_recipe_html is a pure
        # string builder aside from that one assignment -- no widget
        # needed -- so it's called directly here (never via a browser)
        # purely to keep _last_recipe_text current, exactly as this
        # method's own docstring already claims it does.
        self._build_recipe_html(steps, warnings, params, source_label=self._recipe_last_source_label)
        self._populate_sim_feature_sequence()
        # _rebuild_recipe_panel_dynamic_fields() now runs FIRST, above --
        # see this method's own docstring for why the order flipped.
        self._sync_sim_layers_from_recipe_features()  # keep shadow-calc state in sync

    def _populate_sim_feature_sequence(self):
        """Renders self._recipe_features as reorderable/deletable/hand-
        overridable blocks, relocated
        here from the Recipe tab's old "Traced Recipe Timeline" (see
        _refresh_recipe_features's docstring): the mill/oxidation
        placement prediction now lives live in Simulate Design's
        "Predicted Recipe Sequence" card, not just at Recipe-tab
        generation time. Logic is otherwise unchanged from the retired
        Recipe-tab renderer it replaces."""
        if not hasattr(self, "sim_feature_sequence_layout"):
            return
        layout = self.sim_feature_sequence_layout
        # Fixes a crash after repeated Run Simulation/Run
        # Angle Diagnostic clicks, especially across several loaded
        # designs: prune this batch's own themed widgets out of
        # self._themed_widgets BEFORE deleteLater()-ing them -- see
        # _prune_themed_widgets's own docstring for the full story.
        old_roots = [layout.itemAt(i).widget() for i in range(layout.count())]
        self._prune_themed_widgets([w for w in old_roots if w is not None])
        while layout.count():
            item = layout.takeAt(0)
            w = item.widget()
            if w is not None:
                w.deleteLater()

        if not self._recipe_features:
            placeholder = QLabel("Nothing predicted yet -- run the Angle Diagnostic and set which finger "
                                  "deposits first; the mill/deposition/oxidation sequence will appear here.")
            placeholder.setWordWrap(True)
            self._themed(placeholder, lambda: f"color: {DIM_COLOR}; font-size: 8pt;")
            layout.addWidget(placeholder)
            # Still offer a way to start a sequence entirely by
            # hand even before any geometry-derived prediction exists.
            layout.addWidget(self._build_insert_step_row(0))
            return

        layout.addWidget(self._build_insert_step_row(0))
        for i, feat in enumerate(self._recipe_features):
            color = self._FEATURE_COLOR.get(feat.warning_source, "#8ea3c2")
            block = QFrame()
            block.setStyleSheet(f"QFrame {{ background-color: #232530; border-left: 4px solid {color}; "
                                 f"border-radius: 3px; }}")
            block_layout = QVBoxLayout(block)
            block_layout.setContentsMargins(8, 6, 8, 6)

            # Fixes a layout bug where all of the sidebar tabs would widen
            # too much once the prediction order card was populated,
            # crowding out other cards (like the chamber side-view)
            # because every card in the sidebar resizes its contents to
            # match the widest one. Root cause: the title
            # label below (kind tag + this feature's own, often fairly
            # long, predicted label -- e.g. "Mill before finger_A (pass
            # 1 of 2)") used to share ONE horizontal row with the alpha/
            # theta override fields AND all three up/down/delete
            # buttons, with no word-wrap on the title -- so a long label
            # forced that single row's natural width past whatever this
            # card's column was ever sized for. Since every card in
            # Simulate Design's left sidebar shares the SAME parent
            # width (see angle_layout), that one oversized row dragged
            # every other card along with it, matching the reported
            # symptom of every card widening together. Restructured into two rows instead of
            # one: the title alone, word-wrapped (so a long label drops
            # to a second line instead of demanding more width -- the
            # same fix _sim_card's own title and the Complete Process
            # table's Subproc Name column already use), then a second,
            # SEPARATE row underneath for the angle override fields
            # (left) and the up/down/delete buttons (right) -- those are
            # all small, fixed-width controls, so that row's own natural
            # width no longer depends on how long any feature's label
            # happens to be.
            title_row = QHBoxLayout()
            kind_tag = {"mill": "MILL", "deposition": "DEPOSIT", "oxidation": "OXIDIZE"}.get(feat.kind, feat.kind.upper())
            title = QLabel(f"[{kind_tag}] {feat.label}")
            title.setWordWrap(True)
            self._themed(title, lambda: f"color: {TEXT_COLOR}; font-weight: bold;")
            title_row.addWidget(title, stretch=1)
            block_layout.addLayout(title_row)

            controls_row = QHBoxLayout()
            controls_row.setSpacing(3)
            # The generated recipe can occasionally be wrong on real
            # designs, so alpha/theta need to
            # be a manual override the user can type over directly here
            # -- not just read off the block -- rather than forcing a
            # trip back to Simulate Design's override fields (which don't even
            # apply per-feature). Editing either field sets
            # feat.manual_override, which _build_recipe_html reads to
            # show a "Manual Override" warning badge -- an edited angle
            # is exactly the kind of thing that should be visibly
            # flagged, not silently trusted the same as a generated one.
            if feat.alpha is not None and feat.theta is not None:
                alpha_lbl = QLabel("\u03b1=")
                alpha_lbl.setStyleSheet(f"color: {color}; font-family: monospace;")
                alpha_edit = QLineEdit(f"{feat.alpha:.1f}")
                alpha_edit.setFixedWidth(48)
                alpha_edit.setStyleSheet(f"color: {color}; font-family: monospace; background-color: #1a1c24; "
                                          f"border: 1px solid #3a3d4d; border-radius: 3px; padding: 1px 3px;")
                theta_lbl = QLabel("\u00b0  \u03b8=")
                theta_lbl.setStyleSheet(f"color: {color}; font-family: monospace;")
                theta_edit = QLineEdit(f"{feat.theta:.1f}")
                theta_edit.setFixedWidth(48)
                theta_edit.setStyleSheet(alpha_edit.styleSheet())
                deg_lbl = QLabel("\u00b0")
                deg_lbl.setStyleSheet(f"color: {color}; font-family: monospace;")
                alpha_edit.editingFinished.connect(
                    lambda idx=i, ae=alpha_edit, te=theta_edit: self._on_recipe_feature_angle_edited(idx, ae, te))
                theta_edit.editingFinished.connect(
                    lambda idx=i, ae=alpha_edit, te=theta_edit: self._on_recipe_feature_angle_edited(idx, ae, te))
                controls_row.addWidget(alpha_lbl)
                controls_row.addWidget(alpha_edit)
                controls_row.addWidget(theta_lbl)
                controls_row.addWidget(theta_edit)
                controls_row.addWidget(deg_lbl)
            controls_row.addStretch(1)
            up_btn = QPushButton("\u25b2")
            up_btn.setFixedWidth(24)
            up_btn.setEnabled(i > 0)
            up_btn.clicked.connect(lambda _=False, idx=i: self._move_recipe_feature(idx, -1))
            down_btn = QPushButton("\u25bc")
            down_btn.setFixedWidth(24)
            down_btn.setEnabled(i < len(self._recipe_features) - 1)
            down_btn.clicked.connect(lambda _=False, idx=i: self._move_recipe_feature(idx, 1))
            del_btn = QPushButton("\u2715")
            del_btn.setFixedWidth(24)
            del_btn.clicked.connect(lambda _=False, idx=i: self._delete_recipe_feature(idx))
            controls_row.addWidget(up_btn)
            controls_row.addWidget(down_btn)
            controls_row.addWidget(del_btn)
            block_layout.addLayout(controls_row)

            if feat.manual_override:
                override_lbl = QLabel("\u26a0 Manual Override -- alpha/theta typed by hand, not from the simulation")
                override_lbl.setWordWrap(True)
                override_lbl.setStyleSheet(f"color: {WARN_COLOR}; font-size: 7.5pt; font-weight: bold;")
                block_layout.addWidget(override_lbl)

            detail = QLabel(feat.provenance)
            detail.setWordWrap(True)
            self._themed(detail, lambda: f"color: {DIM_COLOR}; font-size: 8pt;")
            block_layout.addWidget(detail)

            layout.addWidget(block)
            layout.addWidget(self._build_insert_step_row(i + 1))

    def _build_insert_step_row(self, insert_index: int) -> QWidget:
        """Adds an insert-step dropdown to add mill/deposition/
        oxidation steps anywhere in the sequence, with the generated
        recipe updating accordingly. Delete already existed (the ✕
        button on every block); this is the missing other half -- one
        thin row between every pair of blocks (plus one before the
        first and, implicitly, one after the last), each carrying a
        small dropdown that inserts a brand-new hand-created step at
        exactly that position. `insert_index` is a plain list index into
        self._recipe_features (0 = before everything, len(...) = after
        everything)."""
        row = QWidget()
        row_layout = QHBoxLayout(row)
        row_layout.setContentsMargins(0, 0, 0, 0)
        row_layout.setSpacing(4)
        left_line = QFrame()
        left_line.setFrameShape(QFrame.HLine)
        left_line.setStyleSheet("color: #3a3d4d;")
        row_layout.addWidget(left_line, stretch=1)
        insert_btn = QToolButton()
        insert_btn.setText("+ Insert Step ▾")
        insert_btn.setPopupMode(QToolButton.InstantPopup)
        insert_btn.setCursor(Qt.PointingHandCursor)
        insert_btn.setStyleSheet("""
            QToolButton { background-color: #22303a; color: #7fc8e6; border: 1px solid #3a5a6a;
                         border-radius: 4px; font-size: 7.5pt; padding: 2px 6px; }
            QToolButton:hover { background-color: #2a3d4a; }
            QToolButton::menu-indicator { image: none; width: 0px; }
        """)
        menu = QMenu(insert_btn)
        mill_action = menu.addAction("Mill Step")
        mill_action.triggered.connect(
            lambda _checked=False, idx=insert_index: self._insert_recipe_feature(idx, "mill"))
        # A manually-inserted deposition
        # step always used source_id="__manual_insert__" -- no
        # attribution to any real finger/patch -- so no matter what angle
        # it was given, it could never register in self._sim_finger_
        # layers/_sim_patch_layers, the ONLY state Post-Shadow Result's
        # shadow geometry actually reads. An earlier fix made
        # "Deposition Step" a submenu requiring the user to pick a single
        # target (a specific finger, or "Patches") up front, calling the
        # SAME already-correct _on_add_finger_layer/_on_add_patch_layer
        # the (data-model-identical) per-feature angle tree uses.
        #
        # That submenu turned out to be the wrong interaction: adding a
        # deposition step should not require specifying a type or target
        # up front -- the user should just click, enter the alpha/theta
        # angles, and have it incorporate that deposition step directly.
        # "Deposition
        # Step" is now a single flat action again (like "Mill Step"/
        # "Oxidation Step" right beside it, no submenu) -- see
        # _insert_deposition_step's own docstring for the full history:
        # it went through two more follow-up fixes
        # after this one (an "always every target" phase that twice
        # fanned out to more than one target on a single click) before
        # landing on its current, final behavior -- exactly ONE new step
        # at exactly the clicked position, attributed to a single real
        # target only when that position unambiguously belongs to one,
        # otherwise the same plain freeform step Mill/Oxidation Step
        # already give.
        dep_action = menu.addAction("Deposition Step")
        dep_action.triggered.connect(
            lambda _checked=False, idx=insert_index: self._insert_deposition_step(idx))
        oxidation_action = menu.addAction("Oxidation Step")
        oxidation_action.triggered.connect(
            lambda _checked=False, idx=insert_index: self._insert_recipe_feature(idx, "oxidation"))
        insert_btn.setMenu(menu)
        row_layout.addWidget(insert_btn)
        right_line = QFrame()
        right_line.setFrameShape(QFrame.HLine)
        right_line.setStyleSheet("color: #3a3d4d;")
        row_layout.addWidget(right_line, stretch=1)
        return row

    def _insert_recipe_feature(self, index: int, kind: str):
        """Inserts a brand-new, fully hand-created SimulationFeature at
        `index` (see _build_insert_step_row above). Defaults are
        deliberately simple, safe starting points -- NOT a real
        prediction -- since there's no geometry backing this step;
        source_id="__manual_insert__" is what _reapply_manual_angle_
        overrides (see its own docstring) uses to recognize and carry
        this step forward through every later live regeneration, the
        same way an override on a real feature already survives one."""
        index = max(0, min(index, len(self._recipe_features)))
        self._recipe_manual_insert_counter = getattr(self, "_recipe_manual_insert_counter", 0) + 1
        n = self._recipe_manual_insert_counter
        p = self._current_recipe_params()
        if kind == "deposition":
            default_thickness = getattr(p, "al_thickness_1_nm", None) or 20.0
            feat = ji.SimulationFeature(
                kind="deposition", alpha=30.0, theta=0.0, thickness_nm=default_thickness,
                label=f"Manually inserted deposition step #{n}",
                provenance="Manually inserted -- not derived from the simulated geometry. Set the "
                           "real alpha/theta/thickness before generating the recipe.",
                warning_source=None, source_id="__manual_insert__", manual_override=True)
        elif kind == "mill":
            feat = ji.SimulationFeature(
                kind="mill", alpha=50.0, theta=0.0, thickness_nm=None,
                label=f"Manually inserted mill step #{n}",
                provenance="Manually inserted -- not derived from the simulated geometry. Set the "
                           "real alpha/theta before generating the recipe.",
                warning_source=None, source_id="__manual_insert__", manual_override=True)
        else:
            feat = ji.SimulationFeature(
                kind="oxidation", alpha=None, theta=None, thickness_nm=None,
                label=f"Manually inserted oxidation step #{n}",
                provenance="Manually inserted -- not derived from the simulated geometry.",
                warning_source=None, source_id="__manual_insert__", manual_override=True)
        self._recipe_features.insert(index, feat)
        self._rebuild_recipe_from_features()

    def _insert_deposition_step(self, insert_index: int):
        """Adds exactly ONE new deposition step at the exact position
        the user clicked in the Predicted Recipe Sequence (see
        _build_insert_step_row) -- never more than one, and never
        anywhere else.

        HISTORY, kept because this function's design went through several
        iterations, each solving a real, reproduced bug but leaving
        another one behind:

        Originally, "Deposition Step" was a submenu forcing a
        target choice (a specific finger, or "Patches") up front --
        never physically accurate (one Plassys pass exposes the whole
        wafer at once), and unnecessarily complicated the common case of
        just wanting to add a deposition step without specifying which
        finger or patch it belonged to. Replaced with a single
        flat action that added a new pass to EVERY real target at once
        (every finger AND patches), reasoning that one physical pass
        really does hit every aperture simultaneously.

        Follow-up #1: that "add to everything" behavior turned out to be
        wrong -- inserting a deposition step at one position in the
        sequence should add only one step in that one area, not one
        everywhere. Root cause: the position
        the user actually clicked (`insert_index`) was never used at all
        -- every click unconditionally appended to the very END of every
        target's own layer list, regardless of which of the many per-gap
        "+ Insert Step" buttons was pressed. Fixed the POSITION each
        target's own new pass landed at, but every click still added a
        pass to every target -- it never changed WHO got one.

        Follow-up #2: the same "adds a step everywhere" symptom recurred
        for patches specifically.
        Fixed by scoping a click to a single target only when the click
        sits squarely inside that target's own contiguous block (both
        neighboring features share the same source_id) -- ambiguous/
        boundary clicks (the very start, the very end, between two
        DIFFERENT targets' blocks) still fanned out to every target.

        Follow-up #3 (THIS fix): a boundary-ish click still fanned out to
        multiple extra steps after follow-up #2. The actual requirement is
        simple and unambiguous: inserting one step at one position should
        add exactly one step there and nowhere else, whether that
        position is in the middle of the sequence or at the very
        beginning or end.
        This makes the actual requirement unambiguous, and it's simpler
        than every earlier design: there is NEVER a "fan out to every
        target" case, full stop -- exactly matching how "Mill Step" and
        "Oxidation Step" beside this same menu entry have always worked
        (_insert_recipe_feature: one single, freeform step, wherever
        clicked, nothing else). "Deposition Step" now works identically,
        with one added refinement so it still gets incorporated
        into the real shadow math per the
        original design intent: when the clicked position sits squarely inside ONE
        target's own contiguous block (_recipe_insert_target_scope --
        e.g. between two of patches' own steps, or between two of one
        finger's own passes), the new pass is attributed to that one
        target alone (via _on_add_finger_layer/_on_add_patch_layer, so
        it's a REAL pass, not just documentation) at the exact local
        position _recipe_local_pass_insert_positions computes for it.
        Anywhere else -- the very start, the very end, or a boundary
        between two DIFFERENT targets' blocks, where there genuinely is
        no single target the click could mean -- falls back to the
        same plain, unattributed freeform step _insert_recipe_feature
        already gives Mill/Oxidation Step, never to more than one
        feature and never to more than one target.

        Follow-up #4: after follow-up #3 shipped, a newly inserted step
        still needed to be verified as actually taking effect everywhere
        it should -- the shadow sim, the post-deposition view, the
        Recipe tab, and the Deposition Slideshow all needed to reflect an
        inserted step, not just the Predicted Recipe Sequence card
        itself. Reproduced directly: the single most
        natural click position of all -- right after a target's own
        MOST RECENT pass, immediately before that target's own
        oxidation step (or, if it's the last real target in the whole
        sequence, before the recipe's one trailing final-oxidation
        feature) -- was itself scoping to None (ambiguous) under follow-
        up #3's immediate-neighbor-only check, because the very next
        feature there is an untargeted connector (oxidation,
        source_id=None), not another same-target deposit. That silently
        routed the single most common real workflow (adding a target's
        very next angle) into the disconnected freeform fallback, which
        by design (see _sync_sim_layers_from_recipe_features's own
        docstring) has zero shadow effect and is excluded from
        _generate_recipe_from_sim's build_simulation_result call
        entirely -- so it never reached the shadow sim, Post-Shadow
        Result, the Recipe tab, OR (via self._recipe_last_steps) the
        Deposition Slideshow. Fixed by _recipe_insert_target_scope now
        comparing each side's ZONE (_recipe_feature_zone -- carries a
        gap's attribution backward through untargeted connector
        features to the most recent real target) instead of raw
        immediate-neighbor source_id -- see that function's own
        docstring for the full mechanism. No separate propagation fix
        was needed for the shadow sim/recipe/slideshow specifically:
        once the scope resolves correctly, this function already routes
        through _on_add_finger_layer/_on_add_patch_layer, the same
        mutators the Deposition Angles tree's own "+" button has always
        used, which is the ONE place self._sim_finger_layers/
        _sim_patch_layers are written -- and every one of those other
        views/tabs already reads its data from that same state."""
        junction = self._sim_cached_junction
        scope = self._recipe_insert_target_scope(insert_index) if junction is not None and junction.fingers else None
        _debug_log(f"INSERT_DEP insert_index={insert_index} scope={scope!r} "
                   f"list_before={[(f.kind, f.source_id, f.theta, f.label) for f in self._recipe_features]}")
        if scope is not None and junction is not None:
            stable_id_to_finger_idx = {getattr(f, "stable_id", None): i for i, f in enumerate(junction.fingers)}
            if scope in stable_id_to_finger_idx:
                finger_idx = stable_id_to_finger_idx[scope]
                finger = junction.fingers[finger_idx]
                params = self._current_recipe_params()
                default_thickness = ji.default_finger_pass_thickness(finger, 0.0, params)
                finger_positions, _patch_position = self._recipe_local_pass_insert_positions(insert_index)
                _debug_log(f"INSERT_DEP -> _on_add_finger_layer finger_idx={finger_idx} "
                           f"stable_id={scope!r} insert_pos={finger_positions.get(finger_idx)}")
                self._on_add_finger_layer(finger_idx, 0.0, default_thickness,
                                           insert_pos=finger_positions.get(finger_idx))
                return
            if scope == "patches" and any(getattr(s, "kind", None) == "patch" for s in junction.other_shapes):
                params = self._current_recipe_params()
                default_thickness = ji.default_patch_pass_thickness(params)
                _finger_positions, patch_position = self._recipe_local_pass_insert_positions(insert_index)
                _debug_log(f"INSERT_DEP -> _on_add_patch_layer insert_pos={patch_position}")
                self._on_add_patch_layer(0.0, default_thickness, insert_pos=patch_position)
                return
            _debug_log(f"INSERT_DEP scope={scope!r} matched NEITHER a finger stable_id NOR 'patches' "
                       f"(other_shapes kinds={[getattr(s, 'kind', None) for s in junction.other_shapes]}) "
                       f"-- falling through to freeform")
        # Ambiguous/global position (before the very first feature,
        # after the very last one, a boundary between two DIFFERENT
        # targets' own blocks, or no real junction geometry at all) --
        # exactly ONE plain, unattributed step, same as Mill/Oxidation
        # Step -- never fanned out to more than one feature.
        _debug_log("INSERT_DEP -> freeform _insert_recipe_feature fallback")
        self._insert_recipe_feature(insert_index, "deposition")

    def _recipe_feature_effective_source_id(self, feat):
        """A feature's real attribution for zone/scope/pass-counting
        purposes -- feat.source_id when it's set, else "patches" when
        feat.warning_source == "patches" (a patches feature with no
        source_id of its own), else None.

        ROOT CAUSE this closes, found via debug logging against a real
        patch-integrated GDS import with the identical
        symptom surviving multiple supposedly-verified fixes: a
        locally-running copy of junction_import.py was an OLDER copy whose
        "Mill before patches"/"Deposit patches" SimulationFeature
        constructors set warning_source="patches" but never source_id=
        "patches" on those same features -- a fix from an EARLIER
        iteration that only ever got applied to junction_import.py on
        the development side, never actually re-shipped alongside a
        later update (each later update re-sent main_gui.py, whose
        own build tag was confirmed each time -- but never re-sent
        junction_import.py itself, so that half of the fix silently
        never reached the deployed copy). With source_id=None on those features,
        _recipe_feature_zone's old source_id-only backward scan skipped
        straight past "Mill before patches"/"Deposit patches" to
        whichever FINGER's own feature happened to precede them,
        resolving an Insert Step click meant for patches onto that
        finger instead -- byte-for-byte the "lands on finger_1 (2nd)"
        bug reported three times. Falling back to warning_source here
        means zone/scope/pass-count resolution self-heals the instant
        EITHER field correctly says "patches", instead of silently
        depending on both staying in lockstep across every copy of
        junction_import.py this app is ever shipped alongside -- the
        exact class of drift that caused this entire saga."""
        sid = feat.source_id
        if sid is not None:
            return sid
        if feat.warning_source == "patches":
            return "patches"
        return None

    def _recipe_feature_zone(self, index):
        """Which real target's own "trailing region" self._recipe_features[index]
        falls in, carrying forward through untargeted connector features
        (source_id is None -- the global initial mill, or an oxidation
        step) from whichever real target's own feature most recently
        preceded them. Scans BACKWARD from `index` (inclusive) to the
        first feature with a non-None EFFECTIVE source id
        (_recipe_feature_effective_source_id -- source_id, falling back
        to "patches" when warning_source says so -- see that method's
        own docstring for why this fallback matters) and returns it;
        returns None if nothing with a real attribution precedes `index`
        at all (e.g. `index` is, or is before, the global initial mill).

        GAP this closes, found and reproduced:
        _recipe_insert_target_scope (below) used to compare ONLY the two
        features immediately touching the clicked gap, with no
        carry-forward. That works for a gap strictly BETWEEN two of one
        target's own deposition passes, but silently fails for the far
        more common click position -- right after a target's ONLY
        existing pass so far, immediately before that target's own
        oxidation step (or, if it's the last real target in the
        sequence, before the recipe's single trailing final-oxidation
        step) -- because the very next feature is an untargeted
        oxidation (source_id=None), not another same-target deposit. On
        a real patch-integrated design, clicking "+Insert
        Step" right after "Deposit patches" and before "Final protective
        oxidation" (reproduced directly: patches already has passes at
        two angles, one gap after the last one, immediately before
        the recipe's one global final-oxidation feature) resolved to
        `None` (ambiguous) under the old immediate-neighbor-only check,
        so it fell back to a disconnected freeform step with zero shadow
        effect -- the inserted step appeared in the sequence but had no
        actual effect on the shadow geometry. Carrying the zone forward through the
        oxidation step fixes this: the gap right before ANY oxidation
        (per-target or the final one) now correctly resolves to whatever
        real target's own block most recently preceded it, letting a
        user add that target's very next pass exactly where they'd
        naturally click for it."""
        feats = self._recipe_features
        for i in range(index, -1, -1):
            sid = self._recipe_feature_effective_source_id(feats[i])
            if sid is not None:
                return sid
        return None

    def _recipe_insert_target_scope(self, insert_index):
        """Whether the clicked gap at `insert_index` (see
        _build_insert_step_row/_insert_deposition_step) sits inside one
        single target's own trailing region -- i.e. the zone
        (_recipe_feature_zone, which carries forward through untargeted
        connector features like oxidation steps -- see its own
        docstring for the directly-reported gap this closes) of the
        feature immediately before the gap matches the zone of the
        feature immediately after it, and that shared zone is a real
        target (a finger's own `stable_id`, or `"patches"`).

        Returns that shared zone string when so, else None for a
        genuinely ambiguous/global gap: before the very first feature,
        after the very last one, or exactly at the boundary between two
        DIFFERENT targets' own regions (where there's no single target
        the click could unambiguously mean).

        Fixes a bug reported against a real patch-integrated design:
        adding a second deposition layer to one of the junction fingers
        did not show up in the shadow sim or post deposition
        view when inserted right after that finger's second deposition
        step. Reproduced directly: that click sits
        immediately after finger_0's own deposition pass and immediately
        before "Mill before patches (pass 1 of 2)" -- a MILL step, but
        one that (unlike a plain untargeted oxidation/prep connector)
        carries its own REAL attribution (source_id="patches", so
        patches can get its own contact mill before its own deposition;
        see junction_import.py's patch-mill construction). Because that
        mill step's own zone is "patches", not None, the old check above
        never got a chance to carry the scan backward through it the way
        it already does for an unattributed oxidation step (see
        _recipe_feature_zone's own docstring) -- `before_zone` resolved
        to "finger_0", `after_zone` resolved to "patches", they disagree,
        and the click fell back to the fully unattributed freeform
        "Manually inserted deposition step #N" path -- same zero-shadow-
        effect fallback _sync_sim_layers_from_recipe_features's own
        docstring says is reserved for GENUINE ambiguity (a real boundary
        between two different targets' own DEPOSITION blocks). This
        wasn't that: a mill/oxidation step is a prep/connector action,
        never itself the start of a competing deposition block, so its
        OWN attribution (real or not) should never be enough by itself
        to block a deposition insert from attaching to whichever real
        target's deposition pass sits immediately on the other side of
        it. Fixed by checking the KIND of the feature immediately
        touching the gap (not the zone-resolved target) before falling
        back to "ambiguous": if the immediate neighbor on one side is a
        real deposition step (giving a real zone) while the immediate
        neighbor on the OTHER side is a mill/oxidation connector (whatever
        ITS OWN zone happens to be), the gap still counts as squarely
        inside the deposition-side target's own trailing region. Only a
        gap between two DIRECTLY-adjacent DEPOSITION features belonging
        to two different targets remains genuinely ambiguous."""
        feats = self._recipe_features
        if 0 < insert_index < len(feats):
            before_zone = self._recipe_feature_zone(insert_index - 1)
            after_zone = self._recipe_feature_zone(insert_index)
            if before_zone is not None and before_zone == after_zone:
                return before_zone
            before_is_deposition = feats[insert_index - 1].kind == "deposition"
            after_is_deposition = feats[insert_index].kind == "deposition"
            if before_zone is not None and before_is_deposition and not after_is_deposition:
                return before_zone
            if after_zone is not None and after_is_deposition and not before_is_deposition:
                return after_zone
        return None

    def _recipe_local_pass_insert_positions(self, insert_index):
        """Translates `insert_index` -- a plain list index into
        self._recipe_features, i.e. which specific gap between blocks
        the user clicked an insert-step button at (see
        _build_insert_step_row) -- into, for EACH real shadow target
        (every finger, and patches), how many of THAT target's own
        existing deposition passes already appear before that gap in
        the currently-displayed sequence.

        _insert_deposition_step uses this so a newly
        inserted physical deposition step lands, for whichever target's
        own block the clicked gap falls inside (or right before), at
        the position that actually corresponds to where the user
        clicked -- instead of unconditionally appending after every
        target's own existing passes regardless of where the click was.
        See that function's own docstring for the full directly-reported
        bug this fixes.

        Returns (finger_positions: Dict[int, int], patch_position: int).
        A target whose entire block already lies before `insert_index`
        gets its own full existing pass count back (an ordinary append
        -- exactly reproducing the old, correct-for-that-one-case
        behavior when `insert_index` is at/past the very end of the
        sequence, e.g. the top "+ Insert Step" menu). A target whose
        block hasn't started yet by `insert_index` (or that has no
        passes at all yet) gets 0 -- the new pass becomes that target's
        own first pass, correctly landing at (not after) the clicked
        gap once the sequence is regrouped and rebuilt."""
        junction = self._sim_cached_junction
        finger_positions = {i: 0 for i in range(len(junction.fingers))} if junction is not None else {}
        patch_position = 0
        stable_id_to_finger_idx = {}
        if junction is not None:
            for i, f in enumerate(junction.fingers):
                stable_id_to_finger_idx[getattr(f, "stable_id", None)] = i
        for i, feat in enumerate(self._recipe_features):
            if i >= insert_index:
                break
            if feat.kind != "deposition":
                continue
            effective_sid = self._recipe_feature_effective_source_id(feat)
            if effective_sid == "patches":
                patch_position += 1
            else:
                finger_idx = stable_id_to_finger_idx.get(effective_sid)
                if finger_idx is not None:
                    finger_positions[finger_idx] = finger_positions.get(finger_idx, 0) + 1
        return finger_positions, patch_position

    def _on_recipe_feature_angle_edited(self, index: int, alpha_edit: QLineEdit, theta_edit: QLineEdit):
        """Commits a hand-typed alpha/theta override on one timeline
        feature. Both fields route through here (whichever one lost
        focus) so a single edit updates both values together and only
        rebuilds once. Invalid/unparseable text is silently ignored
        (falls back to the feature's existing value) rather than
        crashing or clearing the field, matching this app's established
        live-preview-typing convention (_f)."""
        if not (0 <= index < len(self._recipe_features)):
            return
        feat = self._recipe_features[index]
        try:
            new_alpha = float(alpha_edit.text())
        except ValueError:
            new_alpha = feat.alpha
        try:
            new_theta = float(theta_edit.text())
        except ValueError:
            new_theta = feat.theta
        if new_alpha == feat.alpha and new_theta == feat.theta:
            return
        feat.alpha = new_alpha
        feat.theta = new_theta
        feat.manual_override = True
        self._rebuild_recipe_from_features()

    def _move_recipe_feature(self, index: int, delta: int):
        # Fixes a real crash found by a rapid-click
        # stress test on the widget (clicking an up/down arrow whose lambda captured `idx`
        # against an OLDER, now-shorter self._recipe_features list -- e.g. a
        # second real click landing on a stale button in the brief window
        # before a prior click's own _rebuild_recipe_from_features() rebuild
        # takes effect, i.e. clicking faster than the UI can rebuild):
        # only `new_index` was ever bounds-checked below -- `index` itself
        # was used completely unchecked one line later, raising a raw
        # IndexError the instant the list had shrunk since this button's
        # lambda captured its own idx. _delete_recipe_feature and
        # _on_recipe_feature_angle_edited already bounds-checked their own
        # `index` correctly; this was the one place that didn't.
        if not (0 <= index < len(self._recipe_features)):
            return
        new_index = index + delta
        if not (0 <= new_index < len(self._recipe_features)):
            return
        self._recipe_features[index], self._recipe_features[new_index] = \
            self._recipe_features[new_index], self._recipe_features[index]
        self._rebuild_recipe_from_features()

    def _delete_recipe_feature(self, index: int):
        if 0 <= index < len(self._recipe_features):
            feat = self._recipe_features[index]
            _debug_log(f"DELETE index={index} kind={feat.kind} source_id={feat.source_id!r} "
                       f"theta={feat.theta} label={feat.label!r} list_len_before={len(self._recipe_features)} "
                       f"sim_has_run={getattr(self, '_sim_has_run', None)} "
                       f"angle_diagnostic_run={getattr(self, '_sim_angle_diagnostic_run', None)}")
            del self._recipe_features[index]
            self._rebuild_recipe_from_features()
            _debug_log(f"DELETE done -- list_len_after={len(self._recipe_features)} "
                       f"labels={[f.label for f in self._recipe_features]}")

    def _build_import_panel(self) -> QWidget:
        w = QWidget()
        layout = QVBoxLayout(w)
        note = QLabel("Import a .gds file or its KLayout Python script; measurements are computed from the real geometry.")
        note.setWordWrap(True)
        self._themed(note, lambda: f"color: {DIM_COLOR};")
        layout.addWidget(note)

        source_row = QHBoxLayout()
        self.import_source_group = QButtonGroup(w)
        gds_radio = QRadioButton("GDS file (.gds)")
        script_radio = QRadioButton("KLayout script (.py)")
        gds_radio.setChecked(True)
        self.import_source_group.addButton(gds_radio, 0)
        self.import_source_group.addButton(script_radio, 1)
        source_row.addWidget(gds_radio)
        source_row.addWidget(script_radio)
        layout.addLayout(source_row)

        browse_btn = QPushButton("Browse...")
        browse_btn.clicked.connect(self._on_import_browse)
        layout.addWidget(browse_btn)
        self.import_path_label = QLabel("No file selected.")
        self.import_path_label.setWordWrap(True)
        self._themed(self.import_path_label, lambda: f"color: {DIM_COLOR}; font-size: 8pt;")
        layout.addWidget(self.import_path_label)

        # --- GDS-specific controls ---
        self.import_gds_controls = QWidget()
        gds_layout = QVBoxLayout(self.import_gds_controls)
        gds_layout.setContentsMargins(0, 4, 0, 0)
        gds_layout.addWidget(QLabel("Layer:"))
        self.import_layer_list = QListWidget()
        self.import_layer_list.setMaximumHeight(80)
        self.import_layer_list.currentRowChanged.connect(self._on_import_layer_select)
        gds_layout.addWidget(self.import_layer_list)
        gds_layout.addWidget(QLabel("Candidate junction cell:"))
        self.import_cell_list = QListWidget()
        self.import_cell_list.setMaximumHeight(100)
        gds_layout.addWidget(self.import_cell_list)
        layout.addWidget(self.import_gds_controls)

        # --- Script-specific controls ---
        self.import_script_controls = QWidget()
        script_layout = QVBoxLayout(self.import_script_controls)
        script_layout.setContentsMargins(0, 4, 0, 0)
        script_layout.addWidget(QLabel("Generator function:"))
        self.import_function_list = QListWidget()
        self.import_function_list.setMaximumHeight(80)
        self.import_function_list.currentRowChanged.connect(self._on_import_function_select)
        script_layout.addWidget(self.import_function_list)
        self.import_params_form = QFormLayout()
        script_layout.addLayout(self.import_params_form)
        jj_layer_row = QFormLayout()
        self.import_jj_layer_edit = QLineEdit()
        jj_layer_row.addRow("JJ layer (optional):", self.import_jj_layer_edit)
        script_layout.addLayout(jj_layer_row)
        layout.addWidget(self.import_script_controls)
        self.import_script_controls.setVisible(False)
        self.import_source_group.idClicked.connect(self._on_import_source_changed)

        import_btn = QPushButton("Import & Analyze")
        import_btn.clicked.connect(self._run_import_analysis)
        layout.addWidget(import_btn)
        self.import_status_label = QLabel("")
        self.import_status_label.setWordWrap(True)
        self._themed(self.import_status_label, lambda: f"color: {DIM_COLOR}; font-size: 8pt;")
        layout.addWidget(self.import_status_label)

        layout.addStretch()

        self._import_gds_path = None
        self._import_project_key = None  # (source_kind, path) of the last-loaded GDS file/script -- a
                                             # "project" for reset purposes; see _on_import_browse and
                                             # _maybe_reset_for_new_project. A different key means a
                                             # genuinely different PROJECT, distinct from switching to a
                                             # different DESIGN/cell within the same
                                             # file, which resets the wafer-wide resist/electrode/alpha
                                             # fields too -- a same-project, different-cell import does not.
        self._import_script_source = None
        self._import_layer_choices = []
        self._import_cell_choices = []
        self._import_param_entries = {}
        self._electrode_base = None
        self._electrode_base_key = None
        self._imported_junction = None
        self._imported_report = None
        self._display_source = "parametric"
        self._active_design_id = None  # which design_library.py entry (if any) the current
                                          # design was loaded from / last saved to this session --
                                          # lets File > Save Design... overwrite it in place
                                          # instead of always prompting for a brand-new entry
        return w

    def _on_import_source_changed(self, idx):
        self.import_gds_controls.setVisible(idx == 0)
        self.import_script_controls.setVisible(idx == 1)

    def _on_import_electrode_only(self):
        """Imports JUST electrode geometry from a real GDS file -- for
        designing fingers parametrically against a real electrode shape,
        instead of importing (or hand-drawing) a whole junction cell.
        Finds the hole polygon nearest the file's own origin (arbitrary
        but predictable choice for a whole-chip file with many repeats),
        and re-centers it on this canvas's origin so it starts somewhere
        immediately visible/relevant -- drag it into position from there."""
        path, _ = QFileDialog.getOpenFileName(self, "Select a GDS file for its electrode layer",
                                              "", "GDS files (*.gds);;All files (*.*)")
        if not path:
            return
        try:
            base = ji.load_electrode_base(path)
        except Exception as e:
            self.import_status_label.setText(f"Couldn't load electrode geometry: {e}")
            return
        if base is None or not base.holes_world:
            self.import_status_label.setText("No electrode geometry found in that file "
                                              "(checked for 'Pads_v4_Manhattan' or a 'pad'-named cell).")
            return
        nearest = min(base.holes_world, key=lambda poly: poly.centroid.distance(sg.Point(0, 0)))
        centroid = nearest.centroid
        local_pts = [(x - centroid.x, y - centroid.y) for x, y in nearest.exterior.coords]
        self._push_undo_snapshot()
        self.electrode_scene.add(kind="polygon", cx=0.0, cy=0.0, angle_deg=0.0,
                                 points=local_pts, role="electrode")
        self.custom_electrode_check.setChecked(True)
        self.import_status_label.setText(
            f"Imported electrode geometry from {path.split('/')[-1]} -- drag it into position, "
            "then design fingers against it in Finger Geometry.")
        self._create_import_force_fit = True  # new geometry, possibly a very different scale/
                                                  # location than whatever the view was fit to before
        self._update_preview()

    def _switch_active_project_recipe_links(self, old_key, new_key):
        """The actual mechanics behind the recipe-
        link fix/feature (see the long comment on self._batch_recipe_links'
        own declaration for the full user-facing rationale). Called only
        when old_key != new_key (every call site below already guards
        that), i.e. only when the design/recipe-link state currently
        sitting in the four fields this touches genuinely stops applying
        to whatever's now active.

        Stashes the OUTGOING project's own current recipe-link state into
        _batch_recipe_links[old_key] (a no-op the very first time,
        old_key is None then) -- so switching back to that project later
        this session still finds its own recipe rather than losing it --
        then adopts whatever the INCOMING project's own last-known state
        is (empty/None the first time new_key is ever seen). new_key=None
        (a parametric/"Created" design, which has no project-file
        identity to key a carry-over by -- see _current design's own
        callers) always adopts the empty state fresh, exactly matching
        _new_junction's own pre-existing hard-reset behavior for a
        from-scratch design."""
        if old_key is not None:
            self._batch_recipe_links[old_key] = {
                "links": dict(getattr(self, "_current_design_recipe_links", {}) or {}),
                "baselines": dict(getattr(self, "_current_design_recipe_baselines", {}) or {}),
                "link": getattr(self, "_current_design_recipe_link", None),
                "recipe_builder_path": getattr(self, "_recipe_builder_current_path", None),
            }
        carried = (self._batch_recipe_links.get(new_key) if new_key is not None else None) or {
            "links": {}, "baselines": {}, "link": None, "recipe_builder_path": None,
        }
        self._current_design_recipe_links = dict(carried["links"])
        self._current_design_recipe_baselines = dict(carried["baselines"])
        self._current_design_recipe_link = carried["link"]
        self._recipe_builder_current_path = carried["recipe_builder_path"]
        self._active_design_id = None  # a different project's design-library entry (if any) is
                                          # unrelated to whatever was active for the outgoing one
        self._recipe_link_active_project_key = new_key
        self._recipe_builder_refresh_design_link_banner()  # keep the Recipe Builder's own
                                                              # "this design's recipe" banner in sync
                                                              # immediately, not just on next visit

    def _maybe_reset_for_new_project(self, project_key):
        """Blanks the wafer-wide resist/electrode/alpha fields the
        moment a genuinely NEW project (a different GDS file, or a
        different KLayout script file) is picked. The rule is: a new
        design keeps the wafer-wide parameters (bilayer resist and
        electrode thicknesses, and alpha) since those describe the
        physical wafer/run, not the individual design; a new project
        resets everything, including the process parameters. A different
        CELL/design
        picked from the SAME already-loaded file is not a new project
        (project_key is unchanged), so this is a no-op there -- those
        fields are assumed to describe the same physical wafer/run
        across every design imported from one file. project_key is (source_kind, path); the very first
        pick in a session also counts as "new" (self._import_project_key
        starts as None), which is harmless since the fields are already
        at their fresh, blank/default construction-time values then."""
        is_new_project = project_key != getattr(self, "_import_project_key", None)
        self._import_project_key = project_key
        if is_new_project:
            for edit in (getattr(self, "pmma_edit", None), getattr(self, "pmgi_edit", None),
                         getattr(self, "es_height_edit", None), getattr(self, "sim_alpha_override_edit", None)):
                if edit is not None:
                    edit.setText("")
        return is_new_project

    def _on_import_browse(self):
        if self.import_source_group.checkedId() == 0:
            path, _ = QFileDialog.getOpenFileName(self, "Select a GDS file", "", "GDS files (*.gds);;All files (*.*)")
            if not path:
                return
            self._maybe_reset_for_new_project(("gds", path))
            self._import_gds_path = path
            self.import_path_label.setText(path)
            try:
                layers = ji.inspect_gds_layers(path)
            except Exception as e:
                self.import_status_label.setText(f"Couldn't read GDS file: {e}")
                return
            self.import_layer_list.clear()
            self._import_layer_choices = []
            for layer, datatype, count, avg_size in layers:
                self.import_layer_list.addItem(f"layer {layer} ({count} shapes, avg {avg_size:.2f} \u00b5m)")
                self._import_layer_choices.append((layer, datatype))
            self.import_status_label.setText(f"Loaded {len(layers)} layers. Pick the junction layer above.")
            try:
                self._electrode_base = ji.load_electrode_base(path)
                self._electrode_base_key = path
            except Exception as e:
                self.import_status_label.setText(f"Loaded layers, but electrode base failed: {e}")
        else:
            path, _ = QFileDialog.getOpenFileName(self, "Select a KLayout .py script", "", "Python files (*.py);;All files (*.*)")
            if not path:
                return
            try:
                with open(path, "r") as f:
                    source = f.read()
            except Exception as e:
                self.import_status_label.setText(f"Couldn't read file: {e}")
                return
            self._maybe_reset_for_new_project(("script", path))
            self._import_script_source = source
            self.import_path_label.setText(path)
            fns = ji.find_generator_functions(source)
            self.import_function_list.clear()
            for fn_name in fns:
                self.import_function_list.addItem(fn_name)
            for i in reversed(range(self.import_params_form.count())):
                self.import_params_form.removeRow(i)
            self._import_param_entries = {}
            self.import_status_label.setText(f"Found {len(fns)} candidate function(s). Pick one above.")

    def _on_import_layer_select(self, row):
        if row < 0 or self._import_gds_path is None:
            return
        layer, datatype = self._import_layer_choices[row]
        try:
            cells = ji.list_gds_cells_on_layer(self._import_gds_path, layer, datatype)
        except Exception as e:
            self.import_status_label.setText(f"Couldn't list cells: {e}")
            return
        self.import_cell_list.clear()
        self._import_cell_choices = []
        for name, shape_count, bb in cells:
            self.import_cell_list.addItem(f"{name}  ({shape_count} shapes)")
            self._import_cell_choices.append(name)
        self.import_status_label.setText(
            f"{len(cells)} candidate junction cells found on layer {layer}. "
            "Some may be decorative rather than real junctions -- check the preview after importing.")

    def _on_import_function_select(self, row):
        if row < 0 or self._import_script_source is None:
            return
        fn_name = self.import_function_list.item(row).text()
        try:
            sig = ji.get_function_signature(self._import_script_source, fn_name)
        except Exception as e:
            self.import_status_label.setText(f"Couldn't read function signature: {e}")
            return
        for i in reversed(range(self.import_params_form.count())):
            self.import_params_form.removeRow(i)
        self._import_param_entries = {}
        for pname, default_repr in sig:
            if pname in ("layout", "self"):
                continue
            entry = QLineEdit()
            if default_repr is not None:
                entry.setText(default_repr.strip("'\""))
            self.import_params_form.addRow(f"{pname}:", entry)
            self._import_param_entries[pname] = entry

    def _parse_param_value(self, text):
        text = text.strip()
        try:
            return int(text)
        except ValueError:
            pass
        try:
            return float(text)
        except ValueError:
            pass
        return text

    def _run_import_analysis(self):
        try:
            if self.import_source_group.checkedId() == 0:
                if self._import_gds_path is None:
                    raise ValueError("No GDS file selected.")
                layer_row = self.import_layer_list.currentRow()
                cell_row = self.import_cell_list.currentRow()
                if layer_row < 0:
                    raise ValueError("Select a layer first.")
                if cell_row < 0:
                    raise ValueError("Select a candidate cell first.")
                layer, datatype = self._import_layer_choices[layer_row]
                cell_name = self._import_cell_choices[cell_row]
                if self._electrode_base_key != self._import_gds_path:
                    self._electrode_base = ji.load_electrode_base(self._import_gds_path)
                    self._electrode_base_key = self._import_gds_path
                junction = ji.import_gds_cell(self._import_gds_path, layer, datatype, cell_name,
                                              electrode_base=self._electrode_base)
            else:
                if self._import_script_source is None:
                    raise ValueError("No script selected.")
                fn_row = self.import_function_list.currentRow()
                if fn_row < 0:
                    raise ValueError("Select a generator function first.")
                fn_name = self.import_function_list.item(fn_row).text()
                kwargs = {}
                for pname, entry in self._import_param_entries.items():
                    val_text = entry.text()
                    if val_text.strip() == "":
                        raise ValueError(f"Parameter '{pname}' is empty -- fill in a value.")
                    kwargs[pname] = self._parse_param_value(val_text)
                jj_layer_text = self.import_jj_layer_edit.text().strip()
                jj_layer = int(jj_layer_text) if jj_layer_text else None
                junction = ji.run_klayout_script(self._import_script_source, fn_name, kwargs, jj_layer=jj_layer)

            ji.apply_deposit_order(junction, self._deposit_first_index)
            report = ji.compute_measurements(junction)
            self._imported_junction = junction
            self._imported_report = report
            self._junction_scale_base = {}  # a fresh import means fresh stable_ids -- any old
                                               # base_length/width entries would be keyed to shapes
                                               # that no longer exist (or, worse, collide with a
                                               # same-named but different shape in the new design)
            self._role_overrides = {}  # same reasoning -- role overrides from the PREVIOUS import
                                          # shouldn't silently carry over onto a new one's shapes
            self._param_shape_offsets = {}  # a fresh import means the PARAMETRIC junction (if any)
                                               # this design had before is gone too -- same reasoning
            self._param_shape_edits = {}  # Fixes a bug caught while adding the two dicts just
                                             # below: this reset was missing even though
                                             # _param_shape_offsets (its exact sibling) was already
                                             # reset here -- a stale absolute-target edit from the
                                             # PREVIOUS parametric design could otherwise silently
                                             # reapply to a same-indexed shape in a totally different
                                             # design the next time the user switched back to
                                             # "parametric" display source.
            self._param_shape_deletions = set()  # same reasoning -- a deleted patch's stable_id from
                                                    # the previous design must not silently delete an
                                                    # unrelated same-indexed patch in a new one
            self._param_shape_duplicates = {}      # ditto for duplicates
            # See self._batch_recipe_links' own declaration
            # for the full rationale. self._import_project_key is already
            # current by this point (set at file-BROWSE time, by
            # _maybe_reset_for_new_project, strictly before this Import &
            # Analyze click could ever fire) -- a no-op when it's
            # unchanged (same project, a different cell within it --
            # correctly keeps sharing whatever
            # recipe this project already has linked), and a real
            # switch-and-carry-over exactly when it genuinely differs
            # from whatever project the CURRENTLY active recipe-link
            # state actually belongs to.
            new_project_key = getattr(self, "_import_project_key", None)
            if new_project_key != getattr(self, "_recipe_link_active_project_key", None):
                self._switch_active_project_recipe_links(
                    getattr(self, "_recipe_link_active_project_key", None), new_project_key)
            self.import_status_label.setText(
                f"Imported OK -- {len(junction.fingers)} finger(s), {len(junction.other_shapes)} other shape(s).")
            if hasattr(self, "create_import_active_imported_btn"):
                self.create_import_active_imported_btn.setEnabled(True)
            self._set_display_source("imported")
        except Exception as e:
            self.import_status_label.setText(f"Import failed: {e}")

    def _set_display_source(self, source: str):
        # See self._batch_recipe_links' own declaration for
        # the full rationale. Toggling Created<->Imported is, per this
        # method's own existing docstring below, already treated as "a
        # genuinely different design became active" -- so it gets the
        # same recipe-link switch-and-carry-over treatment as a real
        # Import & Analyze click does in _run_import_analysis. A
        # parametric ("Created") design has no project-file identity to
        # key a carry-over by, so it always maps to key None here --
        # always a hard reset, never a carry-over, matching _new_
        # junction's own pre-existing behavior for a from-scratch design.
        # No-ops when the source isn't actually changing (e.g.
        # _run_import_analysis calling this again while already
        # "imported" for a different cell of the same project -- that
        # case is already handled, once, by _run_import_analysis's own
        # identical check against self._import_project_key directly).
        new_project_key = getattr(self, "_import_project_key", None) if source == "imported" else None
        if new_project_key != getattr(self, "_recipe_link_active_project_key", None):
            self._switch_active_project_recipe_links(
                getattr(self, "_recipe_link_active_project_key", None), new_project_key)
        self._display_source = source
        if hasattr(self, "create_import_active_created_btn"):
            self.create_import_active_created_btn.setChecked(source == "parametric")
            self.create_import_active_imported_btn.setChecked(source == "imported")
        # Whatever the view was fit/panned/zoomed to for the PREVIOUS
        # active design has no particular relationship to this one's
        # geometry -- this is the single choke point every "a genuinely
        # different design just became active" path already goes through
        # (a fresh GDS/script import, toggling Created<->Imported, and
        # Design Library load via _apply_params_to_ui), so re-arming the
        # fit flag here covers all of them at once.
        self._create_import_force_fit = True
        self._update_preview()

    # ------------------------------------------------------------------
    # Design library (File > Save Design.../Save Design As New.../Open
    # Design Library..., and the Front Page "Design Library" card) --
    # local persistence so a Created or Imported junction survives
    # closing the app, per the direct feature request: work shouldn't
    # be lost picking up a new code iteration. See design_library.py
    # for the actual storage (fully portable -- no hardcoded paths).
    # ------------------------------------------------------------------

    def _save_current_design(self, design_id: Optional[str] = None):
        """Prompts for a name + notes, then writes whichever design is
        CURRENTLY ACTIVE (self._display_source -- Created or Imported)
        to the library. design_id=None creates a new library entry
        ("Save Design As New..."); passing an existing id overwrites
        that entry in place, keeping its original created_at ("Save
        Design...", reusing self._active_design_id once one design has
        been loaded/saved this session)."""
        default_name, default_notes = "", ""
        if design_id:
            try:
                existing = dl.load_design(design_id)
                default_name, default_notes = existing["name"], existing["notes"]
            except Exception:
                design_id = None  # the entry vanished (e.g. deleted from the library
                                    # dialog since it was loaded) -- fall back to a fresh save
        name, ok = QInputDialog.getText(self, "Save Design", "Design name:",
                                         QLineEdit.Normal, default_name)
        if not ok or not name.strip():
            return
        notes, ok = QInputDialog.getMultiLineText(self, "Save Design", "Notes (optional):", default_notes)
        if not ok:
            notes = default_notes
        try:
            common = dict(
                name=name, notes=notes, deposit_first_index=self._deposit_first_index,
                role_overrides=dict(getattr(self, "_role_overrides", {})),
                junction_scale_base=dict(getattr(self, "_junction_scale_base", {})),
                # Fixes a bug where a parametric
                # design's duplicated fingers went missing entirely
                # after save + reload -- these four dicts are the only
                # place a duplicated/edited/deleted parametric finger/
                # patch/plate lives (re-applied to the freshly-rebuilt
                # junction every _update_preview() call); they were
                # never part of a save before, so now they travel with
                # the design the same way role_overrides does.
                param_shape_offsets=dict(getattr(self, "_param_shape_offsets", {})),
                param_shape_edits=dict(getattr(self, "_param_shape_edits", {})),
                param_shape_deletions=list(getattr(self, "_param_shape_deletions", set())),
                param_shape_duplicates=dict(getattr(self, "_param_shape_duplicates", {})),
                design_id=design_id,
                # Saving a design also saves a LINK to whichever Recipe
                # Builder recipe
                # is currently open (not an embedded copy -- see design_
                # library.save_design's own docstring for why), so this
                # design can jump straight back to it on reload.
                recipe_builder_link=getattr(self, "_recipe_builder_current_path", None),
                # Recipe-tree materialization:
                # every sub-recipe "Generate Recipe" has resolved/written for
                # THIS design (mill passes, deposition passes, the shared
                # Ti-gather/oxidation, the complete-process recipe) -- kind_key
                # -> tree path -- plus the exact baseline steps each one was
                # generated from, so the NEXT "Generate Recipe" on this design
                # can duplicate-and-patch against what actually changed
                # instead of losing track and always creating fresh nodes.
                # See generated_recipe_export.resolve_and_write.
                recipe_builder_links=dict(getattr(self, "_current_design_recipe_links", {}) or {}),
                recipe_builder_baselines=dict(getattr(self, "_current_design_recipe_baselines", {}) or {}),
                # A design loaded back from the design library should have
                # all of the predicted recipe steps already loaded from
                # when the simulation was previously run, without needing
                # to rerun it -- manual edits and hand-typed recipe-tab
                # parameters should be carefully preserved too. Simulate Design's
                # live Predicted Recipe Sequence (including any manual
                # angle/theta override and any hand-inserted freeform
                # step -- see SimulationFeature.manual_override's own
                # docstring), the two-step-workflow gating flags, and the
                # Recipe Parameters panel's per-pass hand-typed thickness/
                # mill-duration text all travel with the design now, the
                # same way the generated recipe/hand-edits already do just
                # above. See design_library.save_design's own docstring
                # for why the lower-level _sim_finger_layers/etc. state is
                # deliberately NOT saved separately.
                sim_recipe_features=list(getattr(self, "_recipe_features", []) or []),
                sim_has_run=bool(getattr(self, "_sim_has_run", False)),
                sim_angle_diagnostic_run=bool(getattr(self, "_sim_angle_diagnostic_run", False)),
                sim_view_mode=getattr(self, "_sim_view_mode", None),
                recipe_panel_thickness_overrides=[
                    {"kind": k[0], "label": k[1], "text": e.text()}
                    for k, e in getattr(self, "recipe_panel_thickness_edits", {}).items()
                    if e.text().strip()
                ],
                recipe_panel_mill_duration_overrides=[
                    {"base": k, "text": e.text()}
                    for k, e in getattr(self, "recipe_panel_mill_duration_edits", {}).items()
                    if e.text().strip()
                ],
            )
            # Whatever recipe is currently
            # generated/adopted for this design -- including any hand-edits
            # (self._recipe_hand_edits) -- is saved right alongside the
            # design geometry, not just the geometry alone.
            if self._recipe_last_steps and self._recipe_last_params is not None:
                common.update(
                    recipe_steps=self._recipe_last_steps,
                    recipe_warnings=self._recipe_last_warnings,
                    recipe_hand_edits=self._recipe_hand_edits,
                    recipe_source_label=self._recipe_last_source_label,
                    recipe_params=self._recipe_last_params,
                )
            # If a user adjusts the
            # settings for a design and saves it, those specific settings
            # should be saved along with it -- a
            # DesignParameters snapshot (self._current_params()) is
            # attached to EVERY save now, Imported designs included, not
            # just Created ones. For an Imported design the geometry
            # half of that snapshot (electrode_shapes, finger angles/
            # lengths) is meaningless and simply ignored on load (the
            # real geometry is junction, saved separately below) -- only
            # the non-geometry half (metal/electrode metal, deposition
            # alpha, resist stack, project name, oxidation time) is
            # restored for it, via _apply_settings_to_ui in
            # _load_design_from_library below. Previously an Imported
            # design's save carried no params at all, so these were never
            # tied to that design -- whatever happened to be live at
            # generate-recipe time was used instead, silently drifting
            # from what the design was actually built/measured with.
            if self._display_source == "imported" and self._imported_junction is not None:
                new_id = dl.save_design(source="imported", junction=self._imported_junction,
                                         params=self._current_params(), **common)
            else:
                new_id = dl.save_design(source="created", params=self._current_params(), **common)
        except Exception as e:
            QMessageBox.warning(self, "Save failed", f"Could not save design: {e}")
            return
        self._active_design_id = new_id
        self._current_design_recipe_link = common.get("recipe_builder_link")
        self._recipe_builder_refresh_design_link_banner()
        QMessageBox.information(self, "Design Saved", f"“{name}” saved to your design library.")

    def _load_design_from_library(self, design_id: str) -> bool:
        """Restores a saved design as the live active design -- an
        Imported one becomes a static ImportedJunction (same as right
        after a fresh GDS import); a Created one is pushed back into
        every Parameters widget via _apply_params_to_ui so it's still
        fully editable, same as if you'd typed it in by hand. Returns
        True on success (callers -- the library dialog -- use this to
        decide whether to close themselves)."""
        try:
            record = dl.load_design(design_id)
        except Exception as e:
            QMessageBox.warning(self, "Load failed", f"Could not load design: {e}")
            return False
        self._push_undo_snapshot()
        self._role_overrides = dict(record["role_overrides"])
        # Format migration: a design saved before the
        # Scale-position fix stored a plain (length_um, width_um) 2-tuple
        # per shape here; _apply_junction_group_scale now expects a
        # richer {"origin":..., "fingers":..., "shapes":...} dict per
        # group. An old-format entry carries no position/origin info to
        # migrate, so it's simply dropped rather than misread as the new
        # shape (which would crash the next Scale on that shape/layer) --
        # the only consequence is that shape's next Scale treats its
        # CURRENT (loaded) size as the new "1.00", the same graceful
        # fallback an never-yet-scaled shape already gets.
        raw_scale_base = dict(record["junction_scale_base"])
        self._junction_scale_base = {k: v for k, v in raw_scale_base.items() if isinstance(v, dict)}
        # Fixes a bug where a parametric design's
        # duplicated/edited/deleted fingers/patches/plates now travel
        # with the save (see design_library.save_design's own comment)
        # -- restored unconditionally here (both branches below), the
        # same way role_overrides/junction_scale_base already are, so a
        # duplicate genuinely survives save+reload instead of silently
        # reverting to the plain (pre-duplicate) design. Also fixes a
        # same-session hazard: loading a DIFFERENT design over a
        # currently-open one used to leave the old design's stale
        # offsets/edits/deletions/duplicates in place (unlike a fresh
        # GDS import, which already resets all four) -- now cleared to
        # this record's own values (empty dicts/set for an older save
        # that predates this fix) every load, not just on import.
        self._param_shape_offsets = dict(record.get("param_shape_offsets") or {})
        self._param_shape_edits = dict(record.get("param_shape_edits") or {})
        self._param_shape_deletions = set(record.get("param_shape_deletions") or set())
        self._param_shape_duplicates = dict(record.get("param_shape_duplicates") or {})
        self._deposit_first_index = record["deposit_first_index"]
        # Best-effort only -- this design's OWN junction/fingers
        # haven't been installed yet at this point (that happens just
        # below), so the panel may still reflect the PREVIOUS design's
        # groups here. It gets authoritatively rebuilt for the real,
        # newly-loaded junction a moment later, inside the _update_preview
        # cascade that _apply_settings_to_ui/_apply_params_to_ui (via
        # _set_display_source) trigger further down this same method --
        # this call just avoids a visibly stale checked-state flash in
        # between.
        self._check_deposit_first_button_for_index(self._deposit_first_index)
        if record["source"] == "imported" and record["junction"] is not None:
            self._imported_junction = record["junction"]
            self._imported_report = None
            self.electrode_scene.shapes = []
            self.electrode_scene.selected_id = None
            if hasattr(self, "create_import_active_imported_btn"):
                self.create_import_active_imported_btn.setEnabled(True)
            self._set_display_source("imported")
            # Restores this Imported
            # design's own non-geometry values (metal/electrode metal,
            # deposition alpha, resist stack, project name, oxidation
            # time) if this save has them -- older saves (from before
            # params was attached to Imported designs too) simply have
            # none, which just leaves whatever's currently live, the same
            # as before this fix. Only that subset is applied -- _apply_settings_to_ui
            # never touches electrode_shapes/finger geometry, which stays
            # exactly what the loaded junction itself already carries.
            if record.get("params") is not None:
                self._apply_settings_to_ui(record["params"])
            if hasattr(self, "import_status_label"):
                self.import_status_label.setText(
                    f"Loaded from Design Library -- {len(record['junction'].fingers)} finger(s), "
                    f"{len(record['junction'].other_shapes)} other shape(s).")
        elif record["params"] is not None:
            self._imported_junction = None
            self._imported_report = None
            self._apply_params_to_ui(record["params"])  # also calls _set_display_source("parametric")
        else:
            QMessageBox.warning(self, "Load failed", "This saved design has no design data in it.")
            return False
        self._active_design_id = design_id

        # A saved recipe (and its hand-
        # edits) comes back with the design, rendered immediately with
        # the same highlights -- not silently dropped, and not requiring
        # the user to regenerate it. Older saves (or a design that never
        # had a recipe generated) simply have none of this, which is the
        # normal/expected empty state.
        self._recipe_last_steps = list(record.get("recipe_steps") or [])
        self._recipe_last_warnings = list(record.get("recipe_warnings") or [])
        self._recipe_hand_edits = list(record.get("recipe_hand_edits") or [])
        self._recipe_last_source_label = record.get("recipe_source_label")
        self._recipe_last_params = record.get("recipe_params")
        if self._recipe_last_steps and self._recipe_last_params is not None:
            self._refresh_recipe_display_after_edit()

        # Restores the LINK to whichever Recipe Builder
        # recipe this design was using (see _save_current_design above),
        # surfaced as a banner in the Recipe Builder view itself rather
        # than force-navigating there on every design load.
        self._current_design_recipe_link = record.get("recipe_builder_link")
        # Recipe-tree materialization: the
        # per-sub-recipe links/baselines this design's own generations have
        # produced so far -- restored so the next "Generate Recipe" click
        # duplicate-and-patches against them rather than starting fresh
        # (see _save_current_design above / generated_recipe_export.resolve_and_write).
        # A design saved before this change simply has neither key, which
        # is the normal empty-dict starting state every design begins with.
        self._current_design_recipe_links = dict(record.get("recipe_builder_links") or {})
        self._current_design_recipe_baselines = dict(record.get("recipe_builder_baselines") or {})
        self._recipe_builder_refresh_design_link_banner()

        # Restored LAST, strictly after the geometry/params
        # cascade above has fully settled -- _apply_params_to_ui/
        # _apply_settings_to_ui (via _set_display_source) both end by
        # triggering _update_preview, which is what sets
        # self._sim_cached_junction and -- via _update_simulate_preview's
        # own fingerprint-mismatch guard -- wipes every _sim_* field for
        # what it (correctly) sees as a brand-new design. Restoring
        # before that point would just get silently wiped a moment
        # later.
        saved_features = list(record.get("sim_recipe_features") or [])
        if saved_features and self._sim_cached_junction is not None:
            self._recipe_features = saved_features
            self._sim_has_run = bool(record.get("sim_has_run", False))
            self._sim_angle_diagnostic_run = bool(record.get("sim_angle_diagnostic_run", False))
            if self._sim_angle_diagnostic_run and hasattr(self, "sim_run_button"):
                self.sim_run_button.setEnabled(True)
            # Re-derives self._sim_finger_layers/_sim_patch_layers/
            # thicknesses/alphas straight from the just-restored features
            # (a documented lossless, order-preserving exact inverse --
            # see this method's own docstring), which in turn cascades
            # through the exact same _refresh_recipe_features /
            # _reapply_manual_angle_overrides / _rebuild_recipe_from_
            # features / _recommit_sim_run machinery a live in-session
            # edit already goes through -- so a manual override or a
            # hand-inserted freeform step survives at the same fidelity a
            # live edit already gets (SimulationFeature.manual_override's
            # own contract), rather than fighting the existing framework
            # with a brand-new, separately-maintained restore path.
            self._sync_sim_layers_from_recipe_features()
            if self._sim_has_run:
                self._recommit_sim_run()  # safety net -- see comment above
            # Recipe Parameters panel's per-pass hand-typed thickness/
            # mill-duration text -- restored AFTER the cascade above,
            # since that's what rebuilds recipe_panel_thickness_edits/
            # recipe_panel_mill_duration_edits (freshly blank) for the
            # restored sequence; setting text before that point would
            # just get discarded the moment the widgets are rebuilt.
            for entry in record.get("recipe_panel_thickness_overrides") or []:
                key = (entry.get("kind"), entry.get("label"))
                edit = getattr(self, "recipe_panel_thickness_edits", {}).get(key)
                if edit is not None:
                    edit.setText(entry.get("text", ""))
            for entry in record.get("recipe_panel_mill_duration_overrides") or []:
                edit = getattr(self, "recipe_panel_mill_duration_edits", {}).get(entry.get("base"))
                if edit is not None:
                    edit.setText(entry.get("text", ""))
            self._set_sim_view_mode(record.get("sim_view_mode") or "optimal")
        return True

    def _open_design_library(self):
        dialog = DesignLibraryDialog(self)
        dialog.exec()

    def _build_deposition_order_panel(self) -> QWidget:
        """A restyle + generalization of the "which finger deposits
        first" control: the plain QRadioButton pair matched nothing else
        in the app -- every other exclusive-
        choice row already uses the QuantumSegmentButton "pill rail"
        used by Simulate Design's VIEW trio, the Recipe tab's mode pair,
        and the Deposition Slideshow's view pair. It also needed to
        generalize beyond a simple two-finger choice: for
        Manhattan-in-series junctions, multiple fingers parallel to each
        other deposit in a given deposition step, so the button
        needs to reflect that -- it can't just be "finger A deposits
        first", it needs to detect the fingers grouped together in the
        same deposition step, and offer a choice of which of those
        groups deposits first.

        The two fixed "Finger A"/"Finger B" QRadioButtons are replaced
        with a DYNAMIC row of QuantumSegmentButtons, one per distinct
        simultaneous-deposit-pass group (ji.enumerate_deposit_order_
        options) -- for a series-chain/layered design where e.g. Finger
        A and Finger D share one axis and never cross each other, this
        collapses onto one button labeled "Finger A + Finger D" rather
        than showing Finger A alone and leaving Finger D's own membership
        invisible. A classic 2-finger design still shows exactly "Finger
        A" / "Finger B", byte-for-byte the same two choices as before
        this generalization -- see enumerate_deposit_order_options' own
        docstring for why.

        The actual buttons live in self._deposit_first_group_buttons and
        are rebuilt by _rebuild_deposit_order_panel (called from
        _update_preview on every refresh, with a cheap signature check
        so the widgets are only actually torn down and recreated when
        the option set itself changes -- not on every keystroke/redraw)
        rather than being built once here, since the number of fingers
        (and therefore the number of groups) can change at any time
        (import, add/delete/promote a finger, design-library load)."""
        w = QWidget()
        layout = QVBoxLayout(w)
        layout.setContentsMargins(0, 0, 0, 0)
        label = QLabel("Which finger(s) deposit first? Informs the linewidth-shrink calc "
                       "(designer) and the self-shadowing check (import). Fingers that share "
                       "one physical pass (parallel, non-crossing -- e.g. a series-chain/layered "
                       "design) are grouped onto a single option automatically.")
        label.setWordWrap(True)
        layout.addWidget(label)

        dynamic_container = QWidget()
        self._deposit_order_dynamic_layout = QVBoxLayout(dynamic_container)
        self._deposit_order_dynamic_layout.setContentsMargins(0, 4, 0, 0)
        layout.addWidget(dynamic_container)

        self._deposit_first_group_buttons = []  # [(QuantumSegmentButton, representative_index, frozenset(members)), ...]
        self._deposit_order_panel_signature = None
        self._rebuild_deposit_order_panel(getattr(self, "_junction", None))

        layout.addStretch()
        return w

    def _rebuild_deposit_order_panel(self, junction):
        """Rebuilds the Deposition Order panel's segmented buttons from
        the CURRENT junction's fingers -- see _build_deposition_order_
        panel's own docstring for the full "why" of this generalization.
        Called from _update_preview() on every refresh (both the
        parametric and imported branches converge before that call, with
        `junction` already carrying every pending edit/deletion/
        duplication for this refresh), so the panel always reflects
        whichever design is currently live.

        A signature check (the sorted tuple of sorted member-index
        tuples) skips the actual widget teardown/recreation -- and the
        visual flicker/focus loss that would come with it -- whenever
        the option set hasn't actually changed since the last call,
        mirroring _rebuild_recipe_panel_dynamic_fields' own "only rebuild
        when the underlying set changes" discipline. When nothing
        changed, only the checked state is refreshed (in case
        self._deposit_first_index itself changed -- e.g. a design-
        library load -- without the finger set changing)."""
        if not hasattr(self, "_deposit_order_dynamic_layout"):
            return
        fingers = junction.fingers if junction is not None else []
        options = ji.enumerate_deposit_order_options(fingers)
        signature = tuple(sorted(tuple(sorted(members)) for _, members in options))
        if signature == getattr(self, "_deposit_order_panel_signature", None):
            self._check_deposit_first_button_for_index(getattr(self, "_deposit_first_index", 0))
            return
        self._deposit_order_panel_signature = signature

        layout = self._deposit_order_dynamic_layout
        while layout.count():
            item = layout.takeAt(0)
            child_widget = item.widget()
            if child_widget is not None:
                child_widget.deleteLater()
            child_layout = item.layout()
            if child_layout is not None:
                while child_layout.count():
                    sub_item = child_layout.takeAt(0)
                    sub_widget = sub_item.widget()
                    if sub_widget is not None:
                        sub_widget.deleteLater()
        self._deposit_first_group_buttons = []

        if not options:
            placeholder = QLabel("No fingers yet -- create or import a design to choose deposition order.")
            placeholder.setWordWrap(True)
            self._themed(placeholder, lambda: f"color: {DIM_COLOR}; font-size: 8pt; font-style: italic;")
            layout.addWidget(placeholder)
            return

        row = QHBoxLayout()
        row.setContentsMargins(0, 0, 0, 0)
        row.setSpacing(0)
        n = len(options)
        for pos, (rep_index, members) in enumerate(options):
            label_text = " + ".join(f"Finger {ji.finger_display_label(i)}" for i in sorted(members))
            position = "solo" if n == 1 else ("left" if pos == 0 else ("right" if pos == n - 1 else "mid"))
            btn = QuantumSegmentButton(label_text, "#e0a875", position)
            btn.clicked.connect(lambda _checked=False, rep=rep_index: self._on_deposit_first_changed(rep))
            row.addWidget(btn)
            self._deposit_first_group_buttons.append((btn, rep_index, frozenset(members)))
        layout.addLayout(row)
        self._check_deposit_first_button_for_index(getattr(self, "_deposit_first_index", 0))

    def _check_deposit_first_button_for_index(self, index):
        """Checks whichever Deposition Order button's group currently
        contains `index`, unchecking the rest -- the generalized
        equivalent of the old two-QRadioButton setChecked pair, now that
        one button can represent more than one finger. Every real finger
        belongs to exactly one option (enumerate_deposit_order_options
        partitions all of them), so this normally finds exactly one
        match; if it finds none (a stale index left over from a
        different, since-changed design, e.g. right after a design-
        library load but before the new junction's own _update_preview
        cascade has run), it falls back to the first option rather than
        leaving the whole row unchecked."""
        buttons = getattr(self, "_deposit_first_group_buttons", [])
        matched = False
        for btn, _rep, members in buttons:
            is_match = index in members
            btn.setChecked(is_match)
            matched = matched or is_match
        if not matched and buttons:
            buttons[0][0].setChecked(True)

    def _build_electrode_designer_panel(self) -> QWidget:
        w = QWidget()
        layout = QVBoxLayout(w)
        note = QLabel("The electrode auto-follows each finger's tip at the standoff gap below. "
                      "Turn on custom placement for full manual control.")
        note.setWordWrap(True)
        self._themed(note, lambda: f"color: {DIM_COLOR};")
        layout.addWidget(note)

        self.electrode_tree = QTreeWidget()
        self.electrode_tree.setHeaderLabels(["Electrode", "Value"])
        self.electrode_tree.setColumnWidth(0, 220)
        inputs_item = QTreeWidgetItem(["Inputs", ""])
        self.electrode_tree.addTopLevelItem(inputs_item)
        self.electrode_gap_edit = self._tree_input_row(inputs_item, "Standoff gap (\u00b5m, negative=overlap)", "-1.5")
        # When not using custom shapes, the standoff gap used to be the
        # only parameter available for the default electrode. Width,
        # length, and angle parameters were added to round this out.
        # These three were
        # already real fields on DesignParameters (horizontal_electrode_
        # w_um/h_um/angle_deg + the vertical_* counterparts for the
        # other finger's electrode) but nothing in the UI ever read or
        # wrote them -- _current_params() silently used their dataclass
        # defaults (4.0um/1.5um/auto) no matter what. Wired below,
        # shared across both fingers' default electrodes the same way
        # the standoff gap above already is. Angle stays optional (like
        # the standoff-following x/y already are) -- blank keeps the
        # existing auto-computed (perpendicular-to-finger) angle;
        # setting a number overrides it.
        self.electrode_width_edit = self._tree_input_row(inputs_item, "Width (\u00b5m)", "4.0")
        self.electrode_length_edit = self._tree_input_row(inputs_item, "Length (\u00b5m)", "1.5")
        self.electrode_angle_edit = self._tree_input_row(inputs_item, "Angle override (deg, blank = auto)", "")
        inputs_item.setExpanded(True)
        layout.addWidget(self.electrode_tree)

        self.custom_electrode_check = QCheckBox("Use custom electrode placement")
        self.custom_electrode_check.setChecked(False)
        self.custom_electrode_check.toggled.connect(self._on_custom_electrode_toggled)
        layout.addWidget(self.custom_electrode_check)

        self.custom_electrode_tools = QWidget()
        tools_layout = QVBoxLayout(self.custom_electrode_tools)
        tools_layout.setContentsMargins(0, 4, 0, 0)
        tools_label = QLabel("Select the Rectangle or Circle tool in the toolbar, then click "
                             "the canvas to place one. Click a shape to select it; drag to move it.")
        tools_label.setWordWrap(True)
        tools_layout.addWidget(tools_label)
        import_electrode_btn = QPushButton("Import Electrode from GDS...")
        import_electrode_btn.clicked.connect(self._on_import_electrode_only)
        tools_layout.addWidget(import_electrode_btn)
        import_note = QLabel("Imports just the electrode geometry near the file's origin.")
        import_note.setWordWrap(True)
        self._themed(import_note, lambda: f"color: {DIM_COLOR}; font-size: 8pt;")
        tools_layout.addWidget(import_note)
        clear_btn = QPushButton("Clear Custom Shapes (revert to auto)")
        clear_btn.clicked.connect(self._clear_custom_electrode_shapes)
        tools_layout.addWidget(clear_btn)
        layout.addWidget(self.custom_electrode_tools)
        self.custom_electrode_tools.setVisible(False)

        layout.addStretch()
        return w

    def _on_custom_electrode_toggled(self, checked):
        self.custom_electrode_tools.setVisible(checked)
        if not checked:
            self._clear_custom_electrode_shapes()

    def _clear_custom_electrode_shapes(self):
        self.electrode_scene.shapes.clear()
        self.electrode_scene.selected_id = None
        self._update_preview()

    def _line_edit_row(self, form: QFormLayout, label: str, default: str) -> QLineEdit:
        """A QLineEdit that live-updates the preview on every keystroke,
        matching the Tk version's <KeyRelease> binding (not editingFinished,
        which would only fire on Enter/blur)."""
        edit = QLineEdit(default)
        edit.textChanged.connect(self._update_preview)
        form.addRow(label, edit)
        return edit

    def _tree_input_row(self, tree_or_item, label: str, default: str) -> QLineEdit:
        """Same QLineEdit + auto-update wiring as _line_edit_row, but
        embedded into a tree item's value column instead of a form row --
        lets an input field live inside the same tree layout as its
        corresponding live measurement, without changing how
        _current_params() reads it (still just a plain QLineEdit)."""
        item = QTreeWidgetItem([label, ""])
        add_fn = tree_or_item.addChild if isinstance(tree_or_item, QTreeWidgetItem) else tree_or_item.addTopLevelItem
        add_fn(item)
        edit = QLineEdit(default)
        edit.setStyleSheet("background: transparent; border: none;")
        edit.textChanged.connect(self._update_preview)
        tree = tree_or_item.treeWidget() if isinstance(tree_or_item, QTreeWidgetItem) else tree_or_item
        tree.setItemWidget(item, 1, edit)
        return edit

    def _tree_output_row(self, parent_item: QTreeWidgetItem, label: str, value: str = "") -> QTreeWidgetItem:
        """A read-only row (a computed/live measurement, not an input) --
        plain text in both columns, no embedded widget."""
        item = QTreeWidgetItem([label, value])
        parent_item.addChild(item)
        return item

    def _build_finger_geometry_panel(self) -> QWidget:
        w = QWidget()
        layout = QVBoxLayout(w)
        self.finger_tree = QTreeWidget()
        self.finger_tree.setHeaderLabels(["Finger Geometry", "Value"])
        self.finger_tree.setColumnWidth(0, 220)

        inputs_item = QTreeWidgetItem(["Inputs", ""])
        self.finger_tree.addTopLevelItem(inputs_item)
        self.h_angle_edit = self._tree_input_row(inputs_item, "Finger A angle (deg)", "0")
        self.v_angle_edit = self._tree_input_row(inputs_item, "Finger B angle (deg)", "270")
        self.h_lw_edit = self._tree_input_row(inputs_item, "Finger A line width (nm)", "200")
        self.v_lw_edit = self._tree_input_row(inputs_item, "Finger B line width (nm)", "220")
        # A passive hint only, sourced from
        # Settings > Resist Stack & Calculator's last-computed linewidth
        # (compute_linewidth_from_alpha) -- never writes into h_lw_edit/
        # v_lw_edit itself. See _refresh_linewidth_hints.
        self.suggested_lw_item = self._tree_output_row(
            inputs_item, "Suggested linewidth (Settings calculator)", "\u2014")
        self.suggested_lw_item.setToolTip(
            1, "From Settings \u2192 Resist Stack & Calculator. A hint only -- not filled in automatically.")
        # This row is named "suggested" but
        # was never actually rendered dim/less-noticeable than a real input --
        # the consolidated Shape Properties card's own suggested-linewidth
        # hint (role=finger) reuses this same _last_suggested_linewidth_nm
        # value and IS rendered dim there, so fixing it here too for
        # consistency.
        self.suggested_lw_item.setForeground(1, QColor(DIM_COLOR))
        self.suggested_lw_item.setForeground(0, QColor(DIM_COLOR))
        self.h_len_edit = self._tree_input_row(inputs_item, "Finger A length (\u00b5m)", "5")
        self.v_len_edit = self._tree_input_row(inputs_item, "Finger B length (\u00b5m)", "5")
        # The junction target overlap was moved here under finger
        # geometry, retiring the separate standalone "Junction Overlap"
        # panel it used to live in. Same widget attribute name
        # (overlap_edit) as the old standalone panel, so _current_params()/
        # _apply_params_to_ui need no changes at all.
        self.overlap_edit = self._tree_input_row(inputs_item, "Target overlap (\u00b5m)", "1.5")
        inputs_item.setExpanded(True)

        layout.addWidget(self.finger_tree)
        overlap_note = QLabel("Target overlap: nominal overlap drawn into the finger crossing. "
                              "Checked against the worst-case shadow-evaporation shrink; warns if insufficient.")
        overlap_note.setWordWrap(True)
        self._themed(overlap_note, lambda: f"color: {DIM_COLOR}; font-size: 8pt;")
        layout.addWidget(overlap_note)
        # NOTE: the perpendicularity warning that used to live here as its
        # own label moved into the new Create / Import "Design Warnings"
        # banner (see _check_design_stage_warnings), and was
        # generalized there to work for real imports too, not just
        # this parametric panel.
        layout.addStretch()
        return w

    def _refresh_linewidth_hints(self):
        """Updates the 'Suggested linewidth' hint row (one finger_tree
        instance, used by Create / Import) from the last value the
        Settings > Resist Stack & Calculator computed. Purely
        informational: never writes into h_lw_edit/v_lw_edit."""
        if not hasattr(self, "suggested_lw_item"):
            return
        lw = getattr(self, "_last_suggested_linewidth_nm", None)
        self.suggested_lw_item.setText(1, f"{lw:.1f} nm" if lw is not None else "—")

